CREATE OR REPLACE PROCEDURE SP_GET_MODEL_PERFORMANCE(
    p_model    IN VARCHAR2,
    p_analysis IN VARCHAR2
) AS
    lv_score NUMBER;
BEGIN
    SELECT test_score
      INTO lv_score
      FROM (
            SELECT test_score
              FROM STACKING.model_score
             WHERE LOWER(model) = LOWER(p_model)
               AND LOWER(name)  = LOWER(p_analysis)
             ORDER BY version DESC, step DESC
           )
     WHERE ROWNUM = 1;

    DBMS_OUTPUT.PUT_LINE('Model: ' || p_model || ' | Score: ' || lv_score);
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Record not found for Model: ' || p_model || ' in Analysis: ' || p_analysis);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

CREATE OR REPLACE PROCEDURE SP_GET_MODEL_PERFORMANCE(
    p_model IN VARCHAR2,
    p_analysis IN VARCHAR2
) AS
    lv_score NUMBER;
BEGIN
    SELECT test_score
    INTO lv_score
    FROM (
      SELECT test_score
      FROM stacking.model_score
      WHERE LOWER(model) = LOWER(p_model)
        AND LOWER(name) = LOWER(p_analysis)
      ORDER BY version DESC, step DESC
    )
    WHERE ROWNUM = 1;

    IF lv_score >= 0.7 THEN
        DBMS_OUTPUT.PUT_LINE('Success: Model ' || p_model || ' passed with score ' || lv_score);
    ELSE
        DBMS_OUTPUT.PUT_LINE('Warning: Model ' || p_model || ' failed to meet the 0.7 threshold.');
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Record not found for Model: ' || p_model || ' in Analysis: ' || p_analysis);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

CREATE OR REPLACE TYPE MODEL_PERFORMANCE_OT AS OBJECT (
    MODEL_NAME   VARCHAR2(200),
    ANALYSIS     VARCHAR2(200),
    MODEL_TYPE   VARCHAR2(100),
    TEST_SCORE   NUMBER,

    MEMBER FUNCTION TO_TEXT RETURN VARCHAR2
);
/
CREATE OR REPLACE TYPE BODY MODEL_PERFORMANCE_OT IS

    MEMBER FUNCTION TO_TEXT RETURN VARCHAR2 IS
    BEGIN
        RETURN 'Model: ' || NVL(SELF.MODEL_NAME, 'N/A') ||
               ' | Analysis: ' || NVL(SELF.ANALYSIS, 'N/A') ||
               ' | Type: ' || NVL(SELF.MODEL_TYPE, 'N/A') ||
               ' | Score: ' || NVL(TO_CHAR(SELF.TEST_SCORE), '0');
    END TO_TEXT;

END;
/
CREATE OR REPLACE PROCEDURE SP_GET_MODEL_PERFORMANCE(
    p_model    VARCHAR2,
    p_analysis VARCHAR2
) AS
    -- Object instance
    l_obj MODEL_PERFORMANCE_OT;

    -- Local variables
    lv_score NUMBER;
    lv_type  VARCHAR2(100);

BEGIN
    /* ---------------------------------------------------------
       Fetch latest model score with problem type
       --------------------------------------------------------- */
    SELECT test_score, type
    INTO   lv_score, lv_type
    FROM (
        SELECT ms.test_score, p.type
        FROM   stacking.model_score ms
        INNER JOIN stacking.problem p
               ON ms.name = p.name
        WHERE  ms.model = p_model
        AND    LOWER(ms.name) = LOWER(p_analysis)
        ORDER BY ms.version DESC, ms.step DESC
    )
    WHERE ROWNUM = 1;

    /* ---------------------------------------------------------
       Build Object
       --------------------------------------------------------- */
    l_obj := MODEL_PERFORMANCE_OT(
        MODEL_NAME => p_model,
        ANALYSIS   => p_analysis,
        MODEL_TYPE => lv_type,
        TEST_SCORE => lv_score
    );

    /* ---------------------------------------------------------
       Output Logic
       --------------------------------------------------------- */
    IF lv_score >= 0.7 THEN
        DBMS_OUTPUT.PUT_LINE(l_obj.TO_TEXT);
    ELSE
        DBMS_OUTPUT.PUT_LINE(
            'Threshold failed for ' || lv_type || ' model: ' || p_model
        );
    END IF;

EXCEPTION
    /* ---------------------------------------------------------
       Exception Handling
       --------------------------------------------------------- */
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE(
            'Record not found for Model: ' || p_model ||
            ' in Analysis: ' || p_analysis
        );

    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Multiple records found for given criteria');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;
/

CREATE OR REPLACE FUNCTION sf_get_customer_total(p_cust_id IN NUMBER)
RETURN VARCHAR2 IS
    lv_total NUMBER;
    lv_dummy NUMBER;
BEGIN
    -- Calculate sum of invoices for the customer
    SELECT SUM(total)
    INTO lv_total
    FROM MUSIC.INVOICE
    WHERE customerid = p_cust_id;

    RETURN NVL(TO_CHAR(lv_total), '0');
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END;
/

CREATE OR REPLACE FUNCTION sf_get_customer_total(p_cust_email IN VARCHAR2) 
RETURN VARCHAR2 IS
    lv_total NUMBER;
    lv_cust_id MUSIC.CUSTOMER.CUSTOMERID%TYPE;
BEGIN
    -- Validate customer existence and fetch their ID
    SELECT customerid INTO lv_cust_id
    FROM MUSIC.CUSTOMER 
    WHERE email = p_cust_email;

    -- Calculate sum of invoices for the customer
    SELECT SUM(total) 
    INTO lv_total
    FROM MUSIC.INVOICE
    WHERE customerid = lv_cust_id;

    RETURN NVL(TO_CHAR(lv_total), '0');
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Error: Customer email not found.';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END;
/

CREATE OR REPLACE TYPE music_customer_total_ot AS OBJECT (
    customer_email VARCHAR2(200),
    total_amount   NUMBER,

    MEMBER FUNCTION to_text RETURN VARCHAR2
);
/
CREATE OR REPLACE TYPE BODY music_customer_total_ot IS

    MEMBER FUNCTION to_text RETURN VARCHAR2 IS
    BEGIN
        RETURN 'Customer Email: ' || NVL(SELF.customer_email, 'N/A')
            || ' | Total Spending: ' || NVL(TO_CHAR(SELF.total_amount), '0');
    END to_text;

END;
/
CREATE OR REPLACE FUNCTION sf_get_customer_total(
    p_cust_email IN VARCHAR2
)
RETURN VARCHAR2 IS

    lv_check NUMBER;
    lv_total NUMBER;

    -- Object variable
    l_obj music_customer_total_ot;

BEGIN
    /* ---------------------------------------------------------
       Validation: Check if customer exists
       --------------------------------------------------------- */
    SELECT COUNT(1)
    INTO lv_check
    FROM MUSIC.CUSTOMER
    WHERE LOWER(email) = LOWER(p_cust_email);

    IF lv_check = 0 THEN
        RETURN 'Error: Customer Email not found';
    END IF;

    /* ---------------------------------------------------------
       Calculate total invoice amount
       --------------------------------------------------------- */
    SELECT NVL(SUM(i.total), 0)
    INTO lv_total
    FROM MUSIC.CUSTOMER c
    LEFT JOIN MUSIC.INVOICE i
        ON c.customerid = i.customerid
    WHERE LOWER(c.email) = LOWER(p_cust_email);

    /* ---------------------------------------------------------
       Build Object
       --------------------------------------------------------- */
    l_obj := music_customer_total_ot(
        customer_email => p_cust_email,
        total_amount   => lv_total
    );

    /* ---------------------------------------------------------
       Return formatted output via object method
       --------------------------------------------------------- */
    RETURN l_obj.to_text;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END;
/

CREATE OR REPLACE PROCEDURE sp_get_current_rate (
    p_from IN VARCHAR2,
    p_to   IN VARCHAR2
) IS
    lv_rate NUMBER;
BEGIN
    -- Retrieve the most recent average rate for the currency pair
    -- Uses an inline view to sort by date descending, then takes the top row
    SELECT AverageRate
    INTO lv_rate
    FROM (
        SELECT AverageRate
        FROM ADVENTUREWORKS.CURRENCYRATE
        WHERE FromCurrencyCode = UPPER(p_from)
          AND ToCurrencyCode = UPPER(p_to)
        ORDER BY CurrencyRateDate DESC
    )
    WHERE ROWNUM = 1;

    -- Output the result
    -- Validation: Check if rate is valid (not null or 0)
    IF lv_rate IS NULL OR lv_rate = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Invalid rate detected');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Current Rate: ' || lv_rate);
    END IF;

EXCEPTION
    -- Handle case where the currency pair does not exist
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Exchange rate not found for ' || UPPER(p_from) || ' to ' || UPPER(p_to));
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

