CREATE OR REPLACE TYPE ot_driver_points_eval AS OBJECT (
    driver_id NUMBER,
    total_points NUMBER,
    race_count NUMBER,
    driver_exists NUMBER
);
/

CREATE OR REPLACE FUNCTION sf_get_driver_points(
    p_driver_id IN NUMBER
) RETURN NUMBER IS
    v_result ot_driver_points_eval := ot_driver_points_eval(NULL, 0, 0, 0);
BEGIN
    -- Validation: Check if driver ID is NULL
    IF p_driver_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Driver ID cannot be NULL');
        RETURN NULL;
    END IF;

    -- Validation: Check if driver ID is positive
    IF p_driver_id <= 0 THEN
        DBMS_OUTPUT.PUT_LINE('Driver ID must be a positive number');
        RETURN NULL;
    END IF;

    -- Validation: Check if driver exists
    SELECT COUNT(*)
    INTO v_result.driver_exists
    FROM F1.DRIVERS_EXT
    WHERE DRIVER_ID = p_driver_id;

    IF v_result.driver_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Driver with ID ' || p_driver_id || ' does not exist');
        RETURN NULL;
    END IF;

    -- Data Retrieval: Calculate total points and race count
    SELECT NVL(SUM(POINTS), 0), COUNT(*)
    INTO v_result.total_points, v_result.race_count
    FROM F1.RESULTS
    WHERE DRIVER_ID = p_driver_id;

    v_result.driver_id := p_driver_id;

    -- Validation: Check for negative points (data integrity)
    IF v_result.total_points < 0 THEN
        DBMS_OUTPUT.PUT_LINE('Invalid data: Negative points detected for driver');
        RETURN NULL;
    END IF;

    -- Validation: Driver exists but has no race participation
    IF v_result.race_count = 0 THEN
        RETURN -1;
    END IF;

    RETURN v_result.total_points;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 0;
    WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Invalid data type for driver ID');
        RETURN NULL;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
        RETURN NULL;
END sf_get_driver_points;
/

