DECLARE
    v_model_name  VARCHAR2(100) := 'Stack';
    v_train_score NUMBER;
    v_test_score  NUMBER;

BEGIN
    -- NULL validation
    IF v_model_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Model name cannot be NULL.');
        RETURN;
    END IF;

    -- This SELECT will raise NO_DATA_FOUND if no rows exist
    SELECT avg_train, avg_test
    INTO   v_train_score, v_test_score
    FROM (
        SELECT AVG(train_score) AS avg_train,
               AVG(test_score)  AS avg_test
        FROM STACKING.MODEL_SCORE
        WHERE model = v_model_name
    )
    WHERE avg_train IS NOT NULL;

    -- Output
    DBMS_OUTPUT.PUT_LINE('=== Model Score Report ===');
    DBMS_OUTPUT.PUT_LINE('Model Name: ' || v_model_name);
    DBMS_OUTPUT.PUT_LINE('Average Train Score: ' || TO_CHAR(v_train_score, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Average Test Score: ' || TO_CHAR(v_test_score, '0.0000'));

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: No data found for model ' || v_model_name);

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END;

