CREATE OR REPLACE PROCEDURE sp_analyze_payment_method(
    p_model_name IN VARCHAR2
) IS
    co_overfitting_threshold CONSTANT NUMBER := 0.1;

    v_train_score NUMBER;
    v_test_score  NUMBER;
    v_importance  NUMBER;
    v_score_diff  NUMBER;
    v_count       NUMBER;

BEGIN
    IF p_model_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Model name cannot be NULL.');
        RETURN;
    END IF;

    SELECT COUNT(*)
    INTO v_count
    FROM STACKING.MODEL_SCORE
    WHERE model = p_model_name;

    IF v_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No scores found for model: ' || p_model_name);
        RETURN;
    END IF;

    SELECT AVG(train_score), AVG(test_score)
    INTO v_train_score, v_test_score
    FROM STACKING.MODEL_SCORE
    WHERE model = p_model_name;

    SELECT avg_imp
    INTO v_importance
    FROM (
      SELECT AVG(importance) AS avg_imp
      FROM STACKING.MODEL_IMPORTANCE
      WHERE model = p_model_name
    )
    WHERE avg_imp IS NOT NULL;

    v_score_diff := ABS(v_train_score - v_test_score);

    DBMS_OUTPUT.PUT_LINE('=== Model Performance Analysis ===');
    DBMS_OUTPUT.PUT_LINE('Model Name: ' || p_model_name);
    DBMS_OUTPUT.PUT_LINE('Average Train Score: ' || TO_CHAR(v_train_score, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Average Test Score: ' || TO_CHAR(v_test_score, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Score Difference: ' || TO_CHAR(v_score_diff, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Average Importance: ' || TO_CHAR(v_importance, '0.0000'));

    IF v_score_diff > co_overfitting_threshold THEN
        DBMS_OUTPUT.PUT_LINE('WARNING: Potential overfitting detected.');
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: No data found for model ' || p_model_name);

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END sp_analyze_payment_method;
/

