CREATE OR REPLACE TYPE ot_model_validation_summary AS OBJECT (
    avg_train_score  NUMBER,
    avg_test_score   NUMBER,
    score_difference NUMBER,
    avg_importance   NUMBER,
    min_required     NUMBER,
    status           VARCHAR2(20)
);
/

CREATE OR REPLACE PROCEDURE sp_analyze_payment_method(
    p_model_name IN VARCHAR2,
    p_min_score  IN NUMBER DEFAULT 0.5
) IS
    co_overfit_limit  CONSTANT NUMBER := 0.1;
    co_min_importance CONSTANT NUMBER := 0.3;

    v_train_score NUMBER;
    v_test_score  NUMBER;
    v_importance  NUMBER;
    v_score_diff  NUMBER;
    v_summary     ot_model_validation_summary;
    v_count       NUMBER;

BEGIN
    IF p_model_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Model name cannot be NULL.');
        RETURN;
    END IF;

    IF p_min_score < 0 OR p_min_score > 1 THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Minimum score must be between 0 and 1.');
        RETURN;
    END IF;

    SELECT COUNT(*)
    INTO v_count
    FROM STACKING.MODEL_SCORE
    WHERE model = p_model_name;

    IF v_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No scores found for model: ' || p_model_name);
        RETURN;
    END IF;

    SELECT AVG(train_score), AVG(test_score)
    INTO v_train_score, v_test_score
    FROM STACKING.MODEL_SCORE
    WHERE model = p_model_name;

    BEGIN
        SELECT avg_imp
        INTO v_importance
        FROM (
            SELECT AVG(importance) AS avg_imp
            FROM STACKING.MODEL_IMPORTANCE
            WHERE model = p_model_name
        )
        WHERE avg_imp IS NOT NULL;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('ERROR: No data found for model ' || p_model_name);
            RETURN;
    END;

    v_importance := NVL(v_importance, 0);
    v_score_diff := ABS(v_train_score - v_test_score);

    IF v_test_score >= p_min_score THEN
        v_summary := ot_model_validation_summary(
            v_train_score,
            v_test_score,
            v_score_diff,
            v_importance,
            p_min_score,
            'PASSED'
        );
    ELSE
        v_summary := ot_model_validation_summary(
            v_train_score,
            v_test_score,
            v_score_diff,
            v_importance,
            p_min_score,
            'FAILED'
        );
    END IF;

    DBMS_OUTPUT.PUT_LINE('=== Comprehensive Model Validation ===');
    DBMS_OUTPUT.PUT_LINE('Model Name: ' || p_model_name);
    DBMS_OUTPUT.PUT_LINE('Validation Status: ' || v_summary.status);
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
    DBMS_OUTPUT.PUT_LINE('Average Train Score: ' || TO_CHAR(v_summary.avg_train_score, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Average Test Score: ' || TO_CHAR(v_summary.avg_test_score, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Score Difference: ' || TO_CHAR(v_summary.score_difference, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Average Importance: ' || TO_CHAR(v_summary.avg_importance, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('Minimum Required Score: ' || TO_CHAR(v_summary.min_required, '0.0000'));
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');

    IF v_summary.avg_test_score < v_summary.min_required THEN
        DBMS_OUTPUT.PUT_LINE('WARNING: Test score below minimum threshold.');
    END IF;

    IF v_summary.score_difference > co_overfit_limit THEN
        DBMS_OUTPUT.PUT_LINE('WARNING: Potential overfitting detected (diff > 0.1).');
    END IF;

    IF v_summary.avg_importance < co_min_importance THEN
        DBMS_OUTPUT.PUT_LINE('INFO: Low model importance. Consider reviewing features.');
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: No data found for model ' || p_model_name);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END sp_analyze_payment_method;
/

