CREATE OR REPLACE PROCEDURE sp_customer_purchase_details (
    p_customer_id IN NUMBER,
    p_from_date   IN DATE,
    p_to_date     IN DATE
) IS
    exp_customer_not_exists EXCEPTION;
    exp_invalid_input       EXCEPTION;
    lv_customer_count       NUMBER;

    TYPE rec_purchase_type IS RECORD (
        customer_name VARCHAR2(200),
        email         VARCHAR2(200),
        invoiceid     NUMBER,
        invoicedate   TIMESTAMP,
        track_name    VARCHAR2(200),
        unitprice     NUMBER
    );

    TYPE t_purchase_type IS TABLE OF rec_purchase_type;
    lv_purchases t_purchase_type;
BEGIN
    IF p_customer_id IS NULL
       OR p_customer_id <= 0
       OR p_from_date IS NULL
       OR p_to_date IS NULL
       OR p_from_date > p_to_date THEN
        RAISE exp_invalid_input;
    END IF;

    SELECT COUNT(*)
    INTO lv_customer_count
    FROM CHINOOK.CUSTOMERS c
    WHERE c.customerid = p_customer_id;

    IF lv_customer_count = 0 THEN
        RAISE exp_customer_not_exists;
    END IF;

    SELECT
        c.firstname || ' ' || c.lastname AS customer_name,
        c.email,
        i.invoiceid,
        i.invoicedate,
        t.name AS track_name,
        ii.unitprice
    BULK COLLECT INTO lv_purchases
    FROM CHINOOK.CUSTOMERS c
    JOIN CHINOOK.INVOICES i
        ON c.customerid = i.customerid
    JOIN CHINOOK.INVOICE_ITEMS ii
        ON i.invoiceid = ii.invoiceid
    JOIN CHINOOK.TRACKS t
        ON ii.trackid = t.trackid
    WHERE c.customerid = p_customer_id
      AND TRUNC(i.invoicedate) BETWEEN TRUNC(p_from_date) AND TRUNC(p_to_date)
    ORDER BY i.invoiceid
    FETCH FIRST 20 ROWS ONLY;

    IF lv_purchases.COUNT = 0 THEN
        RAISE NO_DATA_FOUND;
    END IF;

    FOR lv_index IN 1 .. lv_purchases.COUNT LOOP
        DBMS_OUTPUT.PUT_LINE(
            'CUSTOMER: ' || lv_purchases(lv_index).customer_name ||
            ' | EMAIL: ' || lv_purchases(lv_index).email ||
            ' | INVOICE ID: ' || lv_purchases(lv_index).invoiceid ||
            ' | INVOICE DATE: ' || lv_purchases(lv_index).invoicedate ||
            ' | TRACK: ' || lv_purchases(lv_index).track_name ||
            ' | UNIT PRICE: ' || lv_purchases(lv_index).unitprice
        );
    END LOOP;

EXCEPTION
    WHEN exp_invalid_input THEN
        DBMS_OUTPUT.PUT_LINE('INVALID INPUT VALUES PROVIDED.');
    WHEN exp_customer_not_exists THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID DOES NOT EXIST.');
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('NO PURCHASE DETAILS FOUND FOR GIVEN DATE RANGE.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
