CREATE OR REPLACE PROCEDURE proc_customer_audit(
    p_customer_id IN CHINOOK.CUSTOMERS.CUSTOMERID%TYPE
) IS
    ex_invalid_customer EXCEPTION;
    ex_no_billing       EXCEPTION;

    CURSOR cur_exposure IS
        SELECT i.invoiceid,
               i.total,
               c.country
        FROM chinook.invoices  i
        JOIN chinook.customers c
             ON c.customerid = i.customerid
        WHERE i.customerid = p_customer_id;

    v_invoice_count    NUMBER := 0;
    v_total_exposure   NUMBER := 0;
    v_high_value_count NUMBER := 0;
    v_avg_invoice      NUMBER := 0;
    v_country          chinook.customers.country%TYPE;
BEGIN
    IF p_customer_id IS NULL THEN
        RAISE ex_invalid_customer;
    END IF;

    FOR rec IN cur_exposure LOOP
        v_invoice_count  := v_invoice_count + 1;
        v_total_exposure := v_total_exposure + rec.total;
        v_country        := rec.country;

        IF rec.total > 20 THEN
            v_high_value_count := v_high_value_count + 1;
        END IF;
    END LOOP;

    IF v_invoice_count = 0 THEN
        RAISE ex_no_billing;
    END IF;

    v_avg_invoice := ROUND(v_total_exposure / v_invoice_count, 2);

    DBMS_OUTPUT.PUT_LINE('Country: ' || v_country);
    DBMS_OUTPUT.PUT_LINE('Invoice Count: ' || v_invoice_count);
    DBMS_OUTPUT.PUT_LINE('Total Exposure: ' || v_total_exposure);
    DBMS_OUTPUT.PUT_LINE('Average Invoice Value: ' || v_avg_invoice);

    IF v_high_value_count >= 2 THEN
        DBMS_OUTPUT.PUT_LINE('CREDIT FLAG: HIGH CONCENTRATION RISK');
    ELSIF v_avg_invoice > 15 THEN
        DBMS_OUTPUT.PUT_LINE('CREDIT FLAG: ELEVATED BILLING LEVEL');
    ELSE
        DBMS_OUTPUT.PUT_LINE('CREDIT STATUS: NORMAL');
    END IF;

EXCEPTION
    WHEN ex_invalid_customer THEN
        DBMS_OUTPUT.PUT_LINE('Customer identifier missing');
    WHEN ex_no_billing THEN
        DBMS_OUTPUT.PUT_LINE('No billing records found for customer');
    WHEN OTHERS THEN
       DBMS_OUTPUT.PUT_LINE('Unexpected error occured');
END;
/

