CREATE OR REPLACE PROCEDURE proc_customer_audit (
    p_customer_id IN CHINOOK.CUSTOMERS.CUSTOMERID%TYPE
) IS
    ex_invalid_customer EXCEPTION;
    ex_no_billing       EXCEPTION;
    v_count             NUMBER := 0;

    CURSOR cur_recon IS
        SELECT i.invoiceid,
               SUM(ii.quantity * ii.unitprice) AS calculated_amount,
               i.total AS billed_amount
        FROM chinook.invoices i
        JOIN chinook.invoice_items ii
             ON i.invoiceid = ii.invoiceid
        WHERE i.customerid = p_customer_id
        GROUP BY i.invoiceid, i.total;

    v_mismatch_count NUMBER := 0;
BEGIN
    IF p_customer_id IS NULL THEN
        RAISE ex_invalid_customer;
    END IF;

    FOR rec IN cur_recon LOOP
        v_count := v_count + 1;
        IF rec.calculated_amount <> rec.billed_amount THEN
            DBMS_OUTPUT.PUT_LINE(
                'RECON MISMATCH | Invoice ' || rec.invoiceid ||
                ' | Calculated ' || rec.calculated_amount ||
                ' | Billed ' || rec.billed_amount
            );
            v_mismatch_count := v_mismatch_count + 1;
        END IF;
    END LOOP;

    IF v_count = 0 THEN
        RAISE ex_no_billing;
    END IF;

EXCEPTION
    WHEN ex_invalid_customer THEN
        DBMS_OUTPUT.PUT_LINE('Customer identifier missing');
    WHEN ex_no_billing THEN
        DBMS_OUTPUT.PUT_LINE('No billing records found for customer');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occured');
END;
/

