CREATE OR REPLACE PROCEDURE check_stock_availability (
    p_product_id   IN NUMBER,
    p_location_id in number,
    p_required_qty IN NUMBER
) IS
    v_available_qty NUMBER;
BEGIN
    SELECT NVL(SUM(i.qty), 0)
    INTO   v_available_qty
    FROM   oracle_sql.inventory i
    WHERE  i.product_id = p_product_id
    and   i.location_id = p_location_id;

    IF v_available_qty >= p_required_qty THEN
        DBMS_OUTPUT.PUT_LINE('STOCK AVAILABLE');
    ELSE
        DBMS_OUTPUT.PUT_LINE('INSUFFICIENT STOCK');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error while checking stock:');
END check_stock_availability;
/

CREATE OR REPLACE PROCEDURE check_stock_availability (
    p_product_id   IN NUMBER,
    p_warehouse    IN NUMBER,
    p_required_qty IN NUMBER
) IS
    v_available_qty NUMBER;
BEGIN
    SELECT NVL(SUM(i.qty), 0)
    INTO   v_available_qty
    FROM   oracle_sql.inventory i
    JOIN   oracle_sql.locations l
           ON i.location_id = l.id
    WHERE  i.product_id = p_product_id
    AND    l.warehouse  = p_warehouse;

    IF v_available_qty >= p_required_qty THEN
        DBMS_OUTPUT.PUT_LINE('STOCK AVAILABLE');
        DBMS_OUTPUT.PUT_LINE('Available Qty: ' || v_available_qty);
    ELSE
        DBMS_OUTPUT.PUT_LINE('INSUFFICIENT STOCK');
        DBMS_OUTPUT.PUT_LINE('Available Qty: ' || v_available_qty);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error while checking stock: ' );
END check_stock_availability;
/

CREATE OR REPLACE PROCEDURE check_stock_availability (
    p_product_id   IN NUMBER,
    p_warehouse    IN NUMBER,
    p_required_qty IN NUMBER
) IS
    v_available_qty NUMBER;
    v_shortfall_qty NUMBER;

    e_invalid_qty  EXCEPTION;
    e_out_of_stock EXCEPTION;
    e_low_stock    EXCEPTION;
BEGIN
    IF p_required_qty <= 0 THEN
        RAISE e_invalid_qty;
    END IF;

  SELECT NVL(SUM(i.qty), 0)
    INTO   v_available_qty
    FROM   oracle_sql.inventory i
    JOIN   oracle_sql.locations l
           ON i.location_id = l.id
    WHERE  i.product_id = p_product_id
    AND    l.warehouse  = p_warehouse;

    IF v_available_qty = 0 THEN
        RAISE e_out_of_stock;
    ELSIF v_available_qty < p_required_qty THEN
        v_shortfall_qty := p_required_qty - v_available_qty;
        RAISE e_low_stock;
    ELSE
        DBMS_OUTPUT.PUT_LINE('SUFFICIENT STOCK');
        DBMS_OUTPUT.PUT_LINE('Available Qty: ' || v_available_qty);
    END IF;

EXCEPTION
    WHEN e_invalid_qty THEN
        DBMS_OUTPUT.PUT_LINE('Invalid required quantity. Must be greater than zero.');
    WHEN e_out_of_stock THEN
        DBMS_OUTPUT.PUT_LINE('OUT OF STOCK');
        DBMS_OUTPUT.PUT_LINE('Available Qty: 0');
    WHEN e_low_stock THEN
        DBMS_OUTPUT.PUT_LINE('LOW STOCK');
        DBMS_OUTPUT.PUT_LINE('Available Qty: ' || v_available_qty);
        DBMS_OUTPUT.PUT_LINE('Shortfall Qty: ' || v_shortfall_qty);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred: ');
END check_stock_availability;
/

