CREATE OR REPLACE FUNCTION sf_compare_player_weight
(
    p_player_id VARCHAR2
)
RETURN VARCHAR2
IS
    v_weight  NUMBER;
    v_country VARCHAR2(100);
    v_avg     NUMBER;
    v_result  VARCHAR2(50);

BEGIN

    IF p_player_id IS NULL THEN
        RETURN 'Player ID NULL not found';
    END IF;

    SELECT weight, birth_country
    INTO v_weight, v_country
    FROM baseball.player
    WHERE player_id = p_player_id;

    SELECT AVG(weight)
    INTO v_avg
    FROM baseball.player
    WHERE birth_country = v_country;

    IF v_weight > v_avg THEN
        v_result := 'Above Average';
    ELSIF v_weight < v_avg THEN
        v_result := 'Below Average';
    ELSE
        v_result := 'Equal to Average';
    END IF;

    RETURN 'Player ID : ' || p_player_id || CHR(10) ||
           'Player Weight : ' || v_weight || CHR(10) ||
           'Country Average : ' || ROUND(v_avg,2) || CHR(10) ||
           'Result : ' || v_result;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'Player ID : ' || p_player_id || ' Not Found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_compare_player_weight;
/

DECLARE
    v_state_code   VARCHAR2(10) := 'CA';
    v_record_count NUMBER := 0;
    CURSOR cur_legislators IS
    SELECT DISTINCT
        l.full_name,
        lt.party,
        lt.term_type
    FROM
             city_legislation.legislators l
        INNER JOIN city_legislation.legislators_terms lt ON l.id_bioguide = lt.id_bioguide
    WHERE
            lt.state = v_state_code
        AND CAST(lt.term_end AS DATE) BETWEEN TRUNC(SYSDATE) - INTERVAL '2' YEAR AND TRUNC(SYSDATE)
        AND lt.class IS NOT NULL
    ORDER BY
        l.full_name;

BEGIN
    IF v_state_code IS NULL THEN
        dbms_output.put_line('ERROR: State code cannot be NULL.');
        RETURN;
    END IF;
    dbms_output.put_line('=== Legislators for State: '
                         || v_state_code
                         || ' ===');
    dbms_output.put_line('--------------------------------------------------');
    FOR rec IN cur_legislators LOOP
        v_record_count := v_record_count + 1;
        dbms_output.put_line('Name: ' || rec.full_name);
        dbms_output.put_line('Party: ' || rec.party);
        dbms_output.put_line('Term Type: ' || rec.term_type);
        dbms_output.put_line('--------------------------------------------------');
    END LOOP;

    IF v_record_count = 0 THEN
        dbms_output.put_line('No legislators found for state: ' || v_state_code);
    END IF;

    dbms_output.put_line('Total Records: ' || v_record_count);

EXCEPTION
    WHEN OTHERS THEN
        dbms_output.put_line('Unexpected error occurred.');
END;
/

