CREATE OR REPLACE PROCEDURE sp_get_legislators_by_state(
    p_state_code IN VARCHAR2
) IS
    v_record_count NUMBER := 0;

    CURSOR cur_legislators IS
    SELECT DISTINCT
        l.full_name,
        lt.party,
        lt.term_type,
        lt.phone,
        lt.office
    FROM
             city_legislation.legislators l
        INNER JOIN city_legislation.legislators_terms lt ON l.id_bioguide = lt.id_bioguide
    WHERE
            lt.state = p_state_code
        AND lt.term_end >= ADD_MONTHS(TRUNC(SYSDATE), -24)
        AND lt.term_end <= SYSDATE
        AND lt.class IS NOT NULL
    ORDER BY
        l.full_name;

BEGIN
    IF p_state_code IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: State code cannot be NULL.');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('=== Legislators for State: ' || p_state_code || ' ===');
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');

    FOR rec IN cur_legislators LOOP
        v_record_count := v_record_count + 1;
        DBMS_OUTPUT.PUT_LINE('Name: ' || rec.full_name);
        DBMS_OUTPUT.PUT_LINE('Party: ' || rec.party);
        DBMS_OUTPUT.PUT_LINE('Term Type: ' || rec.term_type);
        DBMS_OUTPUT.PUT_LINE('Phone: ' || rec.phone);
        DBMS_OUTPUT.PUT_LINE('Office: ' || rec.office);
        DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
    END LOOP;

    IF v_record_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No legislators found for state: ' || p_state_code);
    END IF;

    DBMS_OUTPUT.PUT_LINE('Total Records: ' || v_record_count);

