CREATE OR REPLACE PROCEDURE sp_get_legislators_by_state(
    p_state_code IN VARCHAR2,
    p_party      IN VARCHAR2 DEFAULT NULL
) IS
    v_record_count NUMBER := 0;
    v_sen_count    NUMBER := 0;
    v_rep_count    NUMBER := 0;

    CURSOR cur_legislators IS
    SELECT DISTINCT
        l.full_name,
        l.gender,
        lt.party,
        lt.term_type,
        lt.phone,
        lt.office
    FROM
        city_legislation.legislators l
        INNER JOIN city_legislation.legislators_terms lt
            ON l.id_bioguide = lt.id_bioguide
    WHERE
        lt.state = p_state_code
        AND (p_party IS NULL OR lt.party = p_party)
        AND lt.term_end >= ADD_MONTHS(TRUNC(SYSDATE), -24)
        AND lt.class IS NOT NULL
    ORDER BY
        l.full_name;

BEGIN
    IF p_state_code IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: State code cannot be NULL.');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('=== Legislators Report ===');
    DBMS_OUTPUT.PUT_LINE('State: ' || p_state_code);
    IF p_party IS NOT NULL THEN
        DBMS_OUTPUT.PUT_LINE('Party Filter: ' || p_party);
    END IF;
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');

    FOR rec IN cur_legislators LOOP
        v_record_count := v_record_count + 1;

        IF rec.term_type = 'sen' THEN
            v_sen_count := v_sen_count + 1;
        ELSIF rec.term_type = 'rep' THEN
            v_rep_count := v_rep_count + 1;
        END IF;

        DBMS_OUTPUT.PUT_LINE('Name: ' || rec.full_name);
        DBMS_OUTPUT.PUT_LINE('Gender: ' || rec.gender);
        DBMS_OUTPUT.PUT_LINE('Party: ' || rec.party);
        DBMS_OUTPUT.PUT_LINE('Term Type: ' || rec.term_type);
        DBMS_OUTPUT.PUT_LINE('Phone: ' || rec.phone);
        DBMS_OUTPUT.PUT_LINE('Office: ' || rec.office);
        DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
    END LOOP;

    IF v_record_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No legislators found for the specified criteria.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('=== Summary ===');
    DBMS_OUTPUT.PUT_LINE('Total Legislators: ' || v_record_count);
    DBMS_OUTPUT.PUT_LINE('Senators: ' || v_sen_count);
    DBMS_OUTPUT.PUT_LINE('Representatives: ' || v_rep_count);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END sp_get_legislators_by_state;
/

