CREATE OR REPLACE PROCEDURE sp_report_team_appearances(
  p_team_id IN BASEBALL.APPEARANCES.team_id%TYPE,
  p_year    IN BASEBALL.APPEARANCES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR cur_team_app IS
    SELECT player_id,
           SUM(g_all) AS total_games,
           SUM(gs)    AS total_starts
      FROM BASEBALL.APPEARANCES
     WHERE team_id = p_team_id
       AND year = p_year
     GROUP BY player_id
     ORDER BY SUM(g_all) DESC, player_id;

  lv_any_rows NUMBER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('TEAM=' || p_team_id || ' YEAR=' || TO_CHAR(p_year));
  DBMS_OUTPUT.PUT_LINE(RPAD('PLAYER_ID', 16) || RPAD('TOTAL_G', 10) || 'TOTAL_GS');

  FOR rec_app IN cur_team_app LOOP
    EXIT WHEN lv_any_rows >= co_report_limit;
    lv_any_rows := lv_any_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec_app.player_id, 16) ||
      RPAD(TO_CHAR(rec_app.total_games), 10) ||
      TO_CHAR(rec_app.total_starts)
    );
  END LOOP;

  IF lv_any_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No appearances found for given team and year');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned unexpectedly');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_report_team_appearances;
/

CREATE OR REPLACE PROCEDURE sp_get_team_appearance_leader(
  p_team_id            IN  BASEBALL.APPEARANCES.team_id%TYPE,
  p_year               IN  BASEBALL.APPEARANCES.year%TYPE,
  out_leader_player_id OUT BASEBALL.APPEARANCES.player_id%TYPE,
  out_leader_games     OUT NUMBER,
  out_leader_pct       OUT NUMBER
) IS
  CURSOR cur_player_totals IS
    SELECT player_id,
           SUM(g_all) AS total_games
      FROM BASEBALL.APPEARANCES
     WHERE team_id = p_team_id
       AND year = p_year
     GROUP BY player_id
     ORDER BY SUM(g_all) DESC, player_id;

  lv_team_total_games NUMBER := 0;
  lv_found_rows       NUMBER := 0;
BEGIN
  out_leader_player_id := NULL;
  out_leader_games := NULL;
  out_leader_pct := NULL;

  FOR rec_tot IN cur_player_totals LOOP
    lv_found_rows := lv_found_rows + 1;
    lv_team_total_games := lv_team_total_games + rec_tot.total_games;

    IF lv_found_rows = 1 THEN
      out_leader_player_id := rec_tot.player_id;
      out_leader_games := rec_tot.total_games;
    END IF;
  END LOOP;

  IF lv_found_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  IF lv_team_total_games = 0 THEN
    out_leader_pct := 0;
  ELSE
    out_leader_pct := ROUND((out_leader_games / lv_team_total_games) * 100, 2);
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'LEADER=' || out_leader_player_id ||
    ' GAMES=' || TO_CHAR(out_leader_games) ||
    ' PCT=' || TO_CHAR(out_leader_pct)
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No appearance data to compute leader');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned unexpectedly');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_get_team_appearance_leader;
/

