CREATE OR REPLACE PACKAGE pkg_payroll_risk IS
  PROCEDURE sp_print_risks(
    p_team_id    IN BASEBALL.SALARY.team_id%TYPE,
    p_year       IN BASEBALL.SALARY.year%TYPE,
    p_min_games  IN NUMBER,
    p_min_salary IN NUMBER
  );
END pkg_payroll_risk;
/

CREATE OR REPLACE PACKAGE BODY pkg_payroll_risk IS
  PROCEDURE sp_print_risks(
    p_team_id    IN BASEBALL.SALARY.team_id%TYPE,
    p_year       IN BASEBALL.SALARY.year%TYPE,
    p_min_games  IN NUMBER,
    p_min_salary IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR cur_salary IS
      SELECT player_id,
             salary
        FROM BASEBALL.SALARY
       WHERE team_id = p_team_id
         AND year = p_year
         AND salary >= p_min_salary
       ORDER BY salary DESC, player_id;

    lv_total_games NUMBER;
    lv_printed     NUMBER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('TEAM=' || p_team_id || ' YEAR=' || TO_CHAR(p_year));
    DBMS_OUTPUT.PUT_LINE('Thresholds: min_salary=' || TO_CHAR(p_min_salary) || ' min_games=' || TO_CHAR(p_min_games));
    DBMS_OUTPUT.PUT_LINE(RPAD('PLAYER_ID', 16) || RPAD('SALARY', 14) || 'TOTAL_G');

    FOR rec_sal IN cur_salary LOOP
      EXIT WHEN lv_printed >= co_report_limit;

      lv_total_games := 0;

      BEGIN
        SELECT SUM(a.g_all)
          INTO lv_total_games
          FROM BASEBALL.APPEARANCES a
         WHERE a.team_id = p_team_id
           AND a.year = p_year
           AND a.player_id = rec_sal.player_id;

        IF lv_total_games IS NULL THEN
          lv_total_games := 0;
        END IF;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_total_games := 0;
        WHEN TOO_MANY_ROWS THEN
          DBMS_OUTPUT.PUT_LINE('Multiple rows returned unexpectedly');
          lv_total_games := 0;
        WHEN OTHERS THEN
          DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
          lv_total_games := 0;
      END;

      IF lv_total_games < p_min_games THEN
        lv_printed := lv_printed + 1;
        DBMS_OUTPUT.PUT_LINE(
          RPAD(rec_sal.player_id, 16) ||
          RPAD(TO_CHAR(rec_sal.salary), 14) ||
          TO_CHAR(lv_total_games)
        );
      END IF;
    END LOOP;

    IF lv_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No payroll risk records found');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned unexpectedly');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
  END sp_print_risks;
END pkg_payroll_risk;
/

CREATE OR REPLACE PROCEDURE sp_batsman_performance (
    p_player_id IN NUMBER,
    p_match_id  IN NUMBER
)
IS
    lv_total_runs   NUMBER;
    lv_ball_count   NUMBER;
    lv_performance  VARCHAR2(20);

    exp_player_not_played EXCEPTION;
BEGIN
    SELECT COUNT(*)
    INTO   lv_ball_count
