CREATE OR REPLACE PROCEDURE sp_get_player_batting_details (
    p_player_id IN baseball.player.player_id%TYPE,
    p_year      IN baseball.batting.year%TYPE
)
IS
    -- User-defined exceptions
    e_invalid_player   EXCEPTION;
    e_no_batting_data  EXCEPTION;

    CURSOR cur_batting IS
        SELECT b.g,
               b.h,
               b.league_id,
               t.name AS team_name
        FROM baseball.batting b
        LEFT JOIN baseball.team t
               ON b.team_id = t.team_id
              AND b.year = t.year
        WHERE b.player_id = p_player_id
          AND b.year = p_year
          order by b.g;

    v_player_count NUMBER;
    v_found        BOOLEAN := FALSE;
BEGIN
    -- Validate player existence
    SELECT COUNT(*)
    INTO v_player_count
    FROM baseball.player
    WHERE player_id = p_player_id;

    IF v_player_count = 0 THEN
        RAISE e_invalid_player;
    END IF;

    -- Fetch batting data with team details
    FOR rec IN cur_batting LOOP
        v_found := TRUE;
        DBMS_OUTPUT.PUT_LINE(
            'Games: ' || rec.g ||
            ', Hits: ' || rec.h ||
            ', League: ' || rec.league_id ||
            ', Team: ' || rec.team_name
        );
    END LOOP;

    IF NOT v_found THEN
        RAISE e_no_batting_data;
    END IF;

EXCEPTION
    WHEN e_invalid_player THEN
        DBMS_OUTPUT.PUT_LINE('Player does not exist');

    WHEN e_no_batting_data THEN
        DBMS_OUTPUT.PUT_LINE('No batting records found for this player in the given year');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_get_player_batting_details;
/

CREATE OR REPLACE PROCEDURE sp_get_player_season_summary (
    p_player_id IN baseball.player.player_id%TYPE,
    p_year      IN baseball.batting.year%TYPE
)
IS
    e_player_id_null   EXCEPTION;
    e_year_null        EXCEPTION;
    e_invalid_year     EXCEPTION;
    e_invalid_player   EXCEPTION;
    e_no_batting_data  EXCEPTION;
    e_zero_ab          EXCEPTION;

    CURSOR cur_batting IS
        SELECT b.g,
               b.h,
               b.ab,
               b.league_id,
               t.name AS team_name
        FROM baseball.batting b
        LEFT JOIN baseball.team t
               ON b.team_id = t.team_id
              AND b.year = t.year
        WHERE b.player_id = p_player_id
          AND b.year = p_year
        ORDER BY b.g;

    v_player_count NUMBER;
    v_found        BOOLEAN := FALSE;
    v_total_games  NUMBER := 0;
    v_total_hits   NUMBER := 0;
    v_total_ab     NUMBER := 0;
    v_batting_avg  NUMBER;

BEGIN
    IF p_player_id IS NULL THEN
        RAISE e_player_id_null;
    ELSIF p_year IS NULL THEN
        RAISE e_year_null;
    ELSIF p_year < 1800 OR p_year > EXTRACT(YEAR FROM SYSDATE) THEN
        RAISE e_invalid_year;
    END IF;

    SELECT COUNT(*)
    INTO v_player_count
    FROM baseball.player
    WHERE player_id = p_player_id;

    IF v_player_count = 0 THEN
        RAISE e_invalid_player;
    END IF;

    FOR rec IN cur_batting LOOP
        v_found := TRUE;

        v_total_games := v_total_games + rec.g;
        v_total_hits  := v_total_hits + rec.h;
        v_total_ab    := v_total_ab + rec.ab;

        DBMS_OUTPUT.PUT_LINE(
            'Games: ' || rec.g ||
            ', Hits: ' || rec.h ||
            ', League: ' || rec.league_id ||
            ', Team: ' || rec.team_name
        );
    END LOOP;

    IF NOT v_found THEN
        RAISE e_no_batting_data;
    END IF;

    IF v_total_ab > 0 THEN
        v_batting_avg := v_total_hits / v_total_ab;
    ELSE
        RAISE e_zero_ab;
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- Season Summary ---');
    DBMS_OUTPUT.PUT_LINE('Player ID: ' || p_player_id);
    DBMS_OUTPUT.PUT_LINE('Season Year: ' || p_year);
    DBMS_OUTPUT.PUT_LINE('Total Games Played: ' || v_total_games);
    DBMS_OUTPUT.PUT_LINE('Total Hits: ' || v_total_hits);
    DBMS_OUTPUT.PUT_LINE('Batting Average: ' || ROUND(v_batting_avg, 3));

EXCEPTION
    WHEN e_player_id_null THEN
        DBMS_OUTPUT.PUT_LINE('Player ID cannot be NULL');

    WHEN e_year_null THEN
        DBMS_OUTPUT.PUT_LINE('Year cannot be NULL');

    WHEN e_invalid_year THEN
        DBMS_OUTPUT.PUT_LINE('Invalid year provided');

    WHEN e_invalid_player THEN
        DBMS_OUTPUT.PUT_LINE('Player does not exist');

    WHEN e_no_batting_data THEN
        DBMS_OUTPUT.PUT_LINE('No batting records found for this player in the given year');

    WHEN e_zero_ab THEN
        DBMS_OUTPUT.PUT_LINE('Batting average can be calculated only when at-bats are greater than 0');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_get_player_season_summary;
/

DECLARE
    lv_step        NUMBER := 3;
    lv_version     NUMBER := 1;
    lv_model       VARCHAR2(8000) := 'XGBOOST';
    lv_count       NUMBER;
    lv_train_score NUMBER;
    lv_test_score  NUMBER;
    exp_no_value_found EXCEPTION;
    exp_no_model       EXCEPTION;
BEGIN
    IF lv_step IS NULL OR lv_version IS NULL OR lv_model IS NULL THEN
        RAISE exp_no_value_found;
    END IF;

    SELECT COUNT(*)
    INTO   lv_count
    FROM   STACKING.MODEL_SCORE
    WHERE  step = lv_step
    AND    version = lv_version
    AND    model = lv_model;

    IF lv_count = 0 THEN
        RAISE exp_no_model;
    END IF;

    SELECT MAX(train_score),
           MAX(test_score)
    INTO   lv_train_score,
           lv_test_score
    FROM   STACKING.MODEL_SCORE
    WHERE  step = lv_step
    AND    version = lv_version
    AND    model = lv_model;

    DBMS_OUTPUT.PUT_LINE('Model       : ' || lv_model);
    DBMS_OUTPUT.PUT_LINE('Train Score : ' || lv_train_score);
    DBMS_OUTPUT.PUT_LINE('Test  Score : ' || lv_test_score);

EXCEPTION
    WHEN exp_no_value_found THEN
        DBMS_OUTPUT.PUT_LINE('STEP, VERSION and MODEL must be provided');
    WHEN exp_no_model THEN
        DBMS_OUTPUT.PUT_LINE('Model not exist in the table.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

