CREATE OR REPLACE PROCEDURE proc_get_active_products (
    p_category_name IN ADVENTUREWORKS.PRODUCTCATEGORY.NAME%TYPE
) IS
    l_row_count   NUMBER := 0;
    l_classification VARCHAR2(20);

    e_no_active_products EXCEPTION;

    CURSOR cur_products IS
        SELECT
            p.PRODUCTID,
            p.NAME AS product_name,
            pc.NAME AS category_name,
            psc.NAME AS subcategory_name,
            p.LISTPRICE,
            pc.PRODUCTCATEGORYID
        FROM ADVENTUREWORKS.PRODUCT p
        JOIN ADVENTUREWORKS.PRODUCTSUBCATEGORY psc
            ON p.PRODUCTSUBCATEGORYID = psc.PRODUCTSUBCATEGORYID
        JOIN ADVENTUREWORKS.PRODUCTCATEGORY pc
            ON psc.PRODUCTCATEGORYID = pc.PRODUCTCATEGORYID
        WHERE UPPER(pc.NAME) = UPPER(p_category_name)
          AND p.SELLSTARTDATE IS NOT NULL
          AND p.SELLENDDATE IS NULL
          AND p.DISCONTINUEDDATE IS NULL;

    l_avg_rating NUMBER;
    l_review_cnt NUMBER;

BEGIN
    FOR rec IN cur_products LOOP
        l_row_count := l_row_count + 1;

        SELECT
            NVL(AVG(r.RATING), 0),
            COUNT(*)
        INTO
            l_avg_rating,
            l_review_cnt
        FROM ADVENTUREWORKS.PRODUCTREVIEW r
        WHERE r.PRODUCTID = rec.PRODUCTID;

        l_classification := CASE
            WHEN l_avg_rating < 3 THEN 'Low Rated'
            WHEN l_avg_rating >= 3 AND l_avg_rating <= 4 THEN 'MEDIUM RATED'
            ELSE 'HIGH RATED'
        END;

        DBMS_OUTPUT.PUT_LINE(
            'Product ID: ' || rec.PRODUCTID ||
            ' | Name: ' || rec.product_name ||
            ' | Category: ' || rec.category_name ||
            ' | Subcategory: ' || rec.subcategory_name ||
            ' | Price: ' || rec.LISTPRICE ||
            ' | Avg Rating: ' || ROUND(l_avg_rating, 2) ||
            ' | Reviews: ' || l_review_cnt ||
            ' | Product classification: ' || l_classification
        );
    END LOOP;

    IF l_row_count = 0 THEN
        RAISE e_no_active_products;
    END IF;

EXCEPTION
    WHEN e_no_active_products THEN
        DBMS_OUTPUT.PUT_LINE('No active products available for this category.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error');
        RAISE;
END;
/

