CREATE OR REPLACE PROCEDURE SP_GET_WWE_EVENT_SUMMARY_2(
    p_promotion_id IN wwe.cards.promotion_id%TYPE
)
IS
    v_data_found BOOLEAN := FALSE;

    CURSOR c_promo_events IS
        SELECT
            e.id AS event_id,
            e.name AS event_name,
            COUNT(c.id) AS total_cards,
            MAX(c.table_id) KEEP (DENSE_RANK FIRST ORDER BY c.id) AS sample_table,
            MAX(c.location_id) KEEP (DENSE_RANK FIRST ORDER BY c.id) AS sample_location,
            MAX(c.url) KEEP (DENSE_RANK FIRST ORDER BY c.id) AS sample_url
        FROM wwe.events e
        JOIN wwe.cards c
            ON c.event_id = e.id
        WHERE c.promotion_id = p_promotion_id
        GROUP BY e.id, e.name
        ORDER BY total_cards DESC
        FETCH FIRST 10 ROWS ONLY;
BEGIN
    DBMS_OUTPUT.PUT_LINE('--- WWE EVENT SUMMARY FOR PROMOTION ID: ' || p_promotion_id || ' ---');

    FOR rec IN c_promo_events LOOP
        v_data_found := TRUE;

        DBMS_OUTPUT.PUT_LINE(
            'Event: '       || rec.event_name ||
            ' | Cards: '    || rec.total_cards ||
            ' | Table: '    || rec.sample_table ||
            ' | Loc: '      || rec.sample_location ||
            ' | URL: '      || rec.sample_url
        );
    END LOOP;

    IF NOT v_data_found THEN
        DBMS_OUTPUT.PUT_LINE('No event data found for the specified promotion.');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

