CREATE OR REPLACE PROCEDURE sp_analyze_payment_method(
    p_payment_method IN VARCHAR2
) IS
    v_total_payment_amount NUMBER;
    v_total_payment_fee    NUMBER;
    v_net_amount           NUMBER;
    v_order_count          NUMBER;
    v_avg_order_amount     NUMBER;
    v_exists               NUMBER;
BEGIN
    IF p_payment_method IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Payment method cannot be NULL.');
        RETURN;
    END IF;

    SELECT COUNT(*)
    INTO v_exists
    FROM DELIVERY_CENTER.payments p
    WHERE p.payment_method = p_payment_method;

    IF v_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: No data found for payment method ' || p_payment_method);
        RETURN;
    END IF;

    SELECT
        NVL(SUM(p.payment_amount), 0),
        NVL(SUM(p.payment_fee), 0),
        COUNT(DISTINCT o.payment_order_id),
        NVL(AVG(DISTINCT o.order_amount), 0)
    INTO
        v_total_payment_amount,
        v_total_payment_fee,
        v_order_count,
        v_avg_order_amount
    FROM
        DELIVERY_CENTER.payments p
    LEFT JOIN
        DELIVERY_CENTER.orders o ON p.payment_order_id = o.payment_order_id
    WHERE
        p.payment_method = p_payment_method;

    v_net_amount := v_total_payment_amount - v_total_payment_fee;

    DBMS_OUTPUT.PUT_LINE('=== Enhanced Payment Method Analysis ===');
    DBMS_OUTPUT.PUT_LINE('Payment Method: ' || p_payment_method);
    DBMS_OUTPUT.PUT_LINE('Total Payment Amount: $' || TO_CHAR(ROUND(v_total_payment_amount, 2), 'FM9999999990.00'));
    DBMS_OUTPUT.PUT_LINE('Total Processing Fees: $' || TO_CHAR(ROUND(v_total_payment_fee, 2), 'FM9999999990.00'));
    DBMS_OUTPUT.PUT_LINE('Net Amount (After Fees): $' || TO_CHAR(ROUND(v_net_amount, 2), 'FM9999999990.00'));
    DBMS_OUTPUT.PUT_LINE('Associated Orders: ' || v_order_count);
    DBMS_OUTPUT.PUT_LINE('Average Order Amount: $' || TO_CHAR(ROUND(v_avg_order_amount, 2), 'FM9999999990.00'));

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: No data found for payment method ' || p_payment_method);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END sp_analyze_payment_method;
/

