CREATE OR REPLACE PROCEDURE sp_get_tracks_by_album (
    p_album_id IN NUMBER
) IS
    exp_invalid_album EXCEPTION;
    exp_no_tracks_found EXCEPTION;

    TYPE t_track_id_type IS TABLE OF MUSIC.TRACK.trackid%TYPE;
    TYPE t_track_name_type IS TABLE OF MUSIC.TRACK.name%TYPE;
    TYPE t_track_price_type IS TABLE OF MUSIC.TRACK.unitprice%TYPE;

    t_track_ids t_track_id_type;
    t_track_names t_track_name_type;
    t_track_prices t_track_price_type;

    l_album_cnt NUMBER;
BEGIN
    SELECT COUNT(*)
      INTO l_album_cnt
      FROM MUSIC.ALBUM
     WHERE albumid = p_album_id;

    IF l_album_cnt = 0 THEN
        RAISE exp_invalid_album;
    END IF;

    SELECT trackid, name, unitprice
    BULK COLLECT INTO t_track_ids, t_track_names, t_track_prices
      FROM MUSIC.TRACK
     WHERE albumid = p_album_id;

    IF t_track_ids.COUNT = 0 THEN
        RAISE exp_no_tracks_found;
    END IF;

    FOR lv_idx IN 1 .. t_track_ids.COUNT LOOP
        DBMS_OUTPUT.PUT_LINE(
            'Track ID: ' || t_track_ids(lv_idx) ||
            ' | Name: ' || t_track_names(lv_idx) ||
            ' | Price: ' || t_track_prices(lv_idx)
        );
    END LOOP;

EXCEPTION
    WHEN exp_invalid_album THEN
        DBMS_OUTPUT.PUT_LINE('Invalid Album ID.');
    WHEN exp_no_tracks_found THEN
        DBMS_OUTPUT.PUT_LINE('No tracks found for this album.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

DECLARE
    v_race_id NUMBER := 1;
    v_race_name F1.RACES.NAME%TYPE;
    v_race_year F1.RACES.YEAR%TYPE;
    v_driver_name VARCHAR2(200);
    v_lap_number F1.LAP_TIMES.LAP%TYPE;
    v_milliseconds F1.LAP_TIMES.MILLISECONDS%TYPE;
    v_count NUMBER := 0;
    v_race_exists NUMBER := 0;
    c_max_display CONSTANT NUMBER := 5;

BEGIN
    -- Validation: Check if race ID is NULL
    IF v_race_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Race ID cannot be NULL');
        RETURN;
    END IF;

    -- Validation: Check if race exists
    SELECT COUNT(*)
    INTO v_race_exists
    FROM F1.RACES
    WHERE RACE_ID = v_race_id;

    IF v_race_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Race ID ' || v_race_id || ' does not exist');
        RETURN;
    END IF;

    -- Data Retrieval: Get race information
    SELECT NAME, YEAR
    INTO v_race_name, v_race_year
    FROM F1.RACES
    WHERE RACE_ID = v_race_id;

    DBMS_OUTPUT.PUT_LINE('--- FASTEST LAP TIMES ---');
    DBMS_OUTPUT.PUT_LINE('Race: ' || v_race_name || ' (' || v_race_year || ')');
    DBMS_OUTPUT.PUT_LINE('------------------------');

    -- Data Retrieval: Get fastest lap times
    FOR rec IN (
        SELECT d.FORENAME || ' ' || d.SURNAME AS driver_name,
               lt.LAP,
               lt.MILLISECONDS
        FROM F1.LAP_TIMES lt
        INNER JOIN F1.DRIVERS_EXT d ON lt.DRIVER_ID = d.DRIVER_ID
        WHERE lt.RACE_ID = v_race_id
        ORDER BY lt.MILLISECONDS ASC
    ) LOOP
        v_count := v_count + 1;
        EXIT WHEN v_count > c_max_display;

        DBMS_OUTPUT.PUT_LINE(
            v_count || '. ' || rec.driver_name ||
            ' | Lap: ' || rec.LAP ||
            ' | Time: ' || ROUND(rec.MILLISECONDS/1000, 3) || 's'
        );
    END LOOP;

    IF v_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No lap time data available for this race');
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Race information not found');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END;

