CREATE OR REPLACE PROCEDURE sp_get_fastest_laps (
    p_race_id IN F1.RACES.RACE_ID%TYPE,
    p_max_results IN NUMBER DEFAULT 5
)
IS
    CURSOR cur_fastest_laps IS
        SELECT d.FORENAME || ' ' || d.SURNAME AS driver_name,
               lt.LAP,
               lt.MILLISECONDS
        FROM F1.LAP_TIMES lt
        INNER JOIN F1.DRIVERS_EXT d ON lt.DRIVER_ID = d.DRIVER_ID
        WHERE lt.RACE_ID = p_race_id
        ORDER BY lt.MILLISECONDS ASC;

    v_driver_name VARCHAR2(200);
    v_lap F1.LAP_TIMES.LAP%TYPE;
    v_milliseconds F1.LAP_TIMES.MILLISECONDS%TYPE;
    v_race_name F1.RACES.NAME%TYPE;
    v_race_year F1.RACES.YEAR%TYPE;
    v_count NUMBER := 0;
    v_race_exists NUMBER := 0;
    v_avg_lap_time NUMBER := 0;
    v_fastest_lap_time NUMBER := 0;
    v_total_laps NUMBER := 0;

BEGIN
    IF p_race_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Race ID cannot be NULL');
        RETURN;
    END IF;

    IF p_max_results IS NULL OR p_max_results <= 0 THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Maximum results must be a positive number');
        RETURN;
    END IF;

    SELECT COUNT(*)
    INTO v_race_exists
    FROM F1.RACES
    WHERE RACE_ID = p_race_id;

    IF v_race_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Race ID ' || p_race_id || ' does not exist');
        RETURN;
    END IF;

    SELECT NAME, YEAR
    INTO v_race_name, v_race_year
    FROM F1.RACES
    WHERE RACE_ID = p_race_id;

    SELECT COUNT(*),
           AVG(MILLISECONDS),
           MIN(MILLISECONDS)
    INTO v_total_laps, v_avg_lap_time, v_fastest_lap_time
    FROM F1.LAP_TIMES
    WHERE RACE_ID = p_race_id;

    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('RACE LAP TIME ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('Race: ' || v_race_name || ' (' || v_race_year || ')');
    DBMS_OUTPUT.PUT_LINE('Total Laps Recorded: ' || v_total_laps);
    DBMS_OUTPUT.PUT_LINE('Average Lap Time: ' || ROUND(v_avg_lap_time/1000, 3) || 's');
    DBMS_OUTPUT.PUT_LINE('Fastest Lap Time: ' || ROUND(v_fastest_lap_time/1000, 3) || 's');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('TOP ' || p_max_results || ' FASTEST LAPS:');
    DBMS_OUTPUT.PUT_LINE('----------------------------------------');

    IF cur_fastest_laps%ISOPEN THEN
        CLOSE cur_fastest_laps;
    END IF;

    OPEN cur_fastest_laps;
    LOOP
        FETCH cur_fastest_laps INTO v_driver_name, v_lap, v_milliseconds;
        EXIT WHEN cur_fastest_laps%NOTFOUND;

        v_count := v_count + 1;
        EXIT WHEN v_count > p_max_results;

        DBMS_OUTPUT.PUT_LINE(
            v_count || '. ' || v_driver_name ||
            ' | Lap: ' || v_lap ||
            ' | Time: ' || ROUND(v_milliseconds/1000, 3) || 's' ||
            ' | Delta: +' || ROUND((v_milliseconds - v_fastest_lap_time)/1000, 3) || 's'
        );

        EXIT WHEN v_count >= p_max_results;
    END LOOP;
    CLOSE cur_fastest_laps;

    IF v_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No lap time data available for this race');
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Race information not found');
    WHEN OTHERS THEN
        IF cur_fastest_laps%ISOPEN THEN
            CLOSE cur_fastest_laps;
        END IF;
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END sp_get_fastest_laps;
/

