CREATE OR REPLACE PROCEDURE sp_pizza_dtls (
    p_start_dtm DATE DEFAULT trunc(sysdate),
    p_end_dtm   DATE DEFAULT sysdate
) IS

    l_status VARCHAR2(200);
    l_rows   NUMBER := 0;
    invalid_daterange EXCEPTION;
    CURSOR cur_trans IS
    SELECT
        pz.pizza_id,
        pz.pizza_name,
        pco.customer_id,
        TO_TIMESTAMP(pco.order_time, 'YYYY-MM-DD HH24:MI:SS.FF') AS order_dtm
    FROM
             modern_data.pizza_names pz
        JOIN modern_data.pizza_customer_orders pco ON pz.pizza_id = pco.pizza_id
    WHERE
            TO_TIMESTAMP(pco.order_time, 'YYYY-MM-DD HH24:MI:SS.FF') >= CAST(p_start_dtm AS TIMESTAMP)
        AND TO_TIMESTAMP(pco.order_time, 'YYYY-MM-DD HH24:MI:SS.FF') < CAST(p_end_dtm + 1 AS TIMESTAMP);

BEGIN
    -- Validate date range
    IF p_start_dtm > p_end_dtm THEN
        RAISE invalid_daterange;
    END IF;
    FOR i IN cur_trans LOOP
        l_rows := l_rows + 1;

        -- Veg / Non-Veg logic
        IF upper(i.pizza_name) = 'MEATLOVERS' THEN
            l_status := 'Non Veg';
        ELSIF upper(i.pizza_name) = 'VEGETARIAN' THEN
            l_status := 'Veg';
        ELSE
            l_status := 'Unknown';
        END IF;

        dbms_output.put_line('Pizza ID: '
                             || i.pizza_id
                             || ' | Pizza Name: '
                             || i.pizza_name
                             || ' | Customer ID: '
                             || i.customer_id
                             || ' | Order Time: '
                             || to_char(i.order_dtm, 'DD-MON-YYYY HH24:MI:SS')
                             || ' | Type: '
                             || l_status);

    END LOOP;

    IF l_rows = 0 THEN
        dbms_output.put_line('No pizza orders found for the given date range.');
    END IF;
EXCEPTION
    WHEN invalid_daterange THEN
        dbms_output.put_line('Start date is greater than end date.');
    WHEN OTHERS THEN
        dbms_output.put_line('Error');    
       RAISE;
END sp_pizza_dtls;
/

CREATE OR REPLACE PROCEDURE sp_pizza_dtls (
    p_start_dtm VARCHAR2,
    p_end_dtm   VARCHAR2
) IS
    l_status       VARCHAR2(200);
    l_dlvry_status VARCHAR2(200);
    l_rows         NUMBER := 0;
    l_strt_dtm     DATE := TO_DATE(p_start_dtm, 'MMDDYYYY');
    l_end_dtm      DATE := TO_DATE(p_end_dtm, 'MMDDYYYY');
    zero_qty EXCEPTION;
    invalid_daterange EXCEPTION;

    CURSOR cur_trans IS
        SELECT
            pz.pizza_id,
            pz.pizza_name,
            pco.customer_id,
            TO_TIMESTAMP(pco.order_time, 'YYYY-MM-DD HH24:MI:SS.FF') AS order_dtm,
            (SYSTIMESTAMP - TO_TIMESTAMP(pco.order_time, 'YYYY-MM-DD HH24:MI:SS.FF')) AS elapsed_int
        FROM modern_data.pizza_names pz
        JOIN modern_data.pizza_customer_orders pco
            ON pz.pizza_id = pco.pizza_id
        JOIN modern_data.pizza_clean_runner_orders pcro
            ON pcro.order_id = pco.order_id
        WHERE TO_TIMESTAMP(pco.order_time, 'YYYY-MM-DD HH24:MI:SS.FF') >= CAST(l_strt_dtm AS TIMESTAMP)
          AND TO_TIMESTAMP(pco.order_time, 'YYYY-MM-DD HH24:MI:SS.FF') < CAST(l_end_dtm + 1 AS TIMESTAMP);

BEGIN
    IF l_strt_dtm > l_end_dtm THEN
        RAISE invalid_daterange;
    END IF;

    FOR i IN cur_trans LOOP
        l_rows := l_rows + 1;

        IF UPPER(i.pizza_name) = 'MEATLOVERS' THEN
            l_status := 'Non Veg';
        ELSIF UPPER(i.pizza_name) = 'VEGETARIAN' THEN
            l_status := 'Veg';
        ELSE
            l_status := 'Unknown';
        END IF;

        IF EXTRACT(DAY FROM i.elapsed_int) * 1440
           + EXTRACT(HOUR FROM i.elapsed_int) * 60
           + EXTRACT(MINUTE FROM i.elapsed_int) > 30 THEN
            l_dlvry_status := 'Delayed';
        ELSE
            l_dlvry_status := 'On Time';
        END IF;

        DBMS_OUTPUT.PUT_LINE(
            'Pizza ID: ' || i.pizza_id ||
            ' | Pizza Name: ' || i.pizza_name ||
            ' | Customer ID: ' || i.customer_id ||
            ' | Order Time: ' || TO_CHAR(i.order_dtm, 'DD-MON-YYYY HH24:MI:SS') ||
            ' | Type: ' || l_status ||
            ' | Delivery Status: ' || l_dlvry_status
        );
    END LOOP;

    IF l_rows = 0 THEN
        RAISE zero_qty;
    END IF;

EXCEPTION
    WHEN invalid_daterange THEN
        DBMS_OUTPUT.PUT_LINE('Start date is greater than end date.');
    WHEN zero_qty THEN
        DBMS_OUTPUT.PUT_LINE('No pizza orders found for the given date range.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error while processing pizza details');
        RAISE;
END sp_pizza_dtls;
/

