CREATE OR REPLACE FUNCTION sf_get_ipl_match_summary (
    p_match_id IN NUMBER
)
RETURN CLOB
IS

    CURSOR cur_match IS
        SELECT
            m.match_date,
            m.venue,
            t1.name AS team_1_name,
            t2.name AS team_2_name,
            m.match_winner,
            m.win_type,
            m.win_margin,
            m.man_of_the_match
        FROM ipl.match m
        JOIN ipl.team t1 ON m.team_1 = t1.team_id
        JOIN ipl.team t2 ON m.team_2 = t2.team_id
        WHERE m.match_id = p_match_id;

    CURSOR cur_players IS
        SELECT
            p.player_name,
            pm.role,
            t.name AS team_name,
            p.batting_hand,
            p.bowling_skill
        FROM ipl.player_match pm
        JOIN ipl.player p ON pm.player_id = p.player_id
        JOIN ipl.team t ON pm.team_id = t.team_id
        WHERE pm.match_id = p_match_id
        ORDER BY t.name, p.player_name;

    v_match_rec   cur_match%ROWTYPE;
    v_player_rec  cur_players%ROWTYPE;

    v_result CLOB := EMPTY_CLOB();

BEGIN

    IF p_match_id IS NULL THEN
        RETURN 'Match ID NULL not found.';
    END IF;

    OPEN cur_match;
    FETCH cur_match INTO v_match_rec;

    IF cur_match%NOTFOUND THEN
        CLOSE cur_match;
        RAISE NO_DATA_FOUND;
    END IF;

    v_result := v_result ||
        'IPL MATCH SUMMARY' || CHR(10) ||
        'Match ID          :' || ' ' || p_match_id || CHR(10) ||
        'Match Date        :' || ' ' || v_match_rec.match_date || CHR(10) ||
        'Venue             :' || ' ' || v_match_rec.venue || CHR(10) ||
        'Teams             :' || ' ' || v_match_rec.team_1_name || ' vs ' ||
                                 v_match_rec.team_2_name || CHR(10) ||
        'Match Winner      :' || ' ' || v_match_rec.match_winner || CHR(10) ||
        'Win Type          :' || ' ' || v_match_rec.win_type || CHR(10) ||
        'Win Margin        :' || ' ' || v_match_rec.win_margin || CHR(10) ||
        'Man of the Match  :' || ' ' || v_match_rec.man_of_the_match || CHR(10) ||
        '--------------------------------' || CHR(10);

    CLOSE cur_match;

    v_result := v_result || 'PLAYER PERFORMANCE DETAILS' || CHR(10);

    OPEN cur_players;
    LOOP
        FETCH cur_players INTO v_player_rec;
        EXIT WHEN cur_players%NOTFOUND;

        v_result := v_result ||
            'Match ID      :' || ' ' || p_match_id || CHR(10) ||
            'Player Name   :' || ' ' || v_player_rec.player_name || CHR(10) ||
            'Team          :' || ' ' || v_player_rec.team_name || CHR(10) ||
            'Role          :' || ' ' || v_player_rec.role || CHR(10) ||
            'Batting Hand  :' || ' ' || NVL(v_player_rec.batting_hand, 'N/A') || CHR(10) ||
            'Bowling Skill :' || ' ' || NVL(v_player_rec.bowling_skill, 'N/A') || CHR(10) ||
            '--------------------------------' || CHR(10);
    END LOOP;

    CLOSE cur_players;

    RETURN v_result;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Match ID: ' || p_match_id || ' data not found.';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_ipl_match_summary;
/

CREATE OR REPLACE FUNCTION sf_get_match_insights (
    p_match_id IN NUMBER
)
RETURN VARCHAR2
IS
    CURSOR cur_match IS
        SELECT
            t1.name AS team1,
            t2.name AS team2,
            tw.name AS winner_team,
            m.win_type,
            m.win_margin
        FROM ipl.match m
        JOIN ipl.team t1 ON m.team_1 = t1.team_id
        JOIN ipl.team t2 ON m.team_2 = t2.team_id
        LEFT JOIN ipl.team tw ON m.match_winner = tw.team_id
        WHERE m.match_id = p_match_id;

    CURSOR cur_team_players IS
        SELECT
            t.name AS team_name,
            COUNT(*) AS player_count
        FROM ipl.player_match pm
        JOIN ipl.team t ON pm.team_id = t.team_id
        WHERE pm.match_id = p_match_id
        GROUP BY t.name;

    v_team1           VARCHAR2(200);
    v_team2           VARCHAR2(200);
    v_match_winner    VARCHAR2(200);
    v_win_type        VARCHAR2(50);
    v_win_margin      NUMBER;

    v_team_name       VARCHAR2(200);
    v_player_count    NUMBER;

    v_result          VARCHAR2(32767) := '';
    v_match_quality   VARCHAR2(50);
    v_team1_players   NUMBER := 0;
    v_team2_players   NUMBER := 0;

BEGIN
    IF p_match_id IS NULL THEN
        RETURN 'Match ID NULL not found';
    END IF;

    OPEN cur_match;
    FETCH cur_match INTO
        v_team1,
        v_team2,
        v_match_winner,
        v_win_type,
        v_win_margin;

    IF cur_match%NOTFOUND THEN
        CLOSE cur_match;
        RETURN 'Match ID: ' || p_match_id || ' data not found.';
    END IF;

    CLOSE cur_match;

    IF v_win_type = 'runs' AND v_win_margin <= 10 THEN
        v_match_quality := 'Very Close Match';
    ELSIF v_win_type = 'wickets' AND v_win_margin <= 2 THEN
        v_match_quality := 'Tightly Contested Match';
    ELSIF v_win_margin >= 50 THEN
        v_match_quality := 'One-Sided Match';
    ELSE
        v_match_quality := 'Moderately Competitive Match';
    END IF;

    OPEN cur_team_players;
    LOOP
        FETCH cur_team_players INTO
            v_team_name,
            v_player_count;

        EXIT WHEN cur_team_players%NOTFOUND;

        IF v_team_name = v_team1 THEN
            v_team1_players := v_player_count;
        ELSIF v_team_name = v_team2 THEN
            v_team2_players := v_player_count;
        END IF;
    END LOOP;
    CLOSE cur_team_players;

    v_result :=
        'MATCH INSIGHTS SUMMARY' || CHR(10) ||
        '----------------------' || CHR(10) ||
        'Match ID      : ' || p_match_id || CHR(10) ||
        'Teams         : ' || v_team1 || ' vs ' || v_team2 || CHR(10) ||
        'Winner        : ' || v_match_winner || CHR(10) ||
        'Win Method    : ' || v_win_type || ' (' || v_win_margin || ')' || CHR(10) ||
        'Match Quality : ' || v_match_quality || CHR(10) ||
        'Team Participation' || CHR(10) ||
        v_team1 || CHR(10) ||
        'Players : ' || v_team1_players || CHR(10) ||
        v_team2 || CHR(10) ||
        'Players : ' || v_team2_players || CHR(10);

    IF v_team1_players < 11 OR v_team2_players < 11 THEN
        v_result := v_result ||
            'Alert: Incomplete player participation data detected.';
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_match_insights;
/

CREATE OR REPLACE PROCEDURE get_circuits_metadata(
    p_country IN VARCHAR2
) IS
    l_count NUMBER := 0;
    e_invalid_input exception;
BEGIN
    IF p_country IS NULL THEN
        RAISE e_invalid_input;
    END IF;

    FOR r IN (
        SELECT circuit_id, name, location
        FROM f1.circuits 
        WHERE UPPER(country) = UPPER(p_country)
        order by name
    ) LOOP
        l_count := l_count + 1;
        DBMS_OUTPUT.PUT_LINE(r.circuit_id || ' - ' || r.name || ', ' || r.location);
    END LOOP;

    IF l_count = 0 THEN
        RAISE NO_DATA_FOUND;
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No circuits found!');
        WHEN e_invalid_input THEN
        DBMS_OUTPUT.PUT_LINE('Please enter valid input!');
END;
/

