         DBMS_OUTPUT.PUT_LINE('Invalid product category ID.');
         RETURN;
   END;

   SELECT COUNT(*)
   INTO lv_subcategory_count
   FROM adventureworks.productsubcategory
   WHERE productcategoryid = p_product_category_id;

   DBMS_OUTPUT.PUT_LINE('Total subcategories:' || lv_subcategory_count);

   IF lv_subcategory_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No subcategories found for the given category.');
      RETURN;
   END IF;

   FOR cur_subcategory IN (
      SELECT name
      FROM adventureworks.productsubcategory
      WHERE productcategoryid = p_product_category_id
   ) LOOP
      DBMS_OUTPUT.PUT_LINE('Subcategory:' || cur_subcategory.name);
   END LOOP;

EXCEPTION
   WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END sp_get_subcategories_with_count;
