    p_driver_id IN NUMBER,
    p_year      IN NUMBER
) IS
    -- Local variables
    lv_total_points NUMBER;
    lv_tier         VARCHAR2(20);

BEGIN
    -- Start Log
    DBMS_OUTPUT.PUT_LINE('Starting audit for Driver ' || p_driver_id || ', Year ' || p_year);

    -- Data Retrieval: Using Subquery instead of Join
    DBMS_OUTPUT.PUT_LINE('Fetching race data...');
    SELECT SUM(points)
    INTO lv_total_points
    FROM F1.RESULTS
    WHERE driver_id = p_driver_id
      AND race_id IN (
          SELECT race_id
          FROM F1.RACES
