        DBMS_OUTPUT.PUT_LINE('No records found (SUM is NULL).');
        RAISE NO_DATA_FOUND;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Total Points retrieved: ' || lv_total_points);

