CREATE OR REPLACE PROCEDURE sp_country_population_summary (
    p_country_code IN census_bureau_international.country_names_area.country_code%TYPE
)
IS
    lv_country_name 
        census_bureau_international.country_names_area.country_name%TYPE;

    lv_country_area 
        census_bureau_international.country_names_area.country_area%TYPE;

    lv_year 
        census_bureau_international.midyear_population.year%TYPE;

    lv_population 
        census_bureau_international.midyear_population.midyear_population%TYPE;

    -- New calculated column
    lv_density NUMBER;

    lv_area_num NUMBER;
    lv_pop_num  NUMBER;
    lv_category VARCHAR2(30);

    exp_input_missing EXCEPTION;
BEGIN
    IF p_country_code IS NULL THEN
        RAISE exp_input_missing;
    END IF;

    ------------------------------------------------------------------
    -- Data Retrieval (6 Columns Logical Output)
    ------------------------------------------------------------------
    SELECT a.country_name,
           a.country_area,
           p.year,
           p.midyear_population
    INTO   lv_country_name,
           lv_country_area,
           lv_year,
           lv_population
    FROM   census_bureau_international.country_names_area a
           JOIN census_bureau_international.midyear_population p
             ON a.country_code = p.country_code
    WHERE  a.country_code = p_country_code
    AND    ROWNUM = 1;

    ------------------------------------------------------------------
    -- Population Logic
    ------------------------------------------------------------------
    lv_area_num := TO_NUMBER(lv_country_area);
    lv_pop_num  := TO_NUMBER(lv_population);

    IF lv_area_num = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Area cannot be zero.');
        RETURN;
    END IF;

    lv_density := lv_pop_num / lv_area_num;

    IF lv_pop_num > 100000000 THEN
        lv_category := 'Highly Populated';
    ELSIF lv_pop_num > 10000000 THEN
        lv_category := 'Moderately Populated';
    ELSE
        lv_category := 'Low Population';
    END IF;

    ------------------------------------------------------------------
    -- Output
    ------------------------------------------------------------------
    DBMS_OUTPUT.PUT_LINE('------------------------------');
    DBMS_OUTPUT.PUT_LINE('Country Code : ' || p_country_code);
    DBMS_OUTPUT.PUT_LINE('Country Name : ' || lv_country_name);
    DBMS_OUTPUT.PUT_LINE('Area         : ' || lv_country_area);
    DBMS_OUTPUT.PUT_LINE('Year         : ' || lv_year);
    DBMS_OUTPUT.PUT_LINE('Population   : ' || lv_population);
    DBMS_OUTPUT.PUT_LINE('Density      : ' || ROUND(lv_density,2));
    DBMS_OUTPUT.PUT_LINE('Category     : ' || lv_category);
    DBMS_OUTPUT.PUT_LINE('------------------------------');

EXCEPTION
    WHEN exp_input_missing THEN
        DBMS_OUTPUT.PUT_LINE('Country code cannot be NULL');
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Summary unavailable');
    WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Invalid numeric conversion');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_country_population_summary;
/

