        RETURN 'Shape ID NULL not found';
    END IF;

    -- DATA RETRIEVAL
    SELECT shape_point_lat,
           shape_point_lon,
           shape_distance_traveled
    INTO v_lat, v_lon, v_distance
    FROM san_francisco_transit_muni.shapes
    WHERE shape_id = p_shape_id
    AND ROWNUM = 1;

    RETURN 'Shape ID: ' || p_shape_id ||chr(10)||
           'Lat:'||v_lat||chr(10)||
           'Lon:'||v_lon||chr(10)||
           'Distance:'||v_distance;

-- EXCEPTION HANDLING
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Shape ID: ' || p_shape_id || ' no data found';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_fn_shape_basic;
/

CREATE OR REPLACE FUNCTION sf_fn_shape_extended(
    p_shape_id VARCHAR2
)
RETURN VARCHAR2
IS
    v_seq VARCHAR2(20);
    v_geom VARCHAR2(100);
    v_lat VARCHAR2(30);
    v_lon VARCHAR2(30);
BEGIN

    -- CONTROL FLOW
    IF p_shape_id IS NULL THEN
        RETURN 'Shape ID null not found';
    END IF;

    -- DATA RETRIEVAL
    SELECT shape_point_sequence,
           shape_point_geom,
           shape_point_lat,
           shape_point_lon
    INTO v_seq, v_geom, v_lat, v_lon
    FROM san_francisco_transit_muni.shapes
    WHERE shape_id = p_shape_id
    AND ROWNUM = 1;

    RETURN 'Shape ID: ' || p_shape_id ||chr(10)||
           'Seq:'||v_seq||chr(10)||
           'Geometry:'||v_geom||chr(10)||
           'Lat:'||v_lat||chr(10)||
           'Lon:'||v_lon;

-- EXCEPTION HANDLING
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Shape ID: ' || p_shape_id || ' no data found';
    WHEN OTHERS THEN
