/

CREATE OR REPLACE FUNCTION sf_fn_shape_analysis(
    p_shape_id VARCHAR2
)
RETURN VARCHAR2
IS
    v_count NUMBER;
    v_total_distance NUMBER;
BEGIN

    -- CONTROL FLOW
    IF p_shape_id IS NULL THEN
        RETURN 'Shape ID null not found';
    END IF;

    -- DATA RETRIEVAL
    SELECT COUNT(*),
           SUM(TO_NUMBER(shape_distance_traveled))
    INTO v_count, v_total_distance
    FROM san_francisco_transit_muni.shapes
    WHERE shape_id = p_shape_id;

    -- CONTROL FLOW CHECK
    IF v_count = 0 THEN
        RETURN 'Shape ID: ' || p_shape_id ||' '||'no data found';
    END IF;

    RETURN 'Shape ID: ' || p_shape_id ||chr(10)||
           'Total Points:'||v_count||chr(10)||
           'Total Distance:'||v_total_distance;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_fn_shape_analysis;
/

