DECLARE
    -- p_country_code: Input parameter simulation for the country identifier
    p_country_code   WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE := 'AFG';

    -- [Memory & Type] [Data Synchronization]
    lv_long_name     WORLD_BANK_WDI.COUNTRY_SUMMARY.long_name%TYPE;
    lv_region        WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE;
    lv_income_group  WORLD_BANK_WDI.COUNTRY_SUMMARY.income_group%TYPE;

    -- Derived variables for the final report
    lv_market_status VARCHAR2(50);
    lv_group_count   NUMBER;
BEGIN
    -- [Validation] [Control Flow]
    IF p_country_code IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Country code cannot be NULL.');
        RETURN;
    END IF;

    -- [Data Retrieval] [Inline Execution]
    -- Consolidating lookup, conditional classification, and analytical aggregation
    SELECT long_name, 
           region, 
           income_group, 
           market_status, 
           peer_count
    INTO   lv_long_name, 
           lv_region, 
           lv_income_group, 
           lv_market_status, 
           lv_group_count
    FROM   (
        SELECT long_name, 
               region, 
               income_group,
               CASE 
                   WHEN income_group = 'High income' THEN 'Developed Market'
                   ELSE 'Emerging Market'
               END AS market_status,
               -- [Analytical Modeling] Window function calculates peer group size inline
               COUNT(*) OVER(PARTITION BY income_group) AS peer_count
        FROM   WORLD_BANK_WDI.COUNTRY_SUMMARY
        -- Justification: filter to target country and peers by income_group for global context
        WHERE  country_code = p_country_code OR income_group = (
                    SELECT income_group 
                    FROM WORLD_BANK_WDI.COUNTRY_SUMMARY 
                    WHERE country_code = p_country_code
               )
    )
    -- Justification: filter to return the specific target country's details
    WHERE  long_name = (
                SELECT long_name 
                FROM WORLD_BANK_WDI.COUNTRY_SUMMARY 
                WHERE country_code = p_country_code
           )
      AND  ROWNUM = 1;

    -- [Output] [Control Flow]
    DBMS_OUTPUT.PUT_LINE('--- World Bank WDI Report ---');
    DBMS_OUTPUT.PUT_LINE('Long Name: ' || lv_long_name);
    DBMS_OUTPUT.PUT_LINE('Location : ' || lv_region);
    DBMS_OUTPUT.PUT_LINE('Economy  : ' || lv_income_group);
    DBMS_OUTPUT.PUT_LINE('Market   : ' || lv_market_status);
    DBMS_OUTPUT.PUT_LINE('Global Peer Group: ' || lv_group_count || ' countries share this status.');

    DBMS_OUTPUT.PUT_LINE('Status : Analysis completed successfully.');

EXCEPTION
    -- [Exception Handling]
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause: Country code not found.');
    WHEN OTHERS THEN 
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred'); 
END;
