CREATE OR REPLACE FUNCTION sf_fn_trip_details
(
    p_trip_id VARCHAR2
)
RETURN VARCHAR2
IS
    v_duration VARCHAR2(20);
    v_start    VARCHAR2(200);
    v_end      VARCHAR2(200);
    v_bike     VARCHAR2(100);

BEGIN

    -- STEP 1 : CONTROL FLOW (INPUT VALIDATION)
    IF p_trip_id IS NULL THEN
        RETURN 'Trip ID null not found';
    END IF;

    -- STEP 2 : DATA RETRIEVAL using INLINE VIEW
    SELECT duration_minutes,
           start_station_name,
           end_station_name,
           bike_type
    INTO v_duration,
         v_start,
         v_end,
         v_bike
    FROM (
            SELECT duration_minutes,
                   start_station_name,
                   end_station_name,
                   bike_type
            FROM austin_bikeshare.bikeshare_trips
            WHERE trip_id = p_trip_id
         );

    -- STEP 3 : CONTROL FLOW
    IF v_duration IS NULL THEN
        RETURN 'Trip exists but duration missing';
    END IF;

    -- STEP 4 : INLINE EXECUTION
    RETURN 'Trip '||p_trip_id||chr(10)||
           'Duration: '||v_duration||
           ' mins | From '||v_start||
           ' To '||v_end||chr(10)||
           'Bike: '||v_bike;

-- STEP 5 : EXCEPTION HANDLING
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Trip ID: '||p_trip_id||' '|| 'no data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_fn_trip_details;
/

CREATE OR REPLACE FUNCTION sf_fn_trip_analysis
(
    p_trip_id VARCHAR2
)
RETURN VARCHAR2
IS
    v_subscriber VARCHAR2(50);
    v_message    VARCHAR2(100);

BEGIN

    -- STEP 1 : CONTROL FLOW (INPUT VALIDATION)
    IF p_trip_id IS NULL THEN
        RETURN 'Trip ID cannot null not found';
    END IF;

    -- STEP 2 : DATA RETRIEVAL using INLINE VIEW
    SELECT subscriber_type
    INTO v_subscriber
    FROM (
            SELECT subscriber_type
            FROM austin_bikeshare.bikeshare_trips
            WHERE trip_id = p_trip_id
         );

    -- STEP 3 : CONTROL FLOW
    IF v_subscriber = 'Local365' THEN
        v_message := 'Regular Rider';
    ELSE
        v_message := 'Occasional Rider';
    END IF;

    -- STEP 4 : INLINE EXECUTION
    RETURN sf_fn_trip_details(p_trip_id)
           ||' | User Type: '||v_message;

-- STEP 5 : EXCEPTION HANDLING
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Trip id '|| p_trip_id||' '||'no data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_fn_trip_analysis;
/

DECLARE
    -- Input (acts like IN parameter)
    p_patient_id synthea.patients.id%TYPE := 'c8403116-d069-4130-aa02-39954fc971b5';

    -- Global variable
    gv_patient_exists NUMBER;

    -- Local variables
    lv_first_name synthea.patients.first%TYPE;
    lv_last_name  synthea.patients.last%TYPE;

    -- Custom Exception
    exp_invalid_input EXCEPTION;
    exp_patient_not_found EXCEPTION;

BEGIN
    -- Validate input
    IF p_patient_id IS NULL THEN
        RAISE exp_invalid_input;
    END IF;

    -- Inline execution using subquery
    SELECT COUNT(*)
    INTO gv_patient_exists
    FROM (
        SELECT id
        FROM synthea.patients
        WHERE id = p_patient_id
    );

    IF gv_patient_exists = 0 THEN
        RAISE exp_patient_not_found;
    END IF;

    -- Fetch patient details
    SELECT first, last
    INTO lv_first_name, lv_last_name
    FROM synthea.patients
    WHERE id = p_patient_id;

    DBMS_OUTPUT.PUT_LINE('Patient Name: '
                         || lv_first_name || ' ' || lv_last_name);

EXCEPTION
    WHEN exp_invalid_input THEN
        DBMS_OUTPUT.PUT_LINE('Error: Patient ID cannot be NULL.');

    WHEN exp_patient_not_found THEN
        DBMS_OUTPUT.PUT_LINE('Error: Patient record not found.');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;

