CREATE OR REPLACE PROCEDURE sp_process_county_data (
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE
)
IS
    lv_births       NUMBER;
    lv_age          NUMBER;
    lv_birth_weight NUMBER;
    lv_risk_status  VARCHAR2(20);
    gv_exists       NUMBER;
BEGIN
    -- Null input check
    IF p_county_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Input Error: County cannot be NULL.');
        RETURN;
    END IF;
    -- Inline execution (subquery validation)
    SELECT COUNT(*)
    INTO gv_exists
    FROM (
        SELECT COUNTY_OF_RESIDENCE
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
        WHERE COUNTY_OF_RESIDENCE = p_county_name
    );

    IF gv_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('County does not exist.');
        RETURN;
    END IF;

    -- Fetch metrics
        SELECT SUM(TO_NUMBER(BIRTHS)), AVG(TO_NUMBER(AVE_AGE_OF_MOTHER)), ROUND(AVG(TO_NUMBER(AVE_BIRTH_WEIGHT_GMS)),2)
        INTO lv_births, lv_age, lv_birth_weight
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
        WHERE COUNTY_OF_RESIDENCE = p_county_name;

        DBMS_OUTPUT.PUT_LINE('County: ' || p_county_name);
        DBMS_OUTPUT.PUT_LINE('Total Births: ' || lv_births);
        DBMS_OUTPUT.PUT_LINE('Average Age of Mother: ' || lv_age);
        DBMS_OUTPUT.PUT_LINE('Average Birth Weight: ' || lv_birth_weight);

    -- Simple risk evaluation
    IF lv_births < 50 OR lv_birth_weight < 2000 THEN
        lv_risk_status := 'HIGH RISK';
    ELSE
        lv_risk_status := 'STABLE';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Risk Status: ' || lv_risk_status);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_process_county_data;
/

CREATE OR REPLACE PROCEDURE sp_advanced_county_analysis (
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE
)
IS
    lv_births        NUMBER;
    lv_age           NUMBER;
    lv_birth_weight  NUMBER;
    lv_gest_age      NUMBER;
    lv_risk_status   VARCHAR2(20);
    gv_exists        NUMBER;
BEGIN
        -- Null input check
    IF p_county_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Input Error: County cannot be NULL.');
        RETURN;
    END IF;
    -- Inline execution (subquery validation)
    SELECT COUNT(*)
    INTO gv_exists
    FROM (
        SELECT COUNTY_OF_RESIDENCE
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
        WHERE COUNTY_OF_RESIDENCE = p_county_name
    );

    IF gv_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('County does not exist.');
        RETURN;
    END IF;

    -- Fetch metrics
        SELECT ROUND(SUM(TO_NUMBER(BIRTHS)),2), ROUND(AVG(TO_NUMBER(AVE_AGE_OF_MOTHER)),2), ROUND(AVG(TO_NUMBER(AVE_BIRTH_WEIGHT_GMS)),2), ROUND(AVG(TO_NUMBER(AVE_OE_GESTATIONAL_AGE_WKS)),2)
        INTO lv_births, lv_age, lv_birth_weight, lv_gest_age
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
        WHERE COUNTY_OF_RESIDENCE = p_county_name;

        DBMS_OUTPUT.PUT_LINE('County: ' || p_county_name);
        DBMS_OUTPUT.PUT_LINE('Total Births: ' || lv_births);
        DBMS_OUTPUT.PUT_LINE('Average Age of Mother: ' || lv_age);
        DBMS_OUTPUT.PUT_LINE('Average Birth Weight: ' || lv_birth_weight);
        DBMS_OUTPUT.PUT_LINE('Average Gestational Age: ' || lv_gest_age);


    -- Risk evaluation
    IF lv_births < 50 OR lv_birth_weight < 2000 OR lv_gest_age < 28 THEN
        lv_risk_status := 'HIGH RISK';
    ELSE
        lv_risk_status := 'STABLE';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Risk Status: ' || lv_risk_status);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_advanced_county_analysis;
/

CREATE OR REPLACE FUNCTION sf_get_order_amount (
    p_order_id IN NUMBER
) RETURN VARCHAR2
IS
    v_amount NUMBER(38);
BEGIN
    -- Input validation
    IF p_order_id IS NULL THEN
        RETURN 'Order id null not found';
    END IF;

    -- Data retrieval
    SELECT order_amount
    INTO v_amount
    FROM delivery_center.orders
    WHERE order_id = p_order_id;

    -- Control flow
    IF v_amount IS NULL THEN
        RETURN 'Order id: ' || p_order_id || CHR(10) ||
               'Order found but amount is NULL';
    END IF;

    RETURN 'Order id: ' || p_order_id || CHR(10) ||
           'Order Amount: ' || v_amount;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Order id: ' || p_order_id || ' no data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_order_amount;
/

CREATE OR REPLACE FUNCTION sf_get_order_financials (
    p_order_id IN NUMBER
) RETURN VARCHAR2
IS
    v_amount  NUMBER(38);
    v_fee     NUMBER(38);
    v_status  VARCHAR2(50);
BEGIN
    -- input validation
    IF p_order_id IS NULL THEN
        RETURN 'Order id null not found';
    END IF;

    -- Data retrieval
    SELECT order_amount, order_delivery_fee, order_status
    INTO v_amount, v_fee, v_status
    FROM delivery_center.orders
    WHERE order_id = p_order_id;

    -- Control flow
    IF v_amount IS NULL THEN
        RETURN 'Order id: ' || p_order_id || CHR(10) ||
               'Order exists but amount is missing';
    END IF;

    RETURN 'Order id: ' || p_order_id || CHR(10) ||
           'Status: ' || v_status || CHR(10) ||
           'Amount: ' || v_amount || CHR(10) ||
           'Delivery Fee: ' || NVL(v_fee, 0);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Order id: ' || p_order_id || ' no data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_order_financials;
/

CREATE OR REPLACE FUNCTION sf_get_order_operational_summary (
    p_order_id IN NUMBER
) RETURN VARCHAR2
IS
    v_amount    NUMBER(38);
    v_fee       NUMBER(38);
    v_cost      NUMBER(38);
    v_cycle     NUMBER(38);
    v_status    VARCHAR2(50);
    v_delivered TIMESTAMP(6);

    v_completion_result VARCHAR2(50);
    v_delivery_issue    VARCHAR2(100);
BEGIN
    -- Input validation
    IF p_order_id IS NULL THEN
        RETURN 'Order ID NULL not found';
    END IF;

    -- Data retrieval
    SELECT order_amount,
           order_delivery_fee,
           order_delivery_cost,
           order_metric_cycle_time,
           order_status,
           order_moment_delivered
    INTO v_amount,
         v_fee,
         v_cost,
         v_cycle,
         v_status,
         v_delivered
    FROM delivery_center.orders
    WHERE order_id = p_order_id;

    -- Determine completion status
    IF v_status = 'FINISHED' THEN
        v_completion_result := 'Order was completed successfully';
    ELSE
        v_completion_result := 'Order was canceled';
    END IF;

    -- Determine delivery problems
    IF v_status = 'CANCELED' THEN
        v_delivery_issue := 'Order canceled before completion';

    ELSIF v_status = 'FINISHED' AND v_delivered IS NULL THEN
        v_delivery_issue := 'Order finished but delivery timestamp is missing';

    ELSIF v_status = 'FINISHED' AND v_cycle > 50 THEN
        v_delivery_issue := 'Order finished but delivery took longer than expected';

    ELSE
        v_delivery_issue := 'Order completed normally';
    END IF;

    RETURN 'Order ID: ' || p_order_id || CHR(10) ||
           'Order Status: ' || v_status || CHR(10) ||
           'Completion Result: ' || v_completion_result || CHR(10) ||
           'Total amount paid: ' || (NVL(v_amount,0) + NVL(v_fee,0) + NVL(v_cost,0)) || CHR(10) ||
           'Delivery check: ' || v_delivery_issue;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Order id: ' || p_order_id || ' no data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_order_operational_summary;
/

