    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE exp_no_country;
    END;

    -- Data Retrieval: Calculate debt statistics
    BEGIN
        SELECT COUNT(*),
               COUNT(DISTINCT year),
               NVL(SUM(TO_NUMBER(value)), 0),
               NVL(AVG(TO_NUMBER(value)), 0),
