CREATE OR REPLACE PROCEDURE sp_w_analyze_debt_summary(
    p_country_code IN VARCHAR2 DEFAULT 'CHN'
) IS

    -- Data Retrieval: Variables for country information
    lv_country_code   WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.COUNTRY_CODE%TYPE;
    lv_country_name   WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.SHORT_NAME%TYPE;
    lv_income_group   WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.INCOME_GROUP%TYPE;
    lv_region         WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.REGION%TYPE;
    lv_total_debt     NUMBER := 0;
    lv_avg_debt       NUMBER := 0;
    lv_max_debt       NUMBER := 0;
    lv_min_debt       NUMBER := 0;
    lv_record_count   NUMBER := 0;
    lv_year_count     NUMBER := 0;
    lv_series_count   NUMBER := 0;
    lv_topic_count    NUMBER := 0;
    lv_recent_year_debt NUMBER := 0;
    lv_prev_year_debt   NUMBER := 0;
    lv_debt_growth_pct  NUMBER := 0;

    -- Exception Handling: Custom exceptions
    exp_no_country          EXCEPTION;
    exp_no_debt_data        EXCEPTION;
    exp_null_parameter      EXCEPTION;
    exp_invalid_code_format EXCEPTION;

BEGIN

    DBMS_OUTPUT.PUT_LINE('================================================================');
    DBMS_OUTPUT.PUT_LINE('        OPTIMIZED COUNTRY DEBT ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('================================================================');

    -- Control Flow: Validate input parameter
    IF p_country_code IS NULL THEN
        RAISE exp_null_parameter;
    END IF;

    -- Control Flow: Validate country code format (3 uppercase letters)
    IF LENGTH(p_country_code) != 3 OR NOT REGEXP_LIKE(p_country_code, '^[A-Z]{3}$') THEN
        RAISE exp_invalid_code_format;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Target Country Code: ' || p_country_code);
    DBMS_OUTPUT.PUT_LINE('[RCA] Input validation passed - inline execution ready');
    DBMS_OUTPUT.PUT_LINE('----------------------------------------------------------------');
    DBMS_OUTPUT.PUT_LINE('');

    -- Data Retrieval: Get country information with inline subquery for total debt
    BEGIN
        SELECT cs.country_code,
               cs.short_name,
               cs.income_group,
               cs.region,
               (SELECT NVL(SUM(TO_NUMBER(id.value)), 0)
                FROM   WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
                WHERE  id.country_code = cs.country_code
                  AND  id.value        IS NOT NULL) AS total_debt_inline
        INTO   lv_country_code,
               lv_country_name,
               lv_income_group,
               lv_region,
               lv_total_debt
        FROM   WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
        WHERE  cs.country_code = p_country_code;

        DBMS_OUTPUT.PUT_LINE('COUNTRY INFORMATION:');
        DBMS_OUTPUT.PUT_LINE('  Country: '                  || lv_country_name);
        DBMS_OUTPUT.PUT_LINE('  Code: '                     || lv_country_code);
        DBMS_OUTPUT.PUT_LINE('  Region: '                   || NVL(lv_region, 'Not specified'));
        DBMS_OUTPUT.PUT_LINE('  Income Group: '             || NVL(lv_income_group, 'Not classified'));
        DBMS_OUTPUT.PUT_LINE('  Total Debt (All Years): $'  || TO_CHAR(lv_total_debt, '999,999,999,999,999'));
        DBMS_OUTPUT.PUT_LINE('  [RCA] Total debt calculated using inline subquery for performance');
        DBMS_OUTPUT.PUT_LINE('');

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE exp_no_country;
    END;

    -- Data Retrieval: Calculate detailed debt statistics
    BEGIN
        SELECT COUNT(*),
               COUNT(DISTINCT year),
               NVL(AVG(TO_NUMBER(value)), 0),
               NVL(MAX(TO_NUMBER(value)), 0),
               NVL(MIN(TO_NUMBER(value)), 0)
        INTO   lv_record_count,
               lv_year_count,
               lv_avg_debt,
               lv_max_debt,
               lv_min_debt
        FROM   WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT
        WHERE  country_code = p_country_code
          AND  value        IS NOT NULL;

        -- Control Flow: Check if debt data exists
        IF lv_record_count = 0 THEN
            RAISE exp_no_debt_data;
        END IF;

        DBMS_OUTPUT.PUT_LINE('DEBT STATISTICS:');
        DBMS_OUTPUT.PUT_LINE('  Total Records: ' || lv_record_count);
        DBMS_OUTPUT.PUT_LINE('  Years Covered: ' || lv_year_count);
        DBMS_OUTPUT.PUT_LINE('  Average Value: $' || TO_CHAR(lv_avg_debt, '999,999,999,999'));
        DBMS_OUTPUT.PUT_LINE('  Maximum Value: $' || TO_CHAR(lv_max_debt, '999,999,999,999'));
        DBMS_OUTPUT.PUT_LINE('  Minimum Value: $' || TO_CHAR(lv_min_debt, '999,999,999,999'));
        DBMS_OUTPUT.PUT_LINE('');

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE exp_no_debt_data;
    END;

    -- Inline Execution: Calculate year-over-year growth using CASE expressions
    BEGIN
        SELECT NVL(SUM(CASE WHEN year = '2015' THEN TO_NUMBER(value) ELSE 0 END), 0),
               NVL(SUM(CASE WHEN year = '2014' THEN TO_NUMBER(value) ELSE 0 END), 0)
        INTO   lv_recent_year_debt,
               lv_prev_year_debt
        FROM   WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT
        WHERE  country_code = p_country_code
          AND  year         IN ('2014', '2015')
          AND  value        IS NOT NULL;

        -- Control Flow: Calculate growth percentage if prior year data exists
        IF lv_prev_year_debt > 0 THEN
            lv_debt_growth_pct := ((lv_recent_year_debt - lv_prev_year_debt) / lv_prev_year_debt) * 100;
        END IF;

        DBMS_OUTPUT.PUT_LINE('YEAR-OVER-YEAR ANALYSIS:');
        DBMS_OUTPUT.PUT_LINE('  2014 Total: $'   || TO_CHAR(lv_prev_year_debt,   '999,999,999,999'));
        DBMS_OUTPUT.PUT_LINE('  2015 Total: $'   || TO_CHAR(lv_recent_year_debt, '999,999,999,999'));
        DBMS_OUTPUT.PUT_LINE('  Growth Rate: '   || TO_CHAR(lv_debt_growth_pct,  '990.99') || '%');
        DBMS_OUTPUT.PUT_LINE('  [RCA] Growth calculated using inline CASE expressions');
        DBMS_OUTPUT.PUT_LINE('');

    EXCEPTION
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
    END;

    -- Data Retrieval: Get series count
    BEGIN
        SELECT COUNT(DISTINCT series_code)
        INTO   lv_series_count
        FROM   WORLD_BANK_INTL_DEBT.COUNTRY_SERIES_DEFINITIONS
        WHERE  country_code = p_country_code;

        DBMS_OUTPUT.PUT_LINE('SERIES INFORMATION:');
        DBMS_OUTPUT.PUT_LINE('  Defined Series: ' || lv_series_count);

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('SERIES INFORMATION:');
            DBMS_OUTPUT.PUT_LINE('  Defined Series: 0');
    END;

    -- Data Retrieval: Get topic count from series summary with JOIN
    BEGIN
        SELECT COUNT(DISTINCT ss.topic)
        INTO   lv_topic_count
        FROM   WORLD_BANK_INTL_DEBT.COUNTRY_SERIES_DEFINITIONS csd
        JOIN   WORLD_BANK_INTL_DEBT.SERIES_SUMMARY ss
            ON csd.series_code = ss.series_code
        WHERE  csd.country_code = p_country_code;

        DBMS_OUTPUT.PUT_LINE('  Topics Covered: ' || lv_topic_count);
        DBMS_OUTPUT.PUT_LINE('  [RCA] Topic enrichment from series summary completed');
        DBMS_OUTPUT.PUT_LINE('');

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('  Topics Covered: 0');
            DBMS_OUTPUT.PUT_LINE('');
    END;

    DBMS_OUTPUT.PUT_LINE('================================================================');
    DBMS_OUTPUT.PUT_LINE('[SUMMARY] Analysis completed for ' || lv_country_name);
    DBMS_OUTPUT.PUT_LINE('[RCA] Optimized analysis with inline execution completed');
    DBMS_OUTPUT.PUT_LINE('================================================================');

EXCEPTION

    WHEN exp_null_parameter THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('[ERROR] NULL Parameter');
        DBMS_OUTPUT.PUT_LINE('[RCA] Country code parameter cannot be NULL');
        DBMS_OUTPUT.PUT_LINE('[RECOMMENDATION] Provide a valid 3-character country code');

    WHEN exp_invalid_code_format THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('[ERROR] Invalid Country Code Format');
        DBMS_OUTPUT.PUT_LINE('[RCA] Country code must be exactly 3 uppercase letters');
        DBMS_OUTPUT.PUT_LINE('[PROVIDED] "' || p_country_code || '"');
        DBMS_OUTPUT.PUT_LINE('[RECOMMENDATION] Use ISO 3166-1 alpha-3 codes (e.g., USA, CHN, IND)');

    WHEN exp_no_country THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('[ERROR] Country Not Found');
        DBMS_OUTPUT.PUT_LINE('[RCA] Country code "' || p_country_code || '" does not exist in database');
        DBMS_OUTPUT.PUT_LINE('[RECOMMENDATION] Verify country code from COUNTRY_SUMMARY table');

    WHEN exp_no_debt_data THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('[ERROR] No Debt Data');
        DBMS_OUTPUT.PUT_LINE('[RCA] No debt indicators found for country: ' || lv_country_name);
        DBMS_OUTPUT.PUT_LINE('[RECOMMENDATION] This country may not have debt data available');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');

END sp_w_analyze_debt_summary;
/

