DECLARE
    -- [Memory & Type], [Data Synchronization]
    -- [Data Retrieval] via Schema.Table.Column anchoring
    lv_input_series BLS.EMPLOYMENT_HOURS_EARNINGS_SERIES.SERIES_ID%TYPE := 'CES1021210013';
    lv_input_year   BLS.EMPLOYMENT_HOURS_EARNINGS.YEAR%TYPE := 2021;

    v_series_title  BLS.EMPLOYMENT_HOURS_EARNINGS_SERIES.SERIES_TITLE%TYPE;
    v_emp_value     BLS.EMPLOYMENT_HOURS_EARNINGS.VALUE%TYPE;
BEGIN
    -- [Set-based Processing] [Analytical Modeling]
    -- Fetching unified data with explicit schema qualification and deterministic sort
    SELECT s.SERIES_TITLE, 
           e.VALUE
    INTO   v_series_title, 
           v_emp_value
    FROM   BLS.EMPLOYMENT_HOURS_EARNINGS e
    INNER JOIN BLS.EMPLOYMENT_HOURS_EARNINGS_SERIES s 
        ON e.SERIES_ID = s.SERIES_ID
    WHERE  e.SERIES_ID = lv_input_series 
      AND  e.YEAR = lv_input_year 
      -- Restrict to first month (M01) to standardize annual comparison across series
      AND  e.PERIOD = 'M01'
    ORDER BY e.YEAR DESC, 
             e.PERIOD ASC;

    -- [Control Flow] [Decision Logic]
    DBMS_OUTPUT.PUT_LINE('--- BLS Qualified Employment Report ---');
    DBMS_OUTPUT.PUT_LINE('Series: ' || v_series_title);
    DBMS_OUTPUT.PUT_LINE('Value : ' || v_emp_value);
    DBMS_OUTPUT.PUT_LINE('Status : Report generated successfully.');

EXCEPTION
    -- [Exception Handling] [Root Cause Analysis]
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause: No record for ' || lv_input_series || ' in ' || lv_input_year);
    WHEN OTHERS THEN 
    DBMS_OUTPUT.PUT_LINE('Unexpected error occurred'); 
END;
/

