CREATE OR REPLACE PROCEDURE SP_GET_BLS_EMPLOYMENT_REPORT_4 (
    lv_input_series BLS.EMPLOYMENT_HOURS_EARNINGS_SERIES.series_id%TYPE ,
    lv_input_year   BLS.EMPLOYMENT_HOURS_EARNINGS.year%TYPE ) is
    lv_series_title BLS.EMPLOYMENT_HOURS_EARNINGS_SERIES.series_title%TYPE;
    lv_emp_value    BLS.EMPLOYMENT_HOURS_EARNINGS.value%TYPE;
    lv_performance  VARCHAR2(20);
BEGIN
    IF lv_input_series IS NULL OR lv_input_year IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Series ID or Year cannot be NULL.');
        RETURN;
    END IF;

    SELECT s.series_title,
           e.value
    INTO   lv_series_title,
           lv_emp_value
    FROM   BLS.EMPLOYMENT_HOURS_EARNINGS e
    INNER JOIN BLS.EMPLOYMENT_HOURS_EARNINGS_SERIES s
        ON e.series_id = s.series_id
    WHERE  e.series_id = lv_input_series
      AND  e.year = lv_input_year
      AND  e.period = 'M01'
    ORDER BY e.year DESC,
             e.period ASC;

    IF lv_emp_value >= 100 THEN
        lv_performance := 'High';
    ELSIF lv_emp_value >= 50 THEN
        lv_performance := 'Moderate';
    ELSE
        lv_performance := 'Low';
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- BLS Qualified Employment Report ---');
    DBMS_OUTPUT.PUT_LINE('Series: ' || lv_series_title);
    DBMS_OUTPUT.PUT_LINE('Value : ' || lv_emp_value);
    DBMS_OUTPUT.PUT_LINE('Performance Category: ' || lv_performance);

    DBMS_OUTPUT.PUT_LINE('Status : Final Report generated successfully.');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause: No record for ' || lv_input_series || ' in ' || lv_input_year);

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

DECLARE
    v_trip_id VARCHAR2(50) := '689799';
    v_station VARCHAR2(100);
    v_duration VARCHAR2(20);
BEGIN
    IF v_trip_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Trip ID NULL not found');
        RETURN;
    END IF;
    -- DATA RETRIEVAL using INLINE VIEW
    SELECT start_station_name,
           duration_sec
    INTO v_station,
         v_duration
    FROM (
            SELECT start_station_name,
                   duration_sec,
                   trip_id
            FROM san_francisco.bikeshare_trips
         )
    WHERE trip_id = v_trip_id;

    -- CONTROL FLOW
    IF v_duration IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Duration is NULL');

    ELSIF TO_NUMBER(v_duration) > 800 THEN
        DBMS_OUTPUT.PUT_LINE('Trip ID: '||v_trip_id||' '||'Long Trip');

    ELSE
        DBMS_OUTPUT.PUT_LINE('Trip ID: '||v_trip_id||' '||'Short Trip');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Start Station: '||v_station);
    DBMS_OUTPUT.PUT_LINE('Duration: '||v_duration);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Trip ID: '||v_trip_id||' '||'not found');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;

