CREATE OR REPLACE PROCEDURE sp_get_model_full_summary (
    p_name IN VARCHAR2
) IS
    v_score       stacking.solution.score%TYPE;
    v_version     stacking.solution.version%TYPE;
    v_correlation stacking.solution.correlation%TYPE;
    v_quality     VARCHAR2(30);
BEGIN
    -- Input check (control flow)
    IF p_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Model Name null not found');
		RETURN;
    END IF;

    SELECT DISTINCT score, version, correlation
    INTO v_score, v_version, v_correlation
    FROM stacking.solution
    WHERE name = p_name
    FETCH FIRST 1 ROW ONLY;

    IF v_correlation IS NULL THEN
        v_quality := 'Model quality cannot be determined';
    ELSIF v_correlation >= 0.8 THEN
        v_quality := 'High quality model';
    ELSE
        v_quality := 'Moderate quality model';
