        'Model name: ' || p_name ||chr(10)||
        'Version: ' || v_version ||chr(10)||
        'Score: ' || NVL(TO_CHAR(v_score), 'Not available') ||chr(10)||
        'Correlation: ' || NVL(TO_CHAR(v_correlation), 'N/A') ||chr(10)||
        'Assessment: ' || v_quality
    );

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Model Name: ' || p_name || ' no data found');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');        
