DECLARE
  lv_year          SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2019-01-01';
  lv_county_like   VARCHAR2(100) := '%';
  co_report_limit  CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_skipped_rows  PLS_INTEGER := 0;
  lv_printed_rows  PLS_INTEGER := 0;
  lv_births_num    NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(lv_year, 'YYYY') || ', county like=' || lv_county_like);

  FOR rec IN (
    SELECT cn.county_of_residence,
           cn.births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = lv_year
       AND cn.county_of_residence LIKE lv_county_like
     ORDER BY cn.births DESC
  ) LOOP
    BEGIN
      lv_births_num := TO_NUMBER(TRIM(rec.births));

      lv_printed_rows := lv_printed_rows + 1;
      DBMS_OUTPUT.PUT_LINE(RPAD(rec.county_of_residence, 40) || ' births=' || TO_CHAR(lv_births_num));

      EXIT WHEN lv_printed_rows >= co_report_limit;

    EXCEPTION
      WHEN VALUE_ERROR THEN
        lv_skipped_rows := lv_skipped_rows + 1;
      WHEN INVALID_NUMBER THEN
        lv_skipped_rows := lv_skipped_rows + 1;
      WHEN OTHERS THEN
        lv_skipped_rows := lv_skipped_rows + 1;
        DBMS_OUTPUT.PUT_LINE('Unexpected row-level error for county=' || rec.county_of_residence);
    END;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Printed rows: ' || lv_printed_rows);
  DBMS_OUTPUT.PUT_LINE('Skipped (non-numeric/failed conversions): ' || lv_skipped_rows);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ');
END;
/

