SET SERVEROUTPUT ON;
DECLARE
  lv_year_a SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2017-01-01';
  lv_year_b SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2018-01-01';
  lv_county_like VARCHAR2(100) := '%';
  co_report_limit CONSTANT PLS_INTEGER := 15;
  lv_printed_rows PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('County births increase from ' || TO_CHAR(lv_year_a, 'YYYY') || ' to ' || TO_CHAR(lv_year_b, 'YYYY') || ', county like=' || lv_county_like);
  FOR rec IN (
    WITH births_a AS (
      SELECT cn.county_of_residence AS county_of_residence, SUM(TO_NUMBER(TRIM(cn.births))) AS births_num
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = lv_year_a
         AND cn.county_of_residence LIKE lv_county_like
         AND REGEXP_LIKE(TRIM(cn.births), '^[0-9]+(\.[0-9]+)?$')
       GROUP BY cn.county_of_residence
    ), births_b AS (
      SELECT cn.county_of_residence AS county_of_residence, SUM(TO_NUMBER(TRIM(cn.births))) AS births_num
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = lv_year_b
         AND cn.county_of_residence LIKE lv_county_like
         AND REGEXP_LIKE(TRIM(cn.births), '^[0-9]+(\.[0-9]+)?$')
       GROUP BY cn.county_of_residence
    )
    SELECT b.county_of_residence, a.births_num AS births_a, b.births_num AS births_b,
           (b.births_num - a.births_num) AS delta_births,
           CASE WHEN (b.births_num - a.births_num) >= 1000 THEN 'HIGH' WHEN (b.births_num - a.births_num) >= 200 THEN 'MED' ELSE 'LOW' END AS increase_bucket
      FROM births_a a INNER JOIN births_b b ON b.county_of_residence = a.county_of_residence
     WHERE (b.births_num - a.births_num) > 0
     ORDER BY delta_births DESC
  ) LOOP
    lv_printed_rows := lv_printed_rows + 1;
    DBMS_OUTPUT.PUT_LINE(RPAD(rec.county_of_residence, 40) || ' A=' || TO_CHAR(rec.births_a) || ' B=' || TO_CHAR(rec.births_b) || ' + ' || TO_CHAR(rec.delta_births) || ' bucket=' || rec.increase_bucket);
    EXIT WHEN lv_printed_rows >= co_report_limit;
  END LOOP;
  IF lv_printed_rows = 0 THEN DBMS_OUTPUT.PUT_LINE('No counties found with an increase for the given filters/years.'); END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error: ' );
END;
/

