DECLARE
  lv_year           SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2019-01-01';
  lv_county_like    VARCHAR2(100) := '%';
  co_county_limit   CONSTANT PLS_INTEGER := 15; -- Limit output for diagnostic readability

  lv_total_rows     NUMBER;
  lv_bad_rows       NUMBER;
  lv_bad_pct        NUMBER;
  lv_recommendation VARCHAR2(30);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Data quality diagnostic for year=' || TO_CHAR(lv_year, 'YYYY') || ', county like=' || lv_county_like);

  FOR rec IN (
    SELECT county_of_residence
      FROM (
        SELECT DISTINCT cn.county_of_residence
          FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
         WHERE cn.year = lv_year
           AND cn.county_of_residence LIKE lv_county_like
         ORDER BY cn.county_of_residence
      )
     WHERE ROWNUM <= co_county_limit
  ) LOOP
    SELECT COUNT(*),
           SUM(CASE WHEN REGEXP_LIKE(TRIM(cn.births), '^[0-9]+(\.[0-9]+)?$') THEN 0 ELSE 1 END)
      INTO lv_total_rows, lv_bad_rows
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = lv_year
       AND cn.county_of_residence = rec.county_of_residence;

    IF lv_total_rows = 0 THEN
      lv_bad_pct := 100;
    ELSE
      lv_bad_pct := ROUND((lv_bad_rows / lv_total_rows) * 100, 2);
    END IF;

    IF lv_bad_pct <= 1 THEN
      lv_recommendation := 'SAFE';
    ELSIF lv_bad_pct <= 10 THEN
      lv_recommendation := 'REVIEW';
    ELSE
      lv_recommendation := 'EXCLUDE';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 40) ||
      ' rows=' || TO_CHAR(lv_total_rows) ||
      ' bad=' || TO_CHAR(lv_bad_rows) ||
      ' bad_pct=' || TO_CHAR(lv_bad_pct) ||
      ' recommendation=' || lv_recommendation
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Divide by zero encountered during diagnostic.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' );
END;
/

