DECLARE
  lv_year           SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2019-01-01';
  lv_county_like    VARCHAR2(100) := '%';
  lv_morb_desc      SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY.maternal_morbidity_desc%TYPE := 'Eclampsia';
  co_report_limit   CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed_rows   PLS_INTEGER := 0;
  lv_hint           VARCHAR2(200);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Mismatch check for year=' || TO_CHAR(lv_year, 'YYYY') || ', morbidity=' || lv_morb_desc || ', county like=' || lv_county_like);

  FOR rec IN (
    WITH overall AS (
      SELECT cn.county_of_residence AS county_of_residence,
             SUM(TO_NUMBER(TRIM(cn.births))) AS births_overall
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = lv_year
         AND cn.county_of_residence LIKE lv_county_like
         AND REGEXP_LIKE(TRIM(cn.births), '^[0-9]+(\.[0-9]+)?$')
       GROUP BY cn.county_of_residence
    ),
    morb_y AS (
      SELECT mm.county_of_residence AS county_of_residence,
             SUM(TO_NUMBER(TRIM(mm.births))) AS births_morb_y
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY mm
       WHERE mm.year = lv_year
         AND mm.county_of_residence LIKE lv_county_like
         AND mm.maternal_morbidity_desc = lv_morb_desc
         AND mm.maternal_morbidity_yn = 'Y'
         AND REGEXP_LIKE(TRIM(mm.births), '^[0-9]+(\.[0-9]+)?$')
       GROUP BY mm.county_of_residence
    )
    SELECT o.county_of_residence,
           o.births_overall,
           NVL(m.births_morb_y, 0) AS births_morb_y,
           ABS(o.births_overall - NVL(m.births_morb_y, 0)) AS abs_mismatch
      FROM overall o
      LEFT OUTER JOIN morb_y m
        ON m.county_of_residence = o.county_of_residence
     ORDER BY abs_mismatch DESC
  ) LOOP
    lv_printed_rows := lv_printed_rows + 1;

    IF rec.births_morb_y > rec.births_overall THEN
      lv_hint := 'IMPOSSIBLE: Y births > overall. Likely double-counting, wrong filters, or county name mismatch in morbidity table.';
    ELSIF rec.births_morb_y = 0 THEN
      lv_hint := 'No Y births recorded for this condition; verify coding/availability.';
    ELSE
      lv_hint := 'Review county mapping and condition definition consistency.';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      LPAD(TO_CHAR(lv_printed_rows), 2) || '. ' ||
      RPAD(rec.county_of_residence, 40) ||
      ' overall=' || TO_CHAR(rec.births_overall) ||
      ' morbY=' || TO_CHAR(rec.births_morb_y) ||
      ' mismatch=' || TO_CHAR(rec.abs_mismatch) ||
      ' hint=' || lv_hint
    );

    EXIT WHEN lv_printed_rows >= co_report_limit;
  END LOOP;

  IF lv_printed_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No counties found for the given filters/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' );
END;
/

