DECLARE
    gv_year       CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY.YEAR%TYPE := 2020;
    lv_infant_mortality NUMBER;
    gv_exists     NUMBER;
BEGIN
    -- Null input check
    IF gv_year IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Input Error: Year cannot be NULL.');
        RETURN;
    END IF;

    -- Inline execution to check if data exists for the year
    SELECT COUNT(*)
    INTO gv_exists
    FROM (
        SELECT YEAR
        FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY
        WHERE YEAR = gv_year
    );

    IF gv_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No data exists for the specified year.');
        RETURN;
    END IF;

    -- Fetch total infant mortality
        SELECT SUM(TO_NUMBER(INFANT_MORTALITY))
        INTO lv_infant_mortality
        FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY
        WHERE YEAR = gv_year;

        DBMS_OUTPUT.PUT_LINE('Year: ' || gv_year);
        DBMS_OUTPUT.PUT_LINE('Total Infant Mortality: ' || lv_infant_mortality);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;

