DECLARE
    gv_state CMS_MEDICARE.HOME_HEALTH_AGENCIES.STATE%TYPE := 'DC';
    co_threshold CONSTANT NUMBER := 1000;
    lv_episodes NUMBER;
    lv_count NUMBER;

    exp_invalid_number EXCEPTION;
    exp_null_input EXCEPTION;
    exp_no_data EXCEPTION;

    CURSOR cur_provider IS
        SELECT provider_id, agency_name, total_episodes_non_lupa
        FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES
        WHERE state = UPPER(gv_state)
        ORDER BY agency_name;

    rec_provider cur_provider%ROWTYPE;

BEGIN

    IF gv_state IS NULL THEN
        RAISE exp_null_input;
    END IF;

    SELECT COUNT(*)
    INTO lv_count
    FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES
    WHERE state = UPPER(gv_state);

    IF lv_count = 0 THEN
        RAISE exp_no_data;
    END IF;

    OPEN cur_provider;

    LOOP
        FETCH cur_provider INTO rec_provider;
        EXIT WHEN cur_provider%NOTFOUND;

        BEGIN

            IF REGEXP_LIKE(rec_provider.total_episodes_non_lupa,'^\d+(\.\d+)?$') THEN
                lv_episodes := TO_NUMBER(rec_provider.total_episodes_non_lupa);
            ELSE
                RAISE exp_invalid_number;
            END IF;

            IF lv_episodes > co_threshold THEN
                DBMS_OUTPUT.PUT_LINE(
                    rec_provider.provider_id || ' | ' ||
                    rec_provider.agency_name || ' | Episodes: ' ||
                    lv_episodes
                );
            END IF;

        EXCEPTION
            WHEN exp_invalid_number THEN
                DBMS_OUTPUT.PUT_LINE(
                'Root Cause Analysis: Invalid numeric value for provider '
                || rec_provider.provider_id);
        END;

    END LOOP;

    CLOSE cur_provider;

EXCEPTION
    WHEN exp_null_input THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause Analysis: State input missing.');

    WHEN exp_no_data THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause Analysis: No providers exist for requested state.');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;

