CREATE OR REPLACE PROCEDURE SP_GET_HOSPITAL_DETAILS_3 (
    -- p_provider_id: Input identifier for the hospital search
    p_provider_id IN CMS_MEDICARE.HOSPITAL_GENERAL_INFO.provider_id%TYPE
) AS
    -- [Memory & Type] [Data Synchronization]
    -- lv_hospital_name: Container for the facility name
    lv_provider_id  CMS_MEDICARE.HOSPITAL_GENERAL_INFO.provider_id%TYPE := '100001';
    lv_hospital_name CMS_MEDICARE.HOSPITAL_GENERAL_INFO.hospital_name%TYPE;
    lv_city          CMS_MEDICARE.HOSPITAL_GENERAL_INFO.city%TYPE;
    lv_state         CMS_MEDICARE.HOSPITAL_GENERAL_INFO.state%TYPE;
BEGIN
    -- [Validation] [Control Flow]
    -- Ensuring the input is provided before starting the search
    lv_provider_id:=p_provider_id;
    IF lv_provider_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Provider ID cannot be NULL.');
        RETURN;
    END IF;

    -- [Data Retrieval]
    -- Fetching details from UPPERCASE table using lowercase columns
    SELECT hospital_name, 
           city, 
           state
    INTO   lv_hospital_name, 
           lv_city, 
           lv_state
    FROM   CMS_MEDICARE.HOSPITAL_GENERAL_INFO
    WHERE  provider_id = lv_provider_id;

    -- [Inline Execution]
    -- Displaying the gathered information in a clean report
    DBMS_OUTPUT.PUT_LINE('--- Hospital Profile Analysis ---');
    DBMS_OUTPUT.PUT_LINE('Provider ID : ' || lv_provider_id);
    DBMS_OUTPUT.PUT_LINE('Facility    : ' || lv_hospital_name);
    DBMS_OUTPUT.PUT_LINE('Location    : ' || lv_city || ', ' || lv_state);

    -- Success confirmation
    DBMS_OUTPUT.PUT_LINE('Status : Record retrieved successfully.');

EXCEPTION
    -- [Exception Handling] [Root Cause Analysis]
    -- Specifically handling cases where the ID does not exist
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause: Hospital provider ID not found.');

    -- Handling any other unexpected system issues
    WHEN OTHERS THEN 
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred'); 
END;
/

DECLARE
    p_player_id VARCHAR2(100) := 'kimbage01';
    v_games NUMBER(38);
    v_ab    NUMBER(38);
    v_result VARCHAR2(4000);
BEGIN
    -- Input validation
    IF p_player_id IS NULL THEN
        v_result := 'Player id null NOT FOUND.';

    ELSE
        -- Data retrieval
        SELECT g, ab
        INTO v_games, v_ab
        FROM baseball.batting
        WHERE player_id = p_player_id
        AND ROWNUM = 1;

        -- Control flow
        IF v_ab IS NULL THEN
            v_result := 'Player ' || p_player_id || ' has no at-bat data.';
        ELSE
            v_result := 'Player ID:' || p_player_id || CHR(10) ||
                        'played: ' || v_games || CHR(10) ||
                        'games with: ' || v_ab || ' at-bats.';
        END IF;
    END IF;

    DBMS_OUTPUT.PUT_LINE(v_result);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Player id: ' || p_player_id || ' no data found');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;

