CREATE OR REPLACE PROCEDURE sp_station_validate_input (
    p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.NAME%TYPE
)
IS
    lv_station_count NUMBER;
BEGIN
    -- Validate input
    IF p_station_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Validation Warning: No stations found for input: ' || p_station_name);
        RETURN;
    END IF;

    -- Count matching stations
    SELECT COUNT(*) INTO lv_station_count
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS
     WHERE NAME LIKE '%' || p_station_name || '%';

    IF lv_station_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Validation Warning: No stations found for input: ' || p_station_name);
    ELSE
        DBMS_OUTPUT.PUT_LINE('Total stations found: ' || lv_station_count);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_station_validate_input;
/

CREATE OR REPLACE PROCEDURE sp_station_trip_summary (
    p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.NAME%TYPE
)
IS
    lv_station_count NUMBER;

    -- Cursor for matching stations
    CURSOR cur_station IS
        SELECT STATION_ID, NAME, DOCKCOUNT, LATITUDE, LONGITUDE
          FROM SAN_FRANCISCO.BIKESHARE_STATIONS
         WHERE NAME LIKE '%' || p_station_name || '%'
		 ORDER BY STATION_ID;

    rec_station cur_station%ROWTYPE;

    -- Local variables for trips
    lv_total_trips NUMBER;
    lv_last_trip   TIMESTAMP;

BEGIN
    -- Input validation
    IF p_station_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Validation Warning: No stations found for input: ' || p_station_name);
        RETURN;
    END IF;

    -- Count matching stations
    SELECT COUNT(*) INTO lv_station_count
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS
     WHERE NAME LIKE '%' || p_station_name || '%';

    IF lv_station_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Validation Warning: No stations found for input: ' || p_station_name);
        RETURN;
    ELSE
        DBMS_OUTPUT.PUT_LINE('Total stations found: ' || lv_station_count);
    END IF;

    -- Process each station
    OPEN cur_station;
    LOOP
        FETCH cur_station INTO rec_station;
        EXIT WHEN cur_station%NOTFOUND;

        DBMS_OUTPUT.PUT_LINE('Processing Station: ' || rec_station.NAME ||
                             ' (ID: ' || rec_station.STATION_ID ||
                             ', Docks: ' || rec_station.DOCKCOUNT ||
                             ', Lat: ' || rec_station.LATITUDE ||
                             ', Lon: ' || rec_station.LONGITUDE || ')');

        -- Fetch trips stats
        SELECT COUNT(*), MAX(START_DATE)
          INTO lv_total_trips, lv_last_trip
          FROM SAN_FRANCISCO.BIKESHARE_TRIPS
         WHERE START_STATION_ID = rec_station.STATION_ID;

        IF lv_total_trips = 0 THEN
            DBMS_OUTPUT.PUT_LINE('Trips info missing. Root cause: No trips for station ' || rec_station.STATION_ID);
        ELSE
            DBMS_OUTPUT.PUT_LINE('Total Trips Started: ' || lv_total_trips);
            DBMS_OUTPUT.PUT_LINE('Most Recent Trip Start: ' || NVL(TO_CHAR(lv_last_trip,'YYYY-MM-DD HH24:MI:SS'),'N/A'));
        END IF;

    END LOOP;
    CLOSE cur_station;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END sp_station_trip_summary;
/

CREATE OR REPLACE PROCEDURE sp_bikeshare_station_trips_clean (
    p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.NAME%TYPE
)
IS
    -- Local variables
    lv_station_count NUMBER;

    -- Cursor to fetch all matching stations
    CURSOR cur_station IS
        SELECT STATION_ID, NAME, DOCKCOUNT, LATITUDE, LONGITUDE
          FROM SAN_FRANCISCO.BIKESHARE_STATIONS
         WHERE NAME LIKE '%' || p_station_name || '%'
		 ORDER BY STATION_ID;

    rec_station cur_station%ROWTYPE;

    -- Trip stats
    lv_total_trips NUMBER;
    lv_last_trip   TIMESTAMP;

BEGIN
    ----------------------------
    -- Step 1: Validate input
    ----------------------------
    IF p_station_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('[Validation Error] Station name input cannot be null.');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('[Info] Validating stations for input: ' || p_station_name);

    ----------------------------
    -- Step 2: Count matching stations
    ----------------------------
    SELECT COUNT(*) INTO lv_station_count
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS
     WHERE NAME LIKE '%' || p_station_name || '%';

    IF lv_station_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('[Root Cause] No stations found for input: ' || p_station_name);
        RETURN;
    ELSE
        DBMS_OUTPUT.PUT_LINE('[Info] Total stations found: ' || lv_station_count);
    END IF;

    ----------------------------
    -- Step 3: Process each station
    ----------------------------
    OPEN cur_station;
    LOOP
        FETCH cur_station INTO rec_station;
        EXIT WHEN cur_station%NOTFOUND;

        DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
        DBMS_OUTPUT.PUT_LINE('[Processing Station] ' || rec_station.NAME ||
                             ' (ID: ' || rec_station.STATION_ID ||
                             ', Docks: ' || rec_station.DOCKCOUNT ||
                             ', Lat: ' || rec_station.LATITUDE ||
                             ', Lon: ' || rec_station.LONGITUDE || ')');

        -- Step 3a: Fetch trip statistics
        SELECT COUNT(*), MAX(START_DATE)
          INTO lv_total_trips, lv_last_trip
          FROM SAN_FRANCISCO.BIKESHARE_TRIPS
         WHERE START_STATION_ID = rec_station.STATION_ID;

        -- Step 3b: Analyze trips
        IF lv_total_trips = 0 THEN
            DBMS_OUTPUT.PUT_LINE('[Root Cause] Trips info missing: No trips recorded for station ID ' || rec_station.STATION_ID);
        ELSE
            DBMS_OUTPUT.PUT_LINE('[Trip Summary] Total Trips Started: ' || lv_total_trips);
            DBMS_OUTPUT.PUT_LINE('[Trip Summary] Most Recent Trip Start: ' || TO_CHAR(lv_last_trip,'YYYY-MM-DD HH24:MI:SS'));
        END IF;

    END LOOP;
    CLOSE cur_station;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END sp_bikeshare_station_trips_clean;
