DECLARE
    -- [Memory & Type] [Data Synchronization]
    lv_target_code    WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE := 'USA'; 
    lv_target_year    WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE          := '2020'; 

    -- Variables to hold header info
    lv_long_name      WORLD_BANK_WDI.COUNTRY_SUMMARY.long_name%TYPE; 
    lv_region         WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE; 

    lv_counter        NUMBER := 0;

    -- [Cursors] [Inline Execution]
    -- Subquery isolates the specific indicator set for the target country/year
    CURSOR cur_gdp IS
        SELECT indicator_name, value
        FROM   (
            SELECT indicator_name, value
            FROM   WORLD_BANK_WDI.INDICATORS_DATA
            WHERE  country_code = lv_target_code
              AND  year         = lv_target_year
              AND  indicator_name LIKE 'GDP%'
        )
        ORDER BY indicator_name;
BEGIN
    -- [RCA Logging] Initial Start
    DBMS_OUTPUT.PUT_LINE('RCA LOG -> START: Initializing Economic Data Analysis for ' || lv_target_code);

    -- [Data Retrieval] [Inline Execution]
    -- Validating existence and capturing metadata within an isolated result set
    SELECT long_name, region
    INTO   lv_long_name, lv_region
    FROM   (
        SELECT a.long_name, a.region
        FROM   WORLD_BANK_WDI.COUNTRY_SUMMARY a
        INNER JOIN WORLD_BANK_WDI.INDICATORS_DATA b ON a.country_code = b.country_code
        WHERE  a.country_code = lv_target_code
          AND  b.year         = lv_target_year
          AND  b.indicator_name LIKE 'GDP%'
    )
    WHERE ROWNUM = 1;

    -- [Output] Header
    DBMS_OUTPUT.PUT_LINE('Region    : ' || lv_region);
    DBMS_OUTPUT.PUT_LINE('Analysis for ' || lv_long_name || ' Year ' || lv_target_year || ' completed successfully.');

    -- [Iterative] [Control Flow]
    -- Processing each GDP indicator from the pre-filtered inline cursor
    FOR rec IN cur_gdp LOOP
        lv_counter := lv_counter + 1;
        DBMS_OUTPUT.PUT_LINE(lv_counter || '. ' || rec.indicator_name || ': ' || rec.value);
    END LOOP;

    -- [RCA Logging] Process Completion
    DBMS_OUTPUT.PUT_LINE('RCA LOG -> END: Economic data audit successfully finalized for ' || lv_target_code);

EXCEPTION
    -- [Exception Handling] [Root Cause Analysis]
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause: No GDP data found for ' || lv_target_code || ' in year ' || lv_target_year || '.');

    WHEN OTHERS THEN 
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred'); 
END;

