        NVL(lv_last_enc_class, 'NULL'));
    DBMS_OUTPUT.PUT_LINE('PATIENT_END');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No Record found');
        DBMS_OUTPUT.PUT_LINE('PATIENT_END');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
