CREATE OR REPLACE PACKAGE pkg_patient_health AS

    FUNCTION sf_calculate_age(
        p_birthdate IN DATE
    ) RETURN NUMBER;

    PROCEDURE sp_get_demographics(
        p_patient_id IN VARCHAR2
    );

    PROCEDURE sp_get_full_profile(
        p_patient_id IN VARCHAR2
    );

