/

CREATE OR REPLACE PACKAGE BODY pkg_patient_health AS

    FUNCTION sf_calculate_age(
        p_birthdate IN DATE
    ) RETURN NUMBER IS
        lv_age NUMBER;
    BEGIN
        IF p_birthdate IS NULL THEN
            RETURN NULL;
        END IF;

        lv_age := FLOOR(MONTHS_BETWEEN(SYSDATE, p_birthdate) / 12);
        RETURN lv_age;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN NULL;
    END sf_calculate_age;

    PROCEDURE sp_get_demographics(
        p_patient_id IN VARCHAR2
    ) IS
        lv_first     SYNTHEA.PATIENTS.first%TYPE;
        lv_last      SYNTHEA.PATIENTS.last%TYPE;
        lv_gender    SYNTHEA.PATIENTS.gender%TYPE;
        lv_birthdate SYNTHEA.PATIENTS.birthdate%TYPE;
        lv_city      SYNTHEA.PATIENTS.city%TYPE;
        lv_state     SYNTHEA.PATIENTS.state%TYPE;
        lv_age       NUMBER;

    BEGIN
        DBMS_OUTPUT.PUT_LINE('PATIENT_START');

        IF p_patient_id IS NULL THEN
            DBMS_OUTPUT.PUT_LINE('No Record found');
            DBMS_OUTPUT.PUT_LINE('PATIENT_END');
            RETURN;
        END IF;

        BEGIN
            SELECT first,
                   last,
                   gender,
                   birthdate,
                   city,
                   state
              INTO lv_first,
                   lv_last,
                   lv_gender,
                   lv_birthdate,
                   lv_city,
                   lv_state
              FROM SYNTHEA.PATIENTS
             WHERE id = p_patient_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('No Record found');
                DBMS_OUTPUT.PUT_LINE('PATIENT_END');
                RETURN;
        END;

        lv_age := sf_calculate_age(lv_birthdate);

        DBMS_OUTPUT.PUT_LINE('PATIENT_ID='  || p_patient_id);
        DBMS_OUTPUT.PUT_LINE('FIRST_NAME='  || NVL(lv_first, 'NULL'));
        DBMS_OUTPUT.PUT_LINE('LAST_NAME='   || NVL(lv_last, 'NULL'));
        DBMS_OUTPUT.PUT_LINE('GENDER='      || NVL(lv_gender, 'NULL'));
        DBMS_OUTPUT.PUT_LINE('BIRTHDATE='   ||
            TO_CHAR(lv_birthdate, 'YYYY-MM-DD'));
        DBMS_OUTPUT.PUT_LINE('AGE_YEARS='   || TO_CHAR(NVL(lv_age, 0)));
        DBMS_OUTPUT.PUT_LINE('CITY='        || NVL(lv_city, 'NULL'));
        DBMS_OUTPUT.PUT_LINE('STATE='       || NVL(lv_state, 'NULL'));
        DBMS_OUTPUT.PUT_LINE('PATIENT_END');

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No Record found');
            DBMS_OUTPUT.PUT_LINE('PATIENT_END');
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
    END sp_get_demographics;

    PROCEDURE sp_get_full_profile(
        p_patient_id IN VARCHAR2
