CREATE OR REPLACE FUNCTION sf_region_sales_summary (
    p_region VARCHAR2
)
RETURN VARCHAR2
IS
    v_sales NUMBER;
    v_trans NUMBER;
BEGIN

    -- CONTROL FLOW
    IF p_region IS NULL THEN
        RETURN 'Region null not found';
    END IF;

    -- DATA RETRIEVAL using INLINE VIEW
    SELECT SUM(sales), SUM(transactions)
    INTO v_sales, v_trans
    FROM (
        SELECT sales, transactions
        FROM bank_sales_trading.cleaned_weekly_sales
        WHERE region = p_region
    );

    IF v_sales IS NULL AND v_trans IS NULL THEN
        RETURN 'Region: ' || p_region || ' no data found';
    END IF;

    RETURN 'Region: ' || p_region || chr(10) ||
           'Total Sales: ' || v_sales || chr(10) ||
           'Total Transactions: ' || v_trans;

-- EXCEPTION HANDLING
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_region_sales_summary;
/

CREATE OR REPLACE FUNCTION sf_region_platform_analysis (
    p_region VARCHAR2
)
RETURN VARCHAR2
IS
    v_sales NUMBER;
    v_trans NUMBER;
    v_avg   NUMBER;
BEGIN

    -- CONTROL FLOW
    IF p_region IS NULL THEN
        RETURN 'Region cannot be null';
    END IF;

    -- DATA RETRIEVAL using INLINE VIEW
    SELECT SUM(sales), SUM(transactions), AVG(avg_transaction)
    INTO v_sales, v_trans, v_avg
    FROM (
        SELECT sales, transactions, avg_transaction
        FROM bank_sales_trading.cleaned_weekly_sales
        WHERE region = p_region
    );

    IF v_sales IS NULL AND v_trans IS NULL THEN
        RETURN 'Region: ' || p_region || ' no data found';
    END IF;

    RETURN 'Region: ' || p_region ||CHR(10)||
           'Total Sales: ' || v_sales ||CHR(10)||
           'Total Transactions: ' || v_trans ||CHR(10)||
           'Avg Transaction: ' || ROUND(v_avg,2);

-- EXCEPTION HANDLING
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_region_platform_analysis;
/

DECLARE
  lv_state CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE := 'TX';
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_count PLS_INTEGER;
BEGIN
  SELECT COUNT(*)
    INTO lv_count
    FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
   WHERE hha.state = lv_state
     AND hha.total_episodes_non_lupa IS NOT NULL;

  IF lv_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  ELSE
    FOR rec_agency IN (
      SELECT hha.provider_id,
             hha.agency_name,
             hha.city,
             TO_NUMBER(hha.total_episodes_non_lupa) AS total_episodes
        FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
       WHERE hha.state = lv_state
         AND hha.total_episodes_non_lupa IS NOT NULL
       ORDER BY TO_NUMBER(hha.total_episodes_non_lupa) DESC, hha.provider_id
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        rec_agency.provider_id || ' | ' || rec_agency.agency_name || ' | ' || rec_agency.city || ' | episodes=' || rec_agency.total_episodes
      );
    END LOOP;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: numeric conversion failed for TOTAL_EPISODES_NON_LUPA.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ');
