   lv_trip_date    DATE;
   lv_station_name VARCHAR2(100);
   lv_trip_count   NUMBER := 0;
BEGIN
   DBMS_OUTPUT.PUT_LINE('Anonymous Block: station daily summary');
   lv_station_id := '1';
   lv_trip_date  := DATE '2026-03-17';

   IF lv_station_id IS NULL OR TRIM(lv_station_id) = '' THEN
      DBMS_OUTPUT.PUT_LINE('ERROR: Station ID cannot be NULL or blank.');
      RETURN;
   END IF;

   IF lv_trip_date IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('ERROR: Trip date cannot be NULL.');
      RETURN;
   END IF;

   SELECT name
     INTO lv_station_name
     FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO
    WHERE station_id = lv_station_id
      AND ROWNUM = 1;

   SELECT COUNT(*)
     INTO lv_trip_count
     FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS
    WHERE start_station_id = lv_station_id
      AND TRUNC(CAST(start_date AS DATE)) = TRUNC(lv_trip_date);

   DBMS_OUTPUT.PUT_LINE('Station ID: ' || lv_station_id);
   DBMS_OUTPUT.PUT_LINE('Station Name: ' || NVL(lv_station_name, ''));
   DBMS_OUTPUT.PUT_LINE('Trip Date: ' || TO_CHAR(lv_trip_date, 'YYYY-MM-DD'));
   DBMS_OUTPUT.PUT_LINE('Total Trips Started: ' || lv_trip_count);

