CREATE OR REPLACE PACKAGE BODY pkg_station_daily IS
   PROCEDURE sp_print_station_daily(p_station_id VARCHAR2, p_trip_date DATE) IS
      lv_station_name VARCHAR2(100);
      lv_start_count  NUMBER := 0;
      lv_end_count    NUMBER := 0;
   BEGIN
      IF p_station_id IS NULL OR TRIM(p_station_id) = '' THEN
         DBMS_OUTPUT.PUT_LINE('ERROR: Station ID cannot be NULL or blank.');
         RETURN;
      END IF;

      IF p_trip_date IS NULL THEN
         DBMS_OUTPUT.PUT_LINE('ERROR: Trip date cannot be NULL.');
         RETURN;
      END IF;

      IF TRUNC(p_trip_date) > DATE '2026-03-17' THEN
         DBMS_OUTPUT.PUT_LINE('ERROR: Trip date cannot be in the future.');
         RETURN;
      END IF;

      SELECT name
        INTO lv_station_name
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO
       WHERE station_id = p_station_id
         AND ROWNUM = 1;

      SELECT COUNT(*)
        INTO lv_start_count
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS
       WHERE start_station_id = p_station_id
         AND TRUNC(CAST(start_date AS DATE)) = TRUNC(p_trip_date);

      SELECT cnt
        INTO lv_end_count
        FROM (
               SELECT COUNT(*) AS cnt
                 FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS
                WHERE end_station_id = p_station_id
                  AND TRUNC(CAST(end_date AS DATE)) = TRUNC(p_trip_date)
             );

      DBMS_OUTPUT.PUT_LINE('Station ID: ' || p_station_id);
      DBMS_OUTPUT.PUT_LINE('Station Name: ' || NVL(lv_station_name, ''));
      DBMS_OUTPUT.PUT_LINE('Trip Date: ' || TO_CHAR(p_trip_date, 'YYYY-MM-DD'));
      DBMS_OUTPUT.PUT_LINE('Total Trips Started: ' || lv_start_count);
      DBMS_OUTPUT.PUT_LINE('Total Trips Ended: ' || lv_end_count);

   EXCEPTION
      WHEN NO_DATA_FOUND THEN
         DBMS_OUTPUT.PUT_LINE('ERROR: Station ID not found.');
      WHEN OTHERS THEN
         DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
   END sp_print_station_daily;
END pkg_station_daily;
