CREATE OR REPLACE PROCEDURE sp_get_bowler_ball_details (
    p_bowler_id IN NUMBER,
    p_match_id  IN NUMBER,
    p_innings   IN NUMBER
) IS
    v_dummy      NUMBER;
    v_ball_count NUMBER;
    v_over_count NUMBER;
BEGIN

    -- NULL validation separately
    IF p_bowler_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Bowler ID NULL not found');
    END IF;

    IF p_match_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Match ID NULL not found');
    END IF;

    IF p_innings IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Innings NULL not found');
    END IF;

    IF p_bowler_id IS NOT NULL 
       AND p_match_id IS NOT NULL 
       AND p_innings IS NOT NULL THEN

        -- Print input parameters
        DBMS_OUTPUT.PUT_LINE('Bowler ID: ' || p_bowler_id);
        DBMS_OUTPUT.PUT_LINE('Match ID: ' || p_match_id);
        DBMS_OUTPUT.PUT_LINE('Innings: ' || p_innings);

        -- Check if data exists
        SELECT 1
        INTO v_dummy
        FROM ipl.ball_by_ball
        WHERE bowler = p_bowler_id
        AND match_id = p_match_id
        AND innings_no = p_innings
        AND ROWNUM = 1;

        -- Business logic
        SELECT COUNT(ball_id), COUNT(DISTINCT over_id)
        INTO v_ball_count, v_over_count
        FROM ipl.ball_by_ball
        WHERE bowler = p_bowler_id
        AND match_id = p_match_id
        AND innings_no = p_innings;

        -- Step-by-step output
        DBMS_OUTPUT.PUT_LINE('Bowling Details');
        DBMS_OUTPUT.PUT_LINE('Total Balls Bowled: ' || v_ball_count);
        DBMS_OUTPUT.PUT_LINE('Total Overs Bowled: ' || v_over_count);

    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No data found for Bowler ' || p_bowler_id ||
                             ' in Match ' || p_match_id ||
                             ' in Innings ' || p_innings);

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END sp_get_bowler_ball_details;
