DECLARE
    -- [Input] Product to check
    p_name         ADVENTUREWORKS.PRODUCT.NAME%TYPE := 'Adjustable Race';

    -- [Local Variables]
    lv_prod_num    ADVENTUREWORKS.PRODUCT.PRODUCTNUMBER%TYPE;
    lv_safety      ADVENTUREWORKS.PRODUCT.SAFETYSTOCKLEVEL%TYPE;
    lv_reorder     ADVENTUREWORKS.PRODUCT.REORDERPOINT%TYPE;
    lv_diff        NUMBER;
    lv_status      VARCHAR2(20);
BEGIN
    DBMS_OUTPUT.PUT_LINE('--- Stock Health Check: ' || p_name || ' ---');

    -- Inline Execution using a subquery in the FROM clause
    SELECT PRODUCTNUMBER, 
           SAFETYSTOCKLEVEL, 
           REORDERPOINT, 
           (SAFETYSTOCKLEVEL - REORDERPOINT),
           CASE 
               WHEN (SAFETYSTOCKLEVEL - REORDERPOINT) >= 0 THEN 'Healthy'
               ELSE 'Critical'
           END
    INTO   lv_prod_num, lv_safety, lv_reorder, lv_diff, lv_status
    FROM (
        SELECT PRODUCTNUMBER, SAFETYSTOCKLEVEL, REORDERPOINT
        FROM ADVENTUREWORKS.PRODUCT
