CREATE OR REPLACE PROCEDURE GET_PRODUCT_AND_CATEGORY_STATUS_5 (
    p_name IN ADVENTUREWORKS.PRODUCT.NAME%TYPE := 'Adjustable Race'
) IS
    -- Local variables for data storage
    lv_prod_num    ADVENTUREWORKS.PRODUCT.PRODUCTNUMBER%TYPE;
    lv_cat_name    VARCHAR2(100); 
    lv_safety      ADVENTUREWORKS.PRODUCT.SAFETYSTOCKLEVEL%TYPE;
    lv_reorder     ADVENTUREWORKS.PRODUCT.REORDERPOINT%TYPE;
    lv_status      VARCHAR2(20);
BEGIN
    -- NULL Input Validation
    IF p_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Validation Error: Product name cannot be null.');
        RETURN; 
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- Detailed Stock and Category Check: ' || p_name || ' ---');

    -- Inline Execution using a Join inside the FROM clause (Inline View)
    SELECT PRODUCTNUMBER, 
           CATEGORY_NAME,
           SAFETYSTOCKLEVEL, 
           REORDERPOINT, 
           CASE 
               WHEN (SAFETYSTOCKLEVEL - REORDERPOINT) >= 0 THEN 'Healthy'
               ELSE 'Critical'
           END
    INTO   lv_prod_num, lv_cat_name, lv_safety, lv_reorder, lv_status
    FROM (
        SELECT p.PRODUCTNUMBER, 
               c.NAME as CATEGORY_NAME, 
               p.SAFETYSTOCKLEVEL, 
               p.REORDERPOINT
        FROM ADVENTUREWORKS.PRODUCT p
        LEFT JOIN ADVENTUREWORKS.PRODUCTCATEGORY c 
               ON p.PRODUCTSUBCATEGORYID = c.PRODUCTCATEGORYID
        WHERE p.NAME = p_name
    );

    -- Output results
    DBMS_OUTPUT.PUT_LINE('Product Number   : ' || lv_prod_num);
    DBMS_OUTPUT.PUT_LINE('Category         : ' || NVL(lv_cat_name, 'None/Unassigned'));
    DBMS_OUTPUT.PUT_LINE('Safety Level     : ' || lv_safety);
    DBMS_OUTPUT.PUT_LINE('Reorder Point    : ' || lv_reorder);
    DBMS_OUTPUT.PUT_LINE('Inventory Status : ' || lv_status);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Error: No product found named: ' || p_name);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END;
/

