CREATE OR REPLACE FUNCTION sf_fn_series_area_analysis(
    p_area VARCHAR2
)
RETURN VARCHAR2
IS
    v_count NUMBER;
    v_first_year VARCHAR2(4);
    v_industry_count NUMBER;
BEGIN

    -- INPUT VALIDATION
    IF p_area IS NULL THEN
        RETURN 'Area code null not found';
    END IF;

    -- DATA RETRIEVAL using INLINE VIEW
    SELECT COUNT(*), MIN(begin_year)
    INTO v_count, v_first_year
    FROM (
        SELECT begin_year
        FROM bls.wm_series
        WHERE area_code = p_area
    );

    -- INLINE EXECUTION using INLINE VIEW
    SELECT COUNT(DISTINCT industry_code)
    INTO v_industry_count
    FROM (
        SELECT industry_code
        FROM bls.wm_series
        WHERE area_code = p_area
    );

    -- CONTROL FLOW
    IF v_count = 0 THEN
        RETURN 'Area code: '||p_area||' '||'No data found';
    END IF;

    RETURN 'Area: '||p_area||chr(10)||
           'Total Series: '||v_count||chr(10)||
           'First Data Year: '||v_first_year||chr(10)||
           'Industries Covered: '||v_industry_count;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_fn_series_area_analysis;
/

CREATE OR REPLACE FUNCTION sf_fn_series_industry_summary(
    p_industry VARCHAR2
)
RETURN VARCHAR2
IS
    v_total NUMBER := 0;
    v_start VARCHAR2(4);
    v_end   VARCHAR2(4);
    v_types NUMBER := 0;
    v_area_count NUMBER := 0;
BEGIN

    -- INPUT VALIDATION
    IF p_industry IS NULL THEN
        RETURN 'Industry code NULL not found';
    END IF;

    -- DATA RETRIEVAL using INLINE VIEW
    SELECT NVL(COUNT(*),0),
           MIN(begin_year),
           MAX(end_year),
           NVL(COUNT(DISTINCT datatype_code),0)
    INTO v_total, v_start, v_end, v_types
    FROM (
        SELECT begin_year, end_year, datatype_code
        FROM bls.wm_series
        WHERE industry_code = p_industry
    );

    -- INLINE EXECUTION using INLINE VIEW
    SELECT NVL(COUNT(DISTINCT area_code),0)
    INTO v_area_count
    FROM (
        SELECT area_code
        FROM bls.wm_series
        WHERE industry_code = p_industry
    );

    -- CONTROL FLOW
    IF v_total = 0 THEN
        RETURN 'Industry code: '||p_industry||' '||'No data found';
    END IF;

    v_start := NVL(v_start,'N/A');
    v_end   := NVL(v_end,'N/A');

    RETURN 'Industry code: '||p_industry||chr(10)||
           'Series Count: '||v_total||chr(10)||
           'From '||v_start||' To '||v_end||chr(10)||
           'Datatypes: '||v_types||chr(10)||
           'Areas Covered: '||v_area_count;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_fn_series_industry_summary;
