CREATE OR REPLACE FUNCTION sf_get_country_population(p_city_id NUMBER)
RETURN VARCHAR2
IS
    v_total_pop NUMBER;
    v_result    VARCHAR2(4000);
    v_country   VARCHAR2(2);
BEGIN
    IF p_city_id IS NULL THEN
        RETURN 'City id null not found.';
    END IF;

    -- Get country of the city
    SELECT country_code_2
    INTO v_country
    FROM city_legislation.cities
    WHERE city_id = p_city_id;

    -- Aggregate data
    SELECT
        LISTAGG(city_name ||
            CASE
                WHEN population IS NULL THEN '(Population not recorded)'
                ELSE '(' || population || ')'
            END, ', ') WITHIN GROUP (ORDER BY city_name),
        SUM(NVL(population,0))
    INTO v_result, v_total_pop
    FROM city_legislation.cities
    WHERE country_code_2 = v_country;

    IF v_result IS NULL THEN
        RAISE NO_DATA_FOUND;
    END IF;

    RETURN 'City ID:' || p_city_id ||CHR(10)||
           'Country ' || v_country || ' cities: ' || v_result ||
           '. Total population: ' || v_total_pop;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'City ID:' || p_city_id || ' no data found';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_country_population;
/

