CREATE OR REPLACE FUNCTION sf_fn_match_insights (
    p_match_id NUMBER
)
RETURN VARCHAR2
IS
    v_decision VARCHAR2(20);
    v_win_type VARCHAR2(20);
    v_result   VARCHAR2(200);
BEGIN
    -- INPUT VALIDATION
    IF p_match_id IS NULL THEN
        RETURN 'Match ID null NOT FOUND';
    END IF;

    -- Call previous function
    v_result := sf_fn_match_summary(p_match_id);

    SELECT toss_decision, win_type
    INTO v_decision, v_win_type
    FROM ipl.match
    WHERE match_id = p_match_id;

    IF v_win_type = 'RUNS' THEN
        v_result := v_result || CHR(10) || 'Victory Type: Big Score Defense';
    ELSE
        v_result := v_result || CHR(10) || 'Victory Type: Successful Chase';
    END IF;

    RETURN v_result || CHR(10)|| 'Toss Decision: '||v_decision;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Match ID: ' || p_match_id || ' no data found';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';        
END sf_fn_match_insights;
/

