DECLARE
  p_patient_id SYNTHEA.PATIENTS.id%TYPE;

  co_report_limit CONSTANT NUMBER := 15; -- Limit output for report readability

  lv_exists   NUMBER;
  lv_rownum   NUMBER := 0;
BEGIN
  -- Pick a deterministic patient to demonstrate the report.
  SELECT MIN(p.id)
    INTO p_patient_id
    FROM SYNTHEA.PATIENTS p;

  -- Validate patient exists (defensive check in case table is empty).
  SELECT COUNT(*)
    INTO lv_exists
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  IF lv_exists = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Patient not found.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT e.id AS encounter_id,
           e.encounterclass,
           e.description,
           e.start_timestamp AS start_ts,
           e.stop_timestamp  AS stop_ts,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
     ORDER BY e.start_timestamp DESC
  ) LOOP
    lv_rownum := lv_rownum + 1;
    EXIT WHEN lv_rownum > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Encounter ' || TO_CHAR(lv_rownum) || ': ' || rec.encounter_id || ' | ' || rec.encounterclass ||
      ' | ' || rec.description || ' | ' || TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' -> ' || TO_CHAR(rec.stop_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | total_claim_cost=' || TO_CHAR(rec.total_claim_cost)
    );
  END LOOP;

  IF lv_rownum = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient ' || p_patient_id || '.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Patient not found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

