DECLARE
  p_patient_id SYNTHEA.PATIENTS.id%TYPE;

  lv_encounter_id      SYNTHEA.ENCOUNTERS.id%TYPE;
  lv_total_claim_cost  SYNTHEA.ENCOUNTERS.total_claim_cost%TYPE;
  lv_category          VARCHAR2(10);

  -- Simple thresholds for operational triage
  co_high_cost   CONSTANT NUMBER := 10000;
  co_medium_cost CONSTANT NUMBER := 2000;
BEGIN
  -- Deterministic patient selection for repeatable results.
  SELECT MIN(p.id)
    INTO p_patient_id
    FROM SYNTHEA.PATIENTS p;

  -- Pick the single most expensive encounter for that patient.
  SELECT e.id,
         e.total_claim_cost
    INTO lv_encounter_id,
         lv_total_claim_cost
    FROM (
      SELECT e.id,
             e.total_claim_cost
        FROM SYNTHEA.ENCOUNTERS e
       WHERE e.patient = p_patient_id
       ORDER BY e.total_claim_cost DESC, e.id
    ) e
   WHERE ROWNUM = 1;

  IF lv_total_claim_cost >= co_high_cost THEN
    lv_category := 'HIGH';
  ELSIF lv_total_claim_cost >= co_medium_cost THEN
    lv_category := 'MEDIUM';
  ELSE
    lv_category := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Top encounter: ' || lv_encounter_id || ' | total_claim_cost=' || TO_CHAR(lv_total_claim_cost) ||
    ' | category=' || lv_category
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

