question:
Build a quick console report to help operations understand which bike share stations are most frequently used as trip start points. For a given landmark (e.g., 'San Francisco'), show up to 15 stations with the highest number of starts, including the station name and the start count. If the caller passes NULL for landmark, default to 'San Francisco'. If no trips are found for the landmark, print a clear message.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Top start stations for landmark: ' || lv_landmark);
DBMS_OUTPUT.PUT_LINE(RPAD(rec.station_name, 45) || ' | starts=' || rec.start_cnt);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := 'San Francisco';
  lv_input_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := NULL;

  ln_total_rows PLS_INTEGER := 0;
BEGIN
  -- Default landmark when caller provides NULL
  lv_landmark := NVL(lv_input_landmark, 'San Francisco');

  DBMS_OUTPUT.PUT_LINE('Top start stations for landmark: ' || lv_landmark);

  FOR rec IN (
    SELECT *
    FROM (
      SELECT s.name AS station_name,
             COUNT(*) AS start_cnt
        FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
        INNER JOIN SAN_FRANCISCO.BIKESHARE_STATIONS s
          ON s.station_id = t.start_station_id
       WHERE s.landmark = lv_landmark
       GROUP BY s.name
       ORDER BY COUNT(*) DESC, s.name
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    ln_total_rows := ln_total_rows + 1;
    DBMS_OUTPUT.PUT_LINE(RPAD(rec.station_name, 45) || ' | starts=' || rec.start_cnt);
  END LOOP;

  IF ln_total_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

