DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE;
  lv_input_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := NULL;

  lv_latest_time SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
  lv_level VARCHAR2(10);
BEGIN
  lv_landmark := NVL(lv_input_landmark, 'San Francisco');

  -- Most recent snapshot time across all stations
  SELECT MAX(st.time)
    INTO lv_latest_time
    FROM SAN_FRANCISCO.BIKESHARE_STATUS st;

  DBMS_OUTPUT.PUT_LINE('Latest status time: ' || TO_CHAR(lv_latest_time, 'YYYY-MM-DD HH24:MI:SS'));
  DBMS_OUTPUT.PUT_LINE('Availability for top start stations in landmark: ' || lv_landmark);

  FOR rec IN (
    WITH top_starts AS (
      SELECT *
      FROM (
        SELECT s.station_id,
               s.name AS station_name,
               COUNT(*) AS start_cnt
          FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
          INNER JOIN SAN_FRANCISCO.BIKESHARE_STATIONS s
            ON s.station_id = t.start_station_id
         WHERE s.landmark = lv_landmark
         GROUP BY s.station_id, s.name
         ORDER BY COUNT(*) DESC, s.name
      )
      WHERE ROWNUM <= co_report_limit
    )
    SELECT ts.station_name,
           bs.bikes_available,
           bs.docks_available
