      LEFT OUTER JOIN SAN_FRANCISCO.BIKESHARE_STATUS bs
        ON bs.station_id = ts.station_id
       AND bs.time = lv_latest_time
     ORDER BY ts.station_name
  ) LOOP
    IF NVL(TO_NUMBER(rec.bikes_available), 0) = 0 THEN
