DBMS_OUTPUT.PUT_LINE('rank=' || rec.start_rank || ' | ' || RPAD(rec.station_name, 45) || ' | starts=' || rec.start_cnt || ' | bikes=' || rec.bikes_avail_num || ' docks=' || rec.docks_avail_num);
