DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE;
  lv_input_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := NULL;

  lv_latest_time SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
  ln_rows PLS_INTEGER := 0;
BEGIN
  lv_landmark := NVL(lv_input_landmark, 'San Francisco');

  SELECT MAX(st.time)
    INTO lv_latest_time
    FROM SAN_FRANCISCO.BIKESHARE_STATUS st;

  DBMS_OUTPUT.PUT_LINE('CRITICAL stations at latest time for landmark: ' || lv_landmark);
  DBMS_OUTPUT.PUT_LINE('Latest status time: ' || TO_CHAR(lv_latest_time, 'YYYY-MM-DD HH24:MI:SS'));

  FOR rec IN (
    WITH usage_by_station AS (
      SELECT s.station_id,
             s.name AS station_name,
             COUNT(*) AS start_cnt,
             ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC, s.name) AS start_rank
        FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
        INNER JOIN SAN_FRANCISCO.BIKESHARE_STATIONS s
          ON s.station_id = t.start_station_id
       WHERE s.landmark = lv_landmark
       GROUP BY s.station_id, s.name
    ),
    critical_now AS (
      SELECT bs.station_id,
             NVL(TO_NUMBER(bs.bikes_available), 0) AS bikes_avail_num,
             NVL(TO_NUMBER(bs.docks_available), 0) AS docks_avail_num
        FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
       WHERE bs.time = lv_latest_time
         AND NVL(TO_NUMBER(bs.bikes_available), 0) = 0
    )
    SELECT u.start_rank,
           u.station_name,
           u.start_cnt,
           c.bikes_avail_num,
           c.docks_avail_num
      FROM usage_by_station u
      INNER JOIN critical_now c
        ON c.station_id = u.station_id
     ORDER BY u.start_rank, u.station_name
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    ln_rows := ln_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      'rank=' || rec.start_rank || ' | ' || RPAD(rec.station_name, 45) ||
      ' | starts=' || rec.start_cnt || ' | bikes=' || rec.bikes_avail_num ||
      ' docks=' || rec.docks_avail_num
    );
  END LOOP;

  IF ln_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
