CREATE OR REPLACE PROCEDURE sp_get_customer_demographics
(
    p_cust_id    NUMBER
)
IS

------------------------------------------------
-- VARIABLES
------------------------------------------------
    v_education         VARCHAR2(8000);
    v_occupation        VARCHAR2(8000);
    v_household_size    VARCHAR2(8000);
    v_yrs_residence     NUMBER;

BEGIN

------------------------------------------------
-- INPUT VALIDATION
------------------------------------------------
    IF p_cust_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID is NULL not found');
        RETURN;
    END IF;

------------------------------------------------
-- DATA RETRIEVAL
------------------------------------------------
    SELECT education,
           occupation,
           household_size,
           yrs_residence
    INTO   v_education,
           v_occupation,
           v_household_size,
           v_yrs_residence
    FROM   complex_oracle.supplementary_demographics
    WHERE  cust_id = p_cust_id;

------------------------------------------------
-- CONTROL FLOW : BUSINESS LOGIC
------------------------------------------------
    IF v_yrs_residence >= 10 THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID ' || p_cust_id);
        DBMS_OUTPUT.PUT_LINE('CUSTOMER TYPE : LONG TERM RESIDENT');

    ELSIF v_yrs_residence BETWEEN 5 AND 9 THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID ' || p_cust_id);
        DBMS_OUTPUT.PUT_LINE('CUSTOMER TYPE : MEDIUM TERM RESIDENT');

    ELSE
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID ' || p_cust_id);
        DBMS_OUTPUT.PUT_LINE('CUSTOMER TYPE : NEW RESIDENT');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Education : ' || v_education);
    DBMS_OUTPUT.PUT_LINE('Occupation : ' || v_occupation);
    DBMS_OUTPUT.PUT_LINE('Household Size : ' || v_household_size);
    DBMS_OUTPUT.PUT_LINE('Years Residence : ' || v_yrs_residence);

------------------------------------------------
-- EXCEPTION HANDLING
------------------------------------------------
EXCEPTION

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID ' || p_cust_id || ' NO DATA FOUND');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('UNEXPECTED ERROR OCCURRED');

END sp_get_customer_demographics;
