CREATE OR REPLACE PROCEDURE sp_calculate_customer_sports
(
    p_cust_id    NUMBER
)
IS

------------------------------------------------
-- VARIABLES
------------------------------------------------
    v_education         VARCHAR2(8000);
    v_occupation        VARCHAR2(8000);
    v_household_size    VARCHAR2(8000);
    v_yrs_residence     NUMBER;

    v_cricket           NUMBER;
    v_baseball          NUMBER;
    v_tennis            NUMBER;
    v_soccer            NUMBER;
    v_golf              NUMBER;

    v_total             NUMBER;

BEGIN

------------------------------------------------
-- CONTROL FLOW : INPUT VALIDATION
------------------------------------------------
    IF p_cust_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID is NULL not found');
        RETURN;
    END IF;

------------------------------------------------
-- DATA RETRIEVAL
------------------------------------------------
    SELECT education,
           occupation,
           household_size,
           yrs_residence,
           cricket,
           baseball,
           tennis,
           soccer,
           golf
    INTO   v_education,
           v_occupation,
           v_household_size,
           v_yrs_residence,
           v_cricket,
           v_baseball,
           v_tennis,
           v_soccer,
           v_golf
    FROM   complex_oracle.supplementary_demographics
    WHERE  cust_id = p_cust_id;

------------------------------------------------
-- CONTROL FLOW : DEMOGRAPHICS LOGIC
------------------------------------------------
    DBMS_OUTPUT.PUT_LINE('CUSTOMER ID: ' || p_cust_id);

    IF v_yrs_residence >= 10 THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER TYPE : LONG TERM RESIDENT');

    ELSIF v_yrs_residence BETWEEN 5 AND 9 THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER TYPE : MID TERM RESIDENT');

    ELSE
        DBMS_OUTPUT.PUT_LINE('CUSTOMER TYPE : NEW RESIDENT');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Education : ' || v_education);
    DBMS_OUTPUT.PUT_LINE('Occupation : ' || v_occupation);
    DBMS_OUTPUT.PUT_LINE('Household Size : ' || v_household_size);
    DBMS_OUTPUT.PUT_LINE('Years Residence : ' || v_yrs_residence);

------------------------------------------------
-- CONTROL FLOW : SPORTS BUSINESS LOGIC
------------------------------------------------
    v_total :=
        NVL(v_cricket, 0) +
        NVL(v_baseball, 0) +
        NVL(v_tennis, 0) +
        NVL(v_soccer, 0) +
        NVL(v_golf, 0);

    IF v_total >= 4 THEN
        DBMS_OUTPUT.PUT_LINE('SPORTS INTEREST : VERY HIGH');

    ELSIF v_total BETWEEN 2 AND 3 THEN
        DBMS_OUTPUT.PUT_LINE('SPORTS INTEREST : MODERATE');

    ELSIF v_total = 1 THEN
        DBMS_OUTPUT.PUT_LINE('SPORTS INTEREST : LOW');

    ELSE
        DBMS_OUTPUT.PUT_LINE('SPORTS INTEREST : NONE');
    END IF;

    DBMS_OUTPUT.PUT_LINE('TOTAL SPORTS COUNT : ' || v_total);

------------------------------------------------
-- EXCEPTION HANDLING
------------------------------------------------
EXCEPTION

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER ID: ' || p_cust_id || ' NO DATA FOUND');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('UNEXPECTED ERROR OCCURRED');

END sp_calculate_customer_sports;
/

