question:
You are preparing a quick sales-channel briefing. For a given calendar year, print the top channels by total sales amount (sum of SALES.AMOUNT_SOLD), limited to 15 rows for readability.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Top channels for year ' || lv_year || ' (up to ' || co_report_limit || ' rows):');
DBMS_OUTPUT.PUT_LINE(RPAD(lv_rank, 3) || ' | channel_id=' || rec.channel_id || ' | total_amount=' || rec.total_amount);
DBMS_OUTPUT.PUT_LINE('No channels found for the given year.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No channels found for the given year.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_year CONSTANT COMPLEX_ORACLE.TIMES.calendar_year%TYPE := 2000;
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_cnt PLS_INTEGER;
  lv_rank PLS_INTEGER := 0;
BEGIN
  SELECT COUNT(*)
    INTO lv_cnt
    FROM (
      SELECT s.channel_id, SUM(s.amount_sold) AS total_amount
        FROM COMPLEX_ORACLE.SALES s
        INNER JOIN COMPLEX_ORACLE.TIMES t
          ON t.time_id = s.time_id
       WHERE t.calendar_year = lv_year
       GROUP BY s.channel_id
    );

  IF lv_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No channels found for the given year.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top channels for year ' || lv_year || ' (up to ' || co_report_limit || ' rows):');

  FOR rec IN (
    SELECT channel_id, total_amount
      FROM (
        SELECT s.channel_id, SUM(s.amount_sold) AS total_amount
          FROM COMPLEX_ORACLE.SALES s
          INNER JOIN COMPLEX_ORACLE.TIMES t
            ON t.time_id = s.time_id
         WHERE t.calendar_year = lv_year
         GROUP BY s.channel_id
         ORDER BY SUM(s.amount_sold) DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rank := lv_rank + 1;
    DBMS_OUTPUT.PUT_LINE(RPAD(lv_rank, 3) || ' | channel_id=' || rec.channel_id || ' | total_amount=' || rec.total_amount);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No channels found for the given year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

