DECLARE
  lv_start_date CONSTANT COMPLEX_ORACLE.SALES.time_id%TYPE := DATE '2000-01-01';
  lv_end_date   CONSTANT COMPLEX_ORACLE.SALES.time_id%TYPE := DATE '2000-12-31';
  lv_threshold  CONSTANT COMPLEX_ORACLE.SALES.amount_sold%TYPE := 100000;
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_cnt PLS_INTEGER;
  lv_label VARCHAR2(10);
BEGIN
  IF lv_start_date > lv_end_date THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date range.');
    RETURN;
  END IF;

  SELECT COUNT(*)
    INTO lv_cnt
    FROM (
      SELECT s.channel_id
        FROM COMPLEX_ORACLE.SALES s
       WHERE s.time_id BETWEEN lv_start_date AND lv_end_date
       GROUP BY s.channel_id
    );

  IF lv_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No channels found for the given date range.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top channels from ' || TO_CHAR(lv_start_date, 'YYYY-MM-DD') || ' to ' || TO_CHAR(lv_end_date, 'YYYY-MM-DD') || ' (threshold=' || lv_threshold || ', up to ' || co_report_limit || ' rows):');

  FOR rec IN (
    SELECT channel_id, total_amount
      FROM (
        SELECT s.channel_id, SUM(s.amount_sold) AS total_amount
          FROM COMPLEX_ORACLE.SALES s
         WHERE s.time_id BETWEEN lv_start_date AND lv_end_date
         GROUP BY s.channel_id
         ORDER BY SUM(s.amount_sold) DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    IF rec.total_amount >= lv_threshold THEN
      lv_label := 'HIGH';
    ELSE
      lv_label := 'LOW';
