question:
Build a quick on-screen report for BikeShare operations: for a given landmark (e.g., 'San Francisco'), list up to 15 stations ordered by highest total dock count, and include the station id, station name, dock count, and installation date. If the caller passes NULL for the landmark, default it to 'San Francisco'.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Landmark used: ' || lv_landmark);
DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
DBMS_OUTPUT.PUT_LINE('station_id=' || rec.station_id || ', name=' || rec.name || ', dockcount=' || rec.dockcount || ', installation_date=' || TO_CHAR(rec.installation_date, 'YYYY-MM-DD'));
DBMS_OUTPUT.PUT_LINE('No stations found for landmark: ' || lv_landmark);
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No stations found for landmark: ' || lv_landmark.
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'.
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := NULL;
  lv_rows     PLS_INTEGER := 0;
BEGIN
  -- Default operational view to San Francisco when not provided
  lv_landmark := NVL(lv_landmark, 'San Francisco');

  DBMS_OUTPUT.PUT_LINE('Landmark used: ' || lv_landmark);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));

  FOR rec IN (
    SELECT s.station_id,
           s.name,
           s.dockcount,
           s.installation_date
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.landmark = lv_landmark
     ORDER BY TO_NUMBER(s.dockcount) DESC, s.station_id
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      'station_id=' || rec.station_id ||
      ', name=' || rec.name ||
      ', dockcount=' || rec.dockcount ||
      ', installation_date=' || TO_CHAR(rec.installation_date, 'YYYY-MM-DD')
    );
  END LOOP;

  IF lv_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark: ' || lv_landmark);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

