question:
Using the same landmark scope from turns 1 and 2, create a compact on-screen "utilization snapshot": show up to 15 stations with the highest utilization ratio, defined as bikes_available / (bikes_available + docks_available) from the most recent status time for each station. Output station id, station name, the most recent status timestamp, bikes_available, docks_available, and the utilization ratio rounded to 3 decimals. Avoid divide-by-zero; if bikes+docks is 0, treat utilization as NULL and print it as 'N/A'. Make sure the block has robust exception handling.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Landmark used: ' || lv_landmark);
DBMS_OUTPUT.PUT_LINE('Utilization snapshot (top by ratio):');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
DBMS_OUTPUT.PUT_LINE('station_id=' || rec.station_id || ', name=' || rec.name || ', status_time=' || TO_CHAR(rec.status_time, 'YYYY-MM-DD HH24:MI:SS') || ', bikes=' || rec.bikes_available || ', docks=' || rec.docks_available || ', utilization=' || rec.utilization_display);
DBMS_OUTPUT.PUT_LINE('No utilization data found for landmark: ' || lv_landmark);
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No utilization data found for landmark: ' || lv_landmark.
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'.
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := NULL;
  lv_rows     PLS_INTEGER := 0;
BEGIN
  lv_landmark := NVL(lv_landmark, 'San Francisco');

  DBMS_OUTPUT.PUT_LINE('Landmark used: ' || lv_landmark);
  DBMS_OUTPUT.PUT_LINE('Utilization snapshot (top by ratio):');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

  FOR rec IN (
    WITH latest_status AS (
      SELECT bs.station_id,
             bs.time AS status_time,
             bs.bikes_available,
             bs.docks_available,
             ROW_NUMBER() OVER (PARTITION BY bs.station_id ORDER BY bs.time DESC) AS rn
        FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
    )
    SELECT s.station_id,
           s.name,
           ls.status_time,
           ls.bikes_available,
           ls.docks_available,
           CASE
             WHEN TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available) = 0 THEN NULL
             ELSE ROUND(
               TO_NUMBER(ls.bikes_available) /
               (TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available)),
               3
             )
           END AS utilization_ratio,
           CASE
             WHEN TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available) = 0 THEN 'N/A'
             ELSE TO_CHAR(
               ROUND(
                 TO_NUMBER(ls.bikes_available) /
                 (TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available)),
                 3
               )
             )
           END AS utilization_display
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
      INNER JOIN latest_status ls
        ON ls.station_id = s.station_id
       AND ls.rn = 1
     WHERE s.landmark = lv_landmark
     ORDER BY utilization_ratio DESC NULLS LAST, s.station_id
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      'station_id=' || rec.station_id ||
      ', name=' || rec.name ||
      ', status_time=' || TO_CHAR(rec.status_time, 'YYYY-MM-DD HH24:MI:SS') ||
      ', bikes=' || rec.bikes_available ||
      ', docks=' || rec.docks_available ||
