CREATE OR REPLACE PROCEDURE report_top_start_stations(
  p_subscriber_type IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.subscriber_type%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top start stations report (up to 15 rows)');

  IF p_subscriber_type IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Subscriber type filter: ALL');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Subscriber type filter: ' || p_subscriber_type);
  END IF;

  FOR rec IN (
    SELECT t.start_station_name,
           COUNT(*) AS trip_cnt
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
     WHERE p_subscriber_type IS NULL
        OR t.subscriber_type = p_subscriber_type
     GROUP BY t.start_station_name
     ORDER BY trip_cnt DESC, t.start_station_name ASC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE('(station=' || rec.start_station_name || ', trips=' || rec.trip_cnt || ')');
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_start_stations;
/

CREATE OR REPLACE PACKAGE bikeshare_ops_pkg IS
  FUNCTION get_station_id_by_name(
    p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE
  ) RETURN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;

  PROCEDURE print_station_availability(
    p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE
  );
END bikeshare_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops_pkg IS
  FUNCTION get_station_id_by_name(
    p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE
  ) RETURN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE IS
    lv_station_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
  BEGIN
    -- Single-row lookup by exact station name
    SELECT s.station_id
      INTO lv_station_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO s
     WHERE s.name = p_station_name;

    RETURN lv_station_id;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END get_station_id_by_name;

  PROCEDURE print_station_availability(
    p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE
  ) IS
    lv_station_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
    lv_bikes      SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
    lv_docks      SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_docks_available%TYPE;
  BEGIN
    IF p_station_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station name is required.');
      RETURN;
    END IF;

    lv_station_id := get_station_id_by_name(p_station_name);

    IF lv_station_id IS NULL THEN
      -- get_station_id_by_name already printed the reason
      RETURN;
    END IF;

    SELECT st.num_bikes_available,
           st.num_docks_available
      INTO lv_bikes,
           lv_docks
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS st
     WHERE st.station_id = lv_station_id;

    DBMS_OUTPUT.PUT_LINE('Station availability:');
    DBMS_OUTPUT.PUT_LINE('name=''' || p_station_name);
    DBMS_OUTPUT.PUT_LINE('station_id=' || lv_station_id);
    DBMS_OUTPUT.PUT_LINE('bikes_available=' || lv_bikes || 'docks_available=' || lv_docks);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_station_availability;
END bikeshare_ops_pkg;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for review readability

  lv_subscriber_type SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.subscriber_type%TYPE := NULL;
  lv_threshold_txt  VARCHAR2(30) := '5';

  lv_threshold      NUMBER;
  lv_rows_printed   PLS_INTEGER := 0;

  lv_station_id     SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE;
  lv_bikes          SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
  lv_bikes_num      NUMBER;
  lv_flag           VARCHAR2(10);
BEGIN
  lv_threshold := TO_NUMBER(lv_threshold_txt);

  DBMS_OUTPUT.PUT_LINE('Station review (up to 15 rows)');

  IF lv_subscriber_type IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Subscriber type filter: ALL');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Subscriber type filter: ' || lv_subscriber_type);
  END IF;

  DBMS_OUTPUT.PUT_LINE('Threshold bikes available: ' || lv_threshold);

  FOR rec IN (
    SELECT t.start_station_name,
           COUNT(*) AS trip_cnt
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
     WHERE lv_subscriber_type IS NULL
        OR t.subscriber_type = lv_subscriber_type
     GROUP BY t.start_station_name
     ORDER BY trip_cnt DESC, t.start_station_name ASC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;

    lv_station_id := bikeshare_ops_pkg.get_station_id_by_name(rec.start_station_name);

    lv_bikes := NULL;
    IF lv_station_id IS NOT NULL THEN
      BEGIN
        SELECT st.num_bikes_available
          INTO lv_bikes
          FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS st
         WHERE st.station_id = lv_station_id;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_bikes := NULL;
        WHEN TOO_MANY_ROWS THEN
          lv_bikes := NULL;
      END;
    END IF;

    BEGIN
      lv_bikes_num := TO_NUMBER(lv_bikes);
      IF lv_bikes_num < lv_threshold THEN
        lv_flag := 'LOW';
      ELSE
        lv_flag := 'OK';
      END IF;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        lv_flag := 'UNKNOWN';
    END;

    DBMS_OUTPUT.PUT_LINE(
      'station=' || rec.start_station_name ||
      ', station_id=' || NVL(lv_station_id, 'UNKNOWN') ||
      ', bikes=' || NVL(lv_bikes, 'UNKNOWN') ||
      ', flag=' || lv_flag
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid threshold.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

