question:
Now make the report reusable by creating a stored procedure that accepts a year and a county name pattern. It should print a small county summary for that year/pattern (births and average birth weight). Because the source columns are text, treat values as numeric only when they look numeric; otherwise treat them as missing. Also include a simple control-flow category label (e.g., HIGH_BIRTHS/LOW_BIRTHS) based on the numeric births total.

Requirements:
Procedure Name: report_county_natality.
Parameters:
p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE.
p_county_like IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE.
Output:
DBMS_OUTPUT.PUT_LINE('County natality summary for year=' || TO_CHAR(p_year, 'YYYY'));
DBMS_OUTPUT.PUT_LINE('County filter (LIKE)=' || NVL(p_county_like, '%'));
DBMS_OUTPUT.PUT_LINE(RPAD('County', 35) || ' | ' || LPAD('Births', 12) || ' | ' || LPAD('Avg BW (g)', 12) || ' | ' || RPAD('Category', 12));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || RPAD('-', 12, '-') || '-+-' || RPAD('-', 12, '-') || '-+-' || RPAD('-', 12, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.county_of_residence, 35) || ' | ' || LPAD(TO_CHAR(rec.total_births), 12) || ' | ' || LPAD(NVL(TO_CHAR(rec.avg_bw_gms), 'N/A'), 12) || ' | ' || RPAD(lv_category, 12));
DBMS_OUTPUT.PUT_LINE('No rows matched inputs.');
DBMS_OUTPUT.PUT_LINE('Input year is required.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'.
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'.
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
CREATE OR REPLACE PROCEDURE report_county_natality(
  p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_county_like IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 10; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
  lv_category     VARCHAR2(12);
BEGIN
  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input year is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('County natality summary for year=' || TO_CHAR(p_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE('County filter (LIKE)=' || NVL(p_county_like, '%'));

  DBMS_OUTPUT.PUT_LINE(
    RPAD('County', 35) || ' | ' ||
    LPAD('Births', 12) || ' | ' ||
    LPAD('Avg BW (g)', 12) || ' | ' ||
    RPAD('Category', 12)
  );
  DBMS_OUTPUT.PUT_LINE(
    RPAD('-', 35, '-') || '-+-' ||
    RPAD('-', 12, '-') || '-+-' ||
    RPAD('-', 12, '-') || '-+-' ||
    RPAD('-', 12, '-')
  );

  FOR rec IN (
    SELECT cn.county_of_residence,
           SUM(CASE
                 WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+$') THEN TO_NUMBER(TRIM(cn.births))
                 ELSE 0
               END) AS total_births,
           AVG(CASE
                 WHEN REGEXP_LIKE(TRIM(cn.ave_birth_weight_gms), '^\d+(\.\d+)?$') THEN TO_NUMBER(TRIM(cn.ave_birth_weight_gms))
                 ELSE NULL
               END) AS avg_bw_gms
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND cn.county_of_residence LIKE NVL(p_county_like, '%')
     GROUP BY cn.county_of_residence
     ORDER BY total_births DESC, cn.county_of_residence ASC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    IF rec.total_births >= 1000 THEN
      lv_category := 'HIGH_BIRTHS';
    ELSE
      lv_category := 'LOW_BIRTHS';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 35) || ' | ' ||
      LPAD(TO_CHAR(rec.total_births), 12) || ' | ' ||
      LPAD(NVL(TO_CHAR(rec.avg_bw_gms), 'N/A'), 12) || ' | ' ||
      RPAD(lv_category, 12)
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched inputs.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_natality;
/

CREATE OR REPLACE PACKAGE natality_kpi_pkg IS
  FUNCTION get_total_births(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_like IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) RETURN NUMBER;

  PROCEDURE print_total_births_kpi(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_like IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  );
END natality_kpi_pkg;
/

CREATE OR REPLACE PACKAGE BODY natality_kpi_pkg IS
  FUNCTION get_total_births(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_like IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) RETURN NUMBER IS
    lv_total_births NUMBER;
  BEGIN
    IF p_year IS NULL THEN
      RETURN NULL;
    END IF;

    SELECT SUM(CASE
                 WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+$') THEN TO_NUMBER(TRIM(cn.births))
                 ELSE 0
               END)
      INTO lv_total_births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND cn.county_of_residence LIKE NVL(p_county_like, '%');

    RETURN NVL(lv_total_births, 0);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN 0;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN 0;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN 0;
  END get_total_births;

  PROCEDURE print_total_births_kpi(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_like IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) IS
    lv_total_births NUMBER;
  BEGIN
    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input year is required.');
      RETURN;
    END IF;

    lv_total_births := get_total_births(p_year => p_year, p_county_like => p_county_like);

    DBMS_OUTPUT.PUT_LINE(
      'KPI total births for year=' || TO_CHAR(p_year, 'YYYY') ||
      ', county LIKE ' || NVL(p_county_like, '%') ||
      ' = ' || TO_CHAR(lv_total_births)
    );

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_total_births_kpi;
END natality_kpi_pkg;
/

