CREATE OR REPLACE PROCEDURE rpt_hospice_top_payments(
  p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top hospice providers in state=' || p_state || ' (by TOTAL_MEDICARE_PAYMENT_AMOUNT)');

  FOR rec IN (
    SELECT hp.provider_id,
           hp.name,
           hp.city,
           TO_NUMBER(NVL(hp.total_medicare_payment_amount, '0') DEFAULT 0 ON CONVERSION ERROR) AS pay_amt
      FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
     WHERE hp.state = p_state
     ORDER BY TO_NUMBER(NVL(hp.total_medicare_payment_amount, '0') DEFAULT 0 ON CONVERSION ERROR) DESC,
              hp.provider_id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'PROVIDER_ID=' || rec.provider_id ||
      ', NAME=' || rec.name ||
      ', CITY=' || rec.city ||
      ', PAYMENT=' || TO_CHAR(rec.pay_amt)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_hospice_top_payments;
/

CREATE OR REPLACE FUNCTION fn_hospice_provider_count(
  p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
) RETURN NUMBER IS
  lv_cnt NUMBER;
BEGIN
  SELECT COUNT(*)
    INTO lv_cnt
    FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
   WHERE hp.state = p_state;

  RETURN lv_cnt;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 0;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 0;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 0;
END fn_hospice_provider_count;
/

CREATE OR REPLACE PROCEDURE hospice_state_healthcheck(
  p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
) IS
  lv_cnt NUMBER;
BEGIN
  lv_cnt := fn_hospice_provider_count(p_state);

  DBMS_OUTPUT.PUT_LINE('State=' || p_state || ', provider_count=' || TO_CHAR(lv_cnt));

  IF lv_cnt < 10 THEN
    DBMS_OUTPUT.PUT_LINE('Status=LOW');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Status=OK');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END hospice_state_healthcheck;
/

CREATE OR REPLACE PROCEDURE rpt_hospice_top_payments_safe(
  p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  DBMS_OUTPUT.PUT_LINE('SAFE report start for state=' || p_state);

  -- Fix: use safe numeric conversion so bad strings become 0.
  FOR rec IN (
    SELECT hp.provider_id,
           TO_NUMBER(NVL(hp.total_medicare_payment_amount, '0') DEFAULT 0 ON CONVERSION ERROR) AS pay_amt
      FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
     WHERE hp.state = p_state
     ORDER BY TO_NUMBER(NVL(hp.total_medicare_payment_amount, '0') DEFAULT 0 ON CONVERSION ERROR) DESC,
              hp.provider_id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('ROW provider_id=' || rec.provider_id || ', payment=' || TO_CHAR(rec.pay_amt));
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_hospice_top_payments_safe;
