CREATE OR REPLACE PROCEDURE report_country_debt_values(
  p_country_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_code%TYPE,
  p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_printed_count PLS_INTEGER := 0;
BEGIN
  IF p_country_code IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Both inputs are required: country_code and year.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Debt values for country_code=' || p_country_code || ', year=' || p_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('COUNTRY_NAME', 35) || ' | ' || RPAD('INDICATOR_CODE', 25) || ' | ' || 'VALUE_NUM');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 15, '-'));

  FOR rec IN (
    SELECT d.country_name,
           d.indicator_code,
           TO_NUMBER(d.value) AS value_num
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
     WHERE d.country_code = p_country_code
       AND d.year = p_year
       AND REGEXP_LIKE(TRIM(d.value), '^-?\d+(\.\d+)?$')
       AND ROWNUM <= co_report_limit
     ORDER BY d.country_name, d.indicator_code
  ) LOOP
    lv_printed_count := lv_printed_count + 1;
    DBMS_OUTPUT.PUT_LINE(RPAD(rec.country_name, 35) || ' | ' || RPAD(rec.indicator_code, 25) || ' | ' || TO_CHAR(rec.value_num));
  END LOOP;

  IF lv_printed_count = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No numeric debt values found for that country/year.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected value conversion error.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_debt_values;
/

