CREATE OR REPLACE FUNCTION get_debt_trend(
  p_country_code   IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_code%TYPE,
  p_indicator_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE
) RETURN VARCHAR2
IS
  lv_earliest_value NUMBER;
  lv_latest_value   NUMBER;
BEGIN
  IF p_country_code IS NULL OR p_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Trend inputs are required: country_code and indicator_code.');
    RETURN 'UNKNOWN';
  END IF;

  /* Use analytical aggregation to get first/last numeric values by year */
  SELECT MIN(TO_NUMBER(d.value)) KEEP (DENSE_RANK FIRST ORDER BY TO_NUMBER(d.year)),
         MIN(TO_NUMBER(d.value)) KEEP (DENSE_RANK LAST  ORDER BY TO_NUMBER(d.year))
    INTO lv_earliest_value, lv_latest_value
    FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
   WHERE d.country_code = p_country_code
     AND d.indicator_code = p_indicator_code
     AND REGEXP_LIKE(TRIM(d.value), '^-?\d+(\.\d+)?$')
     AND REGEXP_LIKE(TRIM(d.year), '^\d+$');

  IF lv_latest_value > lv_earliest_value THEN
    RETURN 'UP';
  ELSIF lv_latest_value < lv_earliest_value THEN
    RETURN 'DOWN';
  ELSE
    RETURN 'FLAT';
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No numeric debt values found to compute a trend.');
    RETURN 'UNKNOWN';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'UNKNOWN';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
END get_debt_trend;
/

DECLARE
  lv_country_code WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_code%TYPE;
  lv_indicator_code WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE;
  lv_trend VARCHAR2(20);
BEGIN
  /* Pick a common (country_code, indicator_code) pair that has numeric values */
  SELECT country_code, indicator_code
    INTO lv_country_code, lv_indicator_code
    FROM (
      SELECT d.country_code, d.indicator_code
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
       WHERE REGEXP_LIKE(TRIM(d.value), '^-?\d+(\.\d+)?$')
         AND REGEXP_LIKE(TRIM(d.year), '^\d+$')
       GROUP BY d.country_code, d.indicator_code
       ORDER BY COUNT(*) DESC, d.country_code, d.indicator_code
    )
   WHERE ROWNUM = 1;

  lv_trend := get_debt_trend(lv_country_code, lv_indicator_code);
  DBMS_OUTPUT.PUT_LINE('Trend check: country_code=' || lv_country_code || ', indicator_code=' || lv_indicator_code || ' => ' || lv_trend);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No numeric debt values found to compute a trend.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

