CREATE OR REPLACE PROCEDURE dei_gender_balance_check(
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
) IS
  lv_women_cnt NUMBER := 0;
  lv_men_cnt   NUMBER := 0;
  lv_classification VARCHAR2(20);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Gender balance check for workforce=' || p_workforce || ', year=' || p_report_year);

  -- Count women rows
  SELECT COUNT(*)
    INTO lv_women_cnt
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
   WHERE r.workforce = p_workforce
     AND r.report_year = p_report_year
     AND UPPER(r.gender_us) = 'WOMEN';

  -- Count men rows
  SELECT COUNT(*)
    INTO lv_men_cnt
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
   WHERE r.workforce = p_workforce
     AND r.report_year = p_report_year
     AND UPPER(r.gender_us) = 'MEN';

  IF lv_women_cnt > 0 AND lv_men_cnt > 0 THEN
    lv_classification := 'BALANCED';
  ELSE
    lv_classification := 'NOT_BALANCED';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Women rows=' || lv_women_cnt || '; Men rows=' || lv_men_cnt || '; Classification=' || lv_classification);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END dei_gender_balance_check;
/

