    lv_like  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;
    lv_txt_1 SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.ave_age_of_mother%TYPE;
    lv_txt_2 SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.ave_age_of_mother%TYPE;
    lv_age_1 NUMBER;
    lv_age_2 NUMBER;
  BEGIN
    lv_like := NVL(p_county_like, '%');

    DBMS_OUTPUT.PUT_LINE('Mother age comparison');

    SELECT cn.ave_age_of_mother
      INTO lv_txt_1
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year_1
       AND UPPER(cn.county_of_residence) LIKE UPPER(lv_like)
       AND ROWNUM = 1;

    SELECT cn.ave_age_of_mother
      INTO lv_txt_2
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year_2
       AND UPPER(cn.county_of_residence) LIKE UPPER(lv_like)
       AND ROWNUM = 1;

    lv_age_1 := safe_to_number(lv_txt_1);
    lv_age_2 := safe_to_number(lv_txt_2);

    IF lv_age_1 IS NULL OR lv_age_2 IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('YEAR1=' || TO_CHAR(p_year_1, 'YYYY') || ' AVE_AGE_OF_MOTHER=' || TO_CHAR(lv_age_1));
    DBMS_OUTPUT.PUT_LINE('YEAR2=' || TO_CHAR(p_year_2, 'YYYY') || ' AVE_AGE_OF_MOTHER=' || TO_CHAR(lv_age_2));
    DBMS_OUTPUT.PUT_LINE('DIFF(year2-year1)=' || TO_CHAR(lv_age_2 - lv_age_1));

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END compare_mother_age;

  PROCEDURE print_births_quality_issues(
    p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_printed      PLS_INTEGER := 0;
    lv_issues       PLS_INTEGER := 0;
    lv_births_num   NUMBER;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Births quality issues');

    FOR rec IN (
      SELECT cn.county_of_residence,
             cn.county_of_residence_fips,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
         AND ROWNUM <= co_report_limit
       ORDER BY cn.county_of_residence
    ) LOOP
      lv_printed := lv_printed + 1;

      IF rec.births IS NULL THEN
        lv_issues := lv_issues + 1;
        DBMS_OUTPUT.PUT_LINE('COUNTY=' || rec.county_of_residence || ' | FIPS=' || rec.county_of_residence_fips || ' | BIRTHS_RAW=' || rec.births);
      ELSE
        lv_births_num := safe_to_number(rec.births);
        IF lv_births_num IS NULL THEN
          lv_issues := lv_issues + 1;
          DBMS_OUTPUT.PUT_LINE('COUNTY=' || rec.county_of_residence || ' | FIPS=' || rec.county_of_residence_fips || ' | BIRTHS_RAW=' || rec.births);
        END IF;
      END IF;

    END LOOP;

    IF lv_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

    IF lv_issues > 0 THEN
      DBMS_OUTPUT.PUT_LINE('Issues found.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('No issues found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_births_quality_issues;

END natality_reporting_pkg;
/

CREATE OR REPLACE PROCEDURE rpt_season_match_snapshot(
  p_season_id IN IPL.MATCH.season_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Match Snapshot for Season: ' || p_season_id);

  FOR rec IN (
    SELECT m.match_id,
           m.match_date,
           m.venue,
           t1.name AS team1_name,
           t2.name AS team2_name,
           NVL(tw.name, 'NO RESULT') AS winner_name
      FROM IPL.MATCH m
      INNER JOIN IPL.TEAM t1 ON t1.team_id = m.team_1
      INNER JOIN IPL.TEAM t2 ON t2.team_id = m.team_2
      LEFT OUTER JOIN IPL.TEAM tw ON tw.team_id = m.match_winner
     WHERE m.season_id = p_season_id
     ORDER BY m.match_date DESC, m.match_id DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'MATCH_ID=' || rec.match_id ||
      ' | MATCH_DATE=' || TO_CHAR(rec.match_date, 'YYYY-MM-DD') ||
      ' | VENUE=' || rec.venue ||
      ' | TEAM_1=' || rec.team1_name ||
      ' | TEAM_2=' || rec.team2_name ||
      ' | WINNER=' || rec.winner_name
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matches found for the given season.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matches found for the given season.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_season_match_snapshot;
/

CREATE OR REPLACE FUNCTION fn_player_runs_in_season(
  p_player_id IN IPL.PLAYER.player_id%TYPE,
  p_season_id IN IPL.MATCH.season_id%TYPE
) RETURN NUMBER IS
  lv_total_runs NUMBER := 0;
BEGIN
  -- Sum batsman runs for the player across all balls in matches of the season
  SELECT NVL(SUM(bs.runs_scored), 0)
    INTO lv_total_runs
    FROM IPL.MATCH m
    INNER JOIN IPL.BALL_BY_BALL b
      ON b.match_id = m.match_id
    INNER JOIN IPL.BATSMAN_SCORED bs
      ON bs.match_id = b.match_id
     AND bs.innings_no = b.innings_no
     AND bs.over_id = b.over_id
     AND bs.ball_id = b.ball_id
    INNER JOIN IPL.PLAYER p
      ON p.player_id = b.striker
   WHERE m.season_id = p_season_id
     AND p.player_id = p_player_id;

  DBMS_OUTPUT.PUT_LINE('PLAYER_ID=' || p_player_id || ' | SEASON_ID=' || p_season_id || ' | TOTAL_RUNS=' || lv_total_runs);
  RETURN lv_total_runs;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 0;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 0;
END fn_player_runs_in_season;
/

