CREATE OR REPLACE PACKAGE BODY player_season_pkg IS
  PROCEDURE rate_player_season(
    p_player_id IN IPL.PLAYER.player_id%TYPE,
    p_season_id IN IPL.MATCH.season_id%TYPE
  ) IS
    lv_total_runs NUMBER := 0;
    lv_rating     VARCHAR2(20);
    lv_dummy      NUMBER;
  BEGIN
    IF p_player_id IS NULL OR p_season_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Cannot rate: player_id or season_id is NULL.');
      RETURN;
    END IF;

    SELECT 1
      INTO lv_dummy
      FROM IPL.PLAYER
     WHERE player_id = p_player_id;

    SELECT 1
      INTO lv_dummy
      FROM IPL.MATCH
     WHERE season_id = p_season_id;

    lv_total_runs := fn_player_runs_in_season(p_player_id => p_player_id, p_season_id => p_season_id);

    IF lv_total_runs >= 400 THEN
      lv_rating := 'STAR';
    ELSIF lv_total_runs >= 200 THEN
      lv_rating := 'SOLID';
    ELSE
      lv_rating := 'DEVELOPING';
    END IF;

    DBMS_OUTPUT.PUT_LINE('PLAYER_ID=' || p_player_id || ' | SEASON_ID=' || p_season_id || ' | TOTAL_RUNS=' || lv_total_runs || ' | RATING=' || lv_rating);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END rate_player_season;
END player_season_pkg;
/

