CREATE OR REPLACE PACKAGE batting_reporting_pkg IS
  PROCEDURE print_top_hitters(
    p_year    IN NUMBER,
    p_min_ab  IN NUMBER
  );
END batting_reporting_pkg;
/

CREATE OR REPLACE PACKAGE BODY batting_reporting_pkg IS
  PROCEDURE print_top_hitters(
    p_year    IN NUMBER,
    p_min_ab  IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_year   BASEBALL.BATTING.year%TYPE;
    lv_min_ab BASEBALL.BATTING.ab%TYPE;
    lv_rows   PLS_INTEGER := 0;
  BEGIN
    -- Default year to most recent when NULL
    IF p_year IS NULL THEN
      SELECT MAX(b.year)
        INTO lv_year
        FROM BASEBALL.BATTING b;
    ELSE
      lv_year := p_year;
    END IF;

    -- Default min AB to 0 when NULL
    lv_min_ab := NVL(p_min_ab, 0);

    DBMS_OUTPUT.PUT_LINE('Top hitters report');
    DBMS_OUTPUT.PUT_LINE('Year=' || lv_year || ', Min_AB=' || lv_min_ab);
    DBMS_OUTPUT.PUT_LINE(RPAD('PLAYER_ID', 12, ' ') || ' ' || LPAD('H', 6, ' ') || ' ' || LPAD('HR', 6, ' '));

    FOR rec IN (
      SELECT x.player_id,
             x.total_h,
             x.total_hr
        FROM (
          SELECT b.player_id,
                 SUM(b.h)  AS total_h,
                 SUM(b.hr) AS total_hr
            FROM BASEBALL.BATTING b
           WHERE b.year = lv_year
           GROUP BY b.player_id
          HAVING SUM(b.ab) >= lv_min_ab
           ORDER BY SUM(b.h) DESC, SUM(b.hr) DESC, b.player_id ASC
        ) x
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.player_id, 12, ' ') || ' ' || LPAD(TO_CHAR(rec.total_h), 6, ' ') || ' ' || LPAD(TO_CHAR(rec.total_hr), 6, ' ')
      );
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Rows printed=' || TO_CHAR(lv_rows));

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
