CREATE OR REPLACE PACKAGE batting_classification_pkg IS
  FUNCTION get_player_tier(
    p_player_id IN BASEBALL.BATTING.player_id%TYPE,
    p_year      IN BASEBALL.BATTING.year%TYPE
  ) RETURN VARCHAR2;
END batting_classification_pkg;
/

CREATE OR REPLACE PACKAGE BODY batting_classification_pkg IS
  FUNCTION get_player_tier(
    p_player_id IN BASEBALL.BATTING.player_id%TYPE,
    p_year      IN BASEBALL.BATTING.year%TYPE
  ) RETURN VARCHAR2 IS
    lv_hits BASEBALL.BATTING.h%TYPE;
    lv_tier VARCHAR2(20);
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Tier check: player_id=' || p_player_id || ', year=' || p_year);

    -- Aggregate to a single value; treat missing as 0
    SELECT NVL(SUM(b.h), 0)
      INTO lv_hits
      FROM BASEBALL.BATTING b
     WHERE b.player_id = p_player_id
       AND b.year = p_year;

    DBMS_OUTPUT.PUT_LINE('Computed hits=' || TO_CHAR(lv_hits));

    IF lv_hits >= 150 THEN
      lv_tier := 'STAR';
    ELSIF lv_hits BETWEEN 1 AND 149 THEN
      lv_tier := 'REGULAR';
    ELSE
      lv_tier := 'UNKNOWN';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Tier=' || lv_tier);
    RETURN lv_tier;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN 'UNKNOWN';
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN 'UNKNOWN';
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN 'UNKNOWN';
  END get_player_tier;
END batting_classification_pkg;
/

