CREATE OR REPLACE PACKAGE BODY team_summary_debug_pkg IS

  PROCEDURE print_team_summary(
    p_year      IN BASEBALL.TEAM.year%TYPE,
    p_league_id IN BASEBALL.TEAM.league_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Team summary report');
    DBMS_OUTPUT.PUT_LINE('Year=' || p_year || ', League=' || p_league_id);

    -- Simple validation to prevent confusing empty output
    IF p_league_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('League is required.');
      RETURN;
    END IF;

    FOR rec IN (
      SELECT t.team_id,
             t.w AS wins,
             t.l AS losses
        FROM BASEBALL.TEAM t
       WHERE t.year = p_year
         AND t.league_id = p_league_id
       ORDER BY t.w DESC, t.l ASC, t.team_id ASC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(RPAD(rec.team_id, 6, ' ') || ' W=' || TO_CHAR(rec.wins) || ' L=' || TO_CHAR(rec.losses));
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Rows printed=' || TO_CHAR(lv_rows));

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_team_summary;


  PROCEDURE run_buggy_demo(
    p_year      IN BASEBALL.TEAM.year%TYPE,
    p_league_id IN BASEBALL.TEAM.league_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Buggy demo run');
    DBMS_OUTPUT.PUT_LINE('Year=' || p_year || ', League=' || p_league_id);

    -- Intentional bug reproduction:
    -- The alias 'wins' is defined in the inner query but incorrectly referenced in the outer ORDER BY.
    -- Correct would be: ORDER BY x.wins DESC
    FOR rec IN (
      SELECT x.team_id,
             x.wins,
             x.losses
        FROM (
          SELECT t.team_id,
                 t.w AS wins,
                 t.l AS losses
            FROM BASEBALL.TEAM t
           WHERE t.year = p_year
             AND t.league_id = p_league_id
        ) x
       ORDER BY wins DESC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(RPAD(rec.team_id, 6, ' ') || ' W=' || TO_CHAR(rec.wins) || ' L=' || TO_CHAR(rec.losses));
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Rows printed=' || TO_CHAR(lv_rows));

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_buggy_demo;

END team_summary_debug_pkg;
/

