CREATE OR REPLACE PACKAGE station_health_pkg IS
  FUNCTION classify_station_health(
    p_bikes_available IN NUMBER,
    p_capacity        IN NUMBER,
    p_critical_pct    IN NUMBER
  ) RETURN VARCHAR2;

  PROCEDURE region_health_report(
    p_region_name  IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
    p_critical_pct IN NUMBER
  );
END station_health_pkg;
/

CREATE OR REPLACE PACKAGE BODY station_health_pkg IS
  FUNCTION classify_station_health(
    p_bikes_available IN NUMBER,
    p_capacity        IN NUMBER,
    p_critical_pct    IN NUMBER
  ) RETURN VARCHAR2 IS
    lv_pct NUMBER;
  BEGIN
    IF p_capacity IS NULL OR p_capacity = 0 THEN
      RETURN 'CRITICAL';
    END IF;

    lv_pct := (p_bikes_available / p_capacity) * 100;

    IF lv_pct < p_critical_pct THEN
      RETURN 'CRITICAL';
    ELSE
      RETURN 'OK';
    END IF;
  EXCEPTION
    WHEN ZERO_DIVIDE THEN
      RETURN 'CRITICAL';
    WHEN OTHERS THEN
      RETURN 'CRITICAL';
  END classify_station_health;

  PROCEDURE region_health_report(
    p_region_name  IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
    p_critical_pct IN NUMBER
  ) IS
    co_row_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_region_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;

    CURSOR c_stations(p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.region_id%TYPE) IS
      SELECT si.station_id                          AS station_id,
             si.name                                AS station_name,
             TO_NUMBER(si.capacity)                 AS capacity,
             TO_NUMBER(NVL(ss.num_bikes_available, '0')) AS num_bikes
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
          ON ss.station_id = si.station_id
       WHERE si.region_id = p_region_id
       ORDER BY si.name;

    lr_station c_stations%ROWTYPE;
    lv_printed PLS_INTEGER := 0;
    lv_pct NUMBER;
    lv_status VARCHAR2(20);
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Region health report for: ' || p_region_name);
    DBMS_OUTPUT.PUT_LINE('Critical threshold (% bikes/capacity) = ' || p_critical_pct);
    DBMS_OUTPUT.PUT_LINE('Up to ' || co_row_limit || ' stations (by name).');

    SELECT r.region_id
      INTO lv_region_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE r.name = p_region_name;

    OPEN c_stations(lv_region_id);
    LOOP
      FETCH c_stations INTO lr_station;
      EXIT WHEN c_stations%NOTFOUND;

      lv_printed := lv_printed + 1;
      IF lv_printed > co_row_limit THEN
        EXIT;
      END IF;

      IF lr_station.capacity IS NULL OR lr_station.capacity = 0 THEN
        lv_pct := 0;
      ELSE
        lv_pct := (lr_station.num_bikes / lr_station.capacity) * 100;
      END IF;

      lv_status := classify_station_health(lr_station.num_bikes, lr_station.capacity, p_critical_pct);

      DBMS_OUTPUT.PUT_LINE(
        'Station ' || lr_station.station_id || ' - ' || lr_station.station_name ||
        ' | bikes=' || lr_station.num_bikes ||
        ' | cap=' || lr_station.capacity ||
        ' | pct=' || TO_CHAR(lv_pct, 'FM990.00') ||
        ' | status=' || lv_status
      );
    END LOOP;
    CLOSE c_stations;

    IF lv_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No stations found for this region.');
    END IF;

  EXCEPTION
    WHEN VALUE_ERROR THEN
      IF c_stations%ISOPEN THEN
        CLOSE c_stations;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Invalid numeric input.');
    WHEN NO_DATA_FOUND THEN
      IF c_stations%ISOPEN THEN
        CLOSE c_stations;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      IF c_stations%ISOPEN THEN
        CLOSE c_stations;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END region_health_report;
END station_health_pkg;
/

