CREATE OR REPLACE PROCEDURE review_suspicious_trips(
  p_region_name       IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
  p_min_duration_sec  IN NUMBER
) IS
  co_row_limit CONSTANT PLS_INTEGER := 15; -- Limit output for review readability

  lv_region_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;

  CURSOR c_trips(p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.region_id%TYPE) IS
    SELECT t.trip_id                AS trip_id,
           TO_NUMBER(t.duration_sec) AS duration_sec,
           t.subscriber_type        AS subscriber_type,
           si.name                  AS station_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        ON si.station_id = t.start_station_id
     WHERE si.region_id = p_region_id
       AND t.start_station_id = t.end_station_id
       AND TO_NUMBER(t.duration_sec) >= p_min_duration_sec
     ORDER BY TO_NUMBER(t.duration_sec) DESC;

  lr_trip c_trips%ROWTYPE;
  lv_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Suspicious trips review for region: ' || p_region_name);
  DBMS_OUTPUT.PUT_LINE('Minimum duration (sec) = ' || p_min_duration_sec);
  DBMS_OUTPUT.PUT_LINE('Up to ' || co_row_limit || ' trips where start=end station.');

  IF p_min_duration_sec IS NULL OR p_min_duration_sec <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid minimum duration. Provide a positive number.');
    RETURN;
  END IF;

  SELECT r.region_id
    INTO lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE r.name = p_region_name;

  OPEN c_trips(lv_region_id);
  LOOP
    FETCH c_trips INTO lr_trip;
    EXIT WHEN c_trips%NOTFOUND;

    lv_printed := lv_printed + 1;
    IF lv_printed > co_row_limit THEN
      EXIT;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Trip ' || lr_trip.trip_id ||
      ' | dur_sec=' || lr_trip.duration_sec ||
      ' | subscriber=' || lr_trip.subscriber_type ||
      ' | station=' || lr_trip.station_name
    );
  END LOOP;
  CLOSE c_trips;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No suspicious trips found for this region and threshold.');
  END IF;

EXCEPTION
  WHEN VALUE_ERROR THEN
    IF c_trips%ISOPEN THEN
      CLOSE c_trips;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Invalid numeric input.');
  WHEN NO_DATA_FOUND THEN
    IF c_trips%ISOPEN THEN
      CLOSE c_trips;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    IF c_trips%ISOPEN THEN
      CLOSE c_trips;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END review_suspicious_trips;
/

