CREATE OR REPLACE PROCEDURE report_cards_by_event(
  p_event_name_like IN WWE.EVENTS.name%TYPE,
  p_max_rows        IN NUMBER
) IS
  co_default_max_rows CONSTANT PLS_INTEGER := 15; -- Safety limit for report readability

  lv_max_rows PLS_INTEGER;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_max_rows IS NULL OR p_max_rows < 1 OR p_max_rows > co_default_max_rows THEN
    lv_max_rows := co_default_max_rows;
    DBMS_OUTPUT.PUT_LINE('Invalid max rows. Using default max rows = ' || co_default_max_rows);
  ELSE
    lv_max_rows := p_max_rows;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Report start: event name like = ' || NVL(p_event_name_like, 'NULL') || ', max rows = ' || NVL(TO_CHAR(p_max_rows), 'NULL'));

  FOR r IN (
    SELECT c.id AS id,
           e.name AS event_name,
           p.name AS promotion_name,
           l.name AS location_name,
           c.event_date AS event_date
      FROM WWE.CARDS c
      INNER JOIN WWE.EVENTS e
        ON e.id = c.event_id
      INNER JOIN WWE.PROMOTIONS p
        ON p.id = c.promotion_id
      INNER JOIN WWE.LOCATIONS l
        ON l.id = c.location_id
     WHERE (p_event_name_like IS NULL OR e.name LIKE p_event_name_like)
     ORDER BY c.id DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= lv_max_rows;
    DBMS_OUTPUT.PUT_LINE('CARD_ID=' || r.id || ' | EVENT=' || r.event_name || ' | PROMOTION=' || r.promotion_name || ' | LOCATION=' || r.location_name || ' | EVENT_DATE=' || r.event_date);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No cards matched the requested event filter.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
