CREATE OR REPLACE PROCEDURE report_top_winners_for_event(
  p_event_name IN WWE.EVENTS.name%TYPE,
  p_max_rows   IN NUMBER
) IS
  co_default_max_rows CONSTANT PLS_INTEGER := 15; -- Safety limit for report readability

  lv_max_rows PLS_INTEGER;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_max_rows IS NULL OR p_max_rows < 1 OR p_max_rows > co_default_max_rows THEN
    lv_max_rows := co_default_max_rows;
    DBMS_OUTPUT.PUT_LINE('Invalid max rows. Using default max rows = ' || co_default_max_rows);
  ELSE
    lv_max_rows := p_max_rows;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Winners report: event=' || NVL(p_event_name, 'NULL') || ', max rows=' || NVL(TO_CHAR(p_max_rows), 'NULL'));

  FOR r IN (
    SELECT w.name AS winner_name,
           COUNT(*) AS win_cnt
      FROM WWE.EVENTS e
      INNER JOIN WWE.CARDS c
        ON c.event_id = e.id
      INNER JOIN WWE.MATCHES m
        ON m.card_id = c.id
      INNER JOIN WWE.WRESTLERS w
        ON w.id = TO_NUMBER(m.winner_id)
     WHERE p_event_name IS NOT NULL
       AND e.name = p_event_name
       AND m.winner_id IS NOT NULL
     GROUP BY w.name
     ORDER BY COUNT(*) DESC, w.name ASC
  ) LOOP
    EXIT WHEN lv_rows_printed >= lv_max_rows;
    DBMS_OUTPUT.PUT_LINE('WINNER=' || r.winner_name || ' | WINS=' || r.win_cnt);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matches found for the given event.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_winners_for_event;
/

CREATE OR REPLACE PROCEDURE validate_event_match_data(
  p_event_name IN WWE.EVENTS.name%TYPE
) IS
  lv_bad_winner_cnt NUMBER := 0;
  lv_bad_title_cnt  NUMBER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Validation start: event=' || NVL(p_event_name, 'NULL'));

  IF p_event_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Event name is required.');
    RETURN;
  END IF;

  SELECT COUNT(*)
    INTO lv_bad_winner_cnt
    FROM WWE.EVENTS e
    INNER JOIN WWE.CARDS c
      ON c.event_id = e.id
    INNER JOIN WWE.MATCHES m
      ON m.card_id = c.id
   WHERE e.name = p_event_name
     AND m.winner_id IS NOT NULL
     AND NOT REGEXP_LIKE(m.winner_id, '^[0-9]+$');

  SELECT COUNT(*)
    INTO lv_bad_title_cnt
    FROM WWE.EVENTS e
    INNER JOIN WWE.CARDS c
      ON c.event_id = e.id
    INNER JOIN WWE.MATCHES m
      ON m.card_id = c.id
   WHERE e.name = p_event_name
     AND NVL(m.title_change, 0) <> 0
     AND (m.title_id IS NULL OR TRIM(m.title_id) = '');

  DBMS_OUTPUT.PUT_LINE('Invalid winner_id rows (non-numeric): ' || lv_bad_winner_cnt);
  DBMS_OUTPUT.PUT_LINE('Title change rows missing title_id: ' || lv_bad_title_cnt);

  IF lv_bad_winner_cnt = 0 AND lv_bad_title_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Status: OK');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Status: NEEDS_REVIEW');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END validate_event_match_data;
/

