question:
We need a quick report for a given season that shows the top teams by average home attendance. Use the HOME_GAME table and list up to 15 teams for the year, ordered by the calculated average attendance per game (attendance/games). If games is zero or missing, avoid crashing and print a clear message for that row.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Top teams by avg home attendance for year ' || lv_year || ':');
DBMS_OUTPUT.PUT_LINE(RPAD('TEAM', 6) || ' ' || RPAD('LG', 2) || ' ' || RPAD('GAMES', 5) || ' ' || RPAD('ATT', 10) || ' ' || 'AVG_ATT');
DBMS_OUTPUT.PUT_LINE(RPAD(rec.team_id, 6) || ' ' || RPAD(rec.league_id, 2) || ' ' || RPAD(TO_CHAR(rec.games), 5) || ' ' || RPAD(TO_CHAR(rec.attendance), 10) || ' ' || TO_CHAR(ROUND(rec.attendance / rec.games, 2)));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.team_id, 6) || ' ' || RPAD(rec.league_id, 2) || ' ' || RPAD(TO_CHAR(rec.games), 5) || ' ' || RPAD(TO_CHAR(rec.attendance), 10) || ' ' || 'AVG_ATT=N/A (games=0)');
DBMS_OUTPUT.PUT_LINE('No rows found for the given year.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No rows found for the given year.'
WHEN ZERO_DIVIDE THEN: 'Unexpected error.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_year BASEBALL.HOME_GAME.year%TYPE := 2010;
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top teams by avg home attendance for year ' || lv_year || ':');
  DBMS_OUTPUT.PUT_LINE(RPAD('TEAM', 6) || ' ' || RPAD('LG', 2) || ' ' || RPAD('GAMES', 5) || ' ' || RPAD('ATT', 10) || ' ' || 'AVG_ATT');

  FOR rec IN (
    SELECT hg.team_id,
           hg.league_id,
           hg.games,
           hg.attendance
      FROM BASEBALL.HOME_GAME hg
     WHERE hg.year = lv_year
       AND hg.attendance IS NOT NULL
       AND hg.games IS NOT NULL
     ORDER BY (hg.attendance / NULLIF(hg.games, 0)) DESC NULLS LAST
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    IF rec.games = 0 THEN
      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.team_id, 6) || ' ' || RPAD(rec.league_id, 2) || ' ' ||
        RPAD(TO_CHAR(rec.games), 5) || ' ' || RPAD(TO_CHAR(rec.attendance), 10) || ' ' ||
        'AVG_ATT=N/A (games=0)'
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.team_id, 6) || ' ' || RPAD(rec.league_id, 2) || ' ' ||
        RPAD(TO_CHAR(rec.games), 5) || ' ' || RPAD(TO_CHAR(rec.attendance), 10) || ' ' ||
        TO_CHAR(ROUND(rec.attendance / rec.games, 2))
      );
    END IF;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for the given year.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

