  lv_team_id BASEBALL.HOME_GAME.team_id%TYPE := 'NYA';

  lv_games      BASEBALL.HOME_GAME.games%TYPE;
  lv_attendance BASEBALL.HOME_GAME.attendance%TYPE;
  lv_avg_att    NUMBER;
  lv_label      VARCHAR2(10);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Team/year: ' || lv_team_id || '/' || lv_year);

  SELECT hg.games,
         hg.attendance
    INTO lv_games,
         lv_attendance
    FROM BASEBALL.HOME_GAME hg
   WHERE hg.year = lv_year
     AND hg.team_id = lv_team_id
     AND ROWNUM = 1;

  lv_avg_att := lv_attendance / lv_games;

  IF lv_avg_att >= 30000 THEN
    lv_label := 'HIGH';
  ELSE
    lv_label := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Avg home attendance: ' || TO_CHAR(ROUND(lv_avg_att, 2)) || ' => ' || lv_label);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Avg home attendance: N/A (games=0).');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

