DECLARE
  lv_year    BASEBALL.HOME_GAME.year%TYPE := 2010;
  lv_team_id BASEBALL.HOME_GAME.team_id%TYPE := 'NYA';

  lv_games      BASEBALL.HOME_GAME.games%TYPE;
  lv_attendance BASEBALL.HOME_GAME.attendance%TYPE;
  lv_avg_att    NUMBER;

  lv_w BASEBALL.TEAM.w%TYPE;
  lv_l BASEBALL.TEAM.l%TYPE;
  lv_season_label VARCHAR2(10);
BEGIN
  -- Attendance inputs (same basis as prior step)
  SELECT hg.games,
         hg.attendance
    INTO lv_games,
         lv_attendance
    FROM BASEBALL.HOME_GAME hg
   WHERE hg.year = lv_year
     AND hg.team_id = lv_team_id
     AND ROWNUM = 1;

  lv_avg_att := lv_attendance / lv_games;

  -- Team record; expect a single row for (year, team_id)
  SELECT t.w,
         t.l
    INTO lv_w,
         lv_l
    FROM BASEBALL.TEAM t
   WHERE t.year = lv_year
     AND t.team_id = lv_team_id;

  IF lv_w > lv_l THEN
    lv_season_label := 'SUCCESS';
  ELSE
    lv_season_label := 'STRUGGLE';
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Season summary: ' || lv_team_id || '/' || lv_year ||
    ' avg_att=' || TO_CHAR(ROUND(lv_avg_att, 2)) ||
    ' W-L=' || lv_w || '-' || lv_l ||
    ' => ' || lv_season_label
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

