CREATE OR REPLACE PROCEDURE rpt_patient_recent_encounters(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_full_name VARCHAR2(250);
  lv_has_rows  NUMBER;
BEGIN
  IF p_patient_id IS NULL OR TRIM(p_patient_id) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient id is required.');
    RETURN;
  END IF;

  SELECT INITCAP(p.first) || ' ' || INITCAP(p.last)
    INTO lv_full_name
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_full_name || ' (ID=' || p_patient_id || ')');
  DBMS_OUTPUT.PUT_LINE('Most recent encounters (max ' || co_report_limit || '):');

  SELECT COUNT(*)
    INTO lv_has_rows
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = p_patient_id;

  IF lv_has_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for this patient.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT e.start_timestamp AS start_ts,
           e.encounterclass,
           e.description,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
     ORDER BY e.start_timestamp DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | ' || rec.encounterclass ||
      ' | ' || rec.description ||
      ' | claim=' || TO_CHAR(rec.total_claim_cost)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_patient_recent_encounters;
/

