CREATE OR REPLACE PROCEDURE rpt_patient_top_encounterclass(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  lv_top_class SYNTHEA.ENCOUNTERS.encounterclass%TYPE;
  lv_top_cnt   NUMBER;
BEGIN
  IF p_patient_id IS NULL OR TRIM(p_patient_id) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient id is required.');
    RETURN;
  END IF;

  -- Count encounter classes and take the top one.
  SELECT x.encounterclass, x.cnt
    INTO lv_top_class, lv_top_cnt
    FROM (
      SELECT e.encounterclass, COUNT(*) AS cnt
        FROM SYNTHEA.ENCOUNTERS e
       WHERE e.patient = p_patient_id
       GROUP BY e.encounterclass
       ORDER BY COUNT(*) DESC
       FETCH FIRST 1 ROWS ONLY
    ) x;

  DBMS_OUTPUT.PUT_LINE(
    'Top encounter class for patient ' || p_patient_id || ': ' ||
    lv_top_class || ' (count=' || lv_top_cnt || ')'
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for this patient.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_patient_top_encounterclass;
/

