CREATE OR REPLACE PACKAGE patient_encounter_pkg IS
  FUNCTION get_total_claim_cost(
    p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
  ) RETURN NUMBER;

  PROCEDURE print_patient_cost_summary(
    p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
  );
END patient_encounter_pkg;
/

CREATE OR REPLACE PACKAGE BODY patient_encounter_pkg IS

  FUNCTION get_total_claim_cost(
    p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
  ) RETURN NUMBER IS
    lv_total NUMBER;
  BEGIN
    IF p_patient_id IS NULL OR TRIM(p_patient_id) IS NULL THEN
      RETURN NULL;
    END IF;

    SELECT SUM(e.total_claim_cost)
      INTO lv_total
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id;

    RETURN lv_total;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END get_total_claim_cost;

  PROCEDURE print_patient_cost_summary(
    p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
  ) IS
    lv_total_cost NUMBER;
    lv_enc_cnt    NUMBER;
  BEGIN
    IF p_patient_id IS NULL OR TRIM(p_patient_id) IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Patient id is required.');
      RETURN;
    END IF;

    SELECT COUNT(*)
      INTO lv_enc_cnt
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id;

    lv_total_cost := get_total_claim_cost(p_patient_id);

    DBMS_OUTPUT.PUT_LINE(
      'Patient ' || p_patient_id || ' totals: encounters=' || TO_CHAR(lv_enc_cnt) ||
      ', total_claim_cost=' || TO_CHAR(lv_total_cost)
    );

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_patient_cost_summary;

END patient_encounter_pkg;
/

