CREATE OR REPLACE PROCEDURE rpt_patient_claim_vs_meds(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_claim_total NUMBER;
  lv_meds_total  NUMBER;
  lv_enc_cnt     NUMBER;
BEGIN
  IF p_patient_id IS NULL OR TRIM(p_patient_id) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient id is required.');
    RETURN;
  END IF;

  SELECT COUNT(*)
    INTO lv_enc_cnt
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = p_patient_id;

  IF lv_enc_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for this patient.');
    RETURN;
  END IF;

  SELECT SUM(e.total_claim_cost)
    INTO lv_claim_total
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = p_patient_id;

  SELECT SUM(m.totalcost)
    INTO lv_meds_total
    FROM SYNTHEA.MEDICATIONS m
   WHERE m.patient = p_patient_id;

  DBMS_OUTPUT.PUT_LINE(
    'Patient ' || p_patient_id || ' totals: claim_total=' || TO_CHAR(lv_claim_total) ||
    ', meds_total=' || TO_CHAR(lv_meds_total)
  );

  IF NVL(lv_meds_total, 0) > NVL(lv_claim_total, 0) THEN
    DBMS_OUTPUT.PUT_LINE('WARNING: Medication total exceeds encounter claim total.');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top encounters by claim (max ' || co_report_limit || '):');

  FOR rec IN (
    SELECT e.start_timestamp AS start_ts,
           e.description,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
     ORDER BY e.total_claim_cost DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | ' || rec.description ||
      ' | claim=' || TO_CHAR(rec.total_claim_cost)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_patient_claim_vs_meds;
/

