    DBMS_OUTPUT.PUT_LINE('Warning condition not met: NVL(meds_total,0) <= NVL(claim_total,0)');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Medication sample (max ' || co_report_limit || '):');

  SELECT COUNT(*)
    INTO lv_med_cnt
    FROM SYNTHEA.MEDICATIONS m
   WHERE m.patient = p_patient_id;

  IF lv_med_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No medications found for this patient.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT m.totalcost,
           m.description
      FROM SYNTHEA.MEDICATIONS m
     WHERE m.patient = p_patient_id
     ORDER BY m.totalcost DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.totalcost) || ' | ' || rec.description);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END dbg_patient_claim_vs_meds;
/

