CREATE OR REPLACE PROCEDURE report_btc_recent_prices(
  p_ticker IN BANK_SALES_TRADING.BITCOIN_PRICES.ticker%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_ticker IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input ticker is NULL.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Recent prices for ticker=' || p_ticker || ' (max rows=' || co_report_limit || ')');

  FOR r IN (
    SELECT bp.market_date, bp.price, bp.open, bp.high, bp.low
      FROM BANK_SALES_TRADING.BITCOIN_PRICES bp
     WHERE bp.ticker = p_ticker
     ORDER BY TO_DATE(bp.market_date, 'YYYY-MM-DD') DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(TO_DATE(r.market_date, 'YYYY-MM-DD'), 'YYYY-MM-DD') ||
      ' price=' || r.price ||
      ' open=' || r.open ||
      ' high=' || r.high ||
      ' low=' || r.low
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No price history found for this ticker.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_btc_recent_prices;
