CREATE OR REPLACE PROCEDURE report_member_txn_activity(
  p_member_id IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE,
  p_ticker    IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_effective_ticker BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_member_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input member_id is NULL.');
    RETURN;
  END IF;

  IF p_ticker IS NOT NULL THEN
    lv_effective_ticker := p_ticker;
  ELSE
    -- Default to member's most frequently traded ticker
    SELECT ticker
      INTO lv_effective_ticker
      FROM (
        SELECT bt.ticker
          FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
         WHERE bt.member_id = p_member_id
         GROUP BY bt.ticker
         ORDER BY COUNT(*) DESC, bt.ticker
      )
     WHERE ROWNUM = 1;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Using ticker=' || lv_effective_ticker || ' for member_id=' || p_member_id || ' (max rows=' || co_report_limit || ')');

  FOR r IN (
    SELECT bt.txn_date, bt.txn_type, bt.quantity, bt.percentage_fee
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
     WHERE bt.member_id = p_member_id
       AND bt.ticker = lv_effective_ticker
     ORDER BY TO_DATE(bt.txn_date, 'YYYY-MM-DD') DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(TO_DATE(r.txn_date, 'YYYY-MM-DD'), 'YYYY-MM-DD') ||
      ' ' || r.txn_type ||
      ' qty=' || r.quantity ||
      ' fee%=' || r.percentage_fee
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No transactions found for this member/ticker filter.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No transactions found for this member/ticker filter.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_member_txn_activity;
/

CREATE OR REPLACE PROCEDURE report_suspicious_qty_days(
  p_member_id      IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE,
  p_qty_threshold  IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.quantity%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_member_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input member_id is NULL.');
    RETURN;
  END IF;

  IF p_qty_threshold IS NULL OR p_qty_threshold <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Input threshold is NULL or <= 0.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Suspicious quantity days for member_id=' || p_member_id || ' threshold=' || p_qty_threshold);

  FOR r IN (
    SELECT bt.txn_date, SUM(bt.quantity) AS total_qty
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
     WHERE bt.member_id = p_member_id
     GROUP BY bt.txn_date
    HAVING SUM(bt.quantity) > p_qty_threshold
     ORDER BY TO_DATE(bt.txn_date, 'YYYY-MM-DD') DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(TO_DATE(r.txn_date, 'YYYY-MM-DD'), 'YYYY-MM-DD') ||
      ' total_qty=' || r.total_qty
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No suspicious days found for this member.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_suspicious_qty_days;
/

CREATE OR REPLACE PROCEDURE report_member_traded_on_date(
  p_member_id    IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE,
  p_txn_date_str IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.txn_date%TYPE
) IS
  lv_txn_date DATE;
  lv_cnt NUMBER;
BEGIN
  IF p_member_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input member_id is NULL.');
    RETURN;
  END IF;

  IF p_txn_date_str IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input txn date string is NULL.');
    RETURN;
  END IF;

  lv_txn_date := TO_DATE(p_txn_date_str, 'YYYY-MM-DD');

  SELECT COUNT(*)
    INTO lv_cnt
    FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
   WHERE bt.member_id = p_member_id
     AND TO_DATE(bt.txn_date, 'YYYY-MM-DD') = lv_txn_date;

  IF lv_cnt > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Member ' || p_member_id || ' traded on ' || TO_CHAR(lv_txn_date, 'YYYY-MM-DD') || ': YES');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Member ' || p_member_id || ' traded on ' || TO_CHAR(lv_txn_date, 'YYYY-MM-DD') || ': NO');
  END IF;

EXCEPTION
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date format. Expected YYYY-MM-DD.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_member_traded_on_date;
/

CREATE OR REPLACE PROCEDURE rpt_country_fertility_mortality(
  p_country_name_like IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Report for country name like: ' || p_country_name_like);

  FOR r IN (
    SELECT
      f.year,
      f.total_fertility_rate,
      f.gross_reproduction_rate,
      f.sex_ratio_at_birth,
      m.life_expectancy
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
    LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
      ON m.country_name = f.country_name
     AND m.year = f.year
    WHERE UPPER(f.country_name) LIKE UPPER('%' || p_country_name_like || '%')
    ORDER BY f.year DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Year=' || r.year ||
      ' TFR=' || r.total_fertility_rate ||
      ' GRR=' || r.gross_reproduction_rate ||
      ' SRB=' || r.sex_ratio_at_birth ||
      ' LifeExp=' || r.life_expectancy
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matching rows found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_country_fertility_mortality;
/

CREATE OR REPLACE FUNCTION get_country_latest_key(
  p_country_name_exact IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE
) RETURN VARCHAR2 IS
  lv_key VARCHAR2(50);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Lookup country: ' || p_country_name_exact);

  SELECT c.country_code || ':' || f.year
    INTO lv_key
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
    INNER JOIN (
      SELECT f2.country_code, MAX(f2.year) AS year
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f2
        INNER JOIN CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m2
          ON m2.country_code = f2.country_code
         AND m2.year = f2.year
       GROUP BY f2.country_code
    ) f
      ON f.country_code = c.country_code
   WHERE c.country_name = p_country_name_exact;

  DBMS_OUTPUT.PUT_LINE('Key=' || lv_key);
  RETURN lv_key;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    DBMS_OUTPUT.PUT_LINE('No matching country/year found.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END get_country_latest_key;
/

