question:
Finally, build a single orchestration procedure that uses the exact-name key from the previous step and then prints a combined snapshot for that specific country/year, including crude birth rate, crude death rate, and growth rate alongside total fertility rate and life expectancy. Add clear guardrails: if the key cannot be derived or parsing the key fails, print a message and stop gracefully.

Requirements:
Procedure Name: run_country_snapshot
Parameters:
p_country_name_exact IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Snapshot request for: ' || p_country_name_exact);
DBMS_OUTPUT.PUT_LINE('Could not derive key for country.');
DBMS_OUTPUT.PUT_LINE('Key format invalid.');
DBMS_OUTPUT.PUT_LINE('CountryCode=' || lv_country_code || ' Year=' || lv_year);
DBMS_OUTPUT.PUT_LINE('TFR=' || lv_tfr || ' LifeExp=' || lv_lifeexp || ' CBR=' || lv_cbr || ' CDR=' || lv_cdr || ' Growth=' || lv_growth);
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Key parsing failed.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE run_country_snapshot(
  p_country_name_exact IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE
) IS
  lv_key VARCHAR2(50);
  lv_pos PLS_INTEGER;
  lv_country_code CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_code%TYPE;
  lv_year CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;

  lv_tfr CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_lifeexp CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY.life_expectancy%TYPE;
  lv_cbr CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_birth_rate%TYPE;
  lv_cdr CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_death_rate%TYPE;
  lv_growth CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.growth_rate%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Snapshot request for: ' || p_country_name_exact);

  lv_key := get_country_latest_key(p_country_name_exact);
  IF lv_key IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Could not derive key for country.');
    RETURN;
  END IF;

  lv_pos := INSTR(lv_key, ':');
  IF lv_pos = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Key format invalid.');
    RETURN;
  END IF;

  lv_country_code := SUBSTR(lv_key, 1, lv_pos - 1);
  lv_year := SUBSTR(lv_key, lv_pos + 1);

  IF lv_country_code IS NULL OR lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Key format invalid.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CountryCode=' || lv_country_code || ' Year=' || lv_year);

  -- Pull the specific country/year snapshot across the three subject-area tables.
  SELECT f.total_fertility_rate,
         m.life_expectancy,
         b.crude_birth_rate,
         b.crude_death_rate,
         b.growth_rate
    INTO lv_tfr, lv_lifeexp, lv_cbr, lv_cdr, lv_growth
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
    INNER JOIN CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
      ON m.country_code = f.country_code
     AND m.year = f.year
    INNER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
      ON b.country_code = f.country_code
     AND b.year = f.year
   WHERE f.country_code = lv_country_code
     AND f.year = lv_year;

  DBMS_OUTPUT.PUT_LINE(
    'TFR=' || lv_tfr ||
    ' LifeExp=' || lv_lifeexp ||
    ' CBR=' || lv_cbr ||
    ' CDR=' || lv_cdr ||
    ' Growth=' || lv_growth
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Key parsing failed.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END run_country_snapshot;
/

