     WHERE e.patient = p_patient_id
     ORDER BY e.start_timestamp DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(r.start_ts, 'YYYY-MM-DD HH24:MI:SS') || ' -> ' || TO_CHAR(r.stop_ts, 'YYYY-MM-DD HH24:MI:SS') || ' | class=' || r.encounter_class || ' | cost=' || r.total_claim_cost
