Parameters: p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Eligibility check for patient=' || p_patient_id);
DBMS_OUTPUT.PUT_LINE('Eligible=Y | Active careplan(s) found: ' || lv_active_cnt);
DBMS_OUTPUT.PUT_LINE('Eligible=N | No active careplans found.');
