question:
Debug a quality issue: some encounter records appear to have negative durations (stop before start). Write a diagnostic block that, for a given patient id, prints up to 15 such problematic encounters and a clear summary count at the end. Make it easy to tell whether the issue is real or just missing stop timestamps.

Requirements:
Procedure Name: Anonymous Block
Parameters: p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Debug: negative-duration encounters for patient=' || p_patient_id || ' (max rows = ' || co_report_limit || ')');
DBMS_OUTPUT.PUT_LINE('Encounter=' || r.encounter_id || ' | start=' || TO_CHAR(r.start_ts, 'YYYY-MM-DD HH24:MI:SS') || ' | stop=' || TO_CHAR(r.stop_ts, 'YYYY-MM-DD HH24:MI:SS') || ' | seconds_diff=' || r.seconds_diff);
DBMS_OUTPUT.PUT_LINE('Summary | negative_duration_count=' || lv_problem_cnt || ' | printed=' || lv_rows_printed);
DBMS_OUTPUT.PUT_LINE('Invalid input value.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid input value.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  p_patient_id SYNTHEA.PATIENTS.id%TYPE := 'REPLACE_WITH_PATIENT_ID';
  lv_rows_printed PLS_INTEGER := 0;
  lv_problem_cnt NUMBER := 0;
BEGIN
  IF p_patient_id IS NULL OR LENGTH(TRIM(p_patient_id)) = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Debug: negative-duration encounters for patient=' || p_patient_id || ' (max rows = ' || co_report_limit || ')');

  FOR r IN (
    SELECT e.id AS encounter_id,
           e.start_timestamp AS start_ts,
           e.stop_timestamp AS stop_ts,
           ((CAST(e.stop_timestamp AS DATE) - CAST(e.start_timestamp AS DATE)) * 86400) AS seconds_diff
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
       AND e.stop_timestamp IS NOT NULL
       AND e.start_timestamp IS NOT NULL
       AND e.stop_timestamp < e.start_timestamp
     ORDER BY e.start_timestamp DESC
  ) LOOP
    lv_problem_cnt := lv_problem_cnt + 1;

    IF lv_rows_printed < co_report_limit THEN
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE(
        'Encounter=' || r.encounter_id || ' | start=' || TO_CHAR(r.start_ts, 'YYYY-MM-DD HH24:MI:SS') || ' | stop=' || TO_CHAR(r.stop_ts, 'YYYY-MM-DD HH24:MI:SS') || ' | seconds_diff=' || r.seconds_diff
      );
    END IF;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Summary | negative_duration_count=' || lv_problem_cnt || ' | printed=' || lv_rows_printed);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

