question:
Create an anonymous PL/SQL report that helps our demographic analysts quickly spot the most recent fertility picture for a single country. The report should accept a country name, find the latest available YEAR for that country in the age-specific fertility table, and then print up to 15 rows (most-recent year first) showing the total fertility rate and age-band fertility rates. Treat the numeric fertility fields as strings in the table but present them as numbers where possible; if a field cannot be converted to a number, print it as NULL.

Requirements:
Procedure Name: Anonymous Block
Parameters:
None
Output:
DBMS_OUTPUT.PUT_LINE('Fertility report for: ' || lv_country_name || ' (latest year=' || lv_latest_year || ')');
DBMS_OUTPUT.PUT_LINE('YEAR=' || rec.year || ' TFR=' || TO_CHAR(rec.tfr) || ' 15_19=' || TO_CHAR(rec.fr_15_19) || ' 20_24=' || TO_CHAR(rec.fr_20_24) || ' 25_29=' || TO_CHAR(rec.fr_25_29) || ' 30_34=' || TO_CHAR(rec.fr_30_34) || ' 35_39=' || TO_CHAR(rec.fr_35_39) || ' 40_44=' || TO_CHAR(rec.fr_40_44) || ' 45_49=' || TO_CHAR(rec.fr_45_49));
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

tests:
SET SERVEROUTPUT ON;
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15;
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE := 'Bhutan';
  lv_latest_year  CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;
  CURSOR c_fert(p_country CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
                p_latest_year CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE) IS
    SELECT a.year,
           CASE WHEN REGEXP_LIKE(a.total_fertility_rate, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.total_fertility_rate)) ELSE NULL END AS tfr,
           CASE WHEN REGEXP_LIKE(a.fertility_rate_15_19, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.fertility_rate_15_19)) ELSE NULL END AS fr_15_19,
           CASE WHEN REGEXP_LIKE(a.fertility_rate_20_24, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.fertility_rate_20_24)) ELSE NULL END AS fr_20_24,
           CASE WHEN REGEXP_LIKE(a.fertility_rate_25_29, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.fertility_rate_25_29)) ELSE NULL END AS fr_25_29,
           CASE WHEN REGEXP_LIKE(a.fertility_rate_30_34, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.fertility_rate_30_34)) ELSE NULL END AS fr_30_34,
           CASE WHEN REGEXP_LIKE(a.fertility_rate_35_39, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.fertility_rate_35_39)) ELSE NULL END AS fr_35_39,
           CASE WHEN REGEXP_LIKE(a.fertility_rate_40_44, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.fertility_rate_40_44)) ELSE NULL END AS fr_40_44,
           CASE WHEN REGEXP_LIKE(a.fertility_rate_45_49, '^\s*[-+]?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(a.fertility_rate_45_49)) ELSE NULL END AS fr_45_49
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
     WHERE a.country_name = p_country
       AND a.year <= p_latest_year
     ORDER BY a.year DESC;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  SELECT MAX(a.year) INTO lv_latest_year FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a WHERE a.country_name = lv_country_name;
  DBMS_OUTPUT.PUT_LINE('Fertility report for: ' || lv_country_name || ' (latest year=' || lv_latest_year || ')');
  FOR rec IN c_fert(lv_country_name, lv_latest_year) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;
    DBMS_OUTPUT.PUT_LINE('YEAR=' || rec.year || ' TFR=' || TO_CHAR(rec.tfr) || ' 15_19=' || TO_CHAR(rec.fr_15_19) || ' 20_24=' || TO_CHAR(rec.fr_20_24) || ' 25_29=' || TO_CHAR(rec.fr_25_29) || ' 30_34=' || TO_CHAR(rec.fr_30_34) || ' 35_39=' || TO_CHAR(rec.fr_35_39) || ' 40_44=' || TO_CHAR(rec.fr_40_44) || ' 45_49=' || TO_CHAR(rec.fr_45_49));
  END LOOP;
EXCEPTION WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No data found.'); WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('Multiple rows returned.'); WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error.'); END;
