question:
We have occasional data quality issues where numeric metrics are stored as non-numeric text. Build a package that validates and summarizes those issues for a given country and year range, using the same two metrics from the previous procedure (TFR and CRUDE_BIRTH_RATE). The package should expose a function that returns the number of "bad numeric" rows found (where the value exists but cannot be converted to a number) across both tables. It should also expose a procedure that prints up to 15 offending rows with the table name, year, and the raw text value.

Requirements:
Procedure Name: pkg_country_metric_dq
Parameters:
None
Output:
DBMS_OUTPUT.PUT_LINE('DQ Summary for: ' || p_country_name || ' years ' || p_year_from || '-' || p_year_to);
DBMS_OUTPUT.PUT_LINE('Bad numeric count=' || TO_CHAR(lv_bad_count));
DBMS_OUTPUT.PUT_LINE('TABLE=' || rec.src_table || ' YEAR=' || rec.year || ' RAW_VALUE=' || rec.raw_value);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE pkg_country_metric_dq IS
  FUNCTION count_bad_numeric(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) RETURN NUMBER;

  PROCEDURE print_bad_numeric(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  );
END pkg_country_metric_dq;
/

CREATE OR REPLACE PACKAGE BODY pkg_country_metric_dq IS

  FUNCTION count_bad_numeric(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) RETURN NUMBER IS
    lv_bad_count NUMBER := 0;
  BEGIN
    SELECT COUNT(*)
      INTO lv_bad_count
      FROM (
        SELECT a.total_fertility_rate AS raw_value
          FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
         WHERE a.country_name = p_country_name
           AND a.year BETWEEN p_year_from AND p_year_to
           AND a.total_fertility_rate IS NOT NULL
           AND NOT REGEXP_LIKE(a.total_fertility_rate, '^\s*[-+]?\d+(\.\d+)?\s*$')
        UNION ALL
        SELECT b.crude_birth_rate AS raw_value
          FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
         WHERE b.country_name = p_country_name
           AND b.year BETWEEN p_year_from AND p_year_to
           AND b.crude_birth_rate IS NOT NULL
           AND NOT REGEXP_LIKE(b.crude_birth_rate, '^\s*[-+]?\d+(\.\d+)?\s*$')
      );

    RETURN lv_bad_count;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN 0;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN 0;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN 0;
  END count_bad_numeric;


  PROCEDURE print_bad_numeric(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_bad IS
      SELECT src_table, year, raw_value
        FROM (
          SELECT 'AGE_SPECIFIC_FERTILITY_RATES' AS src_table,
                 a.year,
                 a.total_fertility_rate AS raw_value
            FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
           WHERE a.country_name = p_country_name
             AND a.year BETWEEN p_year_from AND p_year_to
             AND a.total_fertility_rate IS NOT NULL
             AND NOT REGEXP_LIKE(a.total_fertility_rate, '^\s*[-+]?\d+(\.\d+)?\s*$')
          UNION ALL
          SELECT 'BIRTH_DEATH_GROWTH_RATES' AS src_table,
                 b.year,
                 b.crude_birth_rate AS raw_value
            FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
           WHERE b.country_name = p_country_name
             AND b.year BETWEEN p_year_from AND p_year_to
             AND b.crude_birth_rate IS NOT NULL
             AND NOT REGEXP_LIKE(b.crude_birth_rate, '^\s*[-+]?\d+(\.\d+)?\s*$')
        )
       ORDER BY year DESC, src_table ASC;

    lv_rows_printed PLS_INTEGER := 0;
    lv_bad_count    NUMBER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('DQ Summary for: ' || p_country_name || ' years ' || p_year_from || '-' || p_year_to);

    lv_bad_count := count_bad_numeric(p_country_name, p_year_from, p_year_to);
    DBMS_OUTPUT.PUT_LINE('Bad numeric count=' || TO_CHAR(lv_bad_count));

    FOR rec IN c_bad LOOP
      lv_rows_printed := lv_rows_printed + 1;
      EXIT WHEN lv_rows_printed > co_report_limit;
      DBMS_OUTPUT.PUT_LINE('TABLE=' || rec.src_table || ' YEAR=' || rec.year || ' RAW_VALUE=' || rec.raw_value);
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_bad_numeric;

END pkg_country_metric_dq;
/

