CREATE OR REPLACE PROCEDURE classify_natural_increase(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE,
  p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
  p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_years IS
    SELECT b.year,
           CASE WHEN REGEXP_LIKE(b.crude_birth_rate, '^\s*[-+]?\d+(\.\d+)?\s*$')
                THEN TO_NUMBER(TRIM(b.crude_birth_rate))
                ELSE NULL
           END AS cbr,
           CASE WHEN REGEXP_LIKE(b.crude_death_rate, '^\s*[-+]?\d+(\.\d+)?\s*$')
                THEN TO_NUMBER(TRIM(b.crude_death_rate))
                ELSE NULL
           END AS cdr
      FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
     WHERE b.country_name = p_country_name
       AND b.year BETWEEN p_year_from AND p_year_to
     ORDER BY b.year DESC;

  lv_rows_printed PLS_INTEGER := 0;
  lv_diff         NUMBER;
  lv_status       VARCHAR2(20);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Natural increase classification for: ' || p_country_name || ' years ' || p_year_from || '-' || p_year_to);

  FOR rec IN c_years LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    IF rec.cbr IS NULL OR rec.cdr IS NULL THEN
      lv_diff := NULL;
      lv_status := 'UNKNOWN';
    ELSE
      lv_diff := rec.cbr - rec.cdr;

      IF lv_diff > 1 THEN
        lv_status := 'GROWING';
      ELSIF lv_diff >= -1 THEN
        lv_status := 'STABLE';
      ELSE
        lv_status := 'DECLINING';
      END IF;
    END IF;

    DBMS_OUTPUT.PUT_LINE('YEAR=' || rec.year || ' CBR=' || TO_CHAR(rec.cbr) || ' CDR=' || TO_CHAR(rec.cdr) || ' DIFF=' || TO_CHAR(lv_diff) || ' STATUS=' || lv_status);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
