  lv_calendar_year COMPLEX_ORACLE.TIMES.calendar_year%TYPE;

  lv_row_count PLS_INTEGER := 0;
BEGIN
  -- Pick a commonly used channel_id and year to make the block deterministic.
  SELECT s.channel_id, t.calendar_year
    INTO lv_channel_id, lv_calendar_year
    FROM COMPLEX_ORACLE.SALES s
    JOIN COMPLEX_ORACLE.TIMES t
      ON t.time_id = s.time_id
   GROUP BY s.channel_id, t.calendar_year
   ORDER BY COUNT(*) DESC
   FETCH FIRST 1 ROWS ONLY;

  DBMS_OUTPUT.PUT_LINE('Sales pulse for channel_id=' || lv_channel_id || ', year=' || lv_calendar_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('Product', 35) || ' | ' || LPAD('Qty', 10) || ' | ' || LPAD('Amount', 14));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || LPAD('-', 14, '-'));

  FOR rec IN (
    SELECT p.prod_name,
           SUM(s.quantity_sold) qty_sold,
