  BEGIN
    IF p_channel_id IS NULL OR p_calendar_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input channel_id or calendar year is NULL.');
      RETURN;
    END IF;

    -- Debugging fix: explicitly count matching sales rows so "No data found" is accurate.
    SELECT COUNT(*)
      INTO lv_sales_rows
      FROM COMPLEX_ORACLE.SALES s
      JOIN COMPLEX_ORACLE.TIMES t
        ON t.time_id = s.time_id
     WHERE s.channel_id = p_channel_id
       AND t.calendar_year = p_calendar_year;

    DBMS_OUTPUT.PUT_LINE('Sales pulse for channel_id=' || p_channel_id || ', year=' || p_calendar_year);
    DBMS_OUTPUT.PUT_LINE(RPAD('Product', 35) || ' | ' || LPAD('Qty', 10) || ' | ' || LPAD('Amount', 14));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || LPAD('-', 14, '-'));

    FOR rec IN (
      SELECT p.prod_name,
             SUM(s.quantity_sold) qty_sold,
             SUM(s.amount_sold)   amt_sold
        FROM COMPLEX_ORACLE.SALES s
        JOIN COMPLEX_ORACLE.TIMES t
          ON t.time_id = s.time_id
        JOIN COMPLEX_ORACLE.PRODUCTS p
          ON p.prod_id = s.prod_id
       WHERE s.channel_id = p_channel_id
         AND t.calendar_year = p_calendar_year
       GROUP BY p.prod_name
       ORDER BY SUM(s.amount_sold) DESC
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;

      IF rec.qty_sold IS NULL OR rec.amt_sold IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Warning: NULL totals detected for product=' || rec.prod_name);
      END IF;

      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.prod_name, 35) || ' | ' ||
        LPAD(TO_CHAR(NVL(rec.qty_sold, 0)), 10) || ' | ' ||
        LPAD(TO_CHAR(NVL(rec.amt_sold, 0)), 14)
      );
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Diagnostic: rows_printed=' || lv_rows_printed);

    IF lv_sales_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_channel_year_pulse;

END sales_reporting_pkg;
