question:
Now add a safety check on top of the monthly snapshot: given a channel id and a maximum allowed average unit price, scan up to 15 recent COSTS rows for that channel and flag whether any unit_price exceeds the threshold. Print a PASS/FAIL summary and print each offending product id with its unit price.

Requirements:
Procedure Name: Anonymous Block.
Parameters:
p_channel_id IN COMPLEX_ORACLE.COSTS.channel_id%TYPE.
p_max_avg_unit_price IN COMPLEX_ORACLE.COSTS.unit_price%TYPE.
Output:
DBMS_OUTPUT.PUT_LINE('Channel id is required.');
DBMS_OUTPUT.PUT_LINE('Max unit price is required.');
DBMS_OUTPUT.PUT_LINE('Cost price check for channel ' || p_channel_id || ' (max rows = ' || co_report_limit || ')');
DBMS_OUTPUT.PUT_LINE('FAIL: prod_id=' || rec.prod_id || ', unit_price=' || rec.unit_price);
DBMS_OUTPUT.PUT_LINE('PASS: No unit_price values exceed the threshold.');
DBMS_OUTPUT.PUT_LINE('FAIL: ' || lv_fail_count || ' cost rows exceed the threshold.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No cost rows found for this channel.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  p_channel_id          COMPLEX_ORACLE.COSTS.channel_id%TYPE := NULL;
  p_max_avg_unit_price  COMPLEX_ORACLE.COSTS.unit_price%TYPE := NULL;
  co_report_limit       CONSTANT PLS_INTEGER := 15; -- Limit output for review
  lv_checked_count      NUMBER := 0;
  lv_fail_count         NUMBER := 0;
BEGIN
  IF p_channel_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Channel id is required.');
    RETURN;
  END IF;

  IF p_max_avg_unit_price IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Max unit price is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Cost price check for channel ' || p_channel_id || ' (max rows = ' || co_report_limit || ')');

  FOR rec IN (
    SELECT c.prod_id,
           c.unit_price
      FROM COMPLEX_ORACLE.COSTS c
     WHERE c.channel_id = p_channel_id
     ORDER BY c.time_id DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_checked_count := lv_checked_count + 1;

    IF rec.unit_price > p_max_avg_unit_price THEN
      lv_fail_count := lv_fail_count + 1;
      DBMS_OUTPUT.PUT_LINE('FAIL: prod_id=' || rec.prod_id || ', unit_price=' || rec.unit_price);
    END IF;
  END LOOP;

  IF lv_checked_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No cost rows found for this channel.');
  ELSIF lv_fail_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('PASS: No unit_price values exceed the threshold.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('FAIL: ' || lv_fail_count || ' cost rows exceed the threshold.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No cost rows found for this channel.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

