CREATE OR REPLACE PACKAGE cpiu_pkg IS
  FUNCTION classify_avg(
    p_avg_value IN NUMBER
  ) RETURN VARCHAR2;

  PROCEDURE print_year_summary(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE,
    p_year      IN BLS.CPI_U.year%TYPE
  );
END cpiu_pkg;
/

CREATE OR REPLACE PACKAGE BODY cpiu_pkg IS
  FUNCTION classify_avg(
    p_avg_value IN NUMBER
  ) RETURN VARCHAR2 IS
  BEGIN
    IF p_avg_value < 100 THEN
      RETURN 'LOW';
    ELSIF p_avg_value < 200 THEN
      RETURN 'MID';
    ELSE
      RETURN 'HIGH';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN 'UNKNOWN';
  END classify_avg;

  PROCEDURE print_year_summary(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE,
    p_year      IN BLS.CPI_U.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_cpi IS
      SELECT c.period,
             c.c_date,
             c.value
        FROM BLS.CPI_U c
       WHERE c.area_name = p_area_name
         AND c.item_name = p_item_name
         AND c.year = p_year
       ORDER BY c.c_date ASC;

    lv_period BLS.CPI_U.period%TYPE;
    lv_c_date BLS.CPI_U.c_date%TYPE;
    lv_value  BLS.CPI_U.value%TYPE;

    lv_rows_printed PLS_INTEGER := 0;
    lv_sum_value    NUMBER := 0;
    lv_cnt_value    PLS_INTEGER := 0;
    lv_avg_value    NUMBER;
    lv_class        VARCHAR2(10);
  BEGIN
    DBMS_OUTPUT.PUT_LINE('CPI-U Year Summary');
    DBMS_OUTPUT.PUT_LINE('Area=' || NVL(p_area_name, 'NULL') || ' | Item=' || NVL(p_item_name, 'NULL') || ' | Year=' || NVL(p_year, 'NULL'));

    OPEN c_cpi;
    LOOP
      FETCH c_cpi INTO lv_period, lv_c_date, lv_value;
      EXIT WHEN c_cpi%NOTFOUND;

      lv_cnt_value := lv_cnt_value + 1;
      lv_sum_value := lv_sum_value + TO_NUMBER(lv_value);

      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE('PERIOD=' || lv_period || ' | C_DATE=' || TO_CHAR(lv_c_date, 'YYYY-MM-DD') || ' | VALUE=' || lv_value);
      EXIT WHEN lv_rows_printed >= co_report_limit;
    END LOOP;
    CLOSE c_cpi;

    IF lv_cnt_value = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

    lv_avg_value := lv_sum_value / lv_cnt_value;
    lv_class := classify_avg(lv_avg_value);

    DBMS_OUTPUT.PUT_LINE('AVG_VALUE=' || TO_CHAR(lv_avg_value) || ' | CLASS=' || lv_class);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the criteria.');
      IF c_cpi%ISOPEN THEN
        CLOSE c_cpi;
      END IF;
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric CPI value encountered.');
      IF c_cpi%ISOPEN THEN
        CLOSE c_cpi;
      END IF;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      IF c_cpi%ISOPEN THEN
        CLOSE c_cpi;
      END IF;
  END print_year_summary;
END cpiu_pkg;
/

