DECLARE
  co_rank_limit CONSTANT PLS_INTEGER := 10; -- Limit output for report readability

  lv_area_name BLS.CPI_U.area_name%TYPE;
  lv_item_name BLS.CPI_U.item_name%TYPE;
  lv_curr_year BLS.CPI_U.year%TYPE;
  lv_prev_year BLS.CPI_U.year%TYPE;

  CURSOR c_yoy IS
    WITH prev_year_data AS (
      SELECT c.period,
             TO_NUMBER(c.value) AS prev_val
        FROM BLS.CPI_U c
       WHERE c.area_name = lv_area_name
         AND c.item_name = lv_item_name
         AND c.year = lv_prev_year
    ),
    curr_year_data AS (
      SELECT c.period,
             TO_NUMBER(c.value) AS curr_val
        FROM BLS.CPI_U c
       WHERE c.area_name = lv_area_name
         AND c.item_name = lv_item_name
         AND c.year = lv_curr_year
    ),
    joined AS (
      SELECT cur.period,
             prv.prev_val,
             cur.curr_val,
             ABS(cur.curr_val - prv.prev_val) AS abs_change
        FROM curr_year_data cur
        INNER JOIN prev_year_data prv
          ON prv.period = cur.period
    ),
    ranked AS (
      SELECT j.period,
             j.prev_val,
             j.curr_val,
             j.abs_change,
             ROW_NUMBER() OVER (ORDER BY j.abs_change DESC, j.period ASC) AS rn
        FROM joined j
    )
    SELECT r.period,
           r.prev_val,
           r.curr_val,
           r.abs_change
      FROM ranked r
     WHERE r.rn <= co_rank_limit
     ORDER BY r.rn;

  lv_period     BLS.CPI_U.period%TYPE;
  lv_prev_val   NUMBER;
  lv_curr_val   NUMBER;
  lv_abs_change NUMBER;

  lv_rows PLS_INTEGER := 0;
BEGIN
  SELECT area_name, item_name, year
    INTO lv_area_name, lv_item_name, lv_curr_year
    FROM (
          SELECT c.area_name, c.item_name, c.year, COUNT(*) cnt
            FROM BLS.CPI_U c
           GROUP BY c.area_name, c.item_name, c.year
           ORDER BY COUNT(*) DESC
         )
   WHERE ROWNUM = 1;

  lv_prev_year := TO_CHAR(TO_NUMBER(lv_curr_year) - 1);

  DBMS_OUTPUT.PUT_LINE('Running current-year summary first...');
  cpiu_pkg.print_year_summary(lv_area_name, lv_item_name, lv_curr_year);

  DBMS_OUTPUT.PUT_LINE('YoY Top Changes (Previous Year=' || lv_prev_year || ', Current Year=' || lv_curr_year || ')');

  OPEN c_yoy;
  LOOP
    FETCH c_yoy INTO lv_period, lv_prev_val, lv_curr_val, lv_abs_change;
    EXIT WHEN c_yoy%NOTFOUND;

    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      'PERIOD=' || lv_period ||
      ' | PREV=' || TO_CHAR(lv_prev_val) ||
      ' | CURR=' || TO_CHAR(lv_curr_val) ||
      ' | ABS_CHANGE=' || TO_CHAR(lv_abs_change)
    );
  END LOOP;
  CLOSE c_yoy;

  IF lv_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    IF c_yoy%ISOPEN THEN
      CLOSE c_yoy;
    END IF;
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric CPI value encountered.');
    IF c_yoy%ISOPEN THEN
      CLOSE c_yoy;
    END IF;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_yoy%ISOPEN THEN
      CLOSE c_yoy;
    END IF;
END;

