CREATE OR REPLACE PACKAGE pick_dash_pkg IS
  PROCEDURE print_monthly_pick_report(
    p_mth IN ORACLE_SQL.MONTHLY_SALES.mth%TYPE
  );
END pick_dash_pkg;
/
CREATE OR REPLACE PACKAGE BODY pick_dash_pkg IS
  PROCEDURE print_monthly_pick_report(
    p_mth IN ORACLE_SQL.MONTHLY_SALES.mth%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows         PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Pick dashboard for month=' || NVL(p_mth, ''));
    DBMS_OUTPUT.PUT_LINE(RPAD('PRODUCT', 40) || ' | ' || LPAD('ORDER_QTY', 10) || ' | ' || LPAD('INVENTORY_QTY', 13));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 40, '-') || '-+-' || RPAD('-', 10, '-') || '-+-' || RPAD('-', 13, '-'));

    -- Aggregate monthly demand and join to current inventory on hand.
    FOR rec IN (
      WITH demand AS (
        SELECT ms.product_id,
               SUM(ms.qty) AS order_qty
          FROM ORACLE_SQL.MONTHLY_SALES ms
         WHERE ms.mth = p_mth
         GROUP BY ms.product_id
      ),
      inv AS (
        SELECT i.product_id,
               SUM(i.qty) AS inventory_qty
          FROM ORACLE_SQL.INVENTORY i
         GROUP BY i.product_id
      )
      SELECT p.name AS product_name,
             d.order_qty,
             NVL(iv.inventory_qty, 0) AS inventory_qty
        FROM demand d
        INNER JOIN ORACLE_SQL.PRODUCTS p
          ON p.id = d.product_id
        LEFT OUTER JOIN inv iv
          ON iv.product_id = d.product_id
       ORDER BY d.order_qty DESC, p.name ASC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.product_name, 40) || ' | ' ||
        LPAD(TO_CHAR(rec.order_qty), 10) || ' | ' ||
        LPAD(TO_CHAR(rec.inventory_qty), 13)
      );
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Total rows printed=' || TO_CHAR(lv_rows));

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched for the provided month.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_monthly_pick_report;
END pick_dash_pkg;
/

CREATE OR REPLACE PACKAGE pick_restock_pkg IS
  PROCEDURE print_restock_suggestions(
    p_mth IN ORACLE_SQL.MONTHLY_SALES.mth%TYPE
  );
END pick_restock_pkg;
/
CREATE OR REPLACE PACKAGE BODY pick_restock_pkg IS
  PROCEDURE print_restock_suggestions(
    p_mth IN ORACLE_SQL.MONTHLY_SALES.mth%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows         PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Restock suggestions for month=' || NVL(p_mth, ''));

    -- Treat NULL month as invalid input (explicitly tested via VALUE_ERROR handler).
    IF p_mth IS NULL THEN
      RAISE VALUE_ERROR;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD('PRODUCT', 40) || ' | ' || LPAD('ORDER_QTY', 10) || ' | ' ||
      LPAD('INV_QTY', 7) || ' | ' || LPAD('MIN_QTY', 7) || ' | ' || LPAD('SUGG_BUY', 8)
    );
    DBMS_OUTPUT.PUT_LINE(
      RPAD('-', 40, '-') || '-+-' || RPAD('-', 10, '-') || '-+-' ||
      RPAD('-', 7, '-') || '-+-' || RPAD('-', 7, '-') || '-+-' || RPAD('-', 8, '-')
    );

    FOR rec IN (
      WITH demand AS (
        SELECT ms.product_id,
               SUM(ms.qty) AS order_qty
          FROM ORACLE_SQL.MONTHLY_SALES ms
         WHERE ms.mth = p_mth
         GROUP BY ms.product_id
      ),
      inv AS (
        SELECT i.product_id,
               SUM(i.qty) AS inv_qty
          FROM ORACLE_SQL.INVENTORY i
         GROUP BY i.product_id
      )
      SELECT p.name AS product_name,
             d.order_qty,
             NVL(iv.inv_qty, 0) AS inv_qty,
             pm.qty_minimum AS min_qty,
             CASE
               WHEN NVL(iv.inv_qty, 0) < pm.qty_minimum THEN pm.qty_minimum - NVL(iv.inv_qty, 0)
               ELSE 0
             END AS sugg_buy
        FROM demand d
        INNER JOIN ORACLE_SQL.PRODUCTS p
          ON p.id = d.product_id
        INNER JOIN ORACLE_SQL.PRODUCT_MINIMUMS pm
          ON pm.product_id = d.product_id
        LEFT OUTER JOIN inv iv
          ON iv.product_id = d.product_id
       WHERE NVL(iv.inv_qty, 0) < pm.qty_minimum
       ORDER BY (pm.qty_minimum - NVL(iv.inv_qty, 0)) DESC, d.order_qty DESC, p.name ASC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.product_name, 40) || ' | ' ||
        LPAD(TO_CHAR(rec.order_qty), 10) || ' | ' ||
        LPAD(TO_CHAR(rec.inv_qty), 7) || ' | ' ||
        LPAD(TO_CHAR(rec.min_qty), 7) || ' | ' ||
        LPAD(TO_CHAR(rec.sugg_buy), 8)
      );
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Rows suggested=' || TO_CHAR(lv_rows));

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No at-risk products found for the provided month.');
    END IF;

  EXCEPTION
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: month is required.');
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_restock_suggestions;
END pick_restock_pkg;
/

CREATE OR REPLACE PACKAGE pick_diag_pkg IS
  PROCEDURE diagnose_product_inventory(
    p_mth        IN ORACLE_SQL.MONTHLY_SALES.mth%TYPE,
    p_product_id IN ORACLE_SQL.PRODUCTS.id%TYPE
  );
END pick_diag_pkg;
/
CREATE OR REPLACE PACKAGE BODY pick_diag_pkg IS
  PROCEDURE diagnose_product_inventory(
    p_mth        IN ORACLE_SQL.MONTHLY_SALES.mth%TYPE,
    p_product_id IN ORACLE_SQL.PRODUCTS.id%TYPE
  ) IS
    co_report_limit  CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_product_name  ORACLE_SQL.PRODUCTS.name%TYPE;
    lv_demand_qty    ORACLE_SQL.MONTHLY_SALES.qty%TYPE := 0;
    lv_has_minimums  VARCHAR2(5) := 'FALSE';
    lv_min_cnt       NUMBER;
    lv_rows          PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'DIAG month=' || NVL(p_mth, '') ||
      ', product_id=' || NVL(TO_CHAR(p_product_id), '')
    );

    IF p_mth IS NULL OR p_product_id IS NULL THEN
      RAISE VALUE_ERROR;
    END IF;

    SELECT p.name
      INTO lv_product_name
      FROM ORACLE_SQL.PRODUCTS p
     WHERE p.id = p_product_id;

    DBMS_OUTPUT.PUT_LINE('Product name=' || lv_product_name);

    -- Demand may not exist for this product/month combination; default to 0.
    SELECT NVL(SUM(ms.qty), 0)
      INTO lv_demand_qty
      FROM ORACLE_SQL.MONTHLY_SALES ms
     WHERE ms.mth = p_mth
       AND ms.product_id = p_product_id;

    DBMS_OUTPUT.PUT_LINE('Demand qty=' || TO_CHAR(lv_demand_qty));

    -- Minimums presence check (restock logic dependency).
    SELECT COUNT(*)
      INTO lv_min_cnt
      FROM ORACLE_SQL.PRODUCT_MINIMUMS pm
     WHERE pm.product_id = p_product_id;

    IF lv_min_cnt > 0 THEN
      lv_has_minimums := 'TRUE';
    ELSE
      lv_has_minimums := 'FALSE';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Has minimums row=' || lv_has_minimums);

    DBMS_OUTPUT.PUT_LINE(RPAD('LOCATION_ID', 12) || ' | ' || LPAD('INV_QTY', 10));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 12, '-') || '-+-' || RPAD('-', 10, '-'));

    FOR rec IN (
      SELECT i.location_id,
             SUM(i.qty) AS inv_qty
        FROM ORACLE_SQL.INVENTORY i
       WHERE i.product_id = p_product_id
       GROUP BY i.location_id
       ORDER BY SUM(i.qty) DESC, i.location_id ASC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(
        RPAD(TO_CHAR(rec.location_id), 12) || ' | ' || LPAD(TO_CHAR(rec.inv_qty), 10)
      );
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Inventory location rows printed=' || TO_CHAR(lv_rows));

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No inventory rows found for this product.');
    END IF;

  EXCEPTION
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: month and product_id are required.');
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END diagnose_product_inventory;
END pick_diag_pkg;
/

DECLARE
  lv_mth        ORACLE_SQL.MONTHLY_SALES.mth%TYPE;
  lv_product_id ORACLE_SQL.PRODUCTS.id%TYPE;
BEGIN
  -- Example call for quick manual execution.
  SELECT x.mth
    INTO lv_mth
    FROM (
      SELECT ms.mth
        FROM ORACLE_SQL.MONTHLY_SALES ms
       GROUP BY ms.mth
       ORDER BY COUNT(*) DESC, ms.mth ASC
    ) x
