  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

question:
Our demographic analyst needs a quick console report to understand which countries have the highest total fertility rate in a given year. Build an anonymous PL/SQL block that accepts a year value (as a variable in the block), prints a header, then lists up to 15 countries ordered by total fertility rate (highest first). The fertility columns are stored as text, so make sure you safely convert them to numbers and skip rows where conversion is not possible.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Top total fertility rates for year ' || lv_year || ':');
DBMS_OUTPUT.PUT_LINE(rp.country_name || ' | TFR=' || TO_CHAR(rp.tfr));
DBMS_OUTPUT.PUT_LINE('No rows available for the requested year.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No rows available for the requested year.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_year CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE := '2010';
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top total fertility rates for year ' || lv_year || ':');

  FOR rp IN (
    SELECT country_name,
           TO_NUMBER(total_fertility_rate) AS tfr
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES
     WHERE year = lv_year
       AND REGEXP_LIKE(total_fertility_rate, '^[0-9]+(\.[0-9]+)?$')
     ORDER BY TO_NUMBER(total_fertility_rate) DESC, country_name ASC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(rp.country_name || ' | TFR=' || TO_CHAR(rp.tfr));
  END LOOP;

  IF lv_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows available for the requested year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

