CREATE OR REPLACE PROCEDURE report_high_fertility(
  p_year     IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
  p_min_tfr  IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_min_tfr NUMBER := p_min_tfr;
  lv_rows    PLS_INTEGER := 0;
BEGIN
  IF lv_min_tfr IS NULL THEN
    lv_min_tfr := 0;
    DBMS_OUTPUT.PUT_LINE('Minimum TFR threshold is NULL; defaulting to 0.');
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'High fertility countries for year ' || p_year || ' (min TFR=' || TO_CHAR(lv_min_tfr) || '):'
  );

  FOR rp IN (
    SELECT country_name,
           TO_NUMBER(total_fertility_rate) AS tfr
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES
     WHERE year = p_year
       AND REGEXP_LIKE(total_fertility_rate, '^[0-9]+(\.[0-9]+)?$')
       AND TO_NUMBER(total_fertility_rate) >= lv_min_tfr
     ORDER BY TO_NUMBER(total_fertility_rate) DESC, country_name ASC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(rp.country_name || ' | TFR=' || TO_CHAR(rp.tfr));
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_high_fertility;
/

