CREATE OR REPLACE PACKAGE fertility_pkg IS
  PROCEDURE run_yearly_avg(
    p_start_year IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_end_year   IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_threshold  IN NUMBER
  );
END fertility_pkg;
/

CREATE OR REPLACE PACKAGE BODY fertility_pkg IS
  PROCEDURE run_yearly_avg(
    p_start_year IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_end_year   IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_threshold  IN NUMBER
  ) IS
    lv_year      VARCHAR2(4);
    lv_avg_tfr   NUMBER;
    lv_class     VARCHAR2(10);
    lv_threshold NUMBER := p_threshold;
  BEGIN
    IF lv_threshold IS NULL THEN
      lv_threshold := 0;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Yearly average TFR from ' || p_start_year || ' to ' || p_end_year || ' (threshold=' || TO_CHAR(lv_threshold) || '):'
    );

    FOR yr IN (
      SELECT year
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES
       WHERE year BETWEEN p_start_year AND p_end_year
       GROUP BY year
       ORDER BY year
    ) LOOP
      lv_year := yr.year;

      BEGIN
        SELECT AVG(TO_NUMBER(total_fertility_rate))
          INTO lv_avg_tfr
          FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES
         WHERE year = lv_year
           AND REGEXP_LIKE(total_fertility_rate, '^[0-9]+(\.[0-9]+)?$');

        IF lv_avg_tfr IS NULL THEN
          DBMS_OUTPUT.PUT_LINE(lv_year || ' | No numeric TFR rows.');
        ELSE
          IF lv_avg_tfr > lv_threshold THEN
            lv_class := 'High';
          ELSE
            lv_class := 'Low';
          END IF;

          DBMS_OUTPUT.PUT_LINE(lv_year || ' | AVG_TFR=' || TO_CHAR(lv_avg_tfr) || ' | CLASS=' || lv_class);
        END IF;

      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          DBMS_OUTPUT.PUT_LINE(lv_year || ' | No numeric TFR rows.');
        WHEN TOO_MANY_ROWS THEN
          DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
        WHEN OTHERS THEN
          DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      END;
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_yearly_avg;
END fertility_pkg;
/

