DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark      SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := NULL;
  lv_snapshot_time SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;

  lv_anomaly_cnt PLS_INTEGER := 0;
BEGIN
  IF lv_landmark IS NULL THEN
    lv_landmark := 'San Francisco';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Using landmark filter: ' || lv_landmark);

  SELECT MAX(bs.time)
    INTO lv_snapshot_time
    FROM SAN_FRANCISCO.BIKESHARE_STATUS bs;

  DBMS_OUTPUT.PUT_LINE('Latest status snapshot: ' || TO_CHAR(lv_snapshot_time, 'YYYY-MM-DD HH24:MI:SS'));
  DBMS_OUTPUT.PUT_LINE('Dockcount mismatch anomalies (max ' || co_report_limit || ' rows):');

  FOR rec IN (
    SELECT z.station_id,
           z.station_name,
           z.dockcount,
           z.bikes_available,
           z.docks_available,
           z.total_slots,
           z.diff_slots
      FROM (
            SELECT st.station_id AS station_id,
                   st.name AS station_name,
                   TO_NUMBER(st.dockcount) AS dockcount,
                   TO_NUMBER(bs.bikes_available) AS bikes_available,
                   TO_NUMBER(bs.docks_available) AS docks_available,
                   (TO_NUMBER(bs.bikes_available) + TO_NUMBER(bs.docks_available)) AS total_slots,
                   (TO_NUMBER(st.dockcount) - (TO_NUMBER(bs.bikes_available) + TO_NUMBER(bs.docks_available))) AS diff_slots
              FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
              INNER JOIN SAN_FRANCISCO.BIKESHARE_STATIONS st
                ON st.station_id = bs.station_id
             WHERE bs.time = lv_snapshot_time
               AND st.landmark = lv_landmark
               AND (TO_NUMBER(bs.bikes_available) + TO_NUMBER(bs.docks_available)) <> TO_NUMBER(st.dockcount)
             ORDER BY ABS(TO_NUMBER(st.dockcount) - (TO_NUMBER(bs.bikes_available) + TO_NUMBER(bs.docks_available))) DESC,
                      st.name ASC
           ) z
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_anomaly_cnt := lv_anomaly_cnt + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Station ' || rec.station_id || ' | ' || rec.station_name ||
      ' | dockcount=' || rec.dockcount ||
      ' | bikes=' || rec.bikes_available || ' | docks=' || rec.docks_available ||
      ' | total=' || rec.total_slots ||
      ' | diff=' || rec.diff_slots
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Anomalies printed: ' || lv_anomaly_cnt);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

