CREATE OR REPLACE PROCEDURE rpt_promo_title_changes(
  p_promotion_name IN WWE.PROMOTIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_promo_id   WWE.PROMOTIONS.id%TYPE;
  lv_promo_name WWE.PROMOTIONS.name%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_promotion_name IS NULL OR TRIM(p_promotion_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Promotion not found: ' || p_promotion_name);
    RETURN;
  END IF;

  SELECT p.id, p.name
    INTO lv_promo_id, lv_promo_name
    FROM WWE.PROMOTIONS p
   WHERE UPPER(p.name) = UPPER(p_promotion_name);

  DBMS_OUTPUT.PUT_LINE('Promotion: ' || lv_promo_name);

  FOR r IN (
    WITH recent_cards AS (
      SELECT c.id AS card_id,
             c.event_date,
             c.event_id,
             c.location_id
        FROM WWE.CARDS c
       WHERE c.promotion_id = lv_promo_id
         AND c.event_id IS NOT NULL
       ORDER BY c.id DESC
    ), limited_cards AS (
      SELECT rc.card_id, rc.event_date, rc.event_id, rc.location_id
        FROM recent_cards rc
       WHERE ROWNUM <= co_report_limit
    )
    SELECT e.name AS event_name,
           lc.event_date AS event_date,
           l.name AS location_name,
           mt.name AS match_type_name,
           ww.name AS winner_name,
           wl.name AS loser_name,
           b.name AS belt_name,
           m.title_change AS title_change
      FROM limited_cards lc
      INNER JOIN WWE.EVENTS e
        ON e.id = lc.event_id
      LEFT OUTER JOIN WWE.LOCATIONS l
        ON l.id = lc.location_id
      INNER JOIN WWE.MATCHES m
        ON m.card_id = lc.card_id
      LEFT OUTER JOIN WWE.MATCH_TYPES mt
        ON mt.id = TO_NUMBER(m.match_type_id)
      LEFT OUTER JOIN WWE.WRESTLERS ww
        ON ww.id = TO_NUMBER(m.winner_id)
      LEFT OUTER JOIN WWE.WRESTLERS wl
        ON wl.id = TO_NUMBER(m.loser_id)
      LEFT OUTER JOIN WWE.BELTS b
        ON b.id = TO_NUMBER(m.title_id)
     WHERE m.title_change = 1
     ORDER BY lc.card_id DESC, m.id DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE('Event: ' || r.event_name || ' | Date: ' || r.event_date || ' | Location: ' || r.location_name);
    DBMS_OUTPUT.PUT_LINE('  Match Type: ' || r.match_type_name);
    DBMS_OUTPUT.PUT_LINE('  Winner: ' || NVL(r.winner_name, 'UNKNOWN') || ' | Loser: ' || NVL(r.loser_name, 'UNKNOWN'));
    DBMS_OUTPUT.PUT_LINE('  Belt: ' || NVL(r.belt_name, 'N/A') || ' | Title Change: ' || CASE WHEN r.title_change = 1 THEN 'Y' ELSE 'N' END);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No title-change matches found for promotion: ' || lv_promo_name);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_promo_title_changes;
/

CREATE OR REPLACE PROCEDURE diag_promo_wrestler_id_issues(
  p_promotion_name IN WWE.PROMOTIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_promo_id   WWE.PROMOTIONS.id%TYPE;
  lv_promo_name WWE.PROMOTIONS.name%TYPE;

  lv_issue_cnt PLS_INTEGER := 0;

  lv_dummy NUMBER;
BEGIN
  IF p_promotion_name IS NULL OR TRIM(p_promotion_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Promotion not found: ' || p_promotion_name);
    RETURN;
  END IF;

  SELECT p.id, p.name
    INTO lv_promo_id, lv_promo_name
    FROM WWE.PROMOTIONS p
   WHERE UPPER(p.name) = UPPER(p_promotion_name);

  DBMS_OUTPUT.PUT_LINE('Promotion: ' || lv_promo_name || ' | Checking most recent cards, max rows = ' || co_report_limit);

  FOR r IN (
    WITH recent_cards AS (
      SELECT c.id AS card_id
        FROM WWE.CARDS c
       WHERE c.promotion_id = lv_promo_id
         AND c.event_id IS NOT NULL
       ORDER BY c.id DESC
    ), limited_cards AS (
      SELECT rc.card_id
        FROM recent_cards rc
       WHERE ROWNUM <= co_report_limit
    )
    SELECT lc.card_id,
           m.id AS match_id,
           m.winner_id,
           m.loser_id
      FROM limited_cards lc
      INNER JOIN WWE.MATCHES m
        ON m.card_id = lc.card_id
     ORDER BY lc.card_id DESC, m.id DESC
  ) LOOP
    -- Winner ID numeric check
    BEGIN
      lv_dummy := TO_NUMBER(r.winner_id);
    EXCEPTION
      WHEN VALUE_ERROR THEN
        lv_issue_cnt := lv_issue_cnt + 1;
        DBMS_OUTPUT.PUT_LINE('Issue: Non-numeric winner_id. Card=' || r.card_id || ' Match=' || r.match_id || ' winner_id=' || r.winner_id);
        lv_dummy := NULL;
    END;

    -- Winner existence check only if numeric conversion succeeded
    IF lv_dummy IS NOT NULL THEN
      BEGIN
        SELECT 1
          INTO lv_dummy
          FROM WWE.WRESTLERS w
         WHERE w.id = lv_dummy;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_issue_cnt := lv_issue_cnt + 1;
          DBMS_OUTPUT.PUT_LINE('Issue: Missing winner wrestler row. Card=' || r.card_id || ' Match=' || r.match_id || ' winner_id=' || r.winner_id);
      END;
    END IF;

    -- Loser ID numeric check
    BEGIN
      lv_dummy := TO_NUMBER(r.loser_id);
    EXCEPTION
      WHEN VALUE_ERROR THEN
        lv_issue_cnt := lv_issue_cnt + 1;
        DBMS_OUTPUT.PUT_LINE('Issue: Non-numeric loser_id. Card=' || r.card_id || ' Match=' || r.match_id || ' loser_id=' || r.loser_id);
        lv_dummy := NULL;
    END;

    -- Loser existence check only if numeric conversion succeeded
    IF lv_dummy IS NOT NULL THEN
      BEGIN
        SELECT 1
          INTO lv_dummy
          FROM WWE.WRESTLERS w
         WHERE w.id = lv_dummy;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_issue_cnt := lv_issue_cnt + 1;
          DBMS_OUTPUT.PUT_LINE('Issue: Missing loser wrestler row. Card=' || r.card_id || ' Match=' || r.match_id || ' loser_id=' || r.loser_id);
      END;
    END IF;
  END LOOP;

  IF lv_issue_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No wrestler-id issues found for promotion: ' || lv_promo_name);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END diag_promo_wrestler_id_issues;
/

CREATE OR REPLACE PROCEDURE rca_promo_title_change_dropouts(
  p_promotion_name IN WWE.PROMOTIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_promo_id   WWE.PROMOTIONS.id%TYPE;
  lv_promo_name WWE.PROMOTIONS.name%TYPE;

  lv_bad_match_type NUMBER := 0;
  lv_bad_winner     NUMBER := 0;
  lv_bad_loser      NUMBER := 0;
  lv_bad_title      NUMBER := 0;
BEGIN
  IF p_promotion_name IS NULL OR TRIM(p_promotion_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Promotion not found: ' || p_promotion_name);
    RETURN;
  END IF;

  SELECT p.id, p.name
    INTO lv_promo_id, lv_promo_name
    FROM WWE.PROMOTIONS p
   WHERE UPPER(p.name) = UPPER(p_promotion_name);

  DBMS_OUTPUT.PUT_LINE('Promotion: ' || lv_promo_name || ' | RCA window: most recent cards, max rows = ' || co_report_limit);

  WITH recent_cards AS (
    SELECT c.id AS card_id
      FROM WWE.CARDS c
     WHERE c.promotion_id = lv_promo_id
       AND c.event_id IS NOT NULL
     ORDER BY c.id DESC
  ), limited_cards AS (
    SELECT rc.card_id
      FROM recent_cards rc
     WHERE ROWNUM <= co_report_limit
  ), base_matches AS (
    SELECT m.match_type_id,
           m.winner_id,
           m.loser_id,
           m.title_id
      FROM limited_cards lc
      INNER JOIN WWE.MATCHES m
        ON m.card_id = lc.card_id
  )
  SELECT SUM(CASE WHEN bm.match_type_id IS NOT NULL AND NOT REGEXP_LIKE(bm.match_type_id, '^\d+$') THEN 1 ELSE 0 END),
         SUM(CASE WHEN bm.winner_id IS NOT NULL AND NOT REGEXP_LIKE(bm.winner_id, '^\d+$') THEN 1 ELSE 0 END),
         SUM(CASE WHEN bm.loser_id IS NOT NULL AND NOT REGEXP_LIKE(bm.loser_id, '^\d+$') THEN 1 ELSE 0 END),
         SUM(CASE WHEN bm.title_id IS NOT NULL AND NOT REGEXP_LIKE(bm.title_id, '^\d+$') THEN 1 ELSE 0 END)
    INTO lv_bad_match_type, lv_bad_winner, lv_bad_loser, lv_bad_title
    FROM base_matches bm;

  DBMS_OUTPUT.PUT_LINE('Counts in RCA window (any match, not just title changes):');
  DBMS_OUTPUT.PUT_LINE('  Non-numeric match_type_id: ' || lv_bad_match_type);
  DBMS_OUTPUT.PUT_LINE('  Non-numeric winner_id: ' || lv_bad_winner);
  DBMS_OUTPUT.PUT_LINE('  Non-numeric loser_id: ' || lv_bad_loser);
  DBMS_OUTPUT.PUT_LINE('  Non-numeric title_id: ' || lv_bad_title);

  DBMS_OUTPUT.PUT_LINE('Recommendation: In Turn 1, replace TO_NUMBER(...) joins with REGEXP_LIKE checks (e.g., LEFT JOIN match_types ON mt.id = CASE WHEN REGEXP_LIKE(m.match_type_id, ''^\d+$'') THEN TO_NUMBER(m.match_type_id) END) so bad IDs do not abort or filter rows.');

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
