CREATE OR REPLACE PROCEDURE wdi_top_indicators(
  p_country_code IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE
) IS
  co_report_limit CONSTANT NUMBER := 15; -- Limit output for report readability
  lv_rows_printed NUMBER := 0;
BEGIN
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Country code is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top indicators (max rows = ' || co_report_limit || ') for country ' || p_country_code);

  -- Implicit cursor loop: counts per indicator, requiring a matching series definition
  FOR r IN (
    SELECT q.indicator_code,
           q.description
      FROM (
            SELECT id.indicator_code,
                   csd.description,
                   COUNT(*) AS row_cnt
              FROM WORLD_BANK_WDI.INDICATORS_DATA id
              INNER JOIN WORLD_BANK_WDI.COUNTRY_SERIES_DEFINITIONS csd
                ON csd.country_code = id.country_code
               AND csd.series_code = id.indicator_code
             WHERE id.country_code = p_country_code
             GROUP BY id.indicator_code, csd.description
             ORDER BY COUNT(*) DESC, id.indicator_code
           ) q
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE('Indicator: ' || r.indicator_code || ' - ' || r.description);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No indicators found for this country.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END wdi_top_indicators;
/

