CREATE OR REPLACE PROCEDURE rpt_league_hr_leaders(
  p_year      IN BASEBALL.BATTING.year%TYPE,
  p_league_id IN BASEBALL.BATTING.league_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('HR leaders for year=' || p_year || ', league=' || p_league_id || ' (max rows=' || co_report_limit || ')');
  DBMS_OUTPUT.PUT_LINE(RPAD('HR', 6) || RPAD('PLAYER_ID', 15) || 'NAME');

  FOR r IN (
    SELECT *
    FROM (
      SELECT b.player_id AS player_id,
             (p.name_first || ' ' || p.name_last) AS name_full,
             SUM(b.hr) AS hr_total
        FROM BASEBALL.BATTING b
        INNER JOIN BASEBALL.PLAYER p
          ON p.player_id = b.player_id
       WHERE b.year = p_year
         AND b.league_id = p_league_id
       GROUP BY b.player_id, p.name_first, p.name_last
       ORDER BY SUM(b.hr) DESC, b.player_id
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(RPAD(TO_CHAR(r.hr_total), 6) || RPAD(r.player_id, 15) || r.name_full);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No batting data found for the requested year/league.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No batting data found for the requested year/league.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_league_hr_leaders;
