CREATE OR REPLACE PACKAGE BODY pkg_scouting IS
  PROCEDURE player_hr_buckets(
    p_year       IN BASEBALL.BATTING.year%TYPE,
    p_team_id    IN BASEBALL.BATTING.team_id%TYPE,
    p_high_hr    IN NUMBER,
    p_medium_hr  IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_rows_printed PLS_INTEGER := 0;
    lv_bucket       VARCHAR2(10);
  BEGIN
    IF p_high_hr < 0 OR p_medium_hr < 0 OR p_high_hr < p_medium_hr THEN
      RAISE VALUE_ERROR;
    END IF;

    DBMS_OUTPUT.PUT_LINE('HR buckets for year=' || p_year || ', team=' || p_team_id ||
                         ' (high>=' || p_high_hr || ', medium>=' || p_medium_hr ||
                         ', max rows=' || co_report_limit || ')');
    DBMS_OUTPUT.PUT_LINE(RPAD('BUCKET', 10) || RPAD('HR', 6) || RPAD('PLAYER_ID', 15) || 'NAME');

    FOR r IN (
      SELECT *
      FROM (
        SELECT b.player_id AS player_id,
               (p.name_first || ' ' || p.name_last) AS name_full,
               SUM(b.hr) AS hr_total
          FROM BASEBALL.BATTING b
          INNER JOIN BASEBALL.PLAYER p
            ON p.player_id = b.player_id
         WHERE b.year = p_year
           AND b.team_id = p_team_id
         GROUP BY b.player_id, p.name_first, p.name_last
         ORDER BY SUM(b.hr) DESC, b.player_id
      )
      WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;

      IF r.hr_total >= p_high_hr THEN
        lv_bucket := 'HIGH';
      ELSIF r.hr_total >= p_medium_hr THEN
        lv_bucket := 'MEDIUM';
      ELSE
        lv_bucket := 'LOW';
      END IF;

      DBMS_OUTPUT.PUT_LINE(RPAD(lv_bucket, 10) || RPAD(TO_CHAR(r.hr_total), 6) || RPAD(r.player_id, 15) || r.name_full);
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No batting data found for the requested year/team.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No batting data found for the requested year/team.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid thresholds: high must be >= medium and both must be >= 0.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END player_hr_buckets;
END pkg_scouting;
/

