  DBMS_OUTPUT.PUT_LINE('Calling bucket report...');
  pkg_scouting.player_hr_buckets(lv_year, lv_team_id, 30, 10);
  FOR r IN (
    SELECT * FROM (
      SELECT b.player_id AS player_id, b.league_id AS league_id, SUM(b.hr) AS hr_total
