        INNER JOIN BASEBALL.PLAYER p ON p.player_id = b.player_id
       WHERE b.year = lv_year AND b.team_id = lv_team_id AND b.league_id IS NOT NULL
       GROUP BY b.player_id, b.league_id
       ORDER BY SUM(b.hr) DESC, b.player_id
    ) WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_found_rows := lv_found_rows + 1;
