CREATE OR REPLACE FUNCTION is_station_usable(
  p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
) RETURN VARCHAR2 IS
  lv_installed SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_installed%TYPE;
  lv_renting   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_renting%TYPE;
  lv_returning SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_returning%TYPE;
  lv_result    VARCHAR2(1);
  lv_dummy     SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
BEGIN
  -- Ensure the station exists (avoids treating missing station as simply "not usable").
  SELECT si.station_id
    INTO lv_dummy
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
   WHERE si.station_id = p_station_id;

  SELECT ss.is_installed, ss.is_renting, ss.is_returning
    INTO lv_installed, lv_renting, lv_returning
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
   WHERE ss.station_id = p_station_id;

  DBMS_OUTPUT.PUT_LINE('Station ' || p_station_id || ' flags: installed=' || lv_installed || ', renting=' || lv_renting || ', returning=' || lv_returning);

  IF lv_installed = '1' AND lv_renting = '1' AND lv_returning = '1' THEN
    lv_result := 'Y';
    DBMS_OUTPUT.PUT_LINE('Station ' || p_station_id || ' usable=Y');
  ELSE
    lv_result := 'N';
    DBMS_OUTPUT.PUT_LINE('Station ' || p_station_id || ' usable=N');
  END IF;

  RETURN lv_result;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'N';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'N';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'N';
END is_station_usable;
/

