    p_only_usable  IN VARCHAR2
  );
END bikeshare_ops;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops IS

  PROCEDURE run_region_health(
    p_region_name  IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
    p_only_usable  IN VARCHAR2
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_region_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
    lv_region_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
    lv_only_usable VARCHAR2(1);
  BEGIN
    IF NVL(p_only_usable, 'N') = 'Y' THEN
      lv_only_usable := 'Y';
      DBMS_OUTPUT.PUT_LINE('Mode: only usable stations');
    ELSE
      lv_only_usable := 'N';
      DBMS_OUTPUT.PUT_LINE('Mode: all stations');
    END IF;

    SELECT r.region_id, r.name
      INTO lv_region_id, lv_region_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE r.name = p_region_name;

    DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region_name);
    DBMS_OUTPUT.PUT_LINE('Stations (ordered by name), max rows = ' || co_report_limit);

    FOR lr IN (
      SELECT *
        FROM (
          SELECT si.station_id AS station_id,
                 si.name AS station_name,
                 NVL(ss.num_bikes_available, 'N/A') AS bikes_avail,
                 NVL(ss.num_docks_available, 'N/A') AS docks_avail,
                 NVL(ss.is_renting, 'N/A') AS is_renting,
                 NVL(ss.is_returning, 'N/A') AS is_returning,
                 CASE
                   WHEN ss.is_installed = '1' AND ss.is_renting = '1' AND ss.is_returning = '1' THEN 'Y'
                   ELSE 'N'
                 END AS usable
            FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
            LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
              ON ss.station_id = si.station_id
           WHERE si.region_id = lv_region_id
             AND (lv_only_usable = 'N'
                  OR (ss.is_installed = '1' AND ss.is_renting = '1' AND ss.is_returning = '1'))
           ORDER BY si.name
        )
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      DBMS_OUTPUT.PUT_LINE('Station ' || lr.station_id || ' - ' || lr.station_name || ': bikes=' || lr.bikes_avail || ', docks=' || lr.docks_avail || ', renting=' || lr.is_renting || ', returning=' || lr.is_returning || ', usable=' || lr.usable);
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_region_health;

END bikeshare_ops;
/

