    p_picklist_id IN ORACLE_SQL.PICKING_LIST.id%TYPE
  );
END pkg_picking_ops;
/

CREATE OR REPLACE PACKAGE BODY pkg_picking_ops IS
  PROCEDURE print_picklist_summary(
    p_picklist_id IN ORACLE_SQL.PICKING_LIST.id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_created     ORACLE_SQL.PICKING_LIST.created%TYPE;
    lv_picker_id   ORACLE_SQL.PICKING_LIST.picker_emp_id%TYPE;
    lv_picker_name ORACLE_SQL.EMPLOYEES.name%TYPE;
    lv_line_cnt    NUMBER;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Picklist: ' || p_picklist_id);

    -- Header (single-row fetch). If missing, NO_DATA_FOUND is raised.
    SELECT pl.created,
           pl.picker_emp_id
      INTO lv_created,
           lv_picker_id
      FROM ORACLE_SQL.PICKING_LIST pl
     WHERE pl.id = p_picklist_id;

    -- Picker name is optional.
    IF lv_picker_id IS NULL THEN
      lv_picker_name := 'UNASSIGNED';
    ELSE
      SELECT e.name
        INTO lv_picker_name
        FROM ORACLE_SQL.EMPLOYEES e
       WHERE e.id = lv_picker_id;
    END IF;

    SELECT COUNT(*)
      INTO lv_line_cnt
      FROM ORACLE_SQL.PICKING_LINE pln
     WHERE pln.picklist_id = p_picklist_id;

    DBMS_OUTPUT.PUT_LINE('Created: ' || lv_created);
    DBMS_OUTPUT.PUT_LINE('Picker: ' || lv_picker_name);
    DBMS_OUTPUT.PUT_LINE('Line count: ' || lv_line_cnt);

    FOR rec IN (
      SELECT x.line_no,
             x.product_id,
             x.location_id,
             x.qty
        FROM (
          SELECT pln.line_no,
                 pln.product_id,
                 pln.location_id,
                 pln.qty
            FROM ORACLE_SQL.PICKING_LINE pln
           WHERE pln.picklist_id = p_picklist_id
           ORDER BY pln.line_no
        ) x
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'Line ' || rec.line_no || ': product=' || rec.product_id ||
        ', location=' || rec.location_id || ', qty=' || rec.qty
      );
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Picklist not found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_picklist_summary;
END pkg_picking_ops;
/

