      DBMS_OUTPUT.PUT_LINE('Picklist not found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_picklist_summary;


  PROCEDURE check_picklist_inventory(
    p_picklist_id IN ORACLE_SQL.PICKING_LIST.id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_exists    NUMBER;
    lv_any_rows  NUMBER := 0;
  BEGIN
    -- Validate picklist exists (single-row check).
    SELECT 1
      INTO lv_exists
      FROM ORACLE_SQL.PICKING_LIST pl
     WHERE pl.id = p_picklist_id;

    FOR rec IN (
      SELECT x.line_no,
             x.product_id,
             x.location_id,
             x.pick_qty,
             x.on_hand
        FROM (
          SELECT pln.line_no,
                 pln.product_id,
                 pln.location_id,
                 pln.qty AS pick_qty,
                 NVL(inv.qty, 0) AS on_hand
            FROM ORACLE_SQL.PICKING_LINE pln
            LEFT OUTER JOIN ORACLE_SQL.INVENTORY inv
              ON inv.product_id = pln.product_id
             AND inv.location_id = pln.location_id
           WHERE pln.picklist_id = p_picklist_id
             AND pln.qty > NVL(inv.qty, 0)
           ORDER BY pln.line_no
        ) x
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      IF lv_any_rows = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Shortages for picklist ' || p_picklist_id);
      END IF;
      lv_any_rows := 1;
      DBMS_OUTPUT.PUT_LINE(
        'Line ' || rec.line_no || ': product=' || rec.product_id ||
        ', location=' || rec.location_id || ', pick_qty=' || rec.pick_qty ||
        ', on_hand=' || rec.on_hand
      );
    END LOOP;

    IF lv_any_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No shortages for picklist ' || p_picklist_id);
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Picklist not found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END check_picklist_inventory;

END pkg_picking_ops;
/

