                 pln.product_id,
                 pln.location_id,
                 pln.qty AS pick_qty,
                 NVL(inv.qty, 0) AS on_hand
            FROM ORACLE_SQL.PICKING_LINE pln
            LEFT OUTER JOIN ORACLE_SQL.INVENTORY inv
              ON inv.product_id = pln.product_id
             AND inv.location_id = pln.location_id
           WHERE pln.picklist_id = p_picklist_id
             AND pln.qty > NVL(inv.qty, 0)
           ORDER BY pln.line_no
        ) x
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_any_rows := 1;
      DBMS_OUTPUT.PUT_LINE(
        'Line ' || rec.line_no || ': product=' || rec.product_id ||
        ', location=' || rec.location_id || ', pick_qty=' || rec.pick_qty ||
        ', on_hand=' || rec.on_hand
      );
    END LOOP;

    IF lv_any_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No shortages for picklist ' || p_picklist_id);
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Picklist not found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END check_picklist_inventory;


  PROCEDURE print_shortage_decisions(
    p_picklist_id IN ORACLE_SQL.PICKING_LIST.id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_exists     NUMBER;
    lv_ok_cnt     NUMBER := 0;
    lv_short_cnt  NUMBER := 0;
  BEGIN
    -- Validate picklist exists.
    SELECT 1
      INTO lv_exists
      FROM ORACLE_SQL.PICKING_LIST pl
     WHERE pl.id = p_picklist_id;

    DBMS_OUTPUT.PUT_LINE('Decisions for picklist ' || p_picklist_id);

    SELECT NVL(SUM(CASE WHEN NVL(inv.qty, 0) >= pln.qty THEN 1 ELSE 0 END), 0),
           NVL(SUM(CASE WHEN NVL(inv.qty, 0) < pln.qty THEN 1 ELSE 0 END), 0)
      INTO lv_ok_cnt, lv_short_cnt
      FROM ORACLE_SQL.PICKING_LINE pln
      LEFT OUTER JOIN ORACLE_SQL.INVENTORY inv
        ON inv.product_id = pln.product_id
       AND inv.location_id = pln.location_id
     WHERE pln.picklist_id = p_picklist_id;

    FOR rec IN (
      SELECT x.line_no,
             x.product_id,
             x.location_id,
             x.pick_qty,
             x.on_hand,
             x.decision
        FROM (
          SELECT pln.line_no,
                 pln.product_id,
                 pln.location_id,
                 pln.qty AS pick_qty,
                 NVL(inv.qty, 0) AS on_hand,
                 CASE
                   WHEN NVL(inv.qty, 0) >= pln.qty THEN 'OK'
                   ELSE 'SHORT'
                 END AS decision
            FROM ORACLE_SQL.PICKING_LINE pln
            LEFT OUTER JOIN ORACLE_SQL.INVENTORY inv
              ON inv.product_id = pln.product_id
             AND inv.location_id = pln.location_id
           WHERE pln.picklist_id = p_picklist_id
           ORDER BY pln.line_no
        ) x
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'Line ' || rec.line_no || ': decision=' || rec.decision ||
        ', product=' || rec.product_id || ', location=' || rec.location_id ||
        ', pick_qty=' || rec.pick_qty || ', on_hand=' || rec.on_hand
      );
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Summary: OK=' || lv_ok_cnt || ', SHORT=' || lv_short_cnt);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Picklist not found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_shortage_decisions;

END pkg_picking_ops;
/

CREATE OR REPLACE PROCEDURE report_recent_encounters(
  p_patient_id IN SYNTHEA.ENCOUNTERS.patient%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_printed      PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Recent encounters for patient: ' || p_patient_id);

  FOR r IN (
    SELECT e.id,
           e.encounterclass,
           e.start_timestamp,
           e.stop_timestamp,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
     ORDER BY e.start_timestamp DESC
  ) LOOP
    EXIT WHEN lv_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Encounter ID=' || r.id ||
      ', Class=' || r.encounterclass ||
      ', Start=' || TO_CHAR(r.start_timestamp, 'YYYY-MM-DD HH24:MI') ||
      ', Stop=' || TO_CHAR(r.stop_timestamp, 'YYYY-MM-DD HH24:MI') ||
      ', Total Claim Cost=' || TO_CHAR(r.total_claim_cost)
    );

    lv_printed := lv_printed + 1;
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient: ' || p_patient_id);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_recent_encounters;
/

