CREATE OR REPLACE PROCEDURE report_top_cost_encounter(
  p_patient_id IN SYNTHEA.ENCOUNTERS.patient%TYPE
) IS
  lv_encounter_id      SYNTHEA.ENCOUNTERS.id%TYPE;
  lv_start_ts          SYNTHEA.ENCOUNTERS.start_timestamp%TYPE;
  lv_total_claim_cost  SYNTHEA.ENCOUNTERS.total_claim_cost%TYPE;
BEGIN
  IF p_patient_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient id is required.');
    RETURN;
  END IF;

  BEGIN
    SELECT x.id,
           x.start_timestamp,
           x.total_claim_cost
      INTO lv_encounter_id,
           lv_start_ts,
           lv_total_claim_cost
      FROM (
        SELECT e.id,
               e.start_timestamp,
               e.total_claim_cost
          FROM SYNTHEA.ENCOUNTERS e
         WHERE e.patient = p_patient_id
         ORDER BY e.total_claim_cost DESC, e.start_timestamp DESC
      ) x
     WHERE ROWNUM = 1;

    DBMS_OUTPUT.PUT_LINE('Top-cost encounter for patient: ' || p_patient_id);
    DBMS_OUTPUT.PUT_LINE(
      'Encounter ID=' || lv_encounter_id ||
      ', Start=' || TO_CHAR(lv_start_ts, 'YYYY-MM-DD HH24:MI') ||
