CREATE OR REPLACE PROCEDURE intake_dashboard(
  p_patient_id IN SYNTHEA.ENCOUNTERS.patient%TYPE
) IS
  lv_patient_id SYNTHEA.ENCOUNTERS.patient%TYPE := p_patient_id;
BEGIN
  IF lv_patient_id IS NULL THEN
    SELECT e.patient
      INTO lv_patient_id
      FROM SYNTHEA.ENCOUNTERS e
     GROUP BY e.patient
     ORDER BY COUNT(*) DESC
     FETCH FIRST 1 ROWS ONLY;

    DBMS_OUTPUT.PUT_LINE('Patient id not provided; using fallback patient: ' || lv_patient_id);
  END IF;

  DBMS_OUTPUT.PUT_LINE('Using patient id: ' || lv_patient_id);

  DBMS_OUTPUT.PUT_LINE('Calling recent encounters report...');
  report_recent_encounters(lv_patient_id);

  DBMS_OUTPUT.PUT_LINE('Calling top-cost encounter report...');
  report_top_cost_encounter(lv_patient_id);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END intake_dashboard;
