BEGIN
  DBMS_OUTPUT.PUT_LINE('Uniqueness check starting. order_id=' || NVL(TO_CHAR(p_order_id), 'NULL'));

  IF p_order_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Order id is required.');
    RETURN;
  END IF;

  SELECT COUNT(*)
    INTO lv_order_rows
    FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS cco
   WHERE cco.order_id = p_order_id;

  IF lv_order_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Order not found.');
    RETURN;
  ELSIF lv_order_rows > 1 THEN
    DBMS_OUTPUT.PUT_LINE('Warning: duplicate customer-order rows found for order_id=' || p_order_id || '. rows=' || lv_order_rows);
  END IF;

  -- Proceed using the first matching row for deterministic behavior.
  SELECT customer_id, pizza_name, status
    INTO lv_customer_id, lv_pizza_name, lv_status
    FROM (
      SELECT
        cco.customer_id,
        pn.pizza_name,
        CASE
          WHEN cro.cancellation IS NULL OR TRIM(cro.cancellation) = '' THEN 'DELIVERED'
          ELSE 'CANCELLED'
        END AS status
      FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS cco
      INNER JOIN MODERN_DATA.PIZZA_NAMES pn
        ON pn.pizza_id = cco.pizza_id
      LEFT JOIN MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS cro
        ON cro.order_id = cco.order_id
      WHERE cco.order_id = p_order_id
      ORDER BY cco.customer_id
    )
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE(
    'Order ' || p_order_id ||
    ': customer_id=' || lv_customer_id ||
    ', pizza=' || lv_pizza_name ||
    ', status=' || lv_status
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

