DECLARE
  p_day_str VARCHAR2(10) := NULL;

  lv_day DATE;
  lv_total_orders     NUMBER := 0;
  lv_delivered_orders NUMBER := 0;
  lv_cancelled_orders NUMBER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Daily snapshot starting. day=' || NVL(p_day_str, 'NULL'));

  IF p_day_str IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Date string is required (YYYY-MM-DD).');
    RETURN;
  END IF;

  lv_day := TO_DATE(p_day_str, 'YYYY-MM-DD');

  SELECT
    COUNT(DISTINCT cco.order_id) AS total_orders,
    COUNT(DISTINCT CASE WHEN cro.cancellation IS NULL OR TRIM(cro.cancellation) = '' THEN cco.order_id END) AS delivered_orders,
    COUNT(DISTINCT CASE WHEN cro.cancellation IS NOT NULL AND TRIM(cro.cancellation) <> '' THEN cco.order_id END) AS cancelled_orders
  INTO lv_total_orders, lv_delivered_orders, lv_cancelled_orders
  FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS cco
  LEFT JOIN MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS cro
    ON cro.order_id = cco.order_id
  WHERE TRUNC(TO_DATE(cco.order_time, 'YYYY-MM-DD HH24:MI:SS')) = TRUNC(lv_day);

  DBMS_OUTPUT.PUT_LINE(
    'Orders for ' || TO_CHAR(lv_day, 'YYYY-MM-DD') ||
    ': total=' || lv_total_orders ||
    ', delivered=' || lv_delivered_orders ||
    ', cancelled=' || lv_cancelled_orders
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date format. Use YYYY-MM-DD.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

