CREATE OR REPLACE PROCEDURE rpt_top_counties_births(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_top IS
    SELECT county_of_residence,
           TO_NUMBER(births) AS births_num,
           TO_NUMBER(ave_age_of_mother) AS ave_age_num,
           TO_NUMBER(ave_birth_weight_gms) AS ave_bw_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
     WHERE year = p_year
       AND REGEXP_LIKE(births, '^\s*[0-9]+\s*$')
       AND REGEXP_LIKE(ave_age_of_mother, '^\s*[0-9]+(\.[0-9]+)?\s*$')
       AND REGEXP_LIKE(ave_birth_weight_gms, '^\s*[0-9]+(\.[0-9]+)?\s*$')
     ORDER BY TO_NUMBER(births) DESC;

  lv_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || p_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('County', 30) || ' | ' || LPAD('Births', 10) || ' | ' || LPAD('Avg Mother Age', 14) || ' | ' || LPAD('Avg Birth Wt', 12));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || LPAD('-', 14, '-') || '-+-' || LPAD('-', 12, '-'));

  FOR rec IN c_top LOOP
    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 30) || ' | ' ||
      LPAD(TO_CHAR(rec.births_num), 10) || ' | ' ||
      LPAD(TO_CHAR(rec.ave_age_num, 'FM990D00'), 14) || ' | ' ||
      LPAD(TO_CHAR(rec.ave_bw_num, 'FM9990'), 12)
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No counties matched the criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_top_counties_births;
/

