  PROCEDURE get_births_by_fips(
    p_year        IN  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_fips IN  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE,
    p_births_num  OUT NUMBER,
    p_status      OUT VARCHAR2
  );
END county_natality_util;
