CREATE OR REPLACE PACKAGE BODY county_natality_util IS
  PROCEDURE get_births_by_fips(
    p_year        IN  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_fips IN  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE,
    p_births_num  OUT NUMBER,
    p_status      OUT VARCHAR2
  ) IS
    lv_births_txt SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.births%TYPE;
  BEGIN
    p_births_num := NULL;
    p_status := 'NOT_FOUND';

    SELECT cn.births
      INTO lv_births_txt
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND cn.county_of_residence_fips = p_county_fips;

    IF REGEXP_LIKE(lv_births_txt, '^\s*[0-9]+\s*$') THEN
      p_births_num := TO_NUMBER(lv_births_txt);
      p_status := 'OK';
    ELSE
      p_births_num := NULL;
      p_status := 'BAD_NUMERIC';
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      p_births_num := NULL;
      p_status := 'NOT_FOUND';
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      p_births_num := NULL;
      p_status := 'DUPLICATE_ROWS';
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      p_births_num := NULL;
      p_status := 'ERROR';
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END get_births_by_fips;
END county_natality_util;
/

DECLARE
  lv_year        SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;
  lv_fips        SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE;
  lv_births_num  NUMBER;
  lv_status      VARCHAR2(30);
BEGIN
  SELECT year, county_of_residence_fips
    INTO lv_year, lv_fips
    FROM (
      SELECT year, county_of_residence_fips
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
       WHERE year IS NOT NULL
         AND county_of_residence_fips IS NOT NULL
       GROUP BY year, county_of_residence_fips
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  county_natality_util.get_births_by_fips(
    p_year        => lv_year,
    p_county_fips => lv_fips,
    p_births_num  => lv_births_num,
    p_status      => lv_status
  );

  DBMS_OUTPUT.PUT_LINE('Births(NUM)=' || TO_CHAR(lv_births_num));
  DBMS_OUTPUT.PUT_LINE('Status=' || lv_status);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

