CREATE OR REPLACE PROCEDURE screen_year_county_births(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit screening for runtime and readability

  CURSOR c_cnty IS
    SELECT county_of_residence_fips
      FROM (
        SELECT county_of_residence_fips
          FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
         WHERE year = p_year
           AND county_of_residence_fips IS NOT NULL
         GROUP BY county_of_residence_fips
         ORDER BY COUNT(*) DESC
      )
     WHERE ROWNUM <= co_report_limit;

  lv_fips   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE;
  lv_births NUMBER;
  lv_status VARCHAR2(30);

  lv_ok     PLS_INTEGER := 0;
  lv_bad    PLS_INTEGER := 0;
  lv_other  PLS_INTEGER := 0;

  lv_rows   PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Screening county births for year=' || p_year);

  OPEN c_cnty;
  LOOP
    FETCH c_cnty INTO lv_fips;
    EXIT WHEN c_cnty%NOTFOUND;
    lv_rows := lv_rows + 1;

    county_natality_util.get_births_by_fips(
      p_year        => p_year,
      p_county_fips => lv_fips,
      p_births_num  => lv_births,
      p_status      => lv_status
    );

    IF lv_status = 'OK' THEN
      lv_ok := lv_ok + 1;
    ELSIF lv_status = 'BAD_NUMERIC' THEN
      lv_bad := lv_bad + 1;
    ELSE
      lv_other := lv_other + 1;
    END IF;
  END LOOP;
  CLOSE c_cnty;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No counties to screen for the provided year.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('OK=' || TO_CHAR(lv_ok) || ', BAD_NUMERIC=' || TO_CHAR(lv_bad) || ', OTHER=' || TO_CHAR(lv_other));
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_cnty%ISOPEN THEN
      CLOSE c_cnty;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_cnty%ISOPEN THEN
      CLOSE c_cnty;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF c_cnty%ISOPEN THEN
      CLOSE c_cnty;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END screen_year_county_births;
/

