CREATE OR REPLACE PROCEDURE rpt_congenital_abnormality_rate(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_ranked IS
    WITH totals AS (
      SELECT cn.county_of_residence_fips AS county_fips,
             SUM(TO_NUMBER(cn.births)) AS total_births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
         AND cn.county_of_residence_fips IS NOT NULL
         AND REGEXP_LIKE(cn.births, '^\s*[0-9]+\s*$')
       GROUP BY cn.county_of_residence_fips
    ),
    checked AS (
      SELECT ca.county_of_residence_fips AS county_fips,
             SUM(TO_NUMBER(ca.births)) AS checked_births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_CONGENITAL_ABNORMALITIES ca
       WHERE ca.year = p_year
         AND ca.county_of_residence_fips IS NOT NULL
         AND ca.congenital_abnormality_checked_yn = 'Yes'
         AND REGEXP_LIKE(ca.births, '^\s*[0-9]+\s*$')
       GROUP BY ca.county_of_residence_fips
    ),
    scored AS (
      SELECT t.county_fips,
             t.total_births,
             NVL(c.checked_births, 0) AS checked_births,
             (NVL(c.checked_births, 0) / NULLIF(t.total_births, 0)) * 100 AS pct_checked,
             ROW_NUMBER() OVER (
               ORDER BY (NVL(c.checked_births, 0) / NULLIF(t.total_births, 0)) DESC, t.total_births DESC
             ) AS rn
        FROM totals t
        LEFT OUTER JOIN checked c
          ON c.county_fips = t.county_fips
    )
    SELECT county_fips AS county_of_residence_fips,
           total_births,
           checked_births,
           pct_checked
      FROM scored
     WHERE rn <= co_report_limit
     ORDER BY rn;

  TYPE t_rank_rec IS RECORD (
    county_of_residence_fips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE,
    total_births             NUMBER,
    checked_births           NUMBER,
    pct_checked              NUMBER
  );

  lv_rec     t_rank_rec;
  lv_rows    PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Congenital abnormality checked rate for year=' || p_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('County FIPS', 12) || ' | ' || LPAD('Total', 10) || ' | ' || LPAD('Checked', 10) || ' | ' || LPAD('%Checked', 10));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 12, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || LPAD('-', 10, '-'));

  OPEN c_ranked;
  LOOP
    FETCH c_ranked INTO lv_rec;
    EXIT WHEN c_ranked%NOTFOUND;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(lv_rec.county_of_residence_fips, 12) || ' | ' ||
      LPAD(TO_CHAR(lv_rec.total_births), 10) || ' | ' ||
      LPAD(TO_CHAR(lv_rec.checked_births), 10) || ' | ' ||
      LPAD(TO_CHAR(lv_rec.pct_checked, 'FM990D00'), 10)
    );
  END LOOP;
  CLOSE c_ranked;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No ranked counties produced for the provided year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_ranked%ISOPEN THEN
      CLOSE c_ranked;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_ranked%ISOPEN THEN
      CLOSE c_ranked;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN ZERO_DIVIDE THEN
    IF c_ranked%ISOPEN THEN
      CLOSE c_ranked;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  WHEN OTHERS THEN
    IF c_ranked%ISOPEN THEN
      CLOSE c_ranked;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_congenital_abnormality_rate;
/

