    p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_flights IS
      SELECT f.flight_no,
             f.scheduled_departure,
             f.arrival_airport,
             f.aircraft_code,
             a.model
        FROM AIRLINES.FLIGHTS f
        INNER JOIN AIRLINES.AIRCRAFTS_DATA a
          ON a.aircraft_code = f.aircraft_code
       WHERE f.departure_airport = p_departure_airport
         AND f.status = 'Scheduled'
       ORDER BY f.scheduled_departure;

    r_f c_flights%ROWTYPE;
    lv_printed PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Upcoming departures for ' || p_departure_airport || ' (max rows = ' || co_report_limit || ')');

    OPEN c_flights;
    LOOP
      FETCH c_flights INTO r_f;
      EXIT WHEN c_flights%NOTFOUND OR lv_printed >= co_report_limit;

      lv_printed := lv_printed + 1;
      DBMS_OUTPUT.PUT_LINE(
        'Flight ' || r_f.flight_no || ' | Dep ' || TO_CHAR(r_f.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
        ' | Arr ' || r_f.arrival_airport || ' | Aircraft ' || r_f.aircraft_code || ' (' || r_f.model || ')'
      );
    END LOOP;
    CLOSE c_flights;

    IF lv_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No scheduled departures found for this airport.');
