    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_pax IS
      SELECT bp.ticket_no,
             bp.seat_no
        FROM AIRLINES.BOARDING_PASSES bp
        INNER JOIN AIRLINES.TICKET_FLIGHTS tf
          ON tf.ticket_no = bp.ticket_no
         AND tf.flight_id = bp.flight_id
       WHERE bp.flight_id = p_flight_id
