  BEGIN
    DBMS_OUTPUT.PUT_LINE('Passengers for flight ID ' || p_flight_id || ' (max rows = ' || co_report_limit || ')');

    lv_has := has_boarding_pass(p_flight_id);
    IF lv_has = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Boarding passes not issued yet for this flight.');
      RETURN;
    END IF;

