CREATE OR REPLACE PROCEDURE customer_orders_report(
  p_customer_name_like IN ORACLE_SQL.CUSTOMERS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_filter ORACLE_SQL.CUSTOMERS.name%TYPE;
  lv_rows   PLS_INTEGER := 0;
BEGIN
  lv_filter := TRIM(p_customer_name_like);
  IF lv_filter IS NULL THEN
    lv_filter := '%';
  ELSE
    lv_filter := '%' || lv_filter || '%';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Customer order summary (max rows = ' || co_report_limit || ')');
  DBMS_OUTPUT.PUT_LINE('Filter (name like): ' || lv_filter);

  FOR r IN (
    SELECT *
    FROM (
      SELECT o.id AS order_id,
             c.name AS customer_name,
             o.ordered AS ordered_str,
             o.delivery AS delivery_str,
             NVL(SUM(ol.amount), 0) AS total_amt
        FROM ORACLE_SQL.ORDERS o
        INNER JOIN ORACLE_SQL.CUSTOMERS c
          ON c.id = o.customer_id
        LEFT OUTER JOIN ORACLE_SQL.ORDERLINES ol
          ON ol.order_id = o.id
       WHERE c.name LIKE lv_filter
       GROUP BY o.id, c.name, o.ordered, o.delivery
       ORDER BY o.id DESC
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      'ORDER_ID=' || r.order_id ||
      ' | CUSTOMER=' || r.customer_name ||
      ' | ORDERED=' || r.ordered_str ||
      ' | DELIVERY=' || r.delivery_str ||
      ' | TOTAL_AMT=' || TO_CHAR(r.total_amt)
    );
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No orders matched the filter.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END customer_orders_report;
/

