CREATE OR REPLACE PROCEDURE brewery_purchase_audit(
  p_brewery_id IN ORACLE_SQL.BREWERIES.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for audit readability

  lv_brewery_name ORACLE_SQL.BREWERIES.name%TYPE;
  lv_purchase_cnt PLS_INTEGER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Brewery purchase audit (max rows = ' || co_report_limit || ')');

  SELECT b.name
    INTO lv_brewery_name
    FROM ORACLE_SQL.BREWERIES b
   WHERE b.id = p_brewery_id;

  DBMS_OUTPUT.PUT_LINE('Brewery: ' || lv_brewery_name || ' (ID=' || TO_CHAR(p_brewery_id) || ')');

  SELECT COUNT(*)
    INTO lv_purchase_cnt
    FROM ORACLE_SQL.PURCHASES p
   WHERE p.brewery_id = p_brewery_id;

  IF lv_purchase_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No purchases found for this brewery.');
    RETURN;
  END IF;

  FOR r IN (
    SELECT *
    FROM (
      SELECT p.purchased AS purchased_str,
             pr.name AS product_name,
             p.qty,
             p.cost
        FROM ORACLE_SQL.PURCHASES p
        INNER JOIN ORACLE_SQL.PRODUCTS pr
          ON pr.id = p.product_id
       WHERE p.brewery_id = p_brewery_id
       ORDER BY p.id DESC
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'PURCHASED=' || r.purchased_str ||
      ' | PRODUCT=' || r.product_name ||
      ' | QTY=' || TO_CHAR(r.qty) ||
      ' | COST=' || TO_CHAR(r.cost)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END brewery_purchase_audit;
/

