question:
Tie the workflow together in a small package for operations support. Create a package that exposes a single procedure which runs two checks: first it calls the suspicious delivery scan for a given customer id, then it calls the brewery purchase audit for a given brewery id. The wrapper must validate inputs (reject both NULL), print a clear start/end banner, and ensure any unexpected exception is handled without crashing.

Requirements:
Procedure Name: ops_support_pkg.run_ops_checks
Parameters:
p_customer_id IN ORACLE_SQL.CUSTOMERS.id%TYPE
p_brewery_id IN ORACLE_SQL.BREWERIES.id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Ops checks started.');
DBMS_OUTPUT.PUT_LINE('Input validation failed: both p_customer_id and p_brewery_id are NULL.');
DBMS_OUTPUT.PUT_LINE('Running suspicious delivery scan...');
DBMS_OUTPUT.PUT_LINE('Running brewery purchase audit...');
DBMS_OUTPUT.PUT_LINE('Ops checks finished.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE ops_support_pkg IS
  PROCEDURE run_ops_checks(
    p_customer_id IN ORACLE_SQL.CUSTOMERS.id%TYPE,
    p_brewery_id  IN ORACLE_SQL.BREWERIES.id%TYPE
  );
END ops_support_pkg;
/

CREATE OR REPLACE PACKAGE BODY ops_support_pkg IS
  PROCEDURE run_ops_checks(
    p_customer_id IN ORACLE_SQL.CUSTOMERS.id%TYPE,
    p_brewery_id  IN ORACLE_SQL.BREWERIES.id%TYPE
  ) IS
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Ops checks started.');

    IF p_customer_id IS NULL AND p_brewery_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: both p_customer_id and p_brewery_id are NULL.');
      DBMS_OUTPUT.PUT_LINE('Ops checks finished.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Running suspicious delivery scan...');
    flag_suspicious_deliveries(p_customer_id);

    DBMS_OUTPUT.PUT_LINE('Running brewery purchase audit...');
    brewery_purchase_audit(p_brewery_id);

    DBMS_OUTPUT.PUT_LINE('Ops checks finished.');

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_ops_checks;
END ops_support_pkg;
/

