DECLARE
  p_solution_name STACKING.EDA.name%TYPE := 'SOLUTION_NAME_HERE';
  p_version       STACKING.EDA.version%TYPE := 1;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows   PLS_INTEGER := 0;
  lv_reason VARCHAR2(50);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Dropped features for ' || p_solution_name || ' v' || p_version || ' (max rows=' || co_report_limit || '):');

  FOR rec IN (
    SELECT e.feature, e.type, e.drop_user, e.drop_correlation
      FROM STACKING.EDA e
     WHERE e.name = p_solution_name
       AND e.version = p_version
       AND (e.drop_user = 1 OR e.drop_correlation = 1)
     ORDER BY e.feature
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    IF rec.drop_user = 1 AND rec.drop_correlation = 1 THEN
      lv_reason := 'USER+CORRELATION';
    ELSIF rec.drop_user = 1 THEN
      lv_reason := 'USER';
    ELSE
      lv_reason := 'CORRELATION';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Feature=' || rec.feature || ', Type=' || rec.type || ', Reason=' || lv_reason);
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No dropped features found for this solution/version.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No dropped features found for this solution/version.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

