DECLARE
  p_solution_name STACKING.MODEL_SCORE.name%TYPE := 'SOLUTION_NAME_HERE';
  p_version       STACKING.MODEL_SCORE.version%TYPE := 1;

  lv_step  STACKING.MODEL_SCORE.step%TYPE;
  lv_model STACKING.MODEL_SCORE.model%TYPE;
  lv_gap   NUMBER;

  lv_solution_exists NUMBER;
BEGIN
  -- Quick sanity check that the solution/version exists
  SELECT COUNT(*)
    INTO lv_solution_exists
    FROM STACKING.SOLUTION s
   WHERE s.name = p_solution_name
     AND s.version = p_version;

  IF lv_solution_exists = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No model scores found for this solution/version.');
    RETURN;
  END IF;

  -- Find the largest train-test gap
  SELECT ms.step,
         ms.model,
         (ms.train_score - ms.test_score)
    INTO lv_step, lv_model, lv_gap
    FROM STACKING.MODEL_SCORE ms
   WHERE ms.name = p_solution_name
     AND ms.version = p_version
   ORDER BY (ms.train_score - ms.test_score) DESC
   FETCH FIRST 1 ROWS ONLY;

  DBMS_OUTPUT.PUT_LINE('Worst generalization gap for ' || p_solution_name || ' v' || p_version || ':');
  DBMS_OUTPUT.PUT_LINE('Step=' || lv_step || ', Model=' || lv_model || ', Gap=' || lv_gap);

  -- Simple recommendation thresholds
  IF lv_gap < 5 THEN
    DBMS_OUTPUT.PUT_LINE('Recommendation: OK');
  ELSIF lv_gap < 15 THEN
    DBMS_OUTPUT.PUT_LINE('Recommendation: REVIEW');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Recommendation: HIGH_RISK');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No model scores found for this solution/version.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

