DECLARE
  p_solution_name STACKING.MODEL_SCORE.name%TYPE := 'SOLUTION_NAME_HERE';
  p_version       STACKING.MODEL_SCORE.version%TYPE := 1;

  lv_step     STACKING.MODEL_SCORE.step%TYPE;
  lv_model    STACKING.MODEL_SCORE.model%TYPE;
  lv_raw_gap  NUMBER;
  lv_abs_gap  NUMBER;

  lv_solution_exists NUMBER;
BEGIN
  -- Debug fix: use ABS() so the reported "worst gap" is always non-negative.
  SELECT COUNT(*)
    INTO lv_solution_exists
    FROM STACKING.SOLUTION s
   WHERE s.name = p_solution_name
     AND s.version = p_version;

  IF lv_solution_exists = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No model scores found for this solution/version.');
    RETURN;
  END IF;

  SELECT ms.step,
         ms.model,
         (ms.train_score - ms.test_score) AS raw_gap,
         ABS(ms.train_score - ms.test_score) AS abs_gap
    INTO lv_step, lv_model, lv_raw_gap, lv_abs_gap
    FROM STACKING.MODEL_SCORE ms
   WHERE ms.name = p_solution_name
     AND ms.version = p_version
   ORDER BY ABS(ms.train_score - ms.test_score) DESC
   FETCH FIRST 1 ROWS ONLY;

  DBMS_OUTPUT.PUT_LINE('Worst absolute gap for ' || p_solution_name || ' v' || p_version || ':');
  DBMS_OUTPUT.PUT_LINE('Step=' || lv_step || ', Model=' || lv_model || ', AbsGap=' || lv_abs_gap || ', RawGap=' || lv_raw_gap);

  IF lv_raw_gap < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Raw gap was negative (test > train).');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Raw gap was non-negative (train >= test).');
  END IF;

EXCEPTION
