CREATE OR REPLACE PROCEDURE county_natality_snapshot(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_births NUMBER;
  lv_age    NUMBER;
  lv_bw     NUMBER;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('County natality snapshot for year=' || TO_CHAR(p_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE('Max rows=' || co_report_limit);

  FOR r IN (
    SELECT cn.county_of_residence,
           cn.births,
           cn.ave_age_of_mother,
           cn.ave_birth_weight_gms
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
     ORDER BY cn.county_of_residence
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    -- Convert string metrics to numbers; treat blanks as NULL.
    lv_births := TO_NUMBER(NULLIF(TRIM(r.births), ''));
    lv_age    := TO_NUMBER(NULLIF(TRIM(r.ave_age_of_mother), ''));
    lv_bw     := TO_NUMBER(NULLIF(TRIM(r.ave_birth_weight_gms), ''));

    DBMS_OUTPUT.PUT_LINE(
      'County=' || r.county_of_residence ||
      ' | Births=' || TO_CHAR(lv_births) ||
      ' | AvgAgeMother=' || TO_CHAR(lv_age) ||
      ' | AvgBirthWtG=' || TO_CHAR(lv_bw)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No county natality rows found for the given year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No county natality rows found for the given year.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered in natality data.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END county_natality_snapshot;
/

CREATE OR REPLACE FUNCTION get_county_total_births(
  p_year   IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_county IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
) RETURN NUMBER IS
  lv_total_births NUMBER;
BEGIN
  SELECT SUM(NVL(TO_NUMBER(NULLIF(TRIM(cn.births), '')), 0))
    INTO lv_total_births
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.year = p_year
     AND cn.county_of_residence = p_county;

  IF lv_total_births IS NULL THEN
    -- SUM() returns NULL when no rows matched.
    RAISE NO_DATA_FOUND;
  END IF;

  RETURN lv_total_births;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN NULL;
  WHEN VALUE_ERROR THEN
    RETURN NULL;
  WHEN OTHERS THEN
    RETURN NULL;
END get_county_total_births;
/

CREATE OR REPLACE PROCEDURE print_county_births(
  p_year   IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_county IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
) IS
  lv_total_births NUMBER;
BEGIN
  lv_total_births := get_county_total_births(p_year => p_year, p_county => p_county);

  IF lv_total_births IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No county/year rows found to sum births.');
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'Total births for County=' || p_county ||
      ' Year=' || TO_CHAR(p_year, 'YYYY') ||
      ' is ' || TO_CHAR(lv_total_births)
    );
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No county/year rows found to sum births.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered while summing births.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END print_county_births;
/

DECLARE
  lv_year   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;
  lv_county SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;

  lv_rows NUMBER;
BEGIN
  SELECT COUNT(*) INTO lv_rows
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No natality data available to run the report.');
    RETURN;
  END IF;

  -- Pick the most common (year, county) pair to drive consistent testable output.
  SELECT t.year, t.county_of_residence
    INTO lv_year, lv_county
    FROM (
          SELECT cn.year,
                 cn.county_of_residence
            FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
           GROUP BY cn.year, cn.county_of_residence
           ORDER BY COUNT(*) DESC, cn.year DESC, cn.county_of_residence ASC
         ) t
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Runner selected Year=' || TO_CHAR(lv_year, 'YYYY') || ' County=' || lv_county);

  county_natality_snapshot(p_year => lv_year);
  print_county_births(p_year => lv_year, p_county => lv_county);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No natality data available to run the report.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

