CREATE OR REPLACE PROCEDURE rpt_top_counties_by_births(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(p_year, 'YYYY') || ':');
  DBMS_OUTPUT.PUT_LINE(RPAD('County', 30) || ' | ' || LPAD('Births', 10) || ' | ' || LPAD('AvgAgeMother', 12));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || LPAD('-', 12, '-'));

  FOR rec IN (
    SELECT
      cn.county_of_residence,
      TO_NUMBER(cn.births) AS births_num,
      TO_NUMBER(cn.ave_age_of_mother) AS avg_age_num
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
    WHERE cn.year = p_year
      AND cn.births IS NOT NULL
      AND REGEXP_LIKE(cn.births, '^\d+(\.\d+)?$')
      AND cn.ave_age_of_mother IS NOT NULL
      AND REGEXP_LIKE(cn.ave_age_of_mother, '^\d+(\.\d+)?$')
    ORDER BY TO_NUMBER(cn.births) DESC, cn.county_of_residence ASC
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 30) || ' | ' ||
      LPAD(TO_CHAR(rec.births_num), 10) || ' | ' ||
      LPAD(TO_CHAR(rec.avg_age_num, 'FM9990D0'), 12)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_top_counties_by_births;
/

CREATE OR REPLACE FUNCTION fn_total_births_for_county_year(
  p_county IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
  p_year   IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) RETURN NUMBER IS
  lv_total_births NUMBER := 0;
BEGIN
  IF p_county IS NULL OR TRIM(p_county) IS NULL OR p_year IS NULL THEN
    RETURN 0;
  END IF;

  SELECT NVL(SUM(TO_NUMBER(cn.births)), 0)
    INTO lv_total_births
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.county_of_residence = p_county
     AND cn.year = p_year
     AND cn.births IS NOT NULL
     AND REGEXP_LIKE(cn.births, '^\d+(\.\d+)?$');

  RETURN lv_total_births;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 0;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 0;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 0;
END fn_total_births_for_county_year;
/

