CREATE OR REPLACE PROCEDURE stacking_report_solutions(
  p_problem_name IN STACKING.PROBLEM.name%TYPE
) IS
  co_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Solutions for problem = ' || p_problem_name || ' (max rows = ' || co_limit || ')');

  FOR r IN (
    SELECT s.version,
           s.score,
           s.correlation,
           s.nb_model,
           s.nb_feature
      FROM STACKING.SOLUTION s
      INNER JOIN STACKING.PROBLEM p
        ON p.name = s.name
     WHERE p.name = p_problem_name
     ORDER BY s.score DESC, s.version DESC
  ) LOOP
    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Version=' || r.version ||
      ', Score=' || r.score ||
      ', Corr=' || r.correlation ||
      ', NB_MODEL=' || r.nb_model ||
      ', NB_FEATURE=' || r.nb_feature
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No solutions found for this problem.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END stacking_report_solutions;
/

