CREATE OR REPLACE FUNCTION stacking_solution_quality(
  p_problem_name IN STACKING.SOLUTION.name%TYPE,
  p_version      IN STACKING.SOLUTION.version%TYPE
) RETURN VARCHAR2 IS
  lv_score STACKING.SOLUTION.score%TYPE;
BEGIN
  SELECT s.score
    INTO lv_score
    FROM STACKING.SOLUTION s
   WHERE s.name = p_problem_name
     AND s.version = p_version;

  IF lv_score >= 90 THEN
    RETURN 'HIGH';
  ELSIF lv_score >= 70 THEN
    RETURN 'MEDIUM';
  ELSE
    RETURN 'LOW';
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'UNKNOWN';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'UNKNOWN';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
END stacking_solution_quality;
/

DECLARE
  lv_problem_name STACKING.SOLUTION.name%TYPE;
  lv_version      STACKING.SOLUTION.version%TYPE;
  lv_quality      VARCHAR2(20);
BEGIN
  -- Pick the most common problem name and one of its versions.
  SELECT s.name, s.version
    INTO lv_problem_name, lv_version
    FROM STACKING.SOLUTION s
   WHERE (s.name, s.version) IN (
         SELECT s2.name, s2.version
           FROM STACKING.SOLUTION s2
          WHERE s2.name = (
                SELECT s3.name
                  FROM STACKING.SOLUTION s3
                 GROUP BY s3.name
                 ORDER BY COUNT(*) DESC
                 FETCH FIRST 1 ROWS ONLY
          )
         ORDER BY s2.version DESC
         FETCH FIRST 1 ROWS ONLY
   );

  lv_quality := stacking_solution_quality(lv_problem_name, lv_version);
  DBMS_OUTPUT.PUT_LINE('Solution quality for ' || lv_problem_name || ' v' || lv_version || ' = ' || lv_quality);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

