CREATE OR REPLACE PACKAGE stacking_cfg_pkg IS
  PROCEDURE validate_model_step(
    p_problem_name IN STACKING.MODEL.name%TYPE,
    p_version      IN STACKING.MODEL.version%TYPE,
    p_step         IN STACKING.MODEL.step%TYPE
  );
END stacking_cfg_pkg;
/

CREATE OR REPLACE PACKAGE BODY stacking_cfg_pkg IS
  PROCEDURE validate_model_step(
    p_problem_name IN STACKING.MODEL.name%TYPE,
    p_version      IN STACKING.MODEL.version%TYPE,
    p_step         IN STACKING.MODEL.step%TYPE
  ) IS
    lv_l1_model STACKING.MODEL.l1_model%TYPE;
    lv_cnt      NUMBER;
  BEGIN
    -- Use COUNT(*) first so we can print a business-friendly invalid message.
    SELECT COUNT(*)
      INTO lv_cnt
      FROM STACKING.MODEL m
     WHERE m.name = p_problem_name
       AND m.version = p_version
       AND m.step = p_step;

    IF lv_cnt = 0 THEN
      DBMS_OUTPUT.PUT_LINE(
        'Invalid model step (not found): ' || p_problem_name ||
        ' v' || p_version ||
        ', step=' || p_step
      );
      RETURN;
    END IF;

    SELECT m.l1_model
      INTO lv_l1_model
      FROM STACKING.MODEL m
     WHERE m.name = p_problem_name
       AND m.version = p_version
       AND m.step = p_step;

    DBMS_OUTPUT.PUT_LINE(
      'Valid model step: ' || p_problem_name ||
      ' v' || p_version ||
      ', step=' || p_step ||
      ', model=' || lv_l1_model
    );

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END validate_model_step;
END stacking_cfg_pkg;
/

