CREATE OR REPLACE PROCEDURE stacking_print_scorecard(
  p_problem_name IN STACKING.MODEL_SCORE.name%TYPE,
  p_version      IN STACKING.MODEL_SCORE.version%TYPE
) IS
  co_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_printed PLS_INTEGER := 0;
  lv_solution_cnt NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Scorecard for ' || p_problem_name || ' v' || p_version || ' (max rows = ' || co_limit || ')');

  -- Confirm the solution/version exists to keep reporting consistent.
  SELECT COUNT(*)
    INTO lv_solution_cnt
    FROM STACKING.SOLUTION s
   WHERE s.name = p_problem_name
     AND s.version = p_version;

  IF lv_solution_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No model scores found for this solution/version.');
    RETURN;
  END IF;

  FOR r IN (
    SELECT ms.step,
           ms.model,
           ms.train_score,
           ms.test_score
      FROM STACKING.MODEL_SCORE ms
     WHERE ms.name = p_problem_name
       AND ms.version = p_version
     ORDER BY ms.step ASC, ms.model ASC
  ) LOOP
    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_limit;

    DBMS_OUTPUT.PUT_LINE(
      'step=' || r.step ||
      ', model=' || r.model ||
      ', train=' || r.train_score ||
      ', test=' || r.test_score
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No model scores found for this solution/version.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END stacking_print_scorecard;
/

