CREATE OR REPLACE FUNCTION get_avg_trip_minutes(
  p_station_name IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_station_name%TYPE,
  p_start_ts     IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE,
  p_end_ts       IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE
) RETURN NUMBER IS
  lv_avg_minutes NUMBER;
BEGIN
  IF p_station_name IS NULL OR p_start_ts IS NULL OR p_end_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for the requested station and period.');
    RETURN NULL;
  END IF;

  IF p_end_ts < p_start_ts THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: end timestamp is before start timestamp.');
    RETURN NULL;
  END IF;

  -- Single-row aggregate; if no rows match, AVG returns NULL (no NO_DATA_FOUND here).
  SELECT AVG(TO_NUMBER(t.duration_sec) / 60)
    INTO lv_avg_minutes
    FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
   WHERE t.start_station_name = p_station_name
     AND t.start_date >= p_start_ts
     AND t.start_date <  p_end_ts;

  IF lv_avg_minutes IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for the requested station and period.');
    RETURN NULL;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Avg minutes for ' || p_station_name ||
    ' from ' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI') ||
    ' to ' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI') ||
    ' = ' || TO_CHAR(lv_avg_minutes, 'FM9999990D00')
  );

  RETURN lv_avg_minutes;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN NULL;
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Invalid number encountered in duration_sec.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END get_avg_trip_minutes;
/

