CREATE OR REPLACE PACKAGE bikeshare_ops_pkg IS
  PROCEDURE scan_short_avg_trips(
    p_start_ts        IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE,
    p_end_ts          IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE,
    p_min_avg_minutes IN NUMBER
  );
END bikeshare_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops_pkg IS
  PROCEDURE scan_short_avg_trips(
    p_start_ts        IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE,
    p_end_ts          IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE,
    p_min_avg_minutes IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    v_rank         PLS_INTEGER := 0;
    v_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF p_start_ts IS NULL OR p_end_ts IS NULL OR p_min_avg_minutes IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: start/end timestamps and threshold are required.');
      RETURN;
    END IF;

    IF p_end_ts < p_start_ts THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: end timestamp is before start timestamp.');
      RETURN;
    END IF;

    IF p_min_avg_minutes < 0 THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: threshold must be non-negative.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Short-average scan from ' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI') ||
      ' to ' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI') ||
      ' (threshold < ' || TO_CHAR(p_min_avg_minutes, 'FM9999990D00') || ' minutes)'
    );

    -- Flag stations with low average trip duration.
    FOR r IN (
      SELECT station_name,
             avg_minutes
        FROM (
          SELECT t.start_station_name                     AS station_name,
                 AVG(TO_NUMBER(t.duration_sec) / 60)      AS avg_minutes
            FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
           WHERE t.start_date >= p_start_ts
             AND t.start_date <  p_end_ts
           GROUP BY t.start_station_name
           HAVING AVG(TO_NUMBER(t.duration_sec) / 60) < p_min_avg_minutes
           ORDER BY AVG(TO_NUMBER(t.duration_sec) / 60) ASC, t.start_station_name ASC
        )
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      v_rank := v_rank + 1;
      v_rows_printed := v_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        LPAD(v_rank, 2, ' ') || '. ' || r.station_name ||
        ' | AvgMinutes=' || TO_CHAR(r.avg_minutes, 'FM9999990D00')
      );
    END LOOP;

    IF v_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No stations matched the scan criteria.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN INVALID_NUMBER THEN
      DBMS_OUTPUT.PUT_LINE('Invalid number encountered in duration_sec.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END scan_short_avg_trips;
END bikeshare_ops_pkg;
/

