CREATE OR REPLACE PROCEDURE report_region_top_start_stations(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
  p_start_ts    IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
  p_end_ts      IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE(
    'DEBUG: region=' || NVL(p_region_name, 'NULL') ||
    ', start=' || NVL(TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI:SS'), 'NULL') ||
    ', end=' || NVL(TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI:SS'), 'NULL')
  );

  IF p_region_name IS NULL OR p_start_ts IS NULL OR p_end_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for the given inputs.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top start stations in region "' || p_region_name || '" (max rows = ' || co_report_limit || '):');

  FOR rec IN (
    SELECT si.name AS station_name,
           COUNT(*) AS trip_cnt
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        ON si.station_id = t.start_station_id
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
        ON r.region_id = si.region_id
     WHERE r.name = p_region_name
       AND t.start_date >= p_start_ts
       AND t.start_date < p_end_ts
     GROUP BY si.name
     ORDER BY COUNT(*) DESC, si.name
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    IF lv_rows_printed > co_report_limit THEN
      EXIT;
    END IF;

    DBMS_OUTPUT.PUT_LINE('  ' || rec.station_name || ' | trips=' || rec.trip_cnt);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for the given inputs.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_top_start_stations;
/

