CREATE OR REPLACE PACKAGE BODY bikeshare_ops IS
  PROCEDURE station_status_snapshot(
    p_short_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.short_name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for readability
    lv_station_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
    lv_rows         PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('DEBUG: snapshot short_name=' || NVL(p_short_name, 'NULL'));

    IF p_short_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station: ' || get_station_label(p_short_name));
      DBMS_OUTPUT.PUT_LINE('No status rows found for this station.');
      RETURN;
    END IF;

    SELECT si.station_id
      INTO lv_station_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
     WHERE si.short_name = p_short_name;

    DBMS_OUTPUT.PUT_LINE('Station: ' || get_station_label(p_short_name));
    DBMS_OUTPUT.PUT_LINE('Most recent status rows (max rows = ' || co_report_limit || '):');

    FOR rec IN (
      SELECT ss.last_reported,
             ss.num_bikes_available,
             ss.num_docks_available
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
       WHERE ss.station_id = lv_station_id
       ORDER BY ss.last_reported DESC
    ) LOOP
      lv_rows := lv_rows + 1;

      IF lv_rows > co_report_limit THEN
        EXIT;
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        '  last_reported=' || rec.last_reported ||
        ', bikes=' || rec.num_bikes_available ||
        ', docks=' || rec.num_docks_available
      );
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for this station.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END station_status_snapshot;
END bikeshare_ops;
/

