DECLARE
  lv_short_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.short_name%TYPE;
  lv_station_id  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
  lv_cnt_a       NUMBER;
  lv_cnt_b       NUMBER;
BEGIN
  -- Pick a station short_name that actually has status rows.
  SELECT short_name
    INTO lv_short_name
    FROM (
      SELECT si.short_name
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
          ON ss.station_id = si.station_id
       WHERE si.short_name IS NOT NULL
       GROUP BY si.short_name
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  SELECT si.station_id
    INTO lv_station_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
   WHERE si.short_name = lv_short_name;

  DBMS_OUTPUT.PUT_LINE('DEBUG: chosen short_name=' || lv_short_name);
  DBMS_OUTPUT.PUT_LINE('DEBUG: resolved station_id=' || lv_station_id);
  DBMS_OUTPUT.PUT_LINE('Station: ' || get_station_label(lv_short_name));

  -- Method A: correct lookup using the station_id as stored.
  SELECT COUNT(*)
    INTO lv_cnt_a
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
   WHERE ss.station_id = lv_station_id;

  -- Method B: a common bug is trimming keys (or otherwise altering them) before lookup.
  SELECT COUNT(*)
    INTO lv_cnt_b
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
   WHERE ss.station_id = TRIM(lv_station_id);

  DBMS_OUTPUT.PUT_LINE('Count method A (direct station_id): ' || lv_cnt_a);
  DBMS_OUTPUT.PUT_LINE('Count method B (trimmed station_id): ' || lv_cnt_b);

  IF lv_cnt_a <> lv_cnt_b THEN
    DBMS_OUTPUT.PUT_LINE('DIAGNOSIS: station_id appears to have leading/trailing spaces; do not trim it in the lookup.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('DIAGNOSIS: counts match; trimming is not the cause in this dataset sample.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

