/
CREATE OR REPLACE PACKAGE BODY demo_fertility_pkg IS
  PROCEDURE report_country_year(
    p_country_like IN VARCHAR2,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_rep IS
      SELECT a.country_name AS country_name,
             a.total_fertility_rate AS tfr,
             b.crude_birth_rate AS cbr,
             b.crude_death_rate AS cdr
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
        INNER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
          ON b.country_name = a.country_name
         AND b.year = a.year
       WHERE a.year = p_year
         AND (p_country_like IS NULL OR a.country_name LIKE p_country_like)
         AND ROWNUM <= co_report_limit
       ORDER BY a.country_name;

    lr_row c_rep%ROWTYPE;
    lv_rows PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('TFR/Birth/Death report for year=' || p_year || ', country like=' || NVL(p_country_like, '(NULL)'));

    OPEN c_rep;
    LOOP
      FETCH c_rep INTO lr_row;
      EXIT WHEN c_rep%NOTFOUND;

      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(
        'COUNTRY=' || lr_row.country_name ||
        ' | TFR=' || lr_row.tfr ||
        ' | CBR=' || lr_row.cbr ||
        ' | CDR=' || lr_row.cdr
      );
    END LOOP;
    CLOSE c_rep;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_rep%ISOPEN THEN
        CLOSE c_rep;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      IF c_rep%ISOPEN THEN
        CLOSE c_rep;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      IF c_rep%ISOPEN THEN
        CLOSE c_rep;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_country_year;

  PROCEDURE classify_tfr_trend(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit yearly output for readability

    CURSOR c_tfr IS
      SELECT yr,
             avg_tfr
        FROM (
          SELECT a.year AS yr,
                 AVG(TO_NUMBER(a.total_fertility_rate)) AS avg_tfr
            FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
            INNER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
              ON c.country_name = a.country_name
           WHERE a.country_name = p_country_name
             AND a.year BETWEEN p_start_year AND p_end_year
           GROUP BY a.year
           ORDER BY a.year
        )
       WHERE ROWNUM <= co_report_limit;

    lr_row c_tfr%ROWTYPE;
    lv_rows PLS_INTEGER := 0;

    lv_prev_year CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;
    lv_prev_tfr  NUMBER;

    lv_seen_up   PLS_INTEGER := 0;
    lv_seen_down PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('TFR trend check for country=' || p_country_name || ', years ' || p_start_year || '-' || p_end_year);

    OPEN c_tfr;
    LOOP
      FETCH c_tfr INTO lr_row;
      EXIT WHEN c_tfr%NOTFOUND;

      lv_rows := lv_rows + 1;

      IF lv_rows = 1 THEN
        DBMS_OUTPUT.PUT_LINE('Year ' || lr_row.yr || ': avg_tfr=' || TO_CHAR(lr_row.avg_tfr));
        lv_prev_year := lr_row.yr;
        lv_prev_tfr  := lr_row.avg_tfr;
      ELSE
        DBMS_OUTPUT.PUT_LINE('Delta ' || lv_prev_year || '->' || lr_row.yr || ': ' || TO_CHAR(lr_row.avg_tfr - lv_prev_tfr));

        IF lr_row.avg_tfr > lv_prev_tfr THEN
          lv_seen_up := 1;
        ELSIF lr_row.avg_tfr < lv_prev_tfr THEN
          lv_seen_down := 1;
        END IF;

        lv_prev_year := lr_row.yr;
        lv_prev_tfr  := lr_row.avg_tfr;
      END IF;
    END LOOP;
    CLOSE c_tfr;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No TFR data found for the requested country/year range.');
    ELSE
      IF lv_seen_up = 1 AND lv_seen_down = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Overall trend: INCREASING');
      ELSIF lv_seen_up = 0 AND lv_seen_down = 1 THEN
        DBMS_OUTPUT.PUT_LINE('Overall trend: DECREASING');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Overall trend: MIXED');
      END IF;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_tfr%ISOPEN THEN
        CLOSE c_tfr;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      IF c_tfr%ISOPEN THEN
        CLOSE c_tfr;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      IF c_tfr%ISOPEN THEN
        CLOSE c_tfr;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
    WHEN OTHERS THEN
      IF c_tfr%ISOPEN THEN
        CLOSE c_tfr;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END classify_tfr_trend;

  PROCEDURE check_year_consistency(
    p_year IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_chk IS
      SELECT a.country_name AS country_name,
             a.total_fertility_rate AS tfr_txt,
             b.crude_birth_rate AS cbr_txt
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
        INNER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
          ON b.country_name = a.country_name
         AND b.year = a.year
       WHERE a.year = p_year
         AND ROWNUM <= co_report_limit
       ORDER BY a.country_name;

    lr_row c_chk%ROWTYPE;
    lv_rows PLS_INTEGER := 0;

    lv_tfr NUMBER;
    lv_cbr NUMBER;
    lv_ratio NUMBER;
    lv_ok PLS_INTEGER;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Consistency check for year=' || p_year);

    OPEN c_chk;
    LOOP
      FETCH c_chk INTO lr_row;
      EXIT WHEN c_chk%NOTFOUND;

      lv_rows := lv_rows + 1;
      lv_ok := 1;

      BEGIN
        lv_tfr := TO_NUMBER(lr_row.tfr_txt);
        lv_cbr := TO_NUMBER(lr_row.cbr_txt);
      EXCEPTION
        WHEN VALUE_ERROR THEN
          lv_ok := 0;
      END;

      IF lv_ok = 0 THEN
        DBMS_OUTPUT.PUT_LINE('COUNTRY=' || lr_row.country_name || ' | Warning: non-numeric TFR/CBR encountered.');
      ELSE
        IF lv_tfr = 0 THEN
          DBMS_OUTPUT.PUT_LINE('COUNTRY=' || lr_row.country_name || ' | Warning: TFR is zero, ratio skipped.');
        ELSE
          lv_ratio := lv_cbr / lv_tfr;
          DBMS_OUTPUT.PUT_LINE('COUNTRY=' || lr_row.country_name || ' | TFR=' || lr_row.tfr_txt || ' | CBR=' || lr_row.cbr_txt || ' | ratio=' || TO_CHAR(lv_ratio));
        END IF;
      END IF;
    END LOOP;
    CLOSE c_chk;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No shared country rows found for the requested year.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_chk%ISOPEN THEN
        CLOSE c_chk;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      IF c_chk%ISOPEN THEN
        CLOSE c_chk;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      IF c_chk%ISOPEN THEN
        CLOSE c_chk;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END check_year_consistency;

  PROCEDURE audit_missing_birth_death(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit missing-year output for readability

    lv_start_num NUMBER;
    lv_end_num   NUMBER;
    lv_year_num  NUMBER;

    lv_year CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;

    lv_years_checked PLS_INTEGER := 0;
    lv_years_missing PLS_INTEGER := 0;
    lv_printed       PLS_INTEGER := 0;

    lv_has_fertility PLS_INTEGER;
    lv_has_birth     PLS_INTEGER;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Audit missing birth/death rows for country=' || p_country_name || ', years ' || p_start_year || '-' || p_end_year);

    lv_start_num := TO_NUMBER(p_start_year);
    lv_end_num   := TO_NUMBER(p_end_year);

    IF lv_start_num > lv_end_num THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year range.');
      RETURN;
    END IF;

    lv_year_num := lv_start_num;
    WHILE lv_year_num <= lv_end_num LOOP
      lv_year := TO_CHAR(lv_year_num);
      lv_years_checked := lv_years_checked + 1;

      SELECT COUNT(*)
        INTO lv_has_fertility
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
       WHERE a.country_name = p_country_name
         AND a.year = lv_year;

      IF lv_has_fertility > 0 THEN
        SELECT COUNT(*)
          INTO lv_has_birth
          FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
         WHERE b.country_name = p_country_name
           AND b.year = lv_year;

        IF lv_has_birth = 0 THEN
          lv_years_missing := lv_years_missing + 1;
          IF lv_printed < co_report_limit THEN
            lv_printed := lv_printed + 1;
            DBMS_OUTPUT.PUT_LINE('Year ' || lv_year || ': missing birth/death row.');
          END IF;
        END IF;
      END IF;

      lv_year_num := lv_year_num + 1;
    END LOOP;

    IF lv_years_checked > 0 AND lv_years_missing = 0 THEN
      NULL;
    END IF;

    IF lv_years_checked = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No fertility rows found for the requested country/year range.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Summary: years_checked=' || lv_years_checked || ', years_missing=' || lv_years_missing);
      IF lv_years_missing = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No fertility rows found for the requested country/year range.');
      END IF;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year range.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END audit_missing_birth_death;
END demo_fertility_pkg;
/

