question:
Build a reusable reporting procedure for operations staff to quickly review the most recent station status snapshots in a chosen region. The report should show the region name, then list up to 15 stations in that region ordered by most recently reported status first. For each row, print a fixed formatted line that keeps the same "Station" and "Last Reported" labels, and includes available bike/dock counts plus the installed flag from the current row. If the region id does not exist, print a clear message and do not error out.

Requirements:
Procedure Name: report_region_station_status
Parameters:
p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region_name || ' (region_id=' || p_region_id || ')');
DBMS_OUTPUT.PUT_LINE('Most recent station status first; max rows = ' || co_report_limit);
DBMS_OUTPUT.PUT_LINE(RPAD('Station', 40) || ' | ' || RPAD('Last Reported', 19) || ' | bikes=' || RPAD(TO_CHAR(rec.num_bikes_available_n), 3) || ' docks=' || RPAD(TO_CHAR(rec.num_docks_available_n), 3) || ' installed=' || rec.is_installed);
DBMS_OUTPUT.PUT_LINE('No stations/status found for this region.');
DBMS_OUTPUT.PUT_LINE('Region not found.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'Region not found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_region_station_status(
  p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Validate region exists and fetch its display name.
  SELECT r.name
    INTO lv_region_name
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE r.region_id = p_region_id;

  DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region_name || ' (region_id=' || p_region_id || ')');
  DBMS_OUTPUT.PUT_LINE('Most recent station status first; max rows = ' || co_report_limit);

  -- Report latest snapshots across stations in the region.
  FOR rec IN (
    SELECT si.name AS station_name,
           ss.last_reported AS last_reported,
           TO_NUMBER(ss.num_bikes_available) AS num_bikes_available_n,
           TO_NUMBER(ss.num_docks_available) AS num_docks_available_n,
           ss.is_installed AS is_installed
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
        ON ss.station_id = si.station_id
     WHERE si.region_id = p_region_id
     ORDER BY ss.last_reported DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD('Station', 40) || ' | ' || RPAD('Last Reported', 19) || ' | bikes=' ||
      RPAD(TO_CHAR(rec.num_bikes_available_n), 3) || ' docks=' ||
      RPAD(TO_CHAR(rec.num_docks_available_n), 3) || ' installed=' || rec.is_installed
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations/status found for this region.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Region not found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_station_status;
/

