CREATE OR REPLACE FUNCTION get_station_operational_state(
  p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
)
RETURN VARCHAR2
IS
  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_region_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
  lv_last_reported_ts SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE;

  lv_is_installed SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_installed%TYPE;
  lv_is_renting   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_renting%TYPE;
  lv_is_returning SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_returning%TYPE;
  lv_bikes_avail_n NUMBER;

  lv_state VARCHAR2(20);
BEGIN
  -- Fetch station + region metadata.
  SELECT si.name, r.name
    INTO lv_station_name, lv_region_name
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
    INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
      ON r.region_id = si.region_id
   WHERE si.station_id = p_station_id;

  -- Fetch most recent status snapshot for this station.
  BEGIN
    SELECT CAST(ss.last_reported AS TIMESTAMP),
           ss.is_installed,
           ss.is_renting,
           ss.is_returning,
           TO_NUMBER(ss.num_bikes_available)
      INTO lv_last_reported_ts,
           lv_is_installed,
           lv_is_renting,
           lv_is_returning,
           lv_bikes_avail_n
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
     WHERE ss.station_id = p_station_id
     ORDER BY ss.last_reported DESC
     FETCH FIRST 1 ROWS ONLY;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No status found for this station.');
      RETURN 'OFFLINE';
  END;

  -- Business classification.
  IF lv_is_installed <> '1' OR lv_is_renting <> '1' OR lv_is_returning <> '1' THEN
    lv_state := 'OFFLINE';
  ELSIF lv_bikes_avail_n = 0 THEN
    lv_state := 'NO_BIKES';
  ELSE
    lv_state := 'OK';
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Station=' || lv_station_name ||
    ' | Region=' || lv_region_name ||
    ' | Last Reported=' || TO_CHAR(lv_last_reported_ts, 'YYYY-MM-DD HH24:MI:SS') ||
    ' | State=' || lv_state
  );

  RETURN lv_state;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Station not found.');
    RETURN 'OFFLINE';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'OFFLINE';
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'OFFLINE';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'OFFLINE';
END get_station_operational_state;
/

