CREATE OR REPLACE PACKAGE bikeshare_ops_pkg IS
  PROCEDURE dashboard_region(
    p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE,
    p_start_ts  IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
    p_end_ts    IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE
  );
END bikeshare_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops_pkg IS
  PROCEDURE dashboard_region(
    p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE,
    p_start_ts  IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
    p_end_ts    IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE
  ) IS
    co_station_limit CONSTANT PLS_INTEGER := 15; -- Keep dashboard concise

    lv_region_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
    lv_state VARCHAR2(20);
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'Dashboard for region_id=' || p_region_id ||
      ' | window ' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' to ' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI:SS')
    );

    IF p_start_ts IS NOT NULL AND p_end_ts IS NOT NULL AND p_end_ts < p_start_ts THEN
      DBMS_OUTPUT.PUT_LINE('Invalid window: end timestamp is earlier than start timestamp.');
      RETURN;
    END IF;

    -- Region must exist.
    SELECT r.name
      INTO lv_region_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE r.region_id = p_region_id;

    DBMS_OUTPUT.PUT_LINE('Max stations displayed = ' || co_station_limit);

    -- For each station in the region, compute state via function and trip activity in the window.
    FOR rec IN (
      SELECT si.station_id,
             si.name AS station_name,
             (
               SELECT COUNT(*)
                 FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
                WHERE t.start_station_id = si.station_id
                  AND (p_start_ts IS NULL OR t.start_date >= p_start_ts)
                  AND (p_end_ts IS NULL OR t.end_date <= p_end_ts)
             ) AS trip_count
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
       WHERE si.region_id = p_region_id
       ORDER BY si.name
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_station_limit;

      -- Calls the previously created function; if it errors, function handles it and returns OFFLINE.
      lv_state := get_station_operational_state(rec.station_id);

      DBMS_OUTPUT.PUT_LINE('Station=' || rec.station_name || ' | State=' || lv_state || ' | trip_count=' || rec.trip_count);
      lv_rows_printed := lv_rows_printed + 1;
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Region not found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END dashboard_region;
END bikeshare_ops_pkg;
/

