  lv_rows PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top patients by encounter count (up to ' || co_report_limit || '):');
  DBMS_OUTPUT.PUT_LINE(RPAD('PATIENT_ID', 38) || RPAD('NAME', 30) || RPAD('GENDER', 8) || 'ENCOUNTERS');

  FOR rec IN (
    SELECT *
    FROM (
      SELECT
        p.id AS patient_id,
        (p.first || ' ' || p.last) AS patient_name,
        p.gender AS gender,
        COUNT(*) AS encounter_cnt
      FROM SYNTHEA.PATIENTS p
      INNER JOIN SYNTHEA.ENCOUNTERS e
