DECLARE
  lv_patient   SYNTHEA.PATIENTS.id%TYPE := 'UNKNOWN';
  lv_expenses  SYNTHEA.PATIENTS.healthcare_expenses%TYPE;
  lv_coverage  SYNTHEA.PATIENTS.healthcare_coverage%TYPE;
  lv_ratio     NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient);

  SELECT p.healthcare_expenses, p.healthcare_coverage
    INTO lv_expenses, lv_coverage
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = lv_patient;

  DBMS_OUTPUT.PUT_LINE('Expenses: ' || TO_CHAR(lv_expenses) || ' | Coverage: ' || TO_CHAR(lv_coverage));

  IF lv_expenses = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Coverage ratio: N/A (expenses is zero)');
  ELSE
    lv_ratio := lv_coverage / lv_expenses;
    DBMS_OUTPUT.PUT_LINE('Coverage ratio: ' || TO_CHAR(lv_ratio));
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No patient found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Coverage ratio: N/A (expenses is zero)');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

