question:
Tie it together for outreach triage: for a single patient id, print their name and then list up to 15 of their most expensive encounters (by total claim cost), including encounter start timestamp, class, and cost. Use the earlier reporting style and make sure the script does not fail if the patient id is missing or has no encounters.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output:
DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient);
DBMS_OUTPUT.PUT_LINE('Name: ' || lv_name);
DBMS_OUTPUT.PUT_LINE('Top encounters by total claim cost (up to ' || co_report_limit || '):');
DBMS_OUTPUT.PUT_LINE(RPAD('START_TS', 22) || RPAD('CLASS', 15) || 'TOTAL_CLAIM_COST');
DBMS_OUTPUT.PUT_LINE(RPAD(TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI:SS'), 22) || RPAD(rec.enc_class, 15) || TO_CHAR(rec.total_cost));
DBMS_OUTPUT.PUT_LINE('No encounters found for patient.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No patient found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient  SYNTHEA.PATIENTS.id%TYPE := 'UNKNOWN';
  lv_name     VARCHAR2(250);
  lv_rows     PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient);

  -- Get patient name first (ensures we give a clear message if patient id is invalid)
  SELECT (p.first || ' ' || p.last)
    INTO lv_name
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = lv_patient;

  DBMS_OUTPUT.PUT_LINE('Name: ' || lv_name);

  DBMS_OUTPUT.PUT_LINE('Top encounters by total claim cost (up to ' || co_report_limit || '):');
  DBMS_OUTPUT.PUT_LINE(RPAD('START_TS', 22) || RPAD('CLASS', 15) || 'TOTAL_CLAIM_COST');

  FOR rec IN (
    SELECT *
    FROM (
      SELECT
        e.start_timestamp AS start_ts,
        e.encounterclass AS enc_class,
        e.total_claim_cost AS total_cost
      FROM SYNTHEA.ENCOUNTERS e
      WHERE e.patient = lv_patient
      ORDER BY e.total_claim_cost DESC NULLS LAST, e.start_timestamp DESC
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI:SS'), 22) || RPAD(rec.enc_class, 15) || TO_CHAR(rec.total_cost)
    );
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No patient found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

