question:
Now turn the scouting report into a reusable component. Create a package that exposes a procedure which, for a given year, walks the same Top-AB list (up to 15 players) and for each player:
checks whether that player was an All-Star in that same year, and
prints a line with AB and an "ALL_STAR=Y/N" flag.

Use explicit cursors (manual OPEN/FETCH/CLOSE) for both the Top-AB list and the All-Star check. Include defensive exception handling for missing inputs and unexpected query problems.

Requirements:
Procedure Name: BASEBALL_SCOUT_PKG.RUN_TOP_AB_ALLSTAR
Parameters:
P_YEAR IN BASEBALL.BATTING.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Top AB + All-Star flag for year=' || p_year);
DBMS_OUTPUT.PUT_LINE('Player=' || lv_player_id || ' AB=' || lv_total_ab || ' ALL_STAR=' || lv_all_star_flag);
DBMS_OUTPUT.PUT_LINE('Year is required.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE baseball_scout_pkg IS
  PROCEDURE run_top_ab_allstar(
    p_year IN BASEBALL.BATTING.year%TYPE
  );
END baseball_scout_pkg;
/

CREATE OR REPLACE PACKAGE BODY baseball_scout_pkg IS
  PROCEDURE run_top_ab_allstar(
    p_year IN BASEBALL.BATTING.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_top_ab(p_in_year BASEBALL.BATTING.year%TYPE) IS
      SELECT b.player_id,
             SUM(b.ab) AS total_ab
        FROM BASEBALL.BATTING b
       WHERE b.year = p_in_year
       GROUP BY b.player_id
       ORDER BY SUM(b.ab) DESC, b.player_id;

    CURSOR c_allstar_flag(
      p_in_year   BASEBALL.ALL_STAR.year%TYPE,
      p_player_id BASEBALL.ALL_STAR.player_id%TYPE
    ) IS
      SELECT NVL(SUM(a.gp), 0) AS total_gp
        FROM BASEBALL.ALL_STAR a
       WHERE a.year = p_in_year
         AND a.player_id = p_player_id;

    lv_player_id     BASEBALL.BATTING.player_id%TYPE;
    lv_total_ab      BASEBALL.BATTING.ab%TYPE;
    lv_rows          PLS_INTEGER := 0;

    lv_total_gp      BASEBALL.ALL_STAR.gp%TYPE;
    lv_all_star_flag VARCHAR2(1);
  BEGIN
    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Year is required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Top AB + All-Star flag for year=' || p_year);

    OPEN c_top_ab(p_year);
    LOOP
      FETCH c_top_ab INTO lv_player_id, lv_total_ab;
      EXIT WHEN c_top_ab%NOTFOUND OR lv_rows >= co_report_limit;

      lv_rows := lv_rows + 1;

      OPEN c_allstar_flag(p_year, lv_player_id);
      FETCH c_allstar_flag INTO lv_total_gp;
      CLOSE c_allstar_flag;

      IF lv_total_gp > 0 THEN
        lv_all_star_flag := 'Y';
      ELSE
        lv_all_star_flag := 'N';
      END IF;

      DBMS_OUTPUT.PUT_LINE('Player=' || lv_player_id || ' AB=' || lv_total_ab || ' ALL_STAR=' || lv_all_star_flag);
    END LOOP;
    CLOSE c_top_ab;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_top_ab_allstar;
END baseball_scout_pkg;
/

