    lv_total_ab      BASEBALL.BATTING.ab%TYPE;
    lv_rows          PLS_INTEGER := 0;

    lv_total_gp      BASEBALL.ALL_STAR.gp%TYPE;
    lv_all_star_flag VARCHAR2(1);
  BEGIN
    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Year is required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Top AB + All-Star flag for year=' || p_year);

    OPEN c_top_ab(p_year);
    LOOP
      FETCH c_top_ab INTO lv_player_id, lv_total_ab;
      EXIT WHEN c_top_ab%NOTFOUND OR lv_rows >= co_report_limit;

      lv_rows := lv_rows + 1;

      OPEN c_allstar_flag(p_year, lv_player_id);
      FETCH c_allstar_flag INTO lv_total_gp;
      CLOSE c_allstar_flag;

      IF lv_total_gp > 0 THEN
        lv_all_star_flag := 'Y';
      ELSE
        lv_all_star_flag := 'N';
      END IF;

      DBMS_OUTPUT.PUT_LINE('Player=' || lv_player_id || ' AB=' || lv_total_ab || ' ALL_STAR=' || lv_all_star_flag);
    END LOOP;
    CLOSE c_top_ab;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_top_ab_allstar;

  PROCEDURE diagnose_allstar_flag(
    p_year  IN BASEBALL.BATTING.year%TYPE,
    p_debug IN VARCHAR2
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_ranked_top_ab(p_in_year BASEBALL.BATTING.year%TYPE) IS
      WITH ab_by_player AS (
        SELECT b.player_id,
               SUM(b.ab) AS total_ab
          FROM BASEBALL.BATTING b
         WHERE b.year = p_in_year
         GROUP BY b.player_id
      ), ranked AS (
        SELECT a.player_id,
               a.total_ab,
               ROW_NUMBER() OVER (ORDER BY a.total_ab DESC, a.player_id) AS rn
          FROM ab_by_player a
      )
      SELECT r.player_id,
             r.total_ab,
             r.rn
        FROM ranked r
       WHERE r.rn <= co_report_limit
       ORDER BY r.rn;

    CURSOR c_allstar_diag(
      p_in_year   BASEBALL.ALL_STAR.year%TYPE,
      p_player_id BASEBALL.ALL_STAR.player_id%TYPE
    ) IS
      SELECT COUNT(*) AS row_count,
             NVL(SUM(a.gp), 0) AS gp_sum
        FROM BASEBALL.ALL_STAR a
       WHERE a.year = p_in_year
         AND a.player_id = p_player_id;

    CURSOR c_player_name(p_player_id BASEBALL.PLAYER.player_id%TYPE) IS
      SELECT p.name_first,
             p.name_last
        FROM BASEBALL.PLAYER p
       WHERE p.player_id = p_player_id;

    lv_player_id BASEBALL.BATTING.player_id%TYPE;
    lv_total_ab  BASEBALL.BATTING.ab%TYPE;
    lv_rn        NUMBER;

    lv_row_count NUMBER;
    lv_gp_sum    BASEBALL.ALL_STAR.gp%TYPE;

    lv_first     BASEBALL.PLAYER.name_first%TYPE;
    lv_last      BASEBALL.PLAYER.name_last%TYPE;
    lv_full_name VARCHAR2(4000);

    lv_all_star_flag VARCHAR2(1);
  BEGIN
    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Year is required.');
      RETURN;
    END IF;

    IF NVL(p_debug, 'N') NOT IN ('Y', 'N') THEN
      DBMS_OUTPUT.PUT_LINE('p_debug must be Y or N.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Diagnose All-Star flag for year=' || p_year || ' debug=' || p_debug);

    OPEN c_ranked_top_ab(p_year);
    LOOP
      FETCH c_ranked_top_ab INTO lv_player_id, lv_total_ab, lv_rn;
      EXIT WHEN c_ranked_top_ab%NOTFOUND;

      OPEN c_allstar_diag(p_year, lv_player_id);
      FETCH c_allstar_diag INTO lv_row_count, lv_gp_sum;
      CLOSE c_allstar_diag;

      IF lv_gp_sum > 0 THEN
        lv_all_star_flag := 'Y';
      ELSE
        lv_all_star_flag := 'N';
      END IF;

      lv_first := NULL;
      lv_last  := NULL;
      OPEN c_player_name(lv_player_id);
      FETCH c_player_name INTO lv_first, lv_last;
      CLOSE c_player_name;
      lv_full_name := NVL(lv_first, 'UNKNOWN') || ' ' || NVL(lv_last, 'UNKNOWN');

      IF p_debug = 'Y' THEN
        DBMS_OUTPUT.PUT_LINE('DEBUG player=' || lv_player_id || ' allstar_row_count=' || lv_row_count || ' gp_sum=' || lv_gp_sum);
      END IF;

      DBMS_OUTPUT.PUT_LINE('Player=' || lv_full_name || ' AB=' || lv_total_ab || ' ALL_STAR=' || lv_all_star_flag || ' ALLSTAR_ROWS=' || lv_row_count || ' GP_SUM=' || lv_gp_sum);
    END LOOP;
    CLOSE c_ranked_top_ab;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END diagnose_allstar_flag;
END baseball_scout_pkg;
/

CREATE OR REPLACE PROCEDURE rpt_upcoming_flights_by_departure(
  p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_departure_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No flights found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Upcoming flights from ' || p_departure_airport || ':');

  FOR rec IN (
    SELECT f.flight_no,
           f.scheduled_departure,
           f.scheduled_arrival,
           f.status
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = p_departure_airport
       AND f.scheduled_departure IS NOT NULL
     ORDER BY f.scheduled_departure
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      'Flight ' || rec.flight_no ||
      ' | Dep ' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
      ' | Arr ' || TO_CHAR(rec.scheduled_arrival, 'YYYY-MM-DD HH24:MI') ||
      ' | Status ' || rec.status
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No flights found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No flights found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_upcoming_flights_by_departure;
