CREATE OR REPLACE FUNCTION fn_departure_punctuality(
  p_flight_id IN AIRLINES.FLIGHTS.flight_id%TYPE
) RETURN VARCHAR2 IS
  lv_sched AIRLINES.FLIGHTS.scheduled_departure%TYPE;
  lv_actual AIRLINES.FLIGHTS.actual_departure%TYPE;
  lv_result VARCHAR2(20);
BEGIN
  SELECT f.scheduled_departure,
         f.actual_departure
    INTO lv_sched,
         lv_actual
    FROM AIRLINES.FLIGHTS f
   WHERE f.flight_id = p_flight_id;

  IF lv_actual IS NULL OR lv_sched IS NULL THEN
    lv_result := 'NO_ACTUAL';
  ELSIF lv_actual < lv_sched THEN
    lv_result := 'EARLY';
  ELSIF lv_actual <= (lv_sched + (15/1440)) THEN
    lv_result := 'ON_TIME';
  ELSE
    lv_result := 'LATE';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Punctuality: ' || lv_result);
  RETURN lv_result;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'NO_DATA';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'MULTIPLE_ROWS';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'ERROR';
END fn_departure_punctuality;
/

