CREATE OR REPLACE PROCEDURE rpt_country_year_snapshot(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
) IS
  lv_country_code CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;
  lv_population   CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.midyear_population%TYPE;
  lv_tfr          CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_match_cnt    NUMBER;
BEGIN
  -- Resolve a single canonical country from the reference list.
  SELECT COUNT(*)
    INTO lv_match_cnt
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';

  IF lv_match_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  ELSIF lv_match_cnt > 1 THEN
    -- Force a controlled TOO_MANY_ROWS path (so callers see a consistent message).
    SELECT c.country_code
      INTO lv_country_code
      FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
     WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';
  END IF;

  SELECT c.country_code, c.country_name
    INTO lv_country_code, lv_country_name
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%'
     AND ROWNUM = 1;

  -- Optional population for that year.
  BEGIN
    SELECT m.midyear_population
      INTO lv_population
      FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
     WHERE m.country_code = lv_country_code
       AND m.year = p_year
       AND ROWNUM = 1;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      lv_population := NULL;
  END;

  -- Optional fertility rate for that year.
  BEGIN
    SELECT f.total_fertility_rate
      INTO lv_tfr
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
     WHERE f.country_code = lv_country_code
       AND f.year = p_year
       AND ROWNUM = 1;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      lv_tfr := NULL;
  END;

  DBMS_OUTPUT.PUT_LINE('Match: ' || lv_country_name || ' (' || lv_country_code || ')');
  DBMS_OUTPUT.PUT_LINE('Year: ' || p_year);
  DBMS_OUTPUT.PUT_LINE('Population: ' || NVL(lv_population, 'N/A'));
  DBMS_OUTPUT.PUT_LINE('Total fertility rate: ' || NVL(lv_tfr, 'N/A'));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_country_year_snapshot;
/

