CREATE OR REPLACE PROCEDURE rpt_country_trend(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
  p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_code CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
  lv_match_count  PLS_INTEGER;
BEGIN
  -- Resolve a single country.
  SELECT COUNT(*)
    INTO lv_match_count
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';

  IF lv_match_count = 0 THEN
    RAISE NO_DATA_FOUND;
  ELSIF lv_match_count > 1 THEN
    RAISE TOO_MANY_ROWS;
  END IF;

  SELECT c.country_code, c.country_name
    INTO lv_country_code, lv_country_name
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (' || lv_country_code || ')');
  DBMS_OUTPUT.PUT_LINE('Range: ' || p_start_year || ' - ' || p_end_year || ', max rows = ' || co_report_limit);

  FOR rec IN (
    WITH years AS (
      SELECT DISTINCT y.year
        FROM (
          SELECT m.year
            FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
           WHERE m.country_code = lv_country_code
             AND TO_NUMBER(m.year) BETWEEN TO_NUMBER(p_start_year) AND TO_NUMBER(p_end_year)
          UNION
          SELECT f.year
            FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
           WHERE f.country_code = lv_country_code
             AND TO_NUMBER(f.year) BETWEEN TO_NUMBER(p_start_year) AND TO_NUMBER(p_end_year)
        ) y
    ),
    series AS (
      SELECT y.year,
             m.midyear_population,
             f.total_fertility_rate,
             LAG(TO_NUMBER(m.midyear_population)) OVER (ORDER BY TO_NUMBER(y.year)) AS prev_pop
        FROM years y
        LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
          ON m.country_code = lv_country_code
         AND m.year = y.year
        LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
          ON f.country_code = lv_country_code
         AND f.year = y.year
    )
    SELECT s.year,
           s.midyear_population,
           s.total_fertility_rate,
           CASE
             WHEN s.midyear_population IS NULL OR s.prev_pop IS NULL THEN 'POP_SAME'
             WHEN TO_NUMBER(s.midyear_population) > s.prev_pop THEN 'POP_UP'
             WHEN TO_NUMBER(s.midyear_population) < s.prev_pop THEN 'POP_DOWN'
             ELSE 'POP_SAME'
           END AS pop_trend
      FROM series s
     ORDER BY TO_NUMBER(s.year)
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    IF lv_rows_printed > co_report_limit THEN
      EXIT;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Year=' || rec.year ||
      ', pop=' || NVL(rec.midyear_population, 'N/A') ||
      ', tfr=' || NVL(rec.total_fertility_rate, 'N/A') ||
      ', pop_trend=' || rec.pop_trend
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows in requested range.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_country_trend;
/

