CREATE OR REPLACE PROCEDURE dq_country_year_check(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
) IS
  lv_country_code CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;

  lv_pop_str      CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.midyear_population%TYPE;
  lv_tfr_str      CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;

  lv_pop_row_cnt  NUMBER := 0;
  lv_tfr_row_cnt  NUMBER := 0;

  lv_pop_row_status VARCHAR2(10);
  lv_tfr_row_status VARCHAR2(10);
  lv_pop_num_status VARCHAR2(10);
  lv_tfr_num_status VARCHAR2(10);
  lv_overall        VARCHAR2(10);

  lv_dummy_num NUMBER;
  lv_country_match_cnt NUMBER := 0;
BEGIN
  SELECT COUNT(*)
    INTO lv_country_match_cnt
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';

  IF lv_country_match_cnt = 0 THEN
    RAISE NO_DATA_FOUND;
  ELSIF lv_country_match_cnt > 1 THEN
    RAISE TOO_MANY_ROWS;
  END IF;

  SELECT c.country_code, c.country_name
    INTO lv_country_code, lv_country_name
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (' || lv_country_code || '), year=' || p_year);

  SELECT COUNT(*)
    INTO lv_pop_row_cnt
    FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
   WHERE m.country_code = lv_country_code
     AND m.year = p_year;

