   WHERE f.country_code = lv_country_code
     AND f.year = p_year;

  IF lv_tfr_row_cnt > 0 THEN
    lv_tfr_row_status := 'PASS';
  ELSE
    lv_tfr_row_status := 'FAIL';
  END IF;

  lv_pop_num_status := 'FAIL';
  IF lv_pop_row_cnt > 0 THEN
    SELECT m.midyear_population
      INTO lv_pop_str
      FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
     WHERE m.country_code = lv_country_code
       AND m.year = p_year
       AND ROWNUM = 1;

    lv_dummy_num := TO_NUMBER(lv_pop_str);
    lv_pop_num_status := 'PASS';
  END IF;

  lv_tfr_num_status := 'FAIL';
  IF lv_tfr_row_cnt > 0 THEN
    SELECT f.total_fertility_rate
      INTO lv_tfr_str
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
     WHERE f.country_code = lv_country_code
       AND f.year = p_year
       AND ROWNUM = 1;

    lv_dummy_num := TO_NUMBER(lv_tfr_str);
    lv_tfr_num_status := 'PASS';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Check POP row exists: ' || lv_pop_row_status);
  DBMS_OUTPUT.PUT_LINE('Check POP numeric: ' || lv_pop_num_status);
  DBMS_OUTPUT.PUT_LINE('Check TFR row exists: ' || lv_tfr_row_status);
  DBMS_OUTPUT.PUT_LINE('Check TFR numeric: ' || lv_tfr_num_status);

  IF lv_pop_row_status = 'PASS' AND lv_tfr_row_status = 'PASS' AND lv_pop_num_status = 'PASS' AND lv_tfr_num_status = 'PASS' THEN
    lv_overall := 'PASS';
  ELSE
    lv_overall := 'FAIL';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Overall DQ: ' || lv_overall);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric value.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END dq_country_year_check;
