CREATE OR REPLACE PROCEDURE rpt_year_inconsistencies(
  p_year IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
  p_mode IN VARCHAR2
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Scan year=' || p_year || ', mode=' || p_mode || ', max rows = ' || co_report_limit);

  IF p_mode = 'POP_WITHOUT_TFR' THEN
    FOR rec IN (
      SELECT DISTINCT m.country_code,
             COALESCE(c.country_name, m.country_name) AS country_name
        FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
        LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
          ON f.country_code = m.country_code
         AND f.year = m.year
        LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
          ON c.country_code = m.country_code
       WHERE m.year = p_year
         AND f.country_code IS NULL
       ORDER BY m.country_code
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      IF lv_rows_printed > co_report_limit THEN
        EXIT;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Country: ' || rec.country_name || ' (' || rec.country_code || ')');
    END LOOP;

  ELSIF p_mode = 'TFR_WITHOUT_POP' THEN
    FOR rec IN (
      SELECT DISTINCT f.country_code,
             COALESCE(c.country_name, f.country_name) AS country_name
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
        LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
          ON m.country_code = f.country_code
         AND m.year = f.year
        LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
          ON c.country_code = f.country_code
       WHERE f.year = p_year
         AND m.country_code IS NULL
       ORDER BY f.country_code
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      IF lv_rows_printed > co_report_limit THEN
        EXIT;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Country: ' || rec.country_name || ' (' || rec.country_code || ')');
    END LOOP;

  ELSE
    DBMS_OUTPUT.PUT_LINE('No inconsistencies found.');
    RETURN;
  END IF;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No inconsistencies found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_year_inconsistencies;
/

