CREATE OR REPLACE PROCEDURE ops_country_year_run(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
) IS
  lv_country_code CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;

  lv_pop_str      CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.midyear_population%TYPE;
  lv_tfr_str      CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;

  lv_pop_row_cnt  NUMBER;
  lv_tfr_row_cnt  NUMBER;

  lv_overall      VARCHAR2(10);
  lv_start_year_n NUMBER;
  lv_end_year_n   NUMBER;
  lv_match_cnt    NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('OPS RUN START: country=' || p_country_name || ', year=' || p_year);

  SELECT COUNT(*)
    INTO lv_match_cnt
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';

  IF lv_match_cnt = 0 THEN
    RAISE NO_DATA_FOUND;
  ELSIF lv_match_cnt > 1 THEN
    RAISE TOO_MANY_ROWS;
  END IF;

  SELECT c.country_code, c.country_name
    INTO lv_country_code, lv_country_name
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE UPPER(c.country_name) LIKE '%' || UPPER(TRIM(p_country_name)) || '%';

  rpt_country_year_snapshot(lv_country_name, p_year);

  SELECT COUNT(*)
    INTO lv_pop_row_cnt
    FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
   WHERE m.country_code = lv_country_code
     AND m.year = p_year;

  SELECT COUNT(*)
    INTO lv_tfr_row_cnt
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
   WHERE f.country_code = lv_country_code
     AND f.year = p_year;

  lv_overall := 'PASS';

  IF lv_pop_row_cnt = 0 OR lv_tfr_row_cnt = 0 THEN
    lv_overall := 'FAIL';
  END IF;

  IF lv_overall = 'PASS' THEN
    SELECT m.midyear_population
      INTO lv_pop_str
      FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
     WHERE m.country_code = lv_country_code
       AND m.year = p_year
       AND ROWNUM = 1;

    SELECT f.total_fertility_rate
      INTO lv_tfr_str
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
     WHERE f.country_code = lv_country_code
       AND f.year = p_year
       AND ROWNUM = 1;

    DECLARE
      lv_dummy NUMBER;
    BEGIN
      lv_dummy := TO_NUMBER(lv_pop_str);
      lv_dummy := TO_NUMBER(lv_tfr_str);
    END;
  END IF;

  IF lv_overall = 'PASS' THEN
    DBMS_OUTPUT.PUT_LINE('OPS: DQ PASS, running trend.');
    lv_end_year_n := TO_NUMBER(p_year);
    lv_start_year_n := lv_end_year_n - 2;
    rpt_country_trend(lv_country_name, TO_CHAR(lv_start_year_n), TO_CHAR(lv_end_year_n));
  ELSE
    DBMS_OUTPUT.PUT_LINE('OPS: DQ FAIL, skipping trend.');
  END IF;

  DBMS_OUTPUT.PUT_LINE('OPS RUN END');

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric value.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END ops_country_year_run;
/

