CREATE OR REPLACE PROCEDURE rpt_top_county_births(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rownum PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(p_year, 'YYYY'));

  -- Ensure we print a friendly message when the year has no rows.
  BEGIN
    SELECT 1
      INTO lv_rownum
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND ROWNUM = 1;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No rows for the requested year.');
      RETURN;
  END;

  lv_rownum := 0;

  FOR rec IN (
    SELECT county_name,
           births_num
      FROM (
        SELECT cn.county_of_residence AS county_name,
               CASE
                 WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+(\.\d+)?$') THEN TO_NUMBER(TRIM(cn.births))
                 ELSE 0
               END AS births_num
          FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
         WHERE cn.year = p_year
         ORDER BY CASE
                    WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+(\.\d+)?$') THEN TO_NUMBER(TRIM(cn.births))
                    ELSE 0
                  END DESC,
                  cn.county_of_residence ASC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rownum := lv_rownum + 1;
    DBMS_OUTPUT.PUT_LINE(LPAD(TO_CHAR(lv_rownum), 2, '0') || '. ' || rec.county_name || ' | births=' || TO_CHAR(rec.births_num));
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_top_county_births;
/

CREATE OR REPLACE PROCEDURE qc_births_text_for_year(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for QC readability
  lv_exists NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('QC births text for year=' || TO_CHAR(p_year, 'YYYY'));

  -- Guard: if no rows exist for the year, print a friendly message.
  BEGIN
    SELECT 1
      INTO lv_exists
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND ROWNUM = 1;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No rows for the requested year.');
      RETURN;
  END;

  FOR rec IN (
    SELECT county_name,
           births_raw,
           status
      FROM (
        SELECT cn.county_of_residence AS county_name,
               cn.births AS births_raw,
               CASE
                 WHEN cn.births IS NULL OR TRIM(cn.births) IS NULL THEN 'BAD_BIRTHS'
                 WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+(\.\d+)?$') THEN 'OK'
                 ELSE 'BAD_BIRTHS'
               END AS status
          FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
         WHERE cn.year = p_year
         ORDER BY cn.county_of_residence ASC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(rec.county_name || ' | births_raw=' || NVL(rec.births_raw, '') || ' | status=' || rec.status);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END qc_births_text_for_year;
/

CREATE OR REPLACE PROCEDURE summarize_births_and_qc(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  lv_total_cnt     NUMBER := 0;
  lv_bad_cnt       NUMBER := 0;
  lv_total_births  NUMBER := 0;
  lv_bad_pct       NUMBER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Summary for year=' || TO_CHAR(p_year, 'YYYY'));

  -- Aggregate in one pass. Numeric births are summed; invalid births contribute 0.
  SELECT COUNT(*),
         SUM(
           CASE
             WHEN cn.births IS NULL OR TRIM(cn.births) IS NULL THEN 0
             WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+(\.\d+)?$') THEN TO_NUMBER(TRIM(cn.births))
             ELSE 0
           END
         ),
         SUM(
           CASE
             WHEN cn.births IS NULL OR TRIM(cn.births) IS NULL THEN 1
             WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+(\.\d+)?$') THEN 0
             ELSE 1
           END
         )
    INTO lv_total_cnt, lv_total_births, lv_bad_cnt
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.year = p_year;

  IF lv_total_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows for the requested year.');
    RETURN;
  END IF;

  lv_bad_pct := (lv_bad_cnt / lv_total_cnt) * 100;

  DBMS_OUTPUT.PUT_LINE('Total births (numeric-only, non-numeric treated as 0)=' || TO_CHAR(lv_total_births));
  DBMS_OUTPUT.PUT_LINE('BAD_BIRTHS counties=' || TO_CHAR(lv_bad_cnt) || ' of ' || TO_CHAR(lv_total_cnt) || ' (' || TO_CHAR(lv_bad_pct, 'FM990D00') || '%)');

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Cannot compute percentage because total counties is 0.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END summarize_births_and_qc;
/

CREATE OR REPLACE PROCEDURE rpt_inventory_by_product(
  p_product_id IN ORACLE_SQL.INVENTORY.product_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_product_name ORACLE_SQL.PRODUCTS.name%TYPE;
  lv_rows         PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Inventory report for product_id=' || NVL(TO_CHAR(p_product_id), 'NULL') || ', max rows=' || co_report_limit);

  IF p_product_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No inventory rows found for this product.');
    RETURN;
  END IF;

  SELECT p.name
    INTO lv_product_name
    FROM ORACLE_SQL.PRODUCTS p
   WHERE p.id = p_product_id;

  DBMS_OUTPUT.PUT_LINE('Product: ' || lv_product_name);

  FOR rec IN (
    SELECT i.location_id,
           l.warehouse,
           l.aisle,
           l.position,
           i.qty
      FROM ORACLE_SQL.INVENTORY i
      INNER JOIN ORACLE_SQL.LOCATIONS l
        ON l.id = i.location_id
     WHERE i.product_id = p_product_id
     ORDER BY i.qty DESC, i.location_id
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE('Location ' || rec.location_id || ' (WH ' || rec.warehouse || ', Aisle ' || rec.aisle || ', Pos ' || rec.position || ') qty=' || rec.qty);
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No inventory rows found for this product.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_inventory_by_product;
/

question:
Using the same inventory data as the previous report, add a checker procedure that flags whether current inventory for a product is below its defined minimum. Show the total on-hand quantity, the minimum quantity, and a clear status message indicating OK or BELOW MINIMUM. If the product has no minimum record or there is no inventory, the procedure should still handle it cleanly.

Requirements:
Procedure Name: chk_product_minimum
Parameters:
p_product_id IN ORACLE_SQL.PRODUCT_MINIMUMS.product_id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Minimum check for product_id=' || NVL(TO_CHAR(p_product_id), 'NULL'));
DBMS_OUTPUT.PUT_LINE('Product: ' || lv_product_name);
DBMS_OUTPUT.PUT_LINE('On-hand qty=' || lv_on_hand_qty || ', minimum=' || lv_min_qty);
DBMS_OUTPUT.PUT_LINE('Status: BELOW MINIMUM');
DBMS_OUTPUT.PUT_LINE('Status: OK');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE chk_product_minimum(
  p_product_id IN ORACLE_SQL.PRODUCT_MINIMUMS.product_id%TYPE
) IS
  lv_product_name ORACLE_SQL.PRODUCTS.name%TYPE;
  lv_on_hand_qty  NUMBER := 0;
  lv_min_qty      ORACLE_SQL.PRODUCT_MINIMUMS.qty_minimum%TYPE := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Minimum check for product_id=' || NVL(TO_CHAR(p_product_id), 'NULL'));

  IF p_product_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Status: BELOW MINIMUM');
    RETURN;
  END IF;

  SELECT p.name
    INTO lv_product_name
    FROM ORACLE_SQL.PRODUCTS p
   WHERE p.id = p_product_id;

  DBMS_OUTPUT.PUT_LINE('Product: ' || lv_product_name);

  BEGIN
    SELECT pm.qty_minimum
      INTO lv_min_qty
      FROM ORACLE_SQL.PRODUCT_MINIMUMS pm
     WHERE pm.product_id = p_product_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      lv_min_qty := 0;
  END;

  SELECT NVL(SUM(i.qty), 0)
    INTO lv_on_hand_qty
    FROM ORACLE_SQL.INVENTORY i
   WHERE i.product_id = p_product_id;

  DBMS_OUTPUT.PUT_LINE('On-hand qty=' || lv_on_hand_qty || ', minimum=' || lv_min_qty);

  IF lv_on_hand_qty < lv_min_qty THEN
    DBMS_OUTPUT.PUT_LINE('Status: BELOW MINIMUM');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Status: OK');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END chk_product_minimum;
/

CREATE OR REPLACE PROCEDURE rpt_order_summary(
  p_order_id IN ORACLE_SQL.ORDERS.id%TYPE
) IS
  lv_order_id       ORACLE_SQL.ORDERS.id%TYPE;
  lv_customer_name  ORACLE_SQL.CUSTOMERS.name%TYPE;
  lv_ordered        ORACLE_SQL.ORDERS.ordered%TYPE;
  lv_delivery       ORACLE_SQL.ORDERS.delivery%TYPE;
  lv_total_qty      NUMBER := 0;
  lv_total_amount   NUMBER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Order summary for order_id=' || NVL(TO_CHAR(p_order_id), 'NULL'));

  IF p_order_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Order id is NULL.');
    RETURN;
  END IF;

  SELECT o.id, o.ordered, o.delivery, c.name
    INTO lv_order_id, lv_ordered, lv_delivery, lv_customer_name
    FROM ORACLE_SQL.ORDERS o
    INNER JOIN ORACLE_SQL.CUSTOMERS c
      ON c.id = o.customer_id
   WHERE o.id = p_order_id;

  DBMS_OUTPUT.PUT_LINE('Order ' || lv_order_id || ' for customer ' || lv_customer_name || ' ordered=' || lv_ordered || ' delivery=' || lv_delivery);

