         NVL(SUM(ol.amount), 0)
    INTO lv_total_qty, lv_total_amount
    FROM ORACLE_SQL.ORDERLINES ol
   WHERE ol.order_id = p_order_id;

  DBMS_OUTPUT.PUT_LINE('Totals: qty=' || lv_total_qty || ', amount=' || lv_total_amount);

