    DBMS_OUTPUT.PUT_LINE('Month is NULL.');
    RETURN;
  END IF;

  FOR rec IN (
    WITH bud AS (
      SELECT mb.product_id,
             SUM(mb.qty) AS budget_qty
        FROM ORACLE_SQL.MONTHLY_BUDGET mb
       WHERE mb.mth = p_mth
       GROUP BY mb.product_id
    ),
    sal AS (
      SELECT ms.product_id,
             SUM(ms.qty) AS sold_qty
        FROM ORACLE_SQL.MONTHLY_SALES ms
       WHERE ms.mth = p_mth
       GROUP BY ms.product_id
    )
    SELECT p.id AS product_id,
           p.name AS product_name,
           NVL(bud.budget_qty, 0) AS budget_qty,
           NVL(sal.sold_qty, 0) AS sold_qty,
           (NVL(sal.sold_qty, 0) - NVL(bud.budget_qty, 0)) AS variance_qty
      FROM ORACLE_SQL.PRODUCTS p
      LEFT OUTER JOIN bud
        ON bud.product_id = p.id
      LEFT OUTER JOIN sal
        ON sal.product_id = p.id
     WHERE NVL(bud.budget_qty, 0) <> 0
        OR NVL(sal.sold_qty, 0) <> 0
     ORDER BY ABS(NVL(sal.sold_qty, 0) - NVL(bud.budget_qty, 0)) DESC, p.id
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE('Product ' || rec.product_id || ' - ' || rec.product_name || ': budget=' || rec.budget_qty || ', sold=' || rec.sold_qty || ', variance=' || rec.variance_qty);
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for this month.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_monthly_sales_vs_budget;
