CREATE OR REPLACE PROCEDURE report_batting_league_year(
  p_year      IN BASEBALL.BATTING.year%TYPE,
  p_league_id IN BASEBALL.BATTING.league_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  v_rows_printed  PLS_INTEGER := 0;

  v_player_id BASEBALL.BATTING.player_id%TYPE;
  v_g         BASEBALL.BATTING.g%TYPE;
  v_ab        BASEBALL.BATTING.ab%TYPE;
  v_h         BASEBALL.BATTING.h%TYPE;
  v_hr        BASEBALL.BATTING.hr%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Batting summary for year=' || p_year || ', league=' || p_league_id);
  DBMS_OUTPUT.PUT_LINE(RPAD('PLAYER_ID', 12) || ' ' || LPAD('G', 6) || ' ' || LPAD('AB', 7) || ' ' || LPAD('H', 7) || ' ' || LPAD('HR', 6));

  FOR r IN (
    SELECT b.player_id,
           SUM(b.g)  AS total_g,
           SUM(b.ab) AS total_ab,
           SUM(b.h)  AS total_h,
           SUM(b.hr) AS total_hr
      FROM BASEBALL.BATTING b
     WHERE b.year = p_year
       AND b.league_id = p_league_id
     GROUP BY b.player_id
     ORDER BY SUM(b.hr) DESC, b.player_id
  ) LOOP
    v_player_id := r.player_id;
    v_g := r.total_g;
    v_ab := r.total_ab;
    v_h := r.total_h;
    v_hr := r.total_hr;

    DBMS_OUTPUT.PUT_LINE(RPAD(v_player_id, 12) || ' ' || LPAD(v_g, 6) || ' ' || LPAD(v_ab, 7) || ' ' || LPAD(v_h, 7) || ' ' || LPAD(v_hr, 6));

    v_rows_printed := v_rows_printed + 1;
    IF v_rows_printed >= co_report_limit THEN
      EXIT;
    END IF;
  END LOOP;

  IF v_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the input filters.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_batting_league_year;
/

