CREATE OR REPLACE FUNCTION get_top_hr_total(
  p_year      IN BASEBALL.BATTING.year%TYPE,
  p_league_id IN BASEBALL.BATTING.league_id%TYPE
) RETURN BASEBALL.BATTING.hr%TYPE IS
  v_top_hr BASEBALL.BATTING.hr%TYPE;
BEGIN
  /*
    Intentionally use a single-row SELECT INTO to demonstrate TOO_MANY_ROWS when ties exist.
    This is useful for QA: ties are possible and should be handled gracefully.
  */
  SELECT t.total_hr
    INTO v_top_hr
    FROM (
      SELECT b.player_id,
             SUM(b.hr) AS total_hr
        FROM BASEBALL.BATTING b
       WHERE b.year = p_year
         AND b.league_id = p_league_id
       GROUP BY b.player_id
       ORDER BY SUM(b.hr) DESC, b.player_id
    ) t
   WHERE t.total_hr = (
         SELECT MAX(x.total_hr)
           FROM (
             SELECT SUM(b2.hr) AS total_hr
               FROM BASEBALL.BATTING b2
              WHERE b2.year = p_year
                AND b2.league_id = p_league_id
              GROUP BY b2.player_id
           ) x
       );

  DBMS_OUTPUT.PUT_LINE('Top HR total for year=' || p_year || ', league=' || p_league_id || ' is ' || v_top_hr);
  RETURN v_top_hr;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the input filters.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple players are tied for the top HR total; returning NULL.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END get_top_hr_total;
/

