CREATE OR REPLACE PACKAGE batting_qa_pkg IS
  FUNCTION safe_hr(p_hr IN BASEBALL.BATTING.hr%TYPE)
    RETURN BASEBALL.BATTING.hr%TYPE;

  PROCEDURE print_batting_summary(
    p_year      IN BASEBALL.BATTING.year%TYPE,
    p_league_id IN BASEBALL.BATTING.league_id%TYPE
  );
END batting_qa_pkg;
/

CREATE OR REPLACE PACKAGE BODY batting_qa_pkg IS
  FUNCTION safe_hr(p_hr IN BASEBALL.BATTING.hr%TYPE)
    RETURN BASEBALL.BATTING.hr%TYPE IS
  BEGIN
    RETURN NVL(p_hr, 0);
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END safe_hr;

  PROCEDURE print_batting_summary(
    p_year      IN BASEBALL.BATTING.year%TYPE,
    p_league_id IN BASEBALL.BATTING.league_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    v_rows_printed  PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Batting QA summary for year=' || p_year || ', league=' || p_league_id);
    DBMS_OUTPUT.PUT_LINE(
      RPAD('PLAYER_ID', 12) || ' ' ||
      LPAD('G', 6) || ' ' ||
      LPAD('AB', 7) || ' ' ||
      LPAD('H', 7) || ' ' ||
      LPAD('HR', 6) || ' ' ||
      'NULL_HR_ROWS'
    );

    FOR r IN (
      SELECT b.player_id,
             SUM(b.g) AS total_g,
             SUM(b.ab) AS total_ab,
             SUM(b.h) AS total_h,
             SUM(batting_qa_pkg.safe_hr(b.hr)) AS safe_total_hr,
             SUM(CASE WHEN b.hr IS NULL THEN 1 ELSE 0 END) AS null_hr_rows
        FROM BASEBALL.BATTING b
       WHERE b.year = p_year
         AND b.league_id = p_league_id
       GROUP BY b.player_id
       ORDER BY SUM(batting_qa_pkg.safe_hr(b.hr)) DESC, b.player_id
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        RPAD(r.player_id, 12) || ' ' ||
        LPAD(r.total_g, 6) || ' ' ||
        LPAD(r.total_ab, 7) || ' ' ||
        LPAD(r.total_h, 7) || ' ' ||
        LPAD(r.safe_total_hr, 6) || ' ' ||
        LPAD(r.null_hr_rows, 12)
      );

      IF r.null_hr_rows > 0 THEN
        DBMS_OUTPUT.PUT_LINE('Null HR detected for player_id=' || r.player_id);
      END IF;

      v_rows_printed := v_rows_printed + 1;
      IF v_rows_printed >= co_report_limit THEN
        EXIT;
      END IF;
    END LOOP;

    IF v_rows_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the input filters.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_batting_summary;
END batting_qa_pkg;
/

