CREATE OR REPLACE PROCEDURE runner_delivery_summary(
  p_runner_id IN MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.runner_id%TYPE
) IS
  lv_delivered_orders NUMBER;
  lv_avg_distance     MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.distance%TYPE;
  lv_avg_duration     MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.duration%TYPE;
BEGIN
  -- Aggregate delivered (non-cancelled) orders for the runner.
  SELECT COUNT(*),
         AVG(r.distance),
         AVG(r.duration)
    INTO lv_delivered_orders,
         lv_avg_distance,
         lv_avg_duration
    FROM MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS r
   WHERE r.runner_id = p_runner_id
     AND r.cancellation IS NULL;

  IF lv_delivered_orders = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Runner ' || p_runner_id ||
    ' delivered_orders=' || lv_delivered_orders ||
    ' avg_distance=' || NVL(TO_CHAR(ROUND(lv_avg_distance, 2)), 'N/A') ||
    ' avg_duration=' || NVL(TO_CHAR(ROUND(lv_avg_duration, 2)), 'N/A')
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No delivered orders found for the runner.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END runner_delivery_summary;
/

CREATE OR REPLACE FUNCTION runner_avg_speed(
  p_runner_id IN MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.runner_id%TYPE
) RETURN NUMBER IS
  lv_total_distance MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.distance%TYPE;
  lv_total_duration MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.duration%TYPE;
  lv_speed          NUMBER;
BEGIN
  -- Sum distance/duration for delivered rows with usable duration.
  SELECT SUM(r.distance),
         SUM(r.duration)
    INTO lv_total_distance,
         lv_total_duration
    FROM MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS r
   WHERE r.runner_id = p_runner_id
     AND r.cancellation IS NULL
     AND r.duration IS NOT NULL
     AND r.duration <> 0;

  IF lv_total_duration IS NULL OR lv_total_distance IS NULL THEN
    RETURN NULL;
  END IF;

  lv_speed := lv_total_distance / lv_total_duration;
  RETURN lv_speed;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN NULL;
  WHEN ZERO_DIVIDE THEN
    RETURN NULL;
  WHEN OTHERS THEN
    RETURN NULL;
END runner_avg_speed;
/

