CREATE OR REPLACE PACKAGE BODY cpi_reporting AS
  PROCEDURE get_cpi_history(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF p_area_name IS NULL OR p_item_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input area name and item name are required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('CPI History (latest first) for Area="' || p_area_name || '", Item="' || p_item_name || '"');
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 95, '-'));
    DBMS_OUTPUT.PUT_LINE(RPAD('YEAR', 6) || RPAD('PERIOD', 8) || 'VALUE');

    FOR rec IN (
      SELECT c.year, c.period, c.value
        FROM BLS.CPI_U c
       WHERE c.area_name = p_area_name
         AND c.item_name = p_item_name
         AND c.period LIKE 'M%'
         AND LENGTH(c.period) = 3
         AND SUBSTR(c.period, 2, 2) BETWEEN '01' AND '12'
       ORDER BY c.year DESC, c.period DESC
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;
      DBMS_OUTPUT.PUT_LINE(RPAD(TO_CHAR(rec.year), 6) || RPAD(rec.period, 8) || rec.value);
      lv_rows_printed := lv_rows_printed + 1;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No monthly CPI rows found for the given filters.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END get_cpi_history;

  FUNCTION get_cpi_pct_change(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE
  ) RETURN NUMBER IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Align calculation window with the report
    lv_newest_value NUMBER;
    lv_oldest_value NUMBER;
    lv_pct_change   NUMBER;
  BEGIN
    IF p_area_name IS NULL OR p_item_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input area name and item name are required.');
      RETURN NULL;
    END IF;

    -- First order the full result set, then cap at the report limit using ROWNUM
    -- in an outer query. This ensures we operate on the 15 most recent records
    -- rather than an arbitrary 15 rows (which ROWNUM would give inside ORDER BY).
    SELECT newest_val, oldest_val
      INTO lv_newest_value, lv_oldest_value
      FROM (
        SELECT MAX(CASE WHEN rn_desc = 1 THEN val_num END) AS newest_val,
               MAX(CASE WHEN rn_asc  = 1 THEN val_num END) AS oldest_val,
               COUNT(*) AS cnt
          FROM (
            SELECT TO_NUMBER(c.value) AS val_num,
                   ROW_NUMBER() OVER (ORDER BY c.year DESC, c.period DESC) AS rn_desc,
                   ROW_NUMBER() OVER (ORDER BY c.year ASC,  c.period ASC)  AS rn_asc
              FROM (
                SELECT c2.year, c2.period, c2.value
                  FROM BLS.CPI_U c2
                 WHERE c2.area_name = p_area_name
                   AND c2.item_name = p_item_name
                   AND c2.period LIKE 'M%'
                   AND LENGTH(c2.period) = 3
                   AND SUBSTR(c2.period, 2, 2) BETWEEN '01' AND '12'
                 ORDER BY c2.year DESC, c2.period DESC
              ) c
             WHERE ROWNUM <= co_report_limit
          )
      )
     WHERE cnt >= 2;

    lv_pct_change := ((lv_newest_value - lv_oldest_value) / lv_oldest_value) * 100;
    RETURN lv_pct_change;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Not enough CPI points to compute percent change.');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN NULL;
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END get_cpi_pct_change;
END cpi_reporting;
/

