DECLARE
  lv_area_name BLS.CPI_U.area_name%TYPE;
  lv_item_name BLS.CPI_U.item_name%TYPE;
  lv_pct       NUMBER;
BEGIN
  -- Choose a stable, most-common pair so the script can run without manual inputs.
  SELECT area_name, item_name
    INTO lv_area_name, lv_item_name
    FROM (
      SELECT c.area_name, c.item_name
        FROM BLS.CPI_U c
       WHERE c.area_name IS NOT NULL
         AND c.item_name IS NOT NULL
       GROUP BY c.area_name, c.item_name
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  lv_pct := cpi_reporting.get_cpi_pct_change(lv_area_name, lv_item_name);

  DBMS_OUTPUT.PUT_LINE('Inflation pulse for Area="' || lv_area_name || '", Item="' || lv_item_name || '"');
  DBMS_OUTPUT.PUT_LINE('Percent change: ' || TO_CHAR(lv_pct));

  IF lv_pct IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Category: Cannot compute');
  ELSIF lv_pct < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Category: Deflation');
  ELSIF lv_pct BETWEEN 0 AND 2 THEN
    DBMS_OUTPUT.PUT_LINE('Category: Low inflation');
  ELSIF lv_pct BETWEEN 2 AND 5 THEN
    DBMS_OUTPUT.PUT_LINE('Category: Moderate inflation');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Category: High inflation');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

