DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_start_date ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE := DATE '2007-01-01';
  lv_end_date   ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE := DATE '2007-12-31';

  CURSOR c_cat_sales(
    p_start_date IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
    p_end_date   IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE
  ) IS
    WITH cat_rollup AS (
      SELECT pc.name AS category_name,
             COUNT(*) AS line_count,
             SUM(sod.orderqty) AS total_qty
        FROM ADVENTUREWORKS.SALESORDERHEADER soh
        INNER JOIN ADVENTUREWORKS.SALESORDERDETAIL sod
          ON sod.salesorderid = soh.salesorderid
        INNER JOIN ADVENTUREWORKS.PRODUCT p
          ON p.productid = sod.productid
        INNER JOIN ADVENTUREWORKS.PRODUCTSUBCATEGORY psc
          ON psc.productsubcategoryid = p.productsubcategoryid
        INNER JOIN ADVENTUREWORKS.PRODUCTCATEGORY pc
          ON pc.productcategoryid = psc.productcategoryid
       WHERE soh.orderdate >= p_start_date
         AND soh.orderdate <  p_end_date + 1
       GROUP BY pc.name
       ORDER BY SUM(sod.orderqty) DESC, pc.name
    )
    SELECT category_name, line_count, total_qty
      FROM cat_rollup
     WHERE ROWNUM <= co_report_limit;

  lv_rows PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Category sales summary from ' || TO_CHAR(lv_start_date, 'YYYY-MM-DD') || ' to ' || TO_CHAR(lv_end_date, 'YYYY-MM-DD'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Category', 35) || ' | ' || LPAD('Lines', 7) || ' | ' || LPAD('Qty', 10));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 7, '-') || '-+-' || LPAD('-', 10, '-'));

  FOR rec IN c_cat_sales(lv_start_date, lv_end_date) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(RPAD(rec.category_name, 35) || ' | ' || LPAD(rec.line_count, 7) || ' | ' || LPAD(rec.total_qty, 10));
  END LOOP;

  IF lv_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the date range.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

