CREATE OR REPLACE PACKAGE BODY pkg_category_sales IS
  PROCEDURE print_category_sales(
    p_start_date IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
    p_end_date   IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_start_date ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE;
    lv_end_date   ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE;

    lv_category_name ADVENTUREWORKS.PRODUCTCATEGORY.name%TYPE;
    lv_line_count    NUMBER;
    lv_total_qty     NUMBER;

    CURSOR c_cat_sales(
      cp_start_date IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
      cp_end_date   IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE
    ) IS
      WITH cat_rollup AS (
        SELECT pc.name AS category_name,
               COUNT(*) AS line_count,
               SUM(sod.orderqty) AS total_qty
          FROM ADVENTUREWORKS.SALESORDERHEADER soh
          INNER JOIN ADVENTUREWORKS.SALESORDERDETAIL sod
            ON sod.salesorderid = soh.salesorderid
          INNER JOIN ADVENTUREWORKS.PRODUCT p
            ON p.productid = sod.productid
          INNER JOIN ADVENTUREWORKS.PRODUCTSUBCATEGORY psc
            ON psc.productsubcategoryid = p.productsubcategoryid
          INNER JOIN ADVENTUREWORKS.PRODUCTCATEGORY pc
            ON pc.productcategoryid = psc.productcategoryid
         WHERE soh.orderdate >= cp_start_date
           AND soh.orderdate <  cp_end_date + 1
         GROUP BY pc.name
         ORDER BY SUM(sod.orderqty) DESC, pc.name
      )
      SELECT category_name, line_count, total_qty
        FROM cat_rollup
       WHERE ROWNUM <= co_report_limit;

    lv_any_rows PLS_INTEGER := 0;
  BEGIN
    lv_start_date := COALESCE(p_start_date, DATE '2007-01-01');
    lv_end_date   := COALESCE(p_end_date,   DATE '2007-12-31');

    IF lv_start_date > lv_end_date THEN
      RAISE VALUE_ERROR;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Category sales summary from ' || TO_CHAR(lv_start_date, 'YYYY-MM-DD') || ' to ' || TO_CHAR(lv_end_date, 'YYYY-MM-DD'));
    DBMS_OUTPUT.PUT_LINE(RPAD('Category', 35) || ' | ' || LPAD('Lines', 7) || ' | ' || LPAD('Qty', 10));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 7, '-') || '-+-' || LPAD('-', 10, '-'));

    OPEN c_cat_sales(lv_start_date, lv_end_date);
    LOOP
      FETCH c_cat_sales INTO lv_category_name, lv_line_count, lv_total_qty;
      EXIT WHEN c_cat_sales%NOTFOUND;

      lv_any_rows := lv_any_rows + 1;
      DBMS_OUTPUT.PUT_LINE(RPAD(lv_category_name, 35) || ' | ' || LPAD(lv_line_count, 7) || ' | ' || LPAD(lv_total_qty, 10));
    END LOOP;
    CLOSE c_cat_sales;

    IF lv_any_rows = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_cat_sales%ISOPEN THEN
        CLOSE c_cat_sales;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No rows matched the date range.');
    WHEN VALUE_ERROR THEN
      IF c_cat_sales%ISOPEN THEN
        CLOSE c_cat_sales;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Invalid date range: start date is after end date.');
    WHEN OTHERS THEN
      IF c_cat_sales%ISOPEN THEN
        CLOSE c_cat_sales;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_category_sales;


  PROCEDURE print_category_price_quality(
    p_top_n IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_top_n NUMBER;

    lv_category_name  ADVENTUREWORKS.PRODUCTCATEGORY.name%TYPE;
    lv_product_count  NUMBER;
    lv_avg_price      NUMBER;
    lv_null_prices    NUMBER;
    lv_flag           VARCHAR2(4);

    CURSOR c_price_quality(cp_top_n IN NUMBER) IS
      WITH cat_price AS (
        SELECT pc.name AS category_name,
               COUNT(*) AS product_count,
               AVG(p.listprice) AS avg_price,
               SUM(CASE WHEN p.listprice IS NULL THEN 1 ELSE 0 END) AS null_prices
          FROM ADVENTUREWORKS.PRODUCTCATEGORY pc
          INNER JOIN ADVENTUREWORKS.PRODUCTSUBCATEGORY psc
            ON psc.productcategoryid = pc.productcategoryid
          INNER JOIN ADVENTUREWORKS.PRODUCT p
            ON p.productsubcategoryid = psc.productsubcategoryid
         GROUP BY pc.name
      ), ranked AS (
        SELECT category_name,
               product_count,
               avg_price,
               null_prices,
               ROW_NUMBER() OVER (ORDER BY avg_price DESC NULLS LAST, category_name) AS rn
          FROM cat_price
      )
      SELECT category_name, product_count, avg_price, null_prices
        FROM ranked
       WHERE rn <= LEAST(cp_top_n, co_report_limit)
       ORDER BY rn;

    lv_any_rows PLS_INTEGER := 0;
  BEGIN
    lv_top_n := COALESCE(p_top_n, co_report_limit);
    IF lv_top_n <= 0 THEN
      lv_top_n := co_report_limit;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Category price quality (top ' || lv_top_n || ' by avg list price)');
    DBMS_OUTPUT.PUT_LINE(RPAD('Category', 35) || ' | ' || LPAD('Products', 8) || ' | ' || LPAD('AvgPrice', 12) || ' | ' || LPAD('NullPrices', 10) || ' | Flag');
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 8, '-') || '-+-' || LPAD('-', 12, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || RPAD('-', 4, '-'));

    OPEN c_price_quality(lv_top_n);
    LOOP
      FETCH c_price_quality INTO lv_category_name, lv_product_count, lv_avg_price, lv_null_prices;
      EXIT WHEN c_price_quality%NOTFOUND;

      lv_any_rows := lv_any_rows + 1;

      IF lv_product_count = 0 THEN
        lv_flag := 'OK';
      ELSIF (lv_null_prices / lv_product_count) > 0.10 THEN
        lv_flag := 'WARN';
      ELSE
        lv_flag := 'OK';
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(lv_category_name, 35) || ' | ' ||
        LPAD(lv_product_count, 8) || ' | ' ||
        LPAD(TO_CHAR(lv_avg_price, '9999990D00'), 12) || ' | ' ||
        LPAD(lv_null_prices, 10) || ' | ' ||
        lv_flag
      );
    END LOOP;
    CLOSE c_price_quality;

    IF lv_any_rows = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_price_quality%ISOPEN THEN
        CLOSE c_price_quality;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No categories found to evaluate.');
    WHEN OTHERS THEN
      IF c_price_quality%ISOPEN THEN
        CLOSE c_price_quality;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_category_price_quality;

END pkg_category_sales;
/

