question:
We need a quick operational report that lists the busiest start stations for a given month. Build a reusable procedure that accepts a month (YYYY-MM) and prints up to 15 start stations ordered by trip count, including a simple 'share of total trips' percentage for that month. Use an explicit cursor so we can extend this later.

Requirements:
Procedure Name: rpt_busiest_start_stations
Parameters:
p_month_yyyymm IN VARCHAR2
Output:
DBMS_OUTPUT.PUT_LINE('Busiest start stations for month ' || p_month_yyyymm);
DBMS_OUTPUT.PUT_LINE(RPAD('START_STATION_ID', 20) || RPAD('TRIPS', 12) || 'PCT_OF_MONTH');
DBMS_OUTPUT.PUT_LINE(RPAD(rec.start_station_id, 20) || RPAD(TO_CHAR(rec.trip_cnt), 12) || TO_CHAR(ROUND((rec.trip_cnt / lv_total_trips) * 100, 2)));
DBMS_OUTPUT.PUT_LINE('No trips found for month ' || p_month_yyyymm);
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Invalid month format. Expected YYYY-MM.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No trips found for month ' || p_month_yyyymm
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid month format. Expected YYYY-MM.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE rpt_busiest_start_stations(
  p_month_yyyymm IN VARCHAR2
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_month_start    TIMESTAMP;
  lv_month_end      TIMESTAMP;
  lv_total_trips    NUMBER;

  CURSOR c_top_stations IS
    SELECT t.start_station_id,
           COUNT(*) AS trip_cnt
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
     WHERE t.start_date >= lv_month_start
       AND t.start_date <  lv_month_end
     GROUP BY t.start_station_id
     ORDER BY COUNT(*) DESC
     FETCH FIRST co_report_limit ROWS ONLY;
BEGIN
  -- Validate and convert YYYY-MM to a timestamp range [start, next_month)
  lv_month_start := TO_TIMESTAMP(p_month_yyyymm || '-01 00:00:00', 'YYYY-MM-DD HH24:MI:SS');
  lv_month_end   := ADD_MONTHS(lv_month_start, 1);

  SELECT COUNT(*)
    INTO lv_total_trips
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
   WHERE t.start_date >= lv_month_start
     AND t.start_date <  lv_month_end;

  IF lv_total_trips = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for month ' || p_month_yyyymm);
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Busiest start stations for month ' || p_month_yyyymm);
  DBMS_OUTPUT.PUT_LINE(RPAD('START_STATION_ID', 20) || RPAD('TRIPS', 12) || 'PCT_OF_MONTH');

  -- Named cursor FOR loop satisfies explicit cursor requirement
  DECLARE
    lv_printed PLS_INTEGER := 0;
  BEGIN
    FOR rec IN c_top_stations LOOP
      lv_printed := lv_printed + 1;
      EXIT WHEN lv_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.start_station_id, 20) ||
        RPAD(TO_CHAR(rec.trip_cnt), 12) ||
        TO_CHAR(ROUND((rec.trip_cnt / lv_total_trips) * 100, 2))
      );
    END LOOP;
  END;

EXCEPTION
