  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid month format. Expected YYYY-MM.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_busiest_start_stations;
/

question:
Operations now want a companion routine that, for the same month parameter, prints a capacity health snapshot of the stations that appeared in the 'busiest start stations' report. For each of the top 15 stations by trip count in that month, show station name, capacity, and the most recently reported number of bikes available (if we have status). Use an explicit cursor and handle cases where station info or status is missing.

Requirements:
Procedure Name: rpt_station_capacity_health
Parameters:
p_month_yyyymm IN VARCHAR2
Output:
DBMS_OUTPUT.PUT_LINE('Station capacity health for month ' || p_month_yyyymm);
DBMS_OUTPUT.PUT_LINE(RPAD('STATION_ID', 20) || RPAD('STATION_NAME', 40) || RPAD('CAPACITY', 10) || 'BIKES_AVAILABLE');
DBMS_OUTPUT.PUT_LINE(RPAD(rec.station_id, 20) || RPAD(rec.station_name, 40) || RPAD(NVL(rec.capacity, 'N/A'), 10) || NVL(rec.bikes_available, 'N/A'));
DBMS_OUTPUT.PUT_LINE('No trips found for month ' || p_month_yyyymm);
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Invalid month format. Expected YYYY-MM.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No trips found for month ' || p_month_yyyymm
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid month format. Expected YYYY-MM.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE rpt_station_capacity_health(
  p_month_yyyymm IN VARCHAR2
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_month_start TIMESTAMP;
  lv_month_end   TIMESTAMP;
  lv_total_trips NUMBER;

  CURSOR c_station_health IS
    WITH top_stations AS (
      SELECT t.start_station_id AS station_id,
             COUNT(*) AS trip_cnt
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
       WHERE t.start_date >= lv_month_start
         AND t.start_date <  lv_month_end
       GROUP BY t.start_station_id
       ORDER BY COUNT(*) DESC
       FETCH FIRST co_report_limit ROWS ONLY
    ),
    latest_status AS (
      SELECT s.station_id,
             s.num_bikes_available AS bikes_available,
             s.last_reported,
             ROW_NUMBER() OVER (PARTITION BY s.station_id ORDER BY TO_NUMBER(s.last_reported) DESC) AS rn
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
    )
    SELECT ts.station_id,
           si.name AS station_name,
           si.capacity,
           ls.bikes_available
      FROM top_stations ts
      LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        ON si.station_id = ts.station_id
      LEFT OUTER JOIN latest_status ls
        ON ls.station_id = ts.station_id
       AND ls.rn = 1
     ORDER BY ts.trip_cnt DESC;
BEGIN
  lv_month_start := TO_TIMESTAMP(p_month_yyyymm || '-01 00:00:00', 'YYYY-MM-DD HH24:MI:SS');
  lv_month_end   := ADD_MONTHS(lv_month_start, 1);

  SELECT COUNT(*)
    INTO lv_total_trips
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
   WHERE t.start_date >= lv_month_start
     AND t.start_date <  lv_month_end;

  IF lv_total_trips = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for month ' || p_month_yyyymm);
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Station capacity health for month ' || p_month_yyyymm);
  DBMS_OUTPUT.PUT_LINE(RPAD('STATION_ID', 20) || RPAD('STATION_NAME', 40) || RPAD('CAPACITY', 10) || 'BIKES_AVAILABLE');

  FOR rec IN c_station_health LOOP
    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.station_id, 20) ||
      RPAD(NVL(rec.station_name, 'UNKNOWN'), 40) ||
      RPAD(NVL(rec.capacity, 'N/A'), 10) ||
      NVL(rec.bikes_available, 'N/A')
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for month ' || p_month_yyyymm);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid month format. Expected YYYY-MM.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_station_capacity_health;
/

question:
Data quality has become an issue. Create a package that can scan station status rows and classify potential problems for a station: missing/invalid numeric fields or impossible values (like negative bikes available). The package should expose a function that returns a problem code, and a procedure that prints a short exception-safe diagnostic for a given station id by iterating through up to the 15 most recent status rows.

Requirements:
Procedure Name: bikeshare_dq_pkg
Parameters:
scan_station_status(p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE)
get_status_problem_code(p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE, p_last_reported IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.last_reported%TYPE, p_bikes_available IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE) RETURN VARCHAR2
Output:
DBMS_OUTPUT.PUT_LINE('DQ scan for station_id=' || p_station_id);
DBMS_OUTPUT.PUT_LINE(RPAD('LAST_REPORTED', 16) || RPAD('BIKES_AVAILABLE', 16) || 'PROBLEM_CODE');
DBMS_OUTPUT.PUT_LINE(RPAD(rec.last_reported, 16) || RPAD(NVL(rec.num_bikes_available, 'NULL'), 16) || lv_problem);
DBMS_OUTPUT.PUT_LINE('No status rows found for station_id=' || p_station_id);
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Bad data encountered while scanning status rows.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No status rows found for station_id=' || p_station_id
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Bad data encountered while scanning status rows.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE bikeshare_dq_pkg IS
  FUNCTION get_status_problem_code(
    p_station_id      IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE,
    p_last_reported   IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.last_reported%TYPE,
    p_bikes_available IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE
  ) RETURN VARCHAR2;

  PROCEDURE scan_station_status(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE
  );
END bikeshare_dq_pkg;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_dq_pkg IS
  FUNCTION get_status_problem_code(
    p_station_id      IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE,
    p_last_reported   IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.last_reported%TYPE,
    p_bikes_available IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE
  ) RETURN VARCHAR2 IS
    lv_bikes_num NUMBER;
    lv_last_num  NUMBER;
  BEGIN
    -- last_reported should be numeric epoch-like text
    IF p_last_reported IS NULL THEN
      RETURN 'MISSING_LAST_REPORTED';
    END IF;

    lv_last_num := TO_NUMBER(p_last_reported);

    -- bikes_available should be numeric text >= 0
    IF p_bikes_available IS NULL THEN
      RETURN 'MISSING_BIKES_AVAILABLE';
    END IF;

    lv_bikes_num := TO_NUMBER(p_bikes_available);

    IF lv_bikes_num < 0 THEN
      RETURN 'NEGATIVE_BIKES_AVAILABLE';
    END IF;

    RETURN 'OK';

  EXCEPTION
    WHEN VALUE_ERROR THEN
      RETURN 'INVALID_NUMERIC_TEXT';
    WHEN OTHERS THEN
      RETURN 'UNEXPECTED_ERROR';
  END get_status_problem_code;


  PROCEDURE scan_station_status(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_recent_status IS
      SELECT s.last_reported,
             s.num_bikes_available
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
       WHERE s.station_id = p_station_id
       ORDER BY TO_NUMBER(s.last_reported) DESC;

    lv_problem VARCHAR2(40);
    lv_printed PLS_INTEGER := 0;
    lv_found   BOOLEAN := FALSE;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('DQ scan for station_id=' || p_station_id);
    DBMS_OUTPUT.PUT_LINE(RPAD('LAST_REPORTED', 16) || RPAD('BIKES_AVAILABLE', 16) || 'PROBLEM_CODE');

    FOR rec IN c_recent_status LOOP
      lv_found := TRUE;
      lv_printed := lv_printed + 1;
      EXIT WHEN lv_printed > co_report_limit;

      lv_problem := get_status_problem_code(p_station_id, rec.last_reported, rec.num_bikes_available);

      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.last_reported, 16) ||
        RPAD(NVL(rec.num_bikes_available, 'NULL'), 16) ||
        lv_problem
      );
    END LOOP;

    IF NOT lv_found THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for station_id=' || p_station_id);
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for station_id=' || p_station_id);
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Bad data encountered while scanning status rows.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END scan_station_status;

END bikeshare_dq_pkg;
/

