DECLARE
  co_top_n_stations CONSTANT PLS_INTEGER := 5; -- Keep DQ scan short for operations

  lv_month_yyyymm VARCHAR2(7);

  CURSOR c_top5_stations(p_yyyymm IN VARCHAR2) IS
    SELECT t.start_station_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
     WHERE TO_CHAR(t.start_date, 'YYYY-MM') = p_yyyymm
     GROUP BY t.start_station_id
     ORDER BY COUNT(*) DESC
     FETCH FIRST co_top_n_stations ROWS ONLY;
BEGIN
  -- Find busiest month (by trip count)
  SELECT x.yyyymm
    INTO lv_month_yyyymm
    FROM (
      SELECT TO_CHAR(t.start_date, 'YYYY-MM') AS yyyymm,
             COUNT(*) AS trip_cnt
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
       GROUP BY TO_CHAR(t.start_date, 'YYYY-MM')
       ORDER BY COUNT(*) DESC
       FETCH FIRST 1 ROWS ONLY
    ) x;

  DBMS_OUTPUT.PUT_LINE('Auto-run for busiest month ' || lv_month_yyyymm);

  rpt_busiest_start_stations(lv_month_yyyymm);
  rpt_station_capacity_health(lv_month_yyyymm);

  -- DQ scan only for top 5 busiest stations in that month
  FOR rec IN c_top5_stations(lv_month_yyyymm) LOOP
    bikeshare_dq_pkg.scan_station_status(rec.start_station_id);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

