   WHERE r.order_id = lv_order_id
     AND r.cancellation IS NULL;
  IF lv_duration < 20 THEN
    lv_label := 'SHORT';
  ELSIF lv_duration <= 40 THEN
    lv_label := 'MEDIUM';
  ELSE
    lv_label := 'LONG';
  END IF;
  DBMS_OUTPUT.PUT_LINE('Order ' || lv_order_id || ': runner=' || lv_runner_id || ', distance=' || TO_CHAR(lv_distance) || ', duration=' || TO_CHAR(lv_duration) || ' => ' || lv_label);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No delivered order found for that order id.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple delivered orders returned for that order id.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

