CREATE OR REPLACE PROCEDURE classify_member_ticker_activity(
  p_member_id      IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE,
  p_ticker         IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE,
  p_qty_threshold  IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.quantity%TYPE
) IS
  lv_total_qty BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.quantity%TYPE;
  lv_label       VARCHAR2(30);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Member=' || p_member_id || ', Ticker=' || p_ticker);

  IF p_member_id IS NULL OR TRIM(p_member_id) IS NULL OR p_ticker IS NULL OR TRIM(p_ticker) IS NULL THEN
    RAISE VALUE_ERROR;
  END IF;

  SELECT SUM(bt.quantity)
    INTO lv_total_qty
    FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
    CROSS JOIN (
      SELECT MAX(bt2.txn_date) AS max_txn_date
        FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt2
       WHERE bt2.member_id = p_member_id
         AND bt2.ticker = p_ticker
    ) m
   WHERE bt.member_id = p_member_id
     AND bt.ticker = p_ticker
     AND bt.txn_date <= m.max_txn_date
     AND bt.txn_date >= TO_CHAR(TO_DATE(m.max_txn_date,'YYYYMMDD') - 30,'YYYYMMDD');

  IF lv_total_qty IS NULL THEN
    RAISE NO_DATA_FOUND;
  END IF;

  IF lv_total_qty >= p_qty_threshold THEN
    lv_label := 'HIGH_VOLUME';
  ELSE
    lv_label := 'NORMAL';
  END IF;

  DBMS_OUTPUT.PUT_LINE('TOTAL_QTY_30D=' || lv_total_qty || ', LABEL=' || lv_label);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No recent transactions found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END classify_member_ticker_activity;
/

CREATE OR REPLACE PROCEDURE report_member_top_ticker_txns(
  p_member_id IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_top_ticker   BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Member: ' || p_member_id);

  IF p_member_id IS NULL OR TRIM(p_member_id) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No transactions found for member.');
    RETURN;
  END IF;

  -- Find the most frequently traded ticker for this member.
  -- If there is a tie, the SELECT INTO will raise TOO_MANY_ROWS.
  SELECT bt.ticker
    INTO lv_top_ticker
    FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
   WHERE bt.member_id = p_member_id
     AND bt.ticker IN (
       SELECT bt2.ticker
         FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt2
        WHERE bt2.member_id = p_member_id
        GROUP BY bt2.ticker
       HAVING COUNT(*) = (
         SELECT MAX(cnt)
           FROM (
             SELECT COUNT(*) AS cnt
               FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt3
              WHERE bt3.member_id = p_member_id
              GROUP BY bt3.ticker
           )
       )
     );

  DBMS_OUTPUT.PUT_LINE('Top ticker: ' || lv_top_ticker);

  FOR rec IN (
    SELECT bt.txn_id,
           bt.txn_date,
           bt.txn_type,
           bt.quantity
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
     WHERE bt.member_id = p_member_id
       AND bt.ticker = lv_top_ticker
     ORDER BY bt.txn_date DESC, bt.txn_time DESC, bt.txn_id DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'TXN_ID=' || rec.txn_id ||
      ', TXN_DATE=' || rec.txn_date ||
      ', TXN_TYPE=' || rec.txn_type ||
      ', QTY=' || rec.quantity
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No transactions found for member.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No transactions found for member.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple top tickers found for member.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_member_top_ticker_txns;
/

CREATE OR REPLACE PROCEDURE pop_snapshot_by_sex(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION_AGESPECIFIC.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION_AGESPECIFIC.year%TYPE
) IS
  co_row_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed_rows PLS_INTEGER := 0;
  lv_dummy        PLS_INTEGER;
BEGIN
  DBMS_OUTPUT.PUT_LINE(
    'Population snapshot for ' || p_country_name || ' in ' || p_year || ' (up to ' || co_row_limit || ' rows)'
  );

  -- Proactively detect empty result set so we can print a single friendly message.
  SELECT 1
    INTO lv_dummy
    FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION_AGESPECIFIC m
   WHERE m.country_name = p_country_name
     AND m.year = p_year
     AND REGEXP_LIKE(m.age, '^\d+$')
     AND ROWNUM = 1;

  FOR r IN (
    SELECT m.sex,
           m.age,
           m.population
      FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION_AGESPECIFIC m
     WHERE m.country_name = p_country_name
       AND m.year = p_year
       AND REGEXP_LIKE(m.age, '^\d+$')
     ORDER BY m.sex, TO_NUMBER(m.age)
  ) LOOP
    EXIT WHEN lv_printed_rows >= co_row_limit;

    DBMS_OUTPUT.PUT_LINE('sex=' || r.sex || ', age=' || r.age || ', population=' || r.population);
    lv_printed_rows := lv_printed_rows + 1;
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching population rows found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END pop_snapshot_by_sex;
/

CREATE OR REPLACE FUNCTION get_natural_increase_status(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
) RETURN VARCHAR2
IS
  lv_rate_txt CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.rate_natural_increase%TYPE;
  lv_rate_num NUMBER;
BEGIN
  SELECT b.rate_natural_increase
    INTO lv_rate_txt
    FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
   WHERE b.country_name = p_country_name
     AND b.year = p_year;

  -- Treat missing values as 0 for classification.
  lv_rate_num := TO_NUMBER(NVL(lv_rate_txt, '0'));

  IF lv_rate_num > 0 THEN
    RETURN 'INCREASING';
  ELSIF lv_rate_num = 0 THEN
    RETURN 'STABLE';
  ELSE
    RETURN 'DECREASING';
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'UNKNOWN';
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
END get_natural_increase_status;
/

