CREATE OR REPLACE PACKAGE BODY demo_report_pkg IS
  PROCEDURE run_country_year_report(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_rank_limit CONSTANT PLS_INTEGER := 10; -- Limit output for report readability

    lv_status  VARCHAR2(20);
    lv_has_tfr PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Country/year demo report: ' || p_country_name || ' - ' || p_year);

    lv_status := get_natural_increase_status(p_country_name, p_year);
    DBMS_OUTPUT.PUT_LINE('Natural increase status: ' || lv_status);

    BEGIN
      SELECT 1
        INTO lv_has_tfr
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
       WHERE a.country_name = p_country_name
         AND a.year <= p_year
         AND REGEXP_LIKE(a.total_fertility_rate, '^\d+(\.\d+)?$')
         AND ROWNUM = 1;

      DBMS_OUTPUT.PUT_LINE('Top fertility years (up to ' || p_year || '), ranked by total fertility rate:');

      FOR r IN (
        WITH ranked AS (
          SELECT a.year,
                 a.total_fertility_rate,
                 ROW_NUMBER() OVER (ORDER BY TO_NUMBER(a.total_fertility_rate) DESC, a.year DESC) rn
            FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
           WHERE a.country_name = p_country_name
             AND a.year <= p_year
             AND REGEXP_LIKE(a.total_fertility_rate, '^\d+(\.\d+)?$')
        )
        SELECT ranked.rn,
               ranked.year,
               ranked.total_fertility_rate
          FROM ranked
         WHERE ranked.rn <= co_rank_limit
         ORDER BY ranked.rn
      ) LOOP
        DBMS_OUTPUT.PUT_LINE(
          'rank=' || r.rn || ', year=' || r.year || ', total_fertility_rate=' || r.total_fertility_rate
        );
      END LOOP;

    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No fertility rows found for this country/year range.');
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    END;

    -- Always show the population snapshot as the final section.
    pop_snapshot_by_sex(p_country_name, p_year);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_country_year_report;
END demo_report_pkg;
/

CREATE OR REPLACE PACKAGE debt_reporting_pkg IS
  PROCEDURE print_region_year_top_debt(
    p_region IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE,
    p_year   IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  );
