CREATE OR REPLACE PACKAGE BODY debt_reporting_pkg IS
  PROCEDURE print_region_year_top_debt(
    p_region IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE,
    p_year   IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_top IS
      SELECT cs.short_name,
             SUM(TO_NUMBER(id.value)) AS total_debt
        FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
        JOIN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
          ON id.country_code = cs.country_code
       WHERE cs.region = p_region
         AND id.year = p_year
       GROUP BY cs.short_name
       ORDER BY SUM(TO_NUMBER(id.value)) DESC;

    lv_rows PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Report: Top countries by total debt');
    DBMS_OUTPUT.PUT_LINE('Region=' || p_region || ', Year=' || p_year);
    DBMS_OUTPUT.PUT_LINE(RPAD('Country', 35) || ' | ' || LPAD('Total Debt', 20));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 20, '-'));

    FOR rec IN c_top LOOP
      lv_rows := lv_rows + 1;
      EXIT WHEN lv_rows > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.short_name, 35) || ' | ' ||
        LPAD(TO_CHAR(rec.total_debt, 'FM999G999G999G999G990D00'), 20)
      );
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric debt value encountered.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_region_year_top_debt;
END debt_reporting_pkg;
/

