       GROUP BY cs.short_name
       ORDER BY SUM(TO_NUMBER(id.value)) DESC;

    lv_rows PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Report: Top countries by total debt');
    DBMS_OUTPUT.PUT_LINE('Region=' || p_region || ', Year=' || p_year);
    DBMS_OUTPUT.PUT_LINE(RPAD('Country', 35) || ' | ' || LPAD('Total Debt', 20));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 20, '-'));

    FOR rec IN c_top LOOP
      lv_rows := lv_rows + 1;
      EXIT WHEN lv_rows > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.short_name, 35) || ' | ' ||
        LPAD(TO_CHAR(rec.total_debt, 'FM999G999G999G999G990D00'), 20)
      );
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric debt value encountered.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_region_year_top_debt;


  PROCEDURE scan_bad_debt_values(
    p_year IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  ) IS
    co_print_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_debt IS
      SELECT id.country_name,
             id.indicator_code,
             id.value
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
       WHERE id.year = p_year
       ORDER BY id.country_name, id.indicator_code;

    lv_country_name  WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_name%TYPE;
    lv_indicator_code WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE;
    lv_value         WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.value%TYPE;

    lv_checked PLS_INTEGER := 0;
    lv_bad     PLS_INTEGER := 0;
    lv_printed PLS_INTEGER := 0;

    lv_num NUMBER;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Data quality scan for YEAR=' || p_year);

    OPEN c_debt;
    LOOP
      FETCH c_debt INTO lv_country_name, lv_indicator_code, lv_value;
      EXIT WHEN c_debt%NOTFOUND;

      lv_checked := lv_checked + 1;

      BEGIN
        lv_num := TO_NUMBER(lv_value);
      EXCEPTION
        WHEN OTHERS THEN
          lv_bad := lv_bad + 1;
          IF lv_printed < co_print_limit THEN
            lv_printed := lv_printed + 1;
            DBMS_OUTPUT.PUT_LINE(
              'Bad row: COUNTRY_NAME=' || lv_country_name ||
              ', INDICATOR_CODE=' || lv_indicator_code ||
              ', VALUE=' || lv_value
            );
          END IF;
      END;
    END LOOP;
    CLOSE c_debt;

    IF lv_checked = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Rows checked=' || lv_checked || ', Bad rows=' || lv_bad);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END scan_bad_debt_values;
END debt_reporting_pkg;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;
  lv_year   WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE;

  CURSOR c_ranked IS
    WITH totals AS (
      SELECT cs.short_name,
             SUM(TO_NUMBER(id.value)) AS total_debt
        FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
        JOIN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
          ON id.country_code = cs.country_code
       WHERE cs.region = lv_region
         AND id.year = lv_year
       GROUP BY cs.short_name
    ), ranked AS (
      SELECT t.short_name,
             t.total_debt,
             ROW_NUMBER() OVER (ORDER BY t.total_debt DESC) AS rn
        FROM totals t
    )
    SELECT r.rn,
           r.short_name,
           r.total_debt
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn;

  lv_rank       NUMBER;
  lv_short_name WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_total_debt NUMBER;

  lv_rows PLS_INTEGER := 0;
BEGIN
  SELECT cs.region
    INTO lv_region
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.region IS NOT NULL
   GROUP BY cs.region
   ORDER BY COUNT(*) DESC
   FETCH FIRST 1 ROWS ONLY;

  SELECT id.year
    INTO lv_year
    FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
   WHERE id.year IS NOT NULL
   GROUP BY id.year
   ORDER BY COUNT(*) DESC
   FETCH FIRST 1 ROWS ONLY;

  DBMS_OUTPUT.PUT_LINE('Runbook parameters: REGION=' || lv_region || ', YEAR=' || lv_year);

  DBMS_OUTPUT.PUT_LINE('Calling scan_bad_debt_values for YEAR=' || lv_year);
  debt_reporting_pkg.scan_bad_debt_values(lv_year);

  DBMS_OUTPUT.PUT_LINE('Ranked report (Top 15):');
  DBMS_OUTPUT.PUT_LINE(LPAD('Rank', 4) || ' | ' || RPAD('Country', 35) || ' | ' || LPAD('Total Debt', 20));

  OPEN c_ranked;
  LOOP
    FETCH c_ranked INTO lv_rank, lv_short_name, lv_total_debt;
    EXIT WHEN c_ranked%NOTFOUND;

    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      LPAD(TO_CHAR(lv_rank), 4) || ' | ' ||
      RPAD(lv_short_name, 35) || ' | ' ||
      LPAD(TO_CHAR(lv_total_debt, 'FM999G999G999G999G990D00'), 20)
    );
  END LOOP;
  CLOSE c_ranked;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

