CREATE OR REPLACE FUNCTION get_lending_label(
  p_country_code IN WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE
) RETURN VARCHAR2 IS
  lv_lending_category WORLD_BANK_WDI.COUNTRY_SUMMARY.lending_category%TYPE;
BEGIN
  IF p_country_code IS NULL THEN
    RETURN 'Not specified';
  END IF;

  SELECT cs.lending_category
    INTO lv_lending_category
    FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
   WHERE cs.country_code = p_country_code;

  IF lv_lending_category IS NULL THEN
    RETURN 'Not specified';
  END IF;

  RETURN lv_lending_category;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'Not specified';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'Not specified';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'Not specified';
END get_lending_label;
/

DECLARE
