  PROCEDURE report_country_year_indicators(
    p_country_code IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
    p_year         IN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE
  );
END wdi_reporting;
/

CREATE OR REPLACE PACKAGE BODY wdi_reporting IS
  PROCEDURE report_country_year_indicators(
    p_country_code IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
    p_year         IN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_year         WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;
    lv_country_name WORLD_BANK_WDI.INDICATORS_DATA.country_name%TYPE;
    lv_row_count    PLS_INTEGER := 0;
  BEGIN
    IF p_country_code IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    IF p_year IS NULL THEN
      lv_year := '2010';
    ELSE
      lv_year := p_year;
    END IF;

    SELECT x.country_name
      INTO lv_country_name
      FROM (
            SELECT id.country_name
              FROM WORLD_BANK_WDI.INDICATORS_DATA id
             WHERE id.country_code = p_country_code
               AND id.year = lv_year
             GROUP BY id.country_name
             ORDER BY COUNT(*) DESC, id.country_name
           ) x
     WHERE ROWNUM = 1;

    DBMS_OUTPUT.PUT_LINE('Indicators for ' || lv_country_name || ' (' || p_country_code || '), year=' || lv_year);

    FOR rec IN (
      SELECT id.indicator_name, id.value
        FROM WORLD_BANK_WDI.INDICATORS_DATA id
       WHERE id.country_code = p_country_code
         AND id.year = lv_year
       ORDER BY id.indicator_name
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_row_count := lv_row_count + 1;
      DBMS_OUTPUT.PUT_LINE('- ' || rec.indicator_name || ': ' || rec.value);
    END LOOP;

    IF lv_row_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No indicator rows found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_country_year_indicators;
END wdi_reporting;
/

