CREATE OR REPLACE PACKAGE natality_rpt_pkg AS
  PROCEDURE print_county_year_summary(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  );
END natality_rpt_pkg;
/
CREATE OR REPLACE PACKAGE BODY natality_rpt_pkg AS
  PROCEDURE print_county_year_summary(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Dashboard county natality summary (max rows = ' || co_report_limit || ')');

    FOR rec IN (
      SELECT cn.year,
             cn.county_of_residence,
             TO_NUMBER(cn.births) AS births_num,
             TO_NUMBER(cn.ave_age_of_mother) AS ave_age_num,
             TO_NUMBER(cn.ave_birth_weight_gms) AS ave_bw_num
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
         AND cn.county_of_residence = p_county_name
         AND ROWNUM <= co_report_limit
       ORDER BY cn.county_of_residence
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'Year=' || TO_CHAR(rec.year, 'YYYY') ||
        ' County=' || rec.county_of_residence ||
        ' Births=' || rec.births_num ||
        ' AveAgeMother=' || TO_CHAR(rec.ave_age_num) ||
