CREATE OR REPLACE PACKAGE natality_rpt_pkg AS
  PROCEDURE print_county_year_summary(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  );

  PROCEDURE check_births_numeric(
    p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
  );
END natality_rpt_pkg;
/
CREATE OR REPLACE PACKAGE BODY natality_rpt_pkg AS
  PROCEDURE print_county_year_summary(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Dashboard county natality summary (max rows = ' || co_report_limit || ')');

    FOR rec IN (
      SELECT cn.year,
             cn.county_of_residence,
             TO_NUMBER(cn.births) AS births_num,
             TO_NUMBER(cn.ave_age_of_mother) AS ave_age_num,
             TO_NUMBER(cn.ave_birth_weight_gms) AS ave_bw_num
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
         AND cn.county_of_residence = p_county_name
         AND ROWNUM <= co_report_limit
       ORDER BY cn.county_of_residence
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'Year=' || TO_CHAR(rec.year, 'YYYY') ||
        ' County=' || rec.county_of_residence ||
        ' Births=' || rec.births_num ||
        ' AveAgeMother=' || TO_CHAR(rec.ave_age_num) ||
        ' AveBirthWeightGms=' || TO_CHAR(rec.ave_bw_num)
      );
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_county_year_summary;

  PROCEDURE check_births_numeric(
    p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
  ) IS
    co_check_limit CONSTANT PLS_INTEGER := 15; -- Keep the scan small and predictable
    lv_bad_rows    PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'Births numeric check (max rows = ' || co_check_limit || ') for year ' || TO_CHAR(p_year, 'YYYY')
    );

    FOR rec IN (
      SELECT cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
         AND ROWNUM <= co_check_limit
    ) LOOP
      BEGIN
        -- If conversion fails, mark as a bad row and continue.
        DECLARE
          lv_births_num NUMBER;
        BEGIN
          lv_births_num := TO_NUMBER(rec.births);
        EXCEPTION
          WHEN VALUE_ERROR THEN
            lv_bad_rows := lv_bad_rows + 1;
        END;
      END;
    END LOOP;

    IF lv_bad_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Data quality OK: all checked births values are numeric.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Data quality issue: non-numeric births values found = ' || lv_bad_rows);
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END check_births_numeric;
END natality_rpt_pkg;
/

