    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) RETURN NUMBER IS
    lv_total NUMBER;
  BEGIN
    SELECT SUM(TO_NUMBER(cn.births))
      INTO lv_total
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND cn.county_of_residence = p_county_name;

    IF lv_total IS NULL THEN
      -- SUM returns NULL when there are no matching rows.
      DBMS_OUTPUT.PUT_LINE('No matching rows; returning 0.');
      RETURN 0;
    END IF;

    RETURN lv_total;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No matching rows; returning 0.');
      RETURN 0;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
