    p_county_name    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
    p_morbidity_desc IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY.maternal_morbidity_desc%TYPE
  );
END morbidity_compare_pkg;
/
CREATE OR REPLACE PACKAGE BODY morbidity_compare_pkg AS
  PROCEDURE print_morbidity_birth_share(
    p_year           IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
    p_morbidity_desc IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY.maternal_morbidity_desc%TYPE
  ) IS
    lv_base_births NUMBER := 0;
    lv_morb_births NUMBER := 0;
  BEGIN
    -- Baseline births for county/year
    SELECT SUM(TO_NUMBER(cn.births))
      INTO lv_base_births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND cn.county_of_residence = p_county_name;

    IF lv_base_births IS NULL THEN
      lv_base_births := 0;
    END IF;

    -- Morbidity births for county/year where the flag is Yes
    SELECT SUM(TO_NUMBER(mm.births))
      INTO lv_morb_births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY mm
     WHERE mm.year = p_year
       AND mm.county_of_residence = p_county_name
       AND mm.maternal_morbidity_desc = p_morbidity_desc
       AND mm.maternal_morbidity_yn = 'Yes';

    IF lv_morb_births IS NULL THEN
      lv_morb_births := 0;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Baseline births=' || TO_CHAR(lv_base_births));
    DBMS_OUTPUT.PUT_LINE('Morbidity births (Yes)=' || TO_CHAR(lv_morb_births));

    IF lv_base_births = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Cannot compute share: baseline births is 0.');
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'Morbidity share pct=' || TO_CHAR(ROUND((lv_morb_births / lv_base_births) * 100, 2))
      );
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid number encountered in births fields.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_morbidity_birth_share;
END morbidity_compare_pkg;
/

