question:
Build an initial reporting script for our demography dashboard.

For a given country name and year range, print up to 15 yearly rows showing: year, crude birth rate, crude death rate, and growth rate (all as numbers where possible). If any rate value is not numeric, treat it as NULL and still print the row.

Use an explicit cursor (declare it and fetch from it) so we can later add more row-by-row logic. Add clear exception handling so the script never terminates with an unhandled error.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Year | Birth | Death | Growth');
DBMS_OUTPUT.PUT_LINE('-----+-------+-------+-------');
DBMS_OUTPUT.PUT_LINE(lv_year || ' | ' || NVL(TO_CHAR(lv_birth_rate), 'NULL') || ' | ' || NVL(TO_CHAR(lv_death_rate), 'NULL') || ' | ' || NVL(TO_CHAR(lv_growth_rate), 'NULL'));
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE := 'India';
  lv_year_from    CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE := '2000';
  lv_year_to      CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE := '2010';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_rates IS
    SELECT r.year,
           CASE
             WHEN REGEXP_LIKE(r.crude_birth_rate, '^\s*-?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(r.crude_birth_rate))
             ELSE NULL
           END AS crude_birth_rate_num,
           CASE
             WHEN REGEXP_LIKE(r.crude_death_rate, '^\s*-?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(r.crude_death_rate))
             ELSE NULL
           END AS crude_death_rate_num,
           CASE
             WHEN REGEXP_LIKE(r.growth_rate, '^\s*-?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(r.growth_rate))
             ELSE NULL
           END AS growth_rate_num
      FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES r
     WHERE r.country_name = lv_country_name
       AND r.year BETWEEN lv_year_from AND lv_year_to
     ORDER BY r.year;

  lv_year        CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE;
  lv_birth_rate  NUMBER;
  lv_death_rate  NUMBER;
  lv_growth_rate NUMBER;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Year | Birth | Death | Growth');
  DBMS_OUTPUT.PUT_LINE('-----+-------+-------+-------');

  OPEN c_rates;
  LOOP
    FETCH c_rates INTO lv_year, lv_birth_rate, lv_death_rate, lv_growth_rate;
    EXIT WHEN c_rates%NOTFOUND;

    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      lv_year || ' | ' || NVL(TO_CHAR(lv_birth_rate), 'NULL') || ' | ' || NVL(TO_CHAR(lv_death_rate), 'NULL') || ' | ' || NVL(TO_CHAR(lv_growth_rate), 'NULL')
    );
  END LOOP;
  CLOSE c_rates;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_rates%ISOPEN THEN
      CLOSE c_rates;
    END IF;
END;
/

