CREATE OR REPLACE PROCEDURE get_avg_birth_death(
  p_country_name IN  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE,
  p_year_from    IN  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
  p_year_to      IN  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
  p_avg_birth    OUT NUMBER,
  p_avg_death    OUT NUMBER
) IS
  CURSOR c_rates IS
    SELECT r.crude_birth_rate,
           r.crude_death_rate
      FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES r
     WHERE r.country_name = p_country_name
       AND r.year BETWEEN p_year_from AND p_year_to;

  lv_birth_raw CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_birth_rate%TYPE;
  lv_death_raw CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_death_rate%TYPE;

  lv_birth_num NUMBER;
  lv_death_num NUMBER;

  lv_birth_sum NUMBER := 0;
  lv_death_sum NUMBER := 0;

  lv_birth_cnt PLS_INTEGER := 0;
  lv_death_cnt PLS_INTEGER := 0;
BEGIN
  p_avg_birth := NULL;
  p_avg_death := NULL;

  OPEN c_rates;
  LOOP
    FETCH c_rates INTO lv_birth_raw, lv_death_raw;
    EXIT WHEN c_rates%NOTFOUND;

    IF REGEXP_LIKE(lv_birth_raw, '^\s*-?\d+(\.\d+)?\s*$') THEN
      lv_birth_num := TO_NUMBER(TRIM(lv_birth_raw));
      lv_birth_sum := lv_birth_sum + lv_birth_num;
      lv_birth_cnt := lv_birth_cnt + 1;
    END IF;

    IF REGEXP_LIKE(lv_death_raw, '^\s*-?\d+(\.\d+)?\s*$') THEN
      lv_death_num := TO_NUMBER(TRIM(lv_death_raw));
      lv_death_sum := lv_death_sum + lv_death_num;
      lv_death_cnt := lv_death_cnt + 1;
    END IF;
  END LOOP;
  CLOSE c_rates;

  IF lv_birth_cnt > 0 THEN
    p_avg_birth := lv_birth_sum / lv_birth_cnt;
  END IF;

  IF lv_death_cnt > 0 THEN
    p_avg_death := lv_death_sum / lv_death_cnt;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Avg crude birth rate: ' || NVL(TO_CHAR(p_avg_birth), 'NULL'));
  DBMS_OUTPUT.PUT_LINE('Avg crude death rate: ' || NVL(TO_CHAR(p_avg_death), 'NULL'));

  IF lv_birth_cnt = 0 AND lv_death_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_rates%ISOPEN THEN
      CLOSE c_rates;
    END IF;
END get_avg_birth_death;
/

