question:
We need a quality gate before publishing the country/year metrics.

Create a package that exposes:
 a function that validates the year range inputs (not null, numeric 4-digit strings, from <= to). The function should return 'Y' if valid, otherwise 'N'.
 a procedure that calls that validator and then calls the stored procedure from the previous step to compute averages; if validation fails, print a clear message and do not attempt any data access.

Make sure exceptions are handled and reported via DBMS_OUTPUT.

Requirements:
Procedure Name: demo_quality_gate_pkg
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Validation failed.');
DBMS_OUTPUT.PUT_LINE('Avg crude birth rate: ' || NVL(TO_CHAR(lv_avg_birth), 'NULL'));
DBMS_OUTPUT.PUT_LINE('Avg crude death rate: ' || NVL(TO_CHAR(lv_avg_death), 'NULL'));
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE demo_quality_gate_pkg IS
  FUNCTION is_valid_year_range(
    p_year_from IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
    p_year_to   IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  ) RETURN VARCHAR2;

  PROCEDURE run_avg_report(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE,
    p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
    p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  );
END demo_quality_gate_pkg;
/

CREATE OR REPLACE PACKAGE BODY demo_quality_gate_pkg IS
  FUNCTION is_valid_year_range(
    p_year_from IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
    p_year_to   IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  ) RETURN VARCHAR2 IS
    lv_from_num NUMBER;
    lv_to_num   NUMBER;
  BEGIN
    IF p_year_from IS NULL OR p_year_to IS NULL THEN
      RETURN 'N';
    END IF;

    IF NOT REGEXP_LIKE(p_year_from, '^\d{4}$') OR NOT REGEXP_LIKE(p_year_to, '^\d{4}$') THEN
      RETURN 'N';
    END IF;

    lv_from_num := TO_NUMBER(p_year_from);
    lv_to_num   := TO_NUMBER(p_year_to);

    IF lv_from_num > lv_to_num THEN
      RETURN 'N';
    END IF;

    RETURN 'Y';
  EXCEPTION
    WHEN OTHERS THEN
      RETURN 'N';
  END is_valid_year_range;

  PROCEDURE run_avg_report(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE,
    p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
    p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  ) IS
    lv_avg_birth NUMBER;
    lv_avg_death NUMBER;
  BEGIN
    IF is_valid_year_range(p_year_from, p_year_to) <> 'Y' THEN
      DBMS_OUTPUT.PUT_LINE('Validation failed.');
      RETURN;
    END IF;

    get_avg_birth_death(
      p_country_name => p_country_name,
      p_year_from    => p_year_from,
      p_year_to      => p_year_to,
      p_avg_birth    => lv_avg_birth,
      p_avg_death    => lv_avg_death
    );

    DBMS_OUTPUT.PUT_LINE('Avg crude birth rate: ' || NVL(TO_CHAR(lv_avg_birth), 'NULL'));
    DBMS_OUTPUT.PUT_LINE('Avg crude death rate: ' || NVL(TO_CHAR(lv_avg_death), 'NULL'));

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_avg_report;
END demo_quality_gate_pkg;
/

DECLARE
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE;
BEGIN
  SELECT country_name
    INTO lv_country_name
    FROM (
      SELECT country_name
        FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES
