CREATE OR REPLACE PROCEDURE find_latest_high_tfr(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE
) IS
  co_tfr_threshold CONSTANT NUMBER := 2.1;

  CURSOR c_tfr IS
    SELECT r.year,
           r.total_fertility_rate
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES r
     WHERE r.country_name = p_country_name
     ORDER BY r.year;

  lv_year_raw CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;
  lv_tfr_raw  CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;

  lv_year_num NUMBER;
  lv_tfr_num  NUMBER;

  lv_best_year CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE := NULL;
  lv_best_tfr  NUMBER := NULL;

  lv_found BOOLEAN := FALSE;
BEGIN
  OPEN c_tfr;
  LOOP
    FETCH c_tfr INTO lv_year_raw, lv_tfr_raw;
    EXIT WHEN c_tfr%NOTFOUND;

    IF REGEXP_LIKE(lv_year_raw, '^\d{4}$') AND REGEXP_LIKE(lv_tfr_raw, '^\s*-?\d+(\.\d+)?\s*$') THEN
      lv_year_num := TO_NUMBER(lv_year_raw);
      lv_tfr_num  := TO_NUMBER(TRIM(lv_tfr_raw));

      IF lv_tfr_num > co_tfr_threshold THEN
        IF (NOT lv_found) OR (lv_year_num > TO_NUMBER(lv_best_year)) THEN
          lv_best_year := lv_year_raw;
          lv_best_tfr  := lv_tfr_num;
          lv_found := TRUE;
        END IF;
      END IF;
    END IF;
  END LOOP;
  CLOSE c_tfr;

  IF lv_found THEN
    DBMS_OUTPUT.PUT_LINE('Latest high TFR: ' || lv_best_year || ' (TFR=' || TO_CHAR(lv_best_tfr) || ')');
  ELSE
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_tfr%ISOPEN THEN
      CLOSE c_tfr;
    END IF;
END find_latest_high_tfr;
/

CREATE OR REPLACE PROCEDURE report_channel_sales_by_year(
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top channels for year ' || p_calendar_year || ':');
  DBMS_OUTPUT.PUT_LINE(RPAD('CHANNEL', 30) || ' | ' || LPAD('TOTAL_AMOUNT', 15));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || '-+-' || LPAD('-', 15, '-'));

  FOR rec IN (
    SELECT ch.channel_desc,
           SUM(s.amount_sold) AS total_amount
      FROM COMPLEX_ORACLE.SALES s
      INNER JOIN COMPLEX_ORACLE.TIMES t
        ON t.time_id = s.time_id
      INNER JOIN COMPLEX_ORACLE.CHANNELS ch
        ON ch.channel_id = s.channel_id
     WHERE t.calendar_year = p_calendar_year
     GROUP BY ch.channel_desc
     ORDER BY SUM(s.amount_sold) DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(NVL(rec.channel_desc, 'UNKNOWN'), 30) || ' | ' ||
      LPAD(TO_CHAR(rec.total_amount, 'FM999G999G999G990D00'), 15)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No channels found for year ' || p_calendar_year || '.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_sales_by_year;
/

