CREATE OR REPLACE FUNCTION get_channel_perf_label(
  p_channel_id    IN COMPLEX_ORACLE.CHANNELS.channel_id%TYPE,
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE
) RETURN VARCHAR2 IS
  lv_total COMPLEX_ORACLE.SALES.amount_sold%TYPE;
  lv_label VARCHAR2(10);
BEGIN
  -- Aggregate to one row per channel/year; if no rows, treat as NO_DATA_FOUND.
  SELECT SUM(s.amount_sold)
    INTO lv_total
    FROM COMPLEX_ORACLE.SALES s
    INNER JOIN COMPLEX_ORACLE.TIMES t
      ON t.time_id = s.time_id
   WHERE s.channel_id = p_channel_id
     AND t.calendar_year = p_calendar_year;

  IF lv_total IS NULL THEN
    RAISE NO_DATA_FOUND;
  ELSIF lv_total >= 1000000 THEN
    lv_label := 'HIGH';
  ELSIF lv_total >= 100000 THEN
    lv_label := 'MEDIUM';
  ELSE
    lv_label := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Channel ' || p_channel_id || ' year ' || p_calendar_year ||
    ' total=' || TO_CHAR(lv_total, 'FM999G999G999G990D00') ||
    ' label=' || lv_label
  );

  RETURN lv_label;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No sales found for channel/year.');
    RETURN 'UNKNOWN';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'UNKNOWN';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
END get_channel_perf_label;
/

