CREATE OR REPLACE PACKAGE channel_kpi_pkg IS
  PROCEDURE print_top_channels(
    p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
    p_debug         IN NUMBER
  );
END channel_kpi_pkg;
/

CREATE OR REPLACE PACKAGE BODY channel_kpi_pkg IS
  PROCEDURE print_top_channels(
    p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
    p_debug         IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
    lv_year_as_text VARCHAR2(20);
  BEGIN
    IF p_debug = 1 THEN
      DBMS_OUTPUT.PUT_LINE('DEBUG: Starting print_top_channels for year ' || p_calendar_year);

      -- Debugging exercise: the original buggy line was:
      --   lv_year_as_text := p_calendar_year;
      -- which raises VALUE_ERROR (invalid implicit conversion). Fixed with TO_CHAR.
      lv_year_as_text := TO_CHAR(p_calendar_year);
      DBMS_OUTPUT.PUT_LINE('DEBUG: year_as_text=' || lv_year_as_text);
    END IF;

    DBMS_OUTPUT.PUT_LINE(RPAD('CHANNEL', 30) || ' | ' || LPAD('TOTAL_AMOUNT', 15) || ' | ' || RPAD('LABEL', 6));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || '-+-' || LPAD('-', 15, '-') || '-+-' || RPAD('-', 6, '-'));

    FOR rec IN (
      SELECT s.channel_id,
             ch.channel_desc,
             SUM(s.amount_sold) AS total_amount
        FROM COMPLEX_ORACLE.SALES s
        INNER JOIN COMPLEX_ORACLE.TIMES t
          ON t.time_id = s.time_id
        INNER JOIN COMPLEX_ORACLE.CHANNELS ch
          ON ch.channel_id = s.channel_id
       WHERE t.calendar_year = p_calendar_year
       GROUP BY s.channel_id, ch.channel_desc
       ORDER BY SUM(s.amount_sold) DESC
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      EXIT WHEN lv_rows_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(NVL(rec.channel_desc, 'UNKNOWN'), 30) || ' | ' ||
        LPAD(TO_CHAR(rec.total_amount, 'FM999G999G999G990D00'), 15) || ' | ' ||
        RPAD(get_channel_perf_label(rec.channel_id, p_calendar_year), 6)
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Debug bug detected: invalid number-to-text conversion.');
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No channels found for year ' || p_calendar_year || '.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_channels;
END channel_kpi_pkg;
/

