question:
Your analytics team wants a quick CPI-U sanity report before building dashboards. Pull the top 15 CPI-U observations for a given area and item name filter (both optional). For each row, print the year, period, area_name, item_name, and the numeric CPI value. If either filter is NULL, treat it as no filter. Order the output by most recent date first.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('CPI-U report (most recent first), max rows=' || co_report_limit);
DBMS_OUTPUT.PUT_LINE('Filters: area contains="' || NVL(lv_area_filter, 'NULL') || '", item contains="' || NVL(lv_item_filter, 'NULL') || '"');
DBMS_OUTPUT.PUT_LINE(rp.year || ' ' || rp.period || ' | ' || rp.area_name || ' | ' || rp.item_name || ' | value=' || TO_CHAR(rp.cpi_value));
DBMS_OUTPUT.PUT_LINE('No rows matched the provided filters.');
Exception Handling: WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_area_filter BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_filter BLS.CPI_U.item_name%TYPE := 'All items';

  ln_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U report (most recent first), max rows=' || co_report_limit);
  DBMS_OUTPUT.PUT_LINE('Filters: area contains="' || NVL(lv_area_filter, 'NULL') || '", item contains="' || NVL(lv_item_filter, 'NULL') || '"');

  FOR rp IN (
    SELECT
      c.year,
      c.period,
      c.area_name,
      c.item_name,
      TO_NUMBER(c.value) AS cpi_value,
      c.c_date
    FROM BLS.CPI_U c
    WHERE (lv_area_filter IS NULL OR c.area_name LIKE '%' || lv_area_filter || '%')
      AND (lv_item_filter IS NULL OR c.item_name LIKE '%' || lv_item_filter || '%')
    ORDER BY c.c_date DESC
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    ln_rows_printed := ln_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(rp.year || ' ' || rp.period || ' | ' || rp.area_name || ' | ' || rp.item_name || ' | value=' || TO_CHAR(rp.cpi_value));
  END LOOP;

  IF ln_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the provided filters.');
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

