question:
Now that the CPI-U report is working, the next step is to compute a year-over-year (YoY) change for a single area+item and show the most recent 15 monthly points. Use the same filtering concept as before, but this time require exact matches for area_name and item_name. For each row, print the date, CPI value, prior-year CPI value, and the YoY percent change. If a prior-year value doesn’t exist for a row, print YoY as NULL.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('YoY CPI-U for area="' || lv_area_name || '", item="' || lv_item_name || '", max rows=' || co_report_limit);
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rp.c_date, 'YYYY-MM-DD') || ' | value=' || TO_CHAR(rp.cpi_value) || ' | prior_year=' || NVL(TO_CHAR(rp.prior_year_value), 'NULL') || ' | yoy_pct=' || NVL(TO_CHAR(rp.yoy_pct), 'NULL'));
DBMS_OUTPUT.PUT_LINE('No data found for the provided area/item.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.';
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_area_name BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name BLS.CPI_U.item_name%TYPE := 'All items';

  ln_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('YoY CPI-U for area="' || lv_area_name || '", item="' || lv_item_name || '", max rows=' || co_report_limit);

  FOR rp IN (
    WITH base AS (
      SELECT
        c.c_date,
        TO_NUMBER(c.value) AS cpi_value,
        LAG(TO_NUMBER(c.value), 12) OVER (ORDER BY c.c_date) AS prior_year_value
      FROM BLS.CPI_U c
      WHERE c.area_name = lv_area_name
        AND c.item_name = lv_item_name
    )
    SELECT
      b.c_date,
      b.cpi_value,
      b.prior_year_value,
      CASE
        WHEN b.prior_year_value IS NULL THEN NULL
        WHEN b.prior_year_value = 0 THEN NULL
        ELSE ROUND((b.cpi_value - b.prior_year_value) / b.prior_year_value * 100, 4)
      END AS yoy_pct
    FROM base b
    ORDER BY b.c_date DESC
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    ln_rows_printed := ln_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rp.c_date, 'YYYY-MM-DD') ||
      ' | value=' || TO_CHAR(rp.cpi_value) ||
      ' | prior_year=' || NVL(TO_CHAR(rp.prior_year_value), 'NULL') ||
      ' | yoy_pct=' || NVL(TO_CHAR(rp.yoy_pct), 'NULL')
    );
  END LOOP;

  IF ln_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the provided area/item.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

