question:
Finally, build a data-quality check using the same area/item pair from the YoY output. The objective is to flag clearly invalid CPI values in the latest N rows (N=15): any value that cannot be converted to a number or any value that is negative. For each flagged row, print the date, the raw value string, and the reason.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('CPI-U data quality check for area="' || lv_area_name || '", item="' || lv_item_name || '", rows checked=' || co_check_limit);
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rp.c_date, 'YYYY-MM-DD') || ' | raw_value=' || rp.raw_value || ' | issue=INVALID_NUMBER');
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rp.c_date, 'YYYY-MM-DD') || ' | raw_value=' || rp.raw_value || ' | issue=NEGATIVE_VALUE');
DBMS_OUTPUT.PUT_LINE('No data quality issues found in the checked rows.');
DBMS_OUTPUT.PUT_LINE('No data found for the provided area/item.');
Exception Handling: WHEN VALUE_ERROR THEN: 'Value conversion error.';
WHEN NO_DATA_FOUND THEN: 'No data found.';
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  co_check_limit CONSTANT PLS_INTEGER := 15; -- Limit output for check readability

  lv_area_name BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name BLS.CPI_U.item_name%TYPE := 'All items';

  ln_rows_seen     PLS_INTEGER := 0;
  ln_issues_found  PLS_INTEGER := 0;

  -- Safe conversion: return NULL if not numeric
  FUNCTION safe_to_number(p_value IN BLS.CPI_U.value%TYPE) RETURN NUMBER IS
    ln_num NUMBER;
  BEGIN
    ln_num := TO_NUMBER(p_value);
    RETURN ln_num;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END safe_to_number;

BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U data quality check for area="' || lv_area_name || '", item="' || lv_item_name || '", rows checked=' || co_check_limit);

  FOR rp IN (
    SELECT
      c.c_date,
      c.value AS raw_value
    FROM BLS.CPI_U c
    WHERE c.area_name = lv_area_name
      AND c.item_name = lv_item_name
    ORDER BY c.c_date DESC
    FETCH FIRST co_check_limit ROWS ONLY
  ) LOOP
    ln_rows_seen := ln_rows_seen + 1;

    DECLARE
      ln_val NUMBER;
    BEGIN
      ln_val := safe_to_number(rp.raw_value);

      IF ln_val IS NULL THEN
        ln_issues_found := ln_issues_found + 1;
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(rp.c_date, 'YYYY-MM-DD') || ' | raw_value=' || rp.raw_value || ' | issue=INVALID_NUMBER');
      ELSIF ln_val < 0 THEN
        ln_issues_found := ln_issues_found + 1;
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(rp.c_date, 'YYYY-MM-DD') || ' | raw_value=' || rp.raw_value || ' | issue=NEGATIVE_VALUE');
      END IF;
    END;
  END LOOP;

  IF ln_rows_seen = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the provided area/item.');
  ELSIF ln_issues_found = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data quality issues found in the checked rows.');
  END IF;

EXCEPTION
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Value conversion error.');
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

