CREATE OR REPLACE PROCEDURE cpi_check_data_quality(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_checked PLS_INTEGER := 0;
  lv_value_num    NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI data quality check for Area=' || NVL(p_area_name, '') || ', Item=' || NVL(p_item_name, ''));

  FOR r IN (
    SELECT c.c_date,
           c.year,
           c.period,
           c.value
      FROM BLS.CPI_U c
     WHERE (p_area_name IS NULL OR c.area_name = p_area_name)
       AND (p_item_name IS NULL OR c.item_name = p_item_name)
     ORDER BY c.c_date DESC
  ) LOOP
    EXIT WHEN lv_rows_checked >= co_report_limit;

    BEGIN
