question:
For reporting, the team wants a quick way to list the top CPI items in an area for a given year, based on the latest month available in that year. Create a procedure that ranks items using ROW_NUMBER and prints up to 15 ranked items (item name + value + month). Handle cases where the year has no rows.

Requirements:
Procedure Name: cpi_top_items_by_year
Parameters:
p_area_name IN BLS.CPI_U.area_name%TYPE
p_year IN BLS.CPI_U.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Top CPI items for Area=' || NVL(p_area_name, '') || ', Year=' || NVL(p_year, ''));
DBMS_OUTPUT.PUT_LINE('No CPI rows found for the requested filters.');
DBMS_OUTPUT.PUT_LINE('Rank=' || r.rn || ' | Item=' || r.item_name || ' | Period=' || r.period || ' | Value=' || r.value);
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
CREATE OR REPLACE PROCEDURE cpi_top_items_by_year(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top CPI items for Area=' || NVL(p_area_name, '') || ', Year=' || NVL(p_year, ''));

  FOR r IN (
    WITH latest_per_item AS (
      SELECT c.item_name,
             c.period,
             c.value,
             c.c_date,
             ROW_NUMBER() OVER (
               PARTITION BY c.item_name
               ORDER BY c.c_date DESC
             ) AS rn_latest
        FROM BLS.CPI_U c
       WHERE c.area_name = p_area_name
         AND c.year = p_year
    ),
    ranked AS (
      SELECT l.item_name,
             l.period,
             l.value,
             ROW_NUMBER() OVER (
               ORDER BY TO_NUMBER(l.value) DESC, l.item_name
             ) AS rn
        FROM latest_per_item l
       WHERE l.rn_latest = 1
    )
    SELECT r2.rn,
           r2.item_name,
           r2.period,
           r2.value
      FROM ranked r2
     ORDER BY r2.rn
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE('Rank=' || r.rn || ' | Item=' || r.item_name || ' | Period=' || r.period || ' | Value=' || r.value);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No CPI rows found for the requested filters.');
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_top_items_by_year;
/

