CREATE OR REPLACE PACKAGE BODY cpi_pkg IS

  FUNCTION value_diff(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE,
    p_period    IN BLS.CPI_U.period%TYPE,
