    p_year2     IN BLS.CPI_U.year%TYPE
  ) RETURN NUMBER IS
    lv_val1_num NUMBER;
    lv_val2_num NUMBER;
  BEGIN
    SELECT TO_NUMBER(c.value)
      INTO lv_val1_num
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.period = p_period
       AND c.year = p_year1;

    SELECT TO_NUMBER(c.value)
      INTO lv_val2_num
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.period = p_period
       AND c.year = p_year2;

    DBMS_OUTPUT.PUT_LINE('CPI difference calculated for the requested filters.');
    RETURN lv_val2_num - lv_val1_num;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END value_diff;

  PROCEDURE run_report(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('CPI report for Area=' || NVL(p_area_name, '') || ', Item=' || NVL(p_item_name, ''));

    FOR r IN (
      SELECT c.c_date,
             c.year,
             c.period,
             c.value
        FROM BLS.CPI_U c
       WHERE (p_area_name IS NULL OR c.area_name = p_area_name)
         AND (p_item_name IS NULL OR c.item_name = p_item_name)
       ORDER BY c.c_date DESC
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;

      DBMS_OUTPUT.PUT_LINE(TO_CHAR(r.c_date, 'YYYY-MM-DD') || ' | ' || r.year || ' ' || r.period || ' | value=' || r.value);
      lv_rows_printed := lv_rows_printed + 1;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No CPI rows found for the requested filters.');
    END IF;

  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_report;

  PROCEDURE print_diff(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE,
    p_period    IN BLS.CPI_U.period%TYPE,
    p_year1     IN BLS.CPI_U.year%TYPE,
    p_year2     IN BLS.CPI_U.year%TYPE
  ) IS
    lv_diff NUMBER;
  BEGIN
    lv_diff := value_diff(
      p_area_name => p_area_name,
      p_item_name => p_item_name,
      p_period    => p_period,
      p_year1     => p_year1,
      p_year2     => p_year2
    );

    DBMS_OUTPUT.PUT_LINE('CPI diff (year2 - year1) = ' || NVL(TO_CHAR(lv_diff), ''));

  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_diff;

END cpi_pkg;
/

question:
We need a quick operations snapshot for bikeshare in a given landmark. Build an anonymous PL/SQL block that takes a landmark name, finds up to 15 stations in that landmark, and for each station prints the most recent reported availability (bikes and docks). If a station has no status rows yet, still print the station with bikes/docks shown as N/A. Keep the output readable and stable for a help-desk runbook.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Landmark: ' || lv_landmark);
Output: DBMS_OUTPUT.PUT_LINE(RPAD('STATION', 35) || RPAD('ID', 10) || RPAD('LAST_STATUS_TS', 22) || RPAD('BIKES', 8) || 'DOCKS');
Output: DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || RPAD('-', 10, '-') || RPAD('-', 22, '-') || RPAD('-', 8, '-') || RPAD('-', 5, '-'));
Output: DBMS_OUTPUT.PUT_LINE(RPAD(st.name, 35) || RPAD(st.station_id, 10) || RPAD(lv_last_ts_txt, 22) || RPAD(lv_bikes_txt, 8) || lv_docks_txt);
Output: DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No stations found for landmark.'
Exception Handling: WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
Exception Handling: WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := 'San Francisco';

  CURSOR c_stations(p_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE) IS
    SELECT s.station_id,
           s.name
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.landmark = p_landmark
     ORDER BY s.name;

  lv_last_ts      SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
  lv_bikes_avail  SAN_FRANCISCO.BIKESHARE_STATUS.bikes_available%TYPE;
  lv_docks_avail  SAN_FRANCISCO.BIKESHARE_STATUS.docks_available%TYPE;

  lv_last_ts_txt  VARCHAR2(30);
  lv_bikes_txt    VARCHAR2(10);
  lv_docks_txt    VARCHAR2(10);

  ln_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Landmark: ' || lv_landmark);
  DBMS_OUTPUT.PUT_LINE(RPAD('STATION', 35) || RPAD('ID', 10) || RPAD('LAST_STATUS_TS', 22) || RPAD('BIKES', 8) || 'DOCKS');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || RPAD('-', 10, '-') || RPAD('-', 22, '-') || RPAD('-', 8, '-') || RPAD('-', 5, '-'));

  FOR st IN c_stations(lv_landmark) LOOP
    EXIT WHEN ln_printed >= co_report_limit;

    BEGIN
      SELECT bs.time, bs.bikes_available, bs.docks_available
        INTO lv_last_ts, lv_bikes_avail, lv_docks_avail
        FROM (
              SELECT s2.time, s2.bikes_available, s2.docks_available
                FROM SAN_FRANCISCO.BIKESHARE_STATUS s2
               WHERE s2.station_id = st.station_id
               ORDER BY s2.time DESC
             ) bs
       WHERE ROWNUM = 1;

      lv_last_ts_txt := TO_CHAR(lv_last_ts, 'YYYY-MM-DD HH24:MI');
      lv_bikes_txt   := lv_bikes_avail;
      lv_docks_txt   := lv_docks_avail;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_last_ts_txt := 'N/A';
        lv_bikes_txt   := 'N/A';
        lv_docks_txt   := 'N/A';
      WHEN TOO_MANY_ROWS THEN
        lv_last_ts_txt := 'N/A';
        lv_bikes_txt   := 'N/A';
        lv_docks_txt   := 'N/A';
      WHEN OTHERS THEN
        lv_last_ts_txt := 'N/A';
        lv_bikes_txt   := 'N/A';
        lv_docks_txt   := 'N/A';
    END;

    DBMS_OUTPUT.PUT_LINE(RPAD(st.name, 35) || RPAD(st.station_id, 10) || RPAD(lv_last_ts_txt, 22) || RPAD(lv_bikes_txt, 8) || lv_docks_txt);
    ln_printed := ln_printed + 1;
  END LOOP;

  IF ln_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

