question:
Now extend the snapshot logic to focus on a single station. Write an anonymous PL/SQL block that takes a station_id and computes the utilization ratio for its most recent status row: bikes_available / (bikes_available + docks_available). Print the station name, timestamp, bikes, docks, and the ratio rounded to 3 decimals. Handle bad data where the availability columns are non-numeric, and handle the edge case where total docks+bikes is zero.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (ID=' || lv_station_id || ')');
Output: DBMS_OUTPUT.PUT_LINE('Last status: ' || TO_CHAR(lv_status_ts, 'YYYY-MM-DD HH24:MI'));
Output: DBMS_OUTPUT.PUT_LINE('Bikes: ' || lv_bikes_num || ', Docks: ' || lv_docks_num);
Output: DBMS_OUTPUT.PUT_LINE('Utilization ratio: ' || TO_CHAR(lv_ratio, '0.000'));
Output: DBMS_OUTPUT.PUT_LINE('No status found for station.');
Output: DBMS_OUTPUT.PUT_LINE('Bad numeric data in availability columns.');
Output: DBMS_OUTPUT.PUT_LINE('Total capacity is zero; ratio cannot be computed.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No status found for station.'
Exception Handling: WHEN INVALID_NUMBER THEN: 'Bad numeric data in availability columns.'
Exception Handling: WHEN ZERO_DIVIDE THEN: 'Total capacity is zero; ratio cannot be computed.'
Exception Handling: WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
Exception Handling: WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_station_id   SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE := '1';

  CURSOR c_station(p_station_id SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE) IS
    SELECT s.station_id,
           s.name
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.station_id = p_station_id;

  lv_station_name SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE;

  lv_status_ts    SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
  lv_bikes_txt    SAN_FRANCISCO.BIKESHARE_STATUS.bikes_available%TYPE;
  lv_docks_txt    SAN_FRANCISCO.BIKESHARE_STATUS.docks_available%TYPE;

  lv_bikes_num NUMBER;
  lv_docks_num NUMBER;
  lv_ratio     NUMBER;

  lb_found_station BOOLEAN := FALSE;
BEGIN
  FOR st IN c_station(lv_station_id) LOOP
    lb_found_station := TRUE;
    lv_station_name := st.name;
  END LOOP;

  IF NOT lb_found_station THEN
    DBMS_OUTPUT.PUT_LINE('No status found for station.');
    RAISE NO_DATA_FOUND;
  END IF;

  SELECT x.time, x.bikes_available, x.docks_available
    INTO lv_status_ts, lv_bikes_txt, lv_docks_txt
    FROM (
          SELECT bs.time, bs.bikes_available, bs.docks_available
            FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
           WHERE bs.station_id = lv_station_id
           ORDER BY bs.time DESC
         ) x
   WHERE ROWNUM = 1;

  lv_bikes_num := TO_NUMBER(lv_bikes_txt);
  lv_docks_num := TO_NUMBER(lv_docks_txt);

  lv_ratio := lv_bikes_num / (lv_bikes_num + lv_docks_num);

  DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (ID=' || lv_station_id || ')');
  DBMS_OUTPUT.PUT_LINE('Last status: ' || TO_CHAR(lv_status_ts, 'YYYY-MM-DD HH24:MI'));
  DBMS_OUTPUT.PUT_LINE('Bikes: ' || lv_bikes_num || ', Docks: ' || lv_docks_num);
  DBMS_OUTPUT.PUT_LINE('Utilization ratio: ' || TO_CHAR(lv_ratio, '0.000'));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No status found for station.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data in availability columns.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Total capacity is zero; ratio cannot be computed.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

