question:
Finally, turn this into a patrol-style report: for a given landmark and a minimum trip duration threshold, find up to 15 stations in that landmark and print each station along with the count of trips that started there and have duration_sec >= the threshold. Use a cursor to iterate stations and apply defensive checks so non-numeric duration values don't crash the report. If the threshold input is NULL, treat it as 0. 

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Landmark: ' || lv_landmark || ', Min duration (sec): ' || lv_min_duration);
Output: DBMS_OUTPUT.PUT_LINE(RPAD('STATION', 35) || RPAD('ID', 10) || 'LONG_TRIP_COUNT');
Output: DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || RPAD('-', 10, '-') || RPAD('-', 14, '-'));
Output: DBMS_OUTPUT.PUT_LINE(RPAD(st.name, 35) || RPAD(st.station_id, 10) || TO_CHAR(lv_trip_cnt));
Output: DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
Output: DBMS_OUTPUT.PUT_LINE('Bad numeric data in duration_sec.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No stations found for landmark.'
Exception Handling: WHEN INVALID_NUMBER THEN: 'Bad numeric data in duration_sec.'
Exception Handling: WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
Exception Handling: WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_landmark     SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := 'San Francisco';
  lv_min_duration NUMBER := NULL;

  CURSOR c_stations(p_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE) IS
    SELECT s.station_id,
           s.name
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.landmark = p_landmark
     ORDER BY s.name;

  lv_trip_cnt NUMBER;
  ln_printed  PLS_INTEGER := 0;
BEGIN
  lv_min_duration := NVL(lv_min_duration, 0);

  DBMS_OUTPUT.PUT_LINE('Landmark: ' || lv_landmark || ', Min duration (sec): ' || lv_min_duration);
  DBMS_OUTPUT.PUT_LINE(RPAD('STATION', 35) || RPAD('ID', 10) || 'LONG_TRIP_COUNT');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || RPAD('-', 10, '-') || RPAD('-', 14, '-'));

  FOR st IN c_stations(lv_landmark) LOOP
    EXIT WHEN ln_printed >= co_report_limit;

    BEGIN
      SELECT COUNT(*)
        INTO lv_trip_cnt
        FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
       WHERE t.start_station_id = st.station_id
         AND TO_NUMBER(t.duration_sec) >= lv_min_duration;
    EXCEPTION
      WHEN INVALID_NUMBER THEN
        DBMS_OUTPUT.PUT_LINE('Bad numeric data in duration_sec.');
        lv_trip_cnt := 0;
      WHEN NO_DATA_FOUND THEN
        lv_trip_cnt := 0;
      WHEN TOO_MANY_ROWS THEN
        lv_trip_cnt := 0;
      WHEN OTHERS THEN
        lv_trip_cnt := 0;
    END;

    DBMS_OUTPUT.PUT_LINE(RPAD(st.name, 35) || RPAD(st.station_id, 10) || TO_CHAR(lv_trip_cnt));
    ln_printed := ln_printed + 1;
  END LOOP;

  IF ln_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data in duration_sec.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

