reference_answer:
CREATE OR REPLACE PROCEDURE cpi_sanity_snapshot(
  p_area_name_like IN BLS.CPI_U.area_name%TYPE,
  p_item_name_like IN BLS.CPI_U.item_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_year_latest IS
    WITH ranked AS (
      SELECT
        c.year,
        c.period,
        c.c_date,
        c.value,
        ROW_NUMBER() OVER (
          PARTITION BY c.year
          ORDER BY c.c_date DESC
        ) AS rn
      FROM BLS.CPI_U c
      WHERE c.area_name LIKE '%' || p_area_name_like || '%'
        AND c.item_name LIKE '%' || p_item_name_like || '%'
    )
    SELECT
      r.year,
      r.period,
      r.c_date,
      r.value
    FROM ranked r
    WHERE r.rn = 1
    ORDER BY r.year DESC;

  lv_year   BLS.CPI_U.year%TYPE;
  lv_period BLS.CPI_U.period%TYPE;
  lv_c_date BLS.CPI_U.c_date%TYPE;
  lv_value  BLS.CPI_U.value%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  OPEN c_year_latest;

  LOOP
    FETCH c_year_latest INTO lv_year, lv_period, lv_c_date, lv_value;
    EXIT WHEN c_year_latest%NOTFOUND;

    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'YEAR=' || lv_year ||
      ' PERIOD=' || lv_period ||
      ' C_DATE=' || TO_CHAR(lv_c_date, 'YYYY-MM-DD') ||
      ' VALUE=' || lv_value
    );
  END LOOP;

  CLOSE c_year_latest;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_year_latest%ISOPEN THEN
      CLOSE c_year_latest;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    IF c_year_latest%ISOPEN THEN
      CLOSE c_year_latest;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_sanity_snapshot;
/

CREATE OR REPLACE PACKAGE cpi_compare_pkg IS
  PROCEDURE print_year_latest_diff(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE
  );
END cpi_compare_pkg;
/

CREATE OR REPLACE PACKAGE BODY cpi_compare_pkg IS

  PROCEDURE print_year_latest_diff(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_cmp IS
      WITH
      u_ranked AS (
        SELECT
          u.year,
          u.value AS val_u_txt,
          u.c_date AS c_date_u,
          ROW_NUMBER() OVER (PARTITION BY u.year ORDER BY u.c_date DESC) AS rn
        FROM BLS.CPI_U u
        WHERE u.area_name LIKE '%' || p_area_name_like || '%'
          AND u.item_name LIKE '%' || p_item_name_like || '%'
      ),
      c_ranked AS (
        SELECT
          c.year,
          c.value AS val_c_txt,
          c.c_date AS c_date_c,
          ROW_NUMBER() OVER (PARTITION BY c.year ORDER BY c.c_date DESC) AS rn
        FROM BLS.C_CPI_U c
        WHERE c.area_name LIKE '%' || p_area_name_like || '%'
          AND c.item_name LIKE '%' || p_item_name_like || '%'
      )
      SELECT
        u.year,
        u.val_u_txt,
        c.val_c_txt
      FROM u_ranked u
      INNER JOIN c_ranked c
        ON c.year = u.year
      WHERE u.rn = 1
        AND c.rn = 1
      ORDER BY u.year DESC;

    lv_year      BLS.CPI_U.year%TYPE;
    lv_val_u_txt BLS.CPI_U.value%TYPE;
    lv_val_c_txt BLS.C_CPI_U.value%TYPE;

    lv_num_u   NUMBER;
    lv_num_c   NUMBER;
    lv_abs_diff NUMBER;

    lv_rows_seen PLS_INTEGER := 0;
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    OPEN c_cmp;

    LOOP
      FETCH c_cmp INTO lv_year, lv_val_u_txt, lv_val_c_txt;
      EXIT WHEN c_cmp%NOTFOUND;

      lv_rows_seen := lv_rows_seen + 1;

      BEGIN
        lv_num_u := TO_NUMBER(lv_val_u_txt);
        lv_num_c := TO_NUMBER(lv_val_c_txt);
        lv_abs_diff := ABS(lv_num_u - lv_num_c);

        lv_rows_printed := lv_rows_printed + 1;
        EXIT WHEN lv_rows_printed > co_report_limit;

        DBMS_OUTPUT.PUT_LINE(
          'YEAR=' || lv_year ||
          ' CPI_U=' || lv_val_u_txt ||
          ' C_CPI_U=' || lv_val_c_txt ||
          ' ABS_DIFF=' || TO_CHAR(lv_abs_diff)
        );
      EXCEPTION
        WHEN VALUE_ERROR THEN
          DBMS_OUTPUT.PUT_LINE(
            'YEAR=' || lv_year || ' Warning: non-numeric value encountered; row skipped.'
          );
      END;
    END LOOP;

    CLOSE c_cmp;

    IF lv_rows_seen = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_cmp%ISOPEN THEN
        CLOSE c_cmp;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      IF c_cmp%ISOPEN THEN
        CLOSE c_cmp;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_year_latest_diff;

END cpi_compare_pkg;
/

CREATE OR REPLACE PACKAGE cpi_series_audit_pkg IS
