CREATE OR REPLACE PACKAGE BODY cpi_series_audit_pkg IS

  PROCEDURE print_top_series_for_latest_year(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_latest_year BLS.CPI_U.year%TYPE;

    CURSOR c_top_series(p_year IN BLS.CPI_U.year%TYPE) IS
      SELECT
        c.series_id,
        COUNT(*) AS row_count
      FROM BLS.CPI_U c
      WHERE c.year = p_year
        AND c.area_name LIKE '%' || p_area_name_like || '%'
        AND c.item_name LIKE '%' || p_item_name_like || '%'
      GROUP BY c.series_id
      ORDER BY COUNT(*) DESC, c.series_id;

    lv_series_id BLS.CPI_U.series_id%TYPE;
    lv_row_count NUMBER;

    lv_printed PLS_INTEGER := 0;
  BEGIN
    SELECT MAX(c.year)
      INTO lv_latest_year
      FROM BLS.CPI_U c
      WHERE c.area_name LIKE '%' || p_area_name_like || '%'
        AND c.item_name LIKE '%' || p_item_name_like || '%';

    IF lv_latest_year IS NULL THEN
      RAISE NO_DATA_FOUND;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Latest year=' || lv_latest_year);

    OPEN c_top_series(lv_latest_year);

    LOOP
      FETCH c_top_series INTO lv_series_id, lv_row_count;
      EXIT WHEN c_top_series%NOTFOUND;

      lv_printed := lv_printed + 1;
      EXIT WHEN lv_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        'SERIES_ID=' || lv_series_id || ' ROWS=' || TO_CHAR(lv_row_count)
      );
    END LOOP;

    CLOSE c_top_series;

    IF lv_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_top_series%ISOPEN THEN
        CLOSE c_top_series;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      IF c_top_series%ISOPEN THEN
        CLOSE c_top_series;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      IF c_top_series%ISOPEN THEN
        CLOSE c_top_series;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_series_for_latest_year;

END cpi_series_audit_pkg;
