CREATE OR REPLACE PACKAGE cpi_debug_pkg IS
  PROCEDURE print_year_latest_index_bug(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE
  );

  PROCEDURE print_year_latest_index_fixed(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE
  );
END cpi_debug_pkg;
/

CREATE OR REPLACE PACKAGE BODY cpi_debug_pkg IS

  CURSOR c_cmp(
    p_area IN BLS.CPI_U.area_name%TYPE,
    p_item IN BLS.CPI_U.item_name%TYPE
  ) IS
    WITH
    u_ranked AS (
      SELECT
        u.year,
        u.value AS val_u_txt,
        ROW_NUMBER() OVER (PARTITION BY u.year ORDER BY u.c_date DESC) AS rn
      FROM BLS.CPI_U u
      WHERE u.area_name LIKE '%' || p_area || '%'
        AND u.item_name LIKE '%' || p_item || '%'
    ),
    c_ranked AS (
      SELECT
        c.year,
        c.value AS val_c_txt,
        ROW_NUMBER() OVER (PARTITION BY c.year ORDER BY c.c_date DESC) AS rn
      FROM BLS.C_CPI_U c
      WHERE c.area_name LIKE '%' || p_area || '%'
        AND c.item_name LIKE '%' || p_item || '%'
    )
    SELECT
      u.year,
      u.val_u_txt,
      c.val_c_txt
    FROM u_ranked u
    INNER JOIN c_ranked c
      ON c.year = u.year
    WHERE u.rn = 1
      AND c.rn = 1
    ORDER BY u.year DESC;

  PROCEDURE print_year_latest_index_bug(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_year      BLS.CPI_U.year%TYPE;
    lv_val_u_txt BLS.CPI_U.value%TYPE;
    lv_val_c_txt BLS.C_CPI_U.value%TYPE;

    lv_u NUMBER;
    lv_c NUMBER;
    lv_idx NUMBER;

    lv_seen PLS_INTEGER := 0;
    lv_printed PLS_INTEGER := 0;
  BEGIN
    OPEN c_cmp(p_area_name_like, p_item_name_like);

    LOOP
      FETCH c_cmp INTO lv_year, lv_val_u_txt, lv_val_c_txt;
      EXIT WHEN c_cmp%NOTFOUND;

      lv_seen := lv_seen + 1;

      lv_u := TO_NUMBER(lv_val_u_txt);
      lv_c := TO_NUMBER(lv_val_c_txt);

      -- BUG: denominator can be zero when lv_u = lv_c.
      lv_idx := (lv_u - lv_c) / ABS(lv_u - lv_c);

      lv_printed := lv_printed + 1;
      EXIT WHEN lv_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE('YEAR=' || lv_year || ' INDEX=' || TO_CHAR(lv_idx));
    END LOOP;

    CLOSE c_cmp;

    IF lv_seen = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_cmp%ISOPEN THEN
        CLOSE c_cmp;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN ZERO_DIVIDE THEN
      IF c_cmp%ISOPEN THEN
        CLOSE c_cmp;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    WHEN OTHERS THEN
      IF c_cmp%ISOPEN THEN
        CLOSE c_cmp;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_year_latest_index_bug;

  PROCEDURE print_year_latest_index_fixed(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_year      BLS.CPI_U.year%TYPE;
    lv_val_u_txt BLS.CPI_U.value%TYPE;
    lv_val_c_txt BLS.C_CPI_U.value%TYPE;

    lv_u NUMBER;
    lv_c NUMBER;
    lv_denom NUMBER;
    lv_idx NUMBER;

    lv_seen PLS_INTEGER := 0;
    lv_printed PLS_INTEGER := 0;
  BEGIN
    OPEN c_cmp(p_area_name_like, p_item_name_like);

    LOOP
      FETCH c_cmp INTO lv_year, lv_val_u_txt, lv_val_c_txt;
      EXIT WHEN c_cmp%NOTFOUND;

      lv_seen := lv_seen + 1;

      BEGIN
        lv_u := TO_NUMBER(lv_val_u_txt);
        lv_c := TO_NUMBER(lv_val_c_txt);
        lv_denom := ABS(lv_u - lv_c);

        IF lv_denom = 0 THEN
          DBMS_OUTPUT.PUT_LINE('YEAR=' || lv_year || ' INDEX=0');
        ELSE
          lv_idx := (lv_u - lv_c) / lv_denom;
          DBMS_OUTPUT.PUT_LINE('YEAR=' || lv_year || ' INDEX=' || TO_CHAR(lv_idx));
        END IF;

        lv_printed := lv_printed + 1;
        EXIT WHEN lv_printed >= co_report_limit;

      EXCEPTION
        WHEN VALUE_ERROR THEN
          DBMS_OUTPUT.PUT_LINE('YEAR=' || lv_year || ' INDEX=0');
      END;
    END LOOP;

    CLOSE c_cmp;

    IF lv_seen = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_cmp%ISOPEN THEN
        CLOSE c_cmp;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      IF c_cmp%ISOPEN THEN
        CLOSE c_cmp;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_year_latest_index_fixed;

END cpi_debug_pkg;
/

CREATE OR REPLACE PROCEDURE report_season_match_runs(
  p_season_id IN IPL.MATCH.season_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_matches IS
    WITH
      b AS (
        SELECT bs.match_id,
               bs.innings_no,
               SUM(bs.runs_scored) batsman_runs
          FROM IPL.BATSMAN_SCORED bs
         GROUP BY bs.match_id, bs.innings_no
      ),
      e AS (
        SELECT er.match_id,
               er.innings_no,
               SUM(er.extra_runs) extra_runs
          FROM IPL.EXTRA_RUNS er
         GROUP BY er.match_id, er.innings_no
      ),
      totals AS (
        SELECT COALESCE(b.match_id, e.match_id) match_id,
               COALESCE(b.innings_no, e.innings_no) innings_no,
               NVL(b.batsman_runs, 0) + NVL(e.extra_runs, 0) total_runs
          FROM b
          FULL OUTER JOIN e
            ON e.match_id = b.match_id
           AND e.innings_no = b.innings_no
      )
    SELECT m.match_id,
           m.match_date,
           t1.name team1_name,
           t2.name team2_name,
           MAX(CASE WHEN totals.innings_no = 1 THEN totals.total_runs END) inn1_runs,
           MAX(CASE WHEN totals.innings_no = 2 THEN totals.total_runs END) inn2_runs
      FROM IPL.MATCH m
      INNER JOIN IPL.TEAM t1
        ON t1.team_id = m.team_1
      INNER JOIN IPL.TEAM t2
        ON t2.team_id = m.team_2
      LEFT OUTER JOIN totals
        ON totals.match_id = m.match_id
     WHERE m.season_id = p_season_id
     GROUP BY m.match_id, m.match_date, t1.name, t2.name
     ORDER BY m.match_date DESC, m.match_id DESC;

  lr c_matches%ROWTYPE;
  lv_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Match scoring snapshot for season_id=' || p_season_id);

  OPEN c_matches;
  LOOP
    FETCH c_matches INTO lr;
    EXIT WHEN c_matches%NOTFOUND;

    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Match ' || lr.match_id || ' on ' || TO_CHAR(lr.match_date, 'YYYY-MM-DD') ||
      ': ' || lr.team1_name || ' vs ' || lr.team2_name ||
      ' | Inn1=' || NVL(TO_CHAR(lr.inn1_runs), '0') ||
      ' Inn2=' || NVL(TO_CHAR(lr.inn2_runs), '0')
    );
  END LOOP;
  CLOSE c_matches;

  IF lv_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matches found for season_id=' || p_season_id);
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_matches%ISOPEN THEN
      CLOSE c_matches;
    END IF;
END report_season_match_runs;
/

CREATE OR REPLACE PROCEDURE report_team_season_results(
  p_season_id IN IPL.MATCH.season_id%TYPE,
  p_team_id   IN IPL.TEAM.team_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_team_matches IS
    SELECT m.match_id,
           m.match_date,
           m.venue,
           CASE
             WHEN m.outcome_type IS NOT NULL AND m.outcome_type <> 'result' THEN 'NO RESULT'
             WHEN m.match_winner = p_team_id THEN 'WIN'
             WHEN m.match_winner IS NULL THEN 'NO RESULT'
             ELSE 'LOSS'
           END result_label
      FROM IPL.MATCH m
     WHERE m.season_id = p_season_id
       AND (m.team_1 = p_team_id OR m.team_2 = p_team_id)
     ORDER BY m.match_date, m.match_id;

  lr c_team_matches%ROWTYPE;
  lv_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Team results for season_id=' || p_season_id || ' team_id=' || p_team_id);

  OPEN c_team_matches;
  LOOP
    FETCH c_team_matches INTO lr;
    EXIT WHEN c_team_matches%NOTFOUND;

    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Match ' || lr.match_id || ' on ' || TO_CHAR(lr.match_date, 'YYYY-MM-DD') ||
      ' at ' || lr.venue || ' => ' || lr.result_label
    );
  END LOOP;
  CLOSE c_team_matches;

  IF lv_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matches found for season/team.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_team_matches%ISOPEN THEN
      CLOSE c_team_matches;
    END IF;
END report_team_season_results;
/

CREATE OR REPLACE PROCEDURE find_winner_team_mismatches(
  p_season_id IN IPL.MATCH.season_id%TYPE,
  p_team_id   IN IPL.TEAM.team_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_mismatches IS
    SELECT m.match_id,
           m.match_date,
           m.team_1,
           m.team_2,
           m.match_winner
      FROM IPL.MATCH m
     WHERE m.season_id = p_season_id
       AND (m.team_1 = p_team_id OR m.team_2 = p_team_id)
       AND m.match_winner IS NOT NULL
       AND m.match_winner NOT IN (m.team_1, m.team_2)
     ORDER BY m.match_date, m.match_id;

  lr c_mismatches%ROWTYPE;
  lv_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE(
    'Data quality check (winner mismatch) for season_id=' || p_season_id || ' team_id=' || p_team_id
  );

  OPEN c_mismatches;
  LOOP
    FETCH c_mismatches INTO lr;
    EXIT WHEN c_mismatches%NOTFOUND;

    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Anomaly match_id=' || lr.match_id ||
      ' on ' || TO_CHAR(lr.match_date, 'YYYY-MM-DD') ||
      ' team_1=' || lr.team_1 ||
      ' team_2=' || lr.team_2 ||
      ' match_winner=' || lr.match_winner
    );
  END LOOP;
  CLOSE c_mismatches;

  IF lv_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No winner mismatches found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_mismatches%ISOPEN THEN
      CLOSE c_mismatches;
    END IF;
END find_winner_team_mismatches;
/

CREATE OR REPLACE PACKAGE ipl_team_scoring_pkg IS
  PROCEDURE get_top_batters(
    p_season_id IN IPL.MATCH.season_id%TYPE,
    p_team_id   IN IPL.TEAM.team_id%TYPE,
    p_top_n     IN NUMBER
  );

  PROCEDURE show_buggy_top_batters(
    p_season_id IN IPL.MATCH.season_id%TYPE,
    p_team_id   IN IPL.TEAM.team_id%TYPE
  );
END ipl_team_scoring_pkg;
/

CREATE OR REPLACE PACKAGE BODY ipl_team_scoring_pkg IS
  PROCEDURE get_top_batters(
    p_season_id IN IPL.MATCH.season_id%TYPE,
    p_team_id   IN IPL.TEAM.team_id%TYPE,
    p_top_n     IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Hard cap for readability

    lv_top_n PLS_INTEGER;

    CURSOR c_ranked IS
      WITH player_totals AS (
        SELECT bb.striker player_id,
               SUM(bs.runs_scored) total_runs
          FROM IPL.BALL_BY_BALL bb
          INNER JOIN IPL.BATSMAN_SCORED bs
            ON bs.match_id = bb.match_id
          INNER JOIN IPL.MATCH m
            ON m.match_id = bb.match_id
         WHERE m.season_id = p_season_id
           AND bb.team_batting = p_team_id
         GROUP BY bb.striker
      ),
      ranked AS (
        SELECT pt.player_id,
               pt.total_runs,
               RANK() OVER (ORDER BY pt.total_runs DESC, pt.player_id ASC) rnk
          FROM player_totals pt
      )
      SELECT r.rnk,
             p.player_name,
             r.total_runs
        FROM ranked r
        INNER JOIN IPL.PLAYER p
          ON p.player_id = r.player_id
       ORDER BY r.rnk, p.player_name;

    lr c_ranked%ROWTYPE;
    lv_printed PLS_INTEGER := 0;
  BEGIN
    IF p_top_n IS NULL OR p_top_n < 1 OR p_top_n > co_report_limit THEN
      RAISE VALUE_ERROR;
    END IF;

    lv_top_n := TRUNC(p_top_n);

    DBMS_OUTPUT.PUT_LINE(
      'Top batters for season_id=' || p_season_id || ' team_id=' || p_team_id || ' top_n=' || p_top_n
    );

    OPEN c_ranked;
    LOOP
      FETCH c_ranked INTO lr;
      EXIT WHEN c_ranked%NOTFOUND;

      IF lr.rnk <= lv_top_n THEN
        lv_printed := lv_printed + 1;
        EXIT WHEN lv_printed > co_report_limit;

        DBMS_OUTPUT.PUT_LINE(
          'Rank ' || lr.rnk || ': ' || lr.player_name || ' runs=' || lr.total_runs
        );
      END IF;
    END LOOP;
    CLOSE c_ranked;

    IF lv_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No batting data found for season/team.');
      IF c_ranked%ISOPEN THEN
        CLOSE c_ranked;
      END IF;
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid top_n; must be between 1 and 15.');
      IF c_ranked%ISOPEN THEN
        CLOSE c_ranked;
      END IF;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      IF c_ranked%ISOPEN THEN
        CLOSE c_ranked;
      END IF;
  END get_top_batters;


  PROCEDURE show_buggy_top_batters(
    p_season_id IN IPL.MATCH.season_id%TYPE,
    p_team_id   IN IPL.TEAM.team_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_buggy IS
      SELECT p.player_name,
             bs.runs_scored
        FROM IPL.BALL_BY_BALL bb
        INNER JOIN IPL.BATSMAN_SCORED bs
          ON bs.match_id = bb.match_id
        INNER JOIN IPL.MATCH m
          ON m.match_id = bb.match_id
        INNER JOIN IPL.PLAYER p
          ON p.player_id = bb.striker
       WHERE m.season_id = p_season_id
         AND bb.team_batting = p_team_id
       ORDER BY bs.runs_scored DESC, p.player_name;

    lr c_buggy%ROWTYPE;
    lv_printed PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'BUGGY top-batters sample for season_id=' || p_season_id || ' team_id=' || p_team_id
    );

    OPEN c_buggy;
    LOOP
      FETCH c_buggy INTO lr;
      EXIT WHEN c_buggy%NOTFOUND;

      lv_printed := lv_printed + 1;
      EXIT WHEN lv_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        'Buggy row: ' || lr.player_name || ' runs_scored=' || lr.runs_scored
      );
    END LOOP;
    CLOSE c_buggy;

    DBMS_OUTPUT.PUT_LINE(
      'Root cause: ordering individual ball rows without aggregating to player totals creates duplicates and unstable ranking.'
    );

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No batting data found for season/team.');
      IF c_buggy%ISOPEN THEN
        CLOSE c_buggy;
      END IF;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      IF c_buggy%ISOPEN THEN
        CLOSE c_buggy;
      END IF;
  END show_buggy_top_batters;

END ipl_team_scoring_pkg;
/

