question:
Now that we have the season power-hitter report, turn it into a reusable routine for the app. Create a stored procedure that takes a season and a minimum home run threshold, then prints up to 15 qualifying players with their total HR, AB, and H. Use the same defaulting behavior for a NULL season (most recent year). Also categorize each qualifying player as 'ELITE' when HR >= 40, 'SOLID' when HR is between the threshold and 39, otherwise 'NONE'.

Requirements:
Procedure Name: report_power_hitters
Parameters:
p_year IN BASEBALL.BATTING.year%TYPE
p_min_hr IN NUMBER
Output:
DBMS_OUTPUT.PUT_LINE('Season: ' || lv_year || ' (min HR: ' || p_min_hr || ')');
DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Player', 25) || LPAD('HR', 6) || LPAD('AB', 8) || LPAD('H', 8) || RPAD(' Tier', 10));
DBMS_OUTPUT.PUT_LINE(RPAD(TO_CHAR(lv_rank), 6) || RPAD(rec.player_name, 25) || LPAD(TO_CHAR(rec.hr), 6) || LPAD(TO_CHAR(rec.ab), 8) || LPAD(TO_CHAR(rec.h), 8) || RPAD(' ' || lv_tier, 10));
DBMS_OUTPUT.PUT_LINE('No qualifying hitters found for the selected season.');
DBMS_OUTPUT.PUT_LINE('Minimum HR must be >= 0.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No qualifying hitters found for the selected season.'
WHEN VALUE_ERROR THEN: 'Minimum HR must be >= 0.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_power_hitters(
  p_year   IN BASEBALL.BATTING.year%TYPE,
  p_min_hr IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year     BASEBALL.BATTING.year%TYPE;
  lv_rank     PLS_INTEGER := 0;
  lv_rowcount PLS_INTEGER := 0;
  lv_tier     VARCHAR2(10);
BEGIN
  IF p_min_hr < 0 THEN
    RAISE VALUE_ERROR;
  END IF;

  -- Resolve year: if NULL, default to the most recent season in batting
  IF p_year IS NULL THEN
    SELECT MAX(b.year)
      INTO lv_year
      FROM BASEBALL.BATTING b;
  ELSE
    lv_year := p_year;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Season: ' || lv_year || ' (min HR: ' || p_min_hr || ')');
  DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Player', 25) || LPAD('HR', 6) || LPAD('AB', 8) || LPAD('H', 8) || RPAD(' Tier', 10));

  FOR rec IN (
    SELECT player_name,
           hr,
           ab,
           h
      FROM (
        SELECT (p.name_first || ' ' || p.name_last) AS player_name,
               SUM(b.hr) AS hr,
               SUM(b.ab) AS ab,
               SUM(b.h)  AS h
          FROM BASEBALL.BATTING b
          INNER JOIN BASEBALL.PLAYER p
            ON p.player_id = b.player_id
         WHERE b.year = lv_year
         GROUP BY (p.name_first || ' ' || p.name_last)
        HAVING SUM(b.hr) >= p_min_hr
         ORDER BY SUM(b.hr) DESC, SUM(b.ab) DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rowcount := lv_rowcount + 1;
    lv_rank := lv_rank + 1;

    IF rec.hr >= 40 THEN
      lv_tier := 'ELITE';
    ELSIF rec.hr >= p_min_hr THEN
      lv_tier := 'SOLID';
    ELSE
      lv_tier := 'NONE';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(lv_rank), 6) ||
      RPAD(rec.player_name, 25) ||
      LPAD(TO_CHAR(rec.hr), 6) ||
      LPAD(TO_CHAR(rec.ab), 8) ||
      LPAD(TO_CHAR(rec.h), 8) ||
      RPAD(' ' || lv_tier, 10)
    );
  END LOOP;

  IF lv_rowcount = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No qualifying hitters found for the selected season.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Minimum HR must be >= 0.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_power_hitters;
/

CREATE OR REPLACE FUNCTION get_player_hr_by_year(
  p_player_id IN BASEBALL.BATTING.player_id%TYPE,
  p_year      IN BASEBALL.BATTING.year%TYPE
) RETURN NUMBER IS
  lv_total_hr NUMBER;
BEGIN
  SELECT SUM(b.hr)
    INTO lv_total_hr
    FROM BASEBALL.BATTING b
   WHERE b.player_id = p_player_id
     AND b.year = p_year;

  IF lv_total_hr IS NULL THEN
    RAISE NO_DATA_FOUND;
  END IF;

  RETURN lv_total_hr;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No batting data found for that player/year.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END get_player_hr_by_year;
/

DECLARE
  lv_player_id   BASEBALL.BATTING.player_id%TYPE;
  lv_year        BASEBALL.BATTING.year%TYPE;
  lv_total_hr    NUMBER;
  lv_player_name VARCHAR2(200);
BEGIN
  -- Pick a deterministic sample player/year from existing data
  SELECT b.player_id,
         b.year
    INTO lv_player_id,
         lv_year
    FROM BASEBALL.BATTING b
   WHERE b.hr IS NOT NULL
   ORDER BY b.year DESC
   FETCH FIRST 1 ROWS ONLY;

  SELECT (p.name_first || ' ' || p.name_last)
    INTO lv_player_name
    FROM BASEBALL.PLAYER p
   WHERE p.player_id = lv_player_id;

  lv_total_hr := get_player_hr_by_year(lv_player_id, lv_year);

  DBMS_OUTPUT.PUT_LINE('Player: ' || lv_player_name || ' | Season: ' || lv_year || ' | Total HR: ' || lv_total_hr);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No batting data found for that player/year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

