question:
For a complete scouting workflow, build a package that combines the season power-hitter report with data-quality checks. The package should expose one procedure that prints a ranked top-15 list using a proper tie-breaker (total HR desc, then AB desc) and uses an analytic rank so the rank values match the ordering. It should also expose another procedure that scans the top-15 results and flags potential data issues, such as players that have HR but zero AB in that season, and print those findings. Ensure all exceptions are handled and reported.

Requirements:
Procedure Name: pkg_scouting
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Season: ' || lv_year || ' | Top ' || co_report_limit || ' by HR');
DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Player', 25) || LPAD('HR', 6) || LPAD('AB', 8) || LPAD('H', 8));
DBMS_OUTPUT.PUT_LINE(RPAD(TO_CHAR(rec.rnk), 6) || RPAD(rec.player_name, 25) || LPAD(TO_CHAR(rec.hr), 6) || LPAD(TO_CHAR(rec.ab), 8) || LPAD(TO_CHAR(rec.h), 8));
DBMS_OUTPUT.PUT_LINE('Season: ' || lv_year || ' | Data quality checks for top hitters');
DBMS_OUTPUT.PUT_LINE('Issue: HR recorded with zero AB | Player: ' || rec.player_name || ' | HR: ' || rec.hr || ' | AB: ' || rec.ab);
DBMS_OUTPUT.PUT_LINE('No issues detected in the top list.');
DBMS_OUTPUT.PUT_LINE('No batting data found for the selected season.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No batting data found for the selected season.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE pkg_scouting IS
  PROCEDURE print_top_hr;
  PROCEDURE check_top_hr_data_quality;
END pkg_scouting;
/

CREATE OR REPLACE PACKAGE BODY pkg_scouting IS

  PROCEDURE print_top_hr IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_year         BASEBALL.BATTING.year%TYPE;
    lv_rowcount     PLS_INTEGER := 0;
  BEGIN
    SELECT MAX(b.year)
      INTO lv_year
      FROM BASEBALL.BATTING b;

    DBMS_OUTPUT.PUT_LINE('Season: ' || lv_year || ' | Top ' || co_report_limit || ' by HR');
    DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Player', 25) || LPAD('HR', 6) || LPAD('AB', 8) || LPAD('H', 8));

    FOR rec IN (
      WITH totals AS (
        SELECT (p.name_first || ' ' || p.name_last) AS player_name,
               SUM(b.hr) AS hr,
               SUM(b.ab) AS ab,
               SUM(b.h)  AS h
          FROM BASEBALL.BATTING b
          INNER JOIN BASEBALL.PLAYER p
            ON p.player_id = b.player_id
         WHERE b.year = lv_year
         GROUP BY (p.name_first || ' ' || p.name_last)
      ), ranked AS (
        SELECT t.player_name,
               t.hr,
               t.ab,
               t.h,
               RANK() OVER (ORDER BY t.hr DESC, t.ab DESC) AS rnk
          FROM totals t
      )
      SELECT r.player_name,
             r.hr,
             r.ab,
             r.h,
             r.rnk
        FROM ranked r
       WHERE r.rnk <= co_report_limit
       ORDER BY r.rnk, r.player_name
    ) LOOP
      lv_rowcount := lv_rowcount + 1;
      DBMS_OUTPUT.PUT_LINE(
        RPAD(TO_CHAR(rec.rnk), 6) ||
        RPAD(rec.player_name, 25) ||
        LPAD(TO_CHAR(rec.hr), 6) ||
        LPAD(TO_CHAR(rec.ab), 8) ||
        LPAD(TO_CHAR(rec.h), 8)
      );
    END LOOP;

    IF lv_rowcount = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No batting data found for the selected season.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_hr;


  PROCEDURE check_top_hr_data_quality IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_year         BASEBALL.BATTING.year%TYPE;
    lv_issue_count  PLS_INTEGER := 0;
  BEGIN
    SELECT MAX(b.year)
      INTO lv_year
      FROM BASEBALL.BATTING b;

    DBMS_OUTPUT.PUT_LINE('Season: ' || lv_year || ' | Data quality checks for top hitters');

    FOR rec IN (
      WITH totals AS (
        SELECT (p.name_first || ' ' || p.name_last) AS player_name,
               SUM(b.hr) AS hr,
               SUM(b.ab) AS ab
          FROM BASEBALL.BATTING b
          INNER JOIN BASEBALL.PLAYER p
            ON p.player_id = b.player_id
         WHERE b.year = lv_year
         GROUP BY (p.name_first || ' ' || p.name_last)
      ), ranked AS (
        SELECT t.player_name,
               t.hr,
               t.ab,
               RANK() OVER (ORDER BY t.hr DESC, t.ab DESC) AS rnk
          FROM totals t
      )
      SELECT r.player_name,
             r.hr,
             r.ab
        FROM ranked r
       WHERE r.rnk <= co_report_limit
         AND r.hr > 0
         AND r.ab = 0
       ORDER BY r.hr DESC, r.player_name
    ) LOOP
      lv_issue_count := lv_issue_count + 1;
      DBMS_OUTPUT.PUT_LINE('Issue: HR recorded with zero AB | Player: ' || rec.player_name || ' | HR: ' || rec.hr || ' | AB: ' || rec.ab);
    END LOOP;

    IF lv_issue_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No issues detected in the top list.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No batting data found for the selected season.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END check_top_hr_data_quality;

END pkg_scouting;
/

