question:
Build an anonymous reporting script for a care coordinator. Given an organization id, print up to 15 providers from that organization, sorted by highest utilization first. For each provider, output the provider id, provider name, speciality, gender, and utilization. If the organization id has no providers, print a clear message instead of failing.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Provider list for organization_id=' || lv_org_id);
DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || lv_org_id);
DBMS_OUTPUT.PUT_LINE(rp.provider_id || ' | ' || rp.provider_name || ' | ' || rp.speciality || ' | ' || rp.gender || ' | utilization=' || rp.utilization);
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No providers found for organization_id=' || lv_org_id.
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  lv_org_id   SYNTHEA.PROVIDERS.organization%TYPE := '1';
  lv_any_rows NUMBER := 0;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  DBMS_OUTPUT.PUT_LINE('Provider list for organization_id=' || lv_org_id);

  FOR rp IN (
    SELECT p.id   AS provider_id,
           p.name AS provider_name,
           p.speciality,
           p.gender,
           p.utilization
      FROM SYNTHEA.PROVIDERS p
     WHERE p.organization = lv_org_id
     ORDER BY p.utilization DESC, p.id
  ) LOOP
    EXIT WHEN lv_any_rows >= co_report_limit;
    lv_any_rows := lv_any_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      rp.provider_id || ' | ' || rp.provider_name || ' | ' || rp.speciality ||
      ' | ' || rp.gender || ' | utilization=' || rp.utilization
    );
  END LOOP;

  IF lv_any_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || lv_org_id);
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || lv_org_id);
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
