reference_answer:
CREATE OR REPLACE PROCEDURE report_providers_by_org(
  p_org_id      IN SYNTHEA.PROVIDERS.organization%TYPE,
  p_speciality  IN SYNTHEA.PROVIDERS.speciality%TYPE
) IS
  lv_any_rows NUMBER := 0;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  DBMS_OUTPUT.PUT_LINE(
    'Provider list for organization_id=' || p_org_id ||
    ', speciality_filter=' || p_speciality
  );

  FOR rp IN (
    SELECT p.id   AS provider_id,
           p.name AS provider_name,
           p.speciality,
           p.gender,
           p.utilization
      FROM SYNTHEA.PROVIDERS p
     WHERE p.organization = p_org_id
       AND (p_speciality IS NULL OR p.speciality = p_speciality)
     ORDER BY p.utilization DESC, p.id
  ) LOOP
    EXIT WHEN lv_any_rows >= co_report_limit;
    lv_any_rows := lv_any_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      rp.provider_id || ' | ' || rp.provider_name || ' | ' || rp.speciality ||
      ' | ' || rp.gender || ' | utilization=' || rp.utilization
    );
  END LOOP;

  IF lv_any_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || p_org_id || ' with given filter.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || p_org_id || ' with given filter.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_providers_by_org;
/

question:
Using the same provider listing from the previous procedure, create a small package that adds a helper function to classify provider utilization as HIGH/MEDIUM/LOW based on thresholds. Then create a package procedure that prints the same up-to-15 provider list, but with an extra utilization category column. If a provider has NULL utilization, treat it as zero.

Requirements:
Procedure Name: provider_reporting_pkg.report_providers_with_category.
Parameters:
p_org_id IN SYNTHEA.PROVIDERS.organization%TYPE.
Output: DBMS_OUTPUT.PUT_LINE('Provider list (with category) for organization_id=' || p_org_id);
DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || p_org_id);
DBMS_OUTPUT.PUT_LINE(rp.provider_id || ' | ' || rp.provider_name || ' | ' || rp.speciality || ' | ' || rp.gender || ' | utilization=' || rp.utilization || ' | category=' || provider_reporting_pkg.util_category(rp.utilization));
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No providers found for organization_id=' || p_org_id.
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
CREATE OR REPLACE PACKAGE provider_reporting_pkg IS
  FUNCTION util_category(
    p_utilization IN SYNTHEA.PROVIDERS.utilization%TYPE
  ) RETURN VARCHAR2;

  PROCEDURE report_providers_with_category(
    p_org_id IN SYNTHEA.PROVIDERS.organization%TYPE
  );
END provider_reporting_pkg;
/

CREATE OR REPLACE PACKAGE BODY provider_reporting_pkg IS
  FUNCTION util_category(
    p_utilization IN SYNTHEA.PROVIDERS.utilization%TYPE
  ) RETURN VARCHAR2 IS
    lv_util SYNTHEA.PROVIDERS.utilization%TYPE;
  BEGIN
    lv_util := NVL(p_utilization, 0);

    IF lv_util >= 1000 THEN
      RETURN 'HIGH';
    ELSIF lv_util >= 200 THEN
      RETURN 'MEDIUM';
    ELSE
      RETURN 'LOW';
    END IF;

  EXCEPTION
    WHEN OTHERS THEN
      RETURN 'LOW';
  END util_category;

  PROCEDURE report_providers_with_category(
    p_org_id IN SYNTHEA.PROVIDERS.organization%TYPE
  ) IS
    lv_any_rows NUMBER := 0;

    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Provider list (with category) for organization_id=' || p_org_id);

    FOR rp IN (
      SELECT p.id   AS provider_id,
             p.name AS provider_name,
             p.speciality,
             p.gender,
             NVL(p.utilization, 0) AS utilization
        FROM SYNTHEA.PROVIDERS p
       WHERE p.organization = p_org_id
       ORDER BY NVL(p.utilization, 0) DESC, p.id
    ) LOOP
      EXIT WHEN lv_any_rows >= co_report_limit;
      lv_any_rows := lv_any_rows + 1;

      DBMS_OUTPUT.PUT_LINE(
        rp.provider_id || ' | ' || rp.provider_name || ' | ' || rp.speciality ||
        ' | ' || rp.gender || ' | utilization=' || rp.utilization ||
        ' | category=' || provider_reporting_pkg.util_category(rp.utilization)
      );
    END LOOP;

    IF lv_any_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || p_org_id);
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No providers found for organization_id=' || p_org_id);
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_providers_with_category;
END provider_reporting_pkg;
/

