question:
You are building a quick county-level natality briefing for analysts. Create an anonymous PL/SQL report that, for a given year, prints the top counties by total births (highest to lowest). Treat the BIRTHS column as numeric where possible; if a row has non-numeric births, skip it but count how many rows were skipped. Print up to 15 counties.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(lv_year, 'YYYY') || ':');
DBMS_OUTPUT.PUT_LINE(RPAD('County', 35) || ' | ' || RPAD('FIPS', 10) || ' | ' || 'Births');
DBMS_OUTPUT.PUT_LINE('Skipped rows due to non-numeric births: ' || lv_skipped_rows);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_year          SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2019-01-01';
  co_report_limit  CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_skipped_rows  PLS_INTEGER := 0;

  CURSOR c_cnty_births(p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE) IS
    SELECT cn.county_of_residence,
           cn.county_of_residence_fips,
           SUM(TO_NUMBER(cn.births)) AS births_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND REGEXP_LIKE(cn.births, '^\s*[0-9]+\s*$')
     GROUP BY cn.county_of_residence,
              cn.county_of_residence_fips
     ORDER BY SUM(TO_NUMBER(cn.births)) DESC;

  lv_rows_printed  PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(lv_year, 'YYYY') || ':');
  DBMS_OUTPUT.PUT_LINE(RPAD('County', 35) || ' | ' || RPAD('FIPS', 10) || ' | ' || 'Births');

  SELECT COUNT(*)
    INTO lv_skipped_rows
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.year = lv_year
     AND NOT REGEXP_LIKE(cn.births, '^\s*[0-9]+\s*$');

  FOR r IN c_cnty_births(lv_year) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(r.county_of_residence, 35) || ' | ' ||
      RPAD(r.county_of_residence_fips, 10) || ' | ' ||
      TO_CHAR(r.births_num)
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Skipped rows due to non-numeric births: ' || lv_skipped_rows);

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

