question:
Now operationalize the briefing. Create a reusable package that (a) returns the total numeric births for a county/year and (b) prints a small detail report of up to 15 rows for that county/year, showing births plus key averages (age of mother, gestational age, birth weight). If the county/year has no numeric-birth rows, print a single message and exit cleanly.

Requirements:
Procedure Name: COUNTY_NATALITY_PKG
Parameters: p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
Output: DBMS_OUTPUT.PUT_LINE('County/year detail for county=' || p_county_name || ', year=' || TO_CHAR(p_year, 'YYYY') || ':');
DBMS_OUTPUT.PUT_LINE('Total births (numeric only): ' || TO_CHAR(lv_total_births));
DBMS_OUTPUT.PUT_LINE('Row: births=' || r.births || ', ave_age=' || r.ave_age_of_mother || ', oe_ga=' || r.ave_oe_gestational_age_wks || ', lmp_ga=' || r.ave_lmp_gestational_age_wks || ', ave_bw=' || r.ave_birth_weight_gms);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE county_natality_pkg IS
  FUNCTION get_total_births(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) RETURN NUMBER;

  PROCEDURE print_county_year_detail(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  );
END county_natality_pkg;
/

CREATE OR REPLACE PACKAGE BODY county_natality_pkg IS
  FUNCTION get_total_births(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) RETURN NUMBER IS
    lv_total_births NUMBER;
  BEGIN
    IF p_year IS NULL OR p_county_name IS NULL THEN
      RETURN 0;
    END IF;

    SELECT SUM(TO_NUMBER(cn.births))
      INTO lv_total_births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND cn.county_of_residence = p_county_name
       AND REGEXP_LIKE(cn.births, '^\s*[0-9]+\s*$');

    RETURN NVL(lv_total_births, 0);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN 0;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN 0;
  END get_total_births;

  PROCEDURE print_county_year_detail(
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_total_births NUMBER := 0;
    lv_rows_printed PLS_INTEGER := 0;

    CURSOR c_detail(
      cp_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
      cp_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE
    ) IS
      SELECT cn.births,
             cn.ave_age_of_mother,
             cn.ave_oe_gestational_age_wks,
             cn.ave_lmp_gestational_age_wks,
             cn.ave_birth_weight_gms
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = cp_year
         AND cn.county_of_residence = cp_county_name
         AND REGEXP_LIKE(cn.births, '^\s*[0-9]+\s*$')
       ORDER BY TO_NUMBER(cn.births) DESC;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('County/year detail for county=' || p_county_name || ', year=' || TO_CHAR(p_year, 'YYYY') || ':');

    lv_total_births := get_total_births(p_year => p_year, p_county_name => p_county_name);
    DBMS_OUTPUT.PUT_LINE('Total births (numeric only): ' || TO_CHAR(lv_total_births));

    IF lv_total_births = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    FOR r IN c_detail(p_year, p_county_name) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      EXIT WHEN lv_rows_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        'Row: births=' || r.births ||
        ', ave_age=' || r.ave_age_of_mother ||
        ', oe_ga=' || r.ave_oe_gestational_age_wks ||
        ', lmp_ga=' || r.ave_lmp_gestational_age_wks ||
        ', ave_bw=' || r.ave_birth_weight_gms
      );
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_county_year_detail;
END county_natality_pkg;
/

