CREATE OR REPLACE PROCEDURE find_natality_dq_issues(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_scan_limit     CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_scanned   PLS_INTEGER := 0;
  lv_suspect_count  PLS_INTEGER := 0;

  CURSOR c_scan(cp_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE) IS
    SELECT cn.county_of_residence,
           cn.county_of_residence_fips,
           cn.births,
           cn.ave_age_of_mother,
           cn.ave_oe_gestational_age_wks,
           cn.ave_lmp_gestational_age_wks,
           cn.ave_birth_weight_gms
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = cp_year
       AND REGEXP_LIKE(cn.births, '^\s*[0-9]+\s*$')
     ORDER BY TO_NUMBER(cn.births) DESC;
BEGIN
  DBMS_OUTPUT.PUT_LINE('DQ scan for year=' || TO_CHAR(p_year, 'YYYY') || ':');

  FOR r IN c_scan(p_year) LOOP
    lv_rows_scanned := lv_rows_scanned + 1;
    EXIT WHEN lv_rows_scanned > co_scan_limit;

    IF NOT REGEXP_LIKE(r.ave_age_of_mother, '^\s*[0-9]+(\.[0-9]+)?\s*$')
       OR NOT REGEXP_LIKE(r.ave_birth_weight_gms, '^\s*[0-9]+(\.[0-9]+)?\s*$')
       OR NOT REGEXP_LIKE(r.ave_oe_gestational_age_wks, '^\s*[0-9]+(\.[0-9]+)?\s*$')
       OR NOT REGEXP_LIKE(r.ave_lmp_gestational_age_wks, '^\s*[0-9]+(\.[0-9]+)?\s*$') THEN
      lv_suspect_count := lv_suspect_count + 1;

      DBMS_OUTPUT.PUT_LINE(
        'Suspect row: county=' || r.county_of_residence ||
        ', fips=' || r.county_of_residence_fips ||
        ', births=' || r.births ||
        ', ave_age=' || r.ave_age_of_mother ||
        ', oe_ga=' || r.ave_oe_gestational_age_wks ||
        ', lmp_ga=' || r.ave_lmp_gestational_age_wks ||
        ', ave_bw=' || r.ave_birth_weight_gms
      );
    END IF;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Total suspect rows found (limited scan): ' || lv_suspect_count);

  IF lv_rows_scanned = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END find_natality_dq_issues;
/

question:
Finally, tie everything together into a single county selection routine. Create a procedure that, for a given year and a minimum births threshold, finds up to 15 counties whose total births meet the threshold and prints a concise line per county (county, fips, total births). Use an explicit cursor and control flow to stop when the limit is reached. Make sure you handle bad numeric conversions safely (skip non-numeric births). If the threshold is invalid (NULL or negative), print a message and exit without querying.

Requirements:
Procedure Name: PRINT_COUNTIES_OVER_BIRTH_THRESHOLD
Parameters: p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
p_min_births IN NUMBER
Output: DBMS_OUTPUT.PUT_LINE('Invalid threshold.');
DBMS_OUTPUT.PUT_LINE('Counties meeting threshold for year=' || TO_CHAR(p_year, 'YYYY') || ', min_births=' || TO_CHAR(p_min_births) || ':');
DBMS_OUTPUT.PUT_LINE('County=' || r.county_of_residence || ', FIPS=' || r.county_of_residence_fips || ', total_births=' || TO_CHAR(r.total_births));
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN OTHERS THEN: 'Unexpected error.'

