CREATE OR REPLACE PROCEDURE print_counties_over_birth_threshold(
  p_year      IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_min_births IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed      PLS_INTEGER := 0;

  CURSOR c_cnty(cp_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
                cp_min  IN NUMBER) IS
    SELECT cn.county_of_residence,
           cn.county_of_residence_fips,
           SUM(TO_NUMBER(cn.births)) AS total_births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = cp_year
       AND REGEXP_LIKE(cn.births, '^\s*[0-9]+\s*$')
     GROUP BY cn.county_of_residence,
              cn.county_of_residence_fips
    HAVING SUM(TO_NUMBER(cn.births)) >= cp_min
     ORDER BY SUM(TO_NUMBER(cn.births)) DESC;
BEGIN
  IF p_min_births IS NULL OR p_min_births < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid threshold.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Counties meeting threshold for year=' || TO_CHAR(p_year, 'YYYY') || ', min_births=' || TO_CHAR(p_min_births) || ':');

  FOR r IN c_cnty(p_year, p_min_births) LOOP
    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'County=' || r.county_of_residence ||
      ', FIPS=' || r.county_of_residence_fips ||
      ', total_births=' || TO_CHAR(r.total_births)
    );
  END LOOP;

  IF lv_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END print_counties_over_birth_threshold;
/

