CREATE OR REPLACE PROCEDURE report_county_natality_snapshot(
  p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
  p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_county SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;
  lv_year   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  lv_county := p_county_name;
  lv_year   := p_year;

  -- If inputs are missing, use latest available year for the county.
  IF lv_county IS NULL THEN
    lv_county := 'UNKNOWN';
  END IF;

  IF lv_year IS NULL THEN
    SELECT MAX(cn.year)
      INTO lv_year
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence = lv_county;
  END IF;

  DBMS_OUTPUT.PUT_LINE('County: ' || lv_county || ' | Year: ' || TO_CHAR(lv_year, 'YYYY'));

  FOR rec IN (
    SELECT cn.births,
           cn.ave_age_of_mother,
           cn.ave_birth_weight_gms
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence = lv_county
       AND cn.year = lv_year
       AND ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      'Births=' || rec.births ||
      ' | AveAgeMother=' || rec.ave_age_of_mother ||
      ' | AveBirthWeightGms=' || rec.ave_birth_weight_gms
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the given filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_natality_snapshot;
/

