    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('SUSPICIOUS: births_text=' || rec.births);
    END;
  END LOOP;

  IF lv_rows_checked = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the given filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Numeric conversion error.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END screen_natality_births_numeric;
