  lv_rows         PLS_INTEGER := 0;
  lv_state        VARCHAR2(20);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Bike station availability snapshot');

  FOR rec IN (
    SELECT limited_rows.region_name,
           limited_rows.station_name,
           limited_rows.num_bikes_available,
           limited_rows.capacity
      FROM (
