CREATE OR REPLACE PROCEDURE report_region_station_availability(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability.
  lv_region_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_rows         PLS_INTEGER := 0;
  lv_state        VARCHAR2(20);
BEGIN
  IF p_region_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Region name is required.');
  ELSE
    SELECT r.region_id
      INTO lv_region_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE UPPER(r.name) LIKE UPPER(p_region_name);

    DBMS_OUTPUT.PUT_LINE('Availability report for region: ' || p_region_name);

    FOR rec IN (
      SELECT limited_rows.station_name,
             limited_rows.num_bikes_available,
             limited_rows.capacity
        FROM (
              SELECT i.name AS station_name,
                     s.num_bikes_available AS num_bikes_available,
                     i.capacity AS capacity
                FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO i
                INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
                  ON s.station_id = i.station_id
               WHERE i.region_id = lv_region_id
                 AND REGEXP_LIKE(i.capacity, '^\d+$')
                 AND REGEXP_LIKE(s.num_bikes_available, '^\d+$')
               ORDER BY i.name
             ) limited_rows
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rows := lv_rows + 1;

      IF TO_NUMBER(rec.num_bikes_available) = 0 THEN
        lv_state := 'EMPTY';
      ELSE
        lv_state := 'AVAILABLE';
      END IF;

      DBMS_OUTPUT.PUT_LINE('Station: ' || rec.station_name || ', Bikes: ' || rec.num_bikes_available || ', Capacity: ' || rec.capacity || ', Status: ' || lv_state);
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No stations found for region: ' || p_region_name);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Rows printed: ' || lv_rows);
    END IF;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_station_availability;
/

CREATE OR REPLACE FUNCTION get_station_service_label(
  p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
) RETURN VARCHAR2 IS
  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_is_renting   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_renting%TYPE;
  lv_is_returning SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_returning%TYPE;
  lv_bikes        SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
  lv_label        VARCHAR2(40);
BEGIN
  IF p_station_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Station id is required.');
    RETURN 'INPUT REQUIRED';
  ELSE
    SELECT i.name,
           s.is_renting,
           s.is_returning,
           s.num_bikes_available
      INTO lv_station_name,
           lv_is_renting,
           lv_is_returning,
           lv_bikes
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO i
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
        ON s.station_id = i.station_id
     WHERE i.station_id = p_station_id;

    IF lv_is_renting <> '1' THEN
      lv_label := 'NOT RENTING';
    ELSIF lv_is_returning <> '1' THEN
      lv_label := 'NOT RETURNING';
    ELSIF REGEXP_LIKE(lv_bikes, '^\d+$') AND TO_NUMBER(lv_bikes) = 0 THEN
      lv_label := 'OUT OF BIKES';
    ELSE
      lv_label := 'READY';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Station ' || p_station_id || ' service label: ' || lv_label);
    RETURN lv_label;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'NO DATA FOUND';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'MULTIPLE ROWS RETURNED';
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data found.');
    RETURN 'BAD NUMERIC DATA';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNEXPECTED ERROR';
END get_station_service_label;
/

