CREATE OR REPLACE PROCEDURE diagnose_station_status_mismatch(
  p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
) IS
  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_capacity     SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.capacity%TYPE;
  lv_bikes        SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
  lv_is_renting   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_renting%TYPE;
BEGIN
  IF p_station_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Station id is required for diagnosis.');
  ELSE
    SELECT i.name,
           i.capacity,
           s.num_bikes_available,
           s.is_renting
      INTO lv_station_name,
           lv_capacity,
           lv_bikes,
           lv_is_renting
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO i
      LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
        ON s.station_id = i.station_id
     WHERE i.station_id = p_station_id;

    DBMS_OUTPUT.PUT_LINE('Diagnostic for station: ' || lv_station_name || ' (' || p_station_id || ')');

    IF lv_capacity IS NULL OR NOT REGEXP_LIKE(lv_capacity, '^\d+$') THEN
      DBMS_OUTPUT.PUT_LINE('Root cause: capacity is not numeric.');
    ELSIF lv_bikes IS NULL OR NOT REGEXP_LIKE(lv_bikes, '^\d+$') THEN
      DBMS_OUTPUT.PUT_LINE('Root cause: bike availability is not numeric.');
    ELSIF TO_NUMBER(lv_bikes) > TO_NUMBER(lv_capacity) THEN
      DBMS_OUTPUT.PUT_LINE('Root cause: bikes available exceeds station capacity.');
    ELSIF lv_is_renting <> '1' THEN
      DBMS_OUTPUT.PUT_LINE('Root cause: station is not currently renting.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Root cause: no mismatch found for current station status.');
    END IF;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END diagnose_station_status_mismatch;
/

question:
Build a quick console report for our debt data quality review.

Given an income group (for example “Low income” or “Upper middle income”), list up to 15 countries in that income group and show how many international debt rows we have for each country in the dataset. Sort the output so the countries with the most rows show first.

Make it robust: if the income group doesn’t exist, print a clear message; and don’t allow the session to crash for any unexpected issue.

Requirements:
Procedure Name: debt_reporting_pkg.print_country_debt_rowcounts
Parameters:
p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Top countries by debt row count for income group: ' || p_income_group);
DBMS_OUTPUT.PUT_LINE(RPAD('Country', 45) || 'Row_Count');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 45, '-') || RPAD('-', 10, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.country_name, 45) || rec.row_count);
DBMS_OUTPUT.PUT_LINE('No matching countries found for income group: ' || p_income_group);
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No matching countries found for income group: ' || p_income_group
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE debt_reporting_pkg IS
  PROCEDURE print_country_debt_rowcounts(
    p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE
  );
END debt_reporting_pkg;
/

CREATE OR REPLACE PACKAGE BODY debt_reporting_pkg IS
  PROCEDURE print_country_debt_rowcounts(
    p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Top countries by debt row count for income group: ' || p_income_group);
    DBMS_OUTPUT.PUT_LINE(RPAD('Country', 45) || 'Row_Count');
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 45, '-') || RPAD('-', 10, '-'));

    FOR rec IN (
      SELECT id.country_name AS country_name,
             COUNT(*) AS row_count
        FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
        INNER JOIN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
          ON id.country_code = cs.country_code
       WHERE cs.income_group = p_income_group
       GROUP BY id.country_name
       ORDER BY COUNT(*) DESC, id.country_name
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE(RPAD(rec.country_name, 45) || rec.row_count);
    END LOOP;

    IF lv_rows_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No matching countries found for income group: ' || p_income_group);
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_country_debt_rowcounts;
END debt_reporting_pkg;
/

