CREATE OR REPLACE PROCEDURE classify_country_debt_by_threshold(
  p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE,
  p_threshold    IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
  lv_category     VARCHAR2(10);
BEGIN
  IF p_threshold < 0 THEN
    RAISE VALUE_ERROR;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Income group: ' || p_income_group || ' | Threshold: ' || p_threshold);
  DBMS_OUTPUT.PUT_LINE(RPAD('Country', 45) || RPAD('Row_Count', 12) || 'Category');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 45, '-') || RPAD('-', 12, '-') || RPAD('-', 10, '-'));

  FOR rec IN (
    SELECT id.country_name AS country_name,
           COUNT(*) AS row_count
      FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
      INNER JOIN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
        ON id.country_code = cs.country_code
     WHERE cs.income_group = p_income_group
     GROUP BY id.country_name
     ORDER BY COUNT(*) DESC, id.country_name
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;

    IF rec.row_count >= p_threshold THEN
      lv_category := 'High';
    ELSE
      lv_category := 'Low';
    END IF;

    DBMS_OUTPUT.PUT_LINE(RPAD(rec.country_name, 45) || RPAD(rec.row_count, 12) || lv_category);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching countries found for income group: ' || p_income_group);
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid threshold (must be >= 0).');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END classify_country_debt_by_threshold;
/

