CREATE OR REPLACE PROCEDURE pr_print_intersectional_rep(
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Intersectional representation (up to ' || co_report_limit || ' rows)');
  DBMS_OUTPUT.PUT_LINE('Workforce=' || NVL(p_workforce, 'NULL') || ', Year=' || NVL(p_report_year, 'NULL'));

  FOR r IN (
    SELECT ir.gender_us,
           ir.race_asian,
           ir.race_black,
           ir.race_hispanic_latinx,
           ir.race_native_american,
           ir.race_white
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION ir
     WHERE (p_workforce IS NULL OR ir.workforce = p_workforce)
       AND (p_report_year IS NULL OR ir.report_year = p_report_year)
     ORDER BY ir.gender_us,
              ir.race_asian,
              ir.race_black,
              ir.race_hispanic_latinx,
              ir.race_native_american,
              ir.race_white
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Gender=' || r.gender_us ||
      ' | Asian=' || r.race_asian ||
      ' | Black=' || r.race_black ||
      ' | Hispanic/Latinx=' || r.race_hispanic_latinx ||
      ' | Native American=' || r.race_native_american ||
      ' | White=' || r.race_white
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the given workforce/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END pr_print_intersectional_rep;
