CREATE OR REPLACE PROCEDURE pr_rep_data_quality(
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
) IS
  lv_total_rows           PLS_INTEGER := 0;
  lv_rows_with_null_race  PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE(
    'Data quality summary for workforce=' || NVL(p_workforce, 'NULL') ||
    ', year=' || NVL(p_report_year, 'NULL')
  );

  -- Aggregate counts in a single pass.
  SELECT COUNT(*),
         SUM(
           CASE
             WHEN ir.race_asian IS NULL
               OR ir.race_black IS NULL
               OR ir.race_hispanic_latinx IS NULL
               OR ir.race_native_american IS NULL
               OR ir.race_white IS NULL
             THEN 1
             ELSE 0
           END
         )
    INTO lv_total_rows, lv_rows_with_null_race
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION ir
   WHERE (p_workforce IS NULL OR ir.workforce = p_workforce)
     AND (p_report_year IS NULL OR ir.report_year = p_report_year);

  IF lv_total_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows exist for the given workforce/year.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Total rows=' || lv_total_rows);
  DBMS_OUTPUT.PUT_LINE('Rows with any NULL race value=' || lv_rows_with_null_race);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END pr_rep_data_quality;
/

