CREATE OR REPLACE PROCEDURE report_fertility_snapshot(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
) IS
  lv_country_code         CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_country_area         CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_area%TYPE;
  lv_country_name         CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;
  lv_year                 CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;
  lv_total_fertility_rate CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_sex_ratio_at_birth   CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.sex_ratio_at_birth%TYPE;
BEGIN
  -- Resolve the country name to a single code; TOO_MANY_ROWS is intentional if ambiguous.
  SELECT cna.country_code,
         cna.country_area,
         cna.country_name
    INTO lv_country_code,
         lv_country_area,
         lv_country_name
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cna
   WHERE cna.country_name = p_country_name;

  -- Pull the fertility measures for the same code and year.
  SELECT asfr.year,
         asfr.total_fertility_rate,
         asfr.sex_ratio_at_birth
    INTO lv_year,
         lv_total_fertility_rate,
         lv_sex_ratio_at_birth
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
   WHERE asfr.country_code = lv_country_code
     AND asfr.year = p_year;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (code=' || lv_country_code || ', area=' || NVL(lv_country_area, 'UNKNOWN') || ')');
  DBMS_OUTPUT.PUT_LINE('Year: ' || lv_year);
  DBMS_OUTPUT.PUT_LINE('Total fertility rate: ' || lv_total_fertility_rate);
  DBMS_OUTPUT.PUT_LINE('Sex ratio at birth: ' || lv_sex_ratio_at_birth);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_fertility_snapshot;
/

