CREATE OR REPLACE PROCEDURE report_population_context(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
) IS
  lv_country_code       CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_country_name       CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;
  lv_midyear_population CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.midyear_population%TYPE;
  lv_crude_birth_rate   CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_birth_rate%TYPE;
  lv_has_pop            NUMBER := 0;
  lv_has_cbr            NUMBER := 0;
BEGIN
  SELECT cna.country_code,
         cna.country_name
    INTO lv_country_code,
         lv_country_name
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cna
   WHERE cna.country_name = p_country_name;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (code=' || lv_country_code || ')');
  DBMS_OUTPUT.PUT_LINE('Year: ' || p_year);

  BEGIN
    SELECT mp.midyear_population
      INTO lv_midyear_population
      FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION mp
     WHERE mp.country_code = lv_country_code
       AND mp.year = p_year;
    lv_has_pop := 1;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      lv_has_pop := 0;
  END;

  BEGIN
    SELECT bdgr.crude_birth_rate
      INTO lv_crude_birth_rate
      FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bdgr
     WHERE bdgr.country_code = lv_country_code
       AND bdgr.year = p_year;
    lv_has_cbr := 1;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      lv_has_cbr := 0;
  END;

  IF lv_has_pop = 1 THEN
    DBMS_OUTPUT.PUT_LINE('Midyear population: ' || lv_midyear_population);
  ELSE
    DBMS_OUTPUT.PUT_LINE('Midyear population: MISSING');
  END IF;

  IF lv_has_cbr = 1 THEN
    DBMS_OUTPUT.PUT_LINE('Crude birth rate: ' || lv_crude_birth_rate);
  ELSE
    DBMS_OUTPUT.PUT_LINE('Crude birth rate: MISSING');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_population_context;
/

