CREATE OR REPLACE PACKAGE BODY pkg_country_scorecard IS
  PROCEDURE report_year_scorecard(
    p_year IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_year         CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;
  BEGIN
    IF p_year IS NULL THEN
      SELECT MAX(asfr.year)
        INTO lv_year
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr;
    ELSE
      lv_year := p_year;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Scorecard year: ' || lv_year);

    FOR r IN (
      SELECT *
        FROM (
          SELECT asfr.country_name AS country_name,
                 asfr.country_code AS country_code,
                 asfr.total_fertility_rate AS total_fertility_rate,
                 bdgr.crude_birth_rate AS crude_birth_rate,
                 get_birthrate_risk_flag(asfr.country_name, lv_year) AS risk_flag
            FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
            LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bdgr
              ON bdgr.country_code = asfr.country_code
             AND bdgr.year = asfr.year
            INNER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cna
              ON cna.country_code = asfr.country_code
           WHERE asfr.year = lv_year
           ORDER BY asfr.country_name
        )
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'Country: ' || r.country_name || ' (code=' || r.country_code || '), TFR=' || r.total_fertility_rate ||
