CREATE OR REPLACE PROCEDURE audit_country_data_quality(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for audit readability
  lv_country_code CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_country_name CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;
  lv_issue_count  NUMBER := 0;
BEGIN
  SELECT cna.country_code,
         cna.country_name
    INTO lv_country_code,
         lv_country_name
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cna
   WHERE cna.country_name = p_country_name;

  DBMS_OUTPUT.PUT_LINE('Audit country: ' || lv_country_name || ' (code=' || lv_country_code || ')');

  FOR r IN (
    SELECT *
      FROM (
        SELECT asfr.year AS year,
               bdgr.crude_birth_rate AS crude_birth_rate,
               mp.midyear_population AS midyear_population
          FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
          LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bdgr
            ON bdgr.country_code = asfr.country_code
           AND bdgr.year = asfr.year
          LEFT OUTER JOIN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION mp
            ON mp.country_code = asfr.country_code
           AND mp.year = asfr.year
         WHERE asfr.country_code = lv_country_code
         ORDER BY asfr.year DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    IF r.crude_birth_rate IS NOT NULL AND NOT REGEXP_LIKE(r.crude_birth_rate, '^[-]?[0-9]+([.][0-9]+)?$') THEN
      lv_issue_count := lv_issue_count + 1;
      DBMS_OUTPUT.PUT_LINE('WARN: Non-numeric crude birth rate for year ' || r.year || ': ' || r.crude_birth_rate);
    END IF;

    IF r.midyear_population IS NULL THEN
      lv_issue_count := lv_issue_count + 1;
      DBMS_OUTPUT.PUT_LINE('WARN: Missing midyear population for year ' || r.year);
    END IF;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Issue count: ' || lv_issue_count);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END audit_country_data_quality;
/

