CREATE OR REPLACE PROCEDURE county_births_top15(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(p_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE(RPAD('County', 30) || RPAD('Births', 12) || RPAD('AvgWt(g)', 12) || 'AvgAgeMom');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || RPAD('-', 12, '-') || RPAD('-', 12, '-') || RPAD('-', 10, '-'));

  -- Data quality: numeric fields are stored as strings; only keep rows that look numeric.
  FOR rec IN (
    SELECT county_of_residence,
           TO_NUMBER(births) AS births_num,
           TO_NUMBER(ave_birth_weight_gms) AS avg_wt_num,
           TO_NUMBER(ave_age_of_mother) AS avg_age_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
     WHERE year = p_year
       AND REGEXP_LIKE(births, '^\s*[0-9]+\s*$')
       AND REGEXP_LIKE(ave_birth_weight_gms, '^\s*[0-9]+(\.[0-9]+)?\s*$')
       AND REGEXP_LIKE(ave_age_of_mother, '^\s*[0-9]+(\.[0-9]+)?\s*$')
     ORDER BY TO_NUMBER(births) DESC, county_of_residence
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 30) ||
      RPAD(TO_CHAR(rec.births_num), 12) ||
      RPAD(TO_CHAR(rec.avg_wt_num, 'FM9999990.0'), 12) ||
      TO_CHAR(rec.avg_age_num, 'FM9990.0')
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested year after data-quality filtering.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END county_births_top15;
/

CREATE OR REPLACE PROCEDURE county_birth_weight_index_top15(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_nat_avg_wt NUMBER;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- National average birth weight for the year (only numeric-looking rows)
  SELECT AVG(TO_NUMBER(ave_birth_weight_gms))
    INTO lv_nat_avg_wt
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
   WHERE year = p_year
     AND REGEXP_LIKE(ave_birth_weight_gms, '^\s*[0-9]+(\.[0-9]+)?\s*$');

  DBMS_OUTPUT.PUT_LINE('Top counties by birth-weight index for year=' || TO_CHAR(p_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE('NationalAvgWt(g)=' || TO_CHAR(lv_nat_avg_wt, 'FM9999990.0'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('County', 30) || RPAD('Idx', 10) || 'CountyAvgWt(g)');

  FOR rec IN (
    WITH county_avg AS (
      SELECT county_of_residence,
             AVG(TO_NUMBER(ave_birth_weight_gms)) AS avg_wt
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
       WHERE year = p_year
         AND REGEXP_LIKE(ave_birth_weight_gms, '^\s*[0-9]+(\.[0-9]+)?\s*$')
       GROUP BY county_of_residence
    ), ranked AS (
      SELECT county_of_residence,
             avg_wt,
             avg_wt / lv_nat_avg_wt AS wt_index,
             RANK() OVER (ORDER BY avg_wt / lv_nat_avg_wt DESC, county_of_residence) AS rnk
        FROM county_avg
    )
    SELECT rnk,
           county_of_residence,
           wt_index,
           avg_wt
      FROM ranked
     WHERE rnk <= co_report_limit
     ORDER BY rnk, county_of_residence
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.rnk) ||
      RPAD(' ', 6 - LENGTH(TO_CHAR(rec.rnk))) ||
      RPAD(rec.county_of_residence, 30) ||
      RPAD(TO_CHAR(rec.wt_index, 'FM9990.000'), 10) ||
      TO_CHAR(rec.avg_wt, 'FM9999990.0')
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No ranked counties produced for the requested year after data-quality filtering.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Cannot compute index because the national average is zero.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END county_birth_weight_index_top15;
/

CREATE OR REPLACE PROCEDURE county_bw_bucket_report(
  p_year               IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_low_threshold_gms  IN NUMBER,
  p_high_threshold_gms IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Birth-weight bucket report for year=' || TO_CHAR(p_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE('Thresholds: low<' || TO_CHAR(p_low_threshold_gms) || ', high>=' || TO_CHAR(p_high_threshold_gms));

  IF p_low_threshold_gms IS NULL
     OR p_high_threshold_gms IS NULL
     OR p_low_threshold_gms >= p_high_threshold_gms THEN
    DBMS_OUTPUT.PUT_LINE('Invalid thresholds: low must be less than high.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE(RPAD('County', 30) || RPAD('Births', 12) || RPAD('AvgWt(g)', 12) || 'Bucket');

  FOR rec IN (
    WITH base AS (
      SELECT county_of_residence,
             TO_NUMBER(births) AS births_num,
             TO_NUMBER(ave_birth_weight_gms) AS avg_wt_num
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
       WHERE year = p_year
         AND REGEXP_LIKE(births, '^\s*[0-9]+\s*$')
         AND REGEXP_LIKE(ave_birth_weight_gms, '^\s*[0-9]+(\.[0-9]+)?\s*$')
    ), top_births AS (
      SELECT county_of_residence,
             births_num,
             avg_wt_num,
             ROW_NUMBER() OVER (ORDER BY births_num DESC, county_of_residence) AS rn
        FROM base
    )
    SELECT county_of_residence,
           births_num,
           avg_wt_num,
           CASE
             WHEN avg_wt_num < p_low_threshold_gms THEN 'Low'
             WHEN avg_wt_num >= p_high_threshold_gms THEN 'High'
             ELSE 'Normal'
           END AS bucket
      FROM top_births
     WHERE rn <= co_report_limit
     ORDER BY births_num DESC, county_of_residence
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 30) ||
      RPAD(TO_CHAR(rec.births_num), 12) ||
      RPAD(TO_CHAR(rec.avg_wt_num, 'FM9999990.0'), 12) ||
      rec.bucket
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No counties available for bucketing after data-quality filtering.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric threshold value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END county_bw_bucket_report;
/

