  );

  PROCEDURE validate_representation_inputs(
    p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
    p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
  );

  FUNCTION get_most_common_workforce_year
    RETURN VARCHAR2;

  PROCEDURE print_gender_nulls_by_year(
    p_workforce IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
    p_year_from IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE,
    p_year_to   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
  );
END dei_rep_reporting;
/

CREATE OR REPLACE PACKAGE BODY dei_rep_reporting AS
  PROCEDURE print_representation_snapshot(
    p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
    p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    FOR rec IN (
      SELECT r.workforce,
             r.report_year,
             r.gender_us,
             r.race_asian,
             r.race_black,
             r.race_hispanic_latinx,
             r.race_native_american,
             r.race_white
        FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
       WHERE (p_workforce IS NULL OR r.workforce = p_workforce)
         AND (p_report_year IS NULL OR r.report_year = p_report_year)
       ORDER BY r.report_year, r.workforce, r.gender_us
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        'Workforce=' || rec.workforce ||
        ' | Year=' || rec.report_year ||
        ' | Gender=' || rec.gender_us ||
        ' | Asian=' || rec.race_asian ||
        ' | Black=' || rec.race_black ||
        ' | Hispanic/Latinx=' || rec.race_hispanic_latinx ||
        ' | Native American=' || rec.race_native_american ||
        ' | White=' || rec.race_white
      );

      lv_rows_printed := lv_rows_printed + 1;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_representation_snapshot;


  PROCEDURE validate_representation_inputs(
    p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
    p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
  ) IS
    lv_any_row_cnt      PLS_INTEGER;
    lv_null_gender_cnt  PLS_INTEGER;
  BEGIN
    IF p_workforce IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Validation failed: workforce is required.');
      RETURN;
    END IF;

    IF p_report_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Validation failed: report year is required.');
      RETURN;
    END IF;

    SELECT COUNT(*)
      INTO lv_any_row_cnt
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
     WHERE r.workforce = p_workforce
       AND r.report_year = p_report_year;

    IF lv_any_row_cnt = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

    SELECT COUNT(*)
      INTO lv_null_gender_cnt
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
     WHERE r.workforce = p_workforce
       AND r.report_year = p_report_year
       AND r.gender_us IS NULL;

    IF lv_null_gender_cnt > 0 THEN
      DBMS_OUTPUT.PUT_LINE('Validation failed: no rows found for the provided workforce/year.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Validation passed: inputs are usable for reporting.');

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Validation failed: no rows found for the provided workforce/year.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END validate_representation_inputs;


  FUNCTION get_most_common_workforce_year
    RETURN VARCHAR2
  IS
    lv_pair VARCHAR2(200);
  BEGIN
    SELECT x.workforce || '|' || x.report_year
      INTO lv_pair
      FROM (
        SELECT r.workforce, r.report_year, COUNT(*) cnt
          FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
         GROUP BY r.workforce, r.report_year
         ORDER BY COUNT(*) DESC, r.workforce, r.report_year
      ) x
     WHERE ROWNUM = 1;

    RETURN lv_pair;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END get_most_common_workforce_year;


  PROCEDURE print_gender_nulls_by_year(
    p_workforce IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
    p_year_from IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE,
    p_year_to   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
  ) IS
    co_report_limit       CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_year_from_num      PLS_INTEGER;
    lv_year_to_num        PLS_INTEGER;
    lv_year_num           PLS_INTEGER;
    lv_total_rows         PLS_INTEGER;
    lv_null_gender_rows   PLS_INTEGER;
    lv_lines_printed      PLS_INTEGER := 0;
  BEGIN
    -- Convert year strings to numbers; invalid values raise VALUE_ERROR.
    lv_year_from_num := TO_NUMBER(p_year_from);
    lv_year_to_num := TO_NUMBER(p_year_to);

    IF p_workforce IS NULL THEN
      RAISE NO_DATA_FOUND;
    END IF;

    IF lv_year_from_num > lv_year_to_num THEN
      lv_year_num := lv_year_from_num;
      lv_year_from_num := lv_year_to_num;
      lv_year_to_num := lv_year_num;
    END IF;

    lv_year_num := lv_year_from_num;
    WHILE lv_year_num <= lv_year_to_num LOOP
      EXIT WHEN lv_lines_printed >= co_report_limit;

      SELECT COUNT(*)
        INTO lv_total_rows
        FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
       WHERE r.workforce = p_workforce
         AND r.report_year = TO_CHAR(lv_year_num);

      SELECT COUNT(*)
        INTO lv_null_gender_rows
        FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
       WHERE r.workforce = p_workforce
         AND r.report_year = TO_CHAR(lv_year_num)
         AND r.gender_us IS NULL;

      DBMS_OUTPUT.PUT_LINE(
        'Workforce=' || p_workforce ||
        ' | Year=' || TO_CHAR(lv_year_num) ||
        ' | Rows=' || TO_CHAR(lv_total_rows) ||
        ' | Rows with missing gender=' || TO_CHAR(lv_null_gender_rows)
      );

      lv_year_num := lv_year_num + 1;
      lv_lines_printed := lv_lines_printed + 1;
    END LOOP;

    IF lv_lines_printed = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year input.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_gender_nulls_by_year;

END dei_rep_reporting;
/

