CREATE OR REPLACE PROCEDURE get_county_births(
  p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
  p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  lv_births SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.births%TYPE;
BEGIN
  IF p_county_name IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('County and year are required.');
    RETURN;
  END IF;

  -- Single-row lookup for the county-year point-in-time value
  SELECT cn.births
    INTO lv_births
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.county_of_residence = p_county_name
     AND cn.year = p_year;

  DBMS_OUTPUT.PUT_LINE(
    'County=' || p_county_name || ' | Year=' || TO_CHAR(p_year, 'YYYY') || ' | Births=' || lv_births
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END get_county_births;
