CREATE OR REPLACE PROCEDURE report_births_category(
  p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
  p_start_year  IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_end_year    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
  lv_births_num   NUMBER;
  lv_category     VARCHAR2(20);
BEGIN
  IF p_county_name IS NULL OR p_start_year IS NULL OR p_end_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('County and year range are required.');
    RETURN;
  END IF;

  IF p_start_year > p_end_year THEN
    DBMS_OUTPUT.PUT_LINE('Start year is after end year.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT cn.year,
           cn.births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence = p_county_name
       AND cn.year BETWEEN p_start_year AND p_end_year
     ORDER BY cn.year
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    lv_category := 'UNKNOWN';

    IF rec.births IS NOT NULL THEN
      BEGIN
        lv_births_num := TO_NUMBER(rec.births);

        IF lv_births_num > 10000 THEN
          lv_category := 'HIGH';
        ELSIF lv_births_num >= 5000 THEN
          lv_category := 'MEDIUM';
        ELSE
          lv_category := 'LOW';
        END IF;
      EXCEPTION
        WHEN VALUE_ERROR THEN
          lv_category := 'UNKNOWN';
      END;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'County=' || p_county_name || ' | Year=' || TO_CHAR(rec.year, 'YYYY') || ' | Category=' || lv_category
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for county=' || p_county_name || ' in the given year range.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad births value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_births_category;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_season_id IPL.MATCH.season_id%TYPE;
  lv_season_id_txt VARCHAR2(50) := '1';
  lv_rows PLS_INTEGER := 0;
BEGIN
  -- Convert text input to number to allow a VALUE_ERROR test scenario
  lv_season_id := TO_NUMBER(lv_season_id_txt);

  DBMS_OUTPUT.PUT_LINE('--- Match report for season_id=' || NVL(TO_CHAR(lv_season_id), 'NULL') || ' ---');

  FOR rec IN (
    SELECT m.match_date,
           m.venue,
           t1.name AS team1_name,
           t2.name AS team2_name,
           tw.name AS winner_name
      FROM IPL.MATCH m
      INNER JOIN IPL.TEAM t1
        ON t1.team_id = m.team_1
      INNER JOIN IPL.TEAM t2
        ON t2.team_id = m.team_2
      LEFT OUTER JOIN IPL.TEAM tw
        ON tw.team_id = m.match_winner
     WHERE m.season_id = lv_season_id
     ORDER BY m.match_date, m.match_id
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.match_date, 'YYYY-MM-DD') || ' | ' || rec.venue || ' | ' || rec.team1_name || ' vs ' || rec.team2_name || ' | Winner: ' || NVL(rec.winner_name, 'NO RESULT')
    );
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matches found for the given season.');
  END IF;
EXCEPTION
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid season id (not a number).');
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

