CREATE OR REPLACE PROCEDURE report_season_top_winners(
  p_season_id IN IPL.MATCH.season_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 10; -- Keep output short for operational use
  lv_rows PLS_INTEGER := 0;
BEGIN
  IF p_season_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input season id is NULL.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('--- Top winners for season_id=' || TO_CHAR(p_season_id) || ' ---');

  FOR rec IN (
    SELECT t.name AS team_name,
           COUNT(*) AS wins
      FROM IPL.MATCH m
      INNER JOIN IPL.TEAM t
        ON t.team_id = m.match_winner
     WHERE m.season_id = p_season_id
       AND m.match_winner IS NOT NULL
     GROUP BY t.name
     ORDER BY COUNT(*) DESC, t.name
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(RPAD(rec.team_name, 30) || ' wins=' || TO_CHAR(rec.wins));
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No winners found for the given season.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_season_top_winners;
