CREATE OR REPLACE PACKAGE season_ops IS
  PROCEDURE validate_season(
    p_season_id IN IPL.MATCH.season_id%TYPE,
    p_is_valid  OUT NUMBER
  );

  PROCEDURE print_season_summary(
    p_season_id IN IPL.MATCH.season_id%TYPE
  );
END season_ops;
/

CREATE OR REPLACE PACKAGE BODY season_ops IS
  PROCEDURE validate_season(
    p_season_id IN IPL.MATCH.season_id%TYPE,
    p_is_valid  OUT NUMBER
  ) IS
    lv_dummy IPL.MATCH.match_id%TYPE;
  BEGIN
    p_is_valid := 0;

    IF p_season_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input season id is NULL.');
      RETURN;
    END IF;

    SELECT m.match_id
      INTO lv_dummy
      FROM IPL.MATCH m
     WHERE m.season_id = p_season_id
       AND ROWNUM = 1;

    p_is_valid := 1;
    DBMS_OUTPUT.PUT_LINE('Validation passed for season_id=' || TO_CHAR(p_season_id));
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      p_is_valid := 0;
      DBMS_OUTPUT.PUT_LINE('Validation failed: season not found for season_id=' || TO_CHAR(p_season_id));
    WHEN TOO_MANY_ROWS THEN
      p_is_valid := 1;
      DBMS_OUTPUT.PUT_LINE('Validation passed for season_id=' || TO_CHAR(p_season_id));
    WHEN OTHERS THEN
      p_is_valid := 0;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END validate_season;

  PROCEDURE print_season_summary(
    p_season_id IN IPL.MATCH.season_id%TYPE
  ) IS
    co_match_limit  CONSTANT PLS_INTEGER := 15; -- Bound output size
    co_winner_limit CONSTANT PLS_INTEGER := 5;  -- Bound output size

    lv_ok NUMBER;
    lv_match_rows  PLS_INTEGER := 0;
    lv_winner_rows PLS_INTEGER := 0;
  BEGIN
    validate_season(p_season_id => p_season_id, p_is_valid => lv_ok);

    IF lv_ok = 0 THEN
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- Season summary for season_id=' || TO_CHAR(p_season_id) || ' ---');

    DBMS_OUTPUT.PUT_LINE('Matches:');
    FOR rec IN (
      SELECT m.match_date,
             m.venue,
             t1.name AS team1_name,
             t2.name AS team2_name,
             tw.name AS winner_name
        FROM IPL.MATCH m
        INNER JOIN IPL.TEAM t1
          ON t1.team_id = m.team_1
        INNER JOIN IPL.TEAM t2
          ON t2.team_id = m.team_2
        LEFT OUTER JOIN IPL.TEAM tw
          ON tw.team_id = m.match_winner
       WHERE m.season_id = p_season_id
       ORDER BY m.match_date, m.match_id
    ) LOOP
      EXIT WHEN lv_match_rows >= co_match_limit;
      lv_match_rows := lv_match_rows + 1;

      DBMS_OUTPUT.PUT_LINE(
        TO_CHAR(rec.match_date, 'YYYY-MM-DD') || ' | ' || rec.venue || ' | ' || rec.team1_name || ' vs ' || rec.team2_name || ' | Winner: ' || NVL(rec.winner_name, 'NO RESULT')
      );
    END LOOP;

    IF lv_match_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No matches found for the given season.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Top winners:');
    FOR rec IN (
      SELECT t.name AS team_name,
             COUNT(*) AS wins
        FROM IPL.MATCH m
        INNER JOIN IPL.TEAM t
          ON t.team_id = m.match_winner
       WHERE m.season_id = p_season_id
         AND m.match_winner IS NOT NULL
       GROUP BY t.name
       ORDER BY COUNT(*) DESC, t.name
    ) LOOP
      EXIT WHEN lv_winner_rows >= co_winner_limit;
      lv_winner_rows := lv_winner_rows + 1;

      DBMS_OUTPUT.PUT_LINE(RPAD(rec.team_name, 30) || ' wins=' || TO_CHAR(rec.wins));
    END LOOP;

    IF lv_winner_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No winners found for the given season.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_season_summary;
END season_ops;
/

DECLARE
  lv_season_id IPL.MATCH.season_id%TYPE;
BEGIN
  -- Pick a commonly occurring season for a stable demo run
  SELECT m.season_id
    INTO lv_season_id
    FROM IPL.MATCH m
   GROUP BY m.season_id
   ORDER BY COUNT(*) DESC
   FETCH FIRST 1 ROWS ONLY;

  season_ops.print_season_summary(lv_season_id);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

