question:
Build a reusable reporting procedure for our baseball analytics team: given a season year, list up to 15 players who hit the most home runs in that year. Show player_id and total HR for that year, ordered by total HR descending (ties can be arbitrary). Print a clear header and one line per player.

Requirements:
Procedure Name: report_top_hr
Parameters:
p_year IN BASEBALL.BATTING.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Top HR hitters for year ' || p_year || ':');
DBMS_OUTPUT.PUT_LINE('PLAYER_ID=' || rec.player_id || ', TOTAL_HR=' || rec.total_hr);
DBMS_OUTPUT.PUT_LINE('No batting data found for the given year.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No batting data found for the given year.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_top_hr(
  p_year IN BASEBALL.BATTING.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_any_rows     PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top HR hitters for year ' || p_year || ':');

  FOR rec IN (
    SELECT b.player_id,
           SUM(b.hr) AS total_hr
      FROM BASEBALL.BATTING b
     WHERE b.year = p_year
     GROUP BY b.player_id
     ORDER BY SUM(b.hr) DESC, b.player_id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_any_rows := 1;
    DBMS_OUTPUT.PUT_LINE('PLAYER_ID=' || rec.player_id || ', TOTAL_HR=' || rec.total_hr);
  END LOOP;

  IF lv_any_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No batting data found for the given year.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_hr;
/

CREATE OR REPLACE FUNCTION get_player_hr(
  p_year      IN BASEBALL.BATTING.year%TYPE,
  p_player_id IN BASEBALL.BATTING.player_id%TYPE
) RETURN NUMBER IS
  lv_total_hr NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Inputs: YEAR=' || p_year || ', PLAYER_ID=' || p_player_id);

  SELECT SUM(b.hr)
    INTO lv_total_hr
    FROM BASEBALL.BATTING b
   WHERE b.year = p_year
     AND b.player_id = p_player_id;

  lv_total_hr := NVL(lv_total_hr, 0);
  DBMS_OUTPUT.PUT_LINE('Computed TOTAL_HR=' || lv_total_hr);

  RETURN lv_total_hr;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No batting rows found for that player/year; returning 0.');
    RETURN 0;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error; returning 0.');
    RETURN 0;
END get_player_hr;
/

