CREATE OR REPLACE PROCEDURE report_top_teams_by_wins(
  p_year IN BASEBALL.TEAM.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_team_cnt     NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Top teams by wins for year ' || p_year || ':');

  -- Correct single-row SELECT INTO: count the year rows first (avoids runtime failure)
  SELECT COUNT(*)
    INTO lv_team_cnt
    FROM BASEBALL.TEAM t
   WHERE t.year = p_year;

  IF lv_team_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No team data found for the given year.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT t.team_id,
           t.w AS wins
      FROM BASEBALL.TEAM t
     WHERE t.year = p_year
     ORDER BY t.w DESC, t.team_id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('TEAM_ID=' || rec.team_id || ', WINS=' || rec.wins);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No team data found for the given year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_teams_by_wins;
