CREATE OR REPLACE PROCEDURE report_latest_order_details(
  p_customer_id IN MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS.customer_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_latest_order_id MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS.order_id%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_customer_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Customer id is required.');
    RETURN;
  END IF;

  SELECT MAX(cco.order_id)
    INTO lv_latest_order_id
    FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS cco
   WHERE cco.customer_id = p_customer_id;

  IF lv_latest_order_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'LATEST_ORDER_ID=' || lv_latest_order_id || ' FOR CUSTOMER_ID=' || p_customer_id
  );

  FOR rec IN (
    SELECT pn.pizza_name
      FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS cco
      INNER JOIN MODERN_DATA.PIZZA_NAMES pn
        ON pn.pizza_id = cco.pizza_id
     WHERE cco.order_id = lv_latest_order_id
     ORDER BY pn.pizza_name
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE('PIZZA=' || rec.pizza_name);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No pizzas found for the latest order.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_latest_order_details;
