You're building a monthly CPI-U spot-check report for a data quality review. Create an anonymous PL/SQL block that prints the top CPI-U item/area combinations for a given year and period (e.g., 2020 and M01) and shows the CPI value as a number. Because the source VALUE is stored as text, make sure the block handles non-numeric values gracefully and does not crash. Limit the output to a small, readable list.

Requirements:
Procedure Name: Anonymous Block
Parameters:
None
Output:
DBMS_OUTPUT.PUT_LINE('CPI-U spot-check for ' || lv_year || ' ' || lv_period || ':');
DBMS_OUTPUT.PUT_LINE(RPAD('AREA_NAME', 35) || ' | ' || RPAD('ITEM_NAME', 45) || ' | ' || 'VALUE');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || RPAD('-', 45, '-') || '-+-' || RPAD('-', 10, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.area_name, 35) || ' | ' || RPAD(rec.item_name, 45) || ' | ' || TO_CHAR(rec.value_num));
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_year   BLS.CPI_U.year%TYPE   := '2020';
  lv_period BLS.CPI_U.period%TYPE := 'M01';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U spot-check for ' || lv_year || ' ' || lv_period || ':');
  DBMS_OUTPUT.PUT_LINE(RPAD('AREA_NAME', 35) || ' | ' || RPAD('ITEM_NAME', 45) || ' | ' || 'VALUE');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || RPAD('-', 45, '-') || '-+-' || RPAD('-', 10, '-'));

  FOR rec IN (
    SELECT c.area_name,
           c.item_name,
           TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) AS value_num
      FROM BLS.CPI_U c
     WHERE c.year = lv_year
       AND c.period = lv_period
       AND TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) IS NOT NULL
     ORDER BY c.area_name, c.item_name
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(RPAD(rec.area_name, 35) || ' | ' || RPAD(rec.item_name, 45) || ' | ' || TO_CHAR(rec.value_num));
  END LOOP;

  -- Force the "no rows" scenario into a predictable exception for training purposes
  IF SQL%ROWCOUNT = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

