CREATE OR REPLACE PACKAGE cpi_audit_pkg IS
  PROCEDURE print_cpi_spotcheck(
    p_year   IN BLS.CPI_U.year%TYPE,
    p_period IN BLS.CPI_U.period%TYPE
  );
END cpi_audit_pkg;
/

CREATE OR REPLACE PACKAGE BODY cpi_audit_pkg IS
  PROCEDURE print_cpi_spotcheck(
    p_year   IN BLS.CPI_U.year%TYPE,
    p_period IN BLS.CPI_U.period%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  BEGIN
    -- Basic input validation to avoid meaningless scans
    IF p_year IS NULL OR NOT REGEXP_LIKE(p_year, '^[0-9]{4}$') THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year.');
      RETURN;
    END IF;

    IF p_period IS NULL OR NOT REGEXP_LIKE(p_period, '^M[0-9]{2}$') THEN
      DBMS_OUTPUT.PUT_LINE('Invalid period.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('CPI-U spot-check for ' || p_year || ' ' || p_period || ':');
    DBMS_OUTPUT.PUT_LINE(RPAD('AREA_NAME', 35) || ' | ' || RPAD('ITEM_NAME', 45) || ' | ' || 'VALUE');
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || RPAD('-', 45, '-') || '-+-' || RPAD('-', 10, '-'));

    FOR rec IN (
      SELECT c.area_name,
             c.item_name,
             TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) AS value_num
        FROM BLS.CPI_U c
       WHERE c.year = p_year
         AND c.period = p_period
         AND TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) IS NOT NULL
       ORDER BY c.area_name, c.item_name
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(RPAD(rec.area_name, 35) || ' | ' || RPAD(rec.item_name, 45) || ' | ' || TO_CHAR(rec.value_num));
    END LOOP;

    IF SQL%ROWCOUNT = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_cpi_spotcheck;
END cpi_audit_pkg;
/

CREATE OR REPLACE PACKAGE cpi_audit_pkg IS
  PROCEDURE print_cpi_spotcheck(
    p_year   IN BLS.CPI_U.year%TYPE,
    p_period IN BLS.CPI_U.period%TYPE
  );

  FUNCTION get_cpi_percent_change(
    p_year        IN BLS.CPI_U.year%TYPE,
    p_area_name   IN BLS.CPI_U.area_name%TYPE,
    p_item_name   IN BLS.CPI_U.item_name%TYPE,
    p_period_from IN BLS.CPI_U.period%TYPE,
    p_period_to   IN BLS.CPI_U.period%TYPE
  ) RETURN BLS.CPI_U.value%TYPE;
END cpi_audit_pkg;
/

CREATE OR REPLACE PACKAGE BODY cpi_audit_pkg IS
  PROCEDURE print_cpi_spotcheck(
    p_year   IN BLS.CPI_U.year%TYPE,
    p_period IN BLS.CPI_U.period%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  BEGIN
    IF p_year IS NULL OR NOT REGEXP_LIKE(p_year, '^[0-9]{4}$') THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year.');
      RETURN;
    END IF;

    IF p_period IS NULL OR NOT REGEXP_LIKE(p_period, '^M[0-9]{2}$') THEN
      DBMS_OUTPUT.PUT_LINE('Invalid period.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('CPI-U spot-check for ' || p_year || ' ' || p_period || ':');
    DBMS_OUTPUT.PUT_LINE(RPAD('AREA_NAME', 35) || ' | ' || RPAD('ITEM_NAME', 45) || ' | ' || 'VALUE');
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || RPAD('-', 45, '-') || '-+-' || RPAD('-', 10, '-'));

    FOR rec IN (
      SELECT c.area_name,
             c.item_name,
             TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) AS value_num
        FROM BLS.CPI_U c
       WHERE c.year = p_year
         AND c.period = p_period
         AND TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) IS NOT NULL
       ORDER BY c.area_name, c.item_name
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(RPAD(rec.area_name, 35) || ' | ' || RPAD(rec.item_name, 45) || ' | ' || TO_CHAR(rec.value_num));
    END LOOP;

    IF SQL%ROWCOUNT = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_cpi_spotcheck;

  FUNCTION get_cpi_percent_change(
    p_year        IN BLS.CPI_U.year%TYPE,
    p_area_name   IN BLS.CPI_U.area_name%TYPE,
    p_item_name   IN BLS.CPI_U.item_name%TYPE,
    p_period_from IN BLS.CPI_U.period%TYPE,
    p_period_to   IN BLS.CPI_U.period%TYPE
  ) RETURN BLS.CPI_U.value%TYPE IS
    lv_from_val NUMBER;
    lv_to_val   NUMBER;
    lv_pct      NUMBER;
  BEGIN
    -- Fetch "from" value (single-row expected). Any duplicates will surface as TOO_MANY_ROWS.
    SELECT TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR)
      INTO lv_from_val
      FROM BLS.CPI_U c
     WHERE c.year = p_year
       AND c.period = p_period_from
       AND c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) IS NOT NULL;

    -- Fetch "to" value (single-row expected). Any duplicates will surface as TOO_MANY_ROWS.
    SELECT TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR)
      INTO lv_to_val
      FROM BLS.CPI_U c
     WHERE c.year = p_year
       AND c.period = p_period_to
       AND c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) IS NOT NULL;

    lv_pct := ROUND(((lv_to_val - lv_from_val) / lv_from_val) * 100, 4);

    RETURN TO_CHAR(lv_pct);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END get_cpi_percent_change;
END cpi_audit_pkg;
/

DECLARE
  lv_year        BLS.CPI_U.year%TYPE;
  lv_area_name   BLS.CPI_U.area_name%TYPE;
  lv_item_name   BLS.CPI_U.item_name%TYPE;
  lv_period_from BLS.CPI_U.period%TYPE;
  lv_period_to   BLS.CPI_U.period%TYPE;
  lv_result      BLS.CPI_U.value%TYPE;
BEGIN
  -- Pick a deterministic (year, area, item) that has at least two numeric months
  SELECT t.year, t.area_name, t.item_name, t.period_from, t.period_to
    INTO lv_year, lv_area_name, lv_item_name, lv_period_from, lv_period_to
    FROM (
          SELECT c.year,
                 c.area_name,
                 c.item_name,
                 MIN(c.period) AS period_from,
                 MAX(c.period) AS period_to,
                 COUNT(*) AS cnt
            FROM BLS.CPI_U c
           WHERE c.period LIKE 'M%'
             AND TO_NUMBER(c.value DEFAULT NULL ON CONVERSION ERROR) IS NOT NULL
           GROUP BY c.year, c.area_name, c.item_name
          HAVING COUNT(*) >= 2
           ORDER BY c.year, c.area_name, c.item_name
         ) t
   WHERE ROWNUM = 1;

  lv_result := cpi_audit_pkg.get_cpi_percent_change(
                 p_year        => lv_year,
                 p_area_name   => lv_area_name,
                 p_item_name   => lv_item_name,
                 p_period_from => lv_period_from,
                 p_period_to   => lv_period_to
               );

  DBMS_OUTPUT.PUT_LINE('Percent change: ' || lv_result);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

