  PROCEDURE print_growth_report(
    p_country_name IN  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE,
    p_year         IN  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE DEFAULT NULL
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;

    lv_birth_num  NUMBER;
    lv_death_num  NUMBER;
    lv_growth_num NUMBER;
    lv_direction  VARCHAR2(20);
  BEGIN
    IF p_country_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Country name is required.');
      RETURN;
    END IF;

    FOR r IN (
      SELECT b.country_name,
             b.year,
             b.crude_birth_rate,
             b.crude_death_rate,
             b.growth_rate
        FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
       WHERE b.country_name = p_country_name
         AND (p_year IS NULL OR b.year = p_year)
         AND ROWNUM <= co_report_limit
       ORDER BY b.year
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;

      -- Convert numeric-like strings to NUMBER for consistent comparisons.
      lv_birth_num  := to_num_or_null(r.crude_birth_rate);
      lv_death_num  := to_num_or_null(r.crude_death_rate);
      lv_growth_num := to_num_or_null(r.growth_rate);

      IF lv_growth_num IS NULL THEN
        lv_direction := 'UNKNOWN';
      ELSIF lv_growth_num > 0 THEN
        lv_direction := 'POSITIVE';
      ELSIF lv_growth_num < 0 THEN
        lv_direction := 'NEGATIVE';
      ELSE
        lv_direction := 'ZERO';
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'Country=' || r.country_name ||
        ', Year=' || r.year ||
        ', GrowthRateNum=' || NVL(TO_CHAR(lv_growth_num), 'NULL') ||
        ', GrowthDirection=' || lv_direction
      );

      -- Variables retained for potential future use.
      lv_birth_num := lv_birth_num;
      lv_death_num := lv_death_num;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the input criteria.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_growth_report;
END demo_report_pkg;
/

