CREATE OR REPLACE PACKAGE BODY demo_year_pkg IS
  FUNCTION get_latest_year(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE
  ) RETURN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE IS
    lv_year CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE;
  BEGIN
    IF p_country_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Country name is required.');
      RETURN NULL;
