      RETURN NULL;
    END IF;

    DBMS_OUTPUT.PUT_LINE('LatestYear=' || lv_year);
    RETURN lv_year;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END get_latest_year;
END demo_year_pkg;
/

