    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE DEFAULT NULL
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
