      SELECT a.country_name,
             a.year,
             a.total_fertility_rate
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
       WHERE a.country_name = p_country_name
         AND a.year = lv_effective_year
         AND ROWNUM <= co_report_limit
       ORDER BY a.year
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;

      lv_tfr_num := demo_report_pkg.to_num_or_null(r.total_fertility_rate);
