CREATE OR REPLACE PROCEDURE report_station_status(
  p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 10; -- Limit output for report readability

  lv_station_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_region_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;

  CURSOR c_status(p_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE) IS
    SELECT s.last_reported,
           s.num_bikes_available,
           s.num_docks_available
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
     WHERE s.station_id = p_id
     ORDER BY s.last_reported DESC;

  lv_last_reported SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.last_reported%TYPE;
  lv_bikes         SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
  lv_docks         SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_docks_available%TYPE;

  lv_rows_printed  PLS_INTEGER := 0;
BEGIN
  IF p_station_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Station id is required.');
    RETURN;
  END IF;

  SELECT si.station_id,
         si.name,
         r.name
    INTO lv_station_id,
         lv_station_name,
         lv_region_name
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
    LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
      ON r.region_id = si.region_id
   WHERE si.station_id = p_station_id;

  DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_id || ' - ' || lv_station_name);
  DBMS_OUTPUT.PUT_LINE('Region: ' || NVL(lv_region_name, 'UNKNOWN'));
  DBMS_OUTPUT.PUT_LINE('Most recent status snapshots (max rows = ' || co_report_limit || '):');

  OPEN c_status(lv_station_id);
  LOOP
    FETCH c_status INTO lv_last_reported, lv_bikes, lv_docks;
    EXIT WHEN c_status%NOTFOUND OR lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE('As of ' || lv_last_reported || ': bikes=' || lv_bikes || ', docks=' || lv_docks);
  END LOOP;
  CLOSE c_status;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No status rows found for this station.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_status;
/

