CREATE OR REPLACE PACKAGE BODY bike_dq_pkg IS
  PROCEDURE report_suspicious_roundtrips(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_total_suspicious NUMBER := 0;

    CURSOR c_suspicious(p_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE) IS
      SELECT t.trip_id,
             t.start_date,
             t.end_date,
             t.duration_sec
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          ON si.station_id = t.start_station_id
       WHERE t.start_station_id = p_id
         AND t.end_station_id = p_id
       ORDER BY t.start_date DESC;

    lv_printed PLS_INTEGER := 0;
  BEGIN
    IF p_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Suspicious round-trips (start_station_id=end_station_id) for station ' || p_station_id);

    SELECT COUNT(*)
      INTO lv_total_suspicious
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
     WHERE t.start_station_id = p_station_id
       AND t.end_station_id = p_station_id;

    DBMS_OUTPUT.PUT_LINE('Total suspicious trips for station: ' || lv_total_suspicious);
    DBMS_OUTPUT.PUT_LINE('Listing up to ' || co_report_limit || ' suspicious trip(s):');

    FOR r IN c_suspicious(p_station_id) LOOP
      EXIT WHEN lv_printed >= co_report_limit;
      lv_printed := lv_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        'Trip ' || r.trip_id || ': start=' || TO_CHAR(r.start_date, 'YYYY-MM-DD HH24:MI:SS') ||
        ', end=' || TO_CHAR(r.end_date, 'YYYY-MM-DD HH24:MI:SS') ||
        ', duration_sec=' || r.duration_sec
      );
    END LOOP;

    IF lv_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No suspicious trips found for this station.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_suspicious_roundtrips;
END bike_dq_pkg;
/

