    CURSOR c_suspicious(p_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE) IS
      SELECT t.trip_id,
             t.start_date,
             t.end_date,
             t.duration_sec
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          ON si.station_id = t.start_station_id
       WHERE t.start_station_id = p_id
         AND t.end_station_id = p_id
       ORDER BY t.start_date DESC;

    lv_printed PLS_INTEGER := 0;
  BEGIN
    IF p_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Suspicious round-trips (start_station_id=end_station_id) for station ' || p_station_id);

    SELECT COUNT(*)
      INTO lv_total_suspicious
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
     WHERE t.start_station_id = p_station_id
       AND t.end_station_id = p_station_id;

    DBMS_OUTPUT.PUT_LINE('Total suspicious trips for station: ' || lv_total_suspicious);
    DBMS_OUTPUT.PUT_LINE('Listing up to ' || co_report_limit || ' suspicious trip(s):');

    FOR r IN c_suspicious(p_station_id) LOOP
      EXIT WHEN lv_printed >= co_report_limit;
      lv_printed := lv_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        'Trip ' || r.trip_id || ': start=' || TO_CHAR(r.start_date, 'YYYY-MM-DD HH24:MI:SS') ||
        ', end=' || TO_CHAR(r.end_date, 'YYYY-MM-DD HH24:MI:SS') ||
        ', duration_sec=' || r.duration_sec
      );
    END LOOP;

    IF lv_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No suspicious trips found for this station.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_suspicious_roundtrips;

  PROCEDURE summarize_roundtrip_buckets(
    p_station_id      IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE,
    p_short_max_sec   IN NUMBER,
    p_medium_max_sec  IN NUMBER
  ) IS
    lv_short_cnt  NUMBER := 0;
    lv_medium_cnt NUMBER := 0;
    lv_long_cnt   NUMBER := 0;

    CURSOR c_durations(p_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE) IS
      SELECT t.duration_sec
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          ON si.station_id = t.start_station_id
       WHERE t.start_station_id = p_id
         AND t.end_station_id = p_id;

    lv_duration_txt SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.duration_sec%TYPE;
    lv_duration_num NUMBER;
  BEGIN
    IF p_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is required.');
      RETURN;
    END IF;

    IF p_short_max_sec IS NULL OR p_medium_max_sec IS NULL OR p_short_max_sec >= p_medium_max_sec THEN
      DBMS_OUTPUT.PUT_LINE('Invalid duration thresholds.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Round-trip duration buckets for station ' || p_station_id ||
      ' (max short=' || p_short_max_sec || ', max medium=' || p_medium_max_sec || ')'
    );

    OPEN c_durations(p_station_id);
    LOOP
      FETCH c_durations INTO lv_duration_txt;
      EXIT WHEN c_durations%NOTFOUND;

      lv_duration_num := TO_NUMBER(lv_duration_txt);

      IF lv_duration_num <= p_short_max_sec THEN
        lv_short_cnt := lv_short_cnt + 1;
      ELSIF lv_duration_num <= p_medium_max_sec THEN
        lv_medium_cnt := lv_medium_cnt + 1;
      ELSE
        lv_long_cnt := lv_long_cnt + 1;
      END IF;
    END LOOP;
    CLOSE c_durations;

    DBMS_OUTPUT.PUT_LINE('Bucket SHORT: ' || lv_short_cnt);
    DBMS_OUTPUT.PUT_LINE('Bucket MEDIUM: ' || lv_medium_cnt);
    DBMS_OUTPUT.PUT_LINE('Bucket LONG: ' || lv_long_cnt);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid duration thresholds.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END summarize_roundtrip_buckets;
END bike_dq_pkg;
/

