CREATE OR REPLACE PACKAGE wwe_card_quality_pkg IS
  PROCEDURE diagnose_card_data(
    p_card_id IN WWE.CARDS.ID%TYPE,
    p_issue_filter IN WWE.MATCHES.WIN_TYPE%TYPE DEFAULT 'ALL'
  );
END wwe_card_quality_pkg;
/

CREATE OR REPLACE PACKAGE BODY wwe_card_quality_pkg IS
  PROCEDURE diagnose_card_data(
    p_card_id IN WWE.CARDS.ID%TYPE,
    p_issue_filter IN WWE.MATCHES.WIN_TYPE%TYPE DEFAULT 'ALL'
  ) IS
    co_issue_limit CONSTANT NUMBER := 15; -- Keep diagnostics bounded for analyst review
    lv_filter VARCHAR2(20);
    lv_issue_count NUMBER := 0;
    lv_existing_card_id WWE.CARDS.ID%TYPE;
    lv_probe_card_id WWE.CARDS.ID%TYPE;

    CURSOR c_match_diagnostics(cp_card_id WWE.MATCHES.CARD_ID%TYPE) IS
      SELECT limited_issues.match_id,
             limited_issues.winner_id,
             limited_issues.winner_exists,
             limited_issues.loser_id,
             limited_issues.loser_exists,
             limited_issues.match_type_id,
             limited_issues.match_type_exists,
             limited_issues.title_id,
             limited_issues.title_exists
        FROM (
              SELECT m.id AS match_id,
                     m.winner_id AS winner_id,
                     winner_w.id AS winner_exists,
                     m.loser_id AS loser_id,
                     loser_w.id AS loser_exists,
                     m.match_type_id AS match_type_id,
                     mt.id AS match_type_exists,
                     m.title_id AS title_id,
                     b.id AS title_exists
                FROM WWE.MATCHES m
                LEFT OUTER JOIN WWE.WRESTLERS winner_w
                  ON TO_CHAR(winner_w.id) = m.winner_id
                LEFT OUTER JOIN WWE.WRESTLERS loser_w
                  ON TO_CHAR(loser_w.id) = m.loser_id
                LEFT OUTER JOIN WWE.MATCH_TYPES mt
                  ON TO_CHAR(mt.id) = m.match_type_id
                LEFT OUTER JOIN WWE.BELTS b
                  ON TO_CHAR(b.id) = m.title_id
               WHERE m.card_id = cp_card_id
               ORDER BY m.id ASC
             ) limited_issues
       WHERE ROWNUM <= co_issue_limit;
  BEGIN
    lv_filter := UPPER(NVL(p_issue_filter, 'ALL'));

    IF p_card_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Card id is required.');
    ELSIF p_card_id = 0 THEN
      SELECT duplicate_probe.id
        INTO lv_probe_card_id
        FROM (
              SELECT c.id AS id FROM WWE.CARDS c WHERE ROWNUM = 1
              UNION ALL
              SELECT c.id AS id FROM WWE.CARDS c WHERE ROWNUM = 1
             ) duplicate_probe;
      DBMS_OUTPUT.PUT_LINE('Duplicate diagnostic probe completed.');
    ELSIF lv_filter NOT IN ('ALL', 'WINNER', 'LOSER', 'TYPE', 'TITLE') THEN
      DBMS_OUTPUT.PUT_LINE('Unsupported issue filter.');
    ELSE
      SELECT c.id
        INTO lv_existing_card_id
        FROM WWE.CARDS c
       WHERE c.id = p_card_id;

      DBMS_OUTPUT.PUT_LINE('Diagnostic scan for card ' || p_card_id || ' using filter ' || lv_filter || '.');

      FOR rec IN c_match_diagnostics(p_card_id) LOOP
        IF (lv_filter IN ('ALL', 'WINNER')) AND rec.winner_id IS NOT NULL AND rec.winner_exists IS NULL THEN
          lv_issue_count := lv_issue_count + 1;
          DBMS_OUTPUT.PUT_LINE('Issue ' || rec.match_id || ': winner id ' || rec.winner_id || ' does not resolve to WWE.WRESTLERS.');
        ELSIF (lv_filter IN ('ALL', 'LOSER')) AND rec.loser_id IS NOT NULL AND rec.loser_exists IS NULL THEN
          lv_issue_count := lv_issue_count + 1;
          DBMS_OUTPUT.PUT_LINE('Issue ' || rec.match_id || ': loser id ' || rec.loser_id || ' does not resolve to WWE.WRESTLERS.');
        ELSIF (lv_filter IN ('ALL', 'TYPE')) AND rec.match_type_id IS NOT NULL AND rec.match_type_exists IS NULL THEN
          lv_issue_count := lv_issue_count + 1;
          DBMS_OUTPUT.PUT_LINE('Issue ' || rec.match_id || ': match type id ' || rec.match_type_id || ' does not resolve to WWE.MATCH_TYPES.');
        ELSIF (lv_filter IN ('ALL', 'TITLE')) AND rec.title_id IS NOT NULL AND rec.title_exists IS NULL THEN
          lv_issue_count := lv_issue_count + 1;
          DBMS_OUTPUT.PUT_LINE('Issue ' || rec.match_id || ': title id ' || rec.title_id || ' does not resolve to WWE.BELTS.');
        END IF;
      END LOOP;

      IF lv_issue_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No data quality issues found for this card and filter.');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Total issues found: ' || lv_issue_count);
      END IF;
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No diagnostic data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple diagnostic rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid diagnostic input.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected diagnostic error.');
  END diagnose_card_data;
END wwe_card_quality_pkg;
/

