question:
Using the hub-state focus established in the first report, find the busiest state and inspect driver performance for that state. The team wants a row-by-row review of driver modal and type combinations, with a warning when average trip distance is high and a confirmation when it is in the normal operating range.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Driver performance review for state=' || lv_target_state);
DBMS_OUTPUT.PUT_LINE('Long-distance driver pattern: ' || lr_driver.driver_modal || '/' || lr_driver.driver_type);
DBMS_OUTPUT.PUT_LINE('Standard-distance driver pattern: ' || lr_driver.driver_modal || '/' || lr_driver.driver_type);
DBMS_OUTPUT.PUT_LINE('Driver Modal=' || lr_driver.driver_modal || ', Driver Type=' || lr_driver.driver_type || ', Deliveries=' || lr_driver.delivery_count || ', Avg Distance Meters=' || lr_driver.avg_distance_meters || ', Net Delivery Margin=' || lr_driver.net_delivery_margin);
DBMS_OUTPUT.PUT_LINE('No driver performance rows matched the selected state.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT NUMBER := 15; -- Keep the driver review readable
  lv_target_state DELIVERY_CENTER.HUBS.hub_state%TYPE;
  lv_rows         NUMBER := 0;

  CURSOR cur_driver_perf(p_state DELIVERY_CENTER.HUBS.hub_state%TYPE) IS
    SELECT driver_rows.driver_modal,
           driver_rows.driver_type,
           driver_rows.delivery_count,
           driver_rows.avg_distance_meters,
           driver_rows.net_delivery_margin
      FROM (
            SELECT dr.driver_modal,
                   dr.driver_type,
                   COUNT(d.delivery_id) AS delivery_count,
                   ROUND(AVG(d.delivery_distance_meters), 2) AS avg_distance_meters,
                   ROUND(SUM(o.order_delivery_fee - o.order_delivery_cost), 2) AS net_delivery_margin
              FROM DELIVERY_CENTER.HUBS h
              INNER JOIN DELIVERY_CENTER.STORES s
                ON s.hub_id = h.hub_id
              INNER JOIN DELIVERY_CENTER.ORDERS o
                ON o.store_id = s.store_id
              INNER JOIN DELIVERY_CENTER.DELIVERIES d
                ON d.delivery_order_id = o.delivery_order_id
              INNER JOIN DELIVERY_CENTER.DRIVERS dr
                ON dr.driver_id = d.driver_id
             WHERE h.hub_state = p_state
               AND o.order_status = 'FINISHED'
               AND d.delivery_status = 'DELIVERED'
             GROUP BY dr.driver_modal,
                      dr.driver_type
             ORDER BY COUNT(d.delivery_id) DESC
           ) driver_rows
     WHERE ROWNUM <= co_report_limit;

  lr_driver cur_driver_perf%ROWTYPE;
BEGIN
  SELECT state_rows.hub_state
    INTO lv_target_state
    FROM (
          SELECT h.hub_state,
                 COUNT(o.order_id) AS order_count
            FROM DELIVERY_CENTER.HUBS h
            INNER JOIN DELIVERY_CENTER.STORES s
              ON s.hub_id = h.hub_id
            INNER JOIN DELIVERY_CENTER.ORDERS o
              ON o.store_id = s.store_id
           WHERE o.order_status = 'FINISHED'
           GROUP BY h.hub_state
           ORDER BY COUNT(o.order_id) DESC
         ) state_rows
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Driver performance review for state=' || lv_target_state);

  OPEN cur_driver_perf(lv_target_state);
  LOOP
    FETCH cur_driver_perf INTO lr_driver;
    EXIT WHEN cur_driver_perf%NOTFOUND;

    lv_rows := lv_rows + 1;

    IF lr_driver.avg_distance_meters > 5000 THEN
      DBMS_OUTPUT.PUT_LINE('Long-distance driver pattern: ' || lr_driver.driver_modal || '/' || lr_driver.driver_type);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Standard-distance driver pattern: ' || lr_driver.driver_modal || '/' || lr_driver.driver_type);
    END IF;

    DBMS_OUTPUT.PUT_LINE('Driver Modal=' || lr_driver.driver_modal || ', Driver Type=' || lr_driver.driver_type || ', Deliveries=' || lr_driver.delivery_count || ', Avg Distance Meters=' || lr_driver.avg_distance_meters || ', Net Delivery Margin=' || lr_driver.net_delivery_margin);
  END LOOP;
  CLOSE cur_driver_perf;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No driver performance rows matched the selected state.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_driver_perf%ISOPEN THEN
      CLOSE cur_driver_perf;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_driver_perf%ISOPEN THEN
      CLOSE cur_driver_perf;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF cur_driver_perf%ISOPEN THEN
      CLOSE cur_driver_perf;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

