question:
Now take the same operational slice and add a payment-control review. Find finished orders whose payment record is missing, unpaid, or does not match the order amount, and print each exception with enough channel context for finance and operations to triage it.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Payment exception review for finished orders');
DBMS_OUTPUT.PUT_LINE('Missing payment record for order ' || lr_payment.order_id);
DBMS_OUTPUT.PUT_LINE('Payment not settled for order ' || lr_payment.order_id);
DBMS_OUTPUT.PUT_LINE('Payment amount mismatch for order ' || lr_payment.order_id);
DBMS_OUTPUT.PUT_LINE('Order Id=' || lr_payment.order_id || ', Channel=' || lr_payment.channel_name || ', Order Amount=' || lr_payment.order_amount || ', Payment Amount=' || lr_payment.payment_amount || ', Payment Status=' || lr_payment.payment_status || ', Difference=' || lr_payment.amount_difference);
DBMS_OUTPUT.PUT_LINE('No payment exceptions were found in the limited review.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT NUMBER := 15; -- Finance review is capped for screen readability
  lv_rows         NUMBER := 0;

  CURSOR cur_payment_exceptions IS
    SELECT payment_rows.order_id,
           payment_rows.channel_name,
           payment_rows.order_amount,
           payment_rows.payment_amount,
           payment_rows.payment_status,
           payment_rows.amount_difference,
           payment_rows.has_payment_record
      FROM (
            SELECT o.order_id,
                   c.channel_name,
                   o.order_amount,
                   NVL(p.payment_amount, 0) AS payment_amount,
                   NVL(p.payment_status, 'MISSING') AS payment_status,
                   ABS(o.order_amount - NVL(p.payment_amount, 0)) AS amount_difference,
                   CASE
                     WHEN p.payment_order_id IS NULL THEN 'N'
                     ELSE 'Y'
                   END AS has_payment_record
              FROM DELIVERY_CENTER.ORDERS o
              INNER JOIN DELIVERY_CENTER.CHANNELS c
                ON c.channel_id = o.channel_id
              LEFT OUTER JOIN DELIVERY_CENTER.PAYMENTS p
                ON p.payment_order_id = o.payment_order_id
             WHERE o.order_status = 'FINISHED'
               AND (p.payment_order_id IS NULL
                    OR p.payment_status <> 'PAID'
                    OR ABS(o.order_amount - NVL(p.payment_amount, 0)) > 0)
             ORDER BY ABS(o.order_amount - NVL(p.payment_amount, 0)) DESC,
                      o.order_id
           ) payment_rows
     WHERE ROWNUM <= co_report_limit;

  lr_payment cur_payment_exceptions%ROWTYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Payment exception review for finished orders');

  OPEN cur_payment_exceptions;
  LOOP
    FETCH cur_payment_exceptions INTO lr_payment;
    EXIT WHEN cur_payment_exceptions%NOTFOUND;

    lv_rows := lv_rows + 1;

    IF lr_payment.has_payment_record = 'N' THEN
      DBMS_OUTPUT.PUT_LINE('Missing payment record for order ' || lr_payment.order_id);
    ELSIF lr_payment.payment_status <> 'PAID' THEN
      DBMS_OUTPUT.PUT_LINE('Payment not settled for order ' || lr_payment.order_id);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Payment amount mismatch for order ' || lr_payment.order_id);
    END IF;

