question:
Tie the prior operational, driver, and finance checks together into a final dispatch-risk view by hub and store segment. The goal is to review up to fifteen hub/segment groups, score operational risk from delivery and payment issues, and print an action recommendation for each group.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Integrated dispatch risk review by hub and store segment');
DBMS_OUTPUT.PUT_LINE('Immediate review required for hub ' || lr_risk.hub_name || ' / segment ' || lr_risk.store_segment);
DBMS_OUTPUT.PUT_LINE('Monitor hub ' || lr_risk.hub_name || ' / segment ' || lr_risk.store_segment);
DBMS_OUTPUT.PUT_LINE('Stable hub ' || lr_risk.hub_name || ' / segment ' || lr_risk.store_segment);
DBMS_OUTPUT.PUT_LINE('Hub=' || lr_risk.hub_name || ', State=' || lr_risk.hub_state || ', Segment=' || lr_risk.store_segment || ', Orders=' || lr_risk.order_count || ', Drivers=' || lr_risk.driver_count || ', Risk Score=' || lr_risk.risk_score || ', Avg Cycle Time=' || lr_risk.avg_cycle_time || ', Last Order=' || TO_CHAR(lr_risk.last_order_moment, 'YYYY-MM-DD HH24:MI'));
DBMS_OUTPUT.PUT_LINE('No integrated dispatch risk rows were available.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT NUMBER := 15; -- Final operational view remains concise for review meetings
  lv_rows         NUMBER := 0;

  CURSOR cur_dispatch_risk IS
    SELECT risk_rows.hub_name,
           risk_rows.hub_state,
           risk_rows.store_segment,
           risk_rows.order_count,
           risk_rows.driver_count,
           risk_rows.risk_score,
           risk_rows.avg_cycle_time,
           risk_rows.last_order_moment
      FROM (
            SELECT h.hub_name,
                   h.hub_state,
                   s.store_segment,
                   COUNT(o.order_id) AS order_count,
                   COUNT(DISTINCT dr.driver_id) AS driver_count,
                   SUM(CASE
                         WHEN d.delivery_status <> 'DELIVERED' THEN 2
                         WHEN NVL(p.payment_status, 'MISSING') <> 'PAID' THEN 2
                         ELSE 0
                       END) AS risk_score,
                   ROUND(AVG(o.order_metric_cycle_time), 2) AS avg_cycle_time,
                   MAX(o.order_moment_created) AS last_order_moment
              FROM DELIVERY_CENTER.HUBS h
              INNER JOIN DELIVERY_CENTER.STORES s
                ON s.hub_id = h.hub_id
              INNER JOIN DELIVERY_CENTER.ORDERS o
                ON o.store_id = s.store_id
              LEFT OUTER JOIN DELIVERY_CENTER.DELIVERIES d
                ON d.delivery_order_id = o.delivery_order_id
              LEFT OUTER JOIN DELIVERY_CENTER.DRIVERS dr
                ON dr.driver_id = d.driver_id
              LEFT OUTER JOIN DELIVERY_CENTER.PAYMENTS p
                ON p.payment_order_id = o.payment_order_id
             WHERE o.order_status = 'FINISHED'
             GROUP BY h.hub_name,
                      h.hub_state,
                      s.store_segment
             HAVING COUNT(o.order_id) > 0
             ORDER BY SUM(CASE
                            WHEN d.delivery_status <> 'DELIVERED' THEN 2
                            WHEN NVL(p.payment_status, 'MISSING') <> 'PAID' THEN 2
                            ELSE 0
                          END) DESC,
                      COUNT(o.order_id) DESC
           ) risk_rows
     WHERE ROWNUM <= co_report_limit;

  lr_risk cur_dispatch_risk%ROWTYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Integrated dispatch risk review by hub and store segment');

  OPEN cur_dispatch_risk;
  LOOP
    FETCH cur_dispatch_risk INTO lr_risk;
    EXIT WHEN cur_dispatch_risk%NOTFOUND;

    lv_rows := lv_rows + 1;

    IF lr_risk.risk_score >= 10 THEN
      DBMS_OUTPUT.PUT_LINE('Immediate review required for hub ' || lr_risk.hub_name || ' / segment ' || lr_risk.store_segment);
    ELSIF lr_risk.risk_score >= 4 THEN
      DBMS_OUTPUT.PUT_LINE('Monitor hub ' || lr_risk.hub_name || ' / segment ' || lr_risk.store_segment);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Stable hub ' || lr_risk.hub_name || ' / segment ' || lr_risk.store_segment);
    END IF;

    DBMS_OUTPUT.PUT_LINE('Hub=' || lr_risk.hub_name || ', State=' || lr_risk.hub_state || ', Segment=' || lr_risk.store_segment || ', Orders=' || lr_risk.order_count || ', Drivers=' || lr_risk.driver_count || ', Risk Score=' || lr_risk.risk_score || ', Avg Cycle Time=' || lr_risk.avg_cycle_time || ', Last Order=' || TO_CHAR(lr_risk.last_order_moment, 'YYYY-MM-DD HH24:MI'));
  END LOOP;
  CLOSE cur_dispatch_risk;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No integrated dispatch risk rows were available.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_dispatch_risk%ISOPEN THEN
      CLOSE cur_dispatch_risk;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_dispatch_risk%ISOPEN THEN
      CLOSE cur_dispatch_risk;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF cur_dispatch_risk%ISOPEN THEN
      CLOSE cur_dispatch_risk;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

