DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year BASEBALL.BATTING.year%TYPE := NULL; -- Input year (NULL defaults to 2010)
BEGIN
  IF lv_year IS NULL THEN
    lv_year := 2010;
  END IF;

  -- Ensure the year has batting data before printing a report
  DECLARE
    lv_cnt NUMBER;
  BEGIN
    SELECT COUNT(*)
      INTO lv_cnt
      FROM BASEBALL.BATTING b
     WHERE b.year = lv_year;

    IF lv_cnt = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;
  END;

  FOR rec IN (
    SELECT (p.name_first || ' ' || p.name_last) AS name_full,
           b.hr AS hr
      FROM BASEBALL.BATTING b
      INNER JOIN BASEBALL.PLAYER p
        ON p.player_id = b.player_id
     WHERE b.year = lv_year
     ORDER BY b.hr DESC, p.name_last, p.name_first
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('Player: ' || rec.name_full || ' | HR: ' || rec.hr);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No batting data found for year ' || lv_year || '.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

