DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year   BASEBALL.TEAM.year%TYPE := 2010;
  lv_league BASEBALL.TEAM.league_id%TYPE := NULL;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF lv_league IS NULL THEN
    lv_league := 'AL';
  END IF;

  FOR rec IN (
    SELECT t.team_id AS team_id,
           t.w AS w,
           t.l AS l,
           CASE
             WHEN (t.w + t.l) = 0 THEN
               0
             ELSE
               ROUND(t.w / (t.w + t.l), 3)
           END AS pct
      FROM BASEBALL.TEAM t
     WHERE t.year = lv_year
       AND t.league_id = lv_league
     ORDER BY pct DESC, t.team_id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
