  FOR rec IN (
    SELECT report_rows.name, report_rows.version, report_rows.score, report_rows.nb_model, report_rows.nb_feature, report_rows.scored_model_count, report_rows.avg_test_score, report_rows.best_test_score
      FROM (SELECT s.name, s.version, s.score, s.nb_model, s.nb_feature, COUNT(ms.model) AS scored_model_count, AVG(ms.test_score) AS avg_test_score, MAX(ms.test_score) AS best_test_score
              FROM STACKING.SOLUTION s LEFT OUTER JOIN STACKING.MODEL_SCORE ms ON ms.name = s.name AND ms.version = s.version
             GROUP BY s.name, s.version, s.score, s.nb_model, s.nb_feature ORDER BY s.score DESC, s.name, s.version) report_rows
     WHERE ROWNUM <= co_report_limit) LOOP
