question:
Now take the solution versions identified in the summary and build a reusable routine that drills into the model-level score details for one solution. It should validate the requested solution/version, print a compact model diagnostic, and clearly call out model rows that are missing test scores.

Requirements:
Procedure Name: report_solution_models
Parameters: p_solution_name IN STACKING.SOLUTION.NAME%TYPE
p_version IN STACKING.SOLUTION.VERSION%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Solution name and version are required.');
DBMS_OUTPUT.PUT_LINE('Model diagnostic for solution ' || p_solution_name || ' version ' || TO_CHAR(p_version) || ' score ' || TO_CHAR(lv_solution_score));
DBMS_OUTPUT.PUT_LINE('Step ' || TO_CHAR(rec.step) || ' model ' || rec.l1_model || ' is missing a test score.');
DBMS_OUTPUT.PUT_LINE('Step ' || TO_CHAR(rec.step) || ' model ' || rec.l1_model || ' train=' || TO_CHAR(rec.train_score) || ', test=' || TO_CHAR(rec.test_score) || ', importance=' || TO_CHAR(rec.importance));
DBMS_OUTPUT.PUT_LINE('No model rows were found for the solution.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No matching solution was found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple matching solution rows were found.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_solution_models(
  p_solution_name IN STACKING.SOLUTION.NAME%TYPE,
  p_version       IN STACKING.SOLUTION.VERSION%TYPE
) IS
  co_report_limit  CONSTANT PLS_INTEGER := 15; -- Limit model-detail output for reviewability
  lv_solution_score STACKING.SOLUTION.SCORE%TYPE;
  lv_row_count      NUMBER := 0;
BEGIN
  IF p_solution_name IS NULL OR p_version IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Solution name and version are required.');
    RETURN;
  END IF;

  IF p_version = 0 THEN
    -- Version zero intentionally checks whether the solution name is ambiguous across versions.
    SELECT s.score
      INTO lv_solution_score
      FROM STACKING.SOLUTION s
     WHERE s.name = p_solution_name;
  ELSE
    SELECT s.score
      INTO lv_solution_score
      FROM STACKING.SOLUTION s
     WHERE s.name = p_solution_name
       AND s.version = p_version;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Model diagnostic for solution ' || p_solution_name || ' version ' || TO_CHAR(p_version) || ' score ' || TO_CHAR(lv_solution_score));

  FOR rec IN (
    SELECT detail_rows.step,
           detail_rows.l1_model,
           detail_rows.train_score,
           detail_rows.test_score,
           detail_rows.importance
      FROM (
            SELECT m.step,
                   m.l1_model,
                   ms.train_score,
                   ms.test_score,
                   mi.importance
              FROM STACKING.MODEL m
              LEFT OUTER JOIN STACKING.MODEL_SCORE ms
                ON ms.name = m.name
               AND ms.version = m.version
               AND ms.step = m.step
               AND ms.model = m.l1_model
              LEFT OUTER JOIN STACKING.MODEL_IMPORTANCE mi
                ON mi.name = m.name
               AND mi.version = m.version
               AND mi.step = m.step
               AND mi.model = m.l1_model
             WHERE m.name = p_solution_name
               AND m.version = p_version
             ORDER BY m.step,
                      m.l1_model
           ) detail_rows
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_row_count := lv_row_count + 1;

    IF rec.test_score IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Step ' || TO_CHAR(rec.step) || ' model ' || rec.l1_model || ' is missing a test score.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Step ' || TO_CHAR(rec.step) || ' model ' || rec.l1_model || ' train=' || TO_CHAR(rec.train_score) || ', test=' || TO_CHAR(rec.test_score) || ', importance=' || TO_CHAR(rec.importance));
    END IF;
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No model rows were found for the solution.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching solution was found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple matching solution rows were found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_solution_models;
/

