question:
Using the same solution/model data from the previous steps, add a debugging-oriented diagnostic package for root-cause analysis. The package should help explain why a solution may look risky by identifying model rows with large train-vs-test gaps, missing test scores, or missing model importance values.

Requirements:
Procedure Name: stacking_diagnostics_pkg.diagnose_score_gap
Parameters: p_solution_name IN STACKING.SOLUTION.NAME%TYPE
p_version IN STACKING.SOLUTION.VERSION%TYPE
p_gap_threshold IN STACKING.MODEL_SCORE.TEST_SCORE%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Solution name and version are required for gap diagnosis.');
DBMS_OUTPUT.PUT_LINE('Gap threshold must be zero or greater.');
DBMS_OUTPUT.PUT_LINE('Score gap diagnosis for solution ' || p_solution_name || ' version ' || TO_CHAR(p_version) || ' score ' || TO_CHAR(lv_solution_score));
DBMS_OUTPUT.PUT_LINE('Finding: step=' || TO_CHAR(rec.step) || ', model=' || rec.model || ', root_cause=' || rec.root_cause || ', train=' || TO_CHAR(rec.train_score) || ', test=' || TO_CHAR(rec.test_score) || ', gap=' || TO_CHAR(rec.score_gap) || ', importance=' || TO_CHAR(rec.model_importance));
DBMS_OUTPUT.PUT_LINE('Model ' || rec.model || ' is within the configured threshold.');
DBMS_OUTPUT.PUT_LINE('No score gap findings were detected.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No matching solution was found for score gap diagnosis.'
WHEN TOO_MANY_ROWS THEN: 'Multiple matching solution rows were found for score gap diagnosis.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE stacking_diagnostics_pkg AS
  PROCEDURE diagnose_score_gap(
    p_solution_name  IN STACKING.SOLUTION.NAME%TYPE,
    p_version        IN STACKING.SOLUTION.VERSION%TYPE,
    p_gap_threshold  IN STACKING.MODEL_SCORE.TEST_SCORE%TYPE DEFAULT 0
  );
END stacking_diagnostics_pkg;
/

CREATE OR REPLACE PACKAGE BODY stacking_diagnostics_pkg AS
  PROCEDURE diagnose_score_gap(
    p_solution_name  IN STACKING.SOLUTION.NAME%TYPE,
    p_version        IN STACKING.SOLUTION.VERSION%TYPE,
    p_gap_threshold  IN STACKING.MODEL_SCORE.TEST_SCORE%TYPE
  ) IS
    co_report_limit    CONSTANT PLS_INTEGER := 15; -- Keep root-cause output concise for incident triage
    lv_solution_score  STACKING.SOLUTION.SCORE%TYPE;
    lv_findings        NUMBER := 0;
  BEGIN
    IF p_solution_name IS NULL OR p_version IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Solution name and version are required for gap diagnosis.');
      RETURN;
    END IF;

    IF p_gap_threshold IS NULL OR p_gap_threshold < 0 THEN
      DBMS_OUTPUT.PUT_LINE('Gap threshold must be zero or greater.');
      RETURN;
    END IF;

    IF p_version = 0 THEN
      -- Version zero is reserved for ambiguity checks across all versions of a solution.
      SELECT s.score
        INTO lv_solution_score
        FROM STACKING.SOLUTION s
       WHERE s.name = p_solution_name;
    ELSE
      SELECT s.score
        INTO lv_solution_score
        FROM STACKING.SOLUTION s
       WHERE s.name = p_solution_name
         AND s.version = p_version;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Score gap diagnosis for solution ' || p_solution_name || ' version ' || TO_CHAR(p_version) || ' score ' || TO_CHAR(lv_solution_score));

    FOR rec IN (
      SELECT ranked_rows.step,
             ranked_rows.model,
             ranked_rows.train_score,
             ranked_rows.test_score,
             ranked_rows.score_gap,
             ranked_rows.model_importance,
             ranked_rows.root_cause
        FROM (
              SELECT ms.step,
                     ms.model,
                     ms.train_score,
                     ms.test_score,
                     ABS(NVL(ms.train_score, 0) - NVL(ms.test_score, 0)) AS score_gap,
                     mi.importance AS model_importance,
                     CASE
                       WHEN ms.test_score IS NULL THEN 'MISSING_TEST_SCORE'
                       WHEN ABS(NVL(ms.train_score, 0) - NVL(ms.test_score, 0)) > p_gap_threshold THEN 'TRAIN_TEST_GAP'
                       WHEN mi.importance IS NULL THEN 'MISSING_MODEL_IMPORTANCE'
                       ELSE 'OK'
                     END AS root_cause
                FROM STACKING.MODEL_SCORE ms
                LEFT OUTER JOIN STACKING.MODEL_IMPORTANCE mi
                  ON mi.name = ms.name
                 AND mi.version = ms.version
                 AND mi.step = ms.step
                 AND mi.model = ms.model
               WHERE ms.name = p_solution_name
                 AND ms.version = p_version
               ORDER BY ABS(NVL(ms.train_score, 0) - NVL(ms.test_score, 0)) DESC,
                        ms.step,
                        ms.model
             ) ranked_rows
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      IF rec.root_cause <> 'OK' THEN
        lv_findings := lv_findings + 1;
        DBMS_OUTPUT.PUT_LINE('Finding: step=' || TO_CHAR(rec.step) || ', model=' || rec.model || ', root_cause=' || rec.root_cause || ', train=' || TO_CHAR(rec.train_score) || ', test=' || TO_CHAR(rec.test_score) || ', gap=' || TO_CHAR(rec.score_gap) || ', importance=' || TO_CHAR(rec.model_importance));
      ELSE
        DBMS_OUTPUT.PUT_LINE('Model ' || rec.model || ' is within the configured threshold.');
      END IF;
    END LOOP;

    IF lv_findings = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No score gap findings were detected.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No matching solution was found for score gap diagnosis.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple matching solution rows were found for score gap diagnosis.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END diagnose_score_gap;
