CREATE OR REPLACE FUNCTION get_patient_for_encounter(
  p_encounter_id IN SYNTHEA.ENCOUNTERS.id%TYPE
) RETURN SYNTHEA.ENCOUNTERS.patient%TYPE
IS
  lv_patient_id SYNTHEA.ENCOUNTERS.patient%TYPE;
BEGIN
  IF p_encounter_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Encounter ID is NULL.');
    RETURN NULL;
  END IF;

