    INTO lv_patient_id
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.id = p_encounter_id;

  DBMS_OUTPUT.PUT_LINE('Encounter ' || p_encounter_id || ' belongs to patient ' || lv_patient_id || '.');
  RETURN lv_patient_id;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END get_patient_for_encounter;
