  lv_member_id   BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE;
  lv_net_quantity NUMBER := 0;
BEGIN
  SELECT member_id
    INTO lv_member_id
    FROM (
      SELECT t.member_id
        FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
       WHERE t.member_id IS NOT NULL
       GROUP BY t.member_id
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Reviewing member: ' || lv_member_id);

  FOR rec IN (
    SELECT *
      FROM (
        SELECT t.txn_id,
               t.txn_type,
               t.quantity
          FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
         WHERE t.member_id = lv_member_id
         ORDER BY t.txn_id
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    IF UPPER(rec.txn_type) = 'BUY' THEN
      lv_net_quantity := lv_net_quantity + rec.quantity;
      DBMS_OUTPUT.PUT_LINE('Included BUY txn ' || rec.txn_id || ' | Quantity: ' || rec.quantity || ' | Running Net: ' || lv_net_quantity);
    ELSIF UPPER(rec.txn_type) = 'SELL' THEN
      lv_net_quantity := lv_net_quantity - rec.quantity;
      DBMS_OUTPUT.PUT_LINE('Included SELL txn ' || rec.txn_id || ' | Quantity: ' || rec.quantity || ' | Running Net: ' || lv_net_quantity);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Ignored txn ' || rec.txn_id || ' | Type: ' || rec.txn_type);
    END IF;
  END LOOP;

  IF lv_net_quantity > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Net position status: LONG | Net Quantity: ' || lv_net_quantity);
  ELSIF lv_net_quantity < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Net position status: SHORT | Net Quantity: ' || lv_net_quantity);
