DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for market price review
  lv_rows         PLS_INTEGER := 0;
BEGIN
  FOR rec IN (
    WITH latest_dates AS (
      SELECT p.ticker,
             MAX(p.market_date) AS max_market_date
        FROM BANK_SALES_TRADING.BITCOIN_PRICES p
       GROUP BY p.ticker
    )
    SELECT *
      FROM (
        SELECT p.ticker,
               p.market_date,
               p.price,
               p.open AS open_price
          FROM BANK_SALES_TRADING.BITCOIN_PRICES p
          INNER JOIN latest_dates ld
            ON ld.ticker = p.ticker
           AND ld.max_market_date = p.market_date
         WHERE EXISTS (
               SELECT 1
                 FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
                WHERE t.ticker = p.ticker
         )
         ORDER BY p.ticker
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows := lv_rows + 1;

    IF rec.price > rec.open_price THEN
      DBMS_OUTPUT.PUT_LINE('Ticker above open: ' || rec.ticker || ' | Market Date: ' || rec.market_date || ' | Price: ' || rec.price || ' | Open: ' || rec.open_price);
    ELSIF rec.price < rec.open_price THEN
      DBMS_OUTPUT.PUT_LINE('Ticker below open: ' || rec.ticker || ' | Market Date: ' || rec.market_date || ' | Price: ' || rec.price || ' | Open: ' || rec.open_price);
