       WHERE m.region IS NOT NULL
       GROUP BY m.region
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Final audit region: ' || lv_region);

  SELECT COUNT(DISTINCT m.member_id),
         COUNT(t.txn_id),
         NVL(SUM(t.quantity), 0),
         NVL(AVG(t.percentage_fee), 0)
    INTO lv_member_count,
         lv_txn_count,
         lv_total_quantity,
         lv_avg_fee
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
    LEFT OUTER JOIN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
      ON t.member_id = m.member_id
   WHERE m.region = lv_region;

  DBMS_OUTPUT.PUT_LINE('Region summary: Members=' || lv_member_count || ' | Transactions=' || lv_txn_count || ' | Quantity=' || lv_total_quantity || ' | Avg Fee=' || lv_avg_fee);

  IF lv_txn_count = 0 OR lv_member_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Region readiness: REVIEW REQUIRED');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Region readiness: NORMAL');
  END IF;

  FOR rec IN (
    SELECT *
      FROM (
        SELECT t.ticker,
               COUNT(t.txn_id) AS txn_count,
               NVL(SUM(t.quantity), 0) AS total_quantity
          FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
          INNER JOIN BANK_SALES_TRADING.BITCOIN_MEMBERS m
            ON m.member_id = t.member_id
         WHERE m.region = lv_region
         GROUP BY t.ticker
         ORDER BY COUNT(t.txn_id) DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_ticker_rows := lv_ticker_rows + 1;

    IF rec.txn_count >= 5 THEN
      DBMS_OUTPUT.PUT_LINE('High activity ticker: ' || rec.ticker || ' | Transactions: ' || rec.txn_count || ' | Quantity: ' || rec.total_quantity);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Standard activity ticker: ' || rec.ticker || ' | Transactions: ' || rec.txn_count || ' | Quantity: ' || rec.total_quantity);
    END IF;
  END LOOP;

  IF lv_ticker_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No ticker activity found for final audit region.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

