CREATE OR REPLACE PROCEDURE get_country_fert_birth_snapshot(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
) IS
  lv_country_code CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_tfr          CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_cbr          CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_birth_rate%TYPE;
BEGIN
  -- Resolve country code from name to ensure consistent joins across datasets.
  SELECT c.country_code
    INTO lv_country_code
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
   WHERE c.country_name = p_country_name;

  -- Pull a single year snapshot for both metrics.
  SELECT f.total_fertility_rate,
         b.crude_birth_rate
    INTO lv_tfr,
         lv_cbr
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
    INNER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
      ON b.country_code = f.country_code
     AND b.year = f.year
   WHERE f.country_code = lv_country_code
     AND f.year = p_year;

  DBMS_OUTPUT.PUT_LINE(
    'Country=' || p_country_name ||
    ', Year=' || p_year ||
    ', Total Fertility Rate=' || lv_tfr ||
    ', Crude Birth Rate=' || lv_cbr
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END get_country_fert_birth_snapshot;
/

