CREATE OR REPLACE PACKAGE BODY census_fertility_pkg IS
  PROCEDURE print_top_birth_rate_countries(
    p_year  IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
    p_top_n IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for readability
    lv_top_n        PLS_INTEGER;
    lv_rank         PLS_INTEGER := 0;
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    -- Control-flow guardrails: avoid null/zero/negative top-n.
    IF p_top_n IS NULL OR p_top_n <= 0 THEN
      lv_top_n := 1;
    ELSIF p_top_n > co_report_limit THEN
      lv_top_n := co_report_limit;
    ELSE
      lv_top_n := p_top_n;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Top countries by crude birth rate for year ' || p_year || ' (max rows = ' || lv_top_n || ')'
    );

    FOR rec IN (
      SELECT c.country_name,
             b.crude_birth_rate,
             f.total_fertility_rate
        FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
        INNER JOIN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
          ON f.country_code = b.country_code
         AND f.year = b.year
        INNER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
          ON c.country_code = b.country_code
       WHERE b.year = p_year
         AND b.crude_birth_rate IS NOT NULL
       ORDER BY TO_NUMBER(b.crude_birth_rate) DESC, c.country_name
       FETCH FIRST lv_top_n ROWS ONLY
    ) LOOP
      lv_rank := lv_rank + 1;
      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        LPAD(TO_CHAR(lv_rank), 2, '0') ||
        '. ' || rec.country_name ||
        ' | CBR=' || rec.crude_birth_rate ||
        ' | TFR=' || rec.total_fertility_rate
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the criteria.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_birth_rate_countries;
END census_fertility_pkg;
/

