  PROCEDURE print_suspicious_birth_rate_values(
    p_year IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  ) IS
    co_report_limit     CONSTANT PLS_INTEGER := 15; -- Limit output for readability
    lv_suspicious_count PLS_INTEGER := 0;
    lv_printed          PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'Suspicious crude_birth_rate values for year ' || p_year || ' (max rows = ' || co_report_limit || ')'
    );

    -- Count rows where crude_birth_rate exists but is not numeric.
    SELECT COUNT(*)
      INTO lv_suspicious_count
      FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
      INNER JOIN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
        ON f.country_code = b.country_code
       AND f.year = b.year
     WHERE b.year = p_year
       AND b.crude_birth_rate IS NOT NULL
       AND NOT REGEXP_LIKE(b.crude_birth_rate, '^\s*[+-]?(\d+(\.\d+)?)\s*$');

    DBMS_OUTPUT.PUT_LINE('Suspicious count=' || lv_suspicious_count);

    IF lv_suspicious_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No suspicious crude_birth_rate values found.');
      RETURN;
    END IF;

    FOR rec IN (
      SELECT c.country_name,
             b.crude_birth_rate
        FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
        INNER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA c
          ON c.country_code = b.country_code
        INNER JOIN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
          ON f.country_code = b.country_code
         AND f.year = b.year
       WHERE b.year = p_year
         AND b.crude_birth_rate IS NOT NULL
         AND NOT REGEXP_LIKE(b.crude_birth_rate, '^\s*[+-]?(\d+(\.\d+)?)\s*$')
       ORDER BY c.country_name
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_printed := lv_printed + 1;
      DBMS_OUTPUT.PUT_LINE(rec.country_name || ' | crude_birth_rate=' || rec.crude_birth_rate);
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_suspicious_birth_rate_values;
