DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient_id   SYNTHEA.ENCOUNTERS.patient%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Pick a real patient id with the most encounters to make the demo meaningful.
  SELECT x.patient
    INTO lv_patient_id
    FROM (
      SELECT e.patient
        FROM SYNTHEA.ENCOUNTERS e
       GROUP BY e.patient
       ORDER BY COUNT(*) DESC, e.patient
    ) x
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Patient = ' || lv_patient_id);
  DBMS_OUTPUT.PUT_LINE('Recent encounters (max rows = ' || co_report_limit || '):');

  FOR r IN (
    SELECT e.start_timestamp,
           e.encounterclass,
           e.description,
           o.name AS org_name
      FROM SYNTHEA.ENCOUNTERS e
      INNER JOIN SYNTHEA.ORGANIZATIONS o
        ON o.id = e.organization
     WHERE e.patient = lv_patient_id
     ORDER BY e.start_timestamp DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(r.start_timestamp, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | ' || r.encounterclass ||
      ' | ' || r.description ||
      ' | ' || r.org_name
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for this patient.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

