DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient_id   SYNTHEA.IMMUNIZATIONS.patient%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Choose a patient id that is most common in immunizations for a useful demo.
  SELECT x.patient
    INTO lv_patient_id
    FROM (
      SELECT i.patient
        FROM SYNTHEA.IMMUNIZATIONS i
       GROUP BY i.patient
       ORDER BY COUNT(*) DESC, i.patient
    ) x
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Patient = ' || lv_patient_id);
  DBMS_OUTPUT.PUT_LINE('Recent immunizations (max rows = ' || co_report_limit || '):');

  FOR r IN (
    SELECT i.date_timestamp,
           i.description AS immunization_desc,
           NVL(e.encounterclass, 'NO_ENCOUNTER') AS encounter_class
      FROM SYNTHEA.IMMUNIZATIONS i
