question:
Now add a simple operational rule on top of the encounter snapshot. For the same patient, count how many encounters they have in total and classify them as HIGH_UTILIZATION if the count is at least 10, otherwise NORMAL_UTILIZATION. Print the patient id, the count, and the classification. Also, print a second line that shows the earliest and latest encounter timestamps for that patient. Make sure the code does not error if there are no encounters.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Patient = ' || lv_patient_id);
DBMS_OUTPUT.PUT_LINE('Encounter count = ' || lv_encounter_count || ' | classification = ' || lv_classification);
DBMS_OUTPUT.PUT_LINE('Encounter range: ' || TO_CHAR(lv_min_start, 'YYYY-MM-DD HH24:MI:SS') || ' -> ' || TO_CHAR(lv_max_start, 'YYYY-MM-DD HH24:MI:SS'));
DBMS_OUTPUT.PUT_LINE('No encounters found for this patient.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_high_util_threshold CONSTANT PLS_INTEGER := 10; -- Simple business threshold for classification

  lv_patient_id       SYNTHEA.ENCOUNTERS.patient%TYPE;
  lv_encounter_count  NUMBER := 0;
  lv_classification   VARCHAR2(30);
  lv_min_start        SYNTHEA.ENCOUNTERS.start_timestamp%TYPE;
  lv_max_start        SYNTHEA.ENCOUNTERS.start_timestamp%TYPE;
BEGIN
  -- Reuse the "most encounters" patient to keep results meaningful.
  SELECT x.patient
    INTO lv_patient_id
    FROM (
      SELECT e.patient
        FROM SYNTHEA.ENCOUNTERS e
       GROUP BY e.patient
       ORDER BY COUNT(*) DESC, e.patient
    ) x
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Patient = ' || lv_patient_id);

  -- Aggregate-based snapshot: count + date range.
  SELECT COUNT(*), MIN(e.start_timestamp), MAX(e.start_timestamp)
    INTO lv_encounter_count, lv_min_start, lv_max_start
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = lv_patient_id;

  IF lv_encounter_count >= co_high_util_threshold THEN
    lv_classification := 'HIGH_UTILIZATION';
  ELSE
    lv_classification := 'NORMAL_UTILIZATION';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Encounter count = ' || lv_encounter_count || ' | classification = ' || lv_classification);

  IF lv_encounter_count = 0 OR lv_min_start IS NULL OR lv_max_start IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for this patient.');
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'Encounter range: ' ||
      TO_CHAR(lv_min_start, 'YYYY-MM-DD HH24:MI:SS') ||
      ' -> ' ||
      TO_CHAR(lv_max_start, 'YYYY-MM-DD HH24:MI:SS')
    );
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

