question:
Debugging task: the helpdesk reports that the immunization report sometimes shows encounter_class=NO_ENCOUNTER even when the immunization has an encounter id. Build a diagnostic anonymous block that prints up to 15 immunizations where IMMUNIZATIONS.ENCOUNTER is NOT NULL but there is no matching ENCOUNTERS row. For each, print patient id, immunization timestamp, the encounter id from immunizations, and a diagnosis label MISSING_ENCOUNTER_ROW. Also print a summary line with the total number of suspect immunizations (not limited to 15). If there are none, print a clear message.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Suspect immunizations (encounter id present but no ENCOUNTERS row), max rows = ' || co_report_limit);
DBMS_OUTPUT.PUT_LINE('patient=' || r.patient || ' | immunization_ts=' || TO_CHAR(r.date_timestamp, 'YYYY-MM-DD HH24:MI:SS') || ' | immunization_encounter=' || r.encounter || ' | diagnosis=MISSING_ENCOUNTER_ROW');
DBMS_OUTPUT.PUT_LINE('Total suspect immunizations = ' || lv_total_suspects);
DBMS_OUTPUT.PUT_LINE('No suspect immunizations found.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_total_suspects NUMBER := 0;
  lv_rows_printed   PLS_INTEGER := 0;
BEGIN
  -- Total suspects (not limited to 15) for an ops-friendly summary.
  SELECT COUNT(*)
    INTO lv_total_suspects
    FROM SYNTHEA.IMMUNIZATIONS i
   WHERE i.encounter IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
         FROM SYNTHEA.ENCOUNTERS e
        WHERE e.id = i.encounter
     );

  IF lv_total_suspects = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No suspect immunizations found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Suspect immunizations (encounter id present but no ENCOUNTERS row), max rows = ' || co_report_limit);

  FOR r IN (
    SELECT i.patient,
           i.date_timestamp,
           i.encounter
      FROM SYNTHEA.IMMUNIZATIONS i
     WHERE i.encounter IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
           FROM SYNTHEA.ENCOUNTERS e
          WHERE e.id = i.encounter
       )
     ORDER BY i.date_timestamp DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'patient=' || r.patient ||
      ' | immunization_ts=' || TO_CHAR(r.date_timestamp, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | immunization_encounter=' || r.encounter ||
      ' | diagnosis=MISSING_ENCOUNTER_ROW'
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Total suspect immunizations = ' || lv_total_suspects);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

