CREATE OR REPLACE PACKAGE natality_pkg IS
  PROCEDURE print_county_snapshot(
    p_year IN sdoh_cdc_wonder_natality.county_natality.year%TYPE
  );
END natality_pkg;
/

CREATE OR REPLACE PACKAGE BODY natality_pkg IS
  PROCEDURE print_county_snapshot(
    p_year IN sdoh_cdc_wonder_natality.county_natality.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_year sdoh_cdc_wonder_natality.county_natality.year%TYPE;
    lv_births_num NUMBER;
    lv_age_num    NUMBER;
  BEGIN
    -- Default to the most recent year if NULL is provided.
    IF p_year IS NULL THEN
      SELECT MAX(cn.year)
        INTO lv_year
        FROM sdoh_cdc_wonder_natality.county_natality cn;
    ELSE
      lv_year := p_year;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Snapshot year = ' || TO_CHAR(lv_year, 'YYYY'));

    FOR rec IN (
      SELECT cn.county_of_residence,
             cn.births,
             cn.ave_age_of_mother
        FROM sdoh_cdc_wonder_natality.county_natality cn
       WHERE cn.year = lv_year
       ORDER BY cn.county_of_residence
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      -- births: treat non-numeric as 0
      IF REGEXP_LIKE(rec.births, '^\s*\d+\s*$') THEN
        lv_births_num := TO_NUMBER(TRIM(rec.births));
      ELSE
        lv_births_num := 0;
      END IF;

      -- ave age: if not numeric, print NULL
      IF REGEXP_LIKE(rec.ave_age_of_mother, '^\s*\d+(\.\d+)?\s*$') THEN
        lv_age_num := TO_NUMBER(TRIM(rec.ave_age_of_mother));
      ELSE
        lv_age_num := NULL;
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'County = ' || rec.county_of_residence ||
        ' | Births = ' || TO_CHAR(lv_births_num) ||
        ' | Ave mother age = ' || CASE WHEN lv_age_num IS NULL THEN 'NULL' ELSE TO_CHAR(lv_age_num) END
      );
    END LOOP;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_county_snapshot;
END natality_pkg;
/

