CREATE OR REPLACE PROCEDURE report_vital_rates(
  p_country_like IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
  p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_vitals(
    cp_country_like CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
    cp_year_from    CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
    cp_year_to      CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  ) IS
    SELECT *
      FROM (
        SELECT cn.country_name AS country_name,
               bd.year         AS year,
               bd.crude_birth_rate AS crude_birth_rate,
               bd.crude_death_rate AS crude_death_rate,
               af.total_fertility_rate AS total_fertility_rate
          FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cn
          INNER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bd
            ON bd.country_name = cn.country_name
          INNER JOIN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES af
            ON af.country_name = cn.country_name
           AND af.year = bd.year
         WHERE (cp_country_like IS NULL OR UPPER(cn.country_name) LIKE UPPER(cp_country_like))
           AND (cp_year_from IS NULL OR bd.year >= cp_year_from)
           AND (cp_year_to IS NULL OR bd.year <= cp_year_to)
         ORDER BY cn.country_name, bd.year
      )
     WHERE ROWNUM <= co_report_limit;

  lv_country_name CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE;
  lv_year         CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE;
  lv_cbr          CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_birth_rate%TYPE;
  lv_cdr          CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_death_rate%TYPE;
  lv_tfr          CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;

  lv_rowcount     PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Report start. Country filter=' || NVL(p_country_like, 'NULL') || ', years ' || NVL(p_year_from, 'NULL') || ' to ' || NVL(p_year_to, 'NULL') || ', max rows=' || co_report_limit);

  OPEN c_vitals(p_country_like, p_year_from, p_year_to);
  LOOP
    FETCH c_vitals INTO lv_country_name, lv_year, lv_cbr, lv_cdr, lv_tfr;
    EXIT WHEN c_vitals%NOTFOUND;

    lv_rowcount := lv_rowcount + 1;
    DBMS_OUTPUT.PUT_LINE('Country=' || lv_country_name || ', Year=' || lv_year || ', CBR=' || lv_cbr || ', CDR=' || lv_cdr || ', TFR=' || lv_tfr);
  END LOOP;
  CLOSE c_vitals;

  IF lv_rowcount = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF c_vitals%ISOPEN THEN
      CLOSE c_vitals;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_vital_rates;
/

