CREATE OR REPLACE PACKAGE pkg_vital_utils IS
  FUNCTION get_total_fertility_rate(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) RETURN NUMBER;

  PROCEDURE print_fertility_classification(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_threshold    IN NUMBER
  );
END pkg_vital_utils;
/

CREATE OR REPLACE PACKAGE BODY pkg_vital_utils IS
  FUNCTION get_total_fertility_rate(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) RETURN NUMBER IS
    lv_tfr_str CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
    lv_tfr_num NUMBER;
    lv_exists  NUMBER;
  BEGIN
    -- Ensure country is in reference list
    SELECT COUNT(*)
      INTO lv_exists
      FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cn
     WHERE cn.country_name = p_country_name;

    IF lv_exists = 0 THEN
      RETURN NULL;
    END IF;

    SELECT af.total_fertility_rate
      INTO lv_tfr_str
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES af
     WHERE af.country_name = p_country_name
       AND af.year = p_year;

    lv_tfr_num := TO_NUMBER(lv_tfr_str);
    RETURN lv_tfr_num;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      RETURN NULL;
    WHEN VALUE_ERROR THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END get_total_fertility_rate;

  PROCEDURE print_fertility_classification(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_threshold    IN NUMBER
  ) IS
    lv_tfr   NUMBER;
    lv_class VARCHAR2(10);
  BEGIN
    lv_tfr := get_total_fertility_rate(p_country_name, p_year);

    IF lv_tfr IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the requested criteria.');
      RETURN;
    END IF;

    IF lv_tfr >= p_threshold THEN
      lv_class := 'High';
    ELSE
      lv_class := 'Low';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Fertility rate for ' || p_country_name || ' (' || p_year || ') is ' || TO_CHAR(lv_tfr) || '; class=' || lv_class);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric value.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_fertility_classification;
END pkg_vital_utils;
/

