CREATE OR REPLACE PACKAGE pkg_growth_batch IS
  PROCEDURE print_top_growth(
    p_year IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  );
END pkg_growth_batch;
/

CREATE OR REPLACE PACKAGE BODY pkg_growth_batch IS
  PROCEDURE print_top_growth(
    p_year IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_effective_year CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE;

    CURSOR c_top_growth(cp_year CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE) IS
      SELECT *
        FROM (
          SELECT bd.country_name AS country_name,
                 bd.growth_rate  AS growth_rate
            FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bd
            INNER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cn
              ON cn.country_name = bd.country_name
           WHERE bd.year = cp_year
           ORDER BY TO_NUMBER(bd.growth_rate) DESC, bd.country_name
        )
       WHERE ROWNUM <= co_report_limit;

    lv_country_name CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE;
    lv_growth_rate  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.growth_rate%TYPE;

    lv_rows PLS_INTEGER := 0;
  BEGIN
    IF p_year IS NULL THEN
      SELECT MAX(bd.year)
        INTO lv_effective_year
        FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bd;
    ELSE
      lv_effective_year := p_year;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Top growth scan. Year=' || lv_effective_year || ', max rows=' || co_report_limit);

    OPEN c_top_growth(lv_effective_year);
    LOOP
      FETCH c_top_growth INTO lv_country_name, lv_growth_rate;
      EXIT WHEN c_top_growth%NOTFOUND;

      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE('Country=' || lv_country_name || ', GrowthRate=' || lv_growth_rate);
    END LOOP;
    CLOSE c_top_growth;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the requested criteria.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      IF c_top_growth%ISOPEN THEN
        CLOSE c_top_growth;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_growth;
END pkg_growth_batch;
/

