DECLARE
  co_year_limit CONSTANT PLS_INTEGER := 3; -- Keep interactive run short

  lv_country   CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE;
  lv_year_min  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE;
  lv_year_max  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE;

  CURSOR c_years(cp_country CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE) IS
    SELECT *
      FROM (
        SELECT bd.year AS year
          FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bd
          INNER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cn
            ON cn.country_name = bd.country_name
         WHERE bd.country_name = cp_country
         GROUP BY bd.year
         ORDER BY bd.year DESC
      )
     WHERE ROWNUM <= co_year_limit;
BEGIN
  SELECT bd.country_name
    INTO lv_country
    FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bd
    GROUP BY bd.country_name
    ORDER BY COUNT(*) DESC
    FETCH FIRST 1 ROWS ONLY;

  SELECT MIN(bd.year), MAX(bd.year)
    INTO lv_year_min, lv_year_max
    FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bd
   WHERE bd.country_name = lv_country;

  DBMS_OUTPUT.PUT_LINE('Interactive run for country=' || lv_country);

  FOR rec_year IN c_years(lv_country) LOOP
    DBMS_OUTPUT.PUT_LINE('Year context=' || rec_year.year);

    -- Reuse Turn 1 procedure: report within the country's min/max bounds
    report_vital_rates('%' || lv_country || '%', lv_year_min, lv_year_max);

    -- Reuse Turn 2 package: classify using the most recent year
    pkg_vital_utils.print_fertility_classification(lv_country, lv_year_max, 2.1);

    -- Reuse Turn 3 package: scan top growth for the same year
    pkg_growth_batch.print_top_growth(lv_year_max);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

