CREATE OR REPLACE PROCEDURE report_station_trip_activity(
  p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE,
  p_start_ts   IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
  p_end_ts     IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_station_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_trip_count    PLS_INTEGER := 0;
  lv_null_duration PLS_INTEGER := 0;
  lv_total_duration NUMBER := 0;

  CURSOR cur_trips IS
    SELECT t.trip_id AS trip_id,
           t.duration_sec AS duration_sec
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
     WHERE t.start_station_id = p_station_id
       AND t.start_date >= p_start_ts
       AND t.end_date   <= p_end_ts
     ORDER BY t.start_date, t.trip_id;
BEGIN
  -- Validate time window.
  IF p_start_ts > p_end_ts THEN
    DBMS_OUTPUT.PUT_LINE('Invalid window: start timestamp is after end timestamp.');
    RETURN;
  END IF;

  -- Resolve station name for display.
  SELECT si.name
    INTO lv_station_name
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
   WHERE si.station_id = p_station_id;

  DBMS_OUTPUT.PUT_LINE('Station ' || p_station_id || ' - ' || lv_station_name);
  DBMS_OUTPUT.PUT_LINE('Trip window: ' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI:SS') || ' to ' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI:SS'));

  FOR rec IN cur_trips LOOP
    lv_trip_count := lv_trip_count + 1;

    IF lv_trip_count > co_report_limit THEN
      EXIT;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Trip ' || rec.trip_id || ' | duration_sec=' || rec.duration_sec);

    IF rec.duration_sec IS NULL THEN
      lv_null_duration := lv_null_duration + 1;
    ELSE
      -- Enforce numeric conversion in a controlled way.
      lv_total_duration := lv_total_duration + TO_NUMBER(rec.duration_sec);
    END IF;
  END LOOP;

  IF lv_trip_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No trips found in the requested window.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Trips found: ' || lv_trip_count || ' | total_duration_sec=' || lv_total_duration || ' | null_duration_rows=' || lv_null_duration);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_trip_activity;
/

