/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops IS
  PROCEDURE run_region_snapshot(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
    p_hours_back  IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_region_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
    lv_region_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;

    lv_hours_back NUMBER := p_hours_back;
    lv_rows_printed PLS_INTEGER := 0;

    lv_trip_count   NUMBER;
    lv_avg_duration NUMBER;

    CURSOR cur_station_rank IS
      SELECT si.station_id AS station_id,
             si.name       AS station_name,
             TO_NUMBER(ss.num_bikes_available) AS bikes_available
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
          ON ss.station_id = si.station_id
       WHERE si.region_id = lv_region_id
       ORDER BY TO_NUMBER(ss.num_bikes_available) DESC, si.station_id;
  BEGIN
    -- Defaulting logic for hours-back parameter.
    IF lv_hours_back IS NULL OR lv_hours_back <= 0 THEN
      lv_hours_back := 24;
    END IF;

    -- Resolve region.
    SELECT r.region_id, r.name
      INTO lv_region_id, lv_region_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE r.name = p_region_name;

    DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region_name || ' (region_id=' || lv_region_id || ')');
    DBMS_OUTPUT.PUT_LINE('Snapshot stations by bikes available (max rows = ' || co_report_limit || ')');
    DBMS_OUTPUT.PUT_LINE('Hours back used: ' || lv_hours_back);

    FOR rec IN cur_station_rank LOOP
      lv_rows_printed := lv_rows_printed + 1;

      IF lv_rows_printed > co_report_limit THEN
        EXIT;
      END IF;

      DBMS_OUTPUT.PUT_LINE('Station ' || rec.station_id || ' - ' || rec.station_name || ' | bikes_available=' || rec.bikes_available);

      -- Trip stats for the rolling window; ignore NULL durations for the average.
      SELECT COUNT(*),
             AVG(TO_NUMBER(t.duration_sec))
        INTO lv_trip_count, lv_avg_duration
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
       WHERE t.start_station_id = rec.station_id
         AND t.start_date >= (SYSTIMESTAMP - NUMTODSINTERVAL(lv_hours_back, 'HOUR'))
         AND t.duration_sec IS NOT NULL;

      DBMS_OUTPUT.PUT_LINE('  Trips started in last ' || lv_hours_back || ' hours: ' || lv_trip_count || ' | avg_duration_sec=' || lv_avg_duration);
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No stations found for this region.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      -- Covers missing region or missing data during processing.
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_region_snapshot;
END bikeshare_ops;
/

