DECLARE
  co_report_limit     CONSTANT NUMBER := 15; -- Limit output for report readability
  co_single_row_limit CONSTANT NUMBER := 1;  -- Validate one distinct calendar year
  lv_calendar_year    COMPLEX_ORACLE.TIMES.calendar_year%TYPE := 2000;
  lv_valid_year       COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
  lv_validation_mode  VARCHAR2(30) := 'NORMAL';
  lv_rows             NUMBER := 0;
BEGIN
  -- Optional diagnostic branch helps identify duplicate year validation issues.
  IF lv_validation_mode = 'DUPLICATE_CHECK' THEN
    SELECT t.calendar_year
      INTO lv_valid_year
      FROM COMPLEX_ORACLE.TIMES t
     WHERE t.calendar_year = lv_calendar_year;
  ELSE
    SELECT yr.calendar_year
      INTO lv_valid_year
      FROM (
            SELECT DISTINCT t.calendar_year
              FROM COMPLEX_ORACLE.TIMES t
             WHERE t.calendar_year = lv_calendar_year
               AND ROWNUM <= co_single_row_limit
           ) yr;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Channel sales snapshot for calendar year ' || lv_calendar_year);

  FOR rec IN (
    SELECT rpt.channel_desc,
           rpt.sale_rows,
           rpt.total_amount
      FROM (
            SELECT ch.channel_desc,
                   COUNT(*) AS sale_rows,
                   SUM(s.amount_sold) AS total_amount
              FROM COMPLEX_ORACLE.SALES s
             INNER JOIN COMPLEX_ORACLE.CHANNELS ch
                ON ch.channel_id = s.channel_id
             INNER JOIN COMPLEX_ORACLE.TIMES t
                ON t.time_id = s.time_id
             WHERE t.calendar_year = lv_valid_year
             GROUP BY ch.channel_desc
             ORDER BY total_amount DESC
           ) rpt
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows := lv_rows + 1;
    IF rec.total_amount > 0 THEN
      DBMS_OUTPUT.PUT_LINE(rec.channel_desc || ': ' || rec.sale_rows || ' sale rows, amount ' || rec.total_amount);
    END IF;
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No channel sales found.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

