CREATE OR REPLACE PROCEDURE report_channel_sales_by_year(
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
  p_min_amount    IN COMPLEX_ORACLE.SALES.amount_sold%TYPE DEFAULT 0
) IS
  co_report_limit     CONSTANT NUMBER := 15; -- Limit output for report readability
  co_single_row_limit CONSTANT NUMBER := 1;  -- Validate one distinct calendar year
  lv_valid_year       COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
  lv_effective_min    COMPLEX_ORACLE.SALES.amount_sold%TYPE;
  lv_rows             NUMBER := 0;
BEGIN
  IF p_calendar_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Calendar year is required.');
    RETURN;
  END IF;

  IF p_calendar_year = 0 THEN
    -- Debug branch: proves whether the calendar validation query can return duplicates.
    SELECT t.calendar_year
      INTO lv_valid_year
      FROM COMPLEX_ORACLE.TIMES t
     WHERE t.calendar_year = (SELECT MIN(t2.calendar_year)
                                FROM COMPLEX_ORACLE.TIMES t2);
  ELSE
    SELECT yr.calendar_year
      INTO lv_valid_year
      FROM (
            SELECT DISTINCT t.calendar_year
              FROM COMPLEX_ORACLE.TIMES t
             WHERE t.calendar_year = p_calendar_year
               AND ROWNUM <= co_single_row_limit
           ) yr;
  END IF;

  lv_effective_min := NVL(p_min_amount, 0);
  DBMS_OUTPUT.PUT_LINE('Reusable channel sales report for year ' || p_calendar_year);

  FOR rec IN (
    SELECT rpt.channel_desc,
           rpt.sale_rows,
           rpt.total_amount
      FROM (
            SELECT ch.channel_desc,
                   COUNT(*) AS sale_rows,
                   SUM(s.amount_sold) AS total_amount
              FROM COMPLEX_ORACLE.SALES s
             INNER JOIN COMPLEX_ORACLE.CHANNELS ch
                ON ch.channel_id = s.channel_id
             INNER JOIN COMPLEX_ORACLE.TIMES t
                ON t.time_id = s.time_id
             WHERE t.calendar_year = lv_valid_year
             GROUP BY ch.channel_desc
            HAVING SUM(s.amount_sold) >= lv_effective_min
             ORDER BY total_amount DESC
           ) rpt
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows := lv_rows + 1;
    IF rec.total_amount >= lv_effective_min THEN
      DBMS_OUTPUT.PUT_LINE(rec.channel_desc || ': ' || rec.sale_rows || ' sale rows, amount ' || rec.total_amount);
    END IF;
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No channel rows matched the filters.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the requested calendar year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple calendar rows found during validation.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error while reporting channel sales.');
END report_channel_sales_by_year;
/

