CREATE OR REPLACE PROCEDURE diagnose_product_margin(
  p_prod_id        IN COMPLEX_ORACLE.PRODUCTS.prod_id%TYPE,
  p_calendar_year  IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE
) IS
  co_report_limit  CONSTANT NUMBER := 15; -- Limit sample rows for diagnostic readability
  lv_product_name  COMPLEX_ORACLE.PRODUCTS.prod_name%TYPE;
  lv_sales_amount  COMPLEX_ORACLE.SALES.amount_sold%TYPE;
  lv_quantity_sold COMPLEX_ORACLE.SALES.quantity_sold%TYPE;
  lv_estimated_cost COMPLEX_ORACLE.COSTS.unit_cost%TYPE;
  lv_margin_amount NUMBER := 0;
  lv_rows          NUMBER := 0;
BEGIN
  IF p_prod_id IS NULL OR p_calendar_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Product id and calendar year are required.');
    RETURN;
  END IF;

  IF p_calendar_year = 0 THEN
    -- Debug branch: deliberately checks whether product validation can return multiple rows.
    SELECT p.prod_name
      INTO lv_product_name
      FROM COMPLEX_ORACLE.PRODUCTS p
     WHERE p.prod_id IS NOT NULL;
  ELSE
    SELECT p.prod_name
      INTO lv_product_name
      FROM COMPLEX_ORACLE.PRODUCTS p
     WHERE p.prod_id = p_prod_id;
  END IF;

  SELECT SUM(s.amount_sold),
         SUM(s.quantity_sold),
         SUM(NVL(c.unit_cost, 0) * s.quantity_sold)
    INTO lv_sales_amount,
         lv_quantity_sold,
         lv_estimated_cost
    FROM COMPLEX_ORACLE.SALES s
   INNER JOIN COMPLEX_ORACLE.TIMES t
      ON t.time_id = s.time_id
    LEFT OUTER JOIN COMPLEX_ORACLE.COSTS c
      ON c.prod_id = s.prod_id
     AND c.time_id = s.time_id
     AND c.channel_id = s.channel_id
     AND c.promo_id = s.promo_id
   WHERE s.prod_id = p_prod_id
     AND t.calendar_year = p_calendar_year;

  DBMS_OUTPUT.PUT_LINE('Margin diagnostic for product ' || p_prod_id || ' - ' || lv_product_name);

  IF lv_sales_amount IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Root cause: no sales rows exist for this product and year.');
    RETURN;
  END IF;

  IF lv_estimated_cost = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Root cause: sales exist but matching cost rows are missing or zero.');
  ELSE
    lv_margin_amount := lv_sales_amount - lv_estimated_cost;
    DBMS_OUTPUT.PUT_LINE('Sales amount: ' || lv_sales_amount);
    DBMS_OUTPUT.PUT_LINE('Estimated cost: ' || lv_estimated_cost);
    DBMS_OUTPUT.PUT_LINE('Margin amount: ' || lv_margin_amount);

    IF lv_margin_amount < 0 THEN
      DBMS_OUTPUT.PUT_LINE('Root cause: estimated cost exceeds sales amount.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Root cause: margin is non-negative.');
    END IF;
  END IF;

  FOR rec IN (
    SELECT sample_rows.time_id,
           sample_rows.channel_id,
           sample_rows.promo_id,
           sample_rows.amount_sold
      FROM (
            SELECT s.time_id,
                   s.channel_id,
                   s.promo_id,
                   s.amount_sold
              FROM COMPLEX_ORACLE.SALES s
             INNER JOIN COMPLEX_ORACLE.TIMES t
                ON t.time_id = s.time_id
             WHERE s.prod_id = p_prod_id
               AND t.calendar_year = p_calendar_year
             ORDER BY s.time_id
           ) sample_rows
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE('Sample sale ' || lv_rows || ': channel ' || rec.channel_id || ', promo ' || rec.promo_id || ', amount ' || rec.amount_sold);
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No sample sales rows printed.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for product diagnostics.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows found while validating diagnostic inputs.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error while diagnosing margin.');
END diagnose_product_margin;
/

