CREATE OR REPLACE PACKAGE bls_cpi_pkg IS
  PROCEDURE report_cpi_snapshot(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE,
    p_from_year      IN BLS.CPI_U.year%TYPE,
    p_to_year        IN BLS.CPI_U.year%TYPE
  );
