CREATE OR REPLACE PACKAGE BODY bls_cpi_pkg IS
  PROCEDURE report_cpi_snapshot(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE,
    p_from_year      IN BLS.CPI_U.year%TYPE,
    p_to_year        IN BLS.CPI_U.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_cpi IS
      SELECT area_name,
             item_name,
             c_date,
             value
        FROM (
              SELECT u.area_name,
                     u.item_name,
                     u.c_date,
                     u.value
                FROM BLS.CPI_U u
               WHERE u.area_name LIKE p_area_name_like
                 AND u.item_name LIKE p_item_name_like
                 AND u.year BETWEEN p_from_year AND p_to_year
                 AND u.period LIKE 'M%'
              UNION ALL
              SELECT c.area_name,
                     c.item_name,
                     c.c_date,
                     c.value
                FROM BLS.C_CPI_U c
               WHERE c.area_name LIKE p_area_name_like
                 AND c.item_name LIKE p_item_name_like
                 AND c.year BETWEEN p_from_year AND p_to_year
                 AND c.period LIKE 'M%'
             )
       ORDER BY c_date DESC;

    r        c_cpi%ROWTYPE;
    lv_count PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('CPI snapshot (max rows=' || co_report_limit || '):');

    OPEN c_cpi;
    LOOP
      FETCH c_cpi INTO r;
      EXIT WHEN c_cpi%NOTFOUND;

      lv_count := lv_count + 1;
      IF lv_count > co_report_limit THEN
        EXIT;
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'AREA=' || r.area_name || ' | ITEM=' || r.item_name || ' | ' || TO_CHAR(r.c_date, 'YYYY-MM-DD') || ' | value=' || r.value
      );
    END LOOP;
    CLOSE c_cpi;

    IF lv_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No CPI rows matched your filters.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      IF c_cpi%ISOPEN THEN
        CLOSE c_cpi;
      END IF;
  END report_cpi_snapshot;

  PROCEDURE flag_large_changes(
    p_area_name_like IN BLS.CPI_U.area_name%TYPE,
    p_item_name_like IN BLS.CPI_U.item_name%TYPE,
    p_from_year      IN BLS.CPI_U.year%TYPE,
    p_to_year        IN BLS.CPI_U.year%TYPE,
    p_pct_threshold  IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_changes IS
      WITH all_rows AS (
        SELECT u.area_name,
               u.item_name,
               u.c_date,
               u.value
          FROM BLS.CPI_U u
         WHERE u.area_name LIKE p_area_name_like
           AND u.item_name LIKE p_item_name_like
           AND u.year BETWEEN p_from_year AND p_to_year
           AND u.period LIKE 'M%'
        UNION ALL
        SELECT c.area_name,
               c.item_name,
               c.c_date,
               c.value
          FROM BLS.C_CPI_U c
         WHERE c.area_name LIKE p_area_name_like
           AND c.item_name LIKE p_item_name_like
           AND c.year BETWEEN p_from_year AND p_to_year
           AND c.period LIKE 'M%'
      ), seq AS (
        SELECT a.area_name,
               a.item_name,
               a.c_date,
               a.value,
               LAG(a.value) OVER (PARTITION BY a.area_name, a.item_name ORDER BY a.c_date) AS prev_value
          FROM all_rows a
      )
      SELECT s.area_name,
             s.item_name,
             s.c_date,
             s.value,
             s.prev_value,
             CASE
               WHEN s.prev_value IS NULL THEN NULL
               WHEN TO_NUMBER(s.prev_value) = 0 THEN NULL
               ELSE (TO_NUMBER(s.value) - TO_NUMBER(s.prev_value)) / TO_NUMBER(s.prev_value) * 100
             END AS pct_change
        FROM seq s
       WHERE s.c_date IS NOT NULL
       ORDER BY s.c_date DESC;

    r              c_changes%ROWTYPE;
    lv_seen        PLS_INTEGER := 0;
    lv_flag_count  PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Large CPI changes (abs pct >= ' || p_pct_threshold || '), max rows=' || co_report_limit);

    OPEN c_changes;
    LOOP
      FETCH c_changes INTO r;
      EXIT WHEN c_changes%NOTFOUND;

      lv_seen := lv_seen + 1;
      IF lv_seen > co_report_limit THEN
        EXIT;
      END IF;

      IF r.pct_change IS NOT NULL AND ABS(r.pct_change) >= p_pct_threshold THEN
        lv_flag_count := lv_flag_count + 1;
        DBMS_OUTPUT.PUT_LINE(
          'AREA=' || r.area_name || ' | ITEM=' || r.item_name || ' | ' || TO_CHAR(r.c_date, 'YYYY-MM-DD') ||
          ' | value=' || r.value || ' | prev=' || r.prev_value || ' | pct=' || TO_CHAR(r.pct_change, 'FM9990D00')
        );
      END IF;
    END LOOP;
    CLOSE c_changes;

    IF lv_flag_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No large changes found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Bad numeric CPI value encountered.');
      IF c_changes%ISOPEN THEN
        CLOSE c_changes;
      END IF;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      IF c_changes%ISOPEN THEN
        CLOSE c_changes;
      END IF;
  END flag_large_changes;

END bls_cpi_pkg;
/

