  lv_threshold  NUMBER := 10;

  lv_series_title_like BLS.UNEMPLOYMENT_CPS_SERIES.series_title%TYPE := '%unemployment%';

  CURSOR c_unemp IS
    SELECT u.series_id,
           u.c_date,
           u.value
      FROM BLS.UNEMPLOYMENT_CPS u
      INNER JOIN BLS.UNEMPLOYMENT_CPS_SERIES s
        ON s.series_id = u.series_id
     WHERE s.series_title LIKE lv_series_title_like
       AND u.year BETWEEN lv_y_from AND lv_y_to
     ORDER BY u.c_date DESC;

  r_unemp c_unemp%ROWTYPE;
  lv_cnt  PLS_INTEGER := 0;
