DECLARE
  -- Inputs (set these to run different checks)
  lv_area_name  BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name  BLS.CPI_U.item_name%TYPE := 'All items';

  lv_series_id  BLS.CPI_U.series_id%TYPE;
  lv_cnt_cpi_u  NUMBER;
  lv_cnt_c_cpi_u NUMBER;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  -- Find exactly one matching series_id for the requested Area/Item.
  SELECT c.series_id
    INTO lv_series_id
    FROM BLS.CPI_U c
   WHERE c.area_name = lv_area_name
     AND c.item_name = lv_item_name
   GROUP BY c.series_id;

  DBMS_OUTPUT.PUT_LINE('Series: ' || lv_series_id || ' | Area: ' || lv_area_name || ' | Item: ' || lv_item_name);
  DBMS_OUTPUT.PUT_LINE('Most recent observations (max rows = ' || co_report_limit || '):');

  FOR r IN (
    SELECT c.c_date, c.period, c.value
      FROM BLS.CPI_U c
     WHERE c.series_id = lv_series_id
     ORDER BY c.c_date DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('  ' || TO_CHAR(r.c_date, 'YYYY-MM-DD') || ' | ' || r.period || ' | ' || r.value);
  END LOOP;

  -- Cross-check how many rows exist for this Area/Item pair in both CPI tables.
  SELECT COUNT(*)
    INTO lv_cnt_cpi_u
    FROM BLS.CPI_U c
   WHERE c.area_name = lv_area_name
     AND c.item_name = lv_item_name;

  SELECT COUNT(*)
    INTO lv_cnt_c_cpi_u
    FROM BLS.C_CPI_U cc
   WHERE cc.area_name = lv_area_name
     AND cc.item_name = lv_item_name;

  DBMS_OUTPUT.PUT_LINE('Row counts for the same Area/Item -> CPI_U=' || lv_cnt_cpi_u || ', C_CPI_U=' || lv_cnt_c_cpi_u);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No series found for the requested Area/Item.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple series matched the requested Area/Item.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

