DECLARE
  -- Inputs (same business keys as Turn 1)
  lv_area_name  BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name  BLS.CPI_U.item_name%TYPE := 'All items';

  lv_series_id     BLS.CPI_U.series_id%TYPE;
  lv_latest_year   BLS.CPI_U.year%TYPE;
  lv_periodicity   VARCHAR2(20);

  lv_monthly_cnt   NUMBER;
  lv_avg_value     NUMBER;
  lv_annual_value  NUMBER;

  lv_dummy_cnt     NUMBER;
BEGIN
  -- Lightweight cross-check that the Area/Item exists in the companion table too.
  SELECT COUNT(*)
    INTO lv_dummy_cnt
    FROM BLS.C_CPI_U cc
   WHERE cc.area_name = lv_area_name
     AND cc.item_name = lv_item_name;

  -- Find the CPI_U series.
  SELECT c.series_id
    INTO lv_series_id
    FROM BLS.CPI_U c
   WHERE c.area_name = lv_area_name
     AND c.item_name = lv_item_name
   GROUP BY c.series_id;

  -- Determine if there are any monthly periods.
  SELECT COUNT(*)
    INTO lv_monthly_cnt
    FROM BLS.CPI_U c
   WHERE c.series_id = lv_series_id
     AND c.period IN ('M01','M02','M03','M04','M05','M06','M07','M08','M09','M10','M11','M12');

  IF lv_monthly_cnt > 0 THEN
    lv_periodicity := 'monthly';
  ELSE
    lv_periodicity := 'annual-only';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Series: ' || lv_series_id || ' | Periodicity: ' || lv_periodicity);

  -- Latest year present for this series.
  SELECT MAX(c.year)
    INTO lv_latest_year
    FROM BLS.CPI_U c
   WHERE c.series_id = lv_series_id;

  IF lv_periodicity = 'monthly' THEN
    -- Average only months that exist; assumes VALUE is numeric text.
    SELECT AVG(TO_NUMBER(c.value))
      INTO lv_avg_value
      FROM BLS.CPI_U c
     WHERE c.series_id = lv_series_id
       AND c.year = lv_latest_year
       AND c.period IN ('M01','M02','M03','M04','M05','M06','M07','M08','M09','M10','M11','M12');

    DBMS_OUTPUT.PUT_LINE('Monthly summary for year ' || lv_latest_year || ' -> AVG=' || TO_CHAR(lv_avg_value));
  ELSE
    -- Use the annual (M13) value.
    SELECT TO_NUMBER(c.value)
      INTO lv_annual_value
      FROM BLS.CPI_U c
     WHERE c.series_id = lv_series_id
       AND c.year = lv_latest_year
       AND c.period = 'M13';

    DBMS_OUTPUT.PUT_LINE('Annual summary for year ' || lv_latest_year || ' (M13) -> VALUE=' || TO_CHAR(lv_annual_value));
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data encountered in VALUE; cannot compute summary.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

