  lv_cnt_cpi_u_year    NUMBER;
  lv_cnt_c_cpi_u_year  NUMBER;
  lv_pct_threshold  NUMBER := 20;
  lv_flagged_cnt NUMBER := 0;
  co_report_limit CONSTANT PLS_INTEGER := 15;
BEGIN
  SELECT c.series_id INTO lv_series_id FROM BLS.CPI_U c WHERE c.area_name = lv_area_name AND c.item_name = lv_item_name GROUP BY c.series_id;
  SELECT MAX(c.year) INTO lv_latest_year FROM BLS.CPI_U c WHERE c.series_id = lv_series_id;
  DBMS_OUTPUT.PUT_LINE('Series: ' || lv_series_id || ' | Latest year: ' || lv_latest_year);
  SELECT COUNT(*) INTO lv_cnt_cpi_u_year FROM BLS.CPI_U c WHERE c.series_id = lv_series_id AND c.year = lv_latest_year;
  SELECT COUNT(*) INTO lv_cnt_c_cpi_u_year FROM BLS.C_CPI_U cc WHERE cc.series_id = lv_series_id AND cc.year = lv_latest_year;
  DBMS_OUTPUT.PUT_LINE('Coverage check for latest year -> CPI_U=' || lv_cnt_cpi_u_year || ', C_CPI_U=' || lv_cnt_c_cpi_u_year);
  DBMS_OUTPUT.PUT_LINE('Flagged observations (max rows = ' || co_report_limit || ', threshold=' || TO_CHAR(lv_pct_threshold) || '%):');
  FOR r IN (
    WITH ordered_vals AS (
      SELECT c.c_date, c.period, c.value,
             CASE WHEN REGEXP_LIKE(c.value, '^[-]?[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(c.value) ELSE NULL END AS value_num,
             LAG(CASE WHEN REGEXP_LIKE(c.value, '^[-]?[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(c.value) ELSE NULL END) OVER (ORDER BY c.c_date) AS prev_value_num
        FROM BLS.CPI_U c
       WHERE c.series_id = lv_series_id AND c.year = lv_latest_year
    ), flagged AS (
      SELECT o.c_date, o.period, o.value,
             CASE WHEN o.value_num IS NULL THEN NULL WHEN o.prev_value_num IS NULL THEN NULL WHEN o.prev_value_num = 0 THEN NULL ELSE ROUND(ABS((o.value_num - o.prev_value_num) / o.prev_value_num) * 100, 2) END AS pct_change,
             CASE WHEN o.value_num IS NULL THEN 1 WHEN o.prev_value_num IS NULL THEN 0 WHEN o.prev_value_num = 0 THEN 0 WHEN ROUND(ABS((o.value_num - o.prev_value_num) / o.prev_value_num) * 100, 2) > lv_pct_threshold THEN 1 ELSE 0 END AS is_flagged
        FROM ordered_vals o
    )
    SELECT f.c_date, f.period, f.value, f.pct_change FROM flagged f WHERE f.is_flagged = 1 ORDER BY f.c_date DESC FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_flagged_cnt := lv_flagged_cnt + 1;
    DBMS_OUTPUT.PUT_LINE('  ' || TO_CHAR(r.c_date, 'YYYY-MM-DD') || ' | ' || r.period || ' | ' || r.value || ' | pct_change=' || TO_CHAR(r.pct_change));
  END LOOP;
  IF lv_flagged_cnt = 0 THEN DBMS_OUTPUT.PUT_LINE('No flagged observations found for the latest year.'); END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

