CREATE OR REPLACE PROCEDURE cpi_print_area_year_snapshot(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_area_name IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: area and year are required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI snapshot - area=' || p_area_name || ', year=' || p_year || ', max rows=' || co_report_limit);

  FOR r IN (
    SELECT c.series_id,
           c.period,
           c.item_name,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.year = p_year
     ORDER BY c.c_date DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE('series_id=' || r.series_id || ', period=' || r.period || ', item_name=' || r.item_name || ', value=' || r.value);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No CPI rows found for the provided area/year.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No CPI rows found for the provided area/year.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_print_area_year_snapshot;
/

CREATE OR REPLACE FUNCTION cpi_get_latest_value(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) RETURN NUMBER IS
  lv_value_raw BLS.CPI_U.value%TYPE;
  lv_value_num NUMBER;
BEGIN
  IF p_area_name IS NULL OR p_item_name IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: area, item, and year are required.');
    RETURN NULL;
  END IF;

  SELECT c.value
    INTO lv_value_raw
    FROM (
      SELECT value
        FROM BLS.CPI_U
       WHERE area_name = p_area_name
         AND item_name = p_item_name
         AND year = p_year
       ORDER BY c_date DESC
    ) c
   WHERE ROWNUM = 1;

  lv_value_num := TO_NUMBER(lv_value_raw);
  DBMS_OUTPUT.PUT_LINE('Latest CPI value (numeric)=' || TO_CHAR(lv_value_num));
  RETURN lv_value_num;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No CPI row found for the provided area/item/year.');
    RETURN NULL;
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad CPI value (non-numeric) encountered.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END cpi_get_latest_value;
/

