CREATE OR REPLACE PROCEDURE cpi_print_labeled_snapshot(
  p_area_name      IN BLS.CPI_U.area_name%TYPE,
  p_year           IN BLS.CPI_U.year%TYPE,
  p_high_threshold IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
  lv_value_num    NUMBER;
  lv_label        VARCHAR2(10);
BEGIN
  IF p_area_name IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: area and year are required.');
    RETURN;
  END IF;

  IF p_high_threshold IS NULL OR p_high_threshold < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid threshold: must be non-null and >= 0.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Labeled CPI snapshot - area=' || p_area_name || ', year=' || p_year || ', threshold=' || TO_CHAR(p_high_threshold) || ', max rows=' || co_report_limit);

  FOR r IN (
    SELECT c.series_id,
           c.period,
           c.item_name,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.year = p_year
     ORDER BY c.c_date DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    BEGIN
      lv_value_num := TO_NUMBER(r.value);
      IF lv_value_num >= p_high_threshold THEN
        lv_label := 'HIGH';
      ELSE
        lv_label := 'NORMAL';
      END IF;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Non-numeric value encountered; defaulting label to NORMAL.');
        lv_label := 'NORMAL';
    END;

    DBMS_OUTPUT.PUT_LINE('series_id=' || r.series_id || ', period=' || r.period || ', item_name=' || r.item_name || ', value=' || r.value || ', label=' || lv_label);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No CPI rows found for the provided area/year.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No CPI rows found for the provided area/year.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_print_labeled_snapshot;
/

