CREATE OR REPLACE PROCEDURE cpi_compare_sources(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_area_name IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: area and year are required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI source comparison - area=' || p_area_name || ', year=' || p_year || ', max rows=' || co_report_limit);

  FOR r IN (
    WITH u_latest AS (
      SELECT u.item_name,
             TO_NUMBER(u.value) AS val_num,
             ROW_NUMBER() OVER (PARTITION BY u.item_name ORDER BY u.c_date DESC) AS rn
        FROM BLS.CPI_U u
       WHERE u.area_name = p_area_name
         AND u.year = p_year
         AND REGEXP_LIKE(u.value, '^[0-9]+(\.[0-9]+)?$')
    ),
    c_latest AS (
      SELECT c.item_name,
             TO_NUMBER(c.value) AS val_num,
             ROW_NUMBER() OVER (PARTITION BY c.item_name ORDER BY c.c_date DESC) AS rn
        FROM BLS.C_CPI_U c
       WHERE c.area_name = p_area_name
         AND c.year = p_year
         AND REGEXP_LIKE(c.value, '^[0-9]+(\.[0-9]+)?$')
    )
    SELECT u.item_name,
           ABS(u.val_num - c.val_num) AS abs_diff
      FROM u_latest u
      INNER JOIN c_latest c
        ON c.item_name = u.item_name
     WHERE u.rn = 1
       AND c.rn = 1
     ORDER BY abs_diff DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE('item_name=' || r.item_name || ', abs_diff=' || TO_CHAR(r.abs_diff));
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No comparable numeric CPI pairs found for the provided area/year.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No comparable numeric CPI pairs found for the provided area/year.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_compare_sources;
/

