question:
Start the profitability review by producing a compact channel-and-category margin snapshot for the earliest calendar year in the warehouse. Go through each summarized row, classify low-margin combinations, and make sure the report never stops with an unhandled error.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Channel margin review for calendar year ' || lv_year);
DBMS_OUTPUT.PUT_LINE('No calendar years found.');
DBMS_OUTPUT.PUT_LINE('Watch: ' || rec_channel.channel_desc || ' / ' || rec_channel.prod_category || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
DBMS_OUTPUT.PUT_LINE('Healthy: ' || rec_channel.channel_desc || ' / ' || rec_channel.prod_category || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
DBMS_OUTPUT.PUT_LINE('No channel margin rows found.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_year COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
  lv_margin NUMBER;
  lv_margin_pct NUMBER;

  CURSOR cur_channel_margin(p_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE) IS
    SELECT ranked.channel_desc,
           ranked.prod_category,
           ranked.total_sales,
           ranked.total_cost,
           ranked.sales_rows
      FROM (
            SELECT ch.channel_desc,
                   pr.prod_category,
                   SUM(s.amount_sold) AS total_sales,
                   SUM(s.quantity_sold * NVL(cs.unit_cost, 0)) AS total_cost,
                   COUNT(*) AS sales_rows
              FROM COMPLEX_ORACLE.SALES s
              INNER JOIN COMPLEX_ORACLE.COSTS cs
                ON cs.prod_id = s.prod_id
               AND cs.time_id = s.time_id
               AND cs.channel_id = s.channel_id
               AND cs.promo_id = s.promo_id
              INNER JOIN COMPLEX_ORACLE.CHANNELS ch
                ON ch.channel_id = s.channel_id
              INNER JOIN COMPLEX_ORACLE.PRODUCTS pr
                ON pr.prod_id = s.prod_id
              INNER JOIN COMPLEX_ORACLE.TIMES tm
                ON tm.time_id = s.time_id
             WHERE tm.calendar_year = p_year
             GROUP BY ch.channel_desc, pr.prod_category
            HAVING SUM(s.amount_sold) > 0
             ORDER BY total_sales DESC
           ) ranked
     WHERE ROWNUM <= co_report_limit;

  rec_channel cur_channel_margin%ROWTYPE;
BEGIN
  SELECT MIN(t.calendar_year)
    INTO lv_year
    FROM COMPLEX_ORACLE.TIMES t;

  IF lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No calendar years found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Channel margin review for calendar year ' || lv_year);

  OPEN cur_channel_margin(lv_year);
  LOOP
    FETCH cur_channel_margin INTO rec_channel;
    EXIT WHEN cur_channel_margin%NOTFOUND;

    lv_margin := rec_channel.total_sales - rec_channel.total_cost;
    IF rec_channel.total_sales = 0 THEN
      lv_margin_pct := 0;
    ELSE
      lv_margin_pct := ROUND((lv_margin / rec_channel.total_sales) * 100, 2);
    END IF;

    IF lv_margin_pct < 10 THEN
      DBMS_OUTPUT.PUT_LINE('Watch: ' || rec_channel.channel_desc || ' / ' || rec_channel.prod_category || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Healthy: ' || rec_channel.channel_desc || ' / ' || rec_channel.prod_category || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
    END IF;
  END LOOP;

  IF cur_channel_margin%ROWCOUNT = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No channel margin rows found.');
  END IF;

  CLOSE cur_channel_margin;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    IF cur_channel_margin%ISOPEN THEN
      CLOSE cur_channel_margin;
    END IF;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    IF cur_channel_margin%ISOPEN THEN
      CLOSE cur_channel_margin;
    END IF;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF cur_channel_margin%ISOPEN THEN
      CLOSE cur_channel_margin;
    END IF;
END;
/

