question:
Now turn the first profitability snapshot into a reusable routine. Let the business user provide a calendar year and channel class, then report category margins for that slice. Validate missing inputs and return a friendly message when the year does not exist or no categories match.

Requirements:
Procedure Name: REPORT_CATEGORY_MARGIN
Parameters: p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE
p_channel_class IN COMPLEX_ORACLE.CHANNELS.channel_class%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Year and channel class are required.');
DBMS_OUTPUT.PUT_LINE('Category margin review for ' || p_channel_class || ' in ' || p_calendar_year);
DBMS_OUTPUT.PUT_LINE('Category ' || rec_category.prod_category || ' is low margin at ' || TO_CHAR(lv_margin_pct) || '% from sales ' || TO_CHAR(rec_category.total_sales));
DBMS_OUTPUT.PUT_LINE('Category ' || rec_category.prod_category || ' is target margin at ' || TO_CHAR(lv_margin_pct) || '% from sales ' || TO_CHAR(rec_category.total_sales));
DBMS_OUTPUT.PUT_LINE('Category ' || rec_category.prod_category || ' is strong margin at ' || TO_CHAR(lv_margin_pct) || '% from sales ' || TO_CHAR(rec_category.total_sales));
DBMS_OUTPUT.PUT_LINE('No categories matched the requested filters.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_category_margin(
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
  p_channel_class IN COMPLEX_ORACLE.CHANNELS.channel_class%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_year COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
  lv_margin NUMBER;
  lv_margin_pct NUMBER;
  lv_found BOOLEAN := FALSE;

  CURSOR cur_category_margin(
    cp_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
    cp_class IN COMPLEX_ORACLE.CHANNELS.channel_class%TYPE
  ) IS
    SELECT ranked.prod_category,
           ranked.total_sales,
           ranked.total_cost,
           ranked.sales_rows
      FROM (
            SELECT pr.prod_category,
                   SUM(s.amount_sold) AS total_sales,
                   SUM(s.quantity_sold * NVL(cs.unit_cost, 0)) AS total_cost,
                   COUNT(*) AS sales_rows
              FROM COMPLEX_ORACLE.SALES s
              INNER JOIN COMPLEX_ORACLE.COSTS cs
                ON cs.prod_id = s.prod_id
               AND cs.time_id = s.time_id
               AND cs.channel_id = s.channel_id
               AND cs.promo_id = s.promo_id
              INNER JOIN COMPLEX_ORACLE.CHANNELS ch
                ON ch.channel_id = s.channel_id
              INNER JOIN COMPLEX_ORACLE.PRODUCTS pr
                ON pr.prod_id = s.prod_id
              INNER JOIN COMPLEX_ORACLE.TIMES tm
                ON tm.time_id = s.time_id
             WHERE tm.calendar_year = cp_year
               AND ch.channel_class = cp_class
             GROUP BY pr.prod_category
            HAVING SUM(s.amount_sold) > 0
             ORDER BY total_sales DESC
           ) ranked
     WHERE ROWNUM <= co_report_limit;

  rec_category cur_category_margin%ROWTYPE;
BEGIN
  IF p_calendar_year IS NULL OR p_channel_class IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year and channel class are required.');
    RETURN;
  END IF;

  SELECT yr.calendar_year
    INTO lv_year
    FROM (
          SELECT DISTINCT t.calendar_year AS calendar_year
            FROM COMPLEX_ORACLE.TIMES t
           WHERE t.calendar_year = p_calendar_year
         ) yr;

  DBMS_OUTPUT.PUT_LINE('Category margin review for ' || p_channel_class || ' in ' || p_calendar_year);

  OPEN cur_category_margin(p_calendar_year, p_channel_class);
  LOOP
    FETCH cur_category_margin INTO rec_category;
    EXIT WHEN cur_category_margin%NOTFOUND;
    lv_found := TRUE;

    lv_margin := rec_category.total_sales - rec_category.total_cost;
    IF rec_category.total_sales = 0 THEN
      lv_margin_pct := 0;
    ELSE
      lv_margin_pct := ROUND((lv_margin / rec_category.total_sales) * 100, 2);
    END IF;

    IF lv_margin_pct < 10 THEN
      DBMS_OUTPUT.PUT_LINE('Category ' || rec_category.prod_category || ' is low margin at ' || TO_CHAR(lv_margin_pct) || '% from sales ' || TO_CHAR(rec_category.total_sales));
    ELSIF lv_margin_pct < 25 THEN
      DBMS_OUTPUT.PUT_LINE('Category ' || rec_category.prod_category || ' is target margin at ' || TO_CHAR(lv_margin_pct) || '% from sales ' || TO_CHAR(rec_category.total_sales));
    ELSE
      DBMS_OUTPUT.PUT_LINE('Category ' || rec_category.prod_category || ' is strong margin at ' || TO_CHAR(lv_margin_pct) || '% from sales ' || TO_CHAR(rec_category.total_sales));
    END IF;
  END LOOP;

  IF NOT lv_found THEN
    DBMS_OUTPUT.PUT_LINE('No categories matched the requested filters.');
  END IF;

  CLOSE cur_category_margin;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    IF cur_category_margin%ISOPEN THEN
      CLOSE cur_category_margin;
    END IF;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    IF cur_category_margin%ISOPEN THEN
      CLOSE cur_category_margin;
    END IF;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF cur_category_margin%ISOPEN THEN
      CLOSE cur_category_margin;
    END IF;
END report_category_margin;
/

CREATE OR REPLACE PACKAGE sales_margin_coach IS
  FUNCTION get_revenue_band(p_amount IN NUMBER) RETURN VARCHAR2;

  PROCEDURE report_top_customers(
    p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
    p_channel_class IN COMPLEX_ORACLE.CHANNELS.channel_class%TYPE,
    p_min_amount IN NUMBER DEFAULT 0
  );
END sales_margin_coach;
/

CREATE OR REPLACE PACKAGE BODY sales_margin_coach IS
  FUNCTION get_revenue_band(p_amount IN NUMBER) RETURN VARCHAR2 IS
  BEGIN
    IF p_amount IS NULL OR p_amount = 0 THEN
      RETURN 'NO SALES';
    ELSIF p_amount < 1000 THEN
      RETURN 'LOW';
    ELSIF p_amount < 10000 THEN
      RETURN 'MEDIUM';
    ELSE
      RETURN 'HIGH';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN 'ERROR';
  END get_revenue_band;

  PROCEDURE report_top_customers(
    p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
    p_channel_class IN COMPLEX_ORACLE.CHANNELS.channel_class%TYPE,
    p_min_amount IN NUMBER DEFAULT 0
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for account-manager review
    lv_year COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
    lv_found BOOLEAN := FALSE;

    CURSOR cur_customers(
      cp_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
      cp_class IN COMPLEX_ORACLE.CHANNELS.channel_class%TYPE,
      cp_min_amount IN NUMBER
    ) IS
      SELECT ranked.cust_id,
             ranked.cust_first_name,
             ranked.cust_last_name,
             ranked.country_name,
             ranked.total_amount,
             ranked.sale_count
        FROM (
              SELECT cu.cust_id,
                     cu.cust_first_name,
                     cu.cust_last_name,
                     cn.country_name,
                     SUM(s.amount_sold) AS total_amount,
                     COUNT(*) AS sale_count
                FROM COMPLEX_ORACLE.SALES s
                INNER JOIN COMPLEX_ORACLE.TIMES tm
                  ON tm.time_id = s.time_id
                INNER JOIN COMPLEX_ORACLE.CHANNELS ch
                  ON ch.channel_id = s.channel_id
                INNER JOIN COMPLEX_ORACLE.CUSTOMERS cu
                  ON cu.cust_id = s.cust_id
                INNER JOIN COMPLEX_ORACLE.COUNTRIES cn
                  ON cn.country_id = cu.country_id
               WHERE tm.calendar_year = cp_year
                 AND ch.channel_class = cp_class
               GROUP BY cu.cust_id, cu.cust_first_name, cu.cust_last_name, cn.country_name
              HAVING SUM(s.amount_sold) >= cp_min_amount
               ORDER BY total_amount DESC
             ) ranked
       WHERE ROWNUM <= co_report_limit;

    rec_customer cur_customers%ROWTYPE;
  BEGIN
    IF p_calendar_year IS NULL OR p_channel_class IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Year and channel class are required.');
      RETURN;
    END IF;

    SELECT yr.calendar_year
      INTO lv_year
      FROM (
            SELECT DISTINCT t.calendar_year AS calendar_year
              FROM COMPLEX_ORACLE.TIMES t
             WHERE t.calendar_year = p_calendar_year
           ) yr;

    DBMS_OUTPUT.PUT_LINE('Top customer review for ' || p_channel_class || ' in ' || p_calendar_year);

    OPEN cur_customers(p_calendar_year, p_channel_class, NVL(p_min_amount, 0));
    LOOP
      FETCH cur_customers INTO rec_customer;
      EXIT WHEN cur_customers%NOTFOUND;
      lv_found := TRUE;
      DBMS_OUTPUT.PUT_LINE('Customer ' || rec_customer.cust_id || ' ' || rec_customer.cust_last_name || ': ' || get_revenue_band(rec_customer.total_amount) || ' revenue ' || TO_CHAR(rec_customer.total_amount));
    END LOOP;

    IF NOT lv_found THEN
      DBMS_OUTPUT.PUT_LINE('No customers matched the requested thresholds.');
    END IF;

    CLOSE cur_customers;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      IF cur_customers%ISOPEN THEN
        CLOSE cur_customers;
      END IF;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      IF cur_customers%ISOPEN THEN
        CLOSE cur_customers;
      END IF;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      IF cur_customers%ISOPEN THEN
        CLOSE cur_customers;
      END IF;
  END report_top_customers;
END sales_margin_coach;
/

question:
Finish the workflow by combining the margin and customer context into a promotion-risk report. For a calendar year and country region, review promotion/channel combinations and flag any whose margin percentage is below the user-supplied threshold.

Requirements:
Procedure Name: REPORT_PROMO_PROFIT_ALERTS
Parameters: p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE
p_country_region IN COMPLEX_ORACLE.COUNTRIES.country_region%TYPE
p_min_margin_pct IN NUMBER DEFAULT 15
Output: DBMS_OUTPUT.PUT_LINE('Year, country region, and minimum margin percent are required.');
DBMS_OUTPUT.PUT_LINE('Promotion margin alerts for ' || p_country_region || ' in ' || p_calendar_year);
DBMS_OUTPUT.PUT_LINE('At risk promo ' || rec_promo.promo_name || ' via ' || rec_promo.channel_desc || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
DBMS_OUTPUT.PUT_LINE('Monitor promo ' || rec_promo.promo_name || ' via ' || rec_promo.channel_desc || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
DBMS_OUTPUT.PUT_LINE('No promotion margin alerts matched the requested filters.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_promo_profit_alerts(
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
  p_country_region IN COMPLEX_ORACLE.COUNTRIES.country_region%TYPE,
  p_min_margin_pct IN NUMBER DEFAULT 15
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for executive review
  lv_year COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
  lv_region COMPLEX_ORACLE.COUNTRIES.country_region%TYPE;
  lv_margin NUMBER;
  lv_margin_pct NUMBER;
  lv_found BOOLEAN := FALSE;

  CURSOR cur_promo_alerts(
    cp_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
    cp_region IN COMPLEX_ORACLE.COUNTRIES.country_region%TYPE
  ) IS
    SELECT ranked.promo_name,
           ranked.channel_desc,
           ranked.total_sales,
           ranked.total_cost,
           ranked.sale_count
      FROM (
            SELECT pm.promo_name,
                   ch.channel_desc,
                   SUM(s.amount_sold) AS total_sales,
                   SUM(s.quantity_sold * NVL(cs.unit_cost, 0)) AS total_cost,
                   COUNT(*) AS sale_count
              FROM COMPLEX_ORACLE.SALES s
              INNER JOIN COMPLEX_ORACLE.COSTS cs
                ON cs.prod_id = s.prod_id
               AND cs.time_id = s.time_id
               AND cs.channel_id = s.channel_id
               AND cs.promo_id = s.promo_id
              INNER JOIN COMPLEX_ORACLE.TIMES tm
                ON tm.time_id = s.time_id
              INNER JOIN COMPLEX_ORACLE.CUSTOMERS cu
                ON cu.cust_id = s.cust_id
              INNER JOIN COMPLEX_ORACLE.COUNTRIES cn
                ON cn.country_id = cu.country_id
              INNER JOIN COMPLEX_ORACLE.CHANNELS ch
                ON ch.channel_id = s.channel_id
              INNER JOIN COMPLEX_ORACLE.PROMOTIONS pm
                ON pm.promo_id = s.promo_id
             WHERE tm.calendar_year = cp_year
               AND cn.country_region = cp_region
             GROUP BY pm.promo_name, ch.channel_desc
            HAVING SUM(s.amount_sold) > 0
             ORDER BY total_sales DESC
           ) ranked
     WHERE ROWNUM <= co_report_limit;

  rec_promo cur_promo_alerts%ROWTYPE;
BEGIN
  IF p_calendar_year IS NULL OR p_country_region IS NULL OR p_min_margin_pct IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year, country region, and minimum margin percent are required.');
    RETURN;
  END IF;

  SELECT yr.calendar_year
    INTO lv_year
    FROM (
          SELECT DISTINCT t.calendar_year AS calendar_year
            FROM COMPLEX_ORACLE.TIMES t
           WHERE t.calendar_year = p_calendar_year
         ) yr;

  SELECT rg.country_region
    INTO lv_region
    FROM (
          SELECT DISTINCT c.country_region AS country_region
            FROM COMPLEX_ORACLE.COUNTRIES c
           WHERE c.country_region = p_country_region
         ) rg;

  DBMS_OUTPUT.PUT_LINE('Promotion margin alerts for ' || p_country_region || ' in ' || p_calendar_year);

  OPEN cur_promo_alerts(lv_year, lv_region);
  LOOP
    FETCH cur_promo_alerts INTO rec_promo;
    EXIT WHEN cur_promo_alerts%NOTFOUND;
    lv_found := TRUE;

    lv_margin := rec_promo.total_sales - rec_promo.total_cost;
    IF rec_promo.total_sales = 0 THEN
      lv_margin_pct := 0;
    ELSE
      lv_margin_pct := ROUND((lv_margin / rec_promo.total_sales) * 100, 2);
    END IF;

    IF lv_margin_pct < p_min_margin_pct THEN
      DBMS_OUTPUT.PUT_LINE('At risk promo ' || rec_promo.promo_name || ' via ' || rec_promo.channel_desc || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Monitor promo ' || rec_promo.promo_name || ' via ' || rec_promo.channel_desc || ' margin ' || TO_CHAR(lv_margin_pct) || '%');
    END IF;
  END LOOP;

  IF NOT lv_found THEN
    DBMS_OUTPUT.PUT_LINE('No promotion margin alerts matched the requested filters.');
  END IF;

  CLOSE cur_promo_alerts;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    IF cur_promo_alerts%ISOPEN THEN
      CLOSE cur_promo_alerts;
    END IF;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    IF cur_promo_alerts%ISOPEN THEN
      CLOSE cur_promo_alerts;
    END IF;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF cur_promo_alerts%ISOPEN THEN
      CLOSE cur_promo_alerts;
    END IF;
END report_promo_profit_alerts;
/

