CREATE OR REPLACE PACKAGE BODY fertility_pkg IS
  PROCEDURE print_country_year_rates(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF p_country_name IS NULL OR p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input country and year are required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Fertility report for ' || p_country_name || ' in ' || p_year);

    FOR rec IN (
      SELECT a.country_name,
             a.year,
             a.total_fertility_rate
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
       WHERE a.country_name = p_country_name
         AND a.year = p_year
         AND ROWNUM <= co_report_limit
       ORDER BY a.country_name, a.year
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE('Country=' || rec.country_name || ', Year=' || rec.year || ', TFR=' || rec.total_fertility_rate);
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_country_year_rates;

  PROCEDURE check_tfr_quality(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
    lv_tfr_num      NUMBER;
  BEGIN
    IF p_country_name IS NULL OR p_start_year IS NULL OR p_end_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input country and year range are required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Quality check for ' || p_country_name || ' from ' || p_start_year || ' to ' || p_end_year);

    FOR rec IN (
      SELECT a.year,
             a.total_fertility_rate
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
       WHERE a.country_name = p_country_name
         AND a.year BETWEEN p_start_year AND p_end_year
         AND ROWNUM <= co_report_limit
       ORDER BY a.year
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;

      BEGIN
        lv_tfr_num := TO_NUMBER(rec.total_fertility_rate);
      EXCEPTION
        WHEN VALUE_ERROR THEN
          DBMS_OUTPUT.PUT_LINE('Year=' || rec.year || ': rate not numeric, skipped');
          CONTINUE;
        WHEN OTHERS THEN
          DBMS_OUTPUT.PUT_LINE('Year=' || rec.year || ': rate not numeric, skipped');
          CONTINUE;
      END;

      IF lv_tfr_num BETWEEN 0 AND 10 THEN
        DBMS_OUTPUT.PUT_LINE('Year=' || rec.year || ': OK (TFR=' || TO_CHAR(lv_tfr_num) || ')');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Year=' || rec.year || ': WARN (TFR=' || TO_CHAR(lv_tfr_num) || ')');
      END IF;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END check_tfr_quality;
END fertility_pkg;
/

CREATE OR REPLACE PROCEDURE report_cpi_area_profile(
  p_area_code IN BLS.CPI_U.area_code%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for dashboard readability
  lv_area_name    BLS.CPI_U.area_name%TYPE;
  lv_rows_printed NUMBER := 0;

  CURSOR c_items(cp_area_code BLS.CPI_U.area_code%TYPE, cp_year BLS.CPI_U.year%TYPE) IS
    SELECT rpt.item_code,
           rpt.item_name,
           rpt.obs_count,
           rpt.avg_value,
           rpt.min_value,
           rpt.max_value
      FROM (
            SELECT cu.item_code,
                   cu.item_name,
                   COUNT(*) AS obs_count,
                   ROUND(AVG(TO_NUMBER(cu.value)), 3) AS avg_value,
                   MIN(TO_NUMBER(cu.value)) AS min_value,
                   MAX(TO_NUMBER(cu.value)) AS max_value
              FROM BLS.CPI_U cu
             WHERE cu.area_code = cp_area_code
               AND cu.year = cp_year
               AND REGEXP_LIKE(cu.value, '^-?[0-9]+(\.[0-9]+)?$')
             GROUP BY cu.item_code, cu.item_name
             ORDER BY avg_value DESC
           ) rpt
     WHERE ROWNUM <= co_report_limit;

  lr_item c_items%ROWTYPE;
BEGIN
  IF p_area_code IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Area code and year are required.');
    RETURN;
  END IF;

  SELECT area_lookup.area_name
    INTO lv_area_name
    FROM (
          SELECT DISTINCT cu.area_name
            FROM BLS.CPI_U cu
           WHERE cu.area_code = p_area_code
             AND cu.year = p_year
         ) area_lookup
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('CPI area profile for ' || lv_area_name || ' (' || p_area_code || ') in ' || p_year);

  OPEN c_items(p_area_code, p_year);
  LOOP
    FETCH c_items INTO lr_item;
    EXIT WHEN c_items%NOTFOUND;
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE('Item ' || lr_item.item_code || ' - ' || lr_item.item_name || ': observations=' || lr_item.obs_count || ', avg=' || lr_item.avg_value || ', min=' || lr_item.min_value || ', max=' || lr_item.max_value);
  END LOOP;
  CLOSE c_items;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No CPI observations matched the filter.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_items%ISOPEN THEN
      CLOSE c_items;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_items%ISOPEN THEN
      CLOSE c_items;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF c_items%ISOPEN THEN
      CLOSE c_items;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_cpi_area_profile;
/

CREATE OR REPLACE PROCEDURE report_cpi_employment_signal(
  p_area_code IN BLS.CPI_U.area_code%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Keep the cross-domain signal concise
  lv_area_name    BLS.CPI_U.area_name%TYPE;
  lv_rows_printed NUMBER := 0;
  lv_signal       VARCHAR2(80);

  CURSOR c_signal(cp_area_code BLS.CPI_U.area_code%TYPE, cp_year BLS.CPI_U.year%TYPE) IS
    WITH cpi AS (
      SELECT cu.item_code,
             cu.item_name,
             ROUND(AVG(TO_NUMBER(cu.value)), 3) AS avg_cpi
        FROM BLS.CPI_U cu
       WHERE cu.area_code = cp_area_code
         AND cu.year = cp_year
         AND REGEXP_LIKE(cu.value, '^-?[0-9]+(\.[0-9]+)?$')
       GROUP BY cu.item_code, cu.item_name
    ),
    chained AS (
      SELECT ccu.item_code,
             ROUND(AVG(TO_NUMBER(ccu.value)), 3) AS avg_chained_cpi
        FROM BLS.C_CPI_U ccu
       WHERE ccu.area_code = cp_area_code
         AND ccu.year = cp_year
         AND REGEXP_LIKE(ccu.value, '^-?[0-9]+(\.[0-9]+)?$')
       GROUP BY ccu.item_code
    ),
    employment AS (
      SELECT ROUND(AVG(TO_NUMBER(ehe.value)), 3) AS avg_employment
        FROM BLS.EMPLOYMENT_HOURS_EARNINGS ehe
       WHERE ehe.year = cp_year
         AND REGEXP_LIKE(ehe.value, '^-?[0-9]+(\.[0-9]+)?$')
    )
    SELECT signal_rows.item_code,
           signal_rows.item_name,
           signal_rows.avg_cpi,
           signal_rows.avg_chained_cpi,
           signal_rows.index_gap,
           signal_rows.avg_employment
      FROM (
            SELECT cpi.item_code,
                   cpi.item_name,
                   cpi.avg_cpi,
                   chained.avg_chained_cpi,
                   ROUND(cpi.avg_cpi - chained.avg_chained_cpi, 3) AS index_gap,
                   employment.avg_employment
              FROM cpi
                   INNER JOIN chained
                     ON chained.item_code = cpi.item_code
                   CROSS JOIN employment
             ORDER BY ABS(cpi.avg_cpi - chained.avg_chained_cpi) DESC
           ) signal_rows
     WHERE ROWNUM <= co_report_limit;

  lr_signal c_signal%ROWTYPE;
BEGIN
  IF p_area_code IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Area code and year are required.');
    RETURN;
  END IF;

  SELECT MAX(cu.area_name)
    INTO lv_area_name
    FROM BLS.CPI_U cu
   WHERE cu.area_code = p_area_code
     AND cu.year = p_year;

  IF lv_area_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No CPI data found for the requested signal.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI/employment signal for ' || lv_area_name || ' in ' || p_year);

  OPEN c_signal(p_area_code, p_year);
  LOOP
    FETCH c_signal INTO lr_signal;
    EXIT WHEN c_signal%NOTFOUND;
    lv_rows_printed := lv_rows_printed + 1;

    IF lr_signal.index_gap >= 2 THEN
      lv_signal := 'CPI higher than chained CPI';
    ELSIF lr_signal.index_gap <= -2 THEN
      lv_signal := 'Chained CPI higher than CPI';
    ELSE
      lv_signal := 'Indexes closely aligned';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Item ' || lr_signal.item_code || ' - ' || lr_signal.item_name || ': cpi=' || lr_signal.avg_cpi || ', chained=' || lr_signal.avg_chained_cpi || ', gap=' || lr_signal.index_gap || ', employment_avg=' || lr_signal.avg_employment || ', signal=' || lv_signal);
  END LOOP;
  CLOSE c_signal;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No joined CPI and employment signal rows matched the filter.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_signal%ISOPEN THEN
      CLOSE c_signal;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_signal%ISOPEN THEN
      CLOSE c_signal;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF c_signal%ISOPEN THEN
      CLOSE c_signal;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_cpi_employment_signal;
/

CREATE OR REPLACE PROCEDURE diagnose_bls_numeric_quality(
  p_year IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- More than enough for the four source feeds
  lv_rows_printed NUMBER := 0;

  CURSOR c_quality(cp_year BLS.CPI_U.year%TYPE) IS
    SELECT quality_rows.source_name,
           quality_rows.total_rows,
           quality_rows.bad_value_rows,
           quality_rows.missing_date_rows,
           ROUND(CASE
                   WHEN quality_rows.total_rows = 0 THEN 0
                   ELSE (quality_rows.bad_value_rows / quality_rows.total_rows) * 100
                 END, 2) AS bad_value_pct
      FROM (
            SELECT 'CPI_U' AS source_name,
                   COUNT(*) AS total_rows,
                   SUM(CASE WHEN cu.value IS NULL OR NOT REGEXP_LIKE(cu.value, '^-?[0-9]+(\.[0-9]+)?$') THEN 1 ELSE 0 END) AS bad_value_rows,
                   SUM(CASE WHEN cu.c_date IS NULL THEN 1 ELSE 0 END) AS missing_date_rows
              FROM BLS.CPI_U cu
             WHERE cu.year = cp_year
            UNION ALL
            SELECT 'C_CPI_U' AS source_name,
                   COUNT(*) AS total_rows,
                   SUM(CASE WHEN ccu.value IS NULL OR NOT REGEXP_LIKE(ccu.value, '^-?[0-9]+(\.[0-9]+)?$') THEN 1 ELSE 0 END) AS bad_value_rows,
                   SUM(CASE WHEN ccu.c_date IS NULL THEN 1 ELSE 0 END) AS missing_date_rows
              FROM BLS.C_CPI_U ccu
             WHERE ccu.year = cp_year
            UNION ALL
            SELECT 'EMPLOYMENT_HOURS_EARNINGS' AS source_name,
                   COUNT(*) AS total_rows,
                   SUM(CASE WHEN ehe.value IS NULL OR NOT REGEXP_LIKE(ehe.value, '^-?[0-9]+(\.[0-9]+)?$') THEN 1 ELSE 0 END) AS bad_value_rows,
                   SUM(CASE WHEN ehe.c_date IS NULL THEN 1 ELSE 0 END) AS missing_date_rows
              FROM BLS.EMPLOYMENT_HOURS_EARNINGS ehe
             WHERE ehe.year = cp_year
            UNION ALL
            SELECT 'UNEMPLOYMENT_CPS' AS source_name,
                   COUNT(*) AS total_rows,
                   SUM(CASE WHEN uc.value IS NULL OR NOT REGEXP_LIKE(uc.value, '^-?[0-9]+(\.[0-9]+)?$') THEN 1 ELSE 0 END) AS bad_value_rows,
                   SUM(CASE WHEN uc.c_date IS NULL THEN 1 ELSE 0 END) AS missing_date_rows
              FROM BLS.UNEMPLOYMENT_CPS uc
             WHERE uc.year = cp_year
           ) quality_rows
     WHERE ROWNUM <= co_report_limit
     ORDER BY quality_rows.source_name;

  lr_quality c_quality%ROWTYPE;
BEGIN
  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year is required for diagnostics.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Numeric quality diagnostic for year ' || p_year);

  OPEN c_quality(p_year);
  LOOP
    FETCH c_quality INTO lr_quality;
    EXIT WHEN c_quality%NOTFOUND;
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(lr_quality.source_name || ': total=' || lr_quality.total_rows || ', bad_value_rows=' || lr_quality.bad_value_rows || ', missing_date_rows=' || lr_quality.missing_date_rows || ', bad_value_pct=' || lr_quality.bad_value_pct);

    IF lr_quality.bad_value_rows > 0 THEN
      DBMS_OUTPUT.PUT_LINE('Root cause candidate: non-numeric VALUE data found in ' || lr_quality.source_name);
    ELSIF lr_quality.missing_date_rows > 0 THEN
      DBMS_OUTPUT.PUT_LINE('Root cause candidate: missing C_DATE values found in ' || lr_quality.source_name);
    ELSE
      DBMS_OUTPUT.PUT_LINE('No immediate numeric or date quality issue found in ' || lr_quality.source_name);
    END IF;
  END LOOP;
  CLOSE c_quality;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No diagnostic rows were produced.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_quality%ISOPEN THEN
      CLOSE c_quality;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_quality%ISOPEN THEN
      CLOSE c_quality;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF c_quality%ISOPEN THEN
      CLOSE c_quality;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END diagnose_bls_numeric_quality;
/

CREATE OR REPLACE PROCEDURE report_macro_watchlist(
  p_area_code IN BLS.CPI_U.area_code%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE,
  p_min_gap   IN NUMBER DEFAULT 3
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Watchlist output is capped for operational review
  lv_threshold    NUMBER := 3;
  lv_rows_printed NUMBER := 0;
  lv_severity     VARCHAR2(40);

  CURSOR c_watch(cp_area_code BLS.CPI_U.area_code%TYPE, cp_year BLS.CPI_U.year%TYPE, cp_threshold NUMBER) IS
    WITH cpi AS (
      SELECT cu.item_code,
             cu.item_name,
             ROUND(AVG(TO_NUMBER(cu.value)), 3) AS avg_cpi
        FROM BLS.CPI_U cu
       WHERE cu.area_code = cp_area_code
         AND cu.year = cp_year
         AND REGEXP_LIKE(cu.value, '^-?[0-9]+(\.[0-9]+)?$')
       GROUP BY cu.item_code, cu.item_name
    ),
    chained AS (
      SELECT ccu.item_code,
             ROUND(AVG(TO_NUMBER(ccu.value)), 3) AS avg_chained_cpi
        FROM BLS.C_CPI_U ccu
       WHERE ccu.area_code = cp_area_code
         AND ccu.year = cp_year
         AND REGEXP_LIKE(ccu.value, '^-?[0-9]+(\.[0-9]+)?$')
       GROUP BY ccu.item_code
    ),
    unemployment AS (
      SELECT ROUND(AVG(TO_NUMBER(uc.value)), 3) AS avg_unemployment
        FROM BLS.UNEMPLOYMENT_CPS uc
       WHERE uc.year = cp_year
         AND REGEXP_LIKE(uc.value, '^-?[0-9]+(\.[0-9]+)?$')
    ),
    wage AS (
      SELECT ROUND(AVG(TO_NUMBER(wm.value)), 3) AS avg_wage
        FROM BLS.WM wm
       WHERE wm.year = cp_year
         AND REGEXP_LIKE(wm.value, '^-?[0-9]+(\.[0-9]+)?$')
    )
    SELECT watch_rows.item_code,
           watch_rows.item_name,
           watch_rows.index_gap,
           watch_rows.avg_unemployment,
           watch_rows.avg_wage
      FROM (
            SELECT cpi.item_code,
                   cpi.item_name,
                   ROUND(cpi.avg_cpi - chained.avg_chained_cpi, 3) AS index_gap,
                   unemployment.avg_unemployment,
                   wage.avg_wage
              FROM cpi
                   INNER JOIN chained
                     ON chained.item_code = cpi.item_code
                   CROSS JOIN unemployment
                   CROSS JOIN wage
             WHERE ABS(cpi.avg_cpi - chained.avg_chained_cpi) >= cp_threshold
             ORDER BY ABS(cpi.avg_cpi - chained.avg_chained_cpi) DESC
           ) watch_rows
     WHERE ROWNUM <= co_report_limit;

  lr_watch c_watch%ROWTYPE;
BEGIN
  IF p_area_code IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Area code and year are required.');
    RETURN;
  END IF;

  IF p_min_gap IS NULL THEN
    lv_threshold := 3;
  ELSE
    lv_threshold := ABS(p_min_gap);
  END IF;

  DBMS_OUTPUT.PUT_LINE('Macro watchlist for area ' || p_area_code || ', year ' || p_year || ', threshold=' || lv_threshold);

  OPEN c_watch(p_area_code, p_year, lv_threshold);
  LOOP
    FETCH c_watch INTO lr_watch;
    EXIT WHEN c_watch%NOTFOUND;
    lv_rows_printed := lv_rows_printed + 1;

    IF ABS(lr_watch.index_gap) >= lv_threshold * 2 THEN
      lv_severity := 'High';
    ELSIF ABS(lr_watch.index_gap) >= lv_threshold THEN
      lv_severity := 'Moderate';
    ELSE
      lv_severity := 'Low';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Item ' || lr_watch.item_code || ' - ' || lr_watch.item_name || ': gap=' || lr_watch.index_gap || ', unemployment_avg=' || lr_watch.avg_unemployment || ', wage_avg=' || lr_watch.avg_wage || ', severity=' || lv_severity);
  END LOOP;
  CLOSE c_watch;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No macro watchlist rows exceeded the threshold.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_watch%ISOPEN THEN
      CLOSE c_watch;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_watch%ISOPEN THEN
      CLOSE c_watch;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    IF c_watch%ISOPEN THEN
      CLOSE c_watch;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Invalid numeric input.');
  WHEN OTHERS THEN
    IF c_watch%ISOPEN THEN
      CLOSE c_watch;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_macro_watchlist;
/

question:
You are building a quick operations report for SF bikeshare. Given a station name (exact match), print the station id/landmark/dockcount and then print up to 15 of the most recent status snapshots for that station (time, bikes available, docks available) in descending time order. If the station name is unknown, print a clear message instead of failing.

