Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_id || ' | ' || lv_station_name || ' | Landmark=' || lv_landmark || ' | Dockcount=' || lv_dockcount);
