DBMS_OUTPUT.PUT_LINE('As of ' || TO_CHAR(r.time, 'YYYY-MM-DD HH24:MI:SS') || ' bikes=' || r.bikes_available || ' docks=' || r.docks_available);
DBMS_OUTPUT.PUT_LINE('No status snapshots found for this station.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
