DECLARE
  lv_station_name  SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE := 'Harry Bridges Plaza (Ferry Building)';
  lv_station_id    SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE;

  lv_time          SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
  lv_bikes         SAN_FRANCISCO.BIKESHARE_STATUS.bikes_available%TYPE;
  lv_docks         SAN_FRANCISCO.BIKESHARE_STATUS.docks_available%TYPE;

  lv_utilization   NUMBER;
BEGIN
  SELECT s.station_id, s.name
    INTO lv_station_id, lv_station_name
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE s.name = lv_station_name;

  DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_id || ' | ' || lv_station_name);

  -- Most recent status row for this station
  SELECT bs.time, bs.bikes_available, bs.docks_available
    INTO lv_time, lv_bikes, lv_docks
    FROM (
      SELECT bs2.time, bs2.bikes_available, bs2.docks_available
