CREATE OR REPLACE PROCEDURE rpt_cpi_u_recent(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_area_name BLS.CPI_U.area_name%TYPE;
  lv_item_name BLS.CPI_U.item_name%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Resolve defaults to the most common area/item when NULL is provided
  IF p_area_name IS NULL THEN
    SELECT area_name
      INTO lv_area_name
      FROM (
        SELECT c.area_name
          FROM BLS.CPI_U c
         GROUP BY c.area_name
         ORDER BY COUNT(*) DESC, c.area_name
      )
     WHERE ROWNUM = 1;
  ELSE
    lv_area_name := p_area_name;
  END IF;

  IF p_item_name IS NULL THEN
    SELECT item_name
      INTO lv_item_name
      FROM (
        SELECT c.item_name
          FROM BLS.CPI_U c
         GROUP BY c.item_name
         ORDER BY COUNT(*) DESC, c.item_name
      )
     WHERE ROWNUM = 1;
  ELSE
    lv_item_name := p_item_name;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI-U recent observations (max rows = ' || co_report_limit || ')');
  DBMS_OUTPUT.PUT_LINE('Area=' || lv_area_name || '; Item=' || lv_item_name);

  FOR r IN (
    SELECT c.c_date, c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND c.c_date IS NOT NULL
     ORDER BY c.c_date DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(r.c_date, 'YYYY-MM-DD') || ' | ' || r.value);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No observations found for the requested area/item.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_cpi_u_recent;
/

