CREATE OR REPLACE FUNCTION fn_cpi_u_combo_exists(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE
) RETURN VARCHAR2 IS
  lv_cnt NUMBER;
  lv_result VARCHAR2(1);
BEGIN
  IF p_area_name IS NULL OR p_item_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Validation: area/item is NULL -> N');
    RETURN 'N';
  END IF;

  SELECT COUNT(*)
    INTO lv_cnt
    FROM BLS.CPI_U c
   WHERE c.area_name = p_area_name
     AND c.item_name = p_item_name;

  IF lv_cnt > 0 THEN
    lv_result := 'Y';
  ELSE
    lv_result := 'N';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Validation: area=' || p_area_name || '; item=' || p_item_name || ' -> ' || lv_result);
  RETURN lv_result;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'N';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'N';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'N';
END fn_cpi_u_combo_exists;
