CREATE OR REPLACE PACKAGE BODY cpi_diag_pkg IS
  PROCEDURE run_report_with_diag(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE
  ) IS
    lv_valid VARCHAR2(1);
    lv_cnt_cpi_u NUMBER := 0;
    lv_cnt_c_cpi_u NUMBER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Diagnostics: starting');

    lv_valid := fn_cpi_u_combo_exists(p_area_name, p_item_name);
    DBMS_OUTPUT.PUT_LINE('Diagnostics: valid_combo=' || lv_valid);

    -- Counts are diagnostic only; they help explain "no rows" complaints.
    SELECT COUNT(*)
      INTO lv_cnt_cpi_u
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name;

    SELECT COUNT(*)
      INTO lv_cnt_c_cpi_u
      FROM BLS.C_CPI_U cc
     WHERE cc.area_name = p_area_name
       AND cc.item_name = p_item_name;

    DBMS_OUTPUT.PUT_LINE('Diagnostics: CPI_U rows=' || lv_cnt_cpi_u || '; C_CPI_U rows=' || lv_cnt_c_cpi_u);

    IF lv_cnt_cpi_u = 0 AND lv_cnt_c_cpi_u > 0 THEN
      DBMS_OUTPUT.PUT_LINE('Hint: Combination not in CPI_U but exists in C_CPI_U. Check if you queried the correct table.');
    END IF;

    IF lv_valid = 'Y' THEN
      rpt_cpi_u_recent(p_area_name, p_item_name);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Report skipped because validation failed.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_report_with_diag;
END cpi_diag_pkg;
/

