CREATE OR REPLACE PROCEDURE report_team_innings_score(
  p_team_id IN IPL.TEAM.TEAM_ID%TYPE
) IS
  co_report_limit CONSTANT NUMBER := 15; -- Limit output for score-audit readability.
  lv_team_name IPL.TEAM.NAME%TYPE;
  lv_rows       NUMBER := 0;

  CURSOR cur_team_innings(cp_team_id IPL.TEAM.TEAM_ID%TYPE) IS
    SELECT *
      FROM (
            SELECT b.match_id,
                   b.innings_no,
                   SUM(NVL(bs.runs_scored, 0)) AS batsman_runs,
                   SUM(NVL(er.extra_runs, 0)) AS extra_runs,
                   SUM(NVL(bs.runs_scored, 0) + NVL(er.extra_runs, 0)) AS total_runs,
                   COUNT(w.player_out) AS wickets
              FROM IPL.BALL_BY_BALL b
              LEFT OUTER JOIN IPL.BATSMAN_SCORED bs
                ON bs.match_id = b.match_id
               AND bs.over_id = b.over_id
               AND bs.ball_id = b.ball_id
               AND bs.innings_no = b.innings_no
              LEFT OUTER JOIN IPL.EXTRA_RUNS er
                ON er.match_id = b.match_id
               AND er.over_id = b.over_id
               AND er.ball_id = b.ball_id
               AND er.innings_no = b.innings_no
              LEFT OUTER JOIN IPL.WICKET_TAKEN w
                ON w.match_id = b.match_id
               AND w.over_id = b.over_id
               AND w.ball_id = b.ball_id
               AND w.innings_no = b.innings_no
             WHERE b.team_batting = cp_team_id
             GROUP BY b.match_id, b.innings_no
             ORDER BY b.match_id, b.innings_no
           )
     WHERE ROWNUM <= co_report_limit;
BEGIN
  IF p_team_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Team id is required.');
    RETURN;
  END IF;

  SELECT t.name
    INTO lv_team_name
    FROM IPL.TEAM t
   WHERE t.team_id = p_team_id;

  DBMS_OUTPUT.PUT_LINE('Score audit for team: ' || lv_team_name || ' (' || p_team_id || ')');

  FOR rec IN cur_team_innings(p_team_id) LOOP
    lv_rows := lv_rows + 1;

    IF rec.wickets >= 10 THEN
      DBMS_OUTPUT.PUT_LINE('Match ' || rec.match_id || ', Innings ' || rec.innings_no || ': Runs=' || rec.total_runs || ' (Bat=' || rec.batsman_runs || ', Extra=' || rec.extra_runs || '), Wickets=' || rec.wickets || ', Status=ALL OUT');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Match ' || rec.match_id || ', Innings ' || rec.innings_no || ': Runs=' || rec.total_runs || ' (Bat=' || rec.batsman_runs || ', Extra=' || rec.extra_runs || '), Wickets=' || rec.wickets || ', Status=NOT ALL OUT');
    END IF;
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No innings found for this team.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_team_innings_score;
/

CREATE OR REPLACE PROCEDURE assess_match_batting_pressure(
  p_team_id  IN IPL.TEAM.TEAM_ID%TYPE,
  p_match_id IN IPL.MATCH.MATCH_ID%TYPE
) IS
  co_report_limit CONSTANT NUMBER := 15; -- Limit output for match pressure review.
  lv_team_name      IPL.TEAM.NAME%TYPE;
  lv_match_date     IPL.MATCH.MATCH_DATE%TYPE;
  lv_rows           NUMBER := 0;
  lv_pressure_label VARCHAR2(30);

  CURSOR cur_pressure(cp_team_id IPL.TEAM.TEAM_ID%TYPE, cp_match_id IPL.MATCH.MATCH_ID%TYPE) IS
    SELECT *
      FROM (
            SELECT b.innings_no,
                   COUNT(*) AS delivery_count,
                   SUM(NVL(bs.runs_scored, 0) + NVL(er.extra_runs, 0)) AS total_runs,
                   COUNT(w.player_out) AS wickets,
                   ROUND(SUM(NVL(bs.runs_scored, 0) + NVL(er.extra_runs, 0)) / NULLIF(COUNT(*), 0), 2) AS runs_per_delivery
              FROM IPL.BALL_BY_BALL b
              LEFT OUTER JOIN IPL.BATSMAN_SCORED bs
                ON bs.match_id = b.match_id
               AND bs.over_id = b.over_id
               AND bs.ball_id = b.ball_id
               AND bs.innings_no = b.innings_no
              LEFT OUTER JOIN IPL.EXTRA_RUNS er
                ON er.match_id = b.match_id
               AND er.over_id = b.over_id
               AND er.ball_id = b.ball_id
               AND er.innings_no = b.innings_no
              LEFT OUTER JOIN IPL.WICKET_TAKEN w
                ON w.match_id = b.match_id
               AND w.over_id = b.over_id
               AND w.ball_id = b.ball_id
               AND w.innings_no = b.innings_no
             WHERE b.team_batting = cp_team_id
               AND b.match_id = cp_match_id
             GROUP BY b.innings_no
             ORDER BY b.innings_no
           )
     WHERE ROWNUM <= co_report_limit;
BEGIN
  IF p_team_id IS NULL OR p_match_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Team id and match id are required.');
    RETURN;
  END IF;

  SELECT t.name
    INTO lv_team_name
    FROM IPL.TEAM t
   WHERE t.team_id = p_team_id;

  SELECT m.match_date
    INTO lv_match_date
    FROM IPL.MATCH m
   WHERE m.match_id = p_match_id;

  DBMS_OUTPUT.PUT_LINE('Pressure assessment for ' || lv_team_name || ' in match ' || p_match_id || ' on ' || TO_CHAR(lv_match_date, 'YYYY-MM-DD'));

  FOR rec IN cur_pressure(p_team_id, p_match_id) LOOP
    lv_rows := lv_rows + 1;

    CASE
      WHEN rec.wickets >= 8 THEN
        lv_pressure_label := 'HIGH RISK';
      WHEN rec.runs_per_delivery >= 1.5 THEN
        lv_pressure_label := 'ATTACKING';
      ELSE
        lv_pressure_label := 'STABLE';
    END CASE;

    DBMS_OUTPUT.PUT_LINE('Innings ' || rec.innings_no || ': Deliveries=' || rec.delivery_count || ', Runs=' || rec.total_runs || ', Wickets=' || rec.wickets || ', RunsPerDelivery=' || rec.runs_per_delivery || ', Pressure=' || lv_pressure_label);
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No batting rows found for this team in the match.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END assess_match_batting_pressure;
/

CREATE OR REPLACE PACKAGE ipl_score_audit_pkg IS
  PROCEDURE validate_team_match_inputs(
    p_team_id  IN IPL.TEAM.TEAM_ID%TYPE,
    p_match_id IN IPL.MATCH.MATCH_ID%TYPE
  );
END ipl_score_audit_pkg;
/
CREATE OR REPLACE PACKAGE BODY ipl_score_audit_pkg IS
  PROCEDURE validate_team_match_inputs(
    p_team_id  IN IPL.TEAM.TEAM_ID%TYPE,
    p_match_id IN IPL.MATCH.MATCH_ID%TYPE
  ) IS
    co_report_limit CONSTANT NUMBER := 15; -- Limit role-mix output for validation review.
    lv_team_name IPL.TEAM.NAME%TYPE;
    lv_match_id  IPL.MATCH.MATCH_ID%TYPE;
    lv_rows      NUMBER := 0;

    CURSOR cur_player_roles(cp_team_id IPL.TEAM.TEAM_ID%TYPE, cp_match_id IPL.MATCH.MATCH_ID%TYPE) IS
      SELECT *
        FROM (
              SELECT pm.role,
                     COUNT(*) AS role_count
                FROM IPL.PLAYER_MATCH pm
               WHERE pm.team_id = cp_team_id
                 AND pm.match_id = cp_match_id
               GROUP BY pm.role
               ORDER BY COUNT(*) DESC, pm.role
             )
       WHERE ROWNUM <= co_report_limit;
  BEGIN
    IF p_team_id IS NULL OR p_match_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Team id and match id are required for validation.');
      RETURN;
    END IF;

    SELECT t.name
      INTO lv_team_name
      FROM IPL.TEAM t
     WHERE t.team_id = p_team_id;

    SELECT m.match_id
      INTO lv_match_id
      FROM IPL.MATCH m
     WHERE m.match_id = p_match_id
       AND (m.team_1 = p_team_id OR m.team_2 = p_team_id);

    DBMS_OUTPUT.PUT_LINE('Validation passed for ' || lv_team_name || ' in match ' || lv_match_id);

    FOR rec IN cur_player_roles(p_team_id, p_match_id) LOOP
      lv_rows := lv_rows + 1;

      IF rec.role IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Role is missing for ' || rec.role_count || ' roster rows.');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Role ' || rec.role || ' count=' || rec.role_count);
      END IF;
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No player roster rows found for this team and match.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END validate_team_match_inputs;
END ipl_score_audit_pkg;
/

CREATE OR REPLACE PROCEDURE debug_match_ball_integrity(
  p_match_id IN IPL.MATCH.MATCH_ID%TYPE
) IS
  co_report_limit CONSTANT NUMBER := 15; -- Limit diagnostic findings for readable root-cause output.
  lv_match_date  IPL.MATCH.MATCH_DATE%TYPE;
  lv_issue_count NUMBER := 0;
  lv_root_cause  VARCHAR2(80);

  CURSOR cur_ball_issues(cp_match_id IPL.MATCH.MATCH_ID%TYPE) IS
    SELECT *
      FROM (
            SELECT b.match_id,
                   b.innings_no,
                   b.over_id,
                   b.ball_id,
                   COUNT(bs.runs_scored) AS batsman_score_rows,
                   COUNT(er.extra_runs) AS extra_rows,
                   COUNT(w.player_out) AS wicket_rows,
                   SUM(NVL(bs.runs_scored, 0)) AS batsman_runs,
                   SUM(NVL(er.extra_runs, 0)) AS extra_runs
              FROM IPL.BALL_BY_BALL b
              LEFT OUTER JOIN IPL.BATSMAN_SCORED bs
                ON bs.match_id = b.match_id
               AND bs.over_id = b.over_id
               AND bs.ball_id = b.ball_id
               AND bs.innings_no = b.innings_no
              LEFT OUTER JOIN IPL.EXTRA_RUNS er
                ON er.match_id = b.match_id
               AND er.over_id = b.over_id
               AND er.ball_id = b.ball_id
               AND er.innings_no = b.innings_no
              LEFT OUTER JOIN IPL.WICKET_TAKEN w
                ON w.match_id = b.match_id
               AND w.over_id = b.over_id
               AND w.ball_id = b.ball_id
               AND w.innings_no = b.innings_no
             WHERE b.match_id = cp_match_id
             GROUP BY b.match_id, b.innings_no, b.over_id, b.ball_id
            HAVING COUNT(bs.runs_scored) <> 1
                OR COUNT(er.extra_runs) > 1
                OR COUNT(w.player_out) > 1
             ORDER BY b.innings_no, b.over_id, b.ball_id
           )
     WHERE ROWNUM <= co_report_limit;

  lv_issue cur_ball_issues%ROWTYPE;
BEGIN
  IF p_match_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Match id is required for debugging.');
    RETURN;
  END IF;

  SELECT m.match_date
    INTO lv_match_date
    FROM IPL.MATCH m
   WHERE m.match_id = p_match_id;

  DBMS_OUTPUT.PUT_LINE('Debugging ball integrity for match ' || p_match_id || ' on ' || TO_CHAR(lv_match_date, 'YYYY-MM-DD'));

  OPEN cur_ball_issues(p_match_id);
  LOOP
    FETCH cur_ball_issues INTO lv_issue;
    EXIT WHEN cur_ball_issues%NOTFOUND;

    lv_issue_count := lv_issue_count + 1;

    IF lv_issue.batsman_score_rows = 0 THEN
      lv_root_cause := 'MISSING BATSMAN_SCORE ROW';
    ELSIF lv_issue.batsman_score_rows > 1 THEN
      lv_root_cause := 'DUPLICATE BATSMAN_SCORE ROWS';
    ELSIF lv_issue.extra_rows > 1 THEN
      lv_root_cause := 'DUPLICATE EXTRA_RUNS ROWS';
    ELSE
      lv_root_cause := 'DUPLICATE WICKET_TAKEN ROWS';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Issue ' || lv_issue_count || ': Innings=' || lv_issue.innings_no || ', Over=' || lv_issue.over_id || ', Ball=' || lv_issue.ball_id || ', RootCause=' || lv_root_cause || ', BatsmanRows=' || lv_issue.batsman_score_rows || ', ExtraRows=' || lv_issue.extra_rows || ', WicketRows=' || lv_issue.wicket_rows);
  END LOOP;
  CLOSE cur_ball_issues;

  IF lv_issue_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No scoring integrity issues found in the first audit window.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF cur_ball_issues%ISOPEN THEN
      CLOSE cur_ball_issues;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END debug_match_ball_integrity;
/

