reference_answer:
CREATE OR REPLACE PROCEDURE report_legislator_terms_by_state(
  p_state IN CITY_LEGISLATION.LEGISLATORS_TERMS.state%TYPE
) IS
  co_report_limit CONSTANT NUMBER := 15; -- Limit output for report readability
  lv_rows         NUMBER := 0;
BEGIN
  IF p_state IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('State is required.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Legislator terms for state ' || UPPER(p_state) || ':');

    FOR rec IN (
      SELECT q.full_name,
             q.term_type,
             q.party,
             q.term_start,
             q.term_end
        FROM (
              SELECT l.full_name,
                     t.term_type,
                     t.party,
                     t.term_start,
                     t.term_end
                FROM CITY_LEGISLATION.LEGISLATORS l
                INNER JOIN CITY_LEGISLATION.LEGISLATORS_TERMS t
                  ON l.id_bioguide = t.id_bioguide
               WHERE t.state = UPPER(p_state)
               ORDER BY t.term_start DESC, l.full_name ASC
             ) q
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(rec.full_name || ' | ' || rec.term_type || ' | ' || rec.party || ' | ' || rec.term_start || ' to ' || rec.term_end);
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No legislator terms found for state.');
    END IF;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_legislator_terms_by_state;
/

