CREATE OR REPLACE FUNCTION get_team_win_band(
  p_year    IN BASEBALL.TEAM.year%TYPE,
  p_team_id IN BASEBALL.TEAM.team_id%TYPE
) RETURN VARCHAR2 AS
  lv_w    BASEBALL.TEAM.w%TYPE;
  lv_l    BASEBALL.TEAM.l%TYPE;
  lv_band VARCHAR2(30);
BEGIN
  IF p_year IS NULL OR p_team_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year and team are required for classification.');
    RETURN 'INVALID_INPUT';
  ELSE
    SELECT t.w, t.l
      INTO lv_w, lv_l
      FROM BASEBALL.TEAM t
     WHERE t.year = p_year
       AND t.team_id = p_team_id;

    IF NVL(lv_w, 0) + NVL(lv_l, 0) = 0 THEN
      lv_band := 'NO_GAMES';
    ELSIF NVL(lv_w, 0) >= 95 THEN
      lv_band := 'ELITE';
    ELSIF NVL(lv_w, 0) >= 85 THEN
      lv_band := 'CONTENDER';
    ELSIF NVL(lv_w, 0) >= NVL(lv_l, 0) THEN
      lv_band := 'COMPETITIVE';
    ELSE
      lv_band := 'REBUILD_WATCH';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Classification for ' || p_team_id || ' in ' || p_year || ': ' || lv_band);
    RETURN lv_band;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No team found for classification.');
    RETURN 'NOT_FOUND';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple teams found for classification.');
    RETURN 'DUPLICATE_TEAM';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'ERROR';
END get_team_win_band;
/

