CREATE OR REPLACE PACKAGE baseball_team_review AS
  PROCEDURE run_review(
    p_year    IN BASEBALL.TEAM.year%TYPE,
    p_team_id IN BASEBALL.TEAM.team_id%TYPE,
    p_min_rbi IN BASEBALL.BATTING.rbi%TYPE DEFAULT 50
  );
END baseball_team_review;
/

CREATE OR REPLACE PACKAGE BODY baseball_team_review AS
  FUNCTION determine_band(
    p_w IN BASEBALL.TEAM.w%TYPE,
    p_l IN BASEBALL.TEAM.l%TYPE
  ) RETURN VARCHAR2 AS
    lv_band VARCHAR2(30);
  BEGIN
    IF NVL(p_w, 0) + NVL(p_l, 0) = 0 THEN
      lv_band := 'NO_GAMES';
    ELSIF NVL(p_w, 0) >= 95 THEN
      lv_band := 'ELITE';
    ELSIF NVL(p_w, 0) >= 85 THEN
      lv_band := 'CONTENDER';
    ELSIF NVL(p_w, 0) >= NVL(p_l, 0) THEN
      lv_band := 'COMPETITIVE';
    ELSE
      lv_band := 'REBUILD_WATCH';
    END IF;

    RETURN lv_band;
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unable to classify team.');
      RETURN 'ERROR';
  END determine_band;

  PROCEDURE run_review(
    p_year    IN BASEBALL.TEAM.year%TYPE,
    p_team_id IN BASEBALL.TEAM.team_id%TYPE,
    p_min_rbi IN BASEBALL.BATTING.rbi%TYPE DEFAULT 50
  ) AS
    co_report_limit  CONSTANT PLS_INTEGER := 15; -- Keep the integrated package report concise
    lv_team_name     BASEBALL.TEAM.name%TYPE;
    lv_w             BASEBALL.TEAM.w%TYPE;
    lv_l             BASEBALL.TEAM.l%TYPE;
    lv_runs          BASEBALL.TEAM.r%TYPE;
    lv_runs_allowed  BASEBALL.TEAM.ra%TYPE;
    lv_band          VARCHAR2(30);
    lv_hitter_rows   PLS_INTEGER := 0;
    lv_pitcher_count PLS_INTEGER := 0;
    lv_pitcher_wins  BASEBALL.PITCHING.w%TYPE;
    lv_avg_era       BASEBALL.PITCHING.era%TYPE;
  BEGIN
    IF p_year IS NULL OR p_team_id IS NULL OR p_min_rbi IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Year, team, and RBI threshold are required.');
    ELSIF p_min_rbi < 0 THEN
      DBMS_OUTPUT.PUT_LINE('RBI threshold cannot be negative.');
    ELSE
      SELECT t.name, t.w, t.l, t.r, t.ra
        INTO lv_team_name, lv_w, lv_l, lv_runs, lv_runs_allowed
        FROM BASEBALL.TEAM t
       WHERE t.year = p_year
         AND t.team_id = p_team_id;

      lv_band := determine_band(lv_w, lv_l);

      DBMS_OUTPUT.PUT_LINE('Integrated team review: ' || lv_team_name || ' (' || p_team_id || ') in ' || p_year || ' | W-L ' || lv_w || '-' || lv_l || ' | Runs ' || lv_runs || ' | Runs Allowed ' || lv_runs_allowed || ' | Band ' || lv_band);
      DBMS_OUTPUT.PUT_LINE('Hitter threshold: RBI >= ' || p_min_rbi);

      FOR rec IN (
        SELECT limited.player_id,
               limited.player_name,
               limited.total_hr,
               limited.total_rbi
          FROM (
            SELECT b.player_id,
                   TRIM(p.name_first || ' ' || p.name_last) AS player_name,
                   SUM(NVL(b.hr, 0)) AS total_hr,
                   SUM(NVL(b.rbi, 0)) AS total_rbi
              FROM BASEBALL.BATTING b
              INNER JOIN BASEBALL.PLAYER p
                ON p.player_id = b.player_id
             WHERE b.year = p_year
               AND b.team_id = p_team_id
             GROUP BY b.player_id, TRIM(p.name_first || ' ' || p.name_last)
            HAVING SUM(NVL(b.rbi, 0)) >= p_min_rbi
             ORDER BY SUM(NVL(b.rbi, 0)) DESC, SUM(NVL(b.hr, 0)) DESC, b.player_id ASC
          ) limited
         WHERE ROWNUM <= co_report_limit
      ) LOOP
        lv_hitter_rows := lv_hitter_rows + 1;
        DBMS_OUTPUT.PUT_LINE(rec.player_id || ' | ' || rec.player_name || ' | HR ' || rec.total_hr || ' | RBI ' || rec.total_rbi);
      END LOOP;

      IF lv_hitter_rows = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No hitters met the RBI threshold.');
      END IF;

      SELECT COUNT(DISTINCT pit.player_id), SUM(NVL(pit.w, 0)), AVG(pit.era)
        INTO lv_pitcher_count, lv_pitcher_wins, lv_avg_era
        FROM BASEBALL.PITCHING pit
       WHERE pit.year = p_year
         AND pit.team_id = p_team_id;

      DBMS_OUTPUT.PUT_LINE('Pitching summary: pitchers=' || lv_pitcher_count || ', wins=' || NVL(TO_CHAR(lv_pitcher_wins), '0') || ', avg ERA=' || NVL(TO_CHAR(ROUND(lv_avg_era, 2)), 'N/A'));
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No team found for package review.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple teams found for package review.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_review;
END baseball_team_review;
/

