CREATE OR REPLACE FUNCTION get_station_trip_count(
  p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE,
  p_start_ts     IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
  p_end_ts       IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE
) RETURN NUMBER IS
  lv_station_id  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
  lv_trip_count  NUMBER := 0;
BEGIN
  IF p_station_name IS NULL OR TRIM(p_station_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Station name is required.');
    RETURN 0;
  END IF;

  IF p_start_ts IS NULL OR p_end_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Start and end timestamps are required.');
    RETURN 0;
  END IF;

  SELECT si.station_id
    INTO lv_station_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
   WHERE si.name = p_station_name
     AND ROWNUM = 1;

  SELECT COUNT(*)
    INTO lv_trip_count
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
   WHERE t.start_station_id = lv_station_id
     AND t.start_date >= p_start_ts
     AND t.start_date < p_end_ts;

  DBMS_OUTPUT.PUT_LINE('Station: ' || p_station_name || ' | Trips started in range: ' || lv_trip_count);
  RETURN lv_trip_count;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 0;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 0;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 0;
END get_station_trip_count;
/

