CREATE OR REPLACE PACKAGE bikeshare_trip_quality IS
  PROCEDURE run_suspicious_trip_report(
    p_region_name       IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
    p_start_ts          IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
    p_end_ts            IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE,
    p_max_duration_sec  IN NUMBER
  );
END bikeshare_trip_quality;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_trip_quality IS
  PROCEDURE run_suspicious_trip_report(
    p_region_name       IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
    p_start_ts          IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
    p_end_ts            IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE,
    p_max_duration_sec  IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_region_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF p_region_name IS NULL OR TRIM(p_region_name) IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Region name is required.');
      RETURN;
    END IF;

    IF p_start_ts IS NULL OR p_end_ts IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Start and end timestamps are required.');
      RETURN;
    END IF;

    IF p_max_duration_sec IS NULL OR p_max_duration_sec <= 0 THEN
      DBMS_OUTPUT.PUT_LINE('Max duration must be greater than zero.');
      RETURN;
    END IF;

    SELECT rgn.region_id
      INTO lv_region_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS rgn
     WHERE rgn.name = p_region_name
       AND ROWNUM = 1;

    DBMS_OUTPUT.PUT_LINE(
      'Suspicious trip report | Region=' || p_region_name ||
      ' | Start=' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | End=' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | MaxDurationSec=' || p_max_duration_sec
    );

    FOR r IN (
      SELECT t.trip_id,
             si.name AS station_name,
             t.start_date,
             TO_NUMBER(t.duration_sec) AS duration_sec_num
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          ON si.station_id = t.start_station_id
       WHERE si.region_id = lv_region_id
         AND t.start_station_id = t.end_station_id
         AND t.start_date >= p_start_ts
         AND t.start_date < p_end_ts
         AND TO_NUMBER(t.duration_sec) <= p_max_duration_sec
       ORDER BY t.start_date DESC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE(
        'TripId=' || r.trip_id ||
        ' | Station=' || r.station_name ||
        ' | Start=' || TO_CHAR(r.start_date, 'YYYY-MM-DD HH24:MI:SS') ||
        ' | DurationSec=' || r.duration_sec_num
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No suspicious trips found for the given filters.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No suspicious trips found for the given filters.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Bad numeric data encountered in trip duration.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_suspicious_trip_report;
END bikeshare_trip_quality;
/

CREATE OR REPLACE PROCEDURE diagnose_region_station_data_issues(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_region_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_issue_count  PLS_INTEGER := 0;
BEGIN
  IF p_region_name IS NULL OR TRIM(p_region_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Region name is required.');
    RETURN;
  END IF;

  SELECT rgn.region_id
    INTO lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS rgn
   WHERE rgn.name = p_region_name
     AND ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Diagnostics for Region=' || p_region_name || ' (max rows per section=' || co_report_limit || ')');

  DBMS_OUTPUT.PUT_LINE('Stations with non-numeric capacity:');
  FOR r1 IN (
    SELECT si.name, si.capacity
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
     WHERE si.region_id = lv_region_id
       AND NOT REGEXP_LIKE(si.capacity, '^[0-9]+$')
     ORDER BY si.name
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_issue_count := lv_issue_count + 1;
    DBMS_OUTPUT.PUT_LINE('  Station=' || r1.name || ' | CapacityRaw=' || r1.capacity);
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Stations with no status rows:');
  FOR r2 IN (
    SELECT si.name, si.station_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
        ON ss.station_id = si.station_id
     WHERE si.region_id = lv_region_id
       AND ss.station_id IS NULL
     ORDER BY si.name
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_issue_count := lv_issue_count + 1;
    DBMS_OUTPUT.PUT_LINE('  Station=' || r2.name || ' | StationId=' || r2.station_id);
  END LOOP;

  IF lv_issue_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No issues found for region.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No issues found for region.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END diagnose_region_station_data_issues;
/

CREATE OR REPLACE PROCEDURE debug_utilization_unexpected_error(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
) IS
  lv_region_id           SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_bad_capacity_cnt    NUMBER := 0;
  lv_bad_bikes_avail_cnt NUMBER := 0;
BEGIN
  IF p_region_name IS NULL OR TRIM(p_region_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Region name is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Debug utilization error | Region=' || p_region_name);

  SELECT rgn.region_id
    INTO lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS rgn
   WHERE rgn.name = p_region_name
     AND ROWNUM = 1;

  SELECT COUNT(*)
    INTO lv_bad_capacity_cnt
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
   WHERE si.region_id = lv_region_id
     AND NOT REGEXP_LIKE(si.capacity, '^[0-9]+$');

  SELECT COUNT(*)
    INTO lv_bad_bikes_avail_cnt
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
    INNER JOIN (
      SELECT st.station_id,
             MAX(TO_NUMBER(st.last_reported)) AS last_reported_num
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS st
       GROUP BY st.station_id
    ) ls
      ON ls.station_id = ss.station_id
     AND TO_NUMBER(ss.last_reported) = ls.last_reported_num
    INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      ON si.station_id = ss.station_id
   WHERE si.region_id = lv_region_id
     AND NOT REGEXP_LIKE(ss.num_bikes_available, '^[0-9]+$');

  DBMS_OUTPUT.PUT_LINE('Check A - Stations with non-numeric capacity: ' || lv_bad_capacity_cnt);
  DBMS_OUTPUT.PUT_LINE('Check B - Latest-status rows with non-numeric bikes available: ' || lv_bad_bikes_avail_cnt);

  IF lv_bad_capacity_cnt > lv_bad_bikes_avail_cnt AND lv_bad_capacity_cnt > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Conclusion: Likely cause is non-numeric station capacity values.');
  ELSIF lv_bad_bikes_avail_cnt > lv_bad_capacity_cnt AND lv_bad_bikes_avail_cnt > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Conclusion: Likely cause is non-numeric bikes-available values in station status.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Conclusion: No obvious numeric-conversion issues found; investigate other data anomalies.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END debug_utilization_unexpected_error;
/

question:
Start the pizza operations review by pulling a small order-mix report. Show the most frequently ordered pizza names and label each pizza as repeat demand or single order demand based on its order count. Keep the output short and make sure the script reports problems cleanly instead of failing at the terminal.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Pizza order mix report');
DBMS_OUTPUT.PUT_LINE('Pizza: ' || rec.pizza_name || ' | Orders: ' || rec.order_count || ' | Category: ' || lv_category);
DBMS_OUTPUT.PUT_LINE('No pizza order rows found.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  ln_rows         NUMBER := 0;
  lv_category     VARCHAR2(30);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Pizza order mix report');

  FOR rec IN (
    SELECT rpt.pizza_name,
           rpt.order_count
      FROM (
            SELECT pn.pizza_name AS pizza_name,
                   COUNT(*) AS order_count
              FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS cco
              INNER JOIN MODERN_DATA.PIZZA_NAMES pn
                ON pn.pizza_id = cco.pizza_id
             GROUP BY pn.pizza_name
             ORDER BY COUNT(*) DESC, pn.pizza_name ASC
           ) rpt
     WHERE ROWNUM <= co_report_limit
  ) LOOP
