DECLARE
  lv_fips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE;
  lv_births NUMBER;
  lv_ave_age NUMBER;
  lv_printed_rows PLS_INTEGER := 0;
  lv_father_race_rows NUMBER;
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR cur_nat(p_fips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE) IS
    SELECT cn.year,
           cn.births,
           cn.ave_age_of_mother
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence_fips = p_fips
     ORDER BY cn.year DESC;

  lr_nat cur_nat%ROWTYPE;
BEGIN
  -- Pick the most common county FIPS to make the report deterministic.
  SELECT x.county_of_residence_fips
    INTO lv_fips
    FROM (
          SELECT cn.county_of_residence_fips, COUNT(*) AS cnt
            FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
           WHERE cn.county_of_residence_fips IS NOT NULL
           GROUP BY cn.county_of_residence_fips
           ORDER BY COUNT(*) DESC, cn.county_of_residence_fips
         ) x
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('County report for FIPS=' || lv_fips);

  OPEN cur_nat(lv_fips);
  LOOP
    FETCH cur_nat INTO lr_nat;
    EXIT WHEN cur_nat%NOTFOUND;

    -- Stop after the report limit.
    EXIT WHEN lv_printed_rows >= co_report_limit;

    BEGIN
      lv_births := TO_NUMBER(TRIM(lr_nat.births));
      lv_ave_age := TO_NUMBER(TRIM(lr_nat.ave_age_of_mother));
      DBMS_OUTPUT.PUT_LINE(
        'Year=' || TO_CHAR(lr_nat.year, 'YYYY') || ', births=' || TO_CHAR(lv_births) || ', ave_age_mom=' || TO_CHAR(lv_ave_age)
      );
      lv_printed_rows := lv_printed_rows + 1;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Skipped row (non-numeric measure) for year=' || TO_CHAR(lr_nat.year, 'YYYY'));
    END;
  END LOOP;
  CLOSE cur_nat;

  SELECT COUNT(*)
    INTO lv_father_race_rows
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_FATHER_RACE fr
   WHERE fr.county_of_residence_fips = lv_fips;

  DBMS_OUTPUT.PUT_LINE('Cross-check: father-race rows for this county=' || TO_CHAR(lv_father_race_rows));

  IF lv_printed_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No reportable rows for this county.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid number in source data.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

