    CURSOR cur_nat(p_cfips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE) IS
      SELECT cn.year,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.county_of_residence_fips = p_cfips
       ORDER BY cn.year DESC;

    lr_nat cur_nat%ROWTYPE;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Birth-threshold report for FIPS=' || p_fips || ', min_births=' || TO_CHAR(lv_min_births));

    OPEN cur_nat(p_fips);
    LOOP
      FETCH cur_nat INTO lr_nat;
      EXIT WHEN cur_nat%NOTFOUND;
      EXIT WHEN lv_printed_rows >= co_report_limit;

      lv_printed_rows := lv_printed_rows + 1;

      BEGIN
        lv_births := TO_NUMBER(TRIM(lr_nat.births));
      EXCEPTION
        WHEN VALUE_ERROR THEN
          DBMS_OUTPUT.PUT_LINE('Skipped row (non-numeric births) for year=' || TO_CHAR(lr_nat.year, 'YYYY'));
          CONTINUE;
      END;

      IF lv_births >= lv_min_births THEN
        SELECT COUNT(*)
          INTO lv_fr_rows
          FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_FATHER_RACE fr
         WHERE fr.county_of_residence_fips = p_fips
           AND fr.year = lr_nat.year;

        DBMS_OUTPUT.PUT_LINE(
          'Year=' || TO_CHAR(lr_nat.year, 'YYYY') || ', births=' || TO_CHAR(lv_births) || ', father_race_rows=' || TO_CHAR(lv_fr_rows)
