        RETURN NULL;
    END;

    SELECT COUNT(*)
      INTO lv_fr_rows
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_FATHER_RACE fr
     WHERE fr.county_of_residence_fips = p_fips
       AND fr.year = p_year;

    IF lv_fr_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Cannot compute ratio: father-race rows is zero.');
      RETURN NULL;
    END IF;

    lv_ratio := lv_births / lv_fr_rows;

    DBMS_OUTPUT.PUT_LINE('Births=' || TO_CHAR(lv_births) || ', father_race_rows=' || TO_CHAR(lv_fr_rows) || ', ratio=' || TO_CHAR(lv_ratio));

    RETURN lv_ratio;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No father-race rows found for the given inputs.');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN NULL;
    WHEN ZERO_DIVIDE THEN
      DBMS_OUTPUT.PUT_LINE('Cannot compute ratio: divide by zero.');
      RETURN NULL;
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid number in source data.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END get_births_per_father_race;

  PROCEDURE print_yearly_classification(
    p_fips                  IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE,
    p_high_births_threshold IN NUMBER
  ) IS
    lv_births NUMBER;
    lv_threshold NUMBER := NVL(p_high_births_threshold, 0);
    lv_class VARCHAR2(20);
    lv_mm_rows NUMBER;
    lv_seen_rows PLS_INTEGER := 0;
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR cur_nat(p_cfips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE) IS
      SELECT cn.year,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.county_of_residence_fips = p_cfips
       ORDER BY cn.year DESC;

    lr_nat cur_nat%ROWTYPE;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Yearly classification for FIPS=' || p_fips || ', high_births_threshold=' || TO_CHAR(lv_threshold));

    OPEN cur_nat(p_fips);
    LOOP
      FETCH cur_nat INTO lr_nat;
      EXIT WHEN cur_nat%NOTFOUND;
      EXIT WHEN lv_seen_rows >= co_report_limit;

      lv_seen_rows := lv_seen_rows + 1;

      BEGIN
        lv_births := TO_NUMBER(TRIM(lr_nat.births));
      EXCEPTION
        WHEN VALUE_ERROR THEN
          DBMS_OUTPUT.PUT_LINE('Skipped row (non-numeric births) for year=' || TO_CHAR(lr_nat.year, 'YYYY'));
          CONTINUE;
      END;

      IF lv_births >= lv_threshold THEN
        lv_class := 'HIGH_BIRTHS';
      ELSE
        lv_class := 'LOW_BIRTHS';
      END IF;

      SELECT COUNT(*)
        INTO lv_mm_rows
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY mm
       WHERE mm.county_of_residence_fips = p_fips
         AND mm.year = lr_nat.year;

      DBMS_OUTPUT.PUT_LINE(
        'Year=' || TO_CHAR(lr_nat.year, 'YYYY') || ', births=' || TO_CHAR(lv_births) || ', class=' || lv_class || ', maternal_morbidity_rows=' || TO_CHAR(lv_mm_rows)
      );
    END LOOP;
    CLOSE cur_nat;

    IF lv_seen_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No yearly rows found for this county.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid number in source data.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_yearly_classification;
END pkg_natality_briefing;
/

CREATE OR REPLACE PROCEDURE patient_snapshot(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  lv_full_name  VARCHAR2(250);
  lv_birthdate  SYNTHEA.PATIENTS.birthdate%TYPE;
  lv_enc_start  SYNTHEA.ENCOUNTERS.start_timestamp%TYPE;
  lv_enc_class  SYNTHEA.ENCOUNTERS.encounterclass%TYPE;
BEGIN
  -- Patient identity
  SELECT p.first || ' ' || p.last,
         p.birthdate
    INTO lv_full_name,
         lv_birthdate
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_full_name || ' (DOB=' || TO_CHAR(lv_birthdate, 'YYYY-MM-DD') || ')');

  -- Most recent encounter (if none, show a friendly message)
  BEGIN
    SELECT e.start_timestamp,
           e.encounterclass
      INTO lv_enc_start,
           lv_enc_class
      FROM (
            SELECT e2.start_timestamp,
                   e2.encounterclass
              FROM SYNTHEA.ENCOUNTERS e2
             WHERE e2.patient = p_patient_id
             ORDER BY e2.start_timestamp DESC
           ) e
     WHERE ROWNUM = 1;

    DBMS_OUTPUT.PUT_LINE('Most recent encounter: ' || TO_CHAR(lv_enc_start, 'YYYY-MM-DD HH24:MI:SS') || ' class=' || lv_enc_class);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END patient_snapshot;
/

CREATE OR REPLACE PROCEDURE patient_encounter_report(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE,
  p_min_start  IN DATE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_row_num   PLS_INTEGER := 0;
  lv_rows_seen PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Encounter report for patient=' || p_patient_id || ', from=' || TO_CHAR(p_min_start, 'YYYY-MM-DD') || ', max rows=' || co_report_limit);

  FOR rec IN (
    SELECT e.start_timestamp,
           e.encounterclass,
           o.name AS org_name,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
      LEFT OUTER JOIN SYNTHEA.ORGANIZATIONS o
        ON o.id = e.organization
     WHERE e.patient = p_patient_id
       AND e.start_timestamp >= CAST(p_min_start AS TIMESTAMP)
     ORDER BY e.start_timestamp DESC
  ) LOOP
    lv_row_num := lv_row_num + 1;
    EXIT WHEN lv_row_num > co_report_limit;

    lv_rows_seen := lv_rows_seen + 1;
    DBMS_OUTPUT.PUT_LINE('Encounter ' || lv_row_num || ': ' || TO_CHAR(rec.start_timestamp, 'YYYY-MM-DD HH24:MI:SS') || ' | class=' || rec.encounterclass || ' | org=' || rec.org_name || ' | claim=' || TO_CHAR(rec.total_claim_cost));
  END LOOP;

  IF lv_rows_seen = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for given criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END patient_encounter_report;
/

