CREATE OR REPLACE FUNCTION get_patient_age_years(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) RETURN NUMBER IS
  lv_birthdate SYNTHEA.PATIENTS.birthdate%TYPE;
  lv_age       NUMBER;
BEGIN
  SELECT p.birthdate
    INTO lv_birthdate
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  lv_age := TRUNC(MONTHS_BETWEEN(SYSDATE, lv_birthdate) / 12);
  RETURN lv_age;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN NULL;
  WHEN OTHERS THEN
