CREATE OR REPLACE PACKAGE patient_ops IS
  PROCEDURE print_top_observations(
    p_patient_id IN SYNTHEA.PATIENTS.id%TYPE,
    p_start_date IN DATE,
    p_end_date   IN DATE
  );
END patient_ops;
/

CREATE OR REPLACE PACKAGE BODY patient_ops IS
  PROCEDURE print_top_observations(
    p_patient_id IN SYNTHEA.PATIENTS.id%TYPE,
    p_start_date IN DATE,
    p_end_date   IN DATE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 10; -- Top-N output limit
    lv_start DATE;
    lv_end   DATE;
    lv_row_num   PLS_INTEGER := 0;
    lv_rows_seen PLS_INTEGER := 0;
  BEGIN
    -- Open-ended range handling
    lv_start := NVL(p_start_date, TO_DATE('1900-01-01', 'YYYY-MM-DD'));
    lv_end   := NVL(p_end_date,   TO_DATE('2999-12-31', 'YYYY-MM-DD'));

    DBMS_OUTPUT.PUT_LINE('Top observations for patient=' || p_patient_id || ', range=' || TO_CHAR(lv_start, 'YYYY-MM-DD') || ' to ' || TO_CHAR(lv_end, 'YYYY-MM-DD') || ', max rows=' || co_report_limit);

    FOR rec IN (
      SELECT o.description,
             COUNT(*) AS cnt
        FROM SYNTHEA.OBSERVATIONS o
       WHERE o.patient = p_patient_id
         AND CAST(o.date_timestamp AS DATE) >= lv_start
         AND CAST(o.date_timestamp AS DATE) <= lv_end
       GROUP BY o.description
       ORDER BY COUNT(*) DESC, o.description
    ) LOOP
      lv_row_num := lv_row_num + 1;
      EXIT WHEN lv_row_num > co_report_limit;

      lv_rows_seen := lv_rows_seen + 1;
      DBMS_OUTPUT.PUT_LINE('Obs ' || lv_row_num || ': ' || rec.description || ' (count=' || rec.cnt || ')');
    END LOOP;

    IF lv_rows_seen = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No observations found for given criteria.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_observations;
END patient_ops;
/

