CREATE OR REPLACE PROCEDURE recommend_followup(
  p_patient_id      IN SYNTHEA.PATIENTS.id%TYPE,
  p_cost_threshold  IN SYNTHEA.ENCOUNTERS.total_claim_cost%TYPE
) IS
  lv_start_ts SYNTHEA.ENCOUNTERS.start_timestamp%TYPE;
  lv_claim    SYNTHEA.ENCOUNTERS.total_claim_cost%TYPE;
  lv_reason   SYNTHEA.ENCOUNTERS.reasondescription%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Follow-up check for patient=' || p_patient_id || ', threshold=' || TO_CHAR(p_cost_threshold));

  SELECT e.start_timestamp,
         e.total_claim_cost,
         e.reasondescription
    INTO lv_start_ts,
         lv_claim,
         lv_reason
    FROM (
          SELECT e2.start_timestamp,
                 e2.total_claim_cost,
                 e2.reasondescription
            FROM SYNTHEA.ENCOUNTERS e2
           WHERE e2.patient = p_patient_id
           ORDER BY e2.start_timestamp DESC
         ) e
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Latest encounter at ' || TO_CHAR(lv_start_ts, 'YYYY-MM-DD HH24:MI:SS') || ' claim=' || TO_CHAR(lv_claim) || ' reason=' || lv_reason);

  IF lv_claim >= p_cost_threshold OR lv_reason IS NOT NULL THEN
    DBMS_OUTPUT.PUT_LINE('Recommendation: FOLLOW-UP');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Recommendation: NO FOLLOW-UP');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END recommend_followup;
/

