    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_station_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE := p_station_id;
    lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;

    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF lv_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is NULL.');
      RETURN;
    END IF;

    SELECT si.name
      INTO lv_station_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
     WHERE si.station_id = lv_station_id;

    DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_id || ' - ' || lv_station_name);
