    FOR rec IN (
      SELECT ss.last_reported,
             ss.num_bikes_available,
             ss.num_docks_available,
             ss.is_renting,
             ss.is_returning
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
       WHERE ss.station_id = lv_station_id
       ORDER BY ss.last_reported DESC
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;
      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
