/

CREATE OR REPLACE PACKAGE BODY station_ops_pkg AS
  PROCEDURE print_station_snapshot(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_station_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE := p_station_id;
    lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;

    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF lv_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is NULL.');
      RETURN;
    END IF;

    SELECT si.name
      INTO lv_station_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
     WHERE si.station_id = lv_station_id;

    DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_id || ' - ' || lv_station_name);
    DBMS_OUTPUT.PUT_LINE('Snapshot (most recent first), max rows = ' || co_report_limit);

    FOR rec IN (
      SELECT ss.last_reported,
             ss.num_bikes_available,
             ss.num_docks_available,
             ss.is_renting,
             ss.is_returning
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
       WHERE ss.station_id = lv_station_id
       ORDER BY ss.last_reported DESC
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;
      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        'As of ' || rec.last_reported || ': bikes=' || rec.num_bikes_available ||
        ', docks=' || rec.num_docks_available || ', renting=' || rec.is_renting ||
        ', returning=' || rec.is_returning
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for this station.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No station info found for this station id.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_station_snapshot;

  FUNCTION get_station_availability(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE
  ) RETURN VARCHAR2 IS
    lv_station_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE := p_station_id;
    lv_bikes_avail_n NUMBER;
  BEGIN
    IF lv_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is NULL.');
      RETURN 'UNKNOWN';
    END IF;

    BEGIN
      SELECT TO_NUMBER(ss.num_bikes_available)
        INTO lv_bikes_avail_n
        FROM (
              SELECT ss.num_bikes_available
                FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
               WHERE ss.station_id = lv_station_id
               ORDER BY ss.last_reported DESC
             ) ss
       WHERE ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RETURN 'NO_STATUS';
    END;

    IF lv_bikes_avail_n = 0 THEN
      RETURN 'EMPTY';
    ELSIF lv_bikes_avail_n <= 3 THEN
      RETURN 'LOW';
    ELSE
      RETURN 'AVAILABLE';
    END IF;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN 'UNKNOWN';
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
