CREATE OR REPLACE PACKAGE station_ops_pkg AS
  PROCEDURE print_station_snapshot(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
  );

  FUNCTION get_station_availability(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE
  ) RETURN VARCHAR2;

  PROCEDURE print_region_station_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  );
END station_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY station_ops_pkg AS
  PROCEDURE print_station_snapshot(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_station_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE := p_station_id;
    lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;

    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF lv_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is NULL.');
      RETURN;
    END IF;

    SELECT si.name
      INTO lv_station_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
     WHERE si.station_id = lv_station_id;

    DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_id || ' - ' || lv_station_name);
    DBMS_OUTPUT.PUT_LINE('Snapshot (most recent first), max rows = ' || co_report_limit);

    FOR rec IN (
      SELECT ss.last_reported,
             ss.num_bikes_available,
             ss.num_docks_available,
             ss.is_renting,
             ss.is_returning
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
       WHERE ss.station_id = lv_station_id
       ORDER BY ss.last_reported DESC
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;
      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        'As of ' || rec.last_reported || ': bikes=' || rec.num_bikes_available ||
        ', docks=' || rec.num_docks_available || ', renting=' || rec.is_renting ||
        ', returning=' || rec.is_returning
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for this station.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No station info found for this station id.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_station_snapshot;

  FUNCTION get_station_availability(
    p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE
  ) RETURN VARCHAR2 IS
    lv_station_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE := p_station_id;
    lv_bikes_avail_n NUMBER;
  BEGIN
    IF lv_station_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Station id is NULL.');
      RETURN 'UNKNOWN';
    END IF;

    BEGIN
      SELECT TO_NUMBER(ss.num_bikes_available)
        INTO lv_bikes_avail_n
        FROM (
              SELECT ss.num_bikes_available
                FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
               WHERE ss.station_id = lv_station_id
               ORDER BY ss.last_reported DESC
             ) ss
       WHERE ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RETURN 'NO_STATUS';
    END;

    IF lv_bikes_avail_n = 0 THEN
      RETURN 'EMPTY';
    ELSIF lv_bikes_avail_n <= 3 THEN
      RETURN 'LOW';
    ELSE
      RETURN 'AVAILABLE';
    END IF;

  EXCEPTION
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN 'UNKNOWN';
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN 'UNKNOWN';
  END get_station_availability;

  PROCEDURE print_region_station_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_region_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE := p_region_name;
    lv_rows_printed PLS_INTEGER := 0;
    lv_availability VARCHAR2(20);
  BEGIN
    IF lv_region_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Region name is NULL.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Region: ' || p_region_name || ' (max rows = ' || co_report_limit || ')');

    FOR rec IN (
      SELECT si.station_id,
             si.name AS station_name,
             si.capacity
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
          ON r.region_id = si.region_id
       WHERE r.name = lv_region_name
       ORDER BY si.station_id
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;
      lv_rows_printed := lv_rows_printed + 1;

      lv_availability := station_ops_pkg.get_station_availability(rec.station_id);

      DBMS_OUTPUT.PUT_LINE(
        'Station ' || rec.station_id || ' - ' || rec.station_name ||
        ', capacity=' || rec.capacity || ', availability=' || lv_availability
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No stations found for this region.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_region_station_health;
END station_ops_pkg;
/

DECLARE
  lv_region_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
BEGIN
  lv_region_name := NULL;
  station_ops_pkg.print_region_station_health(lv_region_name);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

