question:
Build a quick county natality “sanity report” for a given year. The report should list up to 15 counties and show the county name, FIPS, and births. If the year is NULL, use the most recent year available in the data. If births values are not numeric, treat them as invalid and exclude them from the report.

Requirements:
Procedure Name: report_county_births
Parameters:
p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('County births report for year = ' || TO_CHAR(lv_year, 'YYYY'));
DBMS_OUTPUT.PUT_LINE(RPAD('COUNTY', 35) || RPAD('FIPS', 12) || 'BIRTHS');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || RPAD('-', 12, '-') || RPAD('-', 10, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.county_of_residence, 35) || RPAD(rec.county_of_residence_fips, 12) || TO_CHAR(rec.births_num));
DBMS_OUTPUT.PUT_LINE('No numeric births rows found for that year.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_county_births(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_year         SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Default to latest available year when NULL is passed.
  IF p_year IS NULL THEN
    SELECT MAX(year)
      INTO lv_year
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY;
  ELSE
    lv_year := p_year;
  END IF;

  DBMS_OUTPUT.PUT_LINE('County births report for year = ' || TO_CHAR(lv_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE(RPAD('COUNTY', 35) || RPAD('FIPS', 12) || 'BIRTHS');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || RPAD('-', 12, '-') || RPAD('-', 10, '-'));

  FOR rec IN (
    SELECT county_of_residence,
           county_of_residence_fips,
           TO_NUMBER(births) AS births_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
     WHERE year = lv_year
       AND REGEXP_LIKE(births, '^[0-9]+(\.[0-9]+)?$')
     ORDER BY TO_NUMBER(births) DESC, county_of_residence
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 35) ||
      RPAD(rec.county_of_residence_fips, 12) ||
      TO_CHAR(rec.births_num)
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No numeric births rows found for that year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_births;
/

