CREATE OR REPLACE FUNCTION get_births_delta(
  p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE,
  p_year1       IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_year2       IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) RETURN NUMBER IS
  lv_births1 NUMBER;
  lv_births2 NUMBER;
  lv_delta  NUMBER;
BEGIN
  -- Convert births only when numeric; otherwise treat as missing.
  SELECT TO_NUMBER(births)
    INTO lv_births1
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
   WHERE county_of_residence_fips = p_county_fips
     AND year = p_year1
     AND REGEXP_LIKE(births, '^[0-9]+(\.[0-9]+)?$');

  SELECT TO_NUMBER(births)
    INTO lv_births2
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
   WHERE county_of_residence_fips = p_county_fips
     AND year = p_year2
     AND REGEXP_LIKE(births, '^[0-9]+(\.[0-9]+)?$');

  lv_delta := lv_births2 - lv_births1;

  DBMS_OUTPUT.PUT_LINE(
    'Births delta for county FIPS ' || p_county_fips || ' (year2-year1) = ' || TO_CHAR(lv_delta)
  );

  RETURN lv_delta;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Cannot compute delta; missing numeric births for one or both years.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END get_births_delta;
/

