CREATE OR REPLACE PROCEDURE report_top_counties_by_births(
  p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_name_prefix IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
  p_max_rows    IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Cap output for readability
  lv_rows_to_print PLS_INTEGER;
  lv_printed       PLS_INTEGER := 0;
BEGIN
  -- Validate and normalize row limit
  IF p_max_rows IS NULL OR p_max_rows < 1 THEN
    RAISE VALUE_ERROR;
  END IF;

  IF p_max_rows > co_report_limit THEN
    lv_rows_to_print := co_report_limit;
  ELSE
    lv_rows_to_print := p_max_rows;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top counties by births for year ' || TO_CHAR(p_year, 'YYYY'));

  IF p_name_prefix IS NOT NULL THEN
    DBMS_OUTPUT.PUT_LINE('Filter: county starts with ' || p_name_prefix);

    FOR rec IN (
      SELECT cn.county_of_residence,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
         AND cn.county_of_residence LIKE p_name_prefix || '%'
       ORDER BY TO_NUMBER(cn.births) DESC
      FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      EXIT WHEN lv_printed >= lv_rows_to_print;
      DBMS_OUTPUT.PUT_LINE('County: ' || rec.county_of_residence || ' | Births: ' || rec.births);
      lv_printed := lv_printed + 1;
    END LOOP;
  ELSE
    DBMS_OUTPUT.PUT_LINE('Filter: none');

    FOR rec IN (
      SELECT cn.county_of_residence,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
       ORDER BY TO_NUMBER(cn.births) DESC
      FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      EXIT WHEN lv_printed >= lv_rows_to_print;
      DBMS_OUTPUT.PUT_LINE('County: ' || rec.county_of_residence || ' | Births: ' || rec.births);
      lv_printed := lv_printed + 1;
    END LOOP;
  END IF;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No counties found for the given inputs.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No counties found for the given inputs.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid max rows value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_counties_by_births;
/

