    p_county    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
    p_threshold IN NUMBER
  ) RETURN VARCHAR2;

  PROCEDURE print_classification_report(
    p_year      IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_threshold IN NUMBER
  );
END county_natality_pkg;
/

CREATE OR REPLACE PACKAGE BODY county_natality_pkg IS
  FUNCTION classify_births(
    p_year      IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_county    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
    p_threshold IN NUMBER
  ) RETURN VARCHAR2 IS
    lv_births SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.births%TYPE;
  BEGIN
    IF p_threshold IS NULL OR p_threshold < 0 THEN
      RAISE VALUE_ERROR;
    END IF;

    SELECT cn.births
      INTO lv_births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_year
       AND cn.county_of_residence = p_county;

    IF TO_NUMBER(lv_births) >= p_threshold THEN
      RETURN 'HIGH';
    ELSE
      RETURN 'LOW';
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 'LOW';
    WHEN VALUE_ERROR THEN
      RETURN 'LOW';
    WHEN TOO_MANY_ROWS THEN
      RETURN 'LOW';
    WHEN OTHERS THEN
      RETURN 'LOW';
  END classify_births;

  PROCEDURE print_classification_report(
    p_year      IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_threshold IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_printed PLS_INTEGER := 0;
    lv_class   VARCHAR2(10);
  BEGIN
    IF p_threshold IS NULL OR p_threshold < 0 THEN
      RAISE VALUE_ERROR;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Classification report for year ' || TO_CHAR(p_year, 'YYYY') || ' (threshold=' || p_threshold || ')');

    FOR rec IN (
      SELECT cn.county_of_residence,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
       ORDER BY TO_NUMBER(cn.births) DESC
      FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_class := classify_births(p_year => p_year, p_county => rec.county_of_residence, p_threshold => p_threshold);
      DBMS_OUTPUT.PUT_LINE('County: ' || rec.county_of_residence || ' | Births: ' || rec.births || ' | Class: ' || lv_class);
      lv_printed := lv_printed + 1;
    END LOOP;

    IF lv_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No counties found for the report inputs.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid threshold value.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_classification_report;
END county_natality_pkg;
/

