WHEN TOO_MANY_ROWS THEN: 'Multiple latest solution rows found.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE FUNCTION get_solution_score_band(
  p_solution_name IN STACKING.SOLUTION.NAME%TYPE
) RETURN VARCHAR2 IS
  lv_score STACKING.SOLUTION.SCORE%TYPE;
  lv_band  VARCHAR2(20);
BEGIN
  IF p_solution_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Solution name is required.');
    RETURN 'UNKNOWN';
  END IF;

  SELECT s.score
    INTO lv_score
    FROM STACKING.SOLUTION s
   WHERE s.name = p_solution_name
     AND s.version = (
           SELECT MAX(s2.version)
             FROM STACKING.SOLUTION s2
            WHERE s2.name = p_solution_name
         );

  IF lv_score IS NULL THEN
    lv_band := 'UNSCORED';
  ELSIF lv_score >= 90 THEN
    lv_band := 'HIGH';
  ELSIF lv_score >= 70 THEN
    lv_band := 'MEDIUM';
  ELSE
    lv_band := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Score band for ' || p_solution_name || ' is ' || lv_band || '.');
  RETURN lv_band;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching solution found.');
    RETURN 'NOT_FOUND';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple latest solution rows found.');
    RETURN 'DUPLICATE';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'ERROR';
END get_solution_score_band;
/

