Requirements:
Procedure Name: diagnose_solution_portfolio
Parameters: p_solution_name IN STACKING.SOLUTION.NAME%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Solution name is required.');
DBMS_OUTPUT.PUT_LINE('No matching solution found.');
DBMS_OUTPUT.PUT_LINE('Portfolio diagnosis for ' || p_solution_name || ':');
DBMS_OUTPUT.PUT_LINE('Versions=' || lv_solution_count || ', AverageScore=' || lv_avg_score || ', BestScore=' || lv_best_score || ', LowestScore=' || lv_low_score);
DBMS_OUTPUT.PUT_LINE('Portfolio has no scored versions.');
DBMS_OUTPUT.PUT_LINE('Portfolio condition is strong.');
DBMS_OUTPUT.PUT_LINE('Portfolio condition needs review.');
DBMS_OUTPUT.PUT_LINE('Top feature importance signals:');
DBMS_OUTPUT.PUT_LINE('Feature=' || rec.feature || ', TotalImportance=' || rec.total_importance);
DBMS_OUTPUT.PUT_LINE('No feature importance rows found.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE diagnose_solution_portfolio(
  p_solution_name IN STACKING.SOLUTION.NAME%TYPE
) IS
  co_report_limit   CONSTANT NUMBER := 15; -- Limit output for report readability
  lv_solution_count NUMBER := 0;
  lv_avg_score      STACKING.SOLUTION.SCORE%TYPE;
  lv_best_score     STACKING.SOLUTION.SCORE%TYPE;
  lv_low_score      STACKING.SOLUTION.SCORE%TYPE;
  lv_feature_rows   NUMBER := 0;
BEGIN
  IF p_solution_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Solution name is required.');
    RETURN;
  END IF;

  SELECT COUNT(*),
         AVG(s.score),
         MAX(s.score),
         MIN(s.score)
    INTO lv_solution_count,
         lv_avg_score,
         lv_best_score,
         lv_low_score
    FROM STACKING.SOLUTION s
   WHERE s.name = p_solution_name;

  IF lv_solution_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matching solution found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Portfolio diagnosis for ' || p_solution_name || ':');
  DBMS_OUTPUT.PUT_LINE('Versions=' || lv_solution_count || ', AverageScore=' || lv_avg_score || ', BestScore=' || lv_best_score || ', LowestScore=' || lv_low_score);

  IF lv_avg_score IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Portfolio has no scored versions.');
  ELSIF lv_avg_score >= 80 THEN
    DBMS_OUTPUT.PUT_LINE('Portfolio condition is strong.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Portfolio condition needs review.');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top feature importance signals:');

  FOR rec IN (
    SELECT limited.feature,
           limited.total_importance
      FROM (
            SELECT fi.feature,
                   SUM(fi.importance) AS total_importance
              FROM STACKING.FEATURE_IMPORTANCE fi
             WHERE fi.name = p_solution_name
             GROUP BY fi.feature
             ORDER BY SUM(fi.importance) DESC, fi.feature ASC
           ) limited
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_feature_rows := lv_feature_rows + 1;
    DBMS_OUTPUT.PUT_LINE('Feature=' || rec.feature || ', TotalImportance=' || rec.total_importance);
  END LOOP;

  IF lv_feature_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No feature importance rows found.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END diagnose_solution_portfolio;
/

CREATE OR REPLACE PROCEDURE report_station_status(
  p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE,
  p_hours_back   IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_station_id   SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE;
  lv_station_name SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE;
  lv_dockcount    SAN_FRANCISCO.BIKESHARE_STATIONS.dockcount%TYPE;
  lv_landmark     SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
  lv_hours_back   NUMBER;
BEGIN
  -- Validate hours window early (also protects against NULL)
  lv_hours_back := p_hours_back;
  IF lv_hours_back IS NULL OR lv_hours_back <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
    RETURN;
  END IF;

  -- Resolve station by name (enforces single-station expectation)
  SELECT s.station_id, s.name, s.dockcount, s.landmark
    INTO lv_station_id, lv_station_name, lv_dockcount, lv_landmark
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE s.name = p_station_name;

  DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (ID=' || lv_station_id || '), dockcount=' || lv_dockcount || ', landmark=' || lv_landmark);
  DBMS_OUTPUT.PUT_LINE('Status snapshots in last ' || p_hours_back || ' hours (most recent first), max rows=' || co_report_limit);

  FOR r IN (
    SELECT st.time,
           st.bikes_available,
           st.docks_available
      FROM SAN_FRANCISCO.BIKESHARE_STATUS st
     WHERE st.station_id = lv_station_id
       AND st.time >= SYSTIMESTAMP - NUMTODSINTERVAL(lv_hours_back, 'HOUR')
     ORDER BY st.time DESC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE('As of ' || TO_CHAR(r.time, 'YYYY-MM-DD HH24:MI:SS') || ': bikes=' || r.bikes_available || ', docks=' || r.docks_available);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No status rows found for this station in the requested window.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_status;
/

CREATE OR REPLACE FUNCTION get_station_risk(
  p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE,
  p_hours_back   IN NUMBER
) RETURN VARCHAR2 IS
  lv_station_id   SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE;
  lv_station_name SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE;
  lv_dockcount    SAN_FRANCISCO.BIKESHARE_STATIONS.dockcount%TYPE;

  lv_bikes        SAN_FRANCISCO.BIKESHARE_STATUS.bikes_available%TYPE;
  lv_as_of        SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;

  lv_hours_back   NUMBER;
  lv_dock_num     NUMBER;
  lv_bikes_num    NUMBER;
  lv_risk         VARCHAR2(10);
BEGIN
  lv_hours_back := p_hours_back;
  IF lv_hours_back IS NULL OR lv_hours_back <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
    RETURN 'UNKNOWN';
  END IF;

  SELECT s.station_id, s.name, s.dockcount
    INTO lv_station_id, lv_station_name, lv_dockcount
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE s.name = p_station_name;

  -- Get the most recent status snapshot in the requested window.
  SELECT x.time, x.bikes_available
    INTO lv_as_of, lv_bikes
    FROM (
          SELECT st.time,
                 st.bikes_available,
                 ROW_NUMBER() OVER (ORDER BY st.time DESC) AS rn
            FROM SAN_FRANCISCO.BIKESHARE_STATUS st
           WHERE st.station_id = lv_station_id
             AND st.time >= SYSTIMESTAMP - NUMTODSINTERVAL(lv_hours_back, 'HOUR')
         ) x
   WHERE x.rn = 1;

  lv_dock_num := TO_NUMBER(lv_dockcount);
  lv_bikes_num := TO_NUMBER(lv_bikes);

  IF lv_bikes_num = 0 THEN
    lv_risk := 'HIGH';
  ELSIF lv_dock_num > 0 AND lv_bikes_num / lv_dock_num <= 0.10 THEN
    lv_risk := 'MEDIUM';
  ELSE
    lv_risk := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Risk eval for station=' || lv_station_name || ' (ID=' || lv_station_id || '), as_of=' || TO_CHAR(lv_as_of, 'YYYY-MM-DD HH24:MI:SS') || ', bikes=' || lv_bikes || ', dockcount=' || lv_dockcount || ' => ' || lv_risk);

  RETURN lv_risk;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'UNKNOWN';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'UNKNOWN';
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
    RETURN 'UNKNOWN';
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
END get_station_risk;
/

CREATE OR REPLACE PACKAGE bikeshare_ops IS
  PROCEDURE run_station_check(
    p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE,
    p_hours_back   IN NUMBER
  );
END bikeshare_ops;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops IS
  PROCEDURE run_station_check(
    p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE,
    p_hours_back   IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_station_id   SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE;
    lv_station_name SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE;
    lv_dockcount    SAN_FRANCISCO.BIKESHARE_STATIONS.dockcount%TYPE;
    lv_landmark     SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE;

    lv_rows_printed PLS_INTEGER := 0;
    lv_hours_back   NUMBER;

    -- Risk evaluation variables (mirrors the function's decision inputs)
    lv_as_of        SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
    lv_bikes        SAN_FRANCISCO.BIKESHARE_STATUS.bikes_available%TYPE;
    lv_risk         VARCHAR2(10);
  BEGIN
    DBMS_OUTPUT.PUT_LINE('=== Station Check Start ===');

    lv_hours_back := p_hours_back;
    IF lv_hours_back IS NULL OR lv_hours_back <= 0 THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input value.');
      DBMS_OUTPUT.PUT_LINE('=== Station Check End ===');
      RETURN;
    END IF;

    -- Resolve station once for both reporting and risk
    SELECT s.station_id, s.name, s.dockcount, s.landmark
      INTO lv_station_id, lv_station_name, lv_dockcount, lv_landmark
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.name = p_station_name;

    DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (ID=' || lv_station_id || '), dockcount=' || lv_dockcount || ', landmark=' || lv_landmark);
    DBMS_OUTPUT.PUT_LINE('Status snapshots in last ' || p_hours_back || ' hours (most recent first), max rows=' || co_report_limit);

    FOR r IN (
      SELECT st.time,
             st.bikes_available,
             st.docks_available
        FROM SAN_FRANCISCO.BIKESHARE_STATUS st
       WHERE st.station_id = lv_station_id
         AND st.time >= SYSTIMESTAMP - NUMTODSINTERVAL(lv_hours_back, 'HOUR')
       ORDER BY st.time DESC
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      EXIT WHEN lv_rows_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE('As of ' || TO_CHAR(r.time, 'YYYY-MM-DD HH24:MI:SS') || ': bikes=' || r.bikes_available || ', docks=' || r.docks_available);
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for this station in the requested window.');
    END IF;

    -- Risk evaluation: reuse the standalone function, then print escalation if needed.
    lv_risk := get_station_risk(p_station_name => p_station_name, p_hours_back => p_hours_back);

    -- Also print a consistent risk line here for operations runbooks.
    BEGIN
      SELECT x.time, x.bikes_available
        INTO lv_as_of, lv_bikes
        FROM (
              SELECT st.time,
                     st.bikes_available,
                     ROW_NUMBER() OVER (ORDER BY st.time DESC) AS rn
                FROM SAN_FRANCISCO.BIKESHARE_STATUS st
               WHERE st.station_id = lv_station_id
                 AND st.time >= SYSTIMESTAMP - NUMTODSINTERVAL(lv_hours_back, 'HOUR')
             ) x
       WHERE x.rn = 1;

      DBMS_OUTPUT.PUT_LINE('Risk eval for station=' || lv_station_name || ' (ID=' || lv_station_id || '), as_of=' || TO_CHAR(lv_as_of, 'YYYY-MM-DD HH24:MI:SS') || ', bikes=' || lv_bikes || ', dockcount=' || lv_dockcount || ' => ' || lv_risk);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No data found.');
      WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Invalid input value.');
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    END;

    IF lv_risk = 'HIGH' THEN
      DBMS_OUTPUT.PUT_LINE('ESCALATE: Station has zero bikes available.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('=== Station Check End ===');

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      DBMS_OUTPUT.PUT_LINE('=== Station Check End ===');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      DBMS_OUTPUT.PUT_LINE('=== Station Check End ===');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input value.');
      DBMS_OUTPUT.PUT_LINE('=== Station Check End ===');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      DBMS_OUTPUT.PUT_LINE('=== Station Check End ===');
  END run_station_check;
END bikeshare_ops;
/

