CREATE OR REPLACE PROCEDURE dei_rep_report(
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_row_count    PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Workforce=' || p_workforce || ', Report Year=' || p_report_year);

  FOR r IN (
    SELECT
      ir.gender_us,
      ir.race_asian,
      ir.race_black,
      ir.race_hispanic_latinx,
      ir.race_native_american,
      ir.race_white
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION ir
    WHERE ir.workforce = p_workforce
      AND ir.report_year = p_report_year
      AND ROWNUM <= co_report_limit
    ORDER BY ir.gender_us
  ) LOOP
    lv_row_count := lv_row_count + 1;
    DBMS_OUTPUT.PUT_LINE(
      'Gender=' || r.gender_us ||
      ', Asian=' || r.race_asian ||
      ', Black=' || r.race_black ||
      ', Hispanic/Latinx=' || r.race_hispanic_latinx ||
      ', Native American=' || r.race_native_american ||
      ', White=' || r.race_white
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No representation rows found for the requested workforce/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END dei_rep_report;
/

CREATE OR REPLACE FUNCTION dei_rep_status(
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
) RETURN VARCHAR2 IS
  lv_cnt    NUMBER;
  lv_status VARCHAR2(20);
BEGIN
  SELECT COUNT(*)
    INTO lv_cnt
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION ir
   WHERE ir.workforce = p_workforce
     AND ir.report_year = p_report_year;

  IF lv_cnt > 0 THEN
    lv_status := 'OK';
  ELSE
    lv_status := 'NO_DATA';
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Representation status for Workforce=' || p_workforce ||
    ', Report Year=' || p_report_year ||
    ' is ' || lv_status
  );

  RETURN lv_status;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'NO_DATA';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'NO_DATA';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'NO_DATA';
END dei_rep_status;
/

