CREATE OR REPLACE PROCEDURE get_country_demo_snapshot(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
  p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
) IS
  lv_tfr  CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_grr  CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.gross_reproduction_rate%TYPE;
  lv_srab CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.sex_ratio_at_birth%TYPE;
  lv_le   CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY.life_expectancy%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Country: ' || p_country_name || ', Year: ' || p_year);

  -- Fetch fertility metrics for the requested country/year.
  SELECT f.total_fertility_rate,
         f.gross_reproduction_rate,
         f.sex_ratio_at_birth
    INTO lv_tfr,
         lv_grr,
         lv_srab
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
   WHERE f.country_name = p_country_name
     AND f.year = p_year;

  -- Fetch life expectancy for the same country/year.
  SELECT m.life_expectancy
    INTO lv_le
    FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
   WHERE m.country_name = p_country_name
     AND m.year = p_year;

  DBMS_OUTPUT.PUT_LINE('Total fertility rate: ' || lv_tfr);
  DBMS_OUTPUT.PUT_LINE('Gross reproduction rate: ' || lv_grr);
  DBMS_OUTPUT.PUT_LINE('Sex ratio at birth: ' || lv_srab);
  DBMS_OUTPUT.PUT_LINE('Life expectancy: ' || lv_le);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END get_country_demo_snapshot;
/

