CREATE OR REPLACE PACKAGE demo_pkg IS
  PROCEDURE report_infant_mortality_gap(
    p_year IN CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY.year%TYPE
  );

  FUNCTION demographic_pressure_score(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) RETURN NUMBER;
END demo_pkg;
/

CREATE OR REPLACE PACKAGE BODY demo_pkg IS
  PROCEDURE report_infant_mortality_gap(
    p_year IN CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_gap IS
      SELECT *
        FROM (
          SELECT m.country_name,
                 TO_NUMBER(m.infant_mortality_female) AS im_f,
                 TO_NUMBER(m.infant_mortality_male)   AS im_m,
                 (TO_NUMBER(m.infant_mortality_female) - TO_NUMBER(m.infant_mortality_male)) AS gap
            FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
            JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA a
              ON a.country_code = m.country_code
           WHERE m.year = p_year
             AND m.infant_mortality_female IS NOT NULL
             AND m.infant_mortality_male IS NOT NULL
           ORDER BY (TO_NUMBER(m.infant_mortality_female) - TO_NUMBER(m.infant_mortality_male)) DESC,
                    m.country_name
        )
       WHERE ROWNUM <= co_report_limit;

    lv_rank PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Infant mortality gap report for year ' || p_year || ' (max rows = ' || co_report_limit || ')');

    FOR rec IN c_gap LOOP
      lv_rank := lv_rank + 1;
      DBMS_OUTPUT.PUT_LINE('Rank ' || lv_rank || ': ' || rec.country_name || ' | female=' || rec.im_f || ' | male=' || rec.im_m || ' | gap=' || TO_CHAR(rec.gap));
    END LOOP;

    IF lv_rank = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the criteria.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Value error.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_infant_mortality_gap;

  FUNCTION demographic_pressure_score(
    p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_year         IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) RETURN NUMBER IS
    lv_tfr_num NUMBER;
    lv_le_num  NUMBER;
    lv_score   NUMBER;
  BEGIN
    IF p_country_name IS NULL OR p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Cannot compute score (missing inputs).');
      RETURN NULL;
    END IF;

    SELECT TO_NUMBER(f.total_fertility_rate)
      INTO lv_tfr_num
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
     WHERE f.country_name = p_country_name
       AND f.year = p_year;

    SELECT TO_NUMBER(m.life_expectancy)
      INTO lv_le_num
      FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
     WHERE m.country_name = p_country_name
       AND m.year = p_year;

    IF lv_le_num = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Cannot compute score (life expectancy is zero).');
      RETURN NULL;
    END IF;

    lv_score := lv_tfr_num / lv_le_num;
    DBMS_OUTPUT.PUT_LINE('Score: ' || TO_CHAR(lv_score));
    RETURN lv_score;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN NULL;
    WHEN ZERO_DIVIDE THEN
      DBMS_OUTPUT.PUT_LINE('Cannot compute score (life expectancy is zero).');
      RETURN NULL;
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Value error.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END demographic_pressure_score;
END demo_pkg;
/

