CREATE OR REPLACE PROCEDURE print_country_yearly_rollup(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_years IS
    SELECT year
      FROM (
        SELECT DISTINCT f.year AS year
          FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
         WHERE f.country_name = p_country_name
        UNION
        SELECT DISTINCT m.year AS year
          FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
         WHERE m.country_name = p_country_name
      )
     ORDER BY year DESC;

  lv_year   CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;
  lv_tfr    CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_le     CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY.life_expectancy%TYPE;
  lv_score  NUMBER;
  lv_rows   PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Yearly rollup for ' || p_country_name || ' (max years = ' || co_report_limit || ')');

  OPEN c_years;
  LOOP
    FETCH c_years INTO lv_year;
    EXIT WHEN c_years%NOTFOUND OR lv_rows >= co_report_limit;

    lv_rows := lv_rows + 1;

    -- Default to NULL; lookups may fail per-year.
    lv_tfr := NULL;
    lv_le  := NULL;

    BEGIN
      SELECT f.total_fertility_rate
        INTO lv_tfr
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
       WHERE f.country_name = p_country_name
         AND f.year = lv_year;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_tfr := NULL;
      WHEN TOO_MANY_ROWS THEN
        lv_tfr := NULL;
    END;

    BEGIN
      SELECT m.life_expectancy
        INTO lv_le
        FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
       WHERE m.country_name = p_country_name
         AND m.year = lv_year;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_le := NULL;
      WHEN TOO_MANY_ROWS THEN
        lv_le := NULL;
    END;

    lv_score := demo_pkg.demographic_pressure_score(p_country_name, lv_year);

    DBMS_OUTPUT.PUT_LINE('Year ' || lv_year || ' | TFR=' || lv_tfr || ' | LE=' || lv_le || ' | Score=' || TO_CHAR(lv_score));
  END LOOP;
  CLOSE c_years;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matching years found for this country.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Value error.');
  WHEN OTHERS THEN
    -- Ensure cursor is not left open on unexpected failure.
    IF c_years%ISOPEN THEN
      CLOSE c_years;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END print_country_yearly_rollup;
/

