CREATE OR REPLACE PROCEDURE rpt_region_station_availability(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region_like   SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
  lv_chosen_region SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
  lv_chosen_id     SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Station availability report. Max rows = ' || co_report_limit);
  DBMS_OUTPUT.PUT_LINE('Region filter used = ' || NVL(p_region_name, '[AUTO]'));

  IF p_region_name IS NULL THEN
    -- Choose the region with the highest station count.
    SELECT r.name, r.region_id
      INTO lv_chosen_region, lv_chosen_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        ON si.region_id = r.region_id
     GROUP BY r.name, r.region_id
     ORDER BY COUNT(*) DESC
     FETCH FIRST 1 ROW ONLY;
  ELSE
    lv_region_like := '%' || p_region_name || '%';

    SELECT r.name, r.region_id
      INTO lv_chosen_region, lv_chosen_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE UPPER(r.name) LIKE UPPER(lv_region_like)
     FETCH FIRST 1 ROW ONLY;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Chosen region = ' || lv_chosen_region);

  FOR rec IN (
    SELECT si.name AS station_name,
           TO_NUMBER(si.capacity) AS capacity,
           TO_NUMBER(ss.num_bikes_available) AS bikes,
           TO_NUMBER(ss.num_docks_available) AS docks,
           CASE
             WHEN TO_NUMBER(ss.num_bikes_available) <= CEIL(TO_NUMBER(si.capacity) * 0.10) THEN 'LOW_BIKES'
             WHEN TO_NUMBER(ss.num_docks_available) <= CEIL(TO_NUMBER(si.capacity) * 0.10) THEN 'LOW_DOCKS'
             ELSE 'OK'
           END AS status_label
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
        ON ss.station_id = si.station_id
     WHERE si.region_id = lv_chosen_id
       AND ROWNUM <= co_report_limit
     ORDER BY si.name
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('- ' || rec.station_name || ' | cap=' || rec.capacity || ' | bikes=' || rec.bikes || ' | docks=' || rec.docks || ' | status=' || rec.status_label);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_region_station_availability;
/

