CREATE OR REPLACE PROCEDURE rpt_station_health(
  p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_station_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_region_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.region_id%TYPE;
  lv_region_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;

  lv_installed SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_installed%TYPE;
  lv_renting   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_renting%TYPE;
  lv_returning SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_returning%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Station health report. Max rows = ' || co_report_limit);

  IF p_station_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input station name is NULL; report skipped.');
    RETURN;
  END IF;

  SELECT si.station_id, si.name, si.region_id
    INTO lv_station_id, lv_station_name, lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
   WHERE UPPER(si.name) = UPPER(p_station_name)
   FETCH FIRST 1 ROW ONLY;

  SELECT r.name
    INTO lv_region_name
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE r.region_id = lv_region_id;

  SELECT ss.is_installed, ss.is_renting, ss.is_returning
    INTO lv_installed, lv_renting, lv_returning
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
   WHERE ss.station_id = lv_station_id
   ORDER BY TO_NUMBER(ss.last_reported) DESC
   FETCH FIRST 1 ROW ONLY;

  DBMS_OUTPUT.PUT_LINE('Station = ' || lv_station_name);
  DBMS_OUTPUT.PUT_LINE('Region = ' || lv_region_name);
  DBMS_OUTPUT.PUT_LINE('Flags: installed=' || lv_installed || ', renting=' || lv_renting || ', returning=' || lv_returning);
  DBMS_OUTPUT.PUT_LINE('Recent snapshots (most recent first):');

  FOR rec IN (
    SELECT TO_TIMESTAMP('1970-01-01 00:00:00', 'YYYY-MM-DD HH24:MI:SS')
             + NUMTODSINTERVAL(TO_NUMBER(ss.last_reported), 'SECOND') AS as_of_ts,
           TO_NUMBER(ss.num_bikes_available) AS bikes,
           TO_NUMBER(ss.num_docks_available) AS docks,
           TO_NUMBER(ss.num_ebikes_available) AS ebikes
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
     WHERE ss.station_id = lv_station_id
     ORDER BY TO_NUMBER(ss.last_reported) DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('AsOf=' || TO_CHAR(rec.as_of_ts, 'YYYY-MM-DD HH24:MI:SS') || ' bikes=' || rec.bikes || ' docks=' || rec.docks || ' ebikes=' || rec.ebikes);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_station_health;
/

