CREATE OR REPLACE FUNCTION fn_busiest_start_station(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
  p_month_start IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE
) RETURN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE IS
  lv_region_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
  lv_region_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;

  lv_month_start  SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE;
  lv_month_end    SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE;

  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_trip_count   NUMBER;
BEGIN
  -- Default month start if not provided.
  IF p_month_start IS NULL THEN
    SELECT MIN(t.start_date)
      INTO lv_month_start
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t;
  ELSE
    lv_month_start := p_month_start;
  END IF;

  lv_month_end := ADD_MONTHS(lv_month_start, 1);

  DBMS_OUTPUT.PUT_LINE('Busiest start station inputs: region=' || NVL(p_region_name, '[AUTO]') || ', month_start=' || TO_CHAR(lv_month_start, 'YYYY-MM-DD'));

  IF lv_month_end <= lv_month_start THEN
    DBMS_OUTPUT.PUT_LINE('Invalid month_start: end is not after start. Returning UNKNOWN.');
    RETURN 'UNKNOWN';
  END IF;

  -- Resolve region (auto-pick if NULL).
  IF p_region_name IS NULL THEN
    SELECT r.name, r.region_id
      INTO lv_region_name, lv_region_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        ON si.region_id = r.region_id
     GROUP BY r.name, r.region_id
     ORDER BY COUNT(*) DESC
     FETCH FIRST 1 ROW ONLY;
  ELSE
    SELECT r.name, r.region_id
      INTO lv_region_name, lv_region_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE UPPER(r.name) LIKE UPPER('%' || p_region_name || '%')
     FETCH FIRST 1 ROW ONLY;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Chosen region = ' || lv_region_name);

  -- Determine busiest start station within the region and month window.
  SELECT station_name, trip_count
    INTO lv_station_name, lv_trip_count
    FROM (
      SELECT t.start_station_name AS station_name,
             COUNT(*) AS trip_count
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          ON UPPER(si.name) = UPPER(t.start_station_name)
       WHERE si.region_id = lv_region_id
         AND t.start_date >= lv_month_start
         AND t.start_date < lv_month_end
       GROUP BY t.start_station_name
       ORDER BY COUNT(*) DESC, MIN(t.start_station_name) ASC
    )
   FETCH FIRST 1 ROW ONLY;

  DBMS_OUTPUT.PUT_LINE('Busiest start station = ' || lv_station_name || ' (trips=' || lv_trip_count || ')');

  RETURN lv_station_name;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'UNKNOWN';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'UNKNOWN';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNKNOWN';
END fn_busiest_start_station;
/

