CREATE OR REPLACE PACKAGE BODY bikeshare_ops_pkg IS
  PROCEDURE print_monthly_briefing(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
    p_month_start IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_region_name   SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
    lv_region_id     SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
    lv_month_start   SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE;
    lv_busiest_station SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Monthly ops briefing. Max rows = ' || co_report_limit);

    IF p_month_start IS NULL THEN
      SELECT MIN(t.start_date)
        INTO lv_month_start
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t;
    ELSE
      lv_month_start := p_month_start;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Inputs: region=' || NVL(p_region_name, '[AUTO]') || ', month_start=' || TO_CHAR(lv_month_start, 'YYYY-MM-DD'));

    IF p_region_name IS NULL THEN
      SELECT r.name, r.region_id
        INTO lv_region_name, lv_region_id
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          ON si.region_id = r.region_id
       GROUP BY r.name, r.region_id
       ORDER BY COUNT(*) DESC
       FETCH FIRST 1 ROW ONLY;
    ELSE
      SELECT r.name, r.region_id
        INTO lv_region_name, lv_region_id
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
       WHERE UPPER(r.name) LIKE UPPER('%' || p_region_name || '%')
       FETCH FIRST 1 ROW ONLY;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Chosen region = ' || lv_region_name);

    lv_busiest_station := fn_busiest_start_station(lv_region_name, lv_month_start);
    DBMS_OUTPUT.PUT_LINE('Busiest start station (month) = ' || lv_busiest_station);

    FOR rec IN (
      WITH ranked AS (
        SELECT si.name AS station_name,
               si.capacity AS capacity_txt,
               CASE
                 WHEN REGEXP_LIKE(TRIM(si.capacity), '^[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(TRIM(si.capacity))
                 ELSE NULL
               END AS capacity_num,
               CASE
                 WHEN REGEXP_LIKE(TRIM(si.capacity), '^[0-9]+(\.[0-9]+)?$') AND TO_NUMBER(TRIM(si.capacity)) > 0
                   THEN TO_NUMBER(ss.num_bikes_available) / TO_NUMBER(TRIM(si.capacity))
                 ELSE NULL
               END AS bike_ratio,
               TO_NUMBER(ss.num_bikes_available) AS bikes,
               ROW_NUMBER() OVER (
                 ORDER BY
                   CASE
                     WHEN REGEXP_LIKE(TRIM(si.capacity), '^[0-9]+(\.[0-9]+)?$') AND TO_NUMBER(TRIM(si.capacity)) > 0
                       THEN TO_NUMBER(ss.num_bikes_available) / TO_NUMBER(TRIM(si.capacity))
                     ELSE -1
                   END DESC,
                   si.name ASC
               ) AS rn
          FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
            ON ss.station_id = si.station_id
         WHERE si.region_id = lv_region_id
      )
      SELECT station_name,
             capacity_txt,
             capacity_num,
             bike_ratio,
             bikes,
             rn
        FROM ranked
       WHERE rn <= co_report_limit
       ORDER BY rn
    ) LOOP
      IF rec.capacity_num IS NULL OR rec.capacity_num = 0 OR rec.bike_ratio IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Capacity parse issue for station: ' || rec.station_name || ' (capacity=' || rec.capacity_txt || ')');
      ELSE
        DBMS_OUTPUT.PUT_LINE('#' || rec.rn || ' ' || rec.station_name || ' | cap=' || rec.capacity_num || ' | bikes=' || rec.bikes || ' | ratio=' || TO_CHAR(rec.bike_ratio, '0.000'));
      END IF;
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_monthly_briefing;
END bikeshare_ops_pkg;
/

