CREATE OR REPLACE PROCEDURE rpt_payer_high_cost_encounters(
  p_payer_id IN SYNTHEA.ENCOUNTERS.payer%TYPE
) IS
  co_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_payer_id SYNTHEA.ENCOUNTERS.payer%TYPE;
  lv_avg_cost SYNTHEA.ENCOUNTERS.total_claim_cost%TYPE;
  lv_rows     PLS_INTEGER := 0;
BEGIN
  IF p_payer_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: payer id is required.');
    RETURN;
  END IF;

  lv_payer_id := p_payer_id;

  SELECT AVG(e.total_claim_cost)
    INTO lv_avg_cost
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.payer = lv_payer_id;

  IF lv_avg_cost IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for payer ' || lv_payer_id);
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Payer ' || lv_payer_id || ' average total_claim_cost = ' || TO_CHAR(lv_avg_cost));

  FOR r IN (
    SELECT e.id,
           e.patient,
           e.start_timestamp,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.payer = lv_payer_id
       AND e.total_claim_cost > lv_avg_cost
     ORDER BY e.total_claim_cost DESC
  ) LOOP
    EXIT WHEN lv_rows >= co_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Encounter ' || r.id || ' | patient ' || r.patient || ' | start ' || TO_CHAR(r.start_timestamp, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | total_claim_cost ' || TO_CHAR(r.total_claim_cost)
    );
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for payer ' || lv_payer_id);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_payer_high_cost_encounters;
/

