CREATE OR REPLACE PROCEDURE report_top_hr_batters(
  p_year IN BASEBALL.BATTING.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year BASEBALL.BATTING.year%TYPE;

  CURSOR c_top_batters(p_cursor_year BASEBALL.BATTING.year%TYPE) IS
    SELECT player_id,
           SUM(hr)  AS total_hr,
           SUM(ab)  AS total_ab,
           SUM(rbi) AS total_rbi
      FROM BASEBALL.BATTING
     WHERE year = p_cursor_year
     GROUP BY player_id
     ORDER BY SUM(hr) DESC, player_id;

  lv_rows PLS_INTEGER := 0;
BEGIN
  IF p_year IS NULL THEN
    SELECT MAX(year)
      INTO lv_year
      FROM BASEBALL.BATTING;
  ELSE
    lv_year := p_year;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top HR batters for year ' || lv_year || ' (max ' || co_report_limit || ' rows):');
  DBMS_OUTPUT.PUT_LINE(RPAD('PLAYER_ID', 12) || ' ' || LPAD('HR', 6) || ' ' || LPAD('AB', 8) || ' ' || LPAD('RBI', 8));

  FOR rec IN c_top_batters(lv_year) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;

    DBMS_OUTPUT.PUT_LINE(RPAD(rec.player_id, 12) || ' ' || LPAD(rec.total_hr, 6) || ' ' || LPAD(rec.total_ab, 8) || ' ' || LPAD(rec.total_rbi, 8));
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No batting data found for year ' || lv_year || '.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_hr_batters;
/

CREATE OR REPLACE FUNCTION get_ab_per_hr(
  p_player_id IN BASEBALL.BATTING.player_id%TYPE,
  p_year      IN BASEBALL.BATTING.year%TYPE
) RETURN NUMBER
IS
  lv_total_ab BASEBALL.BATTING.ab%TYPE;
  lv_total_hr BASEBALL.BATTING.hr%TYPE;
  lv_ratio    NUMBER;

  CURSOR c_totals IS
    SELECT SUM(ab) AS total_ab,
           SUM(hr) AS total_hr
      FROM BASEBALL.BATTING
     WHERE player_id = p_player_id
       AND year = p_year;

  lv_row c_totals%ROWTYPE;
BEGIN
  OPEN c_totals;
  FETCH c_totals INTO lv_row;
  CLOSE c_totals;

  IF lv_row.total_ab IS NULL AND lv_row.total_hr IS NULL THEN
    RETURN NULL; -- No data for this player/year
  END IF;

  IF lv_row.total_hr = 0 THEN
    RETURN NULL; -- Special case: avoid divide-by-zero and treat as no ratio
  END IF;

  lv_total_ab := lv_row.total_ab;
  lv_total_hr := lv_row.total_hr;
  lv_ratio := lv_total_ab / lv_total_hr;

  DBMS_OUTPUT.PUT_LINE('AB/HR for player ' || p_player_id || ' in year ' || p_year || ' = ' || TO_CHAR(lv_ratio));

  RETURN lv_ratio;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN NULL;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN NULL;
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN NULL;
END get_ab_per_hr;
/

DECLARE
  lv_player BASEBALL.BATTING.player_id%TYPE;
  lv_year   BASEBALL.BATTING.year%TYPE;
  lv_ratio  NUMBER;
BEGIN
  SELECT player_id, year
    INTO lv_player, lv_year
    FROM (
      SELECT player_id, year
        FROM BASEBALL.BATTING
       GROUP BY player_id, year
       ORDER BY COUNT(*) DESC, year DESC, player_id
    )
   WHERE ROWNUM = 1;

  lv_ratio := get_ab_per_hr(lv_player, lv_year);
  DBMS_OUTPUT.PUT_LINE('AB/HR for player ' || lv_player || ' in year ' || lv_year || ' = ' || TO_CHAR(lv_ratio));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

