CREATE OR REPLACE PACKAGE hr_ops_pkg IS
  PROCEDURE print_top_hr_with_team_context(
    p_year IN BASEBALL.BATTING.year%TYPE
  );
END hr_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY hr_ops_pkg IS

  PROCEDURE print_top_hr_with_team_context(
    p_year IN BASEBALL.BATTING.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_year BASEBALL.BATTING.year%TYPE;

    /*
      Root cause fix:
      The buggy version joined/printed by TEAM_ID, which duplicated players.
      This cursor aggregates at PLAYER_ID level and counts distinct TEAM_ID.
    */
    CURSOR c_top_batters(p_cursor_year BASEBALL.BATTING.year%TYPE) IS
      SELECT player_id,
             SUM(hr) AS total_hr,
             SUM(ab) AS total_ab,
             SUM(rbi) AS total_rbi,
             COUNT(DISTINCT team_id) AS team_cnt
        FROM BASEBALL.BATTING
       WHERE year = p_cursor_year
       GROUP BY player_id
       ORDER BY SUM(hr) DESC, player_id;

    lv_rows PLS_INTEGER := 0;
  BEGIN
    IF p_year IS NULL THEN
      SELECT MAX(year)
        INTO lv_year
        FROM BASEBALL.BATTING;
    ELSE
      lv_year := p_year;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Top HR batters with team context for year ' || lv_year || ' (max ' || co_report_limit || ' rows):');
    DBMS_OUTPUT.PUT_LINE(RPAD('PLAYER_ID', 12) || ' ' || LPAD('HR', 6) || ' ' || LPAD('AB', 8) || ' ' || LPAD('RBI', 8) || ' ' || LPAD('TEAM_CNT', 9));

    FOR rec IN c_top_batters(lv_year) LOOP
      EXIT WHEN lv_rows >= co_report_limit;
      lv_rows := lv_rows + 1;

      DBMS_OUTPUT.PUT_LINE(RPAD(rec.player_id, 12) || ' ' || LPAD(rec.total_hr, 6) || ' ' || LPAD(rec.total_ab, 8) || ' ' || LPAD(rec.total_rbi, 8) || ' ' || LPAD(rec.team_cnt, 9));
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No batting data found for year ' || lv_year || '.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_hr_with_team_context;

END hr_ops_pkg;
/

