CREATE OR REPLACE PROCEDURE report_driver_year_results(
  p_year       IN F1.RACES.year%TYPE,
  p_driver_ref IN F1.DRIVERS.driver_ref%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_driver_name  VARCHAR2(600);
  lv_rows         NUMBER := 0;
  lv_total_points NUMBER := 0;
BEGIN
  IF p_year IS NULL OR p_driver_ref IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year and driver reference are required.');
  ELSE
    SELECT d.forename || ' ' || d.surname
      INTO lv_driver_name
      FROM F1.DRIVERS d
     WHERE d.driver_ref = p_driver_ref;

    DBMS_OUTPUT.PUT_LINE('Driver season report: ' || lv_driver_name || ' in ' || p_year);

    FOR rec IN (
      SELECT limited_results.race_round,
             limited_results.race_name,
             limited_results.position_order,
             limited_results.points
        FROM (
              SELECT r.round AS race_round,
                     r.name AS race_name,
                     res.position_order,
                     res.points
                FROM F1.RESULTS res
                INNER JOIN F1.RACES r
                  ON r.race_id = res.race_id
                INNER JOIN F1.DRIVERS d
                  ON d.driver_id = res.driver_id
               WHERE r.year = p_year
                 AND d.driver_ref = p_driver_ref
               ORDER BY r.round
             ) limited_results
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rows := lv_rows + 1;
      lv_total_points := lv_total_points + NVL(rec.points, 0);
      DBMS_OUTPUT.PUT_LINE('Round ' || rec.race_round || ' - ' || rec.race_name || ': P' || rec.position_order || ', points ' || NVL(rec.points, 0));
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No classified results found for this driver and year.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Displayed results: ' || lv_rows || ', displayed points: ' || lv_total_points);
    END IF;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_driver_year_results;
/

CREATE OR REPLACE FUNCTION f1_constructor_points(
  p_year            IN F1.RACES.year%TYPE,
  p_constructor_ref IN F1.CONSTRUCTORS.constructor_ref%TYPE
) RETURN NUMBER IS
  lv_points      NUMBER := 0;
  lv_result_rows NUMBER := 0;
BEGIN
  IF p_year IS NULL OR p_constructor_ref IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year and constructor reference are required.');
    RETURN 0;
  END IF;

  SELECT NVL(SUM(res.points), 0), COUNT(*)
    INTO lv_points, lv_result_rows
    FROM F1.RESULTS res
    INNER JOIN F1.RACES r
      ON r.race_id = res.race_id
    INNER JOIN F1.CONSTRUCTORS c
      ON c.constructor_id = res.constructor_id
   WHERE r.year = p_year
     AND c.constructor_ref = p_constructor_ref;

  IF lv_result_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No constructor results found.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Constructor points: ' || lv_points);
  END IF;

  RETURN lv_points;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 0;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 0;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 0;
END f1_constructor_points;
/

