CREATE OR REPLACE PACKAGE BODY f1_season_audit AS
  PROCEDURE report_constructor_year(
    p_year            IN F1.RACES.year%TYPE,
    p_constructor_ref IN F1.CONSTRUCTORS.constructor_ref%TYPE
  ) IS
    co_report_limit     CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_constructor_name F1.CONSTRUCTORS.name%TYPE;
    lv_total_points     NUMBER := 0;
    lv_rows             NUMBER := 0;
  BEGIN
    IF p_year IS NULL OR p_constructor_ref IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Year and constructor reference are required.');
    ELSE
      SELECT c.name
        INTO lv_constructor_name
        FROM F1.CONSTRUCTORS c
       WHERE c.constructor_ref = p_constructor_ref;

      lv_total_points := f1_constructor_points(p_year, p_constructor_ref);
      DBMS_OUTPUT.PUT_LINE('Constructor season audit: ' || lv_constructor_name || ' in ' || p_year);

      FOR rec IN (
        SELECT limited_results.race_round,
               limited_results.race_name,
               limited_results.points
          FROM (
                SELECT r.round AS race_round,
                       r.name AS race_name,
                       res.points
                  FROM F1.RESULTS res
                  INNER JOIN F1.RACES r
                    ON r.race_id = res.race_id
                  INNER JOIN F1.CONSTRUCTORS c
                    ON c.constructor_id = res.constructor_id
                 WHERE r.year = p_year
                   AND c.constructor_ref = p_constructor_ref
                 ORDER BY r.round
               ) limited_results
         WHERE ROWNUM <= co_report_limit
      ) LOOP
        lv_rows := lv_rows + 1;
        DBMS_OUTPUT.PUT_LINE('Round ' || rec.race_round || ' - ' || rec.race_name || ': points ' || NVL(rec.points, 0));
      END LOOP;

      IF lv_rows = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No constructor race rows found for this year.');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Displayed constructor rows: ' || lv_rows || ', function total points: ' || lv_total_points);
      END IF;

      IF lv_total_points = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Constructor has no points in this year.');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Constructor has points in this year.');
      END IF;
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_constructor_year;
END f1_season_audit;
/

