DECLARE
  co_report_limit     CONSTANT PLS_INTEGER := 15; -- Limit grouped search for deterministic controller behavior
  lv_year             F1.RACES.year%TYPE;
  lv_constructor_ref  F1.CONSTRUCTORS.constructor_ref%TYPE;
  lv_points           NUMBER := 0;
  lv_classification   VARCHAR2(30);
BEGIN
  SELECT ranked_source.year,
         ranked_source.constructor_ref
    INTO lv_year,
         lv_constructor_ref
    FROM (
          SELECT r.year,
                 c.constructor_ref,
                 SUM(NVL(res.points, 0)) AS total_points
            FROM F1.RESULTS res
            INNER JOIN F1.RACES r
              ON r.race_id = res.race_id
            INNER JOIN F1.CONSTRUCTORS c
              ON c.constructor_id = res.constructor_id
           GROUP BY r.year,
                    c.constructor_ref
           ORDER BY SUM(NVL(res.points, 0)) DESC,
                    r.year DESC,
                    c.constructor_ref
         ) ranked_source
   WHERE ROWNUM <= co_report_limit
     AND ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Selected constructor: ' || lv_constructor_ref || ' for ' || lv_year);
  f1_season_audit.report_constructor_year(lv_year, lv_constructor_ref);

  lv_points := f1_constructor_points(lv_year, lv_constructor_ref);
  lv_classification := CASE
                         WHEN lv_points >= 500 THEN 'Dominant'
                         WHEN lv_points >= 100 THEN 'Competitive'
                         ELSE 'Developing'
                       END;

  DBMS_OUTPUT.PUT_LINE('Final classification: ' || lv_classification);
