CREATE OR REPLACE PACKAGE wdi_report_pkg IS
  PROCEDURE run_country_indicator_report(
    p_country_code  IN WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE,
    p_topic_filter  IN WORLD_BANK_WDI.SERIES_SUMMARY.topic%TYPE
  );
END wdi_report_pkg;
/

CREATE OR REPLACE PACKAGE BODY wdi_report_pkg IS
  PROCEDURE run_country_indicator_report(
    p_country_code  IN WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE,
    p_topic_filter  IN WORLD_BANK_WDI.SERIES_SUMMARY.topic%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_country_name WORLD_BANK_WDI.COUNTRY_SUMMARY.short_name%TYPE;

    CURSOR c_series IS
      WITH series_with_counts AS (
        SELECT
          ss.series_code,
          ss.indicator_name,
          ss.unit_of_measure,
          (
            SELECT COUNT(DISTINCT d.year)
              FROM WORLD_BANK_WDI.INDICATORS_DATA d
             WHERE d.country_code = p_country_code
               AND d.indicator_code = ss.series_code
               AND d.value IS NOT NULL
          ) AS distinct_years
        FROM WORLD_BANK_WDI.SERIES_SUMMARY ss
        WHERE p_topic_filter IS NULL
           OR ss.topic = p_topic_filter
      )
      SELECT
        swc.series_code,
        swc.indicator_name,
        swc.unit_of_measure,
        swc.distinct_years
      FROM series_with_counts swc
      WHERE swc.distinct_years > 0
      ORDER BY swc.distinct_years DESC, swc.series_code;

    TYPE t_series_rec IS RECORD (
      series_code      WORLD_BANK_WDI.SERIES_SUMMARY.series_code%TYPE,
      indicator_name   WORLD_BANK_WDI.SERIES_SUMMARY.indicator_name%TYPE,
      unit_of_measure  WORLD_BANK_WDI.SERIES_SUMMARY.unit_of_measure%TYPE,
      distinct_years   NUMBER
    );

    rec t_series_rec;
    lv_rows PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Input country_code=' || NVL(p_country_code, 'NULL') || ', topic_filter=' || NVL(p_topic_filter, 'NULL'));

    SELECT cs.short_name
      INTO lv_country_name
      FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
     WHERE cs.country_code = p_country_code;

    DBMS_OUTPUT.PUT_LINE('Resolved country: ' || lv_country_name);

    OPEN c_series;
    LOOP
      FETCH c_series INTO rec;
      EXIT WHEN c_series%NOTFOUND;

      lv_rows := lv_rows + 1;
      EXIT WHEN lv_rows > co_report_limit;

      DBMS_OUTPUT.PUT_LINE('Series: ' || rec.series_code || ' | ' || rec.indicator_name);
      DBMS_OUTPUT.PUT_LINE('  Unit: ' || NVL(rec.unit_of_measure, 'N/A') || ' | Distinct years with values: ' || rec.distinct_years);
    END LOOP;
    CLOSE c_series;

    IF lv_rows = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF c_series%ISOPEN THEN
        CLOSE c_series;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No indicator data found for the given inputs.');
    WHEN OTHERS THEN
      IF c_series%ISOPEN THEN
        CLOSE c_series;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_country_indicator_report;
END wdi_report_pkg;
/

