  FUNCTION get_latest_year_text(
    p_country_code    IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
    p_indicator_code  IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
  ) RETURN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE IS
    lv_latest_year WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;
  BEGIN
    SELECT MAX(d.year)
      INTO lv_latest_year
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
     WHERE d.country_code = p_country_code
       AND d.indicator_code = p_indicator_code
       AND d.value IS NOT NULL;

    IF lv_latest_year IS NULL THEN
      RAISE NO_DATA_FOUND;
    END IF;

    RETURN lv_latest_year;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END get_latest_year_text;


  PROCEDURE report_missing_years(
    p_country_code    IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
    p_indicator_code  IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE,
    p_start_year      IN NUMBER,
    p_end_year        IN NUMBER
  ) IS
    lv_latest_year WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;

    CURSOR c_years IS
      SELECT (p_start_year + LEVEL - 1) AS yr
        FROM dual
     CONNECT BY LEVEL <= (p_end_year - p_start_year + 1)
     ORDER BY yr;

    TYPE t_year_rec IS RECORD (
      yr NUMBER
    );

    rec t_year_rec;
    lv_missing_count PLS_INTEGER := 0;
    lv_dummy NUMBER;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'Input country_code=' || NVL(p_country_code, 'NULL') ||
      ', indicator_code=' || NVL(p_indicator_code, 'NULL') ||
      ', start_year=' || NVL(TO_CHAR(p_start_year), 'NULL') ||
      ', end_year=' || NVL(TO_CHAR(p_end_year), 'NULL')
    );

    IF p_start_year IS NULL OR p_end_year IS NULL OR p_start_year > p_end_year THEN
      RAISE VALUE_ERROR;
    END IF;

    lv_latest_year := get_latest_year_text(p_country_code, p_indicator_code);
    IF lv_latest_year IS NULL THEN
      RAISE NO_DATA_FOUND;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Latest available year with a value: ' || lv_latest_year);

    OPEN c_years;
    LOOP
      FETCH c_years INTO rec;
      EXIT WHEN c_years%NOTFOUND;

      BEGIN
        SELECT 1
          INTO lv_dummy
          FROM WORLD_BANK_WDI.INDICATORS_DATA d
         WHERE d.country_code = p_country_code
           AND d.indicator_code = p_indicator_code
           AND d.year = TO_CHAR(rec.yr)
           AND d.value IS NOT NULL
           AND ROWNUM = 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_missing_count := lv_missing_count + 1;
          DBMS_OUTPUT.PUT_LINE('Missing year: ' || TO_CHAR(rec.yr));
      END;
    END LOOP;
    CLOSE c_years;

    IF lv_missing_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No missing years in the requested range.');
    END IF;

  EXCEPTION
    WHEN VALUE_ERROR THEN
      IF c_years%ISOPEN THEN
        CLOSE c_years;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Invalid year range.');
    WHEN NO_DATA_FOUND THEN
      IF c_years%ISOPEN THEN
        CLOSE c_years;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No indicator data found for the given inputs.');
    WHEN OTHERS THEN
      IF c_years%ISOPEN THEN
        CLOSE c_years;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_missing_years;

END wdi_report_pkg;
/

