DECLARE
  co_window_years CONSTANT PLS_INTEGER := 5; -- Keep the missing-years check short for readability

  lv_country_code   WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE;
  lv_topic          WORLD_BANK_WDI.SERIES_SUMMARY.topic%TYPE;
  lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE;
  lv_latest_year_tx WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;
  lv_end_year       NUMBER;
  lv_start_year     NUMBER;
BEGIN
  SELECT country_code
    INTO lv_country_code
    FROM (
      SELECT d.country_code
        FROM WORLD_BANK_WDI.INDICATORS_DATA d
       WHERE d.value IS NOT NULL
         AND d.country_code IS NOT NULL
       GROUP BY d.country_code
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  SELECT topic
    INTO lv_topic
    FROM (
      SELECT ss.topic
        FROM WORLD_BANK_WDI.SERIES_SUMMARY ss
       WHERE ss.topic IS NOT NULL
       GROUP BY ss.topic
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Picked inputs -> country_code=' || lv_country_code || ', topic=' || lv_topic);
  DBMS_OUTPUT.PUT_LINE('Calling run_country_indicator_report...');
  wdi_report_pkg.run_country_indicator_report(lv_country_code, lv_topic);

  SELECT indicator_code
    INTO lv_indicator_code
    FROM (
      SELECT d.indicator_code
        FROM WORLD_BANK_WDI.INDICATORS_DATA d
        JOIN WORLD_BANK_WDI.SERIES_SUMMARY ss
          ON ss.series_code = d.indicator_code
       WHERE d.country_code = lv_country_code
         AND d.value IS NOT NULL
         AND ss.topic = lv_topic
         AND d.indicator_code IS NOT NULL
       GROUP BY d.indicator_code
       ORDER BY COUNT(*) DESC
    )
   WHERE ROWNUM = 1;

  lv_latest_year_tx := wdi_report_pkg.get_latest_year_text(lv_country_code, lv_indicator_code);
  IF lv_latest_year_tx IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No indicator available for the chosen country/topic.');
    RETURN;
  END IF;

  lv_end_year := TO_NUMBER(lv_latest_year_tx);
  lv_start_year := lv_end_year - (co_window_years - 1);

  DBMS_OUTPUT.PUT_LINE(
    'Calling report_missing_years for indicator_code=' || lv_indicator_code ||
    ', window=' || TO_CHAR(lv_start_year) || '-' || TO_CHAR(lv_end_year)
  );

  wdi_report_pkg.report_missing_years(
    p_country_code   => lv_country_code,
    p_indicator_code => lv_indicator_code,
    p_start_year     => lv_start_year,
    p_end_year       => lv_end_year
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

