Parameters: p_channel_name IN DELIVERY_CENTER.CHANNELS.channel_name%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Channel name is required.');
DBMS_OUTPUT.PUT_LINE('Channel performance for: ' || p_channel_name);
