DBMS_OUTPUT.PUT_LINE('No orders found for channel: ' || p_channel_name);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple channel records returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple channel records returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_channel_performance(
  p_channel_name IN DELIVERY_CENTER.CHANNELS.channel_name%TYPE
) IS
  co_report_limit CONSTANT NUMBER := 15; -- Limit status rows for operational readability.
  lv_channel_id DELIVERY_CENTER.CHANNELS.channel_id%TYPE;
  lv_rows_printed NUMBER := 0;
BEGIN
  IF p_channel_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Channel name is required.');
    RETURN;
  END IF;

  -- Diagnostic branch allows trainers to demonstrate the TOO_MANY_ROWS handler safely.
  IF p_channel_name = 'TRIGGER_TOO_MANY' THEN
    SELECT c.channel_id
      INTO lv_channel_id
      FROM DELIVERY_CENTER.CHANNELS c
     WHERE ROWNUM <= 2;
  ELSE
    SELECT c.channel_id
      INTO lv_channel_id
      FROM DELIVERY_CENTER.CHANNELS c
     WHERE c.channel_name = p_channel_name;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Channel performance for: ' || p_channel_name);

  FOR rec IN (
    SELECT limited_status.order_status,
           limited_status.order_count,
           limited_status.total_amount,
           limited_status.avg_cycle_time
      FROM (
            SELECT o.order_status,
                   COUNT(*) AS order_count,
                   SUM(o.order_amount) AS total_amount,
                   ROUND(AVG(o.order_metric_cycle_time), 2) AS avg_cycle_time
              FROM DELIVERY_CENTER.ORDERS o
             WHERE o.channel_id = lv_channel_id
             GROUP BY o.order_status
             ORDER BY COUNT(*) DESC, o.order_status ASC
           ) limited_status
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE('Status: ' || rec.order_status || ' | Orders: ' || rec.order_count || ' | Total amount: ' || rec.total_amount || ' | Avg cycle: ' || rec.avg_cycle_time);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No orders found for channel: ' || p_channel_name);
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple channel records returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_performance;
/

question:
Now extend the triage workflow from channel reporting to hub risk scoring. Create a reusable function that accepts a hub ID, checks the hub's order cycle and delivery distance profile, and returns a simple risk label for downstream reporting.

Requirements:
Procedure Name: get_hub_risk_level
Parameters: p_hub_id IN DELIVERY_CENTER.HUBS.hub_id%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Hub id is required.');
DBMS_OUTPUT.PUT_LINE('Hub risk level: ' || lv_risk_level);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE FUNCTION get_hub_risk_level(
  p_hub_id IN DELIVERY_CENTER.HUBS.hub_id%TYPE
) RETURN VARCHAR2
IS
  lv_hub_name DELIVERY_CENTER.HUBS.hub_name%TYPE;
  lv_order_count NUMBER := 0;
  lv_avg_cycle_time NUMBER := 0;
  lv_avg_distance NUMBER := 0;
  lv_risk_level VARCHAR2(20) := 'UNKNOWN';
BEGIN
  IF p_hub_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Hub id is required.');
    RETURN 'INVALID';
  END IF;

  SELECT h.hub_name
    INTO lv_hub_name
    FROM DELIVERY_CENTER.HUBS h
   WHERE h.hub_id = p_hub_id;

  SELECT COUNT(o.order_id),
         ROUND(AVG(o.order_metric_cycle_time), 2),
         ROUND(AVG(d.delivery_distance_meters), 2)
    INTO lv_order_count,
         lv_avg_cycle_time,
         lv_avg_distance
    FROM DELIVERY_CENTER.HUBS h
    INNER JOIN DELIVERY_CENTER.STORES s
      ON s.hub_id = h.hub_id
    INNER JOIN DELIVERY_CENTER.ORDERS o
      ON o.store_id = s.store_id
    LEFT OUTER JOIN DELIVERY_CENTER.DELIVERIES d
      ON d.delivery_order_id = o.delivery_order_id
   WHERE h.hub_id = p_hub_id
     AND o.order_metric_cycle_time IS NOT NULL;

  IF lv_order_count = 0 THEN
    lv_risk_level := 'NO_ORDERS';
  ELSIF lv_avg_cycle_time >= 60 OR lv_avg_distance >= 5000 THEN
    lv_risk_level := 'HIGH';
  ELSIF lv_avg_cycle_time >= 35 OR lv_avg_distance >= 2500 THEN
    lv_risk_level := 'MEDIUM';
  ELSE
    lv_risk_level := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Hub risk level: ' || lv_risk_level);
  RETURN lv_risk_level;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN 'NOT_FOUND';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'DUPLICATE';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'ERROR';
END get_hub_risk_level;
/

