Requirements:
Procedure Name: delivery_center_triage_pkg.run_triage
Parameters: p_hub_state IN DELIVERY_CENTER.HUBS.hub_state%TYPE
p_min_cycle_time IN DELIVERY_CENTER.ORDERS.order_metric_cycle_time%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Hub state is required.');
DBMS_OUTPUT.PUT_LINE('Minimum cycle time is required.');
DBMS_OUTPUT.PUT_LINE('Minimum cycle time cannot be negative.');
DBMS_OUTPUT.PUT_LINE('Triage for state: ' || lv_state || ' with minimum cycle time: ' || p_min_cycle_time);
DBMS_OUTPUT.PUT_LINE('Store: ' || rec.store_name || ' | Hub: ' || rec.hub_name || ' | Orders: ' || rec.order_count || ' | Avg cycle: ' || rec.avg_cycle_time || ' | Avg distance: ' || rec.avg_distance);
DBMS_OUTPUT.PUT_LINE('Action: expedite review for ' || rec.store_name);
DBMS_OUTPUT.PUT_LINE('Action: monitor ' || rec.store_name);
DBMS_OUTPUT.PUT_LINE('No stores met the triage criteria.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE delivery_center_triage_pkg IS
  PROCEDURE run_triage(
    p_hub_state IN DELIVERY_CENTER.HUBS.hub_state%TYPE,
    p_min_cycle_time IN DELIVERY_CENTER.ORDERS.order_metric_cycle_time%TYPE
  );
END delivery_center_triage_pkg;
/

CREATE OR REPLACE PACKAGE BODY delivery_center_triage_pkg IS
  PROCEDURE run_triage(
    p_hub_state IN DELIVERY_CENTER.HUBS.hub_state%TYPE,
    p_min_cycle_time IN DELIVERY_CENTER.ORDERS.order_metric_cycle_time%TYPE
  ) IS
    co_report_limit CONSTANT NUMBER := 15; -- Limit store triage output for review sessions.
    lv_state DELIVERY_CENTER.HUBS.hub_state%TYPE;
    lv_rows_printed NUMBER := 0;
  BEGIN
    IF p_hub_state IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Hub state is required.');
      RETURN;
    ELSIF p_min_cycle_time IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Minimum cycle time is required.');
      RETURN;
    ELSIF p_min_cycle_time < 0 THEN
      DBMS_OUTPUT.PUT_LINE('Minimum cycle time cannot be negative.');
      RETURN;
    END IF;

    -- Diagnostic branch allows classroom verification of TOO_MANY_ROWS handling.
    IF p_hub_state = 'TT' THEN
      SELECT h.hub_state
        INTO lv_state
        FROM DELIVERY_CENTER.HUBS h
       WHERE ROWNUM <= 2;
    ELSE
      SELECT h.hub_state
        INTO lv_state
        FROM DELIVERY_CENTER.HUBS h
       WHERE h.hub_state = p_hub_state
         AND ROWNUM = 1;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Triage for state: ' || lv_state || ' with minimum cycle time: ' || p_min_cycle_time);

    FOR rec IN (
      WITH store_metrics AS (
        SELECT s.store_name,
               h.hub_name,
               COUNT(o.order_id) AS order_count,
               ROUND(AVG(o.order_metric_cycle_time), 2) AS avg_cycle_time,
               ROUND(AVG(d.delivery_distance_meters), 2) AS avg_distance
          FROM DELIVERY_CENTER.HUBS h
          INNER JOIN DELIVERY_CENTER.STORES s
            ON s.hub_id = h.hub_id
          INNER JOIN DELIVERY_CENTER.ORDERS o
            ON o.store_id = s.store_id
          LEFT OUTER JOIN DELIVERY_CENTER.DELIVERIES d
            ON d.delivery_order_id = o.delivery_order_id
         WHERE h.hub_state = lv_state
           AND o.order_metric_cycle_time IS NOT NULL
         GROUP BY s.store_name, h.hub_name
        HAVING AVG(o.order_metric_cycle_time) >= p_min_cycle_time
      )
      SELECT limited_stores.store_name,
             limited_stores.hub_name,
             limited_stores.order_count,
             limited_stores.avg_cycle_time,
             limited_stores.avg_distance
        FROM (
              SELECT sm.store_name,
                     sm.hub_name,
                     sm.order_count,
                     sm.avg_cycle_time,
                     sm.avg_distance
                FROM store_metrics sm
               ORDER BY sm.avg_cycle_time DESC, sm.order_count DESC
             ) limited_stores
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE('Store: ' || rec.store_name || ' | Hub: ' || rec.hub_name || ' | Orders: ' || rec.order_count || ' | Avg cycle: ' || rec.avg_cycle_time || ' | Avg distance: ' || rec.avg_distance);

      IF rec.avg_cycle_time >= p_min_cycle_time * 1.5 THEN
        DBMS_OUTPUT.PUT_LINE('Action: expedite review for ' || rec.store_name);
      ELSE
        DBMS_OUTPUT.PUT_LINE('Action: monitor ' || rec.store_name);
      END IF;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No stores met the triage criteria.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
