CREATE OR REPLACE PROCEDURE city_popularity_tag(
  p_state         IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE,
  p_provider_type IN VARCHAR2,
  p_city          IN VARCHAR2
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Not used for output here; kept as a standard safety constant

  lv_result VARCHAR2(20);
  lv_rank NUMBER;

  CURSOR cur_city_rank IS
    WITH city_counts AS (
      SELECT hp.city AS city,
             COUNT(*) AS provider_cnt
        FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
       WHERE hp.state = p_state
       GROUP BY hp.city
      UNION ALL
      SELECT hha.city AS city,
             COUNT(*) AS provider_cnt
        FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
       WHERE hha.state = p_state
       GROUP BY hha.city
    ),
    filtered AS (
      SELECT cc.city AS city,
             cc.provider_cnt AS provider_cnt
        FROM city_counts cc
       WHERE (p_provider_type = 'HOSPICE' AND EXISTS (
                SELECT 1
                  FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp2
                 WHERE hp2.state = p_state
                   AND hp2.city = cc.city
              ))
          OR (p_provider_type = 'HOME_HEALTH' AND EXISTS (
                SELECT 1
                  FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha2
                 WHERE hha2.state = p_state
                   AND hha2.city = cc.city
              ))
    ),
    ranked AS (
      SELECT f.city AS city,
             ROW_NUMBER() OVER (ORDER BY f.provider_cnt DESC, f.city ASC) AS city_rank
        FROM filtered f
    )
    SELECT r.city_rank
      FROM ranked r
     WHERE r.city = p_city;

BEGIN
  lv_result := 'NOT_FOUND';

  OPEN cur_city_rank;
  FETCH cur_city_rank INTO lv_rank;

  IF cur_city_rank%FOUND THEN
    IF lv_rank = 1 THEN
      lv_result := 'TOP_CITY';
    ELSE
      lv_result := 'OTHER_CITY';
    END IF;
  END IF;

  CLOSE cur_city_rank;

  DBMS_OUTPUT.PUT_LINE(
    'City popularity check: state=' || NVL(p_state, 'ALL') ||
    ' type=' || NVL(p_provider_type, 'UNKNOWN') ||
    ' city=' || NVL(p_city, 'UNKNOWN') ||
    ' => ' || lv_result
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_city_rank%ISOPEN THEN
      CLOSE cur_city_rank;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    IF cur_city_rank%ISOPEN THEN
      CLOSE cur_city_rank;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    IF cur_city_rank%ISOPEN THEN
      CLOSE cur_city_rank;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END city_popularity_tag;
/

