CREATE OR REPLACE PACKAGE provider_audit_pkg IS
  PROCEDURE run_state_audit(
    p_state       IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE,
    p_max_payment IN NUMBER
  );
END provider_audit_pkg;
/

CREATE OR REPLACE PACKAGE BODY provider_audit_pkg IS
  PROCEDURE run_state_audit(
    p_state       IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE,
    p_max_payment IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Standard safety limit for internal lookups

    lv_city CMS_MEDICARE.HOSPICE_PROVIDERS.city%TYPE;

    CURSOR cur_top_hospice_city IS
      SELECT hp.city
        FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
       WHERE hp.state = p_state
         AND hp.city IS NOT NULL
       GROUP BY hp.city
       ORDER BY COUNT(*) DESC, hp.city ASC
       FETCH FIRST 1 ROWS ONLY;

    CURSOR cur_state_exists IS
      SELECT 'Y'
        FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
       WHERE hha.state = p_state
         AND ROWNUM = 1;

    lv_dummy VARCHAR2(1);
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Provider audit start: state=' || NVL(p_state, 'ALL'));

    IF p_state IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN;
    END IF;

    -- Lightweight check that the state has at least one provider row somewhere
    OPEN cur_state_exists;
    FETCH cur_state_exists INTO lv_dummy;
    CLOSE cur_state_exists;

    report_top_providers_by_state(p_state);
    flag_high_payment_providers(p_state, p_max_payment);

    OPEN cur_top_hospice_city;
    FETCH cur_top_hospice_city INTO lv_city;

    IF cur_top_hospice_city%FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Provider audit hospice top city candidate: ' || lv_city);
      city_popularity_tag(p_state, 'HOSPICE', lv_city);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Provider audit hospice top city candidate: ' || lv_city);
      city_popularity_tag(p_state, 'HOSPICE', lv_city);
    END IF;

    CLOSE cur_top_hospice_city;

    DBMS_OUTPUT.PUT_LINE('Provider audit end.');

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF cur_top_hospice_city%ISOPEN THEN
        CLOSE cur_top_hospice_city;
      END IF;
      IF cur_state_exists%ISOPEN THEN
        CLOSE cur_state_exists;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      IF cur_top_hospice_city%ISOPEN THEN
        CLOSE cur_top_hospice_city;
      END IF;
      IF cur_state_exists%ISOPEN THEN
        CLOSE cur_state_exists;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      IF cur_top_hospice_city%ISOPEN THEN
        CLOSE cur_top_hospice_city;
      END IF;
      IF cur_state_exists%ISOPEN THEN
        CLOSE cur_state_exists;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
    WHEN OTHERS THEN
      IF cur_top_hospice_city%ISOPEN THEN
        CLOSE cur_top_hospice_city;
      END IF;
      IF cur_state_exists%ISOPEN THEN
        CLOSE cur_state_exists;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_state_audit;
END provider_audit_pkg;
/

