CREATE OR REPLACE PROCEDURE report_county_birth_trend(
  p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE_FIPS%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability.
  lv_county_name SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE;
BEGIN
  IF p_county_fips IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('County FIPS is required.');
    RETURN;
  END IF;

  SELECT cn.county_of_residence
    INTO lv_county_name
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.county_of_residence_fips = p_county_fips
   FETCH FIRST 1 ROW ONLY;

  DBMS_OUTPUT.PUT_LINE('County: ' || lv_county_name);

  FOR rec IN (
    SELECT cn.year AS birth_year,
           SUM(CASE
                 WHEN REGEXP_LIKE(cn.births, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cn.births)
                 ELSE 0
               END) AS birth_total
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence_fips = p_county_fips
     GROUP BY cn.year
     ORDER BY cn.year DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('Year ' || TO_CHAR(rec.birth_year, 'YYYY') || ': births=' || rec.birth_total);
  END LOOP;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No natality records found for the supplied county FIPS.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple county names found for the supplied county FIPS.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error while reporting county birth trend.');
END report_county_birth_trend;
/

CREATE OR REPLACE FUNCTION get_county_birth_total(
  p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE_FIPS%TYPE,
  p_birth_year   IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE
) RETURN NUMBER IS
  lv_total NUMBER := 0;
  lv_row_count NUMBER := 0;
BEGIN
  IF p_county_fips IS NULL OR p_birth_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('County FIPS and birth year are required.');
    RETURN 0;
  END IF;

  SELECT COUNT(*),
         NVL(SUM(CASE
                   WHEN REGEXP_LIKE(cn.births, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cn.births)
                   ELSE 0
                 END), 0)
    INTO lv_row_count, lv_total
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.county_of_residence_fips = p_county_fips
     AND cn.year = p_birth_year;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No birth rows found for county and year.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Total births for county/year: ' || lv_total);
  END IF;

  RETURN lv_total;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No natality records found for the supplied county and year.');
    RETURN 0;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple aggregate rows returned unexpectedly.');
    RETURN 0;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error while calculating county birth total.');
    RETURN 0;
END get_county_birth_total;
/

