CREATE OR REPLACE PROCEDURE report_prenatal_watchlist(
  p_birth_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE,
  p_min_births IN NUMBER DEFAULT 100
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability.
  lv_rows NUMBER := 0;
BEGIN
  IF p_birth_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Birth year is required.');
    RETURN;
  ELSIF p_min_births IS NULL OR p_min_births < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Minimum births must be zero or greater.');
    RETURN;
  ELSE
    DBMS_OUTPUT.PUT_LINE('Prenatal watchlist for year ' || TO_CHAR(p_birth_year, 'YYYY') || ' and minimum births ' || p_min_births);
  END IF;

  FOR rec IN (
    SELECT cn.county_of_residence,
           SUM(CASE
                 WHEN REGEXP_LIKE(cn.births, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cn.births)
                 ELSE 0
               END) AS birth_total,
           ROUND(AVG(CASE
                       WHEN REGEXP_LIKE(cn.ave_number_of_prenatal_wks, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cn.ave_number_of_prenatal_wks)
                       ELSE NULL
                     END), 1) AS avg_prenatal_weeks
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = p_birth_year
     GROUP BY cn.county_of_residence
    HAVING SUM(CASE
                 WHEN REGEXP_LIKE(cn.births, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cn.births)
                 ELSE 0
               END) >= p_min_births
     ORDER BY avg_prenatal_weeks ASC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(rec.county_of_residence || ': prenatal_weeks=' || rec.avg_prenatal_weeks || ', births=' || rec.birth_total);
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No counties met the prenatal watchlist criteria.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No prenatal records found for the supplied year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple prenatal summary rows returned unexpectedly.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error while reporting prenatal watchlist.');
END report_prenatal_watchlist;
/

CREATE OR REPLACE PACKAGE natality_dashboard_pkg IS
