CREATE OR REPLACE PACKAGE BODY natality_dashboard_pkg IS
  PROCEDURE report_county_payment_mix(
    p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.COUNTY_OF_RESIDENCE_FIPS%TYPE,
    p_birth_year  IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.YEAR%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability.
    lv_rows NUMBER := 0;
  BEGIN
    IF p_county_fips IS NULL OR p_birth_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('County FIPS and birth year are required for payment mix.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Payment mix for county FIPS ' || p_county_fips || ' in ' || TO_CHAR(p_birth_year, 'YYYY'));

    FOR rec IN (
      SELECT cp.source_of_payment,
             SUM(CASE
                   WHEN REGEXP_LIKE(cp.births, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cp.births)
                   ELSE 0
                 END) AS birth_total
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT cp
       WHERE cp.county_of_residence_fips = p_county_fips
         AND cp.year = p_birth_year
       GROUP BY cp.source_of_payment
       ORDER BY birth_total DESC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE(rec.source_of_payment || ': births=' || rec.birth_total);
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No payment mix rows found for county and year.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No payment records found for county and year.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple payment rows returned unexpectedly.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error while reporting payment mix.');
  END report_county_payment_mix;

  PROCEDURE report_county_quality_snapshot(
    p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE_FIPS%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability.
    lv_county_name SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE;
  BEGIN
    IF p_county_fips IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('County FIPS is required for quality snapshot.');
      RETURN;
    END IF;

    SELECT cn.county_of_residence
      INTO lv_county_name
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence_fips = p_county_fips
     FETCH FIRST 1 ROW ONLY;

    DBMS_OUTPUT.PUT_LINE('Quality snapshot for ' || lv_county_name);

    FOR rec IN (
      SELECT cn.year AS birth_year,
             SUM(CASE
                   WHEN REGEXP_LIKE(cn.births, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cn.births)
                   ELSE 0
                 END) AS birth_total,
             ROUND(AVG(CASE
                         WHEN REGEXP_LIKE(cn.ave_birth_weight_gms, '^[0-9]+([.][0-9]+)?$') THEN TO_NUMBER(cn.ave_birth_weight_gms)
                         ELSE NULL
                       END), 1) AS avg_birth_weight_gms
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.county_of_residence_fips = p_county_fips
       GROUP BY cn.year
       ORDER BY cn.year DESC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      DBMS_OUTPUT.PUT_LINE('Year ' || TO_CHAR(rec.birth_year, 'YYYY') || ': births=' || rec.birth_total || ', avg_birth_weight_gms=' || rec.avg_birth_weight_gms);
    END LOOP;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No quality snapshot records found for county.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple county rows returned unexpectedly.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error while reporting quality snapshot.');
  END report_county_quality_snapshot;
END natality_dashboard_pkg;
/

