CREATE OR REPLACE PROCEDURE report_payment_breakdown(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_county_name  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;
  lv_births_all   NUMBER := 0;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input guards
  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year is NULL.');
    RETURN;
  END IF;

  IF p_fips IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: county FIPS is NULL.');
    RETURN;
  END IF;

  -- Pull county name and overall births (aggregate in case multiple rows exist)
  SELECT
    MIN(n.county_of_residence),
    SUM(
      CASE
        WHEN REGEXP_LIKE(TRIM(n.births), '^[-]?[0-9]+$') THEN TO_NUMBER(TRIM(n.births))
        ELSE 0
      END
    )
  INTO lv_county_name, lv_births_all
  FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY n
  WHERE n.year = p_year
    AND n.county_of_residence_fips = p_fips;

  DBMS_OUTPUT.PUT_LINE('County: ' || lv_county_name || ' (FIPS=' || p_fips || '), year=' || TO_CHAR(p_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE('Overall births (all records): ' || TO_CHAR(lv_births_all));
  DBMS_OUTPUT.PUT_LINE('Payment breakdown (max rows = ' || co_report_limit || ')');
  DBMS_OUTPUT.PUT_LINE(RPAD('PAYMENT_SOURCE', 28) || ' ' || LPAD('BIRTHS', 12));

  FOR rec IN (
    SELECT
      p.source_of_payment,
      SUM(
        CASE
          WHEN REGEXP_LIKE(TRIM(p.births), '^[-]?[0-9]+$') THEN TO_NUMBER(TRIM(p.births))
          ELSE 0
        END
      ) AS births_pay
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT p
    WHERE p.year = p_year
      AND p.county_of_residence_fips = p_fips
    GROUP BY p.source_of_payment
    ORDER BY births_pay DESC, p.source_of_payment
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.source_of_payment, 28) || ' ' ||
      LPAD(TO_CHAR(rec.births_pay), 12)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No payment rows found for this county/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_payment_breakdown;
/

