DECLARE
  lv_low_stock_count     NUMBER := 0;
  lv_demand_product_count NUMBER := 0;
  lv_total_shortage      NUMBER := 0;
BEGIN
  WITH inventory_totals AS (
    SELECT i.product_id,
           SUM(i.qty) AS on_hand_qty
      FROM ORACLE_SQL.INVENTORY i
     GROUP BY i.product_id
  ),
  demand_totals AS (
    SELECT ol.product_id,
           SUM(ol.qty) AS ordered_qty
      FROM ORACLE_SQL.ORDERLINES ol
     GROUP BY ol.product_id
  )
  SELECT COUNT(CASE WHEN NVL(it.on_hand_qty, 0) < pm.qty_minimum THEN 1 END),
         COUNT(CASE WHEN NVL(dt.ordered_qty, 0) > 0 THEN 1 END),
         NVL(SUM(CASE
                   WHEN NVL(dt.ordered_qty, 0) > NVL(it.on_hand_qty, 0)
                   THEN NVL(dt.ordered_qty, 0) - NVL(it.on_hand_qty, 0)
                   ELSE 0
                 END), 0)
    INTO lv_low_stock_count,
         lv_demand_product_count,
         lv_total_shortage
    FROM ORACLE_SQL.PRODUCTS p
    LEFT OUTER JOIN ORACLE_SQL.PRODUCT_MINIMUMS pm
      ON pm.product_id = p.id
    LEFT OUTER JOIN inventory_totals it
      ON it.product_id = p.id
    LEFT OUTER JOIN demand_totals dt
      ON dt.product_id = p.id;

  DBMS_OUTPUT.PUT_LINE('Warehouse readiness dashboard');
  DBMS_OUTPUT.PUT_LINE('Products below minimum: ' || lv_low_stock_count);
  DBMS_OUTPUT.PUT_LINE('Products with open order demand: ' || lv_demand_product_count);
  DBMS_OUTPUT.PUT_LINE('Estimated total shortage units: ' || lv_total_shortage);

  IF lv_total_shortage > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Action: Review replenishment before creating the next picking list.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Action: Stock levels are ready for the next picking list.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

