CREATE OR REPLACE PROCEDURE report_region_station_snapshot(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_printed   PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Station snapshot for region: ' || p_region_name);

  SELECT r.region_id
    INTO lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE r.name = p_region_name;

  FOR rec IN (
    SELECT i.station_id,
           i.name,
           s.last_reported,
           s.num_bikes_available,
           s.num_docks_available,
           s.is_installed,
           s.is_renting,
           s.is_returning
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO i
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
        ON s.station_id = i.station_id
     WHERE i.region_id = lv_region_id
     ORDER BY TO_TIMESTAMP(s.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS') DESC, i.station_id
  ) LOOP
    EXIT WHEN lv_printed >= co_report_limit;
    lv_printed := lv_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'As of last_reported=' ||
      TO_CHAR(TO_TIMESTAMP(rec.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS'), 'YYYY-MM-DD HH24:MI:SS') ||
      ' | station=' || rec.station_id || ' | ' || rec.name ||
      ' | bikes=' || rec.num_bikes_available ||
      ' | docks=' || rec.num_docks_available ||
      ' | installed=' || rec.is_installed ||
      ' | renting=' || rec.is_renting ||
      ' | returning=' || rec.is_returning
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for region: ' || p_region_name);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Region not found: ' || p_region_name);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple regions matched: ' || p_region_name);
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_station_snapshot;
/

CREATE OR REPLACE FUNCTION is_station_operational(
  p_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE
) RETURN VARCHAR2 IS
  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;

  lv_is_installed SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_installed%TYPE;
  lv_is_renting   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_renting%TYPE;
  lv_is_returning SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.is_returning%TYPE;

  lv_operational  VARCHAR2(1) := 'N';
BEGIN
  SELECT i.name
    INTO lv_station_name
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO i
   WHERE i.station_id = p_station_id;

  SELECT s.is_installed,
         s.is_renting,
         s.is_returning
    INTO lv_is_installed,
         lv_is_renting,
         lv_is_returning
    FROM (
      SELECT s.is_installed,
             s.is_renting,
             s.is_returning,
             ROW_NUMBER() OVER (
               PARTITION BY s.station_id
               ORDER BY TO_TIMESTAMP(s.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS') DESC
             ) AS rn
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
       WHERE s.station_id = p_station_id
    ) s
   WHERE s.rn = 1;

  IF lv_is_installed = 'true'
     AND lv_is_renting = 'true'
     AND lv_is_returning = 'true'
  THEN
    lv_operational := 'Y';
  ELSE
    lv_operational := 'N';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Station ' || p_station_id || ' (' || lv_station_name || ') operational=' || lv_operational);
  RETURN lv_operational;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Unknown station_id: ' || p_station_id);
    RETURN 'N';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple latest-status rows for station_id: ' || p_station_id);
    RETURN 'N';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'N';
END is_station_operational;
/

