CREATE OR REPLACE PROCEDURE report_risk_trips(
  p_start_ts IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
  p_end_ts   IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed  PLS_INTEGER := 0;
  lv_start_ok VARCHAR2(1);
  lv_end_ok   VARCHAR2(1);
BEGIN
  IF p_start_ts IS NOT NULL
     AND p_end_ts IS NOT NULL
     AND p_start_ts > p_end_ts
  THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date range. Start is after end.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Risk trips from ' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
    ' to ' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI:SS')
  );

  FOR t IN (
    WITH latest_status AS (
      SELECT s.station_id,
             s.is_installed,
             s.is_renting,
             s.is_returning,
             ROW_NUMBER() OVER (
               PARTITION BY s.station_id
               ORDER BY TO_TIMESTAMP(s.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS') DESC
             ) AS rn
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
    )
    SELECT tr.trip_id,
           tr.start_date,
           tr.end_date,
           tr.start_station_id,
           tr.end_station_id,
           CASE
             WHEN ss.is_installed = 'true' AND ss.is_renting = 'true' AND ss.is_returning = 'true' THEN 'Y'
             ELSE 'N'
           END AS start_ok,
           CASE
             WHEN es.is_installed = 'true' AND es.is_renting = 'true' AND es.is_returning = 'true' THEN 'Y'
             ELSE 'N'
           END AS end_ok
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS tr
      LEFT OUTER JOIN latest_status ss
        ON ss.station_id = tr.start_station_id
       AND ss.rn = 1
      LEFT OUTER JOIN latest_status es
        ON es.station_id = tr.end_station_id
       AND es.rn = 1
     WHERE (p_start_ts IS NULL OR tr.start_date >= p_start_ts)
       AND (p_end_ts IS NULL OR tr.end_date <= p_end_ts)
       AND (
         (CASE WHEN ss.is_installed = 'true' AND ss.is_renting = 'true' AND ss.is_returning = 'true' THEN 'Y' ELSE 'N' END) = 'N'
         OR
         (CASE WHEN es.is_installed = 'true' AND es.is_renting = 'true' AND es.is_returning = 'true' THEN 'Y' ELSE 'N' END) = 'N'
       )
     ORDER BY tr.start_date DESC, tr.trip_id
  ) LOOP
    EXIT WHEN lv_printed >= co_report_limit;
    lv_printed := lv_printed + 1;

    lv_start_ok := t.start_ok;
    lv_end_ok := t.end_ok;

    DBMS_OUTPUT.PUT_LINE(
      'trip_id=' || t.trip_id ||
      ' | start=' || TO_CHAR(t.start_date, 'YYYY-MM-DD HH24:MI:SS') ||
