CREATE OR REPLACE PROCEDURE report_region_health(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
  p_start_ts    IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
  p_end_ts      IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE
) IS
  co_station_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_printed   PLS_INTEGER := 0;

  lv_started NUMBER := 0;
  lv_ended   NUMBER := 0;
  lv_flag    VARCHAR2(10) := 'OK';
BEGIN
  IF p_start_ts IS NOT NULL
     AND p_end_ts IS NOT NULL
     AND p_start_ts > p_end_ts
  THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date range. Start is after end.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Region health report for: ' || p_region_name);

  SELECT r.region_id
    INTO lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE r.name = p_region_name;

  DBMS_OUTPUT.PUT_LINE('Station snapshot (most recent first), max rows = ' || co_station_limit);

  FOR rec IN (
    SELECT i.station_id,
           i.name,
           s.last_reported,
           s.num_bikes_available,
           s.num_docks_available
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO i
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
        ON s.station_id = i.station_id
     WHERE i.region_id = lv_region_id
     ORDER BY TO_TIMESTAMP(s.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS') DESC, i.station_id
  ) LOOP
    EXIT WHEN lv_printed >= co_station_limit;
    lv_printed := lv_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'As of last_reported=' ||
      TO_CHAR(TO_TIMESTAMP(rec.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS'), 'YYYY-MM-DD HH24:MI:SS') ||
      ' | station=' || rec.station_id || ' | ' || rec.name ||
      ' | bikes=' || rec.num_bikes_available ||
      ' | docks=' || rec.num_docks_available
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for region: ' || p_region_name);
  END IF;

  SELECT COUNT(*)
    INTO lv_started
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS tr
    INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      ON si.station_id = tr.start_station_id
   WHERE si.region_id = lv_region_id
     AND (p_start_ts IS NULL OR tr.start_date >= p_start_ts)
     AND (p_end_ts IS NULL OR tr.start_date <= p_end_ts);

  SELECT COUNT(*)
    INTO lv_ended
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS tr
    INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      ON si.station_id = tr.end_station_id
   WHERE si.region_id = lv_region_id
     AND (p_start_ts IS NULL OR tr.end_date >= p_start_ts)
     AND (p_end_ts IS NULL OR tr.end_date <= p_end_ts);

  IF lv_ended = 0 THEN
    IF lv_started > 0 THEN
      lv_flag := 'ALERT';
    ELSE
      lv_flag := 'OK';
    END IF;
  ELSE
    IF lv_started > (lv_ended * 1.10) THEN
      lv_flag := 'ALERT';
    ELSE
      lv_flag := 'OK';
    END IF;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Trip summary from ' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
    ' to ' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI:SS') ||
    ' | started_in_region=' || lv_started ||
    ' | ended_in_region=' || lv_ended ||
    ' | flag=' || lv_flag
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Region not found: ' || p_region_name);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple regions matched: ' || p_region_name);
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_health;
/

