    END IF;

    FOR r IN (
      SELECT h.gender_us,
             h.race_asian,
             h.race_black,
             h.race_hispanic_latinx,
             h.race_native_american,
             h.race_white,
             e.race_asian AS exits_race_asian,
             e.race_black AS exits_race_black,
             e.race_hispanic_latinx AS exits_race_hispanic_latinx,
             e.race_native_american AS exits_race_native_american,
