CREATE OR REPLACE PACKAGE BODY dei_hiring_pkg IS
  PROCEDURE print_hiring_snapshot(
    p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.workforce%TYPE,
    p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    v_workforce GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.workforce%TYPE;
    v_year      GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE;
  BEGIN
    IF p_workforce IS NULL THEN
      SELECT workforce
        INTO v_workforce
        FROM (
          SELECT workforce
            FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
           GROUP BY workforce
           ORDER BY COUNT(*) DESC, workforce
        )
       WHERE ROWNUM = 1;
    ELSE
      v_workforce := p_workforce;
    END IF;

    IF p_report_year IS NULL THEN
      SELECT report_year
        INTO v_year
        FROM (
          SELECT report_year
            FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
           GROUP BY report_year
           ORDER BY COUNT(*) DESC, report_year
        )
       WHERE ROWNUM = 1;
    ELSE
      v_year := p_report_year;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Hiring snapshot (max rows=' || co_report_limit || ')');
    DBMS_OUTPUT.PUT_LINE('WORKFORCE=' || v_workforce || ', YEAR=' || v_year);

    FOR rec IN (
      SELECT gender_us,
             race_asian,
             race_black,
             race_hispanic_latinx,
             race_native_american,
             race_white
        FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
       WHERE workforce = v_workforce
         AND report_year = v_year
         AND ROWNUM <= co_report_limit
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'GENDER_US=' || rec.gender_us ||
        ', ASIAN=' || rec.race_asian ||
        ', BLACK=' || rec.race_black ||
        ', HISPANIC_LATINX=' || rec.race_hispanic_latinx ||
        ', NATIVE_AMERICAN=' || rec.race_native_american ||
        ', WHITE=' || rec.race_white
      );
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_hiring_snapshot;

  FUNCTION classify_hiring_presence(
    p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.workforce%TYPE,
    p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE
  ) RETURN VARCHAR2 IS
    v_cnt NUMBER;
  BEGIN
    SELECT COUNT(*)
      INTO v_cnt
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
     WHERE workforce = p_workforce
       AND report_year = p_report_year;

    IF v_cnt > 0 THEN
      RETURN 'HAS_HIRING_ROWS';
    ELSE
      RETURN 'NO_HIRING_ROWS';
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 'NO_HIRING_ROWS';
    WHEN TOO_MANY_ROWS THEN
      RETURN 'HAS_HIRING_ROWS';
    WHEN OTHERS THEN
      RETURN 'NO_HIRING_ROWS';
  END classify_hiring_presence;

  PROCEDURE print_hiring_presence(
    p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.workforce%TYPE,
    p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE
  ) IS
    v_workforce GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.workforce%TYPE;
    v_year      GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE;
    v_status    VARCHAR2(30);
  BEGIN
    IF p_workforce IS NULL THEN
      SELECT workforce
        INTO v_workforce
        FROM (
          SELECT workforce
            FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
           GROUP BY workforce
           ORDER BY COUNT(*) DESC, workforce
        )
       WHERE ROWNUM = 1;
    ELSE
      v_workforce := p_workforce;
    END IF;

    IF p_report_year IS NULL THEN
      SELECT report_year
        INTO v_year
        FROM (
          SELECT report_year
            FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
           GROUP BY report_year
           ORDER BY COUNT(*) DESC, report_year
        )
       WHERE ROWNUM = 1;
    ELSE
      v_year := p_report_year;
    END IF;

    v_status := classify_hiring_presence(v_workforce, v_year);

    DBMS_OUTPUT.PUT_LINE('Presence check: WORKFORCE=' || v_workforce || ', YEAR=' || v_year || ', STATUS=' || v_status);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_hiring_presence;

  PROCEDURE print_hiring_vs_exits(
    p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.workforce%TYPE,
    p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    v_workforce GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.workforce%TYPE;
    v_year      GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE;
    v_presence  VARCHAR2(30);
  BEGIN
    v_workforce := p_workforce;
    v_year := p_report_year;

    IF v_workforce IS NULL OR v_year IS NULL THEN
      IF v_workforce IS NULL THEN
        SELECT workforce
          INTO v_workforce
          FROM (
            SELECT workforce
              FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
             GROUP BY workforce
             ORDER BY COUNT(*) DESC, workforce
          )
         WHERE ROWNUM = 1;
      END IF;

      IF v_year IS NULL THEN
        SELECT report_year
          INTO v_year
          FROM (
            SELECT report_year
              FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING
             GROUP BY report_year
             ORDER BY COUNT(*) DESC, report_year
          )
         WHERE ROWNUM = 1;
      END IF;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Hiring vs Exits comparison (max rows=' || co_report_limit || ')');

    v_presence := classify_hiring_presence(v_workforce, v_year);
    IF v_presence = 'NO_HIRING_ROWS' THEN
      DBMS_OUTPUT.PUT_LINE('No hiring rows found for this workforce/year; comparison skipped.');
      RETURN;
    END IF;

    FOR r IN (
      SELECT h.gender_us,
             h.race_asian,
             h.race_black,
             h.race_hispanic_latinx,
             h.race_native_american,
             h.race_white,
             e.race_asian AS exits_race_asian,
             e.race_black AS exits_race_black,
             e.race_hispanic_latinx AS exits_race_hispanic_latinx,
             e.race_native_american AS exits_race_native_american,
             e.race_white AS exits_race_white
        FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING h
        LEFT OUTER JOIN GOOGLE_DEI.DAR_INTERSECTIONAL_EXITS_REPRESENTATION e
          ON e.workforce = h.workforce
         AND e.report_year = h.report_year
         AND e.gender_us = h.gender_us
       WHERE h.workforce = v_workforce
         AND h.report_year = v_year
         AND ROWNUM <= co_report_limit
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'GENDER_US=' || r.gender_us ||
        ' | H_ASIAN=' || r.race_asian || ', E_ASIAN=' || r.exits_race_asian ||
        ' | H_BLACK=' || r.race_black || ', E_BLACK=' || r.exits_race_black ||
        ' | H_HISPANIC=' || r.race_hispanic_latinx || ', E_HISPANIC=' || r.exits_race_hispanic_latinx ||
        ' | H_NATIVE_AMERICAN=' || r.race_native_american || ', E_NATIVE_AMERICAN=' || r.exits_race_native_american ||
        ' | H_WHITE=' || r.race_white || ', E_WHITE=' || r.exits_race_white
      );
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_hiring_vs_exits;

  PROCEDURE print_representation_trend(
    p_workforce      IN GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
    p_only_complete  IN VARCHAR2
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    v_workforce     GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION.workforce%TYPE;
    v_only_complete VARCHAR2(1);
  BEGIN
    -- Default workforce to most common if NULL
    IF p_workforce IS NULL THEN
      SELECT workforce
        INTO v_workforce
        FROM (
          SELECT workforce
            FROM GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION
           GROUP BY workforce
           ORDER BY COUNT(*) DESC, workforce
        )
       WHERE ROWNUM = 1;
    ELSE
      v_workforce := p_workforce;
    END IF;

    v_only_complete := UPPER(NVL(p_only_complete, 'N'));

    DBMS_OUTPUT.PUT_LINE('Representation trend (max rows=' || co_report_limit || ')');
    DBMS_OUTPUT.PUT_LINE('WORKFORCE=' || v_workforce || ', ONLY_COMPLETE=' || v_only_complete);

    FOR r IN (
      SELECT report_year,
             gender_global_women,
             gender_global_men
        FROM GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION
       WHERE workforce = v_workforce
         AND (v_only_complete <> 'Y'
              OR (gender_global_women IS NOT NULL AND gender_global_men IS NOT NULL))
       ORDER BY report_year DESC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      DBMS_OUTPUT.PUT_LINE(
        'YEAR=' || r.report_year ||
        ', GLOBAL_WOMEN=' || r.gender_global_women ||
        ', GLOBAL_MEN=' || r.gender_global_men
      );
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_representation_trend;
END dei_hiring_pkg;
/

