CREATE OR REPLACE PACKAGE BODY natality_reporting IS
  PROCEDURE report_county_births(
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed  PLS_INTEGER := 0;
  BEGIN
    -- Guardrails for input
    IF p_county_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('County name is required.');
      RETURN;
    END IF;

    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Year is required.');
      RETURN;
    END IF;

    FOR rec IN (
      SELECT cn.county_of_residence,
             cn.county_of_residence_fips,
             cn.year,
             cn.births,
             cn.ave_age_of_mother,
             cn.ave_oe_gestational_age_wks,
             cn.ave_lmp_gestational_age_wks,
             cn.ave_birth_weight_gms,
             cn.ave_pre_pregnancy_bmi,
             cn.ave_number_of_prenatal_wks
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.county_of_residence = p_county_name
         AND cn.year = p_year
         AND ROWNUM <= co_report_limit
       ORDER BY cn.county_of_residence, cn.county_of_residence_fips
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE(
        'County: ' || rec.county_of_residence ||
        ' | FIPS: ' || rec.county_of_residence_fips ||
        ' | Year: ' || TO_CHAR(rec.year, 'YYYY') ||
        ' | Births: ' || rec.births
      );
      DBMS_OUTPUT.PUT_LINE(
        'Avg age mother: ' || rec.ave_age_of_mother ||
        ' | Avg OE gest weeks: ' || rec.ave_oe_gestational_age_wks ||
        ' | Avg LMP gest weeks: ' || rec.ave_lmp_gestational_age_wks
      );
      DBMS_OUTPUT.PUT_LINE(
        'Avg birth weight gms: ' || rec.ave_birth_weight_gms ||
        ' | Avg pre-preg BMI: ' || rec.ave_pre_pregnancy_bmi ||
        ' | Avg prenatal weeks: ' || rec.ave_number_of_prenatal_wks
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      -- Normalize empty result set to the same message used for NO_DATA_FOUND
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_county_births;
END natality_reporting;
/

