CREATE OR REPLACE PACKAGE natality_metrics IS
  FUNCTION get_births_delta(
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
    p_start_year  IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_end_year    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
  ) RETURN NUMBER;
END natality_metrics;
/
CREATE OR REPLACE PACKAGE BODY natality_metrics IS
  FUNCTION get_births_delta(
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
    p_start_year  IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_end_year    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
  ) RETURN NUMBER IS
    lv_births_start_txt SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.births%TYPE;
    lv_births_end_txt   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.births%TYPE;
    lv_births_start_num NUMBER;
    lv_births_end_num   NUMBER;
  BEGIN
    -- Input validation
    IF p_county_name IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('County name is required.');
      RETURN NULL;
    END IF;

    IF p_start_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Start year is required.');
      RETURN NULL;
    END IF;

    IF p_end_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('End year is required.');
      RETURN NULL;
    END IF;

    IF p_end_year < p_start_year THEN
      DBMS_OUTPUT.PUT_LINE('End year must be greater than or equal to start year.');
      RETURN NULL;
    END IF;

    -- Get start year births
    SELECT cn.births
      INTO lv_births_start_txt
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence = p_county_name
       AND cn.year = p_start_year
       AND ROWNUM = 1;

    -- Get end year births
    SELECT cn.births
      INTO lv_births_end_txt
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence = p_county_name
       AND cn.year = p_end_year
       AND ROWNUM = 1;

    -- Convert text to number (may raise INVALID_NUMBER)
    lv_births_start_num := TO_NUMBER(lv_births_start_txt);
    lv_births_end_num   := TO_NUMBER(lv_births_end_txt);

    RETURN (lv_births_end_num - lv_births_start_num);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN NULL;
    WHEN INVALID_NUMBER THEN
      DBMS_OUTPUT.PUT_LINE('Births value is not numeric.');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN NULL;
  END get_births_delta;
END natality_metrics;
/

