DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Kept for consistent output expectations

  lv_county   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;
  lv_min_year SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;
  lv_max_year SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;
  lv_delta    NUMBER;
BEGIN
  -- Pick the most common county in the dataset
  SELECT t.county_of_residence
    INTO lv_county
    FROM (
      SELECT cn.county_of_residence, COUNT(*) cnt
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.county_of_residence IS NOT NULL
       GROUP BY cn.county_of_residence
       ORDER BY COUNT(*) DESC
    ) t
   WHERE ROWNUM = 1;

  -- Get year range for that county
  SELECT MIN(cn.year), MAX(cn.year)
    INTO lv_min_year, lv_max_year
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.county_of_residence = lv_county;

  DBMS_OUTPUT.PUT_LINE('Selected county: ' || lv_county);
  DBMS_OUTPUT.PUT_LINE(
    'Year range: ' || TO_CHAR(lv_min_year, 'YYYY') || ' to ' || TO_CHAR(lv_max_year, 'YYYY')
  );

  -- Reuse the packaged report for the most recent year
  natality_reporting.report_county_births(lv_county, lv_max_year);

  -- Reuse the delta function across the full available range
  lv_delta := natality_metrics.get_births_delta(lv_county, lv_min_year, lv_max_year);
  DBMS_OUTPUT.PUT_LINE('Births delta: ' || TO_CHAR(lv_delta));

  -- The constant is referenced to avoid unused warnings in strict environments
  IF co_report_limit < 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

