reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_state CMS_MEDICARE.HOSPITAL_GENERAL_INFO.state%TYPE := 'CA';
  lv_rows  PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Hospitals in state = ' || lv_state || ' missing inpatient charge rows (max rows = ' || co_report_limit || ')');

  FOR r IN (
    SELECT h.provider_id,
           h.hospital_name
      FROM CMS_MEDICARE.HOSPITAL_GENERAL_INFO h
