question:
Extend the data-quality checks by validating a single hospital provider id. For the given provider id, print the hospital name/state and then print a status line saying whether inpatient charge rows exist for it. If the provider id isn't found in the hospital table, handle that cleanly.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Validation for provider_id = ' || lv_provider_id); 
DBMS_OUTPUT.PUT_LINE('Hospital: ' || lv_hospital_name || ' (state=' || lv_state || ')');
DBMS_OUTPUT.PUT_LINE('Inpatient charges exist for provider_id = ' || lv_provider_id || '.');
DBMS_OUTPUT.PUT_LINE('No inpatient charges found for provider_id = ' || lv_provider_id || '.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_provider_id   CMS_MEDICARE.HOSPITAL_GENERAL_INFO.provider_id%TYPE;
  lv_hospital_name CMS_MEDICARE.HOSPITAL_GENERAL_INFO.hospital_name%TYPE;
  lv_state         CMS_MEDICARE.HOSPITAL_GENERAL_INFO.state%TYPE;
  lv_charge_rows   NUMBER;
BEGIN
  -- Choose a real provider_id deterministically (smallest)
  SELECT MIN(h.provider_id)
    INTO lv_provider_id
    FROM CMS_MEDICARE.HOSPITAL_GENERAL_INFO h;

  DBMS_OUTPUT.PUT_LINE('Validation for provider_id = ' || lv_provider_id);

  SELECT h.hospital_name,
         h.state
    INTO lv_hospital_name,
         lv_state
    FROM CMS_MEDICARE.HOSPITAL_GENERAL_INFO h
   WHERE h.provider_id = lv_provider_id;

  DBMS_OUTPUT.PUT_LINE('Hospital: ' || lv_hospital_name || ' (state=' || lv_state || ')');

  SELECT COUNT(*)
    INTO lv_charge_rows
    FROM CMS_MEDICARE.INPATIENT_CHARGES i
   WHERE i.provider_id = lv_provider_id;

  IF lv_charge_rows > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Inpatient charges exist for provider_id = ' || lv_provider_id || '.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('No inpatient charges found for provider_id = ' || lv_provider_id || '.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

