Parameters: p_match_id IN IPL.MATCH.MATCH_ID%TYPE
p_mode IN VARCHAR2 DEFAULT 'NORMAL'
Output: DBMS_OUTPUT.PUT_LINE('Match id is required.');
DBMS_OUTPUT.PUT_LINE('Match ' || p_match_id || ' run band: ' || lv_band);
DBMS_OUTPUT.PUT_LINE('No match found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No match found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE FUNCTION get_match_run_band(
  p_match_id IN IPL.MATCH.MATCH_ID%TYPE,
  p_mode     IN VARCHAR2 DEFAULT 'NORMAL'
) RETURN VARCHAR2 IS
  lv_match_id   IPL.MATCH.MATCH_ID%TYPE;
  lv_dummy_id   IPL.TEAM.TEAM_ID%TYPE;
  lv_short_text VARCHAR2(1);
  lv_total_runs NUMBER := 0;
  lv_ball_count NUMBER := 0;
  lv_band       VARCHAR2(20);
BEGIN
  IF p_match_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Match id is required.');
    RETURN 'MATCH_ID_REQUIRED';
  END IF;

  IF UPPER(p_mode) = 'MANY' THEN
    SELECT t.team_id
      INTO lv_dummy_id
      FROM IPL.TEAM t
     WHERE ROWNUM <= 2;
  ELSIF UPPER(p_mode) = 'BAD' THEN
    lv_short_text := 'TOO_LONG';
  END IF;

  SELECT m.match_id
    INTO lv_match_id
    FROM IPL.MATCH m
   WHERE m.match_id = p_match_id;

  SELECT NVL(SUM(NVL(bs.runs_scored, 0) + NVL(er.extra_runs, 0)), 0),
         COUNT(b.ball_id)
    INTO lv_total_runs,
         lv_ball_count
    FROM IPL.MATCH m
    LEFT OUTER JOIN IPL.BALL_BY_BALL b
      ON b.match_id = m.match_id
    LEFT OUTER JOIN IPL.BATSMAN_SCORED bs
      ON bs.match_id = b.match_id
     AND bs.over_id = b.over_id
     AND bs.ball_id = b.ball_id
     AND bs.innings_no = b.innings_no
    LEFT OUTER JOIN IPL.EXTRA_RUNS er
      ON er.match_id = b.match_id
     AND er.over_id = b.over_id
     AND er.ball_id = b.ball_id
     AND er.innings_no = b.innings_no
   WHERE m.match_id = p_match_id;

  IF lv_total_runs >= 200 THEN
    lv_band := 'HIGH';
  ELSIF lv_total_runs >= 120 THEN
    lv_band := 'MEDIUM';
  ELSE
    lv_band := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Match ' || p_match_id || ' run band: ' || lv_band);
  RETURN lv_band;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No match found.');
    RETURN 'NO_DATA_FOUND';
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN 'TOO_MANY_ROWS';
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN 'UNEXPECTED_ERROR';
END get_match_run_band;
/

