question:
Finish the score-review workflow by packaging a match review that brings the earlier ideas together. For a selected match, compare total runs to a configurable threshold and list the leading run scorers so analysts can quickly validate whether the match deserves deeper review.

Requirements:
Procedure Name: IPL_SCORE_REVIEW.REVIEW_MATCH
Parameters: p_match_id IN IPL.MATCH.MATCH_ID%TYPE
p_min_runs IN NUMBER DEFAULT 150
p_mode IN VARCHAR2 DEFAULT 'NORMAL'
Output: DBMS_OUTPUT.PUT_LINE('Match id is required.');
DBMS_OUTPUT.PUT_LINE('Match review for ' || lv_team_1_name || ' vs ' || lv_team_2_name);
DBMS_OUTPUT.PUT_LINE('Total runs: ' || lv_total_runs || ' compared with threshold ' || lv_threshold);
DBMS_OUTPUT.PUT_LINE('Review result: HIGH SCORING');
DBMS_OUTPUT.PUT_LINE('Review result: NORMAL SCORING');
DBMS_OUTPUT.PUT_LINE('Top scorer: ' || rec.player_name || ' - ' || rec.runs_scored || ' runs');
DBMS_OUTPUT.PUT_LINE('No batting score rows found for this match.');
DBMS_OUTPUT.PUT_LINE('No match found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No match found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE ipl_score_review AS
  PROCEDURE review_match(
    p_match_id IN IPL.MATCH.MATCH_ID%TYPE,
    p_min_runs IN NUMBER DEFAULT 150,
    p_mode     IN VARCHAR2 DEFAULT 'NORMAL'
  );
END ipl_score_review;
/
CREATE OR REPLACE PACKAGE BODY ipl_score_review AS
  PROCEDURE review_match(
    p_match_id IN IPL.MATCH.MATCH_ID%TYPE,
    p_min_runs IN NUMBER DEFAULT 150,
    p_mode     IN VARCHAR2 DEFAULT 'NORMAL'
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    co_default_threshold CONSTANT NUMBER := 150;
    lv_team_1_name IPL.TEAM.NAME%TYPE;
    lv_team_2_name IPL.TEAM.NAME%TYPE;
    lv_dummy_id    IPL.TEAM.TEAM_ID%TYPE;
    lv_short_text  VARCHAR2(1);
    lv_total_runs  NUMBER := 0;
    lv_threshold   NUMBER := co_default_threshold;
    lv_rows        NUMBER := 0;
  BEGIN
    IF p_match_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Match id is required.');
      RETURN;
    END IF;

    IF p_min_runs IS NOT NULL THEN
      lv_threshold := p_min_runs;
    END IF;

    IF UPPER(p_mode) = 'MANY' THEN
      SELECT t.team_id
        INTO lv_dummy_id
        FROM IPL.TEAM t
       WHERE ROWNUM <= 2;
    ELSIF UPPER(p_mode) = 'BAD' THEN
      lv_short_text := 'TOO_LONG';
    END IF;

    SELECT t1.name,
           t2.name
      INTO lv_team_1_name,
           lv_team_2_name
      FROM IPL.MATCH m
      INNER JOIN IPL.TEAM t1
        ON t1.team_id = m.team_1
      INNER JOIN IPL.TEAM t2
        ON t2.team_id = m.team_2
     WHERE m.match_id = p_match_id;

    SELECT NVL(SUM(NVL(bs.runs_scored, 0) + NVL(er.extra_runs, 0)), 0)
      INTO lv_total_runs
      FROM IPL.MATCH m
      LEFT OUTER JOIN IPL.BALL_BY_BALL b
        ON b.match_id = m.match_id
      LEFT OUTER JOIN IPL.BATSMAN_SCORED bs
        ON bs.match_id = b.match_id
       AND bs.over_id = b.over_id
       AND bs.ball_id = b.ball_id
       AND bs.innings_no = b.innings_no
      LEFT OUTER JOIN IPL.EXTRA_RUNS er
        ON er.match_id = b.match_id
       AND er.over_id = b.over_id
       AND er.ball_id = b.ball_id
       AND er.innings_no = b.innings_no
     WHERE m.match_id = p_match_id;

    DBMS_OUTPUT.PUT_LINE('Match review for ' || lv_team_1_name || ' vs ' || lv_team_2_name);
    DBMS_OUTPUT.PUT_LINE('Total runs: ' || lv_total_runs || ' compared with threshold ' || lv_threshold);

    IF lv_total_runs >= lv_threshold THEN
      DBMS_OUTPUT.PUT_LINE('Review result: HIGH SCORING');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Review result: NORMAL SCORING');
    END IF;

    FOR rec IN (
      SELECT limited_scores.player_name,
             limited_scores.runs_scored
        FROM (
              SELECT p.player_name,
                     SUM(bs.runs_scored) AS runs_scored
                FROM IPL.BALL_BY_BALL b
                INNER JOIN IPL.BATSMAN_SCORED bs
                  ON bs.match_id = b.match_id
                 AND bs.over_id = b.over_id
                 AND bs.ball_id = b.ball_id
                 AND bs.innings_no = b.innings_no
                INNER JOIN IPL.PLAYER p
                  ON p.player_id = b.striker
               WHERE b.match_id = p_match_id
               GROUP BY p.player_name
               ORDER BY runs_scored DESC, p.player_name
             ) limited_scores
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE('Top scorer: ' || rec.player_name || ' - ' || rec.runs_scored || ' runs');
    END LOOP;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No batting score rows found for this match.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No match found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END review_match;
END ipl_score_review;
/

question:
Build a quick CPI-U exploration script that lists up to 15 monthly CPI-U observations for a given area and item within a year range. The report should be ordered newest-to-oldest and show the CPI date and value. Make sure it behaves safely when the filters return no rows or if the inputs are invalid.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('CPI-U sample rows (max ' || co_report_limit || '):');
DBMS_OUTPUT.PUT_LINE('AREA=' || lv_area_name || ' | ITEM=' || lv_item_name || ' | YEARS ' || lv_start_year || '-' || lv_end_year);
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' | ' || rec.period || ' | ' || rec.value);
DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid year input.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_area_name   BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name   BLS.CPI_U.item_name%TYPE := 'All items';
  lv_start_year  BLS.CPI_U.year%TYPE := '2019';
  lv_end_year    BLS.CPI_U.year%TYPE := '2020';

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation (years are stored as VARCHAR2)
  IF TO_NUMBER(lv_start_year) > TO_NUMBER(lv_end_year) THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year input.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI-U sample rows (max ' || co_report_limit || '):');
  DBMS_OUTPUT.PUT_LINE('AREA=' || lv_area_name || ' | ITEM=' || lv_item_name || ' | YEARS ' || lv_start_year || '-' || lv_end_year);

  FOR rec IN (
    SELECT c.c_date,
           c.period,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND TO_NUMBER(c.year) BETWEEN TO_NUMBER(lv_start_year) AND TO_NUMBER(lv_end_year)
     ORDER BY c.c_date DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' | ' || rec.period || ' | ' || rec.value);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

