  ) RETURN VARCHAR2;
END cpi_u_trend_pkg;
/

CREATE OR REPLACE PACKAGE BODY cpi_u_trend_pkg IS
  PROCEDURE print_yoy_trend(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE,
    p_year      IN BLS.CPI_U.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    IF TO_NUMBER(p_year) < 0 THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year input.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('CPI-U YoY trend (max ' || co_report_limit || '):');
    DBMS_OUTPUT.PUT_LINE('AREA=' || p_area_name || ' | ITEM=' || p_item_name || ' | YEAR=' || p_year);

    FOR rec IN (
      WITH base AS (
        SELECT c.period,
               TO_NUMBER(c.year) AS yr,
               TO_NUMBER(c.value) AS val
          FROM BLS.CPI_U c
         WHERE c.area_name = p_area_name
           AND c.item_name = p_item_name
           AND c.period LIKE 'M%'
           AND TO_NUMBER(c.year) IN (TO_NUMBER(p_year) - 1, TO_NUMBER(p_year))
      ),
      calc AS (
        SELECT b.period,
               b.yr,
               b.val AS curr_value,
               LAG(b.val) OVER (PARTITION BY b.period ORDER BY b.yr) AS prior_value
          FROM base b
      )
      SELECT c.period,
             TO_CHAR(c.curr_value) AS curr_value,
             TO_CHAR(c.prior_value) AS prior_value,
             CASE
               WHEN c.yr = TO_NUMBER(p_year) AND c.prior_value IS NOT NULL AND c.prior_value <> 0 THEN
                 TO_CHAR(ROUND((c.curr_value - c.prior_value) / c.prior_value * 100, 2))
               WHEN c.yr = TO_NUMBER(p_year) THEN
                 'N/A'
               ELSE
                 NULL
             END AS yoy_pct
        FROM calc c
       WHERE c.yr = TO_NUMBER(p_year)
       ORDER BY c.period
    ) LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;

      DBMS_OUTPUT.PUT_LINE(rec.period || ' | value=' || rec.curr_value || ' | prior=' || rec.prior_value || ' | yoy_pct=' || rec.yoy_pct);
      lv_rows_printed := lv_rows_printed + 1;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year input.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_yoy_trend;

  FUNCTION classify_yoy(
    p_area_name           IN BLS.CPI_U.area_name%TYPE,
    p_item_name           IN BLS.CPI_U.item_name%TYPE,
    p_year                IN BLS.CPI_U.year%TYPE,
    p_flat_threshold_pct  IN NUMBER
  ) RETURN VARCHAR2 IS
    lv_curr_avg NUMBER;
    lv_prev_avg NUMBER;
    lv_pct_change NUMBER;
  BEGIN
    IF p_flat_threshold_pct IS NULL OR p_flat_threshold_pct < 0 THEN
      RETURN 'INSUFFICIENT_DATA';
    END IF;

    -- Average CPI-U values for current year and previous year.
    SELECT AVG(TO_NUMBER(c.value))
      INTO lv_curr_avg
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.period LIKE 'M%'
       AND TO_NUMBER(c.year) = TO_NUMBER(p_year);

    SELECT AVG(TO_NUMBER(c.value))
      INTO lv_prev_avg
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.period LIKE 'M%'
       AND TO_NUMBER(c.year) = TO_NUMBER(p_year) - 1;

    IF lv_curr_avg IS NULL OR lv_prev_avg IS NULL THEN
      RETURN 'INSUFFICIENT_DATA';
    END IF;

    -- Intentionally compute percentage change; if baseline is zero, handle with ZERO_DIVIDE.
    lv_pct_change := (lv_curr_avg - lv_prev_avg) / lv_prev_avg * 100;

    IF ABS(lv_pct_change) <= p_flat_threshold_pct THEN
      RETURN 'FLAT';
    ELSIF lv_pct_change > p_flat_threshold_pct THEN
      RETURN 'RISING';
    ELSE
      RETURN 'FALLING';
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 'INSUFFICIENT_DATA';
    WHEN TOO_MANY_ROWS THEN
      RETURN 'INSUFFICIENT_DATA';
    WHEN VALUE_ERROR THEN
      RETURN 'INSUFFICIENT_DATA';
    WHEN ZERO_DIVIDE THEN
      RETURN 'INSUFFICIENT_DATA';
    WHEN OTHERS THEN
      RETURN 'INSUFFICIENT_DATA';
  END classify_yoy;
END cpi_u_trend_pkg;
/

DECLARE
  lv_area_name  BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name  BLS.CPI_U.item_name%TYPE := 'All items';
  lv_year       BLS.CPI_U.year%TYPE := '2020';
  lv_label      VARCHAR2(30);
BEGIN
  cpi_u_trend_pkg.print_yoy_trend(
    p_area_name => lv_area_name,
