    p_year      => lv_year
  );

  lv_label := cpi_u_trend_pkg.classify_yoy(
    p_area_name          => lv_area_name,
    p_item_name          => lv_item_name,
    p_year               => lv_year,
    p_flat_threshold_pct => 0.25
  );

  DBMS_OUTPUT.PUT_LINE('YoY classification=' || lv_label);

EXCEPTION
