question:
Operations wants a quick, readable report of the next scheduled departures from a given airport code. Print up to 15 upcoming flights (by scheduled departure time), including flight number, arrival airport, status, aircraft code, and formatted scheduled times. If the airport code is missing or unknown, print a clear message instead of failing.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Upcoming departures from ' || lv_departure_airport || ' (max rows = ' || co_report_limit || ')');
DBMS_OUTPUT.PUT_LINE('Flight ' || rec.flight_no || ' to ' || rec.arrival_airport || ' | status=' || rec.status || ' | aircraft=' || rec.aircraft_code || ' | dep=' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') || ' | arr=' || TO_CHAR(rec.scheduled_arrival, 'YYYY-MM-DD HH24:MI'));
DBMS_OUTPUT.PUT_LINE('No matching upcoming flights found.');
DBMS_OUTPUT.PUT_LINE('Departure airport code is required.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No matching upcoming flights found.'
WHEN VALUE_ERROR THEN: 'Invalid input value.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_departure_airport AIRLINES.FLIGHTS.departure_airport%TYPE := 'SVO';
  lv_rows_printed      PLS_INTEGER := 0;
BEGIN
  IF lv_departure_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Departure airport code is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Upcoming departures from ' || lv_departure_airport || ' (max rows = ' || co_report_limit || ')');

  FOR rec IN (
    SELECT f.flight_no,
           f.arrival_airport,
           f.status,
           f.aircraft_code,
           f.scheduled_departure,
           f.scheduled_arrival
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = lv_departure_airport
       AND f.scheduled_departure >= SYSTIMESTAMP
     ORDER BY f.scheduled_departure
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
