      ' | arr=' || TO_CHAR(rec.scheduled_arrival, 'YYYY-MM-DD HH24:MI')
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matching upcoming flights found.');
    -- Also raise NO_DATA_FOUND to exercise the handler pattern safely
    RAISE NO_DATA_FOUND;
  END IF;

