question:
Using the same concept as the departures report, build a small housekeeping script that checks whether a given flight is overbooked. For a supplied flight_id, compare how many boarding passes exist versus how many seats exist for that flight’s aircraft. Print the capacity check and clearly label whether the flight is overbooked. Make sure missing flight_id, unknown flight_id, and any unexpected conditions are handled cleanly.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Overbooking check for flight_id=' || lv_flight_id || ' (max rows = ' || co_report_limit || ')');
DBMS_OUTPUT.PUT_LINE('Aircraft=' || lv_aircraft_code || ' | seats=' || lv_seat_cnt || ' | boarding_passes=' || lv_bp_cnt);
DBMS_OUTPUT.PUT_LINE('Status: OVERBOOKED');
DBMS_OUTPUT.PUT_LINE('Status: OK');
DBMS_OUTPUT.PUT_LINE('Flight id is required.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Keep output aligned with earlier reporting pattern

  lv_flight_id      AIRLINES.FLIGHTS.flight_id%TYPE := 1;
  lv_aircraft_code  AIRLINES.FLIGHTS.aircraft_code%TYPE;
  lv_seat_cnt       NUMBER := 0;
  lv_bp_cnt         NUMBER := 0;
BEGIN
  IF lv_flight_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Flight id is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Overbooking check for flight_id=' || lv_flight_id || ' (max rows = ' || co_report_limit || ')');

  SELECT f.aircraft_code
    INTO lv_aircraft_code
    FROM AIRLINES.FLIGHTS f
   WHERE f.flight_id = lv_flight_id;

  SELECT COUNT(*)
    INTO lv_seat_cnt
    FROM AIRLINES.SEATS s
   WHERE s.aircraft_code = lv_aircraft_code;

  SELECT COUNT(*)
    INTO lv_bp_cnt
    FROM AIRLINES.BOARDING_PASSES bp
   WHERE bp.flight_id = lv_flight_id;

  DBMS_OUTPUT.PUT_LINE('Aircraft=' || lv_aircraft_code || ' | seats=' || lv_seat_cnt || ' | boarding_passes=' || lv_bp_cnt);

  IF lv_bp_cnt > lv_seat_cnt THEN
    DBMS_OUTPUT.PUT_LINE('Status: OVERBOOKED');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Status: OK');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

